/* ── Thing (core, con union hub/leaf expandido a 32 slots) ── */
typedef struct Thing Thing;

struct Thing {
    V3       pos, vel, prev;
    float    radius, hp, maxhp, mass, life, rot, spin;
    uint32_t id, type, flags, parent, version, side_idx;
    uint16_t num_children, num_mat_refs;
    uint32_t children_ext;
    uint32_t seed;
    union {
        struct {
            uint32_t children[8];
            uint32_t mat_refs[8];
            uint32_t reserved[16];
        } hub;
        struct { float f[32]; } leaf;
    } u;
};



