/* Cockpit tactile panel — sole instrument UI for pilot (maps/refs).
   World crosshair / orientators stay outside. PageUp/Down slides panel. */
enum {
    CPD_PAGE_MAP = 0,   /* radar + contacts */
    CPD_PAGE_SYS,       /* ship vitals / fuel / heat */
    CPD_PAGE_TGT,       /* scan targets / locks */
    CPD_PAGE_NAV,       /* zone / heading / dock refs */
    CPD_PAGE_COUNT
};
enum {
    CPD_POS_BOTTOM = 0,
    CPD_POS_TOP    = 1
};
typedef struct {
    int   visible;
    float y_offset;          /* 0 = bottom, 1 = top */
    float target_y;
    float width_px;
    float height_px;
    float alpha;
    float scan_phase;
    float crosshair_x;       /* secondary aim within panel -1..1 */
    float crosshair_y;
    float refresh_timer;
    int   page;              /* CPD_PAGE_* */
    int   pos_preset;        /* bottom / top snap */
    int   touch_focus;       /* 1 while pointer over panel */
    int   sole_control;      /* 1 = hide redundant HUD maps when piloting */
    int   snap_pending;
    float tab_flash;
} CockpitDisplay;

