static void mat_gen(uint32_t seed, Material* m, PropiedadesMaterial* p) {
    memset(m, 0, sizeof(*m));
    memset(p, 0, sizeof(*p));
    m->runtime_seed = seed;
    uint32_t h = hash_u32(seed ^ 0xCAFEu);
    uint32_t tags = (h & 0x1FFu) ? (h & 0x1FFu) : MAT_TAG_CONDUCTIVE;
    m->tag_mask = tags;
    uint32_t h_weight = hash3_u32(seed, 0x02u, 0xBEEFu);
    uint32_t h_rarity = hash3_u32(seed, 0x03u, 0xF00Du);
    uint32_t h_react  = hash3_u32(seed, 0x05u, 0xBABEu);
    float weight = 0.5f + ((h_weight & 0xFFu) / 255.f) * 5.0f;
    if (tags & MAT_TAG_RARE)        weight *= 1.5f;
    if (tags & MAT_TAG_RADIOACTIVE) weight *= 2.0f;
    if (tags & MAT_TAG_VOLATILE)    weight *= 0.1f;
    m->weight = weight;
    float rarity = ((h_rarity & 0xFFu) / 255.f) * 0.8f;
    if (tags & MAT_TAG_RARE)     rarity = fmaxf(rarity, 0.65f);
    if (tags & MAT_TAG_VOLATILE) rarity = fmaxf(rarity, 0.75f);
    m->rarity = rarity;
    m->price_base = 5.f + rarity * 800.f + weight * 15.f;
    if (tags & MAT_TAG_RARE) m->price_base *= 1.3f;
    m->reactivity = ((h_react & 0xFFu) / 255.f) * 0.9f;
    if (tags & MAT_TAG_VOLATILE) m->reactivity = fmaxf(m->reactivity, 0.7f);
    for (int r = 0; r < 4; r++) { m->refine[r].out_id = 0xFFFF; m->refine[r].qty = 0; }
    uint32_t h_price = hash3_u32(seed, 0x04u, 0xDEADu);
    if ((h >> 16) & 1u) {
        m->refine[0].out_id = (uint16_t)((h_price >> 8) % MATERIAL_COUNT);
        m->refine[0].qty    = (uint16_t)(1 + (h_price & 3u));
    }
    int is_radio    = (tags & MAT_TAG_RADIOACTIVE) ? 1 : 0;
    int is_volatile = (tags & MAT_TAG_VOLATILE)    ? 1 : 0;
    p->densidad      = 0.4f + rarity * 0.6f + (is_radio ? 0.5f : 0.f);
    p->viscosidad    = 0.5f;
    p->emision       = 0.f;
    if (is_radio)    p->emision += 0.5f;
    if (is_volatile) p->emision += 0.3f;
    p->magnetismo    = (tags & MAT_TAG_MAGNETIC)    ? 1.f : 0.f;
    p->radiactividad = is_radio ? 1.f : 0.f;
    p->corrosividad  = (tags & MAT_TAG_TOXIC)       ? 1.f : 0.f;
    p->temperatura   = 0.5f;
    uint32_t h_color = hash3_u32(seed, 0x06u, 0xFACEu);
    int palette = 0;
    if      (tags & MAT_TAG_VOLATILE)    palette = 1;
    else if (tags & MAT_TAG_RADIOACTIVE) palette = 3;
    else if (tags & MAT_TAG_ORGANIC)     palette = 5;
    else if (tags & MAT_TAG_CRYSTALLINE) palette = 2;
    else if (tags & MAT_TAG_RARE)        palette = 3;
    else if (tags & MAT_TAG_INSULATING)  palette = 4;
    m->color = color_gen(h_color, palette);
}

static int mat_pool_find(uint32_t seed) {
    if (seed == 0) return -1;
    if (seed >= 0x10000u && seed < 0x10000u + MATERIAL_COUNT)
        return (int)(seed - 0x10000u);
    for (uint32_t i = MATERIAL_COUNT; i < g_matpool.count; i++)
        if (g_matpool.seeds[i] == seed) return (int)i;
    return -1;
}

static void materials_init(void) {
    if (g_matpool_initialized) return;
    memset(&g_matpool, 0, sizeof(g_matpool));
    memset(g_params, 0, sizeof(g_params));

    for (int i = 0; i < MATERIAL_COUNT; i++) {
        Material* m = &g_matpool.cache[i];
        m->name       = g_base_materials[i].name;
        m->color      = v4(g_base_materials[i].r,
                           g_base_materials[i].g,
                           g_base_materials[i].b, 1.f);
        m->rarity     = g_base_materials[i].rarity;
        m->weight     = g_base_materials[i].weight;
        m->price_base = g_base_materials[i].price;
        m->tag_mask   = g_base_materials[i].tags;
        m->reactivity = g_base_materials[i].rarity * 0.5f;
        m->runtime_seed = 0x10000u + (uint32_t)i;
        for (int r = 0; r < 4; r++) { m->refine[r].out_id = 0xFFFF; m->refine[r].qty = 0; }
        g_matpool.seeds[i] = 0x10000u + (uint32_t)i;

        PropiedadesMaterial* p = &g_matpool.props[i];
        p->densidad      = 0.4f + m->rarity * 0.5f;
        p->viscosidad    = 0.5f;
        p->emision       = 0.f;
        if (m->tag_mask & MAT_TAG_RADIOACTIVE) p->emision += 0.5f;
        if (m->tag_mask & MAT_TAG_VOLATILE)    p->emision += 0.3f;
        p->magnetismo    = (m->tag_mask & MAT_TAG_MAGNETIC)    ? 1.f : 0.f;
        p->radiactividad = (m->tag_mask & MAT_TAG_RADIOACTIVE) ? 1.f : 0.f;
        p->corrosividad  = (m->tag_mask & MAT_TAG_TOXIC)       ? 1.f : 0.f;
        p->temperatura   = 0.5f;

        uint16_t insul = 0;
        if (m->tag_mask & MAT_TAG_INSULATING)  insul |= (uint16_t)(1u << AFF_BURN);
        if (m->tag_mask & MAT_TAG_RADIOACTIVE) insul |= (uint16_t)(1u << AFF_RADIATION);
        if (m->tag_mask & MAT_TAG_TOXIC)
            insul |= (uint16_t)((1u << AFF_POISON) | (1u << AFF_CORROSION));
        g_mat_insulation_mask[i] = insul;

        for (int proc = 0; proc < PROC_TOTAL; proc++)
            for (int est = 0; est < EST_TOTAL; est++) {
                ParametrosPatron* pp = &g_params[i][proc][est];
                pp->frecuencia1 = 2 + (i % 5);
                pp->frecuencia2 = 5 + (i % 8);
                pp->amplitud    = 0.30f + (i % 10) * 0.05f;
                pp->distorsion  = i % 4;
                pp->densidad_visual = 1.f;
                pp->emision = p->emision;
                pp->variacion = 0;
            }
    }
    g_matpool.count = MATERIAL_COUNT;
    g_matpool_initialized = 1;
    LOG("materials_init: %d canonicals", MATERIAL_COUNT);
}

static uint16_t mat_pool_get(uint32_t seed) {
    if (seed == 0) return 0;
    int existing = mat_pool_find(seed);
    if (existing >= 0) return (uint16_t)existing;
    if (g_matpool.count >= MATERIAL_TOTAL_MAX) {
        notice_push("MATERIAL POOL FULL");
        return 0;
    }
    uint32_t idx = g_matpool.count++;
    mat_gen(seed, &g_matpool.cache[idx], &g_matpool.props[idx]);
    snprintf(g_mat_name_storage[idx], 32, "Mat-%05X", seed & 0xFFFFF);
    g_matpool.cache[idx].name = (const char*)g_mat_name_storage[idx];
    uint32_t tags = g_matpool.cache[idx].tag_mask;
    uint16_t insul = 0;
    if (tags & MAT_TAG_INSULATING)  insul |= (uint16_t)(1u << AFF_BURN);
    if (tags & MAT_TAG_RADIOACTIVE) insul |= (uint16_t)(1u << AFF_RADIATION);
    if (tags & MAT_TAG_TOXIC)
        insul |= (uint16_t)((1u << AFF_POISON) | (1u << AFF_CORROSION));
    g_mat_insulation_mask[idx] = insul;
    g_matpool.seeds[idx] = seed;
    if (idx < MATERIAL_COUNT) {
        for (int proc = 0; proc < PROC_TOTAL; proc++)
            for (int est = 0; est < EST_TOTAL; est++) {
                ParametrosPatron* pp = &g_params[idx][proc][est];
                pp->frecuencia1 = 2 + (idx % 5);
                pp->frecuencia2 = 5 + (idx % 8);
                pp->amplitud    = 0.30f + (idx % 10) * 0.05f;
                pp->distorsion  = idx % 4;
                pp->densidad_visual = 1.f;
                pp->emision = g_matpool.props[idx].emision;
            }
    }
    return (uint16_t)idx;
}

static void mat_gen_for_zone(uint32_t zone_seed, int cx, int cy, int cz) {
    if (zone_seed == 0) return;
    uint32_t h = hash3_u32(zone_seed, (uint32_t)(cx + 10000), (uint32_t)(cy + 10000));
    h = hash_combine(h, (uint32_t)(cz + 10000));
    if (h == 0) h = 1;
    int count = 3 + (int)(h % 6u);
    for (int i = 0; i < count; i++) {
        uint32_t s = hash3_u32(h, (uint32_t)i, 0xBEEFu);
        if (s == 0) s = 1;
        if (s >= 0x10000u && s < 0x10000u + MATERIAL_COUNT)
            s += MATERIAL_COUNT;
        mat_pool_get(s);
    }
}

static Material* mat_get(uint16_t idx) {
    if (idx >= g_matpool.count) return &g_matpool.cache[0];
    return &g_matpool.cache[idx];
}

static PropiedadesMaterial* mat_props_get(uint16_t idx) {
    if (idx >= g_matpool.count) return &g_matpool.props[0];
    return &g_matpool.props[idx];
}

static void mat_color(uint16_t idx, V4* out) {
    if (!out) return;
    *out = mat_get(idx)->color;
}

static float mat_similarity(uint16_t a, uint16_t b) {
    if (a == b) return 1.f;
    if (a >= g_matpool.count || b >= g_matpool.count) return 0.f;
    const Material* ma = &g_matpool.cache[a];
    const Material* mb = &g_matpool.cache[b];
    uint32_t common = ma->tag_mask & mb->tag_mask;
    uint32_t uni    = ma->tag_mask | mb->tag_mask;
    float tags_j = uni ? ((float)popcount32(common) / (float)popcount32(uni)) : 0.f;
    float wa = ma->weight, wb = mb->weight;
    float wr = (wa > 0.f && wb > 0.f) ? fminf(wa, wb) / fmaxf(wa, wb) : 0.f;
    float ins = (g_mat_insulation_mask[a] == g_mat_insulation_mask[b]) ? 1.f : 0.f;
    return clampf(0.5f * tags_j + 0.3f * wr + 0.2f * ins, 0.f, 1.f);
}

 static float mat_similarity_checked(int a, int b) {
     if (a < 0 || b < 0) return 0.f;
     if (a >= (int)g_matpool.count || b >= (int)g_matpool.count) return 0.f;
     return mat_similarity((uint16_t)a, (uint16_t)b);
 }

static void mat_derive_phys(uint16_t mat_id, float volume,
                             float* out_mass, float* out_hp,
                             uint8_t* out_resist, uint16_t* out_insul) {
    if (mat_id >= g_matpool.count) {
        if (out_mass)   *out_mass   = volume * 0.5f;
        if (out_hp)     *out_hp     = volume * 10.f;
        if (out_resist) memset(out_resist, 0, 5);
        if (out_insul)  *out_insul  = 0;
        return;
    }
    const Material* m = &g_matpool.cache[mat_id];
    const PropiedadesMaterial* p = &g_matpool.props[mat_id];
    if (out_mass) *out_mass = volume * p->densidad * MAT_MASS_COEF;
    if (out_hp)   *out_hp   = volume * m->weight * MAT_HP_COEF;
    if (out_resist) {
        for (int i = 0; i < 5; i++) out_resist[i] = 0;
        if (m->tag_mask & MAT_TAG_CONDUCTIVE)  out_resist[DMG_ENERGY] = 15;
        if (m->tag_mask & MAT_TAG_INSULATING)  out_resist[DMG_HEAT]   = 25;
        if (m->tag_mask & MAT_TAG_RARE)        out_resist[DMG_EXOTIC] = 20;
        if (m->tag_mask & MAT_TAG_CRYSTALLINE) out_resist[DMG_PHYS]   = 15;
        if (m->tag_mask & MAT_TAG_TOXIC)       out_resist[DMG_CHEM]   = 10;
    }
    if (out_insul) *out_insul = g_mat_insulation_mask[mat_id];
}

static inline uint16_t mat_insulation(uint16_t mat_id) {
    return (mat_id < g_matpool.count) ? g_mat_insulation_mask[mat_id] : 0;
}


static void mat_name_uuid(int id, unsigned long long out[3]) {
    if (!out) return;
    out[0] = ((unsigned long long)hash_u32((uint32_t)id ^ 0xAAu) << 32) | hash_u32((uint32_t)id ^ 0xBBu);
    out[1] = ((unsigned long long)hash_u32((uint32_t)id ^ 0xCCu) << 32) | hash_u32((uint32_t)id ^ 0xDDu);
    out[2] = ((unsigned long long)hash_u32((uint32_t)id ^ 0xEEu) << 32) | hash_u32((uint32_t)id ^ 0xFFu);
}

static void format_mat_name(int id, char* out, int len) {
    if (!out || len < 1) return;
    if (id >= 0 && id < (int)g_matpool.count)
        snprintf(out, len, "%s", g_matpool.cache[id].name ? g_matpool.cache[id].name : "?");
    else
        snprintf(out, len, "Mat#%d", id);
}

static void jitter_props(int mat_id, float factor) {
    if (factor <= 0.f) return;
    if (mat_id < 0 || mat_id >= (int)g_matpool.count) return;
    for (int p = 0; p < 4; p++) {
        Material* m = &g_matpool.cache[mat_id];
        float base = p == 0 ? m->rarity * 100.f
                   : p == 1 ? m->weight * 10.f
                   : p == 2 ? m->price_base * 0.1f
                   : m->reactivity * 100.f;
        base += (xrng_f() * 2.f - 1.f) * factor * base * 0.5f;
        if (base < 0.f) base = 0.f;
        if (p == 0) m->rarity     = clampf(base / 100.f, 0.f, 1.f);
        if (p == 1) m->weight     = clampf(base / 10.f, 0.1f, 30.f);
        if (p == 2) m->price_base = clampf(base * 10.f, 1.f, 999999.f);
        if (p == 3) m->reactivity = clampf(base / 100.f, 0.f, 1.f);
    }
}

static int inv_find(const Inventory* inv, uint32_t seed) {
    if (!inv) return -1;
    for (int i = 0; i < inv->count; i++)
        if (inv->items[i].bp.seed == seed) return i;
    return -1;
}

static int inv_add(Inventory* inv, const ThingBlueprint* bp, uint16_t qty) {
    if (!inv || !bp) return 0;
    int existing = inv_find(inv, bp->seed);
    if (existing >= 0) {
        inv->items[existing].qty += qty;
        return 1;
    }
    if (inv->count >= INVENTORY_MAX) return 0;
    InventoryItem* it = &inv->items[inv->count++];
    memset(it, 0, sizeof(*it));
    it->bp = *bp;
    it->qty = qty;
    if (bp->blocks && bp->block_count > 0) {
        BodyBlock* copy = (BodyBlock*)xmalloc(bp->block_count * sizeof(BodyBlock));
        if (copy) {
            memcpy(copy, bp->blocks, bp->block_count * sizeof(BodyBlock));
            it->bp.blocks = copy;
        } else {
            it->bp.blocks = NULL;
            it->bp.block_count = 0;
        }
    }
    return 1;
}

static int inv_remove(Inventory* inv, uint32_t seed, uint16_t qty) {
    if (!inv) return 0;
    int idx = inv_find(inv, seed);
    if (idx < 0) return 0;
    if (inv->items[idx].qty < qty) return 0;
    inv->items[idx].qty -= qty;
    if (inv->items[idx].qty == 0) {
        if (inv->items[idx].bp.blocks) xfree(inv->items[idx].bp.blocks);
        inv->items[idx] = inv->items[inv->count - 1];
        inv->count--;
        memset(&inv->items[inv->count], 0, sizeof(InventoryItem));
    }
    return 1;
}

static void inv_clear(Inventory* inv) {
    if (!inv) return;
    for (int i = 0; i < inv->count; i++)
        if (inv->items[i].bp.blocks) xfree(inv->items[i].bp.blocks);
    inv->count = 0;
}

static void body_block_push(BodyBlock** buf, int* count, int* cap,
                             V3 pos, V3 scale, V4 color, int mesh) {
    if (*count >= BODY_MORPH_BLOCKS_MAX) return;
    if (*count >= *cap) {
        int nc = (*cap == 0) ? 16 : (*cap * 2 + 2);
        if (nc > BODY_MORPH_BLOCKS_MAX) nc = BODY_MORPH_BLOCKS_MAX;
        BodyBlock* nb = (BodyBlock*)xrealloc(*buf, nc * sizeof(BodyBlock));
        if (!nb) return;
        *buf = nb;
        *cap = nc;
    }
    BodyBlock* b = &(*buf)[(*count)++];
    b->pos_local = pos;
    b->scale = scale;
    b->color = color;
    b->mesh = (uint8_t)mesh;
    b->_pad[0] = b->_pad[1] = b->_pad[2] = 0;
}

static void body_build_head(BodyBlock** buf, int* n, int* cap,
                             SpeciesKind sp, float s, V4 c,
                             const BodyMorphology* morph) {
    float len_mul   = morph ? morph->limb_length_mul    : 1.f;
    float thick_mul = morph ? morph->limb_thickness_mul : 1.f;
    float head_mul  = morph ? morph->head_scale_mul     : 1.f;
    #define Y(v)  ((v) * s * len_mul)
    #define TX(v) ((v) * s * thick_mul * head_mul)
    #define TY(v) ((v) * s * len_mul   * head_mul)
    #define TZ(v) ((v) * s * thick_mul * head_mul)
    V4 eye   = v4(0.95f, 0.95f, 0.95f, 1);
    V4 pupil = v4(0.05f, 0.05f, 0.08f, 1);
    switch (sp) {
        case SPECIES_HUMANOID:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.18f), TY(0.22f), TZ(0.24f)), c, 0);
            body_block_push(buf, n, cap, v3(0, Y(1.40f), 0),
                v3(TX(0.10f), TY(0.10f), TZ(0.10f)), c, 0);
            body_block_push(buf, n, cap, v3(-0.05f, Y(1.58f), 0.10f),
                v3(TX(0.04f), TY(0.02f), TZ(0.04f)), eye, 1);
            body_block_push(buf, n, cap, v3( 0.05f, Y(1.58f), 0.10f),
                v3(TX(0.04f), TY(0.02f), TZ(0.04f)), eye, 1);
            break;
        case SPECIES_ALIEN:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.28f), TY(0.28f), TZ(0.28f)), c, 1);
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0.15f),
                v3(TX(0.08f), TY(0.08f), TZ(0.08f)), eye, 1);
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0.20f),
                v3(TX(0.03f), TY(0.03f), TZ(0.03f)), pupil, 1);
            body_block_push(buf, n, cap, v3(-0.10f, Y(1.60f), 0.12f),
                v3(TX(0.04f), TY(0.04f), TZ(0.04f)), eye, 1);
            body_block_push(buf, n, cap, v3( 0.10f, Y(1.60f), 0.12f),
                v3(TX(0.04f), TY(0.04f), TZ(0.04f)), eye, 1);
            break;
        case SPECIES_ROBOT:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.22f), TY(0.22f), TZ(0.20f)), c, 0);
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0.11f),
                v3(TX(0.08f), TY(0.04f), TZ(0.02f)),
                v4(1, 0.2f, 0.2f, 1), 0);
            body_block_push(buf, n, cap, v3(0, Y(1.70f), 0),
                v3(TX(0.02f), TY(0.08f), TZ(0.02f)),
                v4(c.x*0.6f, c.y*0.6f, c.z*0.6f, 1), 0);
            body_block_push(buf, n, cap, v3(0, Y(1.80f), 0),
                v3(TX(0.03f), TY(0.03f), TZ(0.03f)),
                v4(0.2f, 1, 0.2f, 1), 1);
            break;
        case SPECIES_PLANT:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.20f), TY(0.20f), TZ(0.20f)),
                v4(1, 0.4f, 0.7f, 1), 1);
            body_block_push(buf, n, cap, v3(0, Y(1.60f), 0),
                v3(TX(0.08f), TY(0.06f), TZ(0.08f)),
                v4(1, 0.9f, 0.2f, 1), 1);
            break;
        case SPECIES_INSECTOID:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.16f), TY(0.14f), TZ(0.16f)), c, 1);
            body_block_push(buf, n, cap, v3(-0.05f, Y(1.56f), 0.06f),
                v3(TX(0.04f), TY(0.04f), TZ(0.04f)), eye, 1);
            body_block_push(buf, n, cap, v3( 0.05f, Y(1.56f), 0.06f),
                v3(TX(0.04f), TY(0.04f), TZ(0.04f)), eye, 1);
            body_block_push(buf, n, cap, v3(-0.04f, Y(1.62f), 0.04f),
                v3(TX(0.01f), TY(0.10f), TZ(0.01f)), c, 0);
            body_block_push(buf, n, cap, v3( 0.04f, Y(1.62f), 0.04f),
                v3(TX(0.01f), TY(0.10f), TZ(0.01f)), c, 0);
            break;
        case SPECIES_CRUSTACEAN:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.20f), TY(0.16f), TZ(0.18f)), c, 0);
            body_block_push(buf, n, cap, v3(-0.08f, Y(1.55f), 0.10f),
                v3(TX(0.02f), TY(0.08f), TZ(0.02f)), c, 0);
            body_block_push(buf, n, cap, v3(-0.08f, Y(1.65f), 0.10f),
                v3(TX(0.03f), TY(0.03f), TZ(0.03f)), eye, 1);
            body_block_push(buf, n, cap, v3( 0.08f, Y(1.55f), 0.10f),
                v3(TX(0.02f), TY(0.08f), TZ(0.02f)), c, 0);
            body_block_push(buf, n, cap, v3( 0.08f, Y(1.65f), 0.10f),
                v3(TX(0.03f), TY(0.03f), TZ(0.03f)), eye, 1);
            break;
        default:
            body_block_push(buf, n, cap, v3(0, Y(1.55f), 0),
                v3(TX(0.25f), TY(0.25f), TZ(0.25f)), c, 1);
            body_block_push(buf, n, cap, v3(-0.15f, Y(1.60f), 0),
                v3(TX(0.12f), TY(0.12f), TZ(0.12f)), c, 1);
            body_block_push(buf, n, cap, v3( 0.15f, Y(1.60f), 0),
                v3(TX(0.12f), TY(0.12f), TZ(0.12f)), c, 1);
            break;
    }
    #undef Y
    #undef TX
    #undef TY
    #undef TZ
}

static void body_build_torso(BodyBlock** buf, int* n, int* cap,
                              SpeciesKind sp, float s, V4 c,
                              const BodyMorphology* morph) {
    float len_mul   = morph ? morph->limb_length_mul    : 1.f;
    float thick_mul = morph ? morph->limb_thickness_mul : 1.f;
    float torso_mul = morph ? morph->torso_width_mul    : 1.f;
    float shoulder  = morph ? morph->shoulder_width_mul : 1.f;
    #define Y(v)  ((v) * s * len_mul)
    #define TX(v) ((v) * s * thick_mul * torso_mul)
    #define TY(v) ((v) * s * len_mul)
    #define TZ(v) ((v) * s * thick_mul * torso_mul)
    V4 dark = v4(c.x*0.7f, c.y*0.7f, c.z*0.7f, 1);
    switch (sp) {
        case SPECIES_HUMANOID: {
            float sw = 0.42f * shoulder;
            body_block_push(buf, n, cap, v3(0, Y(1.20f), 0),
                v3(TX(sw), TY(0.24f), TZ(0.30f)), c, 0);
            body_block_push(buf, n, cap, v3(0, Y(0.90f), 0),
                v3(TX(0.36f), TY(0.22f), TZ(0.24f)), c, 0);
            body_block_push(buf, n, cap, v3(0, Y(0.70f), 0),
                v3(TX(0.38f), TY(0.24f), TZ(0.18f)), dark, 0);
            break;
        }
        case SPECIES_ALIEN:
            body_block_push(buf, n, cap, v3(0, Y(1.10f), 0),
                v3(TX(0.55f), TY(0.55f), TZ(0.55f)), c, 1);
            body_block_push(buf, n, cap, v3(0, Y(0.70f), 0),
                v3(TX(0.40f), TY(0.40f), TZ(0.40f)), c, 1);
            break;
        case SPECIES_ROBOT: {
            float w = 0.50f * shoulder;
            body_block_push(buf, n, cap, v3(0, Y(1.15f), 0),
                v3(TX(w), TY(0.60f), TZ(0.34f)), c, 0);
            body_block_push(buf, n, cap, v3(0, Y(1.15f), 0.18f),
                v3(TX(0.14f), TY(0.14f), TZ(0.04f)), dark, 0);
            body_block_push(buf, n, cap, v3(0, Y(0.85f), 0),
                v3(TX(0.42f), TY(0.20f), TZ(0.30f)), dark, 0);
            break;
        }
        case SPECIES_PLANT:
            body_block_push(buf, n, cap, v3(0, Y(0.85f), 0),
                v3(TX(0.12f), TY(1.00f), TZ(0.12f)),
                v4(0.20f*c.x+0.15f, 0.30f*c.y+0.20f, 0.10f, 1), 0);
            break;
        case SPECIES_INSECTOID:
            body_block_push(buf, n, cap, v3(0, Y(1.15f), 0),
                v3(TX(0.30f), TY(0.25f), TZ(0.30f)), c, 1);
            body_block_push(buf, n, cap, v3(0, Y(0.85f), 0.10f),
                v3(TX(0.35f), TY(0.40f), TZ(0.40f)), c, 1);
            break;
        case SPECIES_CRUSTACEAN:
            body_block_push(buf, n, cap, v3(0, Y(0.90f), 0),
                v3(TX(0.65f), TY(0.50f), TZ(0.50f)), c, 0);
            body_block_push(buf, n, cap, v3(0, Y(0.90f), 0.26f),
                v3(TX(0.55f), TY(0.40f), TZ(0.10f)), dark, 0);
            break;
        default:
            body_block_push(buf, n, cap, v3(0, Y(1.00f), 0),
                v3(TX(0.55f), TY(0.65f), TZ(0.55f)), c, 1);
            body_block_push(buf, n, cap, v3(0, Y(0.70f), 0),
                v3(TX(0.45f), TY(0.45f), TZ(0.45f)), c, 1);
            break;
    }
    #undef Y
    #undef TX
    #undef TY
    #undef TZ
}

static void body_build_arm(BodyBlock** buf, int* n, int* cap,
                            SpeciesKind sp, float s, V4 c,
                            int side, int total,
                            const BodyMorphology* morph) {
    float len_mul   = morph ? morph->limb_length_mul    : 1.f;
    float thick_mul = morph ? morph->limb_thickness_mul : 1.f;
    float sh_mul    = morph ? morph->shoulder_width_mul : 1.f;
    float side_sign = (total == 1) ? 1.f : ((side < total / 2) ? -1.f : 1.f);
    float x_pos = (total == 1) ? 0.f
                : (-0.35f + (0.70f * (float)side / (float)(total - 1))) * sh_mul;
    V4 dark = v4(c.x*0.8f, c.y*0.8f, c.z*0.8f, 1);
    #define Y(v)  ((v) * s * len_mul)
    #define TX(v) ((v) * s * thick_mul)
    #define TY(v) ((v) * s * len_mul)
    #define TZ(v) ((v) * s * thick_mul)
    switch (sp) {
        case SPECIES_HUMANOID: {
            body_block_push(buf, n, cap,
                v3(x_pos + side_sign * 0.05f, Y(1.28f), 0),
                v3(TX(0.12f), TY(0.14f), TZ(0.14f)), dark, 0);
            float upper = 0.28f;
            body_block_push(buf, n, cap, v3(x_pos, Y(1.28f - upper), 0),
                v3(TX(0.10f), TY(upper * 1.1f), TZ(0.10f)), c, 0);
            float fore = 0.28f;
            body_block_push(buf, n, cap, v3(x_pos, Y(1.28f - upper - fore * 0.5f), 0),
                v3(TX(0.09f), TY(fore), TZ(0.09f)), c, 0);
            float hs = 0.09f;
            body_block_push(buf, n, cap, v3(x_pos, Y(1.28f - upper - fore), 0),
                v3(TX(hs), TY(hs * 0.7f), TZ(hs * 1.4f)), c, 0);
            break;
        }
        case SPECIES_ALIEN:
            for (int j = 0; j < 3; j++) {
                float dy = 1.10f - (float)j * 0.12f;
                float dx = x_pos + side_sign * (0.05f + (float)j * 0.02f);
                body_block_push(buf, n, cap, v3(dx, Y(dy), 0),
                    v3(TX(0.08f), TY(0.10f), TZ(0.08f)), c, 1);
            }
            break;
        case SPECIES_ROBOT: {
            float upper = 0.28f;
            float fore  = 0.28f;
            body_block_push(buf, n, cap, v3(x_pos, Y(1.22f), 0),
                v3(TX(0.13f), TY(0.15f), TZ(0.13f)), dark, 0);
            body_block_push(buf, n, cap,
                v3(x_pos, Y(1.22f - upper * 0.5f - 0.05f), 0),
                v3(TX(0.10f), TY(upper), TZ(0.10f)), c, 0);
            body_block_push(buf, n, cap, v3(x_pos, Y(1.22f - upper - 0.05f), 0),
                v3(TX(0.12f), TY(0.08f), TZ(0.12f)), dark, 0);
            body_block_push(buf, n, cap,
                v3(x_pos, Y(1.22f - upper - 0.10f - fore * 0.5f), 0),
                v3(TX(0.09f), TY(fore), TZ(0.09f)), c, 0);
            break;
        }
        case SPECIES_PLANT:
            body_block_push(buf, n, cap, v3(x_pos, Y(0.80f), 0),
                v3(TX(0.10f), TY(0.50f), TZ(0.10f)),
                v4(c.x*1.2f, c.y*1.2f, c.z, 1), 0);
            break;
        case SPECIES_INSECTOID:
            for (int j = 0; j < 3; j++) {
                float dy = 1.20f - (float)j * 0.15f;
                body_block_push(buf, n, cap, v3(x_pos, Y(dy), 0),
                    v3(TX(0.06f + j*0.01f), TY(0.10f),
                       TZ(0.06f + j*0.01f)),
                    (j == 0) ? dark : c, 0);
            }
            break;
        case SPECIES_CRUSTACEAN:
            body_block_push(buf, n, cap, v3(x_pos, Y(1.10f), 0),
                v3(TX(0.10f), TY(0.12f), TZ(0.10f)), dark, 0);
            body_block_push(buf, n, cap, v3(x_pos + side_sign*0.10f, Y(0.90f), 0),
                v3(TX(0.15f), TY(0.08f), TZ(0.20f)), c, 1);
            break;
        default:
            for (int j = 0; j < 2; j++) {
                float dy = 1.10f - (float)j * 0.15f;
                body_block_push(buf, n, cap,
                    v3(x_pos + side_sign * 0.08f, Y(dy), 0),
                    v3(TX(0.10f), TY(0.15f), TZ(0.10f)), c, 1);
            }
            break;
    }
    #undef Y
    #undef TX
    #undef TY
    #undef TZ
}

static void body_build_leg(BodyBlock** buf, int* n, int* cap,
                            SpeciesKind sp, float s, V4 c,
                            int side, int total,
                            const BodyMorphology* morph) {
    float len_mul   = morph ? morph->limb_length_mul    : 1.f;
    float thick_mul = morph ? morph->limb_thickness_mul : 1.f;
    float side_sign = (total == 1) ? 1.f : ((side < total / 2) ? -1.f : 1.f);
    float x_pos = (total == 1) ? 0.f
                : (-0.30f + (0.60f * (float)side / (float)(total - 1)));
    V4 dark = v4(c.x*0.6f, c.y*0.6f, c.z*0.6f, 1);
    #define Y(v)  ((v) * s * len_mul)
    #define TX(v) ((v) * s * thick_mul)
    #define TY(v) ((v) * s * len_mul)
    #define TZ(v) ((v) * s * thick_mul)
    switch (sp) {
        case SPECIES_HUMANOID: {
            float thigh = 0.22f, shin = 0.20f;
            body_block_push(buf, n, cap, v3(x_pos, Y(0.42f), 0),
                v3(TX(0.15f), TY(thigh), TZ(0.15f)), c, 0);
            body_block_push(buf, n, cap,
                v3(x_pos, Y(0.42f - thigh * 0.5f - shin * 0.5f), 0),
                v3(TX(0.12f), TY(shin), TZ(0.12f)), c, 0);
            body_block_push(buf, n, cap, v3(x_pos, Y(0.04f), 0.05f),
                v3(TX(0.13f), TY(0.08f), TZ(0.22f)), dark, 0);
            break;
        }
        case SPECIES_ALIEN:
            for (int j = 0; j < 3; j++) {
                float dy = 0.40f - (float)j * 0.12f;
                body_block_push(buf, n, cap, v3(x_pos, Y(dy), 0),
                    v3(TX(0.07f), TY(0.12f), TZ(0.07f)), c, 1);
            }
            body_block_push(buf, n, cap, v3(x_pos, Y(0.02f), 0.04f),
                v3(TX(0.06f), TY(0.04f), TZ(0.10f)), dark, 0);
            break;
        case SPECIES_ROBOT:
            body_block_push(buf, n, cap, v3(x_pos, Y(0.42f), 0),
                v3(TX(0.15f), TY(0.36f), TZ(0.15f)), c, 0);
            body_block_push(buf, n, cap, v3(x_pos, Y(0.20f), 0),
                v3(TX(0.12f), TY(0.22f), TZ(0.12f)), dark, 0);
            body_block_push(buf, n, cap, v3(x_pos, Y(0.04f), 0.05f),
                v3(TX(0.18f), TY(0.08f), TZ(0.24f)), dark, 0);
            break;
        case SPECIES_PLANT:
            body_block_push(buf, n, cap, v3(x_pos, Y(0.25f), 0),
                v3(TX(0.06f), TY(0.50f), TZ(0.06f)),
                v4(c.x*0.8f, c.y*1.1f, c.z*0.5f, 1), 0);
            body_block_push(buf, n, cap, v3(x_pos, Y(0.02f), 0),
                v3(TX(0.10f), TY(0.04f), TZ(0.10f)), dark, 0);
            break;
        case SPECIES_INSECTOID:
            for (int j = 0; j < 3; j++) {
                float dy = 0.55f - (float)j * 0.18f;
                float zz = (float)j * 0.08f;
                body_block_push(buf, n, cap, v3(x_pos, Y(dy), zz),
                    v3(TX(0.04f), TY(0.10f), TZ(0.04f)), c, 0);
            }
            break;
        case SPECIES_CRUSTACEAN:
            body_block_push(buf, n, cap, v3(x_pos, Y(0.30f), 0),
                v3(TX(0.08f), TY(0.30f), TZ(0.08f)), c, 0);
            body_block_push(buf, n, cap, v3(x_pos, Y(0.10f), 0),
                v3(TX(0.10f), TY(0.10f), TZ(0.14f)), dark, 0);
            break;
        default:
            body_block_push(buf, n, cap, v3(x_pos, Y(0.30f), 0),
                v3(TX(0.12f), TY(0.35f), TZ(0.12f)), c, 1);
            body_block_push(buf, n, cap, v3(x_pos, Y(0.06f), 0),
                v3(TX(0.08f), TY(0.08f), TZ(0.14f)),
                v4(c.x*0.9f, c.y*1.1f, c.z*0.9f, 1), 1);
            break;
    }
    #undef Y
    #undef TX
    #undef TY
    #undef TZ
    (void)side_sign;
}

static void body_build_extra(BodyBlock** buf, int* n, int* cap,
                              SpeciesKind sp, float s, V4 c, int idx,
                              const BodyMorphology* morph) {
    (void)sp;
    float len_mul = morph ? morph->limb_length_mul : 1.f;
    float ang = TAU_F * (float)idx / 4.f;
    float ox = cosf(ang) * 0.4f;
    float oz = sinf(ang) * 0.4f;
    for (int j = 0; j < 4; j++) {
        float dy = 1.15f - (float)j * 0.10f;
        float rr = 0.06f - (float)j * 0.008f;
        body_block_push(buf, n, cap,
            v3(ox * s * len_mul, dy * s * len_mul, oz * s * len_mul),
            v3(rr * s, 0.10f * s * len_mul, rr * s), c, 1);
    }
    body_block_push(buf, n, cap,
        v3(ox * s * len_mul, 1.22f * s * len_mul, oz * s * len_mul),
        v3(0.03f * s, 0.03f * s, 0.03f * s),
        v4(c.x*1.3f, c.y*1.3f, c.z*0.7f, 1), 1);
}

static MorphStyle morph_style_sample(uint32_t seed, float humanity, float weird) {
    (void)seed;
    if (xrng_f() < 0.25f) return MORPH_STYLE_NONE;
    float weights[MORPH_STYLE_COUNT] = {0.f};
    for (int i = 1; i < MORPH_STYLE_COUNT; i++) {
        float w = g_style_profiles[i].weight_base;
        switch ((MorphStyle)i) {
            case MORPH_STYLE_ANTHRO:
            case MORPH_STYLE_SLEEK:
            case MORPH_STYLE_RETRO_FUTURE:
                w *= (0.3f + humanity * 1.4f);
                break;
            case MORPH_STYLE_ALIEN_TAXONOMY:
            case MORPH_STYLE_BIOMECH:
                w *= (0.2f + weird * 1.8f);
                break;
            case MORPH_STYLE_CYBERPUNK:
                w *= (0.4f + weird * 1.0f);
                break;
            case MORPH_STYLE_INDUSTRIAL:
            case MORPH_STYLE_MECHA:
                w *= (0.6f + weird * 0.6f);
                break;
            default:
                break;
        }
        weights[i] = w;
    }
    int pick = xrng_weighted(weights, MORPH_STYLE_COUNT);
    if (pick <= 0 || pick >= MORPH_STYLE_COUNT) return MORPH_STYLE_NONE;
    return (MorphStyle)pick;
}

static void morph_style_fill_random(BodyMorphology* out) {
    out->limb_length_mul    = 0.7f + xrng_f() * 0.8f;
    out->limb_thickness_mul = 0.6f + xrng_f() * 1.2f;
    out->torso_width_mul    = 0.7f + xrng_f() * 0.8f;
    out->head_scale_mul     = 0.6f + xrng_f() * 1.0f;
    out->shoulder_width_mul = 0.8f + xrng_f() * 0.8f;
    out->greeble_density    = xrng_f() * 0.5f;
    out->panel_line_density = xrng_f() * 0.3f;
    out->asymmetry_bias     = xrng_f();
    out->adherence          = 0.f;
    out->palette_scheme     = PALETTE_SCHEME_RANDOM;
    out->palette_sat        = 0.4f + xrng_f() * 0.4f;
    out->palette_lum        = 0.4f + xrng_f() * 0.3f;
    out->palette_hue_center = -1.f;
    out->palette_hue_spread = 0.f;
}

static void morph_style_fill_from_profile(BodyMorphology* out,
                                           const MorphStyleProfile* prof) {
    const float J = 0.12f;
    out->limb_length_mul    = prof->limb_length_mul    * (1.f + xrng_range(-J, J));
    out->limb_thickness_mul = prof->limb_thickness_mul * (1.f + xrng_range(-J, J));
    out->torso_width_mul    = prof->torso_width_mul    * (1.f + xrng_range(-J, J));
    out->head_scale_mul     = prof->head_scale_mul     * (1.f + xrng_range(-J, J));
    out->shoulder_width_mul = prof->shoulder_width_mul * (1.f + xrng_range(-J, J));
    out->greeble_density    = clampf(prof->greeble_density    + xrng_range(-0.1f, 0.1f), 0.f, 1.f);
    out->panel_line_density = clampf(prof->panel_line_density + xrng_range(-0.1f, 0.1f), 0.f, 1.f);
    out->asymmetry_bias     = clampf(prof->asymmetry_bias     + xrng_range(-0.1f, 0.1f), 0.f, 1.f);
    out->adherence          = prof->adherence;
    out->palette_scheme     = (uint8_t)prof->palette_scheme;
    out->palette_sat        = prof->palette_sat;
    out->palette_lum        = prof->palette_lum;
    out->palette_hue_center = prof->palette_hue_center;
    out->palette_hue_spread = prof->palette_hue_spread;
}

static void morph_style_fill_profile(uint32_t seed, float humanity,
                                       float weird, BodyMorphology* out) {
    out->style = (uint8_t)morph_style_sample(seed, humanity, weird);
    const MorphStyleProfile* prof = &g_style_profiles[out->style];
    if (out->style == MORPH_STYLE_NONE) {
        morph_style_fill_random(out);
        return;
    }
    morph_style_fill_from_profile(out, prof);
}

static SpeciesKind body_gen_pick_base_species(uint32_t seed, float humanity,
                                                float weird, MorphStyle style) {
    (void)seed;
    if (xrng_f() <= humanity * 0.9f + 0.05f) return SPECIES_HUMANOID;
    uint32_t mask = g_style_profiles[style].preferred_species_mask;
    if (mask && xrng_f() < 0.55f) {
        int candidates[SPECIES_COUNT];
        int nc = 0;
        for (int i = 0; i < SPECIES_COUNT; i++)
            if (mask & (1u << i)) candidates[nc++] = i;
        if (nc > 0) return (SpeciesKind)candidates[xrng_int(nc)];
    }
    return (SpeciesKind)xrng_int(SPECIES_COUNT);
}

static void body_gen_apply_species_mix(BodyMorphology* out, SpeciesKind base,
                                        float weird, float adherence) {
    float mix = weird * 0.5f * (1.f - adherence * 0.6f);
    out->head_species  = (xrng_f() < mix) ? (SpeciesKind)xrng_int(SPECIES_COUNT) : base;
    out->torso_species = (xrng_f() < mix * 0.6f) ? (SpeciesKind)xrng_int(SPECIES_COUNT) : base;
    uint8_t dflt_arm = 2, dflt_leg = 2, dflt_head = 1, dflt_extra = 0;
    switch (base) {
        case SPECIES_ALIEN:      dflt_arm = 3; dflt_leg = 3; dflt_extra = 2; break;
        case SPECIES_PLANT:      dflt_arm = 0; dflt_leg = 0; break;
        case SPECIES_INSECTOID:  dflt_arm = 2; dflt_leg = 4; dflt_extra = 2; break;
        case SPECIES_CRUSTACEAN: dflt_arm = 2; dflt_leg = 4; break;
        case SPECIES_AMORPHOUS:  dflt_arm = 4; break;
        default: break;
    }
    float wm = weird * 0.4f * (1.f - adherence * 0.5f);
    out->arm_count   = (xrng_f() < wm) ? (uint8_t)xrng_int(7) : dflt_arm;
    out->leg_count   = (xrng_f() < wm) ? (uint8_t)xrng_int(7) : dflt_leg;
    out->extra_count = (xrng_f() < wm) ? (uint8_t)xrng_int(5) : dflt_extra;
    out->head_count  = (xrng_f() < weird * 0.15f * (1.f - adherence * 0.7f))
                       ? (uint8_t)(1 + xrng_int(3)) : dflt_head;
    for (int i = 0; i < 6; i++)
        out->arm_species[i] = (xrng_f() < mix) ? (SpeciesKind)xrng_int(SPECIES_COUNT) : base;
    for (int i = 0; i < 6; i++)
        out->leg_species[i] = (xrng_f() < mix) ? (SpeciesKind)xrng_int(SPECIES_COUNT) : base;
    for (int i = 0; i < 4; i++)
        out->extra_species[i] = (SpeciesKind)xrng_int(SPECIES_COUNT);
}

static void body_gen_set_height_from_style(BodyMorphology* out, float humanity) {
    float base = (humanity > 0.7f) ? (1.5f + xrng_f() * 0.5f)
                                    : (0.3f + xrng_f() * 2.7f);
    out->height = base * g_style_profiles[out->style].body_height_mul;
    if (out->height < 0.4f) out->height = 0.4f;
}

static void body_gen_set_colors_from_palette(BodyMorphology* out) {
    out->skin_color = palette_gen_harmonious(out->seed ^ 0x11u,
                                              out->palette_scheme,
                                              out->palette_sat,
                                              out->palette_lum,
                                              out->palette_hue_center,
                                              out->palette_hue_spread);
    out->detail_color = palette_gen_harmonious(out->seed ^ 0x22u,
                                                out->palette_scheme,
                                                out->palette_sat * 0.7f,
                                                out->palette_lum * 1.25f,
                                                out->palette_hue_center,
                                                out->palette_hue_spread);
}

static void body_gen_build_all(BodyMorphology* out) {
    int cap = 0;
    out->block_count = 0;
    float s = out->height / 1.72f;
    for (int i = 0; i < out->head_count; i++) {
        float dx = (out->head_count == 1) ? 0.f
                  : (-0.15f + 0.30f * (float)i / (float)(out->head_count - 1));
        int n0 = out->block_count;
        body_build_head(&out->blocks, &out->block_count, &cap,
                         out->head_species, s, out->skin_color, out);
        for (int k = n0; k < out->block_count; k++)
            out->blocks[k].pos_local.x += dx * s;
    }
    body_build_torso(&out->blocks, &out->block_count, &cap,
                      out->torso_species, s, out->skin_color, out);
    for (int i = 0; i < out->arm_count; i++)
        body_build_arm(&out->blocks, &out->block_count, &cap,
                        out->arm_species[i], s, out->skin_color, i,
                        (int)out->arm_count, out);
    for (int i = 0; i < out->leg_count; i++)
        body_build_leg(&out->blocks, &out->block_count, &cap,
                        out->leg_species[i], s, out->skin_color, i,
                        (int)out->leg_count, out);
    for (int i = 0; i < out->extra_count; i++)
        body_build_extra(&out->blocks, &out->block_count, &cap,
                          out->extra_species[i], s, out->detail_color, i, out);
    out->render_mode = (out->mutation_level > 3) ? 1 : 0;
}

static void body_gen(uint32_t seed, int cx, int cy, int cz, BodyMorphology* out) {
    if (!out) return;
    memset(out, 0, sizeof(*out));
    out->seed = seed;
    xrng_seed(seed);
    float humanity = 1.f / (1.f + sqrtf((float)(cx*cx + cy*cy + cz*cz)) * 0.15f);
    float weird = 1.f - humanity;
    morph_style_fill_profile(seed, humanity, weird, out);
    SpeciesKind base = body_gen_pick_base_species(seed, humanity, weird,
                                                    (MorphStyle)out->style);
    body_gen_apply_species_mix(out, base, weird, out->adherence);
    body_gen_set_height_from_style(out, humanity);
    body_gen_set_colors_from_palette(out);
    out->mutation_level = (uint8_t)clampf(weird * 5.f * xrng_f() +
                                            xrng_f() * 2.f, 0.f, 5.f);
    body_gen_build_all(out);
}

static void body_gen_by_species(uint32_t seed, SpeciesKind sp,
                                 BodyMorphology* out) {
    if (!out) return;
    memset(out, 0, sizeof(*out));
    out->seed = seed;
    xrng_seed(seed);
    out->head_species = sp;
    out->torso_species = sp;
    for (int i = 0; i < 6; i++) { out->arm_species[i] = sp; out->leg_species[i] = sp; }
    for (int i = 0; i < 4; i++) out->extra_species[i] = sp;
    switch (sp) {
        case SPECIES_ALIEN:      out->arm_count=3; out->leg_count=3; out->extra_count=2; break;
        case SPECIES_INSECTOID:  out->arm_count=2; out->leg_count=4; out->extra_count=2; break;
        case SPECIES_CRUSTACEAN: out->arm_count=2; out->leg_count=4; break;
        case SPECIES_AMORPHOUS:  out->arm_count=4; break;
        case SPECIES_PLANT:      break;
        default:                 out->arm_count=2; out->leg_count=2; break;
    }
    out->head_count = 1;
    out->height = 0.5f + xrng_f() * 2.5f;
    morph_style_fill_profile(seed, 0.6f, 0.4f, out);
    body_gen_set_colors_from_palette(out);
    out->mutation_level = (uint8_t)(xrng_u32() % 5);
    body_gen_build_all(out);
}

static void body_free(BodyMorphology* bm) {
    if (!bm) return;
    if (bm->blocks) { xfree(bm->blocks); bm->blocks = NULL; }
    bm->block_count = 0;
}

static void body_publish(const BodyMorphology* bm, V3 world, float yaw,
                          float pitch, uint32_t slot_hint) {
    if (!bm || bm->block_count <= 0 || !bm->blocks) return;
    if (slot_hint >= MAX_ENTITIES) return;
    float cy = cosf(yaw),   sy = sinf(yaw);
    float cp = cosf(pitch), sp = sinf(pitch);
    int idx = 0;
    for (int i = 0; i < bm->block_count && idx < MAX_RCMDS_PER_ENTITY; i++) {
        const BodyBlock* b = &bm->blocks[i];
        int mesh_id = (b->mesh == 0) ? g_mesh_unit_box_id : g_mesh_unit_sphere_id;
        if ((int)mesh_id < 0 || (int)mesh_id >= g_mesh_count) continue;
//        if (mesh_id < 0) continue;
        uint32_t rc = entity_rcmd_get(slot_hint, (uint8_t)idx, 100, RCK_MESH);
        if (rc == UINT32_MAX) break;
        Mat4 m;
        m[0]  =  cy * b->scale.x;
        m[1]  = 0;
        m[2]  =  sy * b->scale.x;
        m[3]  = 0;
        m[4]  = -sy * sp * b->scale.y;
        m[5]  =  cp * b->scale.y;
        m[6]  =  cy * sp * b->scale.y;
        m[7]  = 0;
        m[8]  = -sy * cp * b->scale.z;
        m[9]  = -sp * b->scale.z;
        m[10] =  cy * cp * b->scale.z;
        m[11] = 0;
        V3 lp = b->pos_local;
        float wx = m[0]*lp.x + m[4]*lp.y + m[8]*lp.z;
        float wy = m[1]*lp.x + m[5]*lp.y + m[9]*lp.z;
        float wz = m[2]*lp.x + m[6]*lp.y + m[10]*lp.z;
        m[12] = world.x + wx;
        m[13] = world.y + wy;
        m[14] = world.z + wz;
        m[15] = 1.f;
        Rcmd* c = &g_rp.cmds[rc];
        c->mesh = (GLuint)mesh_id;
        memcpy(c->xform, m, sizeof(Mat4));
        c->color = b->color;
        rcmd_visible(rc);
        idx++;
    }
    entity_rcmds_finalize(slot_hint, (uint8_t)idx);
}

static void bp_free(ThingBlueprint* bp) {
    if (!bp) return;
    if (bp->blocks) { xfree(bp->blocks); bp->blocks = NULL; }
    bp->block_count = 0;
}

static void bp_gen(uint32_t seed, ThingKind kind, ThingBlueprint* out) {
    if (!out) return;
    memset(out, 0, sizeof(*out));
    out->seed = seed;
    out->kind = kind;
    uint64_t ox = g_xrng_x, oy = g_xrng_y;
    int og = g_xrng_gauss_valid;
    float os = g_xrng_gauss_spare;
    xrng_seed(seed);
    out->tier = xrng_u32() % 6;
    out->material_id = mat_pool_get(hash3_u32(seed, 0xAAu, 0xBBu));
    Material* m = mat_get(out->material_id);
    out->tags_mask = m->tag_mask;
    out->recipe_complexity = xrng_f();
    out->mass = 0.1f + xrng_f() * 0.6f;
    out->hp = out->mass * MAT_HP_COEF;
    int cap = 0;
    out->blocks = NULL;
    out->block_count = 0;
    V4 col = m->color;
    int n_blocks = 1 + xrng_u32() % 4;
    for (int i = 0; i < n_blocks; i++) {
        if (out->block_count >= BODY_MORPH_BLOCKS_MAX) break;
        if (out->block_count >= cap) {
            int nc = cap * 2 + 8;
            if (nc > BODY_MORPH_BLOCKS_MAX) nc = BODY_MORPH_BLOCKS_MAX;
            BodyBlock* nb = (BodyBlock*)xrealloc(out->blocks, nc * sizeof(BodyBlock));
            if (!nb) break;
            out->blocks = nb;
            cap = nc;
        }
        BodyBlock* b = &out->blocks[out->block_count++];
        b->pos_local = v3(xrng_range(-0.15f, 0.15f),
                           xrng_range(0.05f, 0.35f),
                           xrng_range(-0.15f, 0.15f));
        b->scale = v3(0.05f + xrng_f() * 0.3f,
                       0.05f + xrng_f() * 0.3f,
                       0.05f + xrng_f() * 0.3f);
        float dark = 0.7f + xrng_f() * 0.5f;
        b->color = v4(clampf(col.x * dark, 0.f, 1.f),
                       clampf(col.y * dark, 0.f, 1.f),
                       clampf(col.z * dark, 0.f, 1.f),
                       1.f);
        b->mesh = (uint8_t)(xrng_u32() % 2);
        b->_pad[0] = b->_pad[1] = b->_pad[2] = 0;
    }
    g_xrng_x = ox; g_xrng_y = oy;
    g_xrng_gauss_valid = og; g_xrng_gauss_spare = os;
}

static void bp_cache_evict(void) {
    for (int i = 0; i < BLUEPRINT_CACHE_MAX; i++) {
        if (g_blueprint_cache[i].bp) {
            bp_free(g_blueprint_cache[i].bp);
            xfree(g_blueprint_cache[i].bp);
            g_blueprint_cache[i].bp = NULL;
        }
        g_blueprint_cache[i].seed = 0;
    }
}

static ThingBlueprint* bp_cache_get(uint32_t seed) {
    if (seed == 0) return NULL;
    g_blueprint_frame++;
    int slot = -1;
    for (int i = 0; i < BLUEPRINT_CACHE_MAX; i++) {
        if (g_blueprint_cache[i].seed == seed && g_blueprint_cache[i].bp) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {
        uint32_t oldest = 0xFFFFFFFFu;
        for (int i = 0; i < BLUEPRINT_CACHE_MAX; i++) {
            if (!g_blueprint_cache[i].bp) { slot = i; break; }
            if (g_blueprint_cache[i].last_used < oldest) {
                oldest = g_blueprint_cache[i].last_used;
                slot = i;
            }
        }
    }
    if (slot < 0) return NULL;
    if (g_blueprint_cache[slot].bp && g_blueprint_cache[slot].seed != seed) {
        bp_free(g_blueprint_cache[slot].bp);
        xfree(g_blueprint_cache[slot].bp);
        g_blueprint_cache[slot].bp = NULL;
        g_blueprint_cache[slot].seed = 0;
    }
    if (!g_blueprint_cache[slot].bp) {
        g_blueprint_cache[slot].bp = (ThingBlueprint*)xmalloc(sizeof(ThingBlueprint));
        if (!g_blueprint_cache[slot].bp) return NULL;
        uint32_t h = hash3_u32(seed, 0xB1u, 0xEEFu) & 0xFFu;
        ThingKind kind;
        if      (h < 51)  kind = THING_KIND_TOOL;
        else if (h < 89)  kind = THING_KIND_SHIP_PIECE;
        else if (h < 115) kind = THING_KIND_COMPUTER;
        else if (h < 140) kind = THING_KIND_WEAPON;
        else if (h < 165) kind = THING_KIND_ARMOR;
        else if (h < 190) kind = THING_KIND_FOOD;
        else if (h < 216) kind = THING_KIND_MEDICINE;
        else if (h < 241) kind = THING_KIND_DRONE_KIT;
        else              kind = THING_KIND_CREATURE;
        bp_gen(seed, kind, g_blueprint_cache[slot].bp);
        g_blueprint_cache[slot].seed = seed;
    }
    g_blueprint_cache[slot].last_used = g_blueprint_frame;
    return g_blueprint_cache[slot].bp;
}

static void bp_compose(const ThingBlueprint* in, int n, uint32_t tier_max,
                        ThingBlueprint* out) {
    if (!in || n <= 0 || !out) return;
    memset(out, 0, sizeof(*out));
    uint32_t seed = 0;
    for (int i = 0; i < n; i++) seed = hash_combine(seed, in[i].seed);
    out->seed = seed ^ 0xC0DE1234u;
    uint32_t h = hash3_u32(out->seed, 0x77u, 0x99u);
    if ((h & 0xFFu) < 38) {
        out->kind = (ThingKind)(hash_u32(out->seed ^ 0xBEEFu) % (uint32_t)THING_KIND_COUNT);
    } else {
        float w[4] = {0};
        int wn = (n < 4) ? n : 4;
        for (int i = 0; i < wn; i++) w[i] = 1.f + (float)in[i].tier * 0.3f;
        out->kind = in[xrng_weighted(w, wn)].kind;
    }
    uint32_t maxt = 0;
    float best_rar = -1.f;
    for (int i = 0; i < n; i++) {
        if (in[i].tier > maxt) maxt = in[i].tier;
        float r = (in[i].material_id < g_matpool.count)
                  ? g_matpool.cache[in[i].material_id].rarity : 0.f;
        if (r > best_rar) {
            best_rar = r;
            out->material_id = in[i].material_id;
        }
        out->tags_mask |= in[i].tags_mask;
    }
    out->tier = maxt + 1;
    if (out->tier > tier_max) out->tier = tier_max;
    if (out->tier > 5) out->tier = 5;
    float mass = 0.f, hp = 0.f;
    for (int i = 0; i < n; i++) { mass += in[i].mass; hp += in[i].hp; }
    out->mass = mass * 0.85f;
    out->hp   = hp   * 0.95f;
    out->recipe_complexity = 1.f;
    int best_i = 0;
    for (int i = 1; i < n; i++)
        if (in[i].block_count > in[best_i].block_count) best_i = i;
    if (in[best_i].block_count > 0) {
        out->blocks = (BodyBlock*)xmalloc(in[best_i].block_count * sizeof(BodyBlock));
        if (out->blocks) {
            memcpy(out->blocks, in[best_i].blocks,
                   in[best_i].block_count * sizeof(BodyBlock));
            out->block_count = in[best_i].block_count;
        }
    }
    if (out->block_count < BODY_MORPH_BLOCKS_MAX && out->blocks) {
        BodyBlock* marker = &out->blocks[out->block_count++];
        marker->pos_local = v3(0, 0.35f, 0);
        marker->scale = v3(0.05f, 0.10f, 0.05f);
        marker->color = color_gen(hash_u32(out->seed), 5);
        marker->mesh = 0;
    }
}

static void bp_downgrade(const ThingBlueprint* in, int n,
                          ThingBlueprint* out) {
    if (!in || n <= 0 || !out) return;
    bp_compose(in, n, 4, out);
    if (out->tier > 0) out->tier--;
    if (out->hp > 0)   out->hp   *= 0.5f;
    if (out->mass > 0) out->mass *= 0.7f;
}

static uint32_t side_struct_size(uint32_t kind) {
    switch (kind) {
        case SD_SHIP:         return (uint32_t)sizeof(ShipData);
        case SD_COMPONENT:    return (uint32_t)sizeof(ComponentData);
        case SD_WEAPON:       return (uint32_t)sizeof(WeaponData);
        case SD_AI:           return (uint32_t)sizeof(AiData);
        case SD_LAUNCHER:     return (uint32_t)sizeof(LauncherData);
        case SD_LANZADERA:    return (uint32_t)sizeof(LanzaderaData);
        case SD_MISSION:      return (uint32_t)sizeof(MissionData);
        case SD_TOURNAMENT:   return (uint32_t)sizeof(TournamentData);
        case SD_FORGE:        return (uint32_t)sizeof(ForgeData);
        case SD_REGIME:       return (uint32_t)sizeof(RegimeData);
        case SD_IDEOLOGY:     return (uint32_t)sizeof(IdeologyData);
        case SD_SOCIAL:       return (uint32_t)sizeof(SocialGroupData);
        case SD_HUB_OVERFLOW: return (uint32_t)sizeof(HubOverflow);
        case SD_ZONE_PERSIST: return (uint32_t)sizeof(ZonePersist);
        case SD_NPC:          return (uint32_t)sizeof(NpcProfile);
        case SD_PSYCH:        return (uint32_t)sizeof(NpcPsychState);
        case SD_NPC_NEEDS:    return (uint32_t)sizeof(NpcNeeds);
        default:              return 0;
    }
}

static void side_pool_init(uint32_t kind, uint32_t initial_cap, int is_pointer) {
    if (kind >= SD_COUNT) return;
    SidePool* p = &g_side_pools[kind];
    uint32_t es = side_struct_size(kind);
    if (es == 0) return;
    if (initial_cap < 8) initial_cap = 8;
    p->elem_size  = es;
    p->is_pointer = (uint8_t)is_pointer;
    p->data_stride = is_pointer ? (uint32_t)sizeof(void*) : es;
    p->capacity   = initial_cap;
    p->count      = 0;
    p->free_count = initial_cap;
    p->data     = xcalloc(initial_cap, p->data_stride);
    p->free_arr = (uint32_t*)xmalloc(initial_cap * sizeof(uint32_t));
    if (!p->data || !p->free_arr) {
        xfree(p->data);
        xfree(p->free_arr);
        memset(p, 0, sizeof(*p));
        return;
    }
    for (uint32_t i = 0; i < initial_cap; i++)
        p->free_arr[i] = initial_cap - 1 - i;
}

static void side_pool_destroy(uint32_t kind) {
    if (kind >= SD_COUNT) return;
    SidePool* p = &g_side_pools[kind];
    if (p->is_pointer) {
        void** slots = (void**)p->data;
        if (slots) for (uint32_t i = 0; i < p->capacity; i++)
            if (slots[i]) xfree(slots[i]);
    }
    xfree(p->data);
    xfree(p->free_arr);
    memset(p, 0, sizeof(*p));
}

static uint32_t side_pool_alloc(uint32_t kind) {
    if (kind >= SD_COUNT) return UINT32_MAX;
    SidePool* p = &g_side_pools[kind];
    if (p->free_count == 0) {
        uint32_t nc = p->capacity * 2 + 2;
        void*     nd = xrealloc(p->data, (size_t)nc * p->data_stride);
        uint32_t* nf = (uint32_t*)xrealloc(p->free_arr, nc * sizeof(uint32_t));
        if (!nd || !nf) {
            if (nd) p->data = nd;
            if (nf) p->free_arr = nf;
            return UINT32_MAX;
        }
        p->data = nd;
        p->free_arr = nf;
        memset((char*)nd + (size_t)p->capacity * p->data_stride, 0,
               (size_t)(nc - p->capacity) * p->data_stride);
        for (uint32_t i = 0; i < (nc - p->capacity); i++)
            p->free_arr[p->free_count++] = nc - 1 - i;
        p->capacity = nc;
    }
    uint32_t idx = p->free_arr[--p->free_count];
    memset((char*)p->data + (size_t)idx * p->data_stride, 0, p->data_stride);
    p->count++;
    if (p->is_pointer) {
        void** slots = (void**)p->data;
        slots[idx] = xcalloc(1, p->elem_size);
        if (!slots[idx]) {
            p->free_arr[p->free_count++] = idx;
            p->count--;
            return UINT32_MAX;
        }
    }
    return idx;
}

static void side_pool_free(uint32_t kind, uint32_t idx) {
    if (kind >= SD_COUNT) return;
    SidePool* p = &g_side_pools[kind];
    if (idx >= p->capacity) return;
    if (p->free_count >= p->capacity) return;
    if (p->is_pointer) {
        void** slots = (void**)p->data;
        if (slots[idx]) { xfree(slots[idx]); slots[idx] = NULL; }
    }
    p->free_arr[p->free_count++] = idx;
    if (p->count > 0) p->count--;
}

static void* side_pool_at(uint32_t kind, uint32_t idx) {
    if (kind >= SD_COUNT) return NULL;
    SidePool* p = &g_side_pools[kind];
    if (idx >= p->capacity) return NULL;
    void* base = (char*)p->data + (size_t)idx * p->data_stride;
    if (p->is_pointer) return *((void**)base);
    return base;
}

static void side_pools_init(void) {
    side_pool_init(SD_SHIP,          16, 1);
    side_pool_init(SD_COMPONENT,     64, 1);
    side_pool_init(SD_WEAPON,        32, 1);
    side_pool_init(SD_AI,            64, 1);
    side_pool_init(SD_LAUNCHER,      8,  1);
    side_pool_init(SD_LANZADERA,     8,  1);
    side_pool_init(SD_MISSION,       64, 1);
    side_pool_init(SD_TOURNAMENT,    8,  1);
    side_pool_init(SD_FORGE,         8,  1);
    side_pool_init(SD_REGIME,        16, 1);
    side_pool_init(SD_IDEOLOGY,      16, 1);
    side_pool_init(SD_SOCIAL,        32, 1);
    side_pool_init(SD_HUB_OVERFLOW,  16, 0);
    side_pool_init(SD_ZONE_PERSIST,  16, 0);
    side_pool_init(SD_NPC,           32, 0);
    side_pool_init(SD_PSYCH,         32, 0);
    side_pool_init(SD_NPC_NEEDS,     32, 0);
    LOG("side_pools_init: %d kinds", SD_COUNT);
}

static void side_pools_shutdown(void) {
    for (int k = 0; k < SD_COUNT; k++) side_pool_destroy(k);
}

static SideKind thing_side_kind_for_type(uint32_t type) {
    switch (type) {
        case ET_SHIP:       return SD_SHIP;
        case ET_COMPONENT:  return SD_COMPONENT;
        case ET_WEAPON:     return SD_WEAPON;
        case ET_ALIEN:
        case ET_PIRATE:
        case ET_DRONE:      return SD_AI;
        case ET_LAUNCHER:   return SD_LAUNCHER;
        case ET_LANZADERA:  return SD_LANZADERA;
        case ET_MISSION:
        case ET_CONTRACT:   return SD_MISSION;
        case ET_TOURNAMENT: return SD_TOURNAMENT;
        case ET_FORGE:      return SD_FORGE;
        case ET_REGIME:     return SD_REGIME;
        case ET_IDEOLOGY:   return SD_IDEOLOGY;
        case ET_SOCIAL:     return SD_SOCIAL;
        default:            return SD_NONE;
    }
}

static void side_detach(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t || t->side_idx == UINT32_MAX) return;
    SideKind k = thing_side_kind_for_type(t->type);
    if (k != SD_NONE) side_pool_free((uint32_t)k, t->side_idx);
    t->side_idx = UINT32_MAX;
}

static void* entity_attach_side(uint32_t slot, SideKind kind) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    if (t->side_idx != UINT32_MAX) return NULL;
    uint32_t idx = side_pool_alloc((uint32_t)kind);
    if (idx == UINT32_MAX) return NULL;
    t->side_idx = idx;
    return side_pool_at((uint32_t)kind, idx);
}

static void* entity_side_ptr(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t || t->side_idx == UINT32_MAX) return NULL;
    SideKind k = thing_side_kind_for_type(t->type);
    if (k == SD_NONE) return NULL;
    return side_pool_at((uint32_t)k, t->side_idx);
}

static NpcProfile* npc_profile_alloc(void) {
    uint32_t idx = side_pool_alloc(SD_NPC);
    if (idx == UINT32_MAX) return NULL;
    return (NpcProfile*)side_pool_at(SD_NPC, idx);
}

static void npc_profile_free(NpcProfile* p) {
    if (!p) return;
    SidePool* pool = &g_side_pools[SD_NPC];
    uint32_t idx = (uint32_t)(((char*)p - (char*)pool->data) / pool->elem_size);
    side_pool_free(SD_NPC, idx);
}

static int npc_profile_bind(uint32_t slot, NpcProfile* p) {
    Thing* t = entity_get(slot);
    if (!t || !p) return 0;
    SidePool* pool = &g_side_pools[SD_NPC];
    uint32_t idx = (uint32_t)(((char*)p - (char*)pool->data) / pool->elem_size);
    ENT_SET_I(t, 30, idx);
    return 1;
}

static NpcProfile* npc_profile_get(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = ENT_I(t, 30);
    if (idx == 0xFFFFFFFFu) return NULL;
    return (NpcProfile*)side_pool_at(SD_NPC, idx);
}

static NpcPsychState* npc_psych_get(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = ENT_I(t, 31);
    if (idx == 0xFFFFFFFFu) return NULL;
    return (NpcPsychState*)side_pool_at(SD_PSYCH, idx);
}

static NpcPsychState* npc_psych_attach(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = side_pool_alloc(SD_PSYCH);
    if (idx == UINT32_MAX) return NULL;
    ENT_SET_I(t, 31, idx);
    return (NpcPsychState*)side_pool_at(SD_PSYCH, idx);
}

static NpcNeeds* npc_needs_attach(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = side_pool_alloc(SD_NPC_NEEDS);
    if (idx == UINT32_MAX) return NULL;
    NpcNeeds* n = (NpcNeeds*)side_pool_at(SD_NPC_NEEDS, idx);
    if (!n) { side_pool_free(SD_NPC_NEEDS, idx); return NULL; }
    ENT_SET_I(t, 27, idx);
    n->vitals.energy  = 0.7f + xrng_f() * 0.3f;
    n->vitals.hunger  = xrng_f() * 0.3f;
    n->vitals.stress  = xrng_f() * 0.2f;
    n->vitals.morale  = 0.5f + xrng_f() * 0.3f;
    n->vitals.boredom = xrng_f() * 0.3f;
    n->vitals.social  = xrng_f() * 0.3f;
    n->occupation     = NPC_OCC_IDLE;
    n->assignment.post_slot = UINT32_MAX;
    n->cache.dirty    = 1;
    return n;
}

static NpcNeeds* npc_needs_get(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = ENT_I(t, 27);
    if (idx == 0xFFFFFFFFu) return NULL;
    return (NpcNeeds*)side_pool_at(SD_NPC_NEEDS, idx);
}

static void type_slot_add(uint32_t type, uint32_t slot) {
    if (type >= ET_COUNT) return;
    uint32_t n = g_type_count[type];
    if (n >= g_type_cap[type]) {
        uint32_t nc = g_type_cap[type] * 2 + 2;
        uint32_t* ns = (uint32_t*)xrealloc(g_type_slots[type], nc * sizeof(uint32_t));
        if (!ns) return;
        g_type_slots[type] = ns;
        g_type_cap[type] = nc;
    }
    g_type_slots[type][n] = slot;
    g_type_count[type] = n + 1;
}

static void type_slot_remove(uint32_t type, uint32_t slot) {
    if (type >= ET_COUNT) return;
    uint32_t n = g_type_count[type];
    for (uint32_t i = 0; i < n; i++) {
        if (g_type_slots[type][i] != slot) continue;
        g_type_slots[type][i] = g_type_slots[type][n - 1];
        g_type_count[type] = n - 1;
        return;
    }
}

static uint32_t query_type(uint32_t type, uint32_t* out, uint32_t max) {
    if (type >= ET_COUNT || !out) return 0;
    uint32_t n = g_type_count[type];
    if (n > max) n = max;
    memcpy(out, g_type_slots[type], n * sizeof(uint32_t));
    return n;
}

static void sh_clear(void) {
    for (uint32_t i = 0; i < SH_BUCKETS; i++) g_sh_head[i] = -1;
}

static int sh_coord(float v) { return (int)floorf(v / SH_CELL); }

static uint32_t sh_hash(int x, int y, int z) {
    uint32_t h = (uint32_t)(x * 73856093) ^ (uint32_t)(y * 19349663)
               ^ (uint32_t)(z * 83492791);
    return h % SH_BUCKETS;
}

static void sh_insert(uint32_t slot, V3 pos) {
    if (!g_sh_next || slot >= g_things_cap) return;
    uint32_t b = sh_hash(sh_coord(pos.x), sh_coord(pos.y), sh_coord(pos.z));
    g_sh_next[slot] = g_sh_head[b];
    g_sh_head[b] = (int32_t)slot;
}

static void sh_rebuild(void) {
    sh_clear();
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) { if (g_sh_next) g_sh_next[i] = -1; continue; }
        sh_insert(i, g_things[i].pos);
    }
}

static uint32_t sh_query_sphere(V3 center, float radius,
                                 uint32_t* out, uint32_t max) {
    if (!out || max == 0) return 0;
    int cx = sh_coord(center.x), cy = sh_coord(center.y), cz = sh_coord(center.z);
    int r = (int)(radius / SH_CELL) + 1;
    float r2 = radius * radius;
    uint32_t n = 0;
    for (int dz = -r; dz <= r; dz++)
    for (int dy = -r; dy <= r; dy++)
    for (int dx = -r; dx <= r; dx++) {
        uint32_t b = sh_hash(cx + dx, cy + dy, cz + dz);
        int32_t s = g_sh_head[b];
        while (s >= 0) {
            uint32_t si = (uint32_t)s;
            if (g_alive[si] && v3distsq(g_things[si].pos, center) <= r2) {
                if (n < max) out[n++] = si;
                else break;
            }
            s = g_sh_next[si];
        }
    }
    return n;
}

/* ---------------------------------------------------------------------
   Consulta dinamica del hash espacial, sin topes fijos de llamadas.
   Scratch por profundidad de anidacion (LIFO): crece via xrealloc
   (tokens 1x1). La capacidad pedida por defecto es g_things_cap, el
   techo exacto de resultados posibles: el limite deje de ser un tope
   de diseno y pasa a ser la poblacion real del mundo.
   --------------------------------------------------------------------- */
static uint32_t** g_sh_scratch_buf   = NULL;
static uint32_t*  g_sh_scratch_cap   = NULL;
static uint32_t   g_sh_scratch_slots = 0;
static uint32_t   g_sh_scratch_depth = 0;

static uint32_t sh_scratch_slot_acquire(uint32_t need) {
    if (need < 1) need = 1;
    if (g_sh_scratch_depth == g_sh_scratch_slots) {
        uint32_t ns = g_sh_scratch_slots ? g_sh_scratch_slots * 2u : 4u;
        uint32_t** nb = (uint32_t**)xrealloc(g_sh_scratch_buf,
                                             (size_t)ns * sizeof(uint32_t*));
        if (!nb) return UINT32_MAX;
        g_sh_scratch_buf = nb;
        uint32_t* nc = (uint32_t*)xrealloc(g_sh_scratch_cap,
                                           (size_t)ns * sizeof(uint32_t));
        if (!nc) return UINT32_MAX;
        g_sh_scratch_cap = nc;
        for (uint32_t i = g_sh_scratch_slots; i < ns; i++) {
            g_sh_scratch_buf[i] = NULL;
            g_sh_scratch_cap[i] = 0;
        }
        g_sh_scratch_slots = ns;
    }
    uint32_t s = g_sh_scratch_depth;
    if (g_sh_scratch_cap[s] < need) {
        uint32_t nc = g_sh_scratch_cap[s] ? g_sh_scratch_cap[s] : 16u;
        while (nc < need) nc *= 2u;
        uint32_t* p = (uint32_t*)xrealloc(g_sh_scratch_buf[s],
                                          (size_t)nc * sizeof(uint32_t));
        if (!p) return UINT32_MAX;
        g_sh_scratch_buf[s] = p;
        g_sh_scratch_cap[s] = nc;
    }
    g_sh_scratch_depth++;
    return s;
}

static void sh_scratch_release(void) {
    if (g_sh_scratch_depth) g_sh_scratch_depth--;
}

static void sh_scratch_shutdown(void) {
    for (uint32_t i = 0; i < g_sh_scratch_slots; i++) xfree(g_sh_scratch_buf[i]);
    xfree(g_sh_scratch_buf);
    xfree(g_sh_scratch_cap);
    g_sh_scratch_buf   = NULL;
    g_sh_scratch_cap   = NULL;
    g_sh_scratch_slots = 0;
    g_sh_scratch_depth = 0;
}

static uint32_t sh_query_dyn(V3 center, float radius, uint32_t want,
                             uint32_t** out_ids) {
    *out_ids = NULL;
    if (want < 1) want = 1;
    uint32_t s = sh_scratch_slot_acquire(want);
    if (s == UINT32_MAX) return 0;
    uint32_t n = sh_query_sphere(center, radius, g_sh_scratch_buf[s], want);
    *out_ids = g_sh_scratch_buf[s];
    return n;
}

static void hub_free_overflow(Thing* t) {
    if (!t || t->children_ext == UINT32_MAX) return;
    HubOverflow* ov = (HubOverflow*)side_pool_at(SD_HUB_OVERFLOW, t->children_ext);
    if (ov) {
        xfree(ov->children);
        xfree(ov->mat_refs);
        ov->children = NULL;
        ov->mat_refs = NULL;
    }
    side_pool_free(SD_HUB_OVERFLOW, t->children_ext);
    t->children_ext = UINT32_MAX;
}

static HubOverflow* hub_ensure_overflow(Thing* t) {
    if (!t) return NULL;
    if (t->children_ext == UINT32_MAX) {
        uint32_t idx = side_pool_alloc(SD_HUB_OVERFLOW);
        if (idx == UINT32_MAX) return NULL;
        HubOverflow* ov = (HubOverflow*)side_pool_at(SD_HUB_OVERFLOW, idx);
        if (!ov) { side_pool_free(SD_HUB_OVERFLOW, idx); return NULL; }
        memset(ov, 0, sizeof(*ov));
        t->children_ext = idx;
    }
    return (HubOverflow*)side_pool_at(SD_HUB_OVERFLOW, t->children_ext);
}

static int thing_add_child(uint32_t parent_slot, uint32_t child_slot) {
    Thing* p = entity_get(parent_slot);
    Thing* c = entity_get(child_slot);
    if (!p || !c) return 0;
    if (p->num_children < 8) {
        p->u.hub.children[p->num_children++] = child_slot;
    } else {
        HubOverflow* ov = hub_ensure_overflow(p);
        if (!ov) return 0;
        if (ov->count >= ov->cap) {
            uint32_t nc = ov->cap ? ov->cap * 2 : 8;
            uint32_t* nca = (uint32_t*)xrealloc(ov->children, nc * sizeof(uint32_t));
            if (!nca) return 0;
            ov->children = nca;
            ov->cap = nc;
        }
        ov->children[ov->count++] = child_slot;
    }
    c->parent = parent_slot;
    p->flags |= ENT_FLAG_HUB;
    return 1;
}

static int thing_add_mat_ref(uint32_t slot, uint16_t mat_id, uint16_t qty) {
    Thing* t = entity_get(slot);
    if (!t) return 0;
    uint32_t packed = ((uint32_t)mat_id << 16) | qty;
    for (uint16_t i = 0; i < t->num_mat_refs; i++) {
        uint32_t r = t->u.hub.mat_refs[i];
        if ((r >> 16) == mat_id) {
            uint16_t nq = (uint16_t)((r & 0xFFFF) + qty);
            t->u.hub.mat_refs[i] = ((uint32_t)mat_id << 16) | nq;
            return 1;
        }
    }
    if (t->num_mat_refs < 8) {
        t->u.hub.mat_refs[t->num_mat_refs++] = packed;
        return 1;
    }
    HubOverflow* ov = hub_ensure_overflow(t);
    if (!ov) return 0;
    for (uint32_t i = 0; i < ov->num_mat_refs; i++) {
        uint32_t r = ov->mat_refs[i];
        if ((r >> 16) == mat_id) {
            uint16_t nq = (uint16_t)((r & 0xFFFF) + qty);
            ov->mat_refs[i] = ((uint32_t)mat_id << 16) | nq;
            return 1;
        }
    }
    if (ov->num_mat_refs >= ov->cap) {
        uint32_t nc = ov->cap ? ov->cap * 2 : 8;
        uint32_t* nm = (uint32_t*)xrealloc(ov->mat_refs, nc * sizeof(uint32_t));
        if (!nm) return 0;
        ov->mat_refs = nm;
        ov->cap = nc;
    }
    ov->mat_refs[ov->num_mat_refs++] = packed;
    return 1;
}

static void thing_pool_grow(uint32_t new_cap) {
    if (new_cap <= g_things_cap) return;
    uint32_t old = g_things_cap;
    Thing*    nt = (Thing*)    xrealloc(g_things,    new_cap * sizeof(Thing));
    uint8_t*  na = (uint8_t*)  xrealloc(g_alive,     new_cap);
    uint32_t* nf = (uint32_t*) xrealloc(g_free_list, new_cap * sizeof(uint32_t));
    int32_t*  ns = (int32_t*)  xrealloc(g_sh_next,   new_cap * sizeof(int32_t));
    if (!nt || !na || !nf || !ns) {
        if (nt) g_things    = nt;
        if (na) g_alive     = na;
        if (nf) g_free_list = nf;
        if (ns) g_sh_next   = ns;
        return;
    }
    g_things    = nt;
    g_alive     = na;
    g_free_list = nf;
    g_sh_next   = ns;
    memset(&g_things[old],    0, (new_cap - old) * sizeof(Thing));
    memset(&g_alive[old],     0, new_cap - old);
    memset(&g_sh_next[old],  -1, (new_cap - old) * sizeof(int32_t));
    for (uint32_t i = 0; i < (new_cap - old); i++)
        g_free_list[g_free_count++] = new_cap - 1 - i;
    g_things_cap = new_cap;
}

static void entity_pool_init(uint32_t initial_cap) {
    if (initial_cap < 64) initial_cap = 64;
    g_things_cap = 0;
    g_free_count = 0;
    g_live_count = 0;
    g_next_id    = 1;
    memset(g_type_count, 0, sizeof(g_type_count));
    thing_pool_grow(initial_cap);
    sh_clear();
    LOG("entity_pool_init: cap=%u", g_things_cap);
}

static void entity_pool_shutdown(void) {
    xfree(g_things);     g_things     = NULL;
    xfree(g_alive);      g_alive      = NULL;
    xfree(g_free_list);  g_free_list  = NULL;
    xfree(g_sh_next);    g_sh_next    = NULL;
    for (int i = 0; i < ET_COUNT; i++) {
        xfree(g_type_slots[i]);
        g_type_slots[i] = NULL;
        g_type_cap[i]   = 0;
    }
    g_things_cap = g_free_count = g_live_count = 0;
}

static int entity_alive(uint32_t slot) {
    return (slot < g_things_cap) && g_alive[slot];
}

static Thing* entity_get(uint32_t slot) {
    return entity_alive(slot) ? &g_things[slot] : NULL;
}

static uint32_t entity_live_count(void) { return g_live_count; }

static void entity_clear_template(Thing* t) {
    memset(t, 0, sizeof(*t));
    t->flags        = ENT_FLAG_ALIVE | ENT_FLAG_PHYSICS | ENT_FLAG_COLLIDE;
    t->radius       = 1.f;
    t->hp = t->maxhp = 1.f;
    t->mass         = 1.f;
    t->side_idx     = UINT32_MAX;
    t->children_ext = UINT32_MAX;
    t->parent       = UINT32_MAX;
    t->version      = 1;
    ENT_SET_I(t, 27, 0xFFFFFFFFu);
    ENT_SET_I(t, 28, 0xFFFFFFFFu);
    ENT_SET_I(t, 30, 0xFFFFFFFFu);
    ENT_SET_I(t, 31, 0xFFFFFFFFu);
}

static uint32_t entity_spawn(const Thing* tmpl) {
    if (!tmpl) return UINT32_MAX;
    if (g_free_count == 0) {
        uint32_t nc = g_things_cap * 2 + 2;
        if (nc < 128) nc = 128;
        thing_pool_grow(nc);
        if (g_free_count == 0) return UINT32_MAX;
    }
    uint32_t slot = g_free_list[--g_free_count];
    Thing* t = &g_things[slot];
    memcpy(t, tmpl, sizeof(Thing));
    t->id = g_next_id++;
    if (t->type >= ET_COUNT) t->type = ET_NONE;
    t->flags |= ENT_FLAG_ALIVE;
    g_alive[slot] = 1;
    g_live_count++;
    type_slot_add(t->type, slot);
    return slot;
}

static void entity_mark_dead(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return;
    if (t->flags & ENT_FLAG_MARKED_DEAD) return;
    t->flags |= ENT_FLAG_MARKED_DEAD;
    t->version++;
}

static void npc_slots_release(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t || t->type != ET_SHIP) return;
    uint32_t idx = ENT_I(t, 30);
    if (idx != 0xFFFFFFFFu) {
        side_pool_free(SD_NPC, idx);
        ENT_SET_I(t, 30, 0xFFFFFFFFu);
    }
    idx = ENT_I(t, 31);
    if (idx != 0xFFFFFFFFu) {
        side_pool_free(SD_PSYCH, idx);
        ENT_SET_I(t, 31, 0xFFFFFFFFu);
    }
    idx = ENT_I(t, 27);
    if (idx != 0xFFFFFFFFu) {
        side_pool_free(SD_NPC_NEEDS, idx);
        ENT_SET_I(t, 27, 0xFFFFFFFFu);
    }
}

static void combat_slot_release(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return;
    uint32_t idx = ENT_I(t, 28);
    ENT_SET_I(t, 28, 0xFFFFFFFFu);
    if (idx == 0xFFFFFFFFu || idx >= g_combat_states_cap) return;
    if (g_combat_free_n >= 512u) return;
    CombatStateData* cs = &g_combat_states[idx];
    memset(cs, 0, sizeof(*cs));
    cs->state             = CS_IDLE;
    cs->state_since       = (float)time_get();
    cs->opponent          = UINT32_MAX;
    cs->future_target     = UINT32_MAX;
    cs->forgive_threshold = 50.f;
    g_combat_free[g_combat_free_n++] = idx;
}

static void entity_destroy(uint32_t slot) {
    if (!entity_alive(slot)) return;
    Thing* t = &g_things[slot];
    uint32_t type = t->type;
    npc_slots_release(slot);
    combat_slot_release(slot);
    side_detach(slot);
    hub_free_overflow(t);
    type_slot_remove(type, slot);
    g_alive[slot] = 0;
    memset(t, 0, sizeof(Thing));
    g_free_list[g_free_count++] = slot;
    g_live_count--;
}

static void entity_flush_marked_dead(void) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) entity_destroy(i);
    }
}

static void rcmd_pool_init(uint32_t cap) {
    if (cap < 64) cap = 64;
    memset(&g_rp, 0, sizeof(g_rp));
    g_rp.cmd_cap     = cap;
    g_rp.cmds        = (Rcmd*)xcalloc(cap, sizeof(Rcmd));
    g_rp.free_cmds   = (uint32_t*)xmalloc(cap * sizeof(uint32_t));
    g_rp.visible     = (uint32_t*)xmalloc(cap * sizeof(uint32_t));
    g_rp.visible_cap = cap;
    if (!g_rp.cmds || !g_rp.free_cmds || !g_rp.visible) {
        xfree(g_rp.cmds);
        xfree(g_rp.free_cmds);
        xfree(g_rp.visible);
        memset(&g_rp, 0, sizeof(g_rp));
        return;
    }
    g_rp.free_count = cap;
    for (uint32_t i = 0; i < cap; i++) g_rp.free_cmds[i] = cap - 1 - i;
}

static void rcmd_pool_destroy(void) {
    xfree(g_rp.cmds);
    xfree(g_rp.free_cmds);
    xfree(g_rp.visible);
    memset(&g_rp, 0, sizeof(g_rp));
}

static void rcmd_pool_grow(uint32_t new_cap) {
    if (new_cap <= g_rp.cmd_cap) return;
    uint32_t old = g_rp.cmd_cap;
    Rcmd*     nc = (Rcmd*)    xrealloc(g_rp.cmds,      new_cap * sizeof(Rcmd));
    uint32_t* nf = (uint32_t*)xrealloc(g_rp.free_cmds, new_cap * sizeof(uint32_t));
    uint32_t* nv = (uint32_t*)xrealloc(g_rp.visible,   new_cap * sizeof(uint32_t));
    if (!nc || !nf || !nv) {
        if (nc) g_rp.cmds = nc;
        if (nf) g_rp.free_cmds = nf;
        if (nv) g_rp.visible = nv;
        return;
    }
    g_rp.cmds = nc;
    g_rp.free_cmds = nf;
    g_rp.visible = nv;
    for (uint32_t i = 0; i < (new_cap - old); i++)
        g_rp.free_cmds[g_rp.free_count++] = new_cap - 1 - i;
    g_rp.cmd_cap = new_cap;
    g_rp.visible_cap = new_cap;
}

static uint32_t rcmd_alloc(uint32_t kind, int32_t layer) {
    if (g_rp.free_count == 0)
        rcmd_pool_grow(g_rp.cmd_cap ? g_rp.cmd_cap * 2 : 256);
    if (g_rp.free_count == 0) return UINT32_MAX;
    uint32_t idx = g_rp.free_cmds[--g_rp.free_count];
    memset(&g_rp.cmds[idx], 0, sizeof(Rcmd));
    g_rp.cmds[idx].kind    = kind;
    g_rp.cmds[idx].layer   = layer;
    g_rp.cmds[idx].color   = v4(1, 1, 1, 1);
    g_rp.cmds[idx].pick_id = -1;
    mat4_identity(g_rp.cmds[idx].xform);
    g_rp.cmd_count++;
    return idx;
}

static void rcmd_free(uint32_t idx) {
    if (idx >= g_rp.cmd_cap) return;
    if (g_rp.cmds[idx].kind == RCK_NONE) return;
    g_rp.cmds[idx].kind = RCK_NONE;
    if (g_rp.free_count >= g_rp.cmd_cap) return;
    g_rp.free_cmds[g_rp.free_count++] = idx;
    if (g_rp.cmd_count > 0) g_rp.cmd_count--;
}

static void rcmd_color(uint32_t idx, V4 c) {
    if (idx < g_rp.cmd_cap) g_rp.cmds[idx].color = c;
}

static void rcmd_quad(uint32_t idx, float x, float y, float w, float h) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].p0 = v3(x, y, 0);
    g_rp.cmds[idx].w  = w;
    g_rp.cmds[idx].h  = h;
}

static void rcmd_line2d(uint32_t idx, float x0, float y0,
                         float x1, float y1, float width) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].p0 = v3(x0, y0, 0);
    g_rp.cmds[idx].p1 = v3(x1, y1, 0);
    g_rp.cmds[idx].w  = width;
}

static void rcmd_point2d(uint32_t idx, float x, float y, float size) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].p0 = v3(x, y, 0);
    g_rp.cmds[idx].w  = size;
}

static void rcmd_billboard(uint32_t idx, V3 pos, float size) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].p0 = pos;
    g_rp.cmds[idx].w  = size;
}

static void rcmd_billboard_tex(uint32_t idx, V3 pos, float size,
                                float u0, float v0, float u1, float v1,
                                float ex, float ey, float ez, float ew) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].p0 = pos;
    g_rp.cmds[idx].w  = size;
    g_rp.cmds[idx].uv[0] = u0; g_rp.cmds[idx].uv[1] = v0;
    g_rp.cmds[idx].uv[2] = u1; g_rp.cmds[idx].uv[3] = v1;
    g_rp.cmds[idx].extra[0] = ex; g_rp.cmds[idx].extra[1] = ey;
    g_rp.cmds[idx].extra[2] = ez; g_rp.cmds[idx].extra[3] = ew;
}

static void rcmd_line3d(uint32_t idx, V3 a, V3 b, float width) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].p0 = a;
    g_rp.cmds[idx].p1 = b;
    g_rp.cmds[idx].w  = width;
}

static void rcmd_mesh(uint32_t idx, GLuint mesh, const Mat4 xform, V4 tint) {
    if (idx >= g_rp.cmd_cap) return;
if ((int)mesh < 0 || (int)mesh >= g_mesh_count) return;
    g_rp.cmds[idx].mesh = mesh;
    if (xform) memcpy(g_rp.cmds[idx].xform, xform, sizeof(Mat4));
    g_rp.cmds[idx].color = tint;
}

static void rcmd_pick(uint32_t idx, int32_t id, int32_t arg) {
    if (idx >= g_rp.cmd_cap) return;
    g_rp.cmds[idx].pick_id  = id;
    g_rp.cmds[idx].pick_arg = arg;
}

static void rcmd_visible(uint32_t idx) {
    if (idx >= g_rp.cmd_cap) return;
    if (g_rp.cmds[idx].flags & RFL_VISIBLE) return;
    g_rp.cmds[idx].flags |= RFL_VISIBLE;
    if (g_rp.visible_count < g_rp.visible_cap)
        g_rp.visible[g_rp.visible_count++] = idx;
}

static void pick_push(int32_t id, int32_t arg, int32_t layer,
                       float x, float y, float w, float h) {
    if (id < 0 || g_pick_n >= MAX_PICK_ZONES) return;
    PickZone* p = &g_pick[g_pick_n++];
    p->id = id; p->arg = arg; p->layer = layer;
    p->x = x; p->y = y; p->w = w; p->h = h;
}

static void pick_sort(void) {
    for (uint32_t i = 1; i < g_pick_n; i++) {
        PickZone key = g_pick[i];
        int32_t j = (int32_t)i - 1;
        while (j >= 0 && g_pick[j].layer > key.layer) {
            g_pick[j + 1] = g_pick[j];
            j--;
        }
        g_pick[j + 1] = key;
    }
}

static int32_t render_pick_test(float mx, float my, int32_t* out_arg) {
    for (int32_t i = (int32_t)g_pick_n - 1; i >= 0; i--) {
        PickZone* p = &g_pick[i];
        if (mx >= p->x && mx <= p->x + p->w &&
            my >= p->y && my <= p->y + p->h) {
            if (out_arg) *out_arg = p->arg;
            return p->id;
        }
    }
    return -1;
}

static void thing_cached_resize(uint32_t need) {
    if (need <= g_thing_cached_cap) return;
    uint32_t nc = g_thing_cached_cap * 2 + 64;
    if (nc < need) nc = need;
    ThingCached* np = (ThingCached*)xrealloc(g_thing_cached, nc * sizeof(ThingCached));
    if (!np) return;
    memset(&np[g_thing_cached_cap], 0,
           (nc - g_thing_cached_cap) * sizeof(ThingCached));
    g_thing_cached = np;
    g_thing_cached_cap = nc;
}

static void thing_cached_recompute(uint32_t slot, ThingCached* c, const Thing* t) {
    (void)slot;
    memset(c, 0, sizeof(*c));
    c->mat_id_in  = ENT_I(t, 0);
    c->seed_in    = t->seed;
    c->version_in = t->version;
    c->mass       = t->mass;
    c->radius_eff = t->radius;
    if (c->mat_id_in < g_matpool.count) {
        const Material* m = &g_matpool.cache[c->mat_id_in];
        c->tag_mask  = m->tag_mask;
        c->mat_color = m->color;
        if (m->tag_mask & MAT_TAG_VOLATILE)    c->is_volatile = 1;
        if (m->tag_mask & MAT_TAG_ORGANIC)     c->is_organic  = 1;
        if (!(m->tag_mask & MAT_TAG_VOLATILE) &&
            !(m->tag_mask & MAT_TAG_TOXIC)    &&
            !(m->tag_mask & MAT_TAG_RADIOACTIVE))
            c->is_stable = 1;
        if (m->tag_mask & MAT_TAG_CONDUCTIVE)  c->resistances[DMG_PHYS]   = 20;
        if (m->tag_mask & MAT_TAG_INSULATING)  c->resistances[DMG_HEAT]   = 40;
        if (m->tag_mask & MAT_TAG_RARE)        c->resistances[DMG_EXOTIC] = 30;
        if (m->tag_mask & MAT_TAG_CRYSTALLINE) c->resistances[DMG_PHYS]  += 15;
        if (m->tag_mask & MAT_TAG_TOXIC)       c->resistances[DMG_CHEM]   = 10;
    }
    c->hp_max_est = t->radius * t->radius * 8.f;
    c->valid = 1;
}

static ThingCached* thing_cached_get(uint32_t slot) {
    thing_cached_resize(slot + 1);
    if (slot >= g_thing_cached_cap) return NULL;
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    ThingCached* c = &g_thing_cached[slot];
    if (!c->valid
        || c->mat_id_in  != ENT_I(t, 0)
        || c->seed_in    != t->seed
        || c->version_in != t->version) {
        thing_cached_recompute(slot, c, t);
    }
    return c;
}

static float resistance_for_cached(uint32_t slot, uint32_t dtype) {
    ThingCached* c = thing_cached_get(slot);
    if (!c) return 0.f;
    if (dtype >= 5) return 0.f;
    return clampf(c->resistances[dtype] / 100.f, 0.f, 0.9f);
}

static void hit_queue_init(void) {
    if (g_hit_queue) return;
    g_hit_queue_cap = 256;
    g_hit_queue = (QueuedHit*)xcalloc(g_hit_queue_cap, sizeof(QueuedHit));
    g_hit_queue_n = 0;
}

static void hit_queue_shutdown(void) {
    xfree(g_hit_queue);
    g_hit_queue = NULL;
    g_hit_queue_cap = g_hit_queue_n = 0;
}

static void hit_queue_push(const QueuedHit* h) {
    if (g_hit_queue_n >= g_hit_queue_cap) {
        uint32_t nc = g_hit_queue_cap * 2 + 2;
        if (nc > HIT_QUEUE_SOFT_CAP) nc = HIT_QUEUE_SOFT_CAP;
        if (nc <= g_hit_queue_cap) return;
        QueuedHit* nq = (QueuedHit*)xrealloc(g_hit_queue, nc * sizeof(QueuedHit));
        if (!nq) return;
        g_hit_queue = nq;
        g_hit_queue_cap = nc;
    }
    g_hit_queue[g_hit_queue_n++] = *h;
}

static void entity_set_publish(PublishFn fn) { g_publish_fn = fn; }
static void entity_set_collide(CollideFn fn) { g_collide_fn = fn; }
static void entity_set_death(DeathFn fn)     { g_death_fn   = fn; }

static void entity_publish_all(PublishFn fn) {
    if (!fn) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].flags & ENT_FLAG_NO_PUBLISH) continue;
        fn(i, &g_things[i]);
    }
}

static void entity_rcmds_init(void) {
    memset(g_entity_rcmds, 0xFF, sizeof(g_entity_rcmds));
    memset(g_entity_rcmd_count, 0, sizeof(g_entity_rcmd_count));
}

static uint32_t entity_rcmd_get(uint32_t slot, uint8_t idx,
                                 int32_t layer, uint32_t kind) {
    if (slot >= MAX_ENTITIES || idx >= MAX_RCMDS_PER_ENTITY) return UINT32_MAX;
    uint32_t rc = g_entity_rcmds[slot][idx];
    if (rc == UINT32_MAX || rc >= g_rp.cmd_cap) {
        rc = rcmd_alloc(kind, layer);
        if (rc == UINT32_MAX) return UINT32_MAX;
        g_entity_rcmds[slot][idx] = rc;
    }
    Rcmd* c = &g_rp.cmds[rc];
    c->kind    = kind;
    c->flags   = 0;
    c->layer   = layer;
    c->color   = v4(1, 1, 1, 1);
    c->pick_id = -1;
    c->uv[0] = c->uv[1] = c->uv[2] = c->uv[3] = 0.f;
    c->extra[0] = c->extra[1] = c->extra[2] = c->extra[3] = 0.f;
    mat4_identity(c->xform);
    return rc;
}

static void entity_rcmds_finalize(uint32_t slot, uint8_t used) {
    if (slot >= MAX_ENTITIES) return;
    uint8_t old = g_entity_rcmd_count[slot];
    for (uint8_t k = used; k < old; k++) {
        if (g_entity_rcmds[slot][k] != UINT32_MAX) {
            rcmd_free(g_entity_rcmds[slot][k]);
            g_entity_rcmds[slot][k] = UINT32_MAX;
        }
    }
    g_entity_rcmd_count[slot] = used;
}

static uint8_t* g_rcmd_mark = NULL;
static uint32_t g_rcmd_mark_cap = 0;

static void rcmd_orphan_scratch_release(void) {
    xfree(g_rcmd_mark); g_rcmd_mark = NULL;
    g_rcmd_mark_cap = 0;
}
static void rcmd_cleanup_orphans(void) {
    if (g_rp.cmd_cap > g_rcmd_mark_cap) {
        uint32_t nc = g_rp.cmd_cap * 2;
        uint8_t* nb = (uint8_t*)xrealloc(g_rcmd_mark, nc);
        if (!nb) return;
        g_rcmd_mark = nb;
        g_rcmd_mark_cap = nc;
    }
    memset(g_rcmd_mark, 0, g_rp.cmd_cap);
    for (uint32_t i = 0; i < g_things_cap && i < MAX_ENTITIES; i++) {
        if (!g_alive[i]) continue;
        uint8_t n = g_entity_rcmd_count[i];
        for (uint8_t k = 0; k < n; k++) {
            uint32_t rc = g_entity_rcmds[i][k];
            if (rc < g_rp.cmd_cap) g_rcmd_mark[rc] = 1;
        }
    }
    for (uint32_t i = 0; i < g_rp.cmd_cap; i++) {
        if (g_rcmd_mark[i]) continue;
        if (g_rp.cmds[i].kind != RCK_NONE) rcmd_free(i);
    }
}

static void ecs_core_init(uint32_t entity_cap, uint32_t rcmd_cap) {
    entity_pool_init(entity_cap);
    entity_rcmds_init();
    side_pools_init();
    rcmd_pool_init(rcmd_cap);
    hit_queue_init();
    thing_cached_resize(entity_cap + 64);
    LOG("ecs_core_init: entity_cap=%u rcmd_cap=%u", entity_cap, rcmd_cap);
}

static void ecs_core_shutdown(void) {
    for (uint32_t i = 0; i < g_things_cap; i++)
        if (g_alive[i]) entity_destroy(i);
    rcmd_cleanup_orphans();
    rcmd_orphan_scratch_release();
    side_pools_shutdown();
    rcmd_pool_destroy();
    entity_pool_shutdown();
    hit_queue_shutdown();
    xfree(g_thing_cached);
    g_thing_cached = NULL;
    g_thing_cached_cap = 0;
    xfree(g_aff_sets);
    xfree(g_aff_inited);
    g_aff_sets = NULL;
    g_aff_inited = NULL;
    g_aff_cap = 0;
    LOG("ecs_core_shutdown");
}

static uint32_t actor_ship_slot(void) {
    return (g_player.inside_ship != UINT32_MAX)
           ? g_player.inside_ship : g_game.player_ship_slot;
}

static int actor_is_pilot(void)   { return g_player.mode == PLAYER_MODE_PILOT; }
static int actor_is_on_foot(void) { return g_player.mode == PLAYER_MODE_ON_FOOT; }
static int actor_is_eva(void)     { return g_player.mode == PLAYER_MODE_EVA; }
static int actor_inside_ship(void) { return g_player.inside_ship != UINT32_MAX; }

static int piloting_is_drone(void) {
    if (g_player.mode != PLAYER_MODE_PILOT) return 0;
    Thing* t = entity_get(g_player.inside_ship);
    return t && t->type == ET_DRONE;
}

static int piloting_is_ship(void) {
    if (g_player.mode != PLAYER_MODE_PILOT) return 0;
    Thing* t = entity_get(g_player.inside_ship);
    return t && t->type == ET_SHIP;
}

static uint32_t pickup_spawn(V3 pos, uint32_t ptype, uint32_t mat_id, float value) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_PICKUP;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_PHYSICS | ENT_FLAG_COLLIDE | ENT_FLAG_SPINNING;
    t.pos    = pos;
    t.radius = 0.4f;
    t.hp = t.maxhp = 1.f;
    t.mass   = 0.1f;
    t.life   = 60.f;
    t.spin   = xrng_range(-2.f, 2.f);
    t.seed   = xrng_u32();
    ENT_SET_I(&t, 0, ptype);
    ENT_SET_I(&t, 1, mat_id);
    ENT_SET_F(&t, 2, value);
    return entity_spawn(&t);
}

static int pickup_collect(uint32_t player_thing_slot, uint32_t pickup_slot) {
    if (!entity_alive(player_thing_slot)) return 0;
    if (!entity_alive(pickup_slot)) return 0;
    Thing* p = entity_get(pickup_slot);
    if (!p || p->type != ET_PICKUP) return 0;
    if (p->flags & ENT_FLAG_MARKED_DEAD) return 0;

    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX || !entity_alive(ship_slot)) return 0;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return 0;

    uint32_t ptype  = ENT_I(p, 0);
    uint32_t mat_id = ENT_I(p, 1);
    float    value  = ENT_F(p, 2);

    switch (ptype) {
        case PICKUP_TYPE_MAT:
            if (mat_id < MATERIAL_COUNT) {
                uint32_t have = sd->matinv[mat_id];
                have += (uint32_t)(value > 0.f ? value : 1.f);
                if (have > 0xFFF) have = 0xFFF;
                sd->matinv[mat_id] = have;
            }
            break;
        case PICKUP_TYPE_FUEL:
            sd->fuel += RECT_FUEL_PICKUP;
            if (sd->fuel > sd->fuel_max) sd->fuel = sd->fuel_max;
            break;
        case PICKUP_TYPE_UFO:
            sd->ufo_pieces += (value > 0.f ? value : 1.f);
            if (sd->ufo_pieces > 9999.f) sd->ufo_pieces = 9999.f;
            break;
        case PICKUP_TYPE_PART:
            part_cargo_push(mat_id, (uint32_t)(value > 0.f ? value : 1.f));
            notice_push("PART LOADED");
            break;
        default: break;
    }
    entity_mark_dead(pickup_slot);
    return 1;
}

static int pickup_try_collect_nearby(uint32_t player_thing_slot, float radius) {
    if (!entity_alive(player_thing_slot)) return 0;
    Thing* pt = entity_get(player_thing_slot);
    if (!pt) return 0;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(pt->pos, radius, g_things_cap, &nearby);
    int collected = 0;
    for (uint32_t k = 0; k < n; k++) {
        uint32_t s = nearby[k];
        if (!entity_alive(s)) continue;
        Thing* t = &g_things[s];
        if (t->type != ET_PICKUP) continue;
        if (pickup_collect(player_thing_slot, s)) collected++;
    }
    sh_scratch_release();
    return collected;
}

static void ship_ext_resize(uint32_t need) {
    if (need <= g_ship_ext_cap) return;
    uint32_t nc = g_ship_ext_cap ? g_ship_ext_cap * 2 : 64;
    if (nc < need) nc = need;
    ShipDataExt* np = (ShipDataExt*)xrealloc(g_ship_ext, nc * sizeof(ShipDataExt));
    if (!np) return;
    memset(&np[g_ship_ext_cap], 0,
           (nc - g_ship_ext_cap) * sizeof(ShipDataExt));
    g_ship_ext = np;
    g_ship_ext_cap = nc;
}

static ShipDataExt* ship_ext(uint32_t slot) {
    if (slot >= g_ship_ext_cap) return NULL;
    return &g_ship_ext[slot];
}

static void dirty_invalidate(uint32_t slot, uint32_t flags) {
    ShipDataExt* ext = ship_ext(slot);
    if (ext) ext->dirty_flags |= flags;
}

static void node_derive_phys(ShipNode* n) {
    if (!n) return;
    V3 d = v3mul(n->half_ext, 2.f);
    float volume = d.x * d.y * d.z;
    if (volume < 0.001f) volume = 0.001f;
    float mass = 0.f, hp = 0.f;
    mat_derive_phys(n->material_id, volume, &mass, &hp,
                    n->base_resist, &n->base_insulation_mask);
    n->mass = mass;
    n->structural_hp = hp;
    if (n->current_hp <= 0.f || n->current_hp > hp)
        n->current_hp = hp;
    if (n->props_mask & NODE_PROP_COMPUTER_ROOM) {
        int slots = (int)(volume * 2.f);
        if (slots < 1) slots = 1;
        if (slots > COMPUTER_ROOM_MAX_SLOTS) slots = COMPUTER_ROOM_MAX_SLOTS;
        n->computer_slot_count = (uint8_t)slots;
    }
}

static void armor_derive_phys(ArmorLayer* a, const ShipNode* node) {
    if (!a || !node) return;
    V3 d = v3mul(node->half_ext, 2.f);
    float volume = d.x * d.y * d.z * 0.15f;
    if (volume < 0.0005f) volume = 0.0005f;
    float mass = 0.f, hp = 0.f;
    mat_derive_phys(a->material_id, volume, &mass, &hp,
                    a->resist, &a->insulation_mask);
    a->maxhp = hp * 3.0f;
    if (a->hp <= 0.f || a->hp > a->maxhp) a->hp = a->maxhp;
}

static int port_opposite(int port) {
    switch (port) {
        case PORT_PX: return PORT_NX;
        case PORT_NX: return PORT_PX;
        case PORT_PY: return PORT_NY;
        case PORT_NY: return PORT_PY;
        case PORT_PZ: return PORT_NZ;
        case PORT_NZ: return PORT_PZ;
        default:      return PORT_PX;
    }
}

static V3 port_normal_local(int port) {
    switch (port) {
        case PORT_PX: return v3( 1, 0, 0);
        case PORT_NX: return v3(-1, 0, 0);
        case PORT_PY: return v3( 0, 1, 0);
        case PORT_NY: return v3( 0,-1, 0);
        case PORT_PZ: return v3( 0, 0, 1);
        case PORT_NZ: return v3( 0, 0,-1);
        default:      return v3( 0, 0, 1);
    }
}

static int edge_other_node(const ShipEdge* e, int cur) {
    if (!e) return -1;
    if (e->node_a == cur) return e->node_b;
    if (e->node_b == cur) return e->node_a;
    return -1;
}

static int node_add(uint32_t slot, uint32_t props_mask, V3 pos, V3 half_ext,
                     uint16_t mat_id) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || ext->node_count >= SHIP_MAX_NODES) return -1;
    int idx = ext->node_count++;
    ShipNode* n = &ext->nodes[idx];
    memset(n, 0, sizeof(*n));
    n->pos_local   = pos;
    n->half_ext    = half_ext;
    n->material_id = mat_id;
    n->props_mask  = props_mask;
    n->seed        = hash3_u32((uint32_t)idx, mat_id, props_mask);
    for (int p = 0; p < 6; p++) {
        n->port_edge[p] = -1;
        n->port_peer_node[p] = -1;
    }
    for (int i = 0; i < COMPUTER_ROOM_MAX_SLOTS; i++)
        n->computer_refs[i] = -1;
    node_derive_phys(n);
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
    return idx;
}

static int edge_add(uint32_t slot, int na, int pa, int nb, int pb, uint8_t kind) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    if (na < 0 || na >= ext->node_count) return -1;
    if (nb < 0 || nb >= ext->node_count) return -1;
    if (na == nb) return -1;
    if (pa < 0 || pa >= 6 || pb < 0 || pb >= 6) return -1;
    if (ext->edge_count >= SHIP_MAX_EDGES) return -1;
    ShipNode* a = &ext->nodes[na];
    ShipNode* b = &ext->nodes[nb];
    if (a->port_edge[pa] != -1) return -1;
    if (b->port_edge[pb] != -1) return -1;
    int eidx = ext->edge_count++;
    ShipEdge* e = &ext->edges[eidx];
    memset(e, 0, sizeof(*e));
    e->node_a = (int16_t)na; e->port_a = (int16_t)pa;
    e->node_b = (int16_t)nb; e->port_b = (int16_t)pb;
    e->kind = kind;
    e->structural_hp_max = (a->structural_hp + b->structural_hp) * 0.25f;
    if (e->structural_hp_max < 5.f) e->structural_hp_max = 5.f;
    e->structural_hp = e->structural_hp_max;
    e->max_stress = e->structural_hp_max * 100.f;
    a->port_edge[pa]      = (int16_t)eidx;
    a->port_peer_node[pa] = (int16_t)nb;
    b->port_edge[pb]      = (int16_t)eidx;
    b->port_peer_node[pb] = (int16_t)na;
    dirty_invalidate(slot, SHIP_DIRTY_TOPO);
    return eidx;
}

static void edge_remove(uint32_t slot, int edge_idx) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || edge_idx < 0 || edge_idx >= ext->edge_count) return;
    ShipEdge* e = &ext->edges[edge_idx];
    int na = e->node_a, pa = e->port_a;
    int nb = e->node_b, pb = e->port_b;
    if (na >= 0 && na < ext->node_count && pa >= 0 && pa < 6) {
        if (ext->nodes[na].port_edge[pa] == edge_idx) {
            ext->nodes[na].port_edge[pa] = -1;
            ext->nodes[na].port_peer_node[pa] = -1;
        }
    }
    if (nb >= 0 && nb < ext->node_count && pb >= 0 && pb < 6) {
        if (ext->nodes[nb].port_edge[pb] == edge_idx) {
            ext->nodes[nb].port_edge[pb] = -1;
            ext->nodes[nb].port_peer_node[pb] = -1;
        }
    }
    int last = ext->edge_count - 1;
    if (edge_idx != last) {
        ext->edges[edge_idx] = ext->edges[last];
        int la = ext->edges[edge_idx].node_a, lpa = ext->edges[edge_idx].port_a;
        int lb = ext->edges[edge_idx].node_b, lpb = ext->edges[edge_idx].port_b;
        if (la >= 0 && la < ext->node_count && lpa >= 0 && lpa < 6) {
            if (ext->nodes[la].port_edge[lpa] == last)
                ext->nodes[la].port_edge[lpa] = (int16_t)edge_idx;
        }
        if (lb >= 0 && lb < ext->node_count && lpb >= 0 && lpb < 6) {
            if (ext->nodes[lb].port_edge[lpb] == last)
                ext->nodes[lb].port_edge[lpb] = (int16_t)edge_idx;
        }
    }
    ext->edge_count--;
    dirty_invalidate(slot, SHIP_DIRTY_TOPO);
}

static void node_remove(uint32_t slot, int node_idx) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    for (int i = ext->edge_count - 1; i >= 0; i--) {
        ShipEdge* e = &ext->edges[i];
        if (e->node_a == node_idx || e->node_b == node_idx)
            edge_remove(slot, i);
    }
    ShipNode* n = &ext->nodes[node_idx];
    for (int i = 0; i < n->comp_ref_count && i < SHIP_MAX_COMP_PER_NODE; i++) {
        uint32_t c = (uint32_t)n->comp_refs[i];
        if (entity_alive(c)) entity_mark_dead(c);
    }
    n->comp_ref_count = 0;
    n->armor_count = 0;
    int last = ext->node_count - 1;
    if (node_idx != last) {
        ext->nodes[node_idx] = ext->nodes[last];
        for (int i = 0; i < ext->edge_count; i++) {
            if (ext->edges[i].node_a == last) ext->edges[i].node_a = (int16_t)node_idx;
            if (ext->edges[i].node_b == last) ext->edges[i].node_b = (int16_t)node_idx;
        }
        for (int i = 0; i < ext->node_count; i++)
            for (int p = 0; p < 6; p++)
                if (ext->nodes[i].port_peer_node[p] == last)
                    ext->nodes[i].port_peer_node[p] = (int16_t)node_idx;
    }
    ext->node_count--;
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
}

static int ship_connect_one(uint32_t slot, int na, int nb, int dir_a, int dir_b,
                             uint8_t kind) {
    return edge_add(slot, na, dir_a, nb, dir_b, kind) >= 0 ? 1 : 0;
}

static int ship_connect_both(uint32_t slot, int na, int nb,
                              int walk_dir_a, int walk_dir_b,
                              int struct_dir_a, int struct_dir_b) {
    int ok_a = edge_add(slot, na, walk_dir_a, nb, walk_dir_b, SHIP_EDGE_WALKABLE) >= 0;
    int ok_b = edge_add(slot, na, struct_dir_a, nb, struct_dir_b, SHIP_EDGE_STRUCTURAL) >= 0;
    return ok_a || ok_b;
}

static int ship_find_node_with_prop(uint32_t slot, uint32_t prop) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    for (int i = 0; i < ext->node_count; i++)
        if (ext->nodes[i].props_mask & prop) return i;
    return -1;
}

static int ship_has_prop(uint32_t slot, uint32_t prop) {
    return ship_find_node_with_prop(slot, prop) >= 0;
}

static int ship_count_prop(uint32_t slot, uint32_t prop) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return 0;
    int n = 0;
    for (int i = 0; i < ext->node_count; i++)
        if (ext->nodes[i].props_mask & prop) n++;
    return n;
}

static int ship_count_comp(uint32_t slot, uint32_t kind) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return 0;
    int n = 0;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* nd = &ext->nodes[i];
        for (int k = 0; k < nd->comp_ref_count; k++) {
            uint32_t c = (uint32_t)nd->comp_refs[k];
            ComponentData* cd = (ComponentData*)entity_side_ptr(c);
            if (cd && cd->kind == kind && cd->status != 2) n++;
        }
    }
    return n;
}

static int ship_has_comp(uint32_t slot, uint32_t kind) {
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (sd && kind < (uint32_t)COMP_COUNT &&
        sd->components_slot[kind] != UINT32_MAX) {
        if (entity_alive(sd->components_slot[kind])) return 1;
    }
    return ship_count_comp(slot, kind) > 0;
}

static int ship_find_node_with_comp(uint32_t slot, uint32_t kind) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        for (int k = 0; k < n->comp_ref_count; k++) {
            uint32_t c = (uint32_t)n->comp_refs[k];
            ComponentData* cd = (ComponentData*)entity_side_ptr(c);
            if (cd && cd->kind == kind && cd->status != 2) return i;
        }
    }
    return -1;
}

static int ship_find_central_walkable(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    V3 sum = v3zero();
    int count = 0;
    for (int i = 0; i < ext->node_count; i++) {
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        sum = v3add(sum, ext->nodes[i].pos_local);
        count++;
    }
    if (count == 0) return -1;
    V3 centroid = v3mul(sum, 1.f / (float)count);
    int best = -1;
    float best_d2 = 1e30f;
    for (int i = 0; i < ext->node_count; i++) {
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        float d2 = v3lensq(v3sub(ext->nodes[i].pos_local, centroid));
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    return best;
}

static int ship_find_room_rear(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    int best = -1;
    float best_z = -1e30f;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        if (!(n->props_mask & NODE_PROP_PRESSURIZED)) continue;
        if (n->pos_local.z > best_z) {
            best_z = n->pos_local.z;
            best = i;
        }
    }
    return best;
}

static int node_find_walkable_nearest(const ShipDataExt* ext, V3 pos) {
    if (!ext) return -1;
    int best = -1;
    float best_d2 = 1e30f;
    for (int i = 0; i < ext->node_count; i++) {
        const ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        float d2 = v3lensq(v3sub(n->pos_local, pos));
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    return best;
}

static void ship_update_vectors(uint32_t slot, V3* fwd, V3* right) {
    Thing* t = entity_get(slot);
    if (!t) {
        if (fwd)   *fwd   = v3(0, 0, 1);
        if (right) *right = v3(1, 0, 0);
        return;
    }
    float cy = cosf(t->rot), sy = sinf(t->rot);
    float cp = cosf(ENT_F(t, 24)), sp = sinf(ENT_F(t, 24));
    if (fwd)   *fwd   = v3(sy * cp, sp, -cy * cp);
    if (right) *right = v3(cy, 0.f, sy);
}

static void ship_cache_transform_if_dirty(uint32_t slot, const Thing* t) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || !t) return;
    float pitch = ENT_F(t, 24);
    uint32_t ha, hb;
    memcpy(&ha, &t->rot, 4);
    memcpy(&hb, &pitch, 4);
    uint32_t rh = hash_combine(ha, hb);
    if (ext->rot_hash == rh) return;
    float cy = cosf(t->rot),   sy = sinf(t->rot);
    float cp = cosf(pitch),    sp = sinf(pitch);
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        V3 lp = n->pos_local;
        float py = lp.y * cp - lp.z * sp;
        float pz = lp.y * sp + lp.z * cp;
        float wx = lp.x * cy + pz * sy;
        float wz = -lp.x * sy + pz * cy;
        ext->node_cached_offset[i] = v3(wx, py, wz);
        V3 h = n->half_ext;
        float* m = ext->node_cached_base[i];
        m[0]  =  cy * h.x;      m[1]  = 0;             m[2]  =  sy * h.x;      m[3]  = 0;
        m[4]  = -sy * sp * h.y; m[5]  =  cp * h.y;     m[6]  =  cy * sp * h.y; m[7]  = 0;
        m[8]  = -sy * cp * h.z; m[9]  = -sp * h.z;     m[10] =  cy * cp * h.z; m[11] = 0;
        m[12] = 0;              m[13] = 0;             m[14] = 0;              m[15] = 1.f;
    }
    Mat4* R = &ext->ship_rot_cache;
    (*R)[0]  =  cy;      (*R)[1]  = 0;   (*R)[2]  =  sy;      (*R)[3]  = 0;
    (*R)[4]  = -sy * sp; (*R)[5]  =  cp; (*R)[6]  =  cy * sp; (*R)[7]  = 0;
    (*R)[8]  = -sy * cp; (*R)[9]  = -sp; (*R)[10] =  cy * cp; (*R)[11] = 0;
    (*R)[12] = 0;        (*R)[13] = 0;   (*R)[14] = 0;        (*R)[15] = 1.f;
    ext->rot_hash = rh;
}

static V3 ship_node_world_pos(uint32_t slot, int node_idx) {
    ShipDataExt* ext = ship_ext(slot);
    Thing* t = entity_get(slot);
    if (!ext || !t || node_idx < 0 || node_idx >= ext->node_count)
        return v3zero();
    ship_cache_transform_if_dirty(slot, t);
    return v3add(t->pos, ext->node_cached_offset[node_idx]);
}

static uint32_t component_spawn(uint32_t ship_slot, uint32_t kind, float hp) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_COMPONENT;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_HUB;
    t.radius = 0.5f;
    t.hp = t.maxhp = hp;
    t.mass = (kind == COMP_HULL) ? 20.f : 5.f;
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    ComponentData* cd = (ComponentData*)entity_attach_side(slot, SD_COMPONENT);
    if (!cd) { entity_destroy(slot); return UINT32_MAX; }
    cd->kind = kind;
    cd->hp = cd->maxhp = hp;
    thing_add_child(ship_slot, slot);
    return slot;
}

static void component_apply_damage(uint32_t ship_slot, uint32_t comp_idx,
                                    float dmg, uint32_t dtype) {
    (void)dtype;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd || comp_idx >= COMP_COUNT) return;
    uint32_t cslot = sd->components_slot[comp_idx];
    ComponentData* cd = (ComponentData*)entity_side_ptr(cslot);
    if (!cd || cd->status == 2) return;
    cd->hp -= dmg;
    if (cd->hp <= 0.f) { cd->hp = 0.f; cd->status = 2; }
    else if (cd->hp < cd->maxhp * 0.5f) cd->status = 1;
    else if (cd->status == 1 && cd->hp >= cd->maxhp * 0.5f) cd->status = 0;
}

static void component_spread_damage_full(uint32_t ship_slot, float dmg, uint32_t dtype,
                                          int hit_node, int apply_aff);

static void component_spread_damage(uint32_t ship_slot, float dmg, uint32_t dtype) {
    component_spread_damage_full(ship_slot, dmg, dtype, -1, 1);
}

static void component_spread_damage_full(uint32_t ship_slot, float dmg, uint32_t dtype,
                                          int hit_node, int apply_aff) {
    Thing* ship = entity_get(ship_slot);
    if (!ship || (ship->flags & ENT_FLAG_MARKED_DEAD)) return;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return;
    ShipDataExt* ext = ship_ext(ship_slot);

    float resist = 0.f;
    if (ext && hit_node >= 0 && hit_node < ext->node_count) {
        resist = (float)ext->nodes[hit_node].base_resist[dtype] / 100.f;
    } else {
        resist = resistance_for_cached(ship_slot, dtype);
    }
    dmg = dmg * (1.f - resist);
    if (dmg <= 0.f) return;

    if (ext && hit_node >= 0 && hit_node < ext->node_count) {
        ShipNode* n = &ext->nodes[hit_node];
        for (int k = 0; k < n->armor_count && dmg > 0.f; k++) {
            ArmorLayer* a = &ext->armor[n->armor_refs[k]];
            if (a->hp <= 0.f) continue;
            float ar = (float)a->resist[dtype] / 100.f;
            float applied = dmg * (1.f - ar);
            a->hp -= applied;
            if (a->hp < 0.f) { dmg = -a->hp; a->hp = 0.f; }
            else             { dmg = 0.f; }
        }
    }
    if (dmg <= 0.f) return;

    component_apply_damage(ship_slot, COMP_HULL, dmg * 0.5f, dtype);
    float rest = dmg * 0.5f;
    int alive_other = 0;
    for (uint32_t i = 1; i < COMP_COUNT; i++) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
        if (cd && cd->status != 2) alive_other++;
    }
    if (alive_other > 0) {
        for (uint32_t i = 1; i < COMP_COUNT; i++) {
            ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
            if (!cd || cd->status == 2) continue;
            component_apply_damage(ship_slot, i, rest / (float)alive_other, dtype);
        }
    } else {
        component_apply_damage(ship_slot, COMP_HULL, rest, dtype);
    }

    if (apply_aff && dmg >= AFFLICTION_MIN_DAMAGE) {
        uint32_t hull_slot = sd->components_slot[COMP_HULL];
        if (entity_alive(hull_slot)) {
            if (dtype == DMG_CHEM)
                affliction_apply(hull_slot, AFF_POISON, 20.f, 3.f, dmg * 0.20f);
            else if (dtype == DMG_HEAT)
                affliction_apply(hull_slot, AFF_BURN, 30.f, 4.f, dmg * 0.25f);
            else if (dtype == DMG_EXOTIC)
                affliction_apply(hull_slot, AFF_RADIATION, 15.f, 5.f, dmg * 0.15f);
        }
    }
}

static int ship_check_death(uint32_t ship_slot) {
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return 1;
    ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[COMP_HULL]);
    if (!cd) return 1;
    return (cd->status == 2) ? 1 : 0;
}

static void node_attach_comp(uint32_t slot, int node_idx, uint32_t comp_slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    if (!entity_alive(comp_slot)) return;
    ShipNode* n = &ext->nodes[node_idx];
    if (n->comp_ref_count >= SHIP_MAX_COMP_PER_NODE) return;
    for (int i = 0; i < n->comp_ref_count; i++)
        if ((uint32_t)n->comp_refs[i] == comp_slot) return;
    n->comp_refs[n->comp_ref_count++] = (int16_t)comp_slot;
    dirty_invalidate(slot, SHIP_DIRTY_COMPONENT | SHIP_DIRTY_MASS);
}

static void node_detach_comp(uint32_t slot, int node_idx, uint32_t comp_slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    ShipNode* n = &ext->nodes[node_idx];
    for (int i = 0; i < n->comp_ref_count; i++) {
        if ((uint32_t)n->comp_refs[i] != comp_slot) continue;
        n->comp_refs[i] = n->comp_refs[n->comp_ref_count - 1];
        n->comp_ref_count--;
        dirty_invalidate(slot, SHIP_DIRTY_COMPONENT | SHIP_DIRTY_MASS);
        return;
    }
}

static void node_attach_armor(uint32_t slot, int node_idx, uint16_t mat_id) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    if (ext->armor_count >= SHIP_MAX_ARMOR_TOTAL) return;
    ShipNode* n = &ext->nodes[node_idx];
    if (n->armor_count >= SHIP_MAX_ARMOR_PER_NODE) return;
    int a_idx = ext->armor_count++;
    ArmorLayer* a = &ext->armor[a_idx];
    memset(a, 0, sizeof(*a));
    a->material_id = mat_id;
    a->retrofit_time = (uint32_t)time_get();
    a->retrofit_layer = n->armor_count;
    armor_derive_phys(a, n);
    n->armor_refs[n->armor_count++] = (int16_t)a_idx;
    dirty_invalidate(slot, SHIP_DIRTY_ARMOR);
}

static void node_remove_armor(uint32_t slot, int node_idx, int layer_idx) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    ShipNode* n = &ext->nodes[node_idx];
    if (layer_idx < 0 || layer_idx >= n->armor_count) return;
    for (int i = layer_idx; i < n->armor_count - 1; i++)
        n->armor_refs[i] = n->armor_refs[i + 1];
    n->armor_count--;
    dirty_invalidate(slot, SHIP_DIRTY_ARMOR);
}

static int node_breach(uint32_t slot, int node_idx) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return 0;
    ShipNode* n = &ext->nodes[node_idx];
    n->props_mask |= NODE_PROP_BREACHED;
    n->damage_visual = 3;
    dirty_invalidate(slot, SHIP_DIRTY_TOPO);
    return 1;
}

static int ship_add_airlock(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    int rear = ship_find_room_rear(slot);
    if (rear < 0) rear = ship_find_central_walkable(slot);
    if (rear < 0) return -1;
    ShipNode* rn = &ext->nodes[rear];
    V3 pos = v3add(rn->pos_local, v3(0.f, 0.f, rn->half_ext.z + 0.6f));
    V3 hx = v3(0.4f, 0.5f, 0.4f);
    uint16_t mat = mat_pool_get(hash3_u32(slot, 0xA1u, 0xC0u));
    int airlock = node_add(slot,
        NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_EJECT,
        pos, hx, mat);
    if (airlock < 0) return -1;
    edge_add(slot, rear, PORT_PZ, airlock, PORT_NZ, SHIP_EDGE_WALKABLE);
    edge_add(slot, rear, PORT_PZ, airlock, PORT_NZ, SHIP_EDGE_STRUCTURAL);
    return airlock;
}

static void computer_aggregate(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    uint32_t cores = 0, tier_max = 0, count = 0;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        for (int j = 0; j < n->comp_ref_count; j++) {
            uint32_t c = (uint32_t)n->comp_refs[j];
            ComponentData* cd = (ComponentData*)entity_side_ptr(c);
            if (!cd || cd->kind != COMP_COMPUTER || cd->status == 2) continue;
            Thing* ct = entity_get(c);
            if (!ct) continue;
            cores += ENT_I(ct, 0);
            uint32_t t = ENT_I(ct, 1);
            if (t > tier_max) tier_max = t;
            count++;
        }
    }
    ext->computer_cores_total = cores;
    ext->computer_tier_max    = tier_max;
    ext->computer_count       = count;
}

static int computer_attach(uint32_t slot, int room_idx, uint32_t seed) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || room_idx < 0 || room_idx >= ext->node_count) return 0;
    ShipNode* n = &ext->nodes[room_idx];
    if (!(n->props_mask & NODE_PROP_COMPUTER_ROOM)) return 0;
    if (n->computer_slot_used >= n->computer_slot_count) return 0;
    uint32_t comp_slot = component_spawn(slot, COMP_COMPUTER, 40.f);
    if (comp_slot == UINT32_MAX) return 0;
    uint32_t h = hash_u32(seed);
    uint32_t tier = h & 0x3u;
    if (((h >> 4) & 0xFFu) < 20u) tier++;
    if (tier > 5) tier = 5;
    uint32_t cores = (1u << tier) + ((h >> 8) & 0x3u);
    Thing* ct = entity_get(comp_slot);
    if (ct) {
        ENT_SET_I(ct, 0, cores);
        ENT_SET_I(ct, 1, tier);
    }
    node_attach_comp(slot, room_idx, comp_slot);
    n->computer_refs[n->computer_slot_used++] = (int16_t)comp_slot;
    computer_aggregate(slot);
    dirty_invalidate(slot, SHIP_DIRTY_COMPONENT);
    return 1;
}

static void computer_detach(uint32_t slot, uint32_t comp_slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_COMPUTER_ROOM)) continue;
        for (int j = 0; j < n->computer_slot_used; j++) {
            if ((uint32_t)n->computer_refs[j] != comp_slot) continue;
            for (int k = j; k < n->computer_slot_used - 1; k++)
                n->computer_refs[k] = n->computer_refs[k + 1];
            n->computer_slot_used--;
            n->computer_refs[n->computer_slot_used] = -1;
            node_detach_comp(slot, i, comp_slot);
            if (entity_alive(comp_slot)) entity_mark_dead(comp_slot);
            computer_aggregate(slot);
            dirty_invalidate(slot, SHIP_DIRTY_COMPONENT);
            return;
        }
    }
}

static int computer_upgrade_cores(uint32_t slot, uint32_t comp_slot, uint32_t add) {
    if (!entity_alive(comp_slot)) return 0;
    ComponentData* cd = (ComponentData*)entity_side_ptr(comp_slot);
    if (!cd || cd->kind != COMP_COMPUTER) return 0;
    Thing* ct = entity_get(comp_slot);
    if (!ct) return 0;
    uint32_t cur = ENT_I(ct, 0);
    const uint32_t cap = 64u;
    if (cur >= cap) return 0;
    if (cur + add > cap) add = cap - cur;
    ENT_SET_I(ct, 0, cur + add);
    computer_aggregate(slot);
    return 1;
}

static int computer_upgrade_tier(uint32_t slot, uint32_t comp_slot) {
    if (!entity_alive(comp_slot)) return 0;
    ComponentData* cd = (ComponentData*)entity_side_ptr(comp_slot);
    if (!cd || cd->kind != COMP_COMPUTER) return 0;
    Thing* ct = entity_get(comp_slot);
    if (!ct) return 0;
    uint32_t cur = ENT_I(ct, 1);
    if (cur >= 5u) return 0;
    ENT_SET_I(ct, 1, cur + 1u);
    computer_aggregate(slot);
    return 1;
}

static void cache_rebuild_comp_index(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    for (int k = 0; k < 8; k++) ext->count_by_comp[k] = 0;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        for (int j = 0; j < n->comp_ref_count; j++) {
            uint32_t c = (uint32_t)n->comp_refs[j];
            ComponentData* cd = (ComponentData*)entity_side_ptr(c);
            if (!cd) continue;
            uint32_t k = cd->kind;
            if (k >= 8) continue;
            if (ext->count_by_comp[k] >= SHIP_MAX_COMP_INDEX) continue;
            ext->pieces_by_comp[k][ext->count_by_comp[k]++] = (int16_t)c;
        }
    }
}

static void cache_rebuild_stress(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    float total_mass = 0.f;
    for (int i = 0; i < ext->node_count; i++) total_mass += ext->nodes[i].mass;
    if (total_mass < 0.001f) total_mass = 0.001f;
    for (int e = 0; e < ext->edge_count; e++) {
        ShipEdge* ed = &ext->edges[e];
        if (ed->kind != SHIP_EDGE_STRUCTURAL && ed->kind != SHIP_EDGE_WALKABLE)
            continue;
        float mass_a = 0.f;
        {
            uint8_t visited[SHIP_MAX_NODES];
            memset(visited, 0, sizeof(visited));
            int stack[SHIP_MAX_NODES];
            int sp = 0;
            if (ed->node_a >= 0 && ed->node_a < SHIP_MAX_NODES) {
                stack[sp++] = ed->node_a;
                visited[ed->node_a] = 1;
            }
            if (ed->node_b >= 0 && ed->node_b < SHIP_MAX_NODES)
                visited[ed->node_b] = 1;
            while (sp > 0) {
                int cur = stack[--sp];
                mass_a += ext->nodes[cur].mass;
                for (int i = 0; i < ext->edge_count; i++) {
                    ShipEdge* e2 = &ext->edges[i];
                    if (e2 == ed) continue;
                    if (e2->kind != SHIP_EDGE_STRUCTURAL &&
                        e2->kind != SHIP_EDGE_WALKABLE) continue;
                    int nb = edge_other_node(e2, cur);
                    if (nb < 0 || nb >= ext->node_count || visited[nb]) continue;
                    visited[nb] = 1;
                    if (sp < SHIP_MAX_NODES) stack[sp++] = nb;
                }
            }
        }
        float mass_b = total_mass - mass_a;
        float min_m = (mass_a < mass_b) ? mass_a : mass_b;
        ed->current_stress = min_m * 100.f;
    }
}

static void cache_rebuild_floor_grid(ShipDataExt* ext) {
    if (!ext) return;
    FloorGrid* fg = &ext->floor_grid;
    memset(fg, 0, sizeof(*fg));
    float min_x = 1e30f, min_z = 1e30f;
    int any = 0;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        if (n->pos_local.x - n->half_ext.x < min_x)
            min_x = n->pos_local.x - n->half_ext.x;
        if (n->pos_local.z - n->half_ext.z < min_z)
            min_z = n->pos_local.z - n->half_ext.z;
        any = 1;
    }
    if (!any) return;
    fg->origin_local = v3(min_x - 0.1f, 0.f, min_z - 0.1f);
    fg->cell_size = FLOOR_GRID_CELL;
    fg->enabled = 1;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        float wx0 = n->pos_local.x - n->half_ext.x;
        float wz0 = n->pos_local.z - n->half_ext.z;
        float wx1 = n->pos_local.x + n->half_ext.x;
        float wz1 = n->pos_local.z + n->half_ext.z;
        int gx0 = (int)floorf((wx0 - fg->origin_local.x) / fg->cell_size);
        int gz0 = (int)floorf((wz0 - fg->origin_local.z) / fg->cell_size);
        int gx1 = (int)floorf((wx1 - fg->origin_local.x) / fg->cell_size);
        int gz1 = (int)floorf((wz1 - fg->origin_local.z) / fg->cell_size);
        if (gx0 < 0) gx0 = 0;
        if (gz0 < 0) gz0 = 0;
        if (gx1 >= FLOOR_GRID_N) gx1 = FLOOR_GRID_N - 1;
        if (gz1 >= FLOOR_GRID_N) gz1 = FLOOR_GRID_N - 1;
        for (int z = gz0; z <= gz1; z++)
            for (int x = gx0; x <= gx1; x++)
                fg->cells[z][x] = 1;
    }
}

static void cache_rebuild_all(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    uint32_t d = ext->dirty_flags;
    if (d & SHIP_DIRTY_TOPO) {
        for (int i = 0; i < 16; i++) ext->categories[i].count = 0;
        static const uint32_t cat_props[16] = {
            NODE_PROP_WALKABLE, NODE_PROP_PRESSURIZED, NODE_PROP_COCKPIT,
            NODE_PROP_THRUSTER, NODE_PROP_WEAPON_MOUNT, NODE_PROP_COMPUTER_ROOM,
            NODE_PROP_EJECT, NODE_PROP_DOCKING, NODE_PROP_REACTOR,
            NODE_PROP_BRIDGE, NODE_PROP_LAB, NODE_PROP_STORAGE,
            NODE_PROP_EXTERIOR, NODE_PROP_INSULATED, NODE_PROP_BREACHED, 0u
        };
        for (int i = 0; i < ext->node_count; i++) {
            uint32_t pm = ext->nodes[i].props_mask;
            for (int c = 0; c < 16; c++) {
                if (cat_props[c] == 0u) continue;
                if (!(pm & cat_props[c])) continue;
                NodeList* lst = &ext->categories[c];
                if (lst->count < SHIP_MAX_NODES)
                    lst->pieces[lst->count++] = (int16_t)i;
            }
        }
        for (int i = 0; i < ext->node_count; i++)
            for (int p = 0; p < 6; p++)
                ext->nodes[i].port_peer_node[p] = -1;
        for (int e = 0; e < ext->edge_count; e++) {
            ShipEdge* ed = &ext->edges[e];
            if (ed->node_a >= 0 && ed->node_a < ext->node_count)
                ext->nodes[ed->node_a].port_peer_node[ed->port_a] = ed->node_b;
            if (ed->node_b >= 0 && ed->node_b < ext->node_count)
                ext->nodes[ed->node_b].port_peer_node[ed->port_b] = ed->node_a;
        }
        cache_rebuild_floor_grid(ext);
        cache_rebuild_comp_index(slot);
        cache_rebuild_stress(slot);
    } else {
        if (d & SHIP_DIRTY_COMPONENT) cache_rebuild_comp_index(slot);
        if (d & SHIP_DIRTY_MASS)      cache_rebuild_stress(slot);
    }
    ext->dirty_flags = 0;
}

static float pf_heuristic(const ShipNode* a, const ShipNode* b) {
    return fabsf(a->pos_local.x - b->pos_local.x) +
           fabsf(a->pos_local.y - b->pos_local.y) +
           fabsf(a->pos_local.z - b->pos_local.z);
}

static int path_find(uint32_t slot, int from, int to, int* out, int max_out,
                     int use_heuristic) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || from < 0 || to < 0 || !out || max_out <= 0) return 0;
    if (from >= ext->node_count || to >= ext->node_count) return 0;
    if (from == to) { out[0] = from; return 1; }

    float g[SHIP_MAX_NODES];
    int   came[SHIP_MAX_NODES];
    uint8_t closed[SHIP_MAX_NODES], open[SHIP_MAX_NODES];
    for (int i = 0; i < SHIP_MAX_NODES; i++) {
        g[i] = 1e30f; came[i] = -1; closed[i] = 0; open[i] = 0;
    }
    g[from] = 0.f;
    open[from] = 1;

    for (int iter = 0; iter < SHIP_MAX_NODES * 4; iter++) {
        int cur = -1;
        float min_f = 1e30f;
        for (int i = 0; i < ext->node_count; i++) {
            if (!open[i] || closed[i]) continue;
            float f = g[i] + (use_heuristic
                ? pf_heuristic(&ext->nodes[i], &ext->nodes[to]) : 0.f);
            if (f < min_f) { min_f = f; cur = i; }
        }
        if (cur < 0) break;
        if (cur == to) break;
        open[cur] = 0;
        closed[cur] = 1;
        for (int e = 0; e < ext->edge_count; e++) {
            ShipEdge* ed = &ext->edges[e];
            if (ed->kind != SHIP_EDGE_WALKABLE) continue;
            int nb = edge_other_node(ed, cur);
            if (nb < 0 || nb >= ext->node_count || closed[nb]) continue;
            float tg = g[cur] + 1.f;
            if (tg >= g[nb]) continue;
            g[nb] = tg;
            came[nb] = cur;
            open[nb] = 1;
        }
    }
    if (came[to] < 0 && to != from) return 0;

    int tmp[SHIP_MAX_NODES];
    int tl = 0, cur = to;
    while (cur != -1 && tl < SHIP_MAX_NODES) {
        tmp[tl++] = cur;
        if (cur == from) break;
        cur = came[cur];
    }
    int out_n = 0;
    for (int i = tl - 1; i >= 0 && out_n < max_out; i--)
        out[out_n++] = tmp[i];
    return out_n;
}

static int pf_path(uint32_t slot, int start, int goal, int* out, int max_out) {
    return path_find(slot, start, goal, out, max_out, 1);
}

static int graph_path(uint32_t slot, int from, int to, int* out, int max) {
    return path_find(slot, from, to, out, max, 0);
}

static int pf_nearest_walkable(uint32_t slot, V3 local, float max_dist) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    int best = -1;
    float best_d2 = max_dist * max_dist;
    for (int i = 0; i < ext->node_count; i++) {
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        float d2 = v3lensq(v3sub(ext->nodes[i].pos_local, local));
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    return best;
}

static int pf_find_reachable_prop(uint32_t slot, int from_node, uint32_t prop,
                                    int* out_path, int max_out) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || from_node < 0 || from_node >= ext->node_count) return 0;
    int cand[SHIP_MAX_NODES];
    float dist[SHIP_MAX_NODES];
    int nc = 0;
    for (int i = 0; i < ext->node_count && nc < SHIP_MAX_NODES; i++) {
        if (!(ext->nodes[i].props_mask & prop)) continue;
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        cand[nc] = i;
        dist[nc] = pf_heuristic(&ext->nodes[from_node], &ext->nodes[i]);
        nc++;
    }
    for (int i = 1; i < nc; i++) {
        int ki = cand[i]; float kd = dist[i];
        int j = i - 1;
        while (j >= 0 && dist[j] > kd) {
            cand[j + 1] = cand[j];
            dist[j + 1] = dist[j];
            j--;
        }
        cand[j + 1] = ki; dist[j + 1] = kd;
    }
    for (int k = 0; k < nc; k++) {
        int n = pf_path(slot, from_node, cand[k], out_path, max_out);
        if (n >= 2) return n;
    }
    return 0;
}

static int graph_traverse(uint32_t slot, int start, int* out, int max) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || start < 0 || start >= ext->node_count || !out || max <= 0) return 0;
    uint8_t visited[SHIP_MAX_NODES];
    memset(visited, 0, sizeof(visited));
    int stack[SHIP_MAX_NODES];
    int sp = 0;
    stack[sp++] = start;
    visited[start] = 1;
    int count = 0;
    while (sp > 0 && count < max) {
        int cur = stack[--sp];
        out[count++] = cur;
        for (int i = 0; i < ext->edge_count; i++) {
            ShipEdge* e = &ext->edges[i];
            if (e->kind != SHIP_EDGE_STRUCTURAL) continue;
            int nb = edge_other_node(e, cur);
            if (nb < 0 || nb >= ext->node_count || visited[nb]) continue;
            visited[nb] = 1;
            if (sp < SHIP_MAX_NODES) stack[sp++] = nb;
        }
    }
    return count;
}

static int graph_components(uint32_t slot, int* out_marker, int* out_count) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || !out_marker || !out_count) return 0;
    for (int i = 0; i < ext->node_count; i++) out_marker[i] = -1;
    *out_count = 0;
    int buf[SHIP_MAX_NODES];
    for (int i = 0; i < ext->node_count; i++) {
        if (out_marker[i] >= 0) continue;
        int cid = *out_count;
        int n = graph_traverse(slot, i, buf, SHIP_MAX_NODES);
        for (int k = 0; k < n; k++) out_marker[buf[k]] = cid;
        (*out_count)++;
    }
    return *out_count;
}

static V3 world_dir_to_local(uint32_t slot, V3 wd) {
    Thing* ship = entity_get(slot);
    if (!ship) return v3zero();
    V3 fwd, right;
    ship_update_vectors(slot, &fwd, &right);
    V3 up = v3norm(v3cross(right, fwd));
    return v3(v3dot(wd, right), v3dot(wd, up), -v3dot(wd, fwd));
}

static V3 local_to_world_dir(uint32_t slot, V3 ld) {
    Thing* ship = entity_get(slot);
    if (!ship) return v3zero();
    V3 fwd, right;
    ship_update_vectors(slot, &fwd, &right);
    V3 up = v3norm(v3cross(right, fwd));
    return v3add(v3add(v3mul(right, ld.x), v3mul(up, ld.y)),
                  v3mul(fwd, -ld.z));
}

static V3 local_to_world_pos(uint32_t slot, V3 lp) {
    Thing* ship = entity_get(slot);
    if (!ship) return v3zero();
    return v3add(ship->pos, local_to_world_dir(slot, lp));
}

static float floor_y_at(uint32_t slot, float lx, float lz, int* out_has) {
    ShipDataExt* ext = ship_ext(slot);
    if (out_has) *out_has = 0;
    if (!ext) return 0.f;
    float best_y = -1e30f;
    int found = 0;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        float dx = lx - n->pos_local.x;
        float dz = lz - n->pos_local.z;
        if (fabsf(dx) > n->half_ext.x) continue;
        if (fabsf(dz) > n->half_ext.z) continue;
        float fy = n->pos_local.y - n->half_ext.y;
        if (fy > best_y) { best_y = fy; found = 1; }
    }
    if (out_has) *out_has = found;
    return found ? best_y : 0.f;
}

static int walker_inside_any_walkable(const ShipDataExt* ext, V3 pos, float radius) {
    if (!ext) return 0;
    for (int i = 0; i < ext->node_count; i++) {
        const ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        float dx = pos.x - n->pos_local.x;
        float dy = pos.y - n->pos_local.y;
        float dz = pos.z - n->pos_local.z;
        if (fabsf(dx) <= n->half_ext.x + radius &&
            fabsf(dy) <= n->half_ext.y + radius &&
            fabsf(dz) <= n->half_ext.z + radius) return 1;
    }
    return 0;
}

static int walker_collide(uint32_t slot, V3 cur_pos, V3 new_pos, V3* out_pos) {
    if (!out_pos) return 0;
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) { *out_pos = new_pos; return 0; }
    const float PR = 0.10f;

    if (walker_inside_any_walkable(ext, new_pos, PR)) {
        *out_pos = new_pos; return 0;
    }
    V3 try_x = v3(new_pos.x, cur_pos.y, cur_pos.z);
    if (walker_inside_any_walkable(ext, try_x, PR)) {
        *out_pos = try_x; return 1;
    }
    V3 try_z = v3(cur_pos.x, cur_pos.y, new_pos.z);
    if (walker_inside_any_walkable(ext, try_z, PR)) {
        *out_pos = try_z; return 1;
    }
    int best = node_find_walkable_nearest(ext, new_pos);
    if (best < 0) { *out_pos = new_pos; return 0; }
    ShipNode* n = &ext->nodes[best];
    float dx = new_pos.x - n->pos_local.x;
    float dy = new_pos.y - n->pos_local.y;
    float dz = new_pos.z - n->pos_local.z;
    float ax = n->half_ext.x + PR;
    float ay = n->half_ext.y + PR;
    float az = n->half_ext.z + PR;
    if (dx >  ax) dx =  ax; if (dx < -ax) dx = -ax;
    if (dy >  ay) dy =  ay; if (dy < -ay) dy = -ay;
    if (dz >  az) dz =  az; if (dz < -az) dz = -az;
    *out_pos = v3(n->pos_local.x + dx, n->pos_local.y + dy, n->pos_local.z + dz);
    return 1;
}

static void walker_reset_to_node(WalkerState* w, uint32_t slot, int node_idx) {
    ShipDataExt* ext = ship_ext(slot);
    Thing* ship = entity_get(slot);
    if (!w || !ext || !ship) return;
    if (node_idx < 0 || node_idx >= ext->node_count) return;
    ShipNode* n = &ext->nodes[node_idx];
    if (!(n->props_mask & NODE_PROP_WALKABLE)) return;
    float fy = n->pos_local.y - n->half_ext.y;
    w->pos_local    = v3(n->pos_local.x, fy, n->pos_local.z);
    w->vel_local    = v3zero();
    w->vel_y        = 0.f;
    w->grounded     = 1;
    w->eye_height   = WALKER_EYE_STAND;
    w->yaw          = 0.f;
    w->pitch        = 0.f;
    w->bob_phase    = 0.f;
    w->bob_amp      = 0.f;
    w->crouch_blend = 0.f;
    w->hurt_shake   = 0.f;
    w->jumping      = 0;
    w->aiming       = 0;
    w->fire_cd      = 0.f;
    w->last_ship_vel_world = ship->vel;
    w->last_ship_rot       = ship->rot;
}

static int node_overlaps_any(uint32_t ship, V3 pos, float radius, int ignore_idx) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext) return 0;
    for (int i = 0; i < ext->node_count; i++) {
        if (i == ignore_idx) continue;
        ShipNode* n = &ext->nodes[i];
        float d = v3dist(n->pos_local, pos);
        float lim = (radius + fmaxf(n->half_ext.x,
                          fmaxf(n->half_ext.y, n->half_ext.z))) * 0.9f;
        if (d < lim) return 1;
    }
    return 0;
}

static int node_add_fuselage(uint32_t ship, int node_a, int node_b) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext || ext->node_count >= SHIP_MAX_NODES) return -1;
    if (node_a < 0 || node_a >= ext->node_count) return -1;
    if (node_b < 0 || node_b >= ext->node_count) return -1;
    if (node_a == node_b) return -1;
    ShipNode* a = &ext->nodes[node_a];
    ShipNode* b = &ext->nodes[node_b];
    V3 center = v3mul(v3add(a->pos_local, b->pos_local), 0.5f);
    float dist = v3dist(a->pos_local, b->pos_local);
    if (dist < 0.01f) return -1;
    V3 half = v3(fminf(a->half_ext.x, b->half_ext.x) * 0.8f,
                  fminf(a->half_ext.y, b->half_ext.y) * 0.8f,
                  dist * 0.5f);
    if (half.z < 0.3f) half.z = 0.3f;
    uint16_t mat = (uint16_t)((a->material_id + b->material_id) / 2);
    uint32_t props = NODE_PROP_PRESSURIZED;
    if ((a->props_mask & NODE_PROP_WALKABLE) &&
        (b->props_mask & NODE_PROP_WALKABLE))
        props |= NODE_PROP_WALKABLE;
    if ((a->props_mask & NODE_PROP_EXTERIOR) ||
        (b->props_mask & NODE_PROP_EXTERIOR))
        props |= NODE_PROP_EXTERIOR;
    return node_add(ship, props, center, half, mat);
}

static void ship_ensure_fuselage(uint32_t ship) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext) return;
    int snap_a[SHIP_MAX_EDGES], snap_b[SHIP_MAX_EDGES];
    uint8_t snap_kind[SHIP_MAX_EDGES];
    int snap_n = 0;
    for (int i = 0; i < ext->edge_count && snap_n < SHIP_MAX_EDGES; i++) {
        ShipEdge* e = &ext->edges[i];
        if (e->node_a < 0 || e->node_b < 0) continue;
        snap_a[snap_n] = e->node_a;
        snap_b[snap_n] = e->node_b;
        snap_kind[snap_n] = e->kind;
        snap_n++;
    }
    for (int i = 0; i < snap_n; i++) {
        int na = snap_a[i], nb = snap_b[i];
        if (na >= ext->node_count || nb >= ext->node_count) continue;
        if (snap_kind[i] != SHIP_EDGE_STRUCTURAL &&
            snap_kind[i] != SHIP_EDGE_WALKABLE) continue;
        ShipNode* a = &ext->nodes[na];
        ShipNode* b = &ext->nodes[nb];
        float gap = v3dist(a->pos_local, b->pos_local)
                    - (a->half_ext.z + b->half_ext.z);
        if (gap < 0.5f) continue;
        int fus = node_add_fuselage(ship, na, nb);
        if (fus < 0) continue;
        int free_pa = -1, free_pb = -1;
        for (int p = 0; p < 6; p++)
            if (ext->nodes[na].port_edge[p] == -1) { free_pa = p; break; }
        for (int p = 0; p < 6; p++)
            if (ext->nodes[nb].port_edge[p] == -1) { free_pb = p; break; }
        if (free_pa >= 0 && free_pb >= 0) {
            edge_add(ship, na, free_pa, fus, 0, snap_kind[i]);
            edge_add(ship, nb, free_pb, fus, 1, snap_kind[i]);
        }
    }
}

static int ship_attach_fuselage_at(uint32_t ship, int base_node, int port) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext || base_node < 0 || base_node >= ext->node_count) return -1;
    if (port < 0 || port >= 6) return -1;
    if (ext->node_count >= SHIP_MAX_NODES) return -1;
    ShipNode* base = &ext->nodes[base_node];
    if (base->port_edge[port] != -1) return -1;
    V3 dir = port_normal_local(port);
    float ext_z = fmaxf(base->half_ext.z * 0.8f, 0.5f);
    V3 new_pos = v3add(base->pos_local,
                        v3mul(dir, base->half_ext.z + ext_z + 0.05f));
    V3 new_ext = v3(base->half_ext.x * 0.85f,
                     base->half_ext.y * 0.85f,
                     ext_z);
    if (node_overlaps_any(ship, new_pos, ext_z, base_node)) return -1;
    uint32_t props = NODE_PROP_PRESSURIZED;
    if (base->props_mask & NODE_PROP_WALKABLE) props |= NODE_PROP_WALKABLE;
    if (base->props_mask & NODE_PROP_EXTERIOR) props |= NODE_PROP_EXTERIOR;
    uint16_t mat = base->material_id;
    int new_idx = node_add(ship, props, new_pos, new_ext, mat);
    if (new_idx < 0) return -1;
    int opp = port_opposite(port);
    edge_add(ship, base_node, port, new_idx, opp,
              (props & NODE_PROP_WALKABLE) ? SHIP_EDGE_WALKABLE
                                             : SHIP_EDGE_STRUCTURAL);
    return new_idx;
}

static int ship_morphology_face_is_allowed(const ShipNode* n, int face) {
    if (face == PORT_PY || face == PORT_NY) {
        if (n->half_ext.y > n->half_ext.x * 1.5f) return 0;
        if (n->half_ext.y > n->half_ext.z * 1.5f) return 0;
        if (xrng_f() < 0.7f) return 0;
    }
    return 1;
}

static void ship_build_external_morphology(uint32_t ship, int node_idx) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    ShipNode* n = &ext->nodes[node_idx];
    if (!(n->props_mask & NODE_PROP_EXTERIOR)) return;
    if (node_idx >= SHIP_MAX_NODES) return;
    NodeExternalMorph* nm = &g_node_morph[node_idx];
    if (nm->seed == n->seed) return;
    nm->seed = n->seed;
    nm->block_count = 0;
    V4 mat_color = mat_get(n->material_id)->color;
    int n_blocks = 1 + (int)(xrng_u32() % 3);
    for (int i = 0; i < n_blocks && nm->block_count < 16; i++) {
        int face = (int)(xrng_u32() % 6);
        if (!ship_morphology_face_is_allowed(n, face)) continue;
        V3 normal = port_normal_local(face);
        V3 pos = v3(
            n->pos_local.x + normal.x * (n->half_ext.x + 0.05f),
            n->pos_local.y + normal.y * (n->half_ext.y + 0.05f),
            n->pos_local.z + normal.z * (n->half_ext.z + 0.05f));
        V3 scale = v3(
            n->half_ext.x * (0.3f + xrng_f() * 0.4f),
            n->half_ext.y * (0.3f + xrng_f() * 0.4f),
            n->half_ext.z * (0.3f + xrng_f() * 0.4f));
        V4 color = v4(
            mat_color.x * (0.7f + xrng_f() * 0.4f),
            mat_color.y * (0.7f + xrng_f() * 0.4f),
            mat_color.z * (0.7f + xrng_f() * 0.4f),
            1.f);
        BodyBlock* b = &nm->blocks[nm->block_count++];
        b->pos_local = pos;
        b->scale = scale;
        b->color = color;
        b->mesh = (uint8_t)(xrng_u32() % 2);
    }
}

static void ship_build_all_external(uint32_t ship) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext) return;
    for (int i = 0; i < ext->node_count; i++)
        ship_build_external_morphology(ship, i);
}

static uint32_t weapon_spawn(uint32_t ship_slot, uint32_t kind) {
    if (kind >= WEAPON_COUNT) kind = WEAPON_PULSE;
    if (!entity_alive(ship_slot)) return UINT32_MAX;
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_WEAPON;
    t.flags  = ENT_FLAG_ALIVE;
    t.radius = 0.3f;
    t.hp = t.maxhp = 20.f;
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    WeaponData* wd = (WeaponData*)entity_attach_side(slot, SD_WEAPON);
    if (!wd) { entity_destroy(slot); return UINT32_MAX; }
    const WeaponDef* d = &g_weapon_defs[kind];
    wd->kind             = kind;
    wd->cooldown_max     = d->cooldown_max;
    wd->damage           = d->damage;
    wd->projectile_speed = d->projectile_speed;
    wd->spread           = d->spread;
    wd->heat_max         = d->heat_max;
    wd->heat_per_shot    = d->heat_per_shot;
    wd->ammo_max         = d->ammo_max;
    wd->ammo_per_shot    = d->ammo_per_shot;
    wd->range            = d->range;
    wd->muzzle_offset    = v3zero();
    wd->cooldown         = 0.f;
    wd->heat             = 0.f;
    wd->ammo             = d->ammo_max;
    thing_add_child(ship_slot, slot);
    return slot;
}

static uint32_t ship_create_with_weapon(V3 pos, uint32_t preset,
                                          uint32_t weapon_kind) {
    if (weapon_kind >= WEAPON_COUNT) weapon_kind = WEAPON_PULSE;
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_SHIP;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_PHYSICS | ENT_FLAG_COLLIDE | ENT_FLAG_HUB;
    t.pos    = pos;
    t.radius = 2.5f;
    t.hp = t.maxhp = 100.f;
    t.mass   = 10.f;
    t.seed   = xrng_u32();
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    ship_ext_resize(slot + 64);
    ShipDataExt* ext = ship_ext(slot);
    if (ext) memset(ext, 0, sizeof(*ext));
    ShipData* sd = (ShipData*)entity_attach_side(slot, SD_SHIP);
    if (!sd) { entity_destroy(slot); return UINT32_MAX; }
    sd->energy = sd->energy_max = 100.f;
    sd->energy_regen = 2.f;
    sd->fuel = sd->fuel_max = 100.f;
    sd->fuel_regen = 0.5f;
    sd->fuel_consumption = 2.f;
    sd->max_speed = 150.f;
    sd->accel = 90.f;
    sd->turn_rate = 2.5f;
    sd->desloc_count = 3;
    sd->speed_sel = 5;
    sd->neutrino_sel = 5;
    sd->cargo_capacity = 60.f;
    sd->weapon_slot = UINT32_MAX;
    sd->computer_slot = UINT32_MAX;
    for (int i = 0; i < COMP_COUNT; i++) sd->components_slot[i] = UINT32_MAX;
    float chp = (preset == SHIP_PRESET_ENEMY) ? 60.f : 100.f;
    for (uint32_t i = 0; i < COMP_COUNT; i++) {
        sd->components_slot[i] = component_spawn(slot, i, chp);
        sd->comp_hp[i] = chp;
        sd->comp_maxhp[i] = chp;
        sd->comp_intact[i] = 1;
    }
    sd->weapon_slot = weapon_spawn(slot, weapon_kind);
    if (preset == SHIP_PRESET_PLAYER)
        g_things[slot].flags |= ENT_FLAG_PLAYER_OWNED;
    return slot;
}

static void ship_gen_player(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    memset(ext, 0, sizeof(*ext));
    ext->dirty_flags = SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS;
    uint16_t mat_hull = (uint16_t)(xrng_u32() % 8);
    uint16_t mat_int  = (uint16_t)(8 + xrng_u32() % 4);
    int nose     = node_add(slot, NODE_PROP_EXTERIOR,
                             v3( 0.0f, 0.0f, -3.5f), v3(0.7f, 0.4f, 1.2f), mat_hull);
    int cockpit  = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_COCKPIT,
                             v3( 0.0f, 0.6f, -1.5f), v3(0.8f, 1.4f, 0.8f), mat_int);
    int corridor = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED,
                             v3( 0.0f, 0.6f,  1.5f), v3(0.4f, 1.4f, 1.5f), mat_int);
    int engine   = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED,
                             v3( 0.0f, 0.6f,  3.5f), v3(0.7f, 0.6f, 0.9f), mat_int);
    int comp_rm  = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_COMPUTER_ROOM,
                             v3(-1.8f, 0.6f,  1.5f), v3(0.6f, 0.5f, 0.8f), mat_hull);
    int airlock  = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_EJECT,
                             v3( 1.8f, 0.6f,  1.5f), v3(0.5f, 0.5f, 0.5f), mat_int);
    int storage  = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_STORAGE,
                             v3( 1.8f, 0.6f,  3.5f), v3(0.6f, 0.5f, 0.8f), mat_hull);
    int thr_l    = node_add(slot, NODE_PROP_THRUSTER | NODE_PROP_EXTERIOR,
                             v3(-1.5f, 0.0f, -2.0f), v3(0.3f, 0.3f, 0.6f), mat_hull);
    int thr_r    = node_add(slot, NODE_PROP_THRUSTER | NODE_PROP_EXTERIOR,
                             v3( 1.5f, 0.0f, -2.0f), v3(0.3f, 0.3f, 0.6f), mat_hull);
    int wpn_l    = node_add(slot, NODE_PROP_WEAPON_MOUNT | NODE_PROP_EXTERIOR,
                             v3(-0.9f, 0.0f, -2.5f), v3(0.2f, 0.2f, 0.4f), mat_hull);
    int wpn_r    = node_add(slot, NODE_PROP_WEAPON_MOUNT | NODE_PROP_EXTERIOR,
                             v3( 0.9f, 0.0f, -2.5f), v3(0.2f, 0.2f, 0.4f), mat_hull);
    int shield_l = node_add(slot, NODE_PROP_EXTERIOR,
                             v3(-2.0f, 0.0f,  0.0f), v3(0.3f, 0.3f, 0.3f), mat_hull);
    int shield_r = node_add(slot, NODE_PROP_EXTERIOR,
                             v3( 2.0f, 0.0f,  0.0f), v3(0.3f, 0.3f, 0.3f), mat_hull);
    if (nose < 0 || cockpit < 0 || corridor < 0 || engine < 0 ||
        comp_rm < 0 || airlock < 0 || storage < 0) return;
    ship_connect_both(slot, nose,     cockpit,  PORT_PZ, PORT_NZ, PORT_PX, PORT_NX);
    ship_connect_both(slot, cockpit,  corridor, PORT_PZ, PORT_NZ, PORT_PY, PORT_NY);
    ship_connect_both(slot, corridor, engine,   PORT_PZ, PORT_NZ, PORT_PX, PORT_NX);
    if (comp_rm >= 0)  ship_connect_one(slot, corridor, comp_rm,  PORT_NX, PORT_PX, SHIP_EDGE_WALKABLE);
    if (airlock >= 0)  ship_connect_one(slot, corridor, airlock,  PORT_PY, PORT_NY, SHIP_EDGE_WALKABLE);
    if (storage >= 0)  ship_connect_one(slot, engine,   storage,  PORT_PY, PORT_NY, SHIP_EDGE_WALKABLE);
    if (thr_l >= 0)    ship_connect_one(slot, nose,     thr_l,    PORT_NX, PORT_PX, SHIP_EDGE_STRUCTURAL);
    if (thr_r >= 0)    ship_connect_one(slot, nose,     thr_r,    PORT_PY, PORT_NY, SHIP_EDGE_STRUCTURAL);
    if (wpn_l >= 0)    ship_connect_one(slot, nose,     wpn_l,    PORT_NY, PORT_PY, SHIP_EDGE_STRUCTURAL);
    if (wpn_r >= 0)    ship_connect_one(slot, cockpit,  wpn_r,    PORT_PX, PORT_NX, SHIP_EDGE_STRUCTURAL);
    if (shield_l >= 0) ship_connect_one(slot, cockpit,  shield_l, PORT_NX, PORT_PX, SHIP_EDGE_STRUCTURAL);
    if (shield_r >= 0) ship_connect_one(slot, engine,   shield_r, PORT_PX, PORT_NX, SHIP_EDGE_STRUCTURAL);
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (sd) {
        if (sd->components_slot[COMP_HULL] != UINT32_MAX)
            node_attach_comp(slot, cockpit, sd->components_slot[COMP_HULL]);
        if (sd->components_slot[COMP_ENGINE] != UINT32_MAX)
            node_attach_comp(slot, engine, sd->components_slot[COMP_ENGINE]);
        if (sd->components_slot[COMP_SHIELD] != UINT32_MAX)
            node_attach_comp(slot, engine, sd->components_slot[COMP_SHIELD]);
        if (sd->components_slot[COMP_LIFE_SUPPORT] != UINT32_MAX)
            node_attach_comp(slot, cockpit, sd->components_slot[COMP_LIFE_SUPPORT]);
    }
    node_attach_armor(slot, cockpit,  mat_hull);
    node_attach_armor(slot, corridor, mat_hull);
    node_attach_armor(slot, engine,   mat_hull);
    computer_attach(slot, comp_rm, hash3_u32(slot, 0xC0u, 0xDEu));
    ship_ensure_fuselage(slot);
    ship_build_all_external(slot);
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
}

/* Base de partida tipo lanzadera: cubierta caminable 3x3 con sala de
   radar encima, almacen y esclusa, todo nodos caminables conectados. */
static void ship_gen_lanzadera_platform(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    memset(ext, 0, sizeof(*ext));
    ext->dirty_flags = SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS;
    uint16_t mat_deck = (uint16_t)(xrng_u32() % 8);
    uint16_t mat_int  = (uint16_t)(8 + xrng_u32() % 4);
    int deck[9];
    int dc = 0;
    for (int zi = -1; zi <= 1; zi++)
        for (int xi = -1; xi <= 1; xi++)
            deck[dc++] = node_add(slot,
                NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED,
                v3((float)xi * 2.0f, 0.f, (float)zi * 2.0f),
                v3(0.95f, 0.35f, 0.95f), mat_deck);
    int radar = node_add(slot,
        NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_COMPUTER_ROOM,
        v3(0.f, 2.0f, 0.f), v3(1.6f, 1.1f, 1.6f), mat_int);
    int storage = node_add(slot,
        NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_STORAGE,
        v3(-4.2f, 0.f, 0.f), v3(1.2f, 1.0f, 1.2f), mat_int);
    int airlock = node_add(slot,
        NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED | NODE_PROP_EJECT |
        NODE_PROP_DOCKING,
        v3(4.2f, 0.f, 0.f), v3(1.2f, 1.0f, 1.2f), mat_int);
    if (radar < 0 || storage < 0 || airlock < 0) return;
    for (int zi = 0; zi < 3; zi++)
        for (int xi = 0; xi < 2; xi++)
            ship_connect_one(slot, deck[zi * 3 + xi], deck[zi * 3 + xi + 1],
                             PORT_PX, PORT_NX, SHIP_EDGE_WALKABLE);
    for (int xi = 0; xi < 3; xi++)
        for (int zi = 0; zi < 2; zi++)
            ship_connect_one(slot, deck[zi * 3 + xi], deck[(zi + 1) * 3 + xi],
                             PORT_PZ, PORT_NZ, SHIP_EDGE_WALKABLE);
    ship_connect_one(slot, deck[4], radar, PORT_PY, PORT_NY, SHIP_EDGE_WALKABLE);
    ship_connect_one(slot, deck[3], storage, PORT_NX, PORT_PX, SHIP_EDGE_WALKABLE);
    ship_connect_one(slot, deck[5], airlock, PORT_PX, PORT_NX, SHIP_EDGE_WALKABLE);
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (sd) {
        if (sd->components_slot[COMP_HULL] != UINT32_MAX)
            node_attach_comp(slot, radar, sd->components_slot[COMP_HULL]);
        if (sd->components_slot[COMP_ENGINE] != UINT32_MAX)
            node_attach_comp(slot, deck[4], sd->components_slot[COMP_ENGINE]);
        if (sd->components_slot[COMP_LIFE_SUPPORT] != UINT32_MAX)
            node_attach_comp(slot, radar, sd->components_slot[COMP_LIFE_SUPPORT]);
    }
    node_attach_armor(slot, radar,   mat_deck);
    node_attach_armor(slot, storage, mat_deck);
    node_attach_armor(slot, airlock, mat_deck);
    computer_attach(slot, radar, hash3_u32(slot, 0xC0u, 0xDEu));
    ext->is_platform = 1;
    ship_ensure_fuselage(slot);
    ship_build_all_external(slot);
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
}

/* Construye un piso/nodo caminable pegado al nodo mas cercano al andador. */
static int ship_build_deck_node(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || ext->node_count >= SHIP_MAX_NODES) return 0;
    V3 p = g_player.walker.pos_local;
    int near_idx = -1;
    float best_d2 = 1e30f;
    for (int i = 0; i < ext->node_count; i++) {
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        float d2 = v3distsq(ext->nodes[i].pos_local, p);
        if (d2 < best_d2) { best_d2 = d2; near_idx = i; }
    }
    if (near_idx < 0) return 0;
    ShipNode* nn = &ext->nodes[near_idx];
    V3 delta = v3sub(p, nn->pos_local);
    float dl = v3len(delta);
    if (dl < 0.01f) return 0;
    int port = -1;
    float best_dot = 0.5f;
    for (int k = 0; k < 6; k++) {
        if (nn->port_edge[k] != -1) continue;
        float dt = v3dot(delta, port_normal_local(k)) / dl;
        if (dt > best_dot) { best_dot = dt; port = k; }
    }
    if (port < 0) return 0;
    V3 dir = port_normal_local(port);
    V3 he  = v3(0.9f, 0.45f, 0.9f);
    float span = (dir.x != 0.f) ? nn->half_ext.x :
                 (dir.y != 0.f) ? nn->half_ext.y : nn->half_ext.z;
    V3 pos = v3add(nn->pos_local, v3mul(dir, span + 0.45f));
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* e = &ext->nodes[i];
        V3 d = v3sub(e->pos_local, pos);
        if (fabsf(d.x) < e->half_ext.x + he.x &&
            fabsf(d.y) < e->half_ext.y + he.y &&
            fabsf(d.z) < e->half_ext.z + he.z) return 0;
    }
    int idx = node_add(slot,
        NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED, pos, he, nn->material_id);
    if (idx < 0) return 0;
    if (edge_add(slot, near_idx, port, idx, port_opposite(port),
                 SHIP_EDGE_WALKABLE) < 0) {
        node_remove(slot, idx);
        return 0;
    }
    ship_ensure_fuselage(slot);
    ship_build_all_external(slot);
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
    return 1;
}

/* =====================================================================
   BLOQUE 17e — Producción en plataforma: forja → parte física →
   carga del jugador → ensamblaje en la nave propia.
   Sin topes: cola de forja dinámica (encola consumiendo materia prima),
   carga dinámica (xrealloc), calidad aleatoria por dado.
   ===================================================================== */

static void part_cargo_push(uint32_t kind, uint32_t quality) {
    if (g_player_cargo_n >= g_player_cargo_cap) {
        uint32_t nc = g_player_cargo_cap ? g_player_cargo_cap * 2 : 8;
        PartCrate* np = (PartCrate*)xrealloc(g_player_cargo,
                                              nc * sizeof(PartCrate));
        if (!np) return;
        g_player_cargo     = np;
        g_player_cargo_cap = nc;
    }
    g_player_cargo[g_player_cargo_n].kind    = kind % COMP_COUNT;
    g_player_cargo[g_player_cargo_n].quality = quality ? quality : 1u;
    g_player_cargo_n++;
}

static uint32_t part_cargo_pop_best(uint32_t* out_kind) {
    if (!g_player_cargo_n || !g_player_cargo) return 0;
    uint32_t best = 0;
    for (uint32_t i = 1; i < g_player_cargo_n; i++)
        if (g_player_cargo[i].quality > g_player_cargo[best].quality) best = i;
    uint32_t q = g_player_cargo[best].quality;
    if (out_kind) *out_kind = g_player_cargo[best].kind;
    g_player_cargo[best] = g_player_cargo[g_player_cargo_n - 1];
    g_player_cargo_n--;
    return q;
}

static uint32_t part_cargo_count(void) { return g_player_cargo_n; }

static void part_cargo_shutdown(void) {
    xfree(g_player_cargo);
    g_player_cargo     = NULL;
    g_player_cargo_n   = 0;
    g_player_cargo_cap = 0;
}

static uint32_t part_crate_spawn(V3 pos, uint32_t kind, uint32_t quality) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_PICKUP;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_PHYSICS | ENT_FLAG_COLLIDE;
    t.pos    = pos;
    t.radius = 0.8f;
    t.hp = t.maxhp = 1.f;
    t.mass   = 40.f;
    t.life   = 600.f;
    t.seed   = xrng_u32();
    ENT_SET_I(&t, 0, PICKUP_TYPE_PART);
    ENT_SET_I(&t, 1, kind % COMP_COUNT);
    ENT_SET_F(&t, 2, (float)(quality ? quality : 1u));
    return entity_spawn(&t);
}

static uint32_t platform_forge_ensure(uint32_t platform_slot) {
    Thing* pl = entity_get(platform_slot);
    if (!pl) return UINT32_MAX;
    g_platform_forge_slot =
        forge_spawn(v3add(pl->pos, v3(-4.2f, 1.4f, 2.6f)));
    if (g_platform_forge_slot == UINT32_MAX) return UINT32_MAX;
    ForgeData* fd = (ForgeData*)entity_side_ptr(g_platform_forge_slot);
    if (fd) fd->owner_slot = g_platform_forge_slot;
    return g_platform_forge_slot;
}

static int assembly_install_one(V3 whence) {
    (void)whence;
    uint32_t s = g_game.player_ship_slot;
    if (s == UINT32_MAX || !entity_alive(s)) return 0;
    if (s == g_player_platform_slot) return 0;
    ShipData* sd = (ShipData*)entity_side_ptr(s);
    if (!sd) return 0;
    uint32_t kind = 0;
    uint32_t q = part_cargo_pop_best(&kind);
    if (!q) return 0;
    if (sd->components_slot[kind] == UINT32_MAX ||
        !entity_alive(sd->components_slot[kind])) {
        uint32_t c = component_spawn(s, kind, 60.f + 20.f * (float)q);
        if (c == UINT32_MAX) { part_cargo_push(kind, q); return 0; }
        sd->components_slot[kind] = c;
        sd->comp_hp[kind]    = 60.f + 20.f * (float)q;
        sd->comp_maxhp[kind] = 60.f + 20.f * (float)q;
        sd->comp_intact[kind] = 1;
        int node = ship_find_node_with_prop(s, NODE_PROP_WALKABLE);
        if (node >= 0) node_attach_comp(s, node, c);
        notice_push("PART INSTALLED");
    } else {
        ComponentData* cd =
            (ComponentData*)entity_side_ptr(sd->components_slot[kind]);
        if (!cd) return 0;
        float boost = 25.f * (float)q;
        cd->maxhp += boost;
        cd->hp    += boost;
        if (cd->status == 2 && cd->hp > cd->maxhp * 0.5f) cd->status = 1;
        notice_push("PART BOLTED (+HP)");
    }
    audio_sfx_dock();
    return 1;
}

static int assembly_near_own_ship(void) {
    uint32_t s = g_game.player_ship_slot;
    if (s == UINT32_MAX || !entity_alive(s)) return 0;
    if (s == g_player_platform_slot) return 0;
    if (g_player.mode == PLAYER_MODE_PILOT &&
        g_player.inside_ship == s) return 1;
    V3 pp;
    if (g_player.mode == PLAYER_MODE_EVA) pp = g_player.eva_pos;
    else if (g_player.inside_ship != UINT32_MAX &&
             entity_alive(g_player.inside_ship))
        pp = local_to_world_pos(g_player.inside_ship, g_player.walker.pos_local);
    else return 0;
    Thing* ship = entity_get(s);
    return v3dist(pp, ship->pos) < 15.f;
}

static void assembly_try_autorun(void) {
    if (!g_player_cargo_n) return;
    if (g_player.mode == PLAYER_MODE_PILOT) return;
    static float s_gate = 0.f;
    if (s_gate > 0.f) return;
    if (!assembly_near_own_ship()) return;
    if (assembly_install_one(v3zero())) s_gate = 0.5f;
}

static void ship_gen(uint32_t slot, uint32_t seed) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    memset(ext, 0, sizeof(*ext));
    ext->dirty_flags = SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS;
    uint64_t ox = g_xrng_x, oy = g_xrng_y;
    int og = g_xrng_gauss_valid;
    float os = g_xrng_gauss_spare;
    xrng_seed(seed);
    uint16_t mat_hub = mat_pool_get(hash3_u32(seed, 0xAAu, 0xBBu));
    int hub = node_add(slot, NODE_PROP_WALKABLE | NODE_PROP_PRESSURIZED,
                        v3zero(), v3(0.5f, 0.5f, 0.5f), mat_hub);
    if (hub < 0) { g_xrng_x = ox; g_xrng_y = oy; return; }
    int target = 12 + xrng_int(16);
    int attach_failures = 0;
    while (ext->node_count < target && attach_failures < 8) {
        int parent = -1;
        for (int tries = 0; tries < 12; tries++) {
            int cand = xrng_int(ext->node_count);
            for (int p = 0; p < 6; p++)
                if (ext->nodes[cand].port_edge[p] == -1) { parent = cand; break; }
            if (parent >= 0) break;
        }
        if (parent < 0) break;
        int port = -1;
        for (int p = 0; p < 6; p++)
            if (ext->nodes[parent].port_edge[p] == -1) { port = p; break; }
        if (port < 0) { attach_failures++; continue; }
        V3 dir = port_normal_local(port);
        V3 base = ext->nodes[parent].pos_local;
        V3 hx_p = ext->nodes[parent].half_ext;
        float cell = (hx_p.x + hx_p.y + hx_p.z) / 3.f + 0.7f;
        V3 new_pos = v3add(base, v3mul(dir, cell));
        V3 new_ext = v3(0.4f + xrng_f() * 0.4f,
                        0.4f + xrng_f() * 0.4f,
                        0.4f + xrng_f() * 0.4f);
        uint32_t props = 0;
        if (xrng_f() < 0.70f) props |= NODE_PROP_WALKABLE;
        if (xrng_f() < 0.60f) props |= NODE_PROP_PRESSURIZED;
        if (xrng_f() < 0.25f) props |= NODE_PROP_EXTERIOR;
        if (xrng_f() < 0.10f) props |= NODE_PROP_INSULATED;
        if (xrng_f() < 0.08f) props |= NODE_PROP_COCKPIT;
        if (xrng_f() < 0.06f) props |= NODE_PROP_EJECT;
        if (xrng_f() < 0.15f) props |= NODE_PROP_DOCKING;
        if (xrng_f() < 0.15f) props |= NODE_PROP_THRUSTER;
        if (xrng_f() < 0.10f) props |= NODE_PROP_WEAPON_MOUNT;
        if (xrng_f() < 0.08f) props |= NODE_PROP_COMPUTER_ROOM;
        uint16_t mat = mat_pool_get(hash3_u32(seed, (uint32_t)ext->node_count, 0xCCu));
        int child = node_add(slot, props, new_pos, new_ext, mat);
        if (child < 0) break;
        int opp = port_opposite(port);
        int pw = (ext->nodes[parent].props_mask & NODE_PROP_WALKABLE) != 0;
        int cw = (ext->nodes[child].props_mask & NODE_PROP_WALKABLE) != 0;
        if (pw && cw) {
            edge_add(slot, parent, port, child, opp, SHIP_EDGE_WALKABLE);
            int perp_p = (port == PORT_PX || port == PORT_NX) ? PORT_PZ : PORT_PX;
            int perp_c = port_opposite(perp_p);
            if (ext->nodes[parent].port_edge[perp_p] == -1 &&
                ext->nodes[child].port_edge[perp_c] == -1) {
                edge_add(slot, parent, perp_p, child, perp_c, SHIP_EDGE_STRUCTURAL);
            }
        } else {
            edge_add(slot, parent, port, child, opp, SHIP_EDGE_STRUCTURAL);
        }
    }
    ship_ensure_fuselage(slot);
    ship_build_all_external(slot);
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
    g_xrng_x = ox; g_xrng_y = oy;
    g_xrng_gauss_valid = og; g_xrng_gauss_spare = os;
}

static void ship_ensure_functional(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    if (!ship_has_prop(slot, NODE_PROP_COCKPIT)) {
        int center = ship_find_central_walkable(slot);
        if (center >= 0) {
            ext->nodes[center].props_mask |= NODE_PROP_COCKPIT;
            dirty_invalidate(slot, SHIP_DIRTY_TOPO);
        }
    }
    if (!ship_has_prop(slot, NODE_PROP_EJECT)) ship_add_airlock(slot);
    if (!ship_has_comp(slot, COMP_ENGINE)) {
        int rear = ship_find_room_rear(slot);
        if (rear >= 0) {
            uint32_t c = component_spawn(slot, COMP_ENGINE, 60.f);
            if (c != UINT32_MAX) node_attach_comp(slot, rear, c);
        }
    }
    if (!ship_has_comp(slot, COMP_HULL)) {
        int center = ship_find_central_walkable(slot);
        if (center >= 0) {
            uint32_t c = component_spawn(slot, COMP_HULL, 100.f);
            if (c != UINT32_MAX) node_attach_comp(slot, center, c);
        }
    }
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_COMPUTER_ROOM)) continue;
        int has = 0;
        for (int k = 0; k < n->comp_ref_count; k++) {
            ComponentData* cd = (ComponentData*)entity_side_ptr((uint32_t)n->comp_refs[k]);
            if (cd && cd->kind == COMP_COMPUTER && cd->status != 2) { has = 1; break; }
        }
        if (!has) computer_attach(slot, i, hash3_u32(slot, 0xC0u, (uint32_t)i));
    }
    dirty_invalidate(slot, SHIP_DIRTY_TOPO | SHIP_DIRTY_MASS);
}

static int ship_can_become_platform(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || ext->is_platform) return 0;
    Thing* t = entity_get(slot);
    if (!t) return 0;
    if (v3len(t->vel) > 5.f) return 0;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (n->structural_hp <= 0.f) continue;
        if (n->current_hp / n->structural_hp < 0.60f) return 0;
        if (n->props_mask & NODE_PROP_BREACHED) return 0;
    }
    return 1;
}

static int ship_can_become_ship(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || !ext->is_platform) return 0;
    if (!ship_has_comp(slot, COMP_ENGINE)) return 0;
    if (!ship_has_comp(slot, COMP_HULL)) return 0;
    if (ship_count_prop(slot, NODE_PROP_THRUSTER) < 2) return 0;
    if (!ship_has_prop(slot, NODE_PROP_COCKPIT)) return 0;
    int cockpit = ship_find_node_with_prop(slot, NODE_PROP_COCKPIT);
    int engine = ship_find_node_with_comp(slot, COMP_ENGINE);
    if (cockpit < 0 || engine < 0) return 0;
    int path[SHIP_MAX_NODES];
    int pn = graph_path(slot, cockpit, engine, path, SHIP_MAX_NODES);
    if (pn < 2) return 0;
    float total_mass = 0.f;
    for (int i = 0; i < ext->node_count; i++) total_mass += ext->nodes[i].mass;
    if (total_mass > 5000.f) return 0;
    return 1;
}

static int ship_can_fly_slot(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || ext->is_platform) return 0;
    if (!ship_has_comp(slot, COMP_ENGINE)) return 0;
    if (!ship_has_comp(slot, COMP_HULL)) return 0;
    if (!ship_has_prop(slot, NODE_PROP_COCKPIT)) return 0;
    if (ship_count_prop(slot, NODE_PROP_THRUSTER) < 1) return 0;
    return 1;
}

static int ship_convert_to_platform(uint32_t slot) {
    if (!ship_can_become_platform(slot)) {
        notice_push("CANNOT CONVERT (damage or moving)");
        return 0;
    }
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return 0;
    ext->is_platform = 1;
    Thing* t = entity_get(slot);
    if (t) t->vel = v3zero();
    notice_push("CONVERTED TO PLATFORM");
    return 1;
}

static int ship_convert_to_ship(uint32_t slot) {
    if (!ship_can_become_ship(slot)) {
        notice_push("CANNOT CONVERT (missing components)");
        return 0;
    }
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return 0;
    ext->is_platform = 0;
    notice_push("CONVERTED TO SHIP");
    return 1;
}

static int ship_dock_repair(uint32_t ship_slot, uint32_t cost) {
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd || sd->matinv[0] < cost) return 0;
    sd->matinv[0] -= cost;
    for (uint32_t i = 0; i < COMP_COUNT; i++) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
        if (!cd) continue;
        cd->hp = cd->maxhp;
        cd->status = 0;
    }
    return 1;
}

static int ship_dock_refuel(uint32_t ship_slot, uint32_t cost) {
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd || sd->matinv[0] < cost) return 0;
    sd->matinv[0] -= cost;
    sd->fuel = sd->fuel_max;
    return 1;
}

static void ship_handle_death(void) {
    uint32_t slot = g_game.player_ship_slot;
    if (slot == UINT32_MAX) return;
    Thing* ship = entity_get(slot);
    if (!ship || !ship_check_death(slot)) return;
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (!sd) return;
    int reset_count = 0;
    for (uint32_t i = 0; i < COMP_COUNT; i++) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
        if (!cd) continue;
        cd->hp = cd->maxhp * 0.5f;
        cd->status = 0;
        reset_count++;
    }
    if (reset_count == 0) {
        LOG("ship_handle_death: no components — spawning replacements");
        for (uint32_t i = 0; i < COMP_COUNT; i++) {
            if (sd->components_slot[i] != UINT32_MAX) continue;
            uint32_t c = component_spawn(slot, i, 100.f);
            if (c != UINT32_MAX) {
                sd->components_slot[i] = c;
                sd->comp_hp[i]     = 100.f;
                sd->comp_maxhp[i]  = 100.f;
                sd->comp_intact[i] = 1;
            }
        }
        if (sd->components_slot[COMP_HULL] == UINT32_MAX) {
            LOG("ship_handle_death: cannot spawn components — marking dead");
            ship->flags |= ENT_FLAG_MARKED_DEAD;
            return;
        }
    }
    if (g_player.mode == PLAYER_MODE_PILOT && g_player.inside_ship == slot) {
        g_player.prev_inside_ship = g_player.inside_ship;
        g_player.prev_mode        = (int)g_player.mode;
        g_player.mode             = PLAYER_MODE_EVA;
        g_player.eva_pos          = ship->pos;
        g_player.eva_vel          = ship->vel;
        g_player.inside_ship      = UINT32_MAX;
    }
    for (int i = 0; i < 5; i++)
        pickup_spawn(ship->pos, PICKUP_TYPE_MAT, xrng_int(MATERIAL_COUNT), 1.f);
    int n = (int)(sd->ufo_pieces * 0.5f);
    for (int i = 0; i < n; i++)
        pickup_spawn(ship->pos, PICKUP_TYPE_UFO, 0, 1.f);
    sd->ufo_pieces *= 0.5f;
    ship->vel = v3mul(ship->vel, 0.3f);
    g_game.flash = 1.f;
    g_game.shake = 2.f;
    notice_push("SHIP CRITICAL — EVA ACTIVATED");
    audio_sfx_explosion(ship->pos, 1);
}

static void ship_update_resources(uint32_t slot, ShipData* sd, float dt) {
    (void)slot;
    sd->energy += sd->energy_regen * dt;
    if (sd->energy > sd->energy_max) sd->energy = sd->energy_max;
    sd->fuel += sd->fuel_regen * dt;
    if (sd->fuel > sd->fuel_max) sd->fuel = sd->fuel_max;
    if (sd->ability_cd > 0.f) sd->ability_cd -= dt;
    Thing* ship = entity_get(slot);
    if (ship && (ship->flags & ENT_FLAG_PLAYER_OWNED)) {
        float bonus = g_xp_b7.perk_toughness * 10.f;
        ComponentData* hull_cd = (ComponentData*)entity_side_ptr(sd->components_slot[COMP_HULL]);
        if (hull_cd) {
            float new_max = 100.f + bonus;
            if (fabsf(hull_cd->maxhp - new_max) > 0.01f) {
                float ratio = (hull_cd->maxhp > 0.f) ? hull_cd->hp / hull_cd->maxhp : 1.f;
                hull_cd->maxhp = new_max;
                hull_cd->hp    = new_max * ratio;
            }
        }
    }
    for (uint32_t i = 0; i < COMP_COUNT; i++) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
        if (!cd) { sd->comp_intact[i] = 0; continue; }
        sd->comp_hp[i]     = cd->hp;
        sd->comp_maxhp[i]  = cd->maxhp;
        sd->comp_intact[i] = (cd->status != 2) ? 1 : 0;
    }
}

static void ship_tick(float dt) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_SHIP) continue;
        Thing* ship = &g_things[i];
        if (ship->flags & ENT_FLAG_MARKED_DEAD) continue;
        ShipData* sd = (ShipData*)entity_side_ptr(i);
        if (!sd) continue;
        ship_update_resources(i, sd, dt);
        if (ship_check_death(i) && !(ship->flags & ENT_FLAG_MARKED_DEAD)) {
            if (ship->flags & ENT_FLAG_PLAYER_OWNED) {
                ship_handle_death();
            } else {
                ship->flags |= ENT_FLAG_MARKED_DEAD;
                ship->version++;
                if (g_death_fn) g_death_fn(i);
            }
        }
    }
}

static EvasiveProfile evasive_profile_compute(uint32_t ship_slot) {
    EvasiveProfile ep = { 1.0f, 0.3f, 5.0f, 200.f, 0 };
    Thing* s = entity_get(ship_slot);
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!s || !sd) return ep;
    float hp_frac = 1.f;
    if (sd->comp_maxhp[COMP_HULL] > 0.f)
        hp_frac = sd->comp_hp[COMP_HULL] / sd->comp_maxhp[COMP_HULL];
    if (hp_frac < 0.25f)      { ep.effectiveness *= 1.4f; ep.energy_cost *= 1.5f; }
    else if (hp_frac < 0.50f) { ep.effectiveness *= 1.2f; ep.energy_cost *= 1.2f; }
    if (sd->energy < sd->energy_max * 0.2f) {
        ep.effectiveness *= 0.5f;
        ep.reaction_time  *= 1.5f;
    } else if (sd->energy > sd->energy_max * 0.8f) {
        ep.effectiveness *= 1.15f;
    }
    int damaged = 0;
    for (uint32_t i = 0; i < COMP_COUNT; i++)
        if (!sd->comp_intact[i]) { damaged = 1; break; }
    if (damaged) { ep.effectiveness *= 0.7f; ep.reaction_time *= 1.4f; }
    if (ext) {
        float comp = clampf((float)ext->computer_cores_total / 16.f, 0.f, 0.5f);
        ep.effectiveness *= (1.f + comp);
    }
    if (sd->camo_active) ep.effectiveness *= 1.25f;
    if (ext) {
        for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
            uint32_t d = ext->drone_slots_ship[i];
            if (d == UINT32_MAX || !entity_alive(d)) continue;
            Thing* dt_ = entity_get(d);
            if (dt_ && dt_->type == ET_DRONE && (ENT_I(dt_, 21) & DRONE_CAP_RECON)) {
                ep.range *= 1.3f;
                ep.reaction_time *= 0.8f;
                break;
            }
        }
    }
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(s->pos, 300.f, g_things_cap, &nearby);
    for (uint32_t i = 0; i < n; i++) {
        Thing* t = &g_things[nearby[i]];
        if (t->type == ET_FIELD && ENT_I(t, 0) == FIELD_TYPE_GRAVITY)
            ep.effectiveness *= 0.7f;
        if (t->type == ET_ANOMALY && ENT_I(t, 0) == ANOMALY_TYPE_WARP)
            ep.effectiveness *= 0.85f;
        if (t->type == ET_BULLET && ENT_I(t, 5) == WEAPON_MISSILE)
            ep.hard_dodge = 1;
    }
    sh_scratch_release();
    return ep;
}

static float landing_score_position(V3 pos) {
    float score = 100.f;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(pos, 500.f, g_things_cap, &nearby);
    for (uint32_t i = 0; i < n; i++) {
        Thing* t = &g_things[nearby[i]];
        float d = v3dist(t->pos, pos);
        if (t->type == ET_FIELD) {
            uint32_t ft = ENT_I(t, 0);
            if (ft == FIELD_TYPE_DAMAGE || ft == FIELD_TYPE_GRAVITY)
                score -= 200.f / (d + 1.f);
        }
        if (t->type == ET_ANOMALY) score -= 150.f / (d + 1.f);
        if (t->type == ET_LAUNCHER || t->type == ET_LANZADERA)
            score += 300.f / (d + 10.f);
        if (t->type == ET_ASTEROID) score -= 20.f / (d + 1.f);
        if (t->type == ET_SHIP && (t->flags & ENT_FLAG_PLAYER_OWNED) &&
            (int)nearby[i] != (int)g_game.player_ship_slot)
            score += 100.f / (d + 10.f);
    }
    sh_scratch_release();
    return score;
}

static V3 ship_find_best_landing_position(void) {
    if (g_game.player_ship_slot == UINT32_MAX) return v3zero();
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (!ship) return v3zero();
    V3 best = ship->pos;
    float best_score = -1e30f;
    for (int i = 0; i < 16; i++) {
        float ang = TAU_F * (float)i / 16.f;
        float rad = 20.f + (i % 4) * 15.f;
        V3 cand = v3(ship->pos.x + cosf(ang) * rad, 0.f,
                     ship->pos.z + sinf(ang) * rad);
        uint32_t* nearby;
        uint32_t nn = sh_query_dyn(cand, 20.f, g_things_cap, &nearby);
        int hazard = 0;
        for (uint32_t k = 0; k < nn; k++) {
            Thing* t = &g_things[nearby[k]];
            if (t->type == ET_FIELD) {
                uint32_t ft = ENT_I(t, 0);
                if (ft == FIELD_TYPE_DAMAGE || ft == FIELD_TYPE_GRAVITY) { hazard = 1; break; }
            }
            if (t->type == ET_ANOMALY) { hazard = 1; break; }
            if (t->type == ET_ASTEROID && t->radius > 20.f) { hazard = 1; break; }
        }
        sh_scratch_release();
        if (hazard) continue;
        float s = landing_score_position(cand);
        if (s > best_score) { best_score = s; best = cand; }
    }
    return best;
}

static void ship_innate_computer_tick(float dt) {
    if (g_player.mode != PLAYER_MODE_PILOT) return;
    if (g_game.player_ship_slot == UINT32_MAX) return;
    if (g_game.docked) return;
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (!ship) return;
    ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
    ShipDataExt* ext = ship_ext(g_game.player_ship_slot);
    if (!sd || !ext) return;
    int crew_stressed = 0;
    for (int i = 0; i < g_crew_count; i++) {
        NpcNeeds* n = npc_needs_get(g_crew[i].entity_slot);
        if (n && n->vitals.stress > 0.8f) crew_stressed++;
    }
    if (crew_stressed > 0 && sd->energy > sd->energy_max * 0.5f) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[COMP_LIFE_SUPPORT]);
        if (cd && cd->status != 2 && cd->hp < cd->maxhp) {
            cd->hp += 2.f * dt;
            if (cd->hp > cd->maxhp) cd->hp = cd->maxhp;
        }
    }
    float hull_frac = (sd->comp_maxhp[COMP_HULL] > 0.f)
                      ? sd->comp_hp[COMP_HULL] / sd->comp_maxhp[COMP_HULL] : 1.f;
    if (hull_frac < 0.5f && sd->energy > sd->energy_max * 0.3f) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[COMP_SHIELD]);
        if (cd && cd->status != 2) {
            sd->energy -= 0.5f * dt;
            cd->hp = cd->maxhp;
        }
    }
    int mats_total = 0;
    for (uint32_t i = 0; i < MATERIAL_COUNT; i++) mats_total += (int)sd->matinv[i];
    int has_damage = 0;
    for (uint32_t i = 0; i < COMP_COUNT; i++) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
        if (cd && cd->status != 2 && cd->hp < cd->maxhp * 0.9f) has_damage = 1;
    }
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        uint32_t d = ext->drone_slots_ship[i];
        if (d == UINT32_MAX || !entity_alive(d)) continue;
        Thing* dt_ = entity_get(d);
        if (!dt_ || dt_->type != ET_DRONE) continue;
        if (!(ENT_I(dt_, 21) & DRONE_CAP_REPAIR)) continue;
        if (mats_total == 0 && has_damage) {
            behavior_force(d, BEH_PATROL);
        } else if (mats_total > 0 && has_damage) {
            int worst = -1;
            float worst_f = 1.f;
            for (int k = 0; k < ext->node_count; k++) {
                ShipNode* nd = &ext->nodes[k];
                if (nd->structural_hp <= 0.f) continue;
                float f = nd->current_hp / nd->structural_hp;
                if (f < worst_f) { worst_f = f; worst = k; }
            }
            if (worst >= 0) {
                Thing* dt2 = entity_get(d);
                if (dt2) {
                    ENT_SET_I(dt2, 24, g_game.player_ship_slot);
                    ENT_SET_I(dt2, 25, (uint32_t)worst);
                    behavior_force(d, BEH_REPAIR_ID);
                }
                break;
            }
        }
    }
    if (v3lensq(ship->vel) < 1.f && sd->fuel < sd->fuel_max * 0.2f) {
        V3 best = ship_find_best_landing_position();
        if (v3lensq(best) > 0.01f) {
            V3 to = v3sub(best, ship->pos);
            float d = v3len(to);
            if (d > 5.f) {
                V3 dir = v3mul(to, 1.f / d);
                ship->vel = v3add(ship->vel, v3mul(dir, 30.f * dt));
            }
        }
    }
}

static void ship_system_init(void) {
    if (g_ship_ext_cap > 0)
        memset(g_ship_ext, 0, sizeof(ShipDataExt) * g_ship_ext_cap);
    if (g_player_consensus.repair_speed_mult <= 0.f)
        g_player_consensus.repair_speed_mult = 1.f;
    if (g_player_consensus.price_multiplier <= 0.f)
        g_player_consensus.price_multiplier = 1.f;
    memset(g_node_morph, 0, sizeof(g_node_morph));
    LOG("ship_system_init");
}

static void block6_init(void) {
    ship_system_init();
    LOG("block6_init: ship system ready");
}

static void block6_shutdown(void) {
    LOG("block6_shutdown");
}

static void particles_pool_init(void) {
    if (g_particles) return;
    g_particles_cap  = PARTICLE_SOFT_CAP;
    g_particles      = (ParticleEx*)xcalloc(g_particles_cap, sizeof(ParticleEx));
    g_particles_live = 0;
    g_particles_head = 0;
}

static void particles_pool_shutdown(void) {
    xfree(g_particles);
    g_particles = NULL;
    g_particles_cap = g_particles_live = g_particles_head = 0;
}

static ParticleEx* particle_alloc(void) {
    if (!g_particles) particles_pool_init();
    if (!g_particles) return NULL;
    for (uint32_t i = 0; i < g_particles_cap; i++) {
        uint32_t idx = (g_particles_head + i) % g_particles_cap;
        if (!g_particles[idx].active) {
            g_particles_head = (idx + 1) % g_particles_cap;
            return &g_particles[idx];
        }
    }
    ParticleEx* p = &g_particles[g_particles_head];
    g_particles_head = (g_particles_head + 1) % g_particles_cap;
    return p;
}

static FxPersonality fx_personality_from(uint32_t seed, float hue_bias, float alpha) {
    FxPersonality p;
    uint32_t h = hash_u32(seed ^ 0xABCDu);
    p.wobble_amp  = ((h        & 0xFF) / 255.f) * 2.f;
    p.wobble_freq = 0.5f + ((h >> 8)  & 0xFF) / 255.f * 2.5f;
    p.spin        = (((h >> 16) & 0xFF) / 255.f) * 2.f - 1.f;
    p.drift_chaos = ((h >> 24) & 0xFF) / 255.f;
    p.color_a     = fx_color_procedural(seed, hue_bias, alpha);
    p.color_b     = fx_color_procedural(seed ^ 0xDEADu, hue_bias, 0.f);
    p.size_mul    = 0.7f + ((h & 0xFF) / 255.f) * 0.9f;
    return p;
}

static uint32_t particle_flags_for(uint32_t kind) {
    switch (kind) {
        case PART_TYPE_SPARK:     return PART_FLAG_ADDITIVE | PART_FLAG_FADE_SIZE;
        case PART_TYPE_SMOKE:     return PART_FLAG_FADE_SIZE | PART_FLAG_COLOR_DRIFT;
        case PART_TYPE_DEBRIS:    return PART_FLAG_BOUNCE;
        case PART_TYPE_GLOW:      return PART_FLAG_ADDITIVE | PART_FLAG_WOBBLE;
        case PART_TYPE_DUST:      return PART_FLAG_FADE_SIZE;
        case PART_TYPE_FOOTSTEP:  return PART_FLAG_FADE_SIZE;
        case PART_TYPE_JETPACK:   return PART_FLAG_ADDITIVE | PART_FLAG_WOBBLE;
        case PART_TYPE_MINED_ORE: return PART_FLAG_BOUNCE | PART_FLAG_FADE_SIZE;
        default:                  return 0u;
    }
}

static V3 particle_default_color(uint32_t kind) {
    switch (kind) {
        case PART_TYPE_SPARK:     return v3(1.0f, 0.85f, 0.30f);
        case PART_TYPE_SMOKE:     return v3(0.35f, 0.35f, 0.35f);
        case PART_TYPE_DEBRIS:    return v3(0.55f, 0.45f, 0.35f);
        case PART_TYPE_GLOW:      return v3(0.60f, 0.85f, 1.00f);
        case PART_TYPE_DUST:      return v3(0.65f, 0.60f, 0.50f);
        case PART_TYPE_FOOTSTEP:  return v3(0.50f, 0.50f, 0.50f);
        case PART_TYPE_JETPACK:   return v3(0.90f, 0.55f, 0.25f);
        case PART_TYPE_MINED_ORE: return v3(0.70f, 0.60f, 0.40f);
        default:                  return v3(1.0f, 1.0f, 1.0f);
    }
}

static void particle_emit_one(V3 pos, V3 vel, uint32_t kind, float life,
                               float size_start, float size_end, uint32_t seed) {
    ParticleEx* p = particle_alloc();
    if (!p) return;
    memset(p, 0, sizeof(*p));
    p->pos        = pos;
    p->vel        = vel;
    p->life       = life;
    p->max_life   = life;
    p->size_start = size_start;
    p->size_end   = size_end;
    p->type       = kind;
    p->flags      = particle_flags_for(kind);
    p->seed       = seed;

    FxPersonality base = fx_personality_from(seed, 0.f, 1.f);
    const FxPersonality* pre = &g_part_presets[kind];
    p->personality = base;
    p->personality.wobble_amp  *= pre->wobble_amp;
    p->personality.wobble_freq  = pre->wobble_freq;
    p->personality.spin        *= pre->spin;
    p->personality.drift_chaos *= pre->drift_chaos;
    p->personality.size_mul    *= pre->size_mul;

    V3 col_rgb = particle_default_color(kind);
    p->color_start = v4(col_rgb.x, col_rgb.y, col_rgb.z, 1.f);
    p->color_end   = v4(col_rgb.x * 0.3f, col_rgb.y * 0.3f, col_rgb.z * 0.3f, 0.f);

    switch (kind) {
        case PART_TYPE_SMOKE:
            p->gravity = v3(0.f, 0.3f, 0.f);
            p->drag = 0.5f;
            break;
        case PART_TYPE_DEBRIS:
        case PART_TYPE_MINED_ORE:
            p->gravity = v3(0.f, -9.f, 0.f);
            p->drag = 0.2f;
            break;
        case PART_TYPE_SPARK:
        case PART_TYPE_GLOW:
            p->gravity = v3zero();
            p->drag = 1.5f;
            break;
        default:
            p->gravity = v3(0.f, -0.5f, 0.f);
            p->drag = 1.0f;
            break;
    }
    p->phase = base.wobble_amp * 0.1f;
    p->active = 1;
    g_particles_live++;
}

static void particle_burst_procedural(V3 pos, int count, float speed,
                                       uint32_t kind, uint32_t seed) {
    if (count <= 0) return;
    if (g_particles_live > PARTICLE_SOFT_CAP / 4 && count > 8) count = 8;
    uint32_t s = seed ? seed : hash_u32((uint32_t)(time_get() * 1000.f));
    for (int i = 0; i < count; i++) {
        uint32_t sub = hash_u32(s ^ (uint32_t)i);
        V3 dir = xrng_dir3();
        V3 vel = v3mul(dir, speed * (0.5f + ((sub & 0xFF) / 255.f)));
        float life = 0.4f + ((sub >> 8) & 0xFF) / 255.f * 1.2f;
        float size_s = 0.15f + ((sub >> 16) & 0xFF) / 255.f * 0.25f;
        float size_e = size_s * 0.2f;
        switch (kind) {
            case PART_TYPE_SMOKE:  life *= 2.f; size_s *= 2.f; break;
            case PART_TYPE_GLOW:   life *= 1.5f; break;
            case PART_TYPE_DEBRIS: life *= 2.f; size_s *= 1.5f; size_e = size_s * 0.5f; break;
            default: break;
        }
        V3 p = v3add(pos, v3mul(dir, 0.2f * ((sub >> 24) & 0xFF) / 255.f));
        particle_emit_one(p, vel, kind, life, size_s, size_e, sub);
    }
}

static void particle_tick_one(ParticleEx* p, float dt) {
    p->life -= dt;
    if (p->life <= 0.f) {
        p->active = 0;
        if (g_particles_live > 0) g_particles_live--;
        return;
    }
    float t = 1.f - (p->life / p->max_life);
    p->phase += dt * p->personality.wobble_freq;
    V3 wobble = v3(sinf(p->phase * 3.1f),
                    cosf(p->phase * 2.3f),
                    sinf(p->phase * 1.7f));
    wobble = v3mul(wobble, p->personality.wobble_amp * dt);
    if (p->flags & PART_FLAG_WOBBLE) p->vel = v3add(p->vel, wobble);
    p->vel = v3add(p->vel, v3mul(p->gravity, dt));
    p->vel = v3mul(p->vel, 1.f - p->drag * dt);
    p->pos = v3add(p->pos, v3mul(p->vel, dt));
    float size = p->size_start * (1.f - t) + p->size_end * t;
    if (p->flags & PART_FLAG_FADE_SIZE) p->size_start = size;
    p->color_start.x = lerpf(p->color_start.x, p->color_end.x, t * 0.1f);
    p->color_start.y = lerpf(p->color_start.y, p->color_end.y, t * 0.1f);
    p->color_start.z = lerpf(p->color_start.z, p->color_end.z, t * 0.1f);
    p->color_start.w = p->color_end.w * (1.f - t);
}

static void particles_tick(float dt) {
    if (!g_particles || dt <= 0.f) return;
    for (uint32_t i = 0; i < g_particles_cap; i++)
        if (g_particles[i].active) particle_tick_one(&g_particles[i], dt);
}

static void trails_pool_init(void) {
    if (g_trails) return;
    g_trails_cap  = TRAIL_SOFT_CAP;
    g_trails      = (Trail*)xcalloc(g_trails_cap, sizeof(Trail));
    g_trails_live = 0;
}

static void trails_pool_shutdown(void) {
    xfree(g_trails);
    g_trails = NULL;
    g_trails_cap = g_trails_live = 0;
}

static Trail* trail_alloc(void) {
    if (!g_trails) trails_pool_init();
    if (!g_trails) return NULL;
    for (uint32_t i = 0; i < g_trails_cap; i++) {
        if (!g_trails[i].active) {
            memset(&g_trails[i], 0, sizeof(Trail));
            g_trails[i].active = 1;
            g_trails_live++;
            return &g_trails[i];
        }
    }
    return NULL;
}

static void trail_push(Trail* tr, V3 pos) {
    if (!tr) return;
    uint32_t idx = tr->head;
    tr->points[idx] = pos;
    tr->ages[idx]   = 0.f;
    tr->head = (tr->head + 1) % TRAIL_POINTS_MAX;
    if (tr->count < TRAIL_POINTS_MAX) tr->count++;
}

static void trail_tick_one(Trail* tr, float dt) {
    for (uint32_t i = 0; i < tr->count; i++) {
        tr->ages[i] += dt;
        if (tr->ages[i] > 0.8f) { tr->count = i; break; }
    }
    if (tr->count == 0) {
        tr->active = 0;
        if (g_trails_live > 0) g_trails_live--;
    }
}

static void trails_tick(float dt) {
    if (!g_trails || dt <= 0.f) return;
    for (uint32_t i = 0; i < g_trails_cap; i++)
        if (g_trails[i].active) trail_tick_one(&g_trails[i], dt);
}

static void decals_pool_init(void) {
    if (g_decals) return;
    g_decals_cap  = DECAL_SOFT_CAP;
    g_decals      = (Decal*)xcalloc(g_decals_cap, sizeof(Decal));
    g_decals_head = 0;
}

static void decals_pool_shutdown(void) {
    xfree(g_decals);
    g_decals = NULL;
    g_decals_cap = g_decals_head = 0;
}

static Decal* decal_alloc(void) {
    if (!g_decals) decals_pool_init();
    if (!g_decals) return NULL;
    for (uint32_t i = 0; i < g_decals_cap; i++) {
        uint32_t idx = (g_decals_head + i) % g_decals_cap;
        if (!g_decals[idx].active) {
            g_decals_head = (idx + 1) % g_decals_cap;
            return &g_decals[idx];
        }
    }
    Decal* d = &g_decals[g_decals_head];
    g_decals_head = (g_decals_head + 1) % g_decals_cap;
    return d;
}

static Decal* decal_spawn(V3 pos, V3 normal, float size, V4 color, float life) {
    Decal* d = decal_alloc();
    if (!d) return NULL;
    memset(d, 0, sizeof(*d));
    d->pos    = pos;
    d->normal = v3norm(normal);
    d->size   = size;
    d->color  = color;
    d->life   = life;
    d->max_life = life;
    d->seed   = xrng_u32();
    d->active = 1;
    return d;
}

static void decal_tick(float dt) {
    if (!g_decals || dt <= 0.f) return;
    for (uint32_t i = 0; i < g_decals_cap; i++) {
        Decal* d = &g_decals[i];
        if (!d->active) continue;
        d->life -= dt;
        if (d->life <= 0.f) d->active = 0;
    }
}

static void decals_tick(float dt) { decal_tick(dt); }

