static void projectiles_pool_init(void) {
    if (g_projectiles) return;
    g_projectiles_cap = 128;
    g_projectiles = (Projectile*)xcalloc(g_projectiles_cap, sizeof(Projectile));
}

static void projectiles_pool_shutdown(void) {
    xfree(g_projectiles);
    g_projectiles = NULL;
    g_projectiles_cap = 0;
}

static Projectile* projectile_alloc(void) {
    if (!g_projectiles) projectiles_pool_init();
    if (!g_projectiles) return NULL;
    for (uint32_t i = 0; i < g_projectiles_cap; i++)
        if (!g_projectiles[i].active) return &g_projectiles[i];
    if (g_projectiles_cap < PROJECTILE_SOFT_CAP) {
        uint32_t nc = g_projectiles_cap * 2 + 2;
        if (nc > PROJECTILE_SOFT_CAP) nc = PROJECTILE_SOFT_CAP;
        Projectile* np = (Projectile*)xrealloc(g_projectiles, nc * sizeof(Projectile));
        if (!np) return NULL;
        memset(&np[g_projectiles_cap], 0, (nc - g_projectiles_cap) * sizeof(Projectile));
        g_projectiles = np;
        uint32_t idx = g_projectiles_cap;
        g_projectiles_cap = nc;
        return &g_projectiles[idx];
    }
    return NULL;
}

static uint32_t projectile_spawn_ext(uint32_t owner_slot, V3 pos, V3 vel,
                                       float damage, uint32_t dmg_type,
                                       uint32_t weapon_kind) {
    Projectile* p = projectile_alloc();
    if (!p) return UINT32_MAX;
    memset(p, 0, sizeof(*p));
    p->pos = p->prev = pos;
    p->vel = vel;
    p->life = PROJECTILE_LIFE;
    p->damage = damage;
    p->dmg_type = dmg_type;
    p->owner_slot = owner_slot;
    p->weapon_kind = weapon_kind;
    p->seed = xrng_u32();
    p->active = 1;
    return (uint32_t)(p - g_projectiles);
}

static int projectile_hit_test(Projectile* p) {
    if (!p) return 0;
    V3 seg = v3sub(p->pos, p->prev);
    float seg_len2 = v3lensq(seg);
    V3 mid = v3mul(v3add(p->prev, p->pos), 0.5f);
    float query_r = sqrtf(seg_len2) * 0.5f + 4.f;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(mid, query_r, g_things_cap, &nearby);
    for (uint32_t k = 0; k < n; k++) {
        uint32_t slot = nearby[k];
        if (slot == p->owner_slot) continue;
        if (!entity_alive(slot)) continue;
        Thing* t = &g_things[slot];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->type == ET_PROJECTILE || t->type == ET_MESSAGE) continue;
        if (t->type == ET_FIELD || t->type == ET_ANOMALY) continue;
        if (t->type == ET_STAR) continue;
        float tt = 0.f;
        if (seg_len2 > 1e-6f)
            tt = clampf(v3dot(v3sub(t->pos, p->prev), seg) / seg_len2, 0.f, 1.f);
        V3 closest = v3add(p->prev, v3mul(seg, tt));
        if (v3dist(t->pos, closest) > (t->radius + 0.3f)) continue;
        if (t->type == ET_SHIP) {
            component_spread_damage(slot, p->damage, p->dmg_type);
        } else {
            thing_hit_simple(p->owner_slot, slot, p->damage, p->dmg_type,
                             closest, v3norm(p->vel));
        }
        p->active = 0;
        sh_scratch_release();
        return 1;
    }
    sh_scratch_release();
    return 0;
}

static void projectile_tick(float dt) {
    if (!g_projectiles || dt <= 0.f) return;
    Thing* ref = entity_get(g_game.player_ship_slot);
    for (uint32_t i = 0; i < g_projectiles_cap; i++) {
        Projectile* p = &g_projectiles[i];
        if (!p->active) continue;
        p->life -= dt;
        if (p->life <= 0.f) { p->active = 0; continue; }
        p->prev = p->pos;
        FxPersonality fp = fx_personality_from(p->seed, 0.f, 1.f);
        float phase = p->life * fp.wobble_freq;
        V3 jitter = v3(cosf(phase) * fp.wobble_amp * 8.f,
                       sinf(phase * 1.37f) * fp.wobble_amp * 8.f,
                       sinf(phase * 0.71f)  * fp.wobble_amp * 8.f);
        p->vel = v3add(p->vel, v3mul(jitter, dt));
        p->pos = v3add(p->pos, v3mul(p->vel, dt));
        if (ref && v3distsq(p->pos, ref->pos) > 4000.f * 4000.f) {
            p->active = 0; continue;
        }
        projectile_hit_test(p);
    }
}

static void projectiles_publish(void) {
    if (!g_projectiles) return;
    for (uint32_t i = 0; i < g_projectiles_cap; i++) {
        Projectile* p = &g_projectiles[i];
        if (!p->active) continue;
        V4 color;
        switch (p->weapon_kind) {
            case WEAPON_LASER:   color = v4(0.3f, 1.f, 1.f, 1.f); break;
            case WEAPON_MISSILE: color = v4(1.f, 0.8f, 0.3f, 1.f); break;
            case WEAPON_PLASMA:  color = v4(1.f, 0.3f, 0.9f, 1.f); break;
            default:             color = v4(0.5f, 1.f, 0.5f, 1.f); break;
        }
        uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 105);
        if (rc != UINT32_MAX) {
            rcmd_billboard(rc, p->pos, 0.9f);
            rcmd_color(rc, color);
            rcmd_visible(rc);
        }
        V3 tp = v3sub(p->pos, v3mul(v3norm(p->vel), 0.4f));
        uint32_t rc2 = rcmd_alloc(RCK_BILLBOARD3D, 104);
        if (rc2 != UINT32_MAX) {
            rcmd_billboard(rc2, tp, 0.45f);
            rcmd_color(rc2, v4(color.x, color.y, color.z, 0.6f));
            rcmd_visible(rc2);
        }
    }
}

static void pickup_tick_one(uint32_t slot, Thing* p, float dt) {
    p->rot += p->spin * dt;
    p->life -= dt;
    if (p->life <= 0.f) { entity_mark_dead(slot); return; }
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot != UINT32_MAX && entity_alive(ship_slot)) {
        Thing* ship = entity_get(ship_slot);
        if (ship) {
            V3 to = v3sub(ship->pos, p->pos);
            float d2 = v3lensq(to);
            float magnet_r = 12.f;
            if (d2 < magnet_r * magnet_r) {
                float d = sqrtf(d2);
                if (d > 0.01f) {
                    V3 dir = v3mul(to, 1.f / d);
                    float pull = clampf((magnet_r - d) / magnet_r, 0.f, 1.f);
                    p->vel = v3add(p->vel, v3mul(dir, pull * 40.f * dt));
                }
                if (d < 1.5f) pickup_collect(ship_slot, slot);
            }
        }
    }
    p->pos = v3add(p->pos, v3mul(p->vel, dt));
    p->vel = v3mul(p->vel, 1.f - 1.5f * dt);
}

static void pickups_tick(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_PICKUP) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        pickup_tick_one(i, &g_things[i], dt);
    }
}

static uint32_t field_spawn(V3 pos, uint32_t ftype, float radius,
                              float strength, float life) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_FIELD;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC;
    t.pos    = pos;
    t.radius = radius;
    t.hp = t.maxhp = 1.f;
    t.mass   = 0.f;
    t.life   = life;
    t.seed   = xrng_u32();
    ENT_SET_I(&t, 0, ftype);
    ENT_SET_F(&t, 1, strength);
    return entity_spawn(&t);
}

static void field_tick_one(uint32_t slot, Thing* f, float dt) {
    f->life -= dt;
    if (f->life <= 0.f) { entity_mark_dead(slot); return; }
    uint32_t ftype = ENT_I(f, 0);
    float strength = ENT_F(f, 1);
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(f->pos, f->radius, g_things_cap, &nearby);
    for (uint32_t k = 0; k < n; k++) {
        uint32_t s = nearby[k];
        if (s == slot) continue;
        if (!entity_alive(s)) continue;
        Thing* t = &g_things[s];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->type == ET_FIELD || t->type == ET_STAR) continue;
        V3 to = v3sub(f->pos, t->pos);
        float d = v3len(to);
        if (d < 0.01f) continue;
        V3 dir = v3mul(to, 1.f / d);
        float falloff = clampf(1.f - d / f->radius, 0.f, 1.f);
        switch (ftype) {
            case FIELD_TYPE_GRAVITY:
                t->vel = v3add(t->vel, v3mul(dir, strength * falloff * dt));
                break;
            case FIELD_TYPE_DAMAGE:
                damage_apply(s, strength * falloff * dt, DMG_ENERGY, slot);
                break;
            case FIELD_TYPE_SLOW:
                t->vel = v3mul(t->vel, 1.f - strength * falloff * dt);
                break;
            case FIELD_TYPE_HEAL:
                if (t->hp < t->maxhp) {
                    t->hp += strength * falloff * dt;
                    if (t->hp > t->maxhp) t->hp = t->maxhp;
                }
                break;
            default: break;
        }
    }
    sh_scratch_release();
}

static void field_tick_all(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_FIELD) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        field_tick_one(i, &g_things[i], dt);
    }
}

static uint32_t anomaly_spawn(V3 pos, uint32_t atype, float radius, float strength) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_ANOMALY;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC;
    t.pos    = pos;
    t.radius = radius;
    t.hp = t.maxhp = 1.f;
    t.mass   = 100.f;
    t.life   = 0.f;
    t.seed   = xrng_u32();
    ENT_SET_I(&t, 0, atype);
    ENT_SET_F(&t, 1, strength);
    return entity_spawn(&t);
}

static void anomaly_tick_one(uint32_t slot, Thing* a, float dt) {
    uint32_t atype = ENT_I(a, 0);
    float strength = ENT_F(a, 1);
    if (a->life > 0.f) {
        a->life -= dt;
        if (a->life <= 0.f) { entity_mark_dead(slot); return; }
    }
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(a->pos, a->radius, g_things_cap, &nearby);
    for (uint32_t k = 0; k < n; k++) {
        uint32_t s = nearby[k];
        if (s == slot) continue;
        if (!entity_alive(s)) continue;
        Thing* t = &g_things[s];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->type == ET_ANOMALY || t->type == ET_FIELD) continue;
        V3 to = v3sub(a->pos, t->pos);
        float d = v3len(to);
        if (d < 0.01f) continue;
        V3 dir = v3mul(to, 1.f / d);
        float falloff = clampf(1.f - d / a->radius, 0.f, 1.f);
        switch (atype) {
            case ANOMALY_TYPE_JITTER:
                t->vel = v3add(t->vel, v3mul(dir, xrng_range(-1.f, 1.f) * strength * falloff * dt));
                break;
            case ANOMALY_TYPE_ATTRACTOR:
                t->vel = v3add(t->vel, v3mul(dir, strength * falloff * dt));
                break;
            case ANOMALY_TYPE_KILLER:
                damage_apply(s, strength * falloff * dt, DMG_EXOTIC, slot);
                break;
            case ANOMALY_TYPE_WARP:
                t->pos = v3add(t->pos, v3mul(dir, strength * falloff * dt * 20.f));
                break;
            default: break;
        }
    }
    sh_scratch_release();
}

static void anomaly_tick_all(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_ANOMALY) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        anomaly_tick_one(i, &g_things[i], dt);
    }
}

