static void ovnis_tick(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_CAPSULE) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        Thing* c = &g_things[i];
        c->rot += c->spin * dt;
        c->pos = v3add(c->pos, v3mul(c->vel, dt));
        c->vel = v3mul(c->vel, 1.f - 0.8f * dt);
        c->life -= dt;
        if (c->life <= 0.f) entity_mark_dead(i);
    }
}

static AfflictionSet* affliction_get(uint32_t slot) {
    if (slot >= MAX_ENTITIES) return NULL;
    if (slot >= g_aff_cap) {
        uint32_t nc = slot + 64;
        AfflictionSet* ns = (AfflictionSet*)xrealloc(g_aff_sets, nc * sizeof(AfflictionSet));
        uint8_t* ni = (uint8_t*)xrealloc(g_aff_inited, nc);
        if (!ns || !ni) {
            if (ns) g_aff_sets = ns;
            if (ni) g_aff_inited = ni;
            return NULL;
        }
        memset(&ns[g_aff_cap], 0, (nc - g_aff_cap) * sizeof(AfflictionSet));
        memset(&ni[g_aff_cap], 0, nc - g_aff_cap);
        g_aff_sets = ns;
        g_aff_inited = ni;
        g_aff_cap = nc;
    }
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    AfflictionSet* s = &g_aff_sets[slot];
    if (!g_aff_inited[slot] || s->owner_id != t->id) {
        memset(s, 0, sizeof(*s));
        s->owner_id = t->id;
        g_aff_inited[slot] = 1;
    }
    return s;
}

static void affliction_apply(uint32_t slot, uint32_t kind,
                              float severity, float duration, float dps) {
    AfflictionSet* s = affliction_get(slot);
    if (!s) return;
    for (uint8_t i = 0; i < s->count; i++) {
        if (s->entries[i].kind != kind) continue;
        AfflictionEntry* e = &s->entries[i];
        if (e->severity  < severity) e->severity  = severity;
        if (e->remaining < duration) e->remaining = duration;
        if (e->stack_count < 8) e->stack_count++;
        return;
    }
    if (s->count >= AFFLICTION_MAX_PER_THING) {
        uint8_t min_i = 0;
        for (uint8_t i = 1; i < s->count; i++)
            if (s->entries[i].severity < s->entries[min_i].severity) min_i = i;
        s->entries[min_i] = s->entries[s->count - 1];
        s->count--;
    }
    AfflictionEntry* e = &s->entries[s->count++];
    e->kind = kind;
    e->severity = severity;
    e->remaining = duration;
    e->tick_timer = AFFLICTION_TICK;
    e->dps = dps;
    e->stack_count = 1;
}

static void damage_apply_ex(uint32_t slot, float dmg, uint32_t dtype,
                             uint32_t attacker, int apply_aff);

static void damage_apply(uint32_t slot, float dmg, uint32_t dtype, uint32_t attacker) {
    damage_apply_ex(slot, dmg, dtype, attacker, 1);
}

static void damage_apply_ex(uint32_t slot, float dmg, uint32_t dtype,
                             uint32_t attacker, int apply_aff) {
    Thing* t = entity_get(slot);
    if (!t) return;
    if (t->flags & ENT_FLAG_MARKED_DEAD) return;

    if (t->type == ET_SHIP) {
        component_spread_damage_full(slot, dmg, dtype, -1, apply_aff);
        if (ship_check_death(slot) && !(t->flags & ENT_FLAG_MARKED_DEAD)) {
            t->flags |= ENT_FLAG_MARKED_DEAD;
            t->version++;
            if (g_death_fn) g_death_fn(slot);
        }
        return;
    }

    float resist = resistance_for_cached(slot, dtype);
    float final_dmg = dmg * (1.f - resist);
    if (final_dmg < 0.f) final_dmg = 0.f;

    t->hp -= final_dmg;
    if (t->hp < 0.f) t->hp = 0.f;
    t->version++;

    if (slot == g_player.inside_ship && g_player.mode == PLAYER_MODE_ON_FOOT) {
        g_player.walker.hurt_shake =
            fminf(g_player.walker.hurt_shake + final_dmg * 0.03f, 1.f);
    }

    if (apply_aff && final_dmg >= AFFLICTION_MIN_DAMAGE) {
        if (dtype == DMG_CHEM)
            affliction_apply(slot, AFF_POISON, 20.f, 3.f, final_dmg * 0.20f);
        else if (dtype == DMG_HEAT)
            affliction_apply(slot, AFF_BURN, 30.f, 4.f, final_dmg * 0.25f);
        else if (dtype == DMG_EXOTIC)
            affliction_apply(slot, AFF_RADIATION, 15.f, 5.f, final_dmg * 0.15f);
    }

    if (attacker != UINT32_MAX && entity_alive(attacker)) {
        CombatStateData* cs = combat_state_attach(slot);
        if (cs && cs->state != CS_ENGAGED && cs->state != CS_FLEEING) {
            combat_state_set(cs, CS_THREATENED);
            cs->opponent = attacker;
        }
    }

    if (t->hp <= 0.f && !(t->flags & ENT_FLAG_MARKED_DEAD)) {
        t->flags |= ENT_FLAG_MARKED_DEAD;
        t->version++;
        if (g_death_fn) g_death_fn(slot);
    }
}


static void affliction_tick_all(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap && i < g_aff_cap; i++) {
        if (!g_alive[i]) continue;
        AfflictionSet* s = affliction_get(i);
        if (!s || s->count == 0) continue;
        for (uint8_t j = 0; j < s->count; ) {
            AfflictionEntry* e = &s->entries[j];
            e->remaining -= dt;
            if (e->remaining <= 0.f) {
                s->entries[j] = s->entries[s->count - 1];
                s->count--;
                continue;
            }
            e->tick_timer -= dt;
            if (e->tick_timer <= 0.f) {
                e->tick_timer = AFFLICTION_TICK;
                float dmg = e->dps * (float)e->stack_count;
                uint32_t tick_dtype = DMG_CHEM;
                switch (e->kind) {
                    case AFF_BURN:      tick_dtype = DMG_HEAT;   break;
                    case AFF_RADIATION: tick_dtype = DMG_EXOTIC; break;
                    default:            tick_dtype = DMG_CHEM;   break;
                }
                Thing* t = entity_get(i);
                if (t && !(t->flags & ENT_FLAG_MARKED_DEAD)) {
                    if (t->type == ET_SHIP) {
                        component_spread_damage_full(i, dmg, tick_dtype, -1, 0);
                        if (ship_check_death(i) && !(t->flags & ENT_FLAG_MARKED_DEAD)) {
                            t->flags |= ENT_FLAG_MARKED_DEAD;
                            t->version++;
                            if (g_death_fn) g_death_fn(i);
                        }
                    } else {
                        float resist = resistance_for_cached(i, tick_dtype);
                        float final_dmg = dmg * (1.f - resist);
                        if (final_dmg < 0.f) final_dmg = 0.f;
                        t->hp -= final_dmg;
                        if (t->hp < 0.f) t->hp = 0.f;
                        t->version++;
                        if (t->hp <= 0.f) {
                            t->flags |= ENT_FLAG_MARKED_DEAD;
                            t->version++;
                            if (g_death_fn) g_death_fn(i);
                        }
                    }
                }
            }
            j++;
        }
    }
}

static void explosion_generic_ex(V3 pos, float radius, float dmg,
                                  uint32_t source_seed, int apply_aff);

static void explosion_generic(V3 pos, float radius, float dmg, uint32_t source_seed) {
    explosion_generic_ex(pos, radius, dmg, source_seed, 1);
}

static void explosion_generic_ex(V3 pos, float radius, float dmg,
                                  uint32_t source_seed, int apply_aff) {
    if (radius <= 0.f) return;

    FxPersonality fp = fx_personality_from(source_seed, 0.05f, 0.9f);
    ring_spawn(pos, radius * 2.f, 0.35f + radius * 0.008f, fp.color_a, fp.color_b);
    int n_particles = 12 + (int)(radius * 1.5f);
    int n_spark  = (int)(n_particles * 0.4f);
    int n_debris = (int)(n_particles * 0.3f);
    int n_smoke  = (int)(n_particles * 0.3f);
    for (int i = 0; i < n_spark; i++) {
        V3 dir = xrng_dir3();
        V3 vel = v3mul(dir, radius * 3.f * (0.5f + xrng_f()));
        particle_spawn_ex(pos, vel, 0.25f + xrng_f() * 0.4f,
                           radius * 0.10f, radius * 0.02f, PART_TYPE_SPARK,
                           PART_FLAG_ADDITIVE | PART_FLAG_FADE_SIZE,
                           source_seed ^ (uint32_t)(i * 0x9E37u));
    }
    for (int i = 0; i < n_debris; i++) {
        V3 dir = xrng_dir3();
        V3 vel = v3mul(dir, radius * 2.f * (0.3f + xrng_f()));
        particle_spawn_ex(pos, vel, 0.7f + xrng_f() * 0.6f,
                           radius * 0.12f, radius * 0.03f, PART_TYPE_DEBRIS,
                           PART_FLAG_FADE_SIZE,
                           source_seed ^ (uint32_t)(i * 0xDEADu));
    }
    for (int i = 0; i < n_smoke; i++) {
        V3 dir = xrng_dir3();
        V3 vel = v3mul(dir, radius * 0.8f * xrng_f());
        particle_spawn_ex(pos, vel, 1.2f + xrng_f() * 1.2f,
                           radius * 0.2f, radius * 0.4f, PART_TYPE_SMOKE, 0,
                           source_seed ^ (uint32_t)(i * 0xCAFEu));
    }
    particle_spawn_ex(pos, v3zero(), 0.15f, radius * 1.4f, radius * 0.2f,
                       PART_TYPE_GLOW, PART_FLAG_ADDITIVE, source_seed ^ 0xF1A5u);
    if (fabsf(pos.y) < radius * 0.5f) {
        for (int i = 0; i < 8; i++) {
            float ang = xrng_f() * TAU_F;
            V3 dpos = v3add(pos, v3(cosf(ang) * radius * 0.3f, 0.1f,
                                     sinf(ang) * radius * 0.3f));
            V3 dvel = v3(cosf(ang) * 3.f, 1.5f, sinf(ang) * 3.f);
            particle_spawn_ex(dpos, dvel, 1.5f, 0.4f, 1.2f, PART_TYPE_DUST, 0,
                               source_seed ^ (uint32_t)(i * 0xAAAAu));
        }
    }
    if (g_game.flash < 0.3f) g_game.flash = 0.3f;
    particle_burst_procedural(pos, 8, radius * 2.f, PART_TYPE_SPARK,
                               source_seed ^ 0x51u);

    if (dmg > 0.f) {
        uint32_t* nearby;
        uint32_t n = sh_query_dyn(pos, radius, g_things_cap, &nearby);
        for (uint32_t k = 0; k < n; k++) {
            uint32_t s = nearby[k];
            if (!entity_alive(s)) continue;
            Thing* t = &g_things[s];
            if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
            float d = v3dist(t->pos, pos);
            float falloff = clampf(1.f - d / radius, 0.f, 1.f);
            if (falloff <= 0.02f) continue;
            damage_apply_ex(s, dmg * falloff, DMG_HEAT, UINT32_MAX, apply_aff);
        }
        sh_scratch_release();
        audio_sfx_explosion(pos, radius > 15.f ? 1 : 0);
    }
}

static void chain_explosion_recursive(V3 pos, float radius, float dmg,
                                       uint32_t source_mat, int depth) {
    if (depth >= CHAIN_LOOP_GUARD) return;
    if (dmg < CHAIN_MIN_DAMAGE) return;
    explosion_generic(pos, radius, dmg,
                       hash_u32((uint32_t)(pos.x * 10.f) + (uint32_t)depth));
    float spread_mul = 1.0f;
    float damage_mul = 1.0f;
    if (source_mat < g_matpool.count) {
        uint32_t tags = g_matpool.cache[source_mat].tag_mask;
        if (tags & MAT_TAG_RADIOACTIVE)      { spread_mul = 1.6f; damage_mul = 0.7f; }
        else if (tags & MAT_TAG_TOXIC)       { spread_mul = 1.2f; damage_mul = 0.9f; }
        else if (tags & MAT_TAG_CRYSTALLINE) { spread_mul = 0.7f; damage_mul = 1.3f; }
    }
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(pos, radius * 1.5f * spread_mul,
                              g_things_cap, &nearby);
    for (uint32_t i = 0; i < n; i++) {
        uint32_t slot = nearby[i];
        if (!entity_alive(slot)) continue;
        Thing* t = &g_things[slot];
        if (t->type != ET_ASTEROID) continue;
        uint32_t mat = ENT_I(t, 0);
        if (mat >= g_matpool.count) continue;
        if (!(g_matpool.cache[mat].tag_mask & MAT_TAG_VOLATILE)) continue;
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        V3 tpos = t->pos;
        float tradius = t->radius;
        entity_mark_dead(slot);
        chain_explosion_recursive(tpos, tradius * 1.2f,
                                   dmg * CHAIN_DAMAGE_FRAC * damage_mul,
                                   mat, depth + 1);
    }
    sh_scratch_release();
}

static int thing_hit_full(const QueuedHit* h) {
    if (!h || !entity_alive(h->target)) return 0;
    Thing* t = &g_things[h->target];
    if (t->flags & ENT_FLAG_MARKED_DEAD) return 0;

    if (t->type == ET_SHIP) {
        V3 pt = h->point;
        if (v3lensq(pt) < 0.01f) pt = t->pos;
        ShipDataExt* ext = ship_ext(h->target);
        int hit_node = -1;
        if (ext && ext->node_count > 0) {
            float best_d2 = 1e30f;
            for (int i = 0; i < ext->node_count; i++) {
                V3 nw = ship_node_world_pos(h->target, i);
                float d2 = v3distsq(nw, pt);
                if (d2 < best_d2) { best_d2 = d2; hit_node = i; }
            }
        }
        int apply_aff = !(h->flags & HIT_FLAG_NO_AFFLICTION);
        float dmg = h->raw_damage;
        if (h->flags & HIT_FLAG_CRIT) dmg *= 2.f;
        component_spread_damage_full(h->target, dmg, h->damage_type, hit_node, apply_aff);
        if (ship_check_death(h->target) && !(t->flags & ENT_FLAG_MARKED_DEAD)) {
            t->flags |= ENT_FLAG_MARKED_DEAD;
            t->version++;
            death_dispatch(h->target);
        }
        return 1;
    }

    V3 pt = h->point;
    if (v3lensq(pt) < 0.01f && v3lensq(t->pos) > 0.01f) pt = t->pos;

    int central_crit = (t->radius > 0.5f && xrng_f() < 0.10f);

    int backstab = 0;
    if (h->attacker != UINT32_MAX && h->attacker != h->target
        && entity_alive(h->attacker) && !(t->flags & ENT_FLAG_STATIC)) {
        Thing* atk = &g_things[h->attacker];
        V3 tgt_fwd = v3(sinf(t->rot), 0.f, -cosf(t->rot));
        if (v3lensq(tgt_fwd) > 0.01f) {
            V3 to_atk = v3sub(atk->pos, t->pos);
            float dl = v3len(to_atk);
            if (dl > 0.5f) {
                to_atk = v3mul(to_atk, 1.f / dl);
                if (v3dot(to_atk, tgt_fwd) < -0.5f) backstab = 1;
            }
        }
    }

    float dmg = h->raw_damage;
    if (central_crit) dmg *= 1.5f;
    if (backstab)     dmg *= 1.5f;
    if (h->flags & HIT_FLAG_CRIT) dmg *= 2.f;

    int apply_aff = !(h->flags & HIT_FLAG_NO_AFFLICTION);
    damage_apply_ex(h->target, dmg, h->damage_type, h->attacker, apply_aff);

    if (t->type == ET_ASTEROID && !(h->flags & HIT_FLAG_NO_CHAIN)) {
        ThingCached* c = thing_cached_get(h->target);
        if (c && c->is_volatile && dmg >= CHAIN_MIN_DAMAGE) {
            V3 tpos = t->pos;
            float trad = t->radius;
            uint32_t mat = ENT_I(t, 0);
            entity_mark_dead(h->target);
            chain_explosion_recursive(tpos, trad * 1.2f,
                                       dmg * CHAIN_DAMAGE_FRAC, mat, 0);
            return 1;
        }
    }

    if (t->hp <= 0.f && !(t->flags & ENT_FLAG_MARKED_DEAD)) {
        t->flags |= ENT_FLAG_MARKED_DEAD;
        t->version++;
        death_dispatch(h->target);
    }
    return 1;
}

static int thing_hit_simple(uint32_t attacker, uint32_t target,
                             float damage, uint32_t dtype,
                             V3 point, V3 normal) {
    QueuedHit h;
    memset(&h, 0, sizeof(h));
    h.attacker = attacker;
    h.target = target;
    h.raw_damage = damage;
    h.damage_type = dtype;
    h.point = point;
    h.normal = normal;
    return thing_hit_full(&h);
}

static void ship_explosion_visual(uint32_t ship_slot) {
    Thing* ship = entity_get(ship_slot);
    if (!ship) return;
    V3 pos = ship->pos;
    float radius = ship->radius;
    explosion_generic(pos, radius * 3.f, 30.f, hash_u32(ship->seed));
    ring_spawn(pos, 0.8f, radius * 4.f,
                v4(1.f, 0.9f, 0.4f, 1.f),
                v4(1.f, 0.2f, 0.1f, 0.f));
    particle_burst_procedural(pos, 32, radius * 4.f, PART_TYPE_SPARK,
                                hash_u32(ship->seed ^ 0xABu));
    particle_burst_procedural(pos, 16, radius * 2.f, PART_TYPE_SMOKE,
                                hash_u32(ship->seed ^ 0xCDu));
    g_game.shake = fminf(g_game.shake + 3.f, 8.f);
    g_game.flash = 0.8f;
}

static void death_dispatch(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return;
    switch (t->type) {
        case ET_ASTEROID: {
            uint32_t mat = ENT_I(t, 0);
            int n = 1 + xrng_int(3);
            for (int i = 0; i < n; i++)
                pickup_spawn(t->pos, PICKUP_TYPE_MAT, mat, 1.f);
            if (xrng_f() < 0.3f)
                pickup_spawn(t->pos, PICKUP_TYPE_FUEL, 0, 1.f);
            g_game.kills_asteroids++;
            xp_gain_b7(1 + xp_greed_dice());
            break;
        }
        case ET_ALIEN: {
            pickup_spawn(t->pos, PICKUP_TYPE_FUEL, 0, 1.f);
            if (xrng_f() < 0.5f)
                pickup_spawn(t->pos, PICKUP_TYPE_UFO, 0, 1.f);
            g_game.kills_aliens++;
            xp_gain_b7(10);
            break;
        }
        case ET_PIRATE: {
            g_game.score += (uint64_t)(25 + xrng_int(125));
            g_game.kills_aliens++;
            xp_gain_b7(15);
            break;
        }
        case ET_TOWER:
        case ET_CANNON:
            pickup_spawn(t->pos, PICKUP_TYPE_MAT, xrng_int(MATERIAL_COUNT), 3.f);
            break;
        case ET_WRECK:
            for (int i = 0; i < 3; i++)
                pickup_spawn(t->pos, PICKUP_TYPE_MAT, xrng_int(MATERIAL_COUNT), 1.f);
            break;
        case ET_CAPSULE:
            pickup_spawn(t->pos, PICKUP_TYPE_UFO, 0, 1.f);
            break;
        case ET_CREW:
            crew_alert_death(t->pos);
            break;
        case ET_SHIP:
            if (t->flags & ENT_FLAG_PLAYER_OWNED) {
                ship_handle_death();
                return;
            }
            break;
        case ET_LANZADERA:
            lanzadera_release_data(slot);
            break;
        default: break;
    }
    NpcProfile* prof = npc_profile_get(slot);
    if (prof) {
        prof->kills_by_player++;
        LOG("death_dispatch: npc %s killed", prof->name);
        npc_profile_free(prof);
        ENT_SET_I(t, 30, 0xFFFFFFFFu);
    }
    audio_sfx_explosion(t->pos,
        (t->type == ET_SHIP || t->type == ET_TOWER) ? 1 : 0);
    explosion_generic(t->pos, t->radius * 2.5f, 20.f, t->seed);
    mission_on_kill(t->type);
    faction_on_kill_real(t);
}

static void death_dispatch_flush(void) {
    entity_flush_marked_dead();
    rcmd_cleanup_orphans();
}

static void ship_publish_exterior(uint32_t ship_slot, int skip_walkable_hull);
static void ship_publish_interior(uint32_t ship_slot);
static void world_structure_publish(uint32_t slot, const Thing* t);

static void emit_world_3d(void) {
    V3 player_center = (g_player.mode == PLAYER_MODE_EVA) ? g_player.eva_pos : g_game.cam.pos;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        if (g_things[i].flags & ENT_FLAG_NO_PUBLISH) continue;
        if (i == g_player.inside_ship && g_player.mode == PLAYER_MODE_PILOT) continue;
        if (g_things[i].type == ET_SHIP) {
            ShipDataExt* ext = ship_ext(i);
            if (ext && ext->node_count > 0 &&
                v3distsq(g_things[i].pos, player_center) < 500.f * 500.f)
                continue;
        }
        if (g_things[i].type == ET_LAUNCHER || g_things[i].type == ET_LANZADERA) {
            if (v3distsq(g_things[i].pos, player_center) < 800.f * 800.f) continue;
        }
        thing_publish_impl(i, &g_things[i]);
    }
    for (int c = 0; c < g_crew_count; c++) crew_publish((uint32_t)c);
    projectiles_publish();
    /* Nave propia en walking/plataforma: publicacion directa, sin depender
       del hash espacial (si faltaba en la query quedaban sin paredes). */
    {
        uint32_t own = g_player.inside_ship;
        if (own != UINT32_MAX && g_alive[own] &&
            g_things[own].type == ET_SHIP &&
            (g_player.mode == PLAYER_MODE_ON_FOOT ||
             g_player.mode == PLAYER_MODE_PLATFORM)) {
            ship_publish_exterior(own, 1);
            ship_publish_interior(own);
        }
    }
    uint32_t* near_ships;
    uint32_t n_near = sh_query_dyn(player_center, 500.f, g_things_cap, &near_ships);
    for (uint32_t k = 0; k < n_near; k++) {
        uint32_t s = near_ships[k];
        if (!g_alive[s]) continue;
        if (g_things[s].type != ET_SHIP) continue;
        if (g_things[s].flags & ENT_FLAG_MARKED_DEAD) continue;
        if (s == g_player.inside_ship &&
            (g_player.mode == PLAYER_MODE_ON_FOOT ||
             g_player.mode == PLAYER_MODE_PLATFORM)) continue;
        ship_publish_exterior(s, 0);
    }
    sh_scratch_release();
    uint32_t* near_world;
    uint32_t n_w = sh_query_dyn(player_center, 800.f, g_things_cap, &near_world);
    for (uint32_t k = 0; k < n_w; k++) {
        uint32_t s = near_world[k];
        if (!g_alive[s]) continue;
        if (g_things[s].flags & ENT_FLAG_MARKED_DEAD) continue;
        if (g_things[s].type == ET_LAUNCHER || g_things[s].type == ET_LANZADERA)
            world_structure_publish(s, &g_things[s]);
    }
    sh_scratch_release();
}

static void debug_emit_3d(void) {
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return;
    for (int i = 0; i < ext->node_count; i++) {
        V3 nw = ship_node_world_pos(ship_slot, i);
        V4 col = (ext->nodes[i].current_hp < ext->nodes[i].structural_hp)
                 ? v4(1.f, 0.4f, 0.4f, 0.9f) : v4(0.4f, 1.f, 0.4f, 0.9f);
        uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 200);
        if (rc != UINT32_MAX) {
            rcmd_billboard(rc, nw, 0.5f);
            rcmd_color(rc, col);
            rcmd_visible(rc);
        }
    }
}

static void scan_emit_3d(void) {
    if (!g_b7_scan_active) return;
    for (uint32_t i = 0; i < g_scan_targets_n; i++) {
        ScanTarget* st = &g_scan_targets[i];
        Thing* t = entity_get(st->slot);
        if (!t) continue;
        V4 color = st->locked ? v4(0.2f, 1.f, 0.2f, 1.f) : v4(1.f, 1.f, 0.2f, 1.f);
        uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 106);
        if (rc != UINT32_MAX) {
            rcmd_billboard(rc, t->pos, 1.2f);
            rcmd_color(rc, color);
            rcmd_visible(rc);
        }
    }
}

static void world_sim_init(void) {
    particles_pool_init();
    trails_pool_init();
    decals_pool_init();
    rings_pool_init();
    ghosts_pool_init();
    projectiles_pool_init();
    LOG("world_sim_init: particles=%u trails=%u decals=%u rings=%u ghosts=%u proj=%u",
        g_particles_cap, g_trails_cap, g_decals_cap,
        g_rings_cap, g_ghosts_cap, g_projectiles_cap);
}

static void world_sim_shutdown(void) {
    particles_pool_shutdown();
    trails_pool_shutdown();
    decals_pool_shutdown();
    rings_pool_shutdown();
    ghosts_pool_shutdown();
    projectiles_pool_shutdown();
    LOG("world_sim_shutdown");
}

static void perception_desc_default(PerceptionDesc* d) {
    if (!d) return;
    d->origin         = v3zero();
    d->fwd            = v3(0, 0, 1);
    d->fov_half_rad   = PI_F / 3.f;
    d->range_cone     = 800.f;
    d->range_radar    = 0.f;
    d->require_los    = 0;
    d->can_see_stealth = 0;
    d->species_tag    = 0;
}

static void perception_desc_for_thing(uint32_t slot, PerceptionDesc* d) {
    if (!d) return;
    perception_desc_default(d);
    Thing* t = entity_get(slot);
    if (!t) return;
    if (g_player.mode == PLAYER_MODE_EVA && slot == g_game.player_ship_slot) {
        d->origin = g_player.eva_pos;
        d->fwd = support_forward(&g_player.walker);
        d->fov_half_rad = PI_F / 2.5f;
        d->range_cone   = 600.f;
        d->range_radar  = 200.f;
        d->species_tag  = 1;
        return;
    }
    if ((g_player.mode == PLAYER_MODE_ON_FOOT ||
         g_player.mode == PLAYER_MODE_PLATFORM) &&
        slot == g_player.inside_ship) {
        d->origin = player_eye_base();
        d->fwd    = support_forward(&g_player.walker);
        d->fov_half_rad = PI_F / 2.5f;
        d->range_cone   = 500.f;
        d->range_radar  = 150.f;
        d->species_tag  = 1;
        return;
    }
    switch (t->type) {
        case ET_SHIP: {
            float pitch = ENT_F(t, 24);
            d->origin = t->pos;
            d->fwd = v3norm(v3(sinf(t->rot) * cosf(pitch), sinf(pitch),
                                -cosf(t->rot) * cosf(pitch)));
            if (v3lensq(d->fwd) < 0.01f) d->fwd = v3(0, 0, 1);
            int is_player = (t->flags & ENT_FLAG_PLAYER_OWNED) != 0;
            d->fov_half_rad = is_player ? (PI_F / 3.f) : (PI_F / 4.f);
            d->range_cone   = 1200.f;
            d->range_radar  = is_player ? 800.f : 600.f;
            d->species_tag  = 2;
            break;
        }
        case ET_DRONE: {
            d->origin = t->pos;
            d->fwd = v3(sinf(t->rot), 0.f, -cosf(t->rot));
            d->fov_half_rad = PI_F / 2.f;
            d->range_cone   = 400.f;
            d->range_radar  = 150.f;
            d->species_tag  = 3;
            break;
        }
        case ET_CREW: {
            d->origin = t->pos;
            float yaw = ENT_F(t, 20);
            d->fwd = walk_forward_dir(yaw, 0.f);
            d->fov_half_rad = PI_F / 2.5f;
            d->range_cone   = 300.f;
            d->range_radar  = 50.f;
            d->species_tag  = 1;
            break;
        }
        case ET_ALIEN: {
            d->origin = t->pos;
            d->fwd = v3(sinf(t->rot), 0.f, -cosf(t->rot));
            d->fov_half_rad = PI_F / 1.5f;
            d->range_cone   = 700.f;
            d->range_radar  = 400.f;
            d->species_tag  = 4;
            break;
        }
        case ET_PIRATE: {
            d->origin = t->pos;
            d->fwd = v3(sinf(t->rot), 0.f, -cosf(t->rot));
            d->fov_half_rad = PI_F / 3.f;
            d->range_cone   = 900.f;
            d->range_radar  = 300.f;
            d->species_tag  = 2;
            break;
        }
        default: {
            d->origin = t->pos;
            d->fwd = v3(0, 0, 1);
            break;
        }
    }
}

static int perception_los_clear(V3 a, V3 b, uint32_t self_slot) {
    V3 mid = v3mul(v3add(a, b), 0.5f);
    float half_dist = v3dist(a, b) * 0.5f;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(mid, half_dist, g_things_cap, &nearby);
    for (uint32_t k = 0; k < n; k++) {
        uint32_t s = nearby[k];
        if (s == self_slot) continue;
        if (!entity_alive(s)) continue;
        Thing* ob = &g_things[s];
        if (ob->type != ET_ASTEROID && ob->type != ET_STAR) continue;
        if (ob->radius < 5.f) continue;
        V3 to_a = v3sub(a, ob->pos);
        V3 ab   = v3sub(b, a);
        float ab_len2 = v3lensq(ab);
        if (ab_len2 < 1e-4f) continue;
        float tt = -v3dot(to_a, ab) / ab_len2;
        if (tt < 0.f || tt > 1.f) continue;
        V3 closest = v3add(a, v3mul(ab, tt));
        if (v3dist(closest, ob->pos) < ob->radius) {
            sh_scratch_release();
            return 0;
        }
    }
    sh_scratch_release();
    return 1;
}

static void perceive(uint32_t slot, PerceptionResult* out) {
    if (!out) return;
    memset(out, 0, sizeof(*out));
    out->valid = 0;
    Thing* self = entity_get(slot);
    if (!self) return;
    PerceptionDesc d;
    perception_desc_for_thing(slot, &d);
    out->observer_slot = slot;
    out->origin        = d.origin;
    out->fwd           = d.fwd;
    out->fov_half_rad  = d.fov_half_rad;
    float max_range = d.range_cone > d.range_radar ? d.range_cone : d.range_radar;
    if (max_range <= 0.f) { out->valid = 1; return; }
    float cos_half = cosf(d.fov_half_rad);
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(d.origin, max_range, g_things_cap, &nearby);
    for (uint32_t k = 0; k < n && out->visible_count < 64; k++) {
        uint32_t s = nearby[k];
        if (s == slot) continue;
        if (!entity_alive(s)) continue;
        Thing* t = &g_things[s];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->type == ET_PROJECTILE || t->type == ET_MESSAGE) continue;
        if (t->flags & ENT_FLAG_NO_PUBLISH) continue;
        V3 to = v3sub(t->pos, d.origin);
        float dist = v3len(to);
        if (dist < 0.01f) continue;
        V3 ndir = v3mul(to, 1.f / dist);
        float dot = v3dot(ndir, d.fwd);
        int in_cone  = (dot >= cos_half) && (dist <= d.range_cone);
        int in_radar = (dist <= d.range_radar);
        int visible = 0;
        if (in_cone) {
            if (d.require_los && !perception_los_clear(d.origin, t->pos, slot))
                visible = 0;
            else
                visible = 1;
        } else if (in_radar) {
            visible = 1;
        }
        if (!visible) continue;
        if (t->type == ET_SHIP && !d.can_see_stealth) {
            ShipData* tsd = (ShipData*)entity_side_ptr(s);
            if (tsd && tsd->camo_active) continue;
        }
        int idx = (int)out->visible_count++;
        out->visible[idx]      = s;
        out->visible_dist[idx] = dist;
        out->is_in_cone[idx]   = in_cone ? 1 : 0;
        if (beh_is_enemy(slot, s)) {
            if (out->hostile_count < 64)
                out->hostiles[out->hostile_count++] = s;
        } else if (beh_is_player_side(slot) && beh_is_player_side(s)) {
            if (out->friendly_count < 64)
                out->friendlies[out->friendly_count++] = s;
        }
    }
    sh_scratch_release();
    out->valid = 1;
}

static void perceive_all(float dt) {
    (void)dt;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        Thing* t = &g_things[i];
        if (!(t->flags & ENT_FLAG_AI_CONTROLLED)) continue;
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        AiData* ai = (AiData*)entity_side_ptr(i);
        if (!ai) continue;
        perceive(i, &ai->perception);
    }
}

static int beh_is_player_side(uint32_t slot) {
    Thing* t = entity_get(slot);
    return t && (t->flags & ENT_FLAG_PLAYER_OWNED);
}

static int beh_is_hostile(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return 0;
    if (t->flags & ENT_FLAG_HOSTILE) return 1;
    return (t->type == ET_ALIEN || t->type == ET_PIRATE);
}

static int beh_is_enemy(uint32_t a, uint32_t b) {
    if (a == b || !entity_alive(a) || !entity_alive(b)) return 0;
    int ap = beh_is_player_side(a), bp = beh_is_player_side(b);
    int ah = beh_is_hostile(a),    bh = beh_is_hostile(b);
    return (ap && bh) || (bp && ah);
}

static void intent_clear_move(Intent* i) {
    if (!i) return;
    i->throttle = 0.f;
    i->strafe   = 0.f;
    i->move_dir = v3zero();
    i->boost    = 0;
    i->brake    = 0;
    i->evasive  = 0;
}

static void intent_clear_fire(Intent* i) {
    if (!i) return;
    i->fire_primary     = 0;
    i->fire_secondary   = 0;
    i->fire_target_slot = UINT32_MAX;
    i->aim_dir          = v3zero();
}

static void intent_full_clear(Intent* i) {
    if (!i) return;
    memset(i, 0, sizeof(*i));
    i->fire_target_slot = UINT32_MAX;
    i->target_slot      = UINT32_MAX;
    i->accuracy_mod     = 1.f;
}

static void ai_intent_steer_world_dir(Intent* i, const Thing* t, V3 desired_dir) {
    if (!i || !t) return;
    if (v3lensq(desired_dir) < 1e-6f) { intent_clear_move(i); return; }
    V3 dir = v3norm(desired_dir);
    float pitch = ENT_F(t, 24);
    V3 fwd   = v3(sinf(t->rot) * cosf(pitch), sinf(pitch), -cosf(t->rot) * cosf(pitch));
    V3 right = v3(cosf(t->rot), 0.f, sinf(t->rot));
    V3 up    = v3norm(v3cross(right, fwd));
    i->throttle   = v3dot(dir, fwd);
    i->strafe     = v3dot(dir, right);
    i->move_dir.y = v3dot(dir, up);
    i->boost      = (fabsf(i->throttle) > 0.7f) ? 1 : 0;
}

static void ai_intent_steer_toward(Intent* i, const Thing* t, V3 target) {
    if (!i || !t) return;
    ai_intent_steer_world_dir(i, t, v3sub(target, t->pos));
}

static void ai_intent_steer_away(Intent* i, const Thing* t, V3 from) {
    if (!i || !t) return;
    ai_intent_steer_world_dir(i, t, v3sub(t->pos, from));
}

static void ai_intent_steer_orbit(Intent* i, const Thing* t, V3 center, float radius) {
    if (!i || !t) return;
    V3 to = v3sub(center, t->pos);
    float dist = v3len(to);
    if (dist < 0.01f) { intent_clear_move(i); return; }
    V3 radial = v3mul(to, 1.f / dist);
    V3 tangent = v3cross(radial, v3(0, 1, 0));
    float tl = v3len(tangent);
    if (tl < 0.01f) tangent = v3(1, 0, 0); else tangent = v3mul(tangent, 1.f / tl);
    float err = dist - radius;
    V3 corr = v3mul(radial, clampf(err * 0.15f, -1.f, 1.f));
    V3 desired = v3norm(v3add(tangent, corr));
    ai_intent_steer_world_dir(i, t, desired);
}

static void ai_intent_brake(Intent* i) {
    if (!i) return;
    i->throttle = 0.f; i->strafe = 0.f; i->move_dir = v3zero();
    i->brake = 1;
}

static void ai_intent_aim_at(Intent* i, V3 from, V3 target) {
    if (!i) return;
    V3 to = v3sub(target, from);
    if (v3lensq(to) < 1e-4f) return;
    i->aim_dir = v3norm(to);
}

static CombatStateData* combat_state_attach(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = ENT_I(t, 28);
    if (idx != 0xFFFFFFFFu && idx < g_combat_states_cap) return &g_combat_states[idx];
    uint32_t nidx;
    if (g_combat_free_n > 0) {
        nidx = g_combat_free[--g_combat_free_n];
    } else {
        if (g_combat_states_n >= g_combat_states_cap) {
            uint32_t nc = g_combat_states_cap * 2 + 2;
            if (nc > 512) nc = 512;
            if (nc <= g_combat_states_cap) return NULL;
            CombatStateData* np = (CombatStateData*)xrealloc(g_combat_states, nc * sizeof(CombatStateData));
            if (!np) return NULL;
            memset(&np[g_combat_states_cap], 0, (nc - g_combat_states_cap) * sizeof(CombatStateData));
            g_combat_states = np;
            g_combat_states_cap = nc;
        }
        nidx = g_combat_states_n++;
    }
    CombatStateData* cs = &g_combat_states[nidx];
    memset(cs, 0, sizeof(*cs));
    cs->state = CS_IDLE;
    cs->state_since = (float)time_get();
    cs->opponent = UINT32_MAX;
    cs->future_target = UINT32_MAX;
    cs->can_apologize = (xrng_f() < 0.6f) ? 1 : 0;
    cs->forgive_threshold = 50.f + xrng_f() * 200.f;
    cs->has_capsule = (xrng_f() < 0.3f) ? 1 : 0;
    ENT_SET_I(t, 28, nidx);
    return cs;
}

static CombatStateData* combat_state_get(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return NULL;
    uint32_t idx = ENT_I(t, 28);
    if (idx == 0xFFFFFFFFu || idx >= g_combat_states_cap) return NULL;
    return &g_combat_states[idx];
}

static void combat_state_set(CombatStateData* cs, CombatState ns) {
    if (!cs || cs->state == ns) return;
    cs->state = ns;
    cs->state_since = (float)time_get();
    if (ns != CS_ENGAGED && ns != CS_HUNTING) cs->attack_cd = 0.f;
}

static void combat_alert_propagate(uint32_t attacker, uint32_t target, float radius) {
    Thing* tt = entity_get(target);
    if (!tt) return;
    NpcProfile* tprof = npc_profile_get(target);
    uint32_t t_faction = tprof ? tprof->faction : 0xFFFFFFFFu;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(tt->pos, radius, g_things_cap, &nearby);
    for (uint32_t i = 0; i < n; i++) {
        uint32_t slot = nearby[i];
        if (slot == attacker || slot == target) continue;
        Thing* o = &g_things[slot];
        if (o->type != ET_CREW && o->type != ET_SHIP &&
            o->type != ET_ALIEN && o->type != ET_PIRATE) continue;
        CombatStateData* cs = combat_state_attach(slot);
        if (!cs) continue;
        if (cs->state == CS_ENGAGED || cs->state == CS_FLEEING) continue;
        NpcProfile* prof = npc_profile_get(slot);
        uint8_t same = (prof && t_faction != 0xFFFFFFFFu && prof->faction == t_faction);
        if (same) {
            combat_state_set(cs, CS_ENGAGED);
            cs->opponent = attacker;
            CombatStateData* tcs = combat_state_get(target);
            if (tcs && tcs->ally_count < 8) tcs->allies[tcs->ally_count++] = slot;
        } else {
            combat_state_set(cs, CS_ALERT);
            cs->opponent = target;
        }
    }
    sh_scratch_release();
}

static void combat_initiate(uint32_t actor, uint32_t target, uint32_t cause) {
    if (!entity_alive(actor) || !entity_alive(target)) return;
    CombatStateData* acs = combat_state_attach(actor);
    CombatStateData* tcs = combat_state_attach(target);
    if (!acs || !tcs) return;
    if (acs->state == CS_ENGAGED && acs->opponent == target) return;
    combat_state_set(acs, CS_ENGAGED); acs->opponent = target;
    combat_state_set(tcs, CS_ENGAGED); tcs->opponent = actor;
    combat_alert_propagate(actor, target, 500.f);
    event_emit(EVT_SHIP_UNDER_ATTACK, actor, target, g_things[target].pos, 0.8f, cause);
}

static void combat_on_weapon_draw(uint32_t actor, uint32_t target) {
    if (!entity_alive(target)) return;
    CombatStateData* tcs = combat_state_attach(target);
    if (!tcs || tcs->state == CS_ENGAGED) return;
    combat_state_set(tcs, CS_THREATENED);
    tcs->opponent = actor;
    combat_alert_propagate(actor, target, 400.f);
}

static void combat_hunt_future(uint32_t slot, uint32_t target, float delay) {
    CombatStateData* cs = combat_state_get(slot);
    if (!cs) return;
    cs->wants_retaliation = 1;
    cs->future_target = target;
    cs->future_when = (float)time_get() + delay;
}

static void combat_flee(uint32_t slot) {
    CombatStateData* cs = combat_state_get(slot);
    if (!cs) return;
    combat_state_set(cs, CS_FLEEING);
    cs->escape_timer = 3.f + xrng_f() * 5.f;
}

static void combat_escape_capsule(uint32_t slot) {
    CombatStateData* cs = combat_state_get(slot);
    if (!cs) return;
    Thing* t = entity_get(slot);
    if (!t) return;
    combat_hunt_future(slot, cs->opponent, 60.f + xrng_f() * 120.f);
    combat_state_set(cs, CS_ESCAPED);
    t->flags |= ENT_FLAG_NO_PUBLISH | ENT_FLAG_NO_COLLIDE;
    t->hp = t->maxhp;
    notice_push("They escaped in a capsule");
    event_emit(EVT_PLAYER_ABANDONED, cs->opponent, slot, t->pos, 0.6f, 0);
}

static void combat_reappear(uint32_t slot) {
    Thing* t = entity_get(slot);
    if (!t) return;
    t->flags &= ~(ENT_FLAG_NO_PUBLISH | ENT_FLAG_NO_COLLIDE);
    CombatStateData* cs = combat_state_get(slot);
    if (cs) combat_state_set(cs, CS_HUNTING);
    notice_push("They're back for revenge");
}

static float combat_accuracy_mod(uint32_t attacker, uint32_t target, uint32_t weapon_kind) {
    if (!entity_alive(attacker) || !entity_alive(target)) return 2.0f;
    Thing* at = entity_get(attacker);
    Thing* tt = entity_get(target);
    if (!at || !tt) return 2.0f;
    float skill = 0.4f;
    NpcProfile* aprof = npc_profile_get(attacker);
    if (aprof) skill = clampf(0.35f + aprof->trades_done / 25.f, 0.2f, 1.f);
    if (at->flags & ENT_FLAG_PLAYER_OWNED)
        skill = clampf(0.5f + g_xp_b7.perk_precision * 0.1f, 0.3f, 1.f);
    if (weapon_kind >= WEAPON_COUNT) weapon_kind = WEAPON_PULSE;
    const WeaponDef* def = &g_weapon_defs[weapon_kind];
    float d = v3dist(at->pos, tt->pos);
    float dfac = clampf(1.f - d / def->range, 0.f, 1.f);
    float eff = skill * (0.3f + dfac * 0.7f);
    float residual = clampf(1.f - eff, 0.05f, 1.5f);
    if (xrng_f() < 0.03f) residual *= 2.0f;
    return residual;
}

static void combat_tick_intent(uint32_t slot, AiData* ai, float dt, Intent* out) {
    if (!ai || !out) return;
    CombatStateData* cs = combat_state_get(slot);
    if (!cs) return;
    Thing* t = entity_get(slot);
    if (!t) return;
    float now = (float)time_get();
    float dur = now - cs->state_since;
    switch (cs->state) {
        case CS_IDLE: return;
        case CS_ALERT: {
            if (cs->opponent != UINT32_MAX && entity_alive(cs->opponent)) {
                CombatStateData* ocs = combat_state_get(cs->opponent);
                if (ocs && ocs->state == CS_ENGAGED) {
                    NpcProfile* me = npc_profile_get(slot);
                    NpcProfile* them = npc_profile_get(cs->opponent);
                    if (me && them && me->faction == them->faction) {
                        combat_state_set(cs, CS_ENGAGED);
                        cs->opponent = ocs->opponent;
                    }
                }
            } else {
                combat_state_set(cs, CS_IDLE);
                cs->opponent = UINT32_MAX;
                return;
            }
            if (dur > 30.f) { combat_state_set(cs, CS_IDLE); return; }
            Thing* op = entity_get(cs->opponent);
            if (op) ai_intent_steer_toward(out, t, op->pos);
            out->brake = 1;
            return;
        }
        case CS_THREATENED: {
            if (cs->opponent == UINT32_MAX || !entity_alive(cs->opponent)) { combat_state_set(cs, CS_IDLE); return; }
            Thing* op = entity_get(cs->opponent);
            if (!op) { combat_state_set(cs, CS_IDLE); return; }
            float d = v3dist(t->pos, op->pos);
            if (d > 2000.f) { combat_state_set(cs, CS_IDLE); return; }
            if (d < 100.f) ai_intent_steer_away(out, t, op->pos);
            else           ai_intent_steer_toward(out, t, op->pos);
            ai_intent_aim_at(out, t->pos, op->pos);
            out->fire_target_slot = cs->opponent;
            return;
        }
        case CS_ENGAGED: {
            if (cs->opponent == UINT32_MAX || !entity_alive(cs->opponent)) {
                for (uint8_t k = 0; k < cs->ally_count; k++) {
                    if (!entity_alive(cs->allies[k])) continue;
                    CombatStateData* acs = combat_state_get(cs->allies[k]);
                    if (acs && acs->opponent != UINT32_MAX && entity_alive(acs->opponent)) { cs->opponent = acs->opponent; break; }
                }
                if (cs->opponent == UINT32_MAX) { combat_state_set(cs, CS_IDLE); return; }
            }
            Thing* op = entity_get(cs->opponent);
            if (!op) { combat_state_set(cs, CS_IDLE); return; }
            float hp_frac = (t->maxhp > 0.f) ? t->hp / t->maxhp : 1.f;
            if (hp_frac < 0.25f) { combat_flee(slot); return; }
            uint32_t wk = ENT_I(t, 5);
            if (wk >= WEAPON_COUNT) wk = WEAPON_PULSE;
            const WeaponDef* def = &g_weapon_defs[wk];
            float d = v3dist(t->pos, op->pos);
            if (d > def->range)              ai_intent_steer_toward(out, t, op->pos);
            else if (d < def->range * 0.25f) ai_intent_steer_away(out, t, op->pos);
            else                             ai_intent_steer_orbit(out, t, op->pos, def->range * 0.5f);
            ai_intent_aim_at(out, t->pos, op->pos);
            out->fire_target_slot = cs->opponent;
            out->fire_primary = 1;
            out->accuracy_mod *= combat_accuracy_mod(slot, cs->opponent, wk);
            return;
        }
        case CS_FLEEING: {
            cs->escape_timer -= dt;
            if (cs->has_capsule && cs->escape_timer <= 0.f) { combat_escape_capsule(slot); return; }
            if (cs->opponent != UINT32_MAX && entity_alive(cs->opponent)) {
                Thing* op = entity_get(cs->opponent);
                if (op && v3dist(t->pos, op->pos) > 1500.f) {
                    combat_hunt_future(slot, cs->opponent, 30.f + xrng_f() * 60.f);
                    combat_state_set(cs, CS_ESCAPED);
                } else if (op) {
                    ai_intent_steer_away(out, t, op->pos);
                    out->boost = 1;
                }
            } else combat_state_set(cs, CS_IDLE);
            return;
        }
        case CS_HUNTING: {
            if (cs->future_target == UINT32_MAX || !entity_alive(cs->future_target)) { combat_state_set(cs, CS_IDLE); return; }
            Thing* target = entity_get(cs->future_target);
            if (!target) { combat_state_set(cs, CS_IDLE); return; }
            ai_intent_steer_toward(out, t, target->pos);
            ai_intent_aim_at(out, t->pos, target->pos);
            out->fire_target_slot = cs->future_target;
            out->fire_primary = (v3dist(t->pos, target->pos) < 800.f) ? 1 : 0;
            return;
        }
        case CS_ESCAPED: {
            if (cs->future_when > 0.f && now > cs->future_when) combat_reappear(slot);
            return;
        }
        default: return;
    }
}

static void combat_tick_all(float dt) { (void)dt; }

static void npc_name_generate(uint32_t seed, char* out, int out_len) {
    static const char* prefix[] = {
        "Kael","Vex","Rin","Tor","Syl","Dra","Vek","Mon","Zar","Ash",
        "Lyr","Nix","Oth","Pyr","Qua","Rok","Sev","Tyr","Ulv","Xar"
    };
    static const char* suffix[] = {
        "is","or","ak","yn","el","ar","ex","on","ul","ix",
        "an","ir","ot","ev","ur","as","im","ok","ay","en"
    };
    if (!out || out_len < 4) return;
    uint32_t h = hash_u32(seed ^ 0xC0FFEEu);
    const char* p = prefix[h % (sizeof(prefix)/sizeof(prefix[0]))];
    const char* s = suffix[(h >> 8) % (sizeof(suffix)/sizeof(suffix[0]))];
    uint32_t n = (h >> 16) & 0xFFu;
    snprintf(out, out_len, "%s%s-%02X", p, s, n);
}

static void npc_template_init(void) {
    g_npc_templates.templates = NULL;
    g_npc_templates.count = 0;
    g_npc_templates.cap   = 0;
    g_npc_next_seed = 0x12345678u;
}

static NpcTemplate* npc_template_alloc(void) {
    if (g_npc_templates.count >= g_npc_templates.cap) {
        uint32_t nc = g_npc_templates.cap + 2;
        NpcTemplate* nt = (NpcTemplate*)xrealloc(g_npc_templates.templates, nc * sizeof(NpcTemplate));
        if (!nt) return NULL;
        memset(&nt[g_npc_templates.cap], 0, (nc - g_npc_templates.cap) * sizeof(NpcTemplate));
        g_npc_templates.templates = nt;
        g_npc_templates.cap = nc;
    }
    NpcTemplate* t = &g_npc_templates.templates[g_npc_templates.count++];
    memset(t, 0, sizeof(*t));
    return t;
}

static void npc_template_fill(NpcTemplate* t, NpcRole role, uint32_t faction) {
    if (!t) return;
    t->seed = g_npc_next_seed++;
    t->base_role = role;
    t->faction   = faction;
    t->weapon_kind = (role == NPC_ROLE_PIRATE)        ? WEAPON_MISSILE
                    :(role == NPC_ROLE_MERCENARY)     ? WEAPON_PLASMA
                    :(role == NPC_ROLE_BOUNTY_HUNTER) ? WEAPON_LASER
                    : WEAPON_PULSE;
    t->ship_preset = SHIP_PRESET_ENEMY;
    t->history_flags_mask = 0;
    t->starting_rep = (role == NPC_ROLE_PATROL) ?  10
                     :(role == NPC_ROLE_TRADER) ?  20
                     :(role == NPC_ROLE_PIRATE) ? -30
                     : 0;
    t->hp_mul     = 0.8f + xrng_f() * 0.6f;
    t->speed_mul  = 0.85f + xrng_f() * 0.4f;
    t->aggression = (role == NPC_ROLE_PIRATE)   ? 0.7f + xrng_f() * 0.3f
                    :(role == NPC_ROLE_PATROL)  ? 0.3f + xrng_f() * 0.3f
                    : 0.2f + xrng_f() * 0.3f;
    t->fear_base      = 0.2f + xrng_f() * 0.3f;
    t->anger_base     = 0.2f + xrng_f() * 0.3f;
    t->loyalty_base   = 0.4f + xrng_f() * 0.4f;
    t->curiosity_base = 0.3f + xrng_f() * 0.4f;
    t->greed_base     = (role == NPC_ROLE_TRADER) ? 0.6f + xrng_f() * 0.3f
                                                  : 0.2f + xrng_f() * 0.4f;
    t->used_count = 0;
    t->last_used  = (float)time_get();
}

static int npc_template_clone_into(const NpcTemplate* tmpl, NpcProfile* dst) {
    if (!tmpl || !dst) return 0;
    memset(dst, 0, sizeof(*dst));
    dst->seed            = tmpl->seed + xrng_u32() % 1024;
    dst->faction         = tmpl->faction;
    dst->role            = tmpl->base_role;
    dst->prev_role       = tmpl->base_role;
    dst->rep_with_player = tmpl->starting_rep;
    dst->history_flags   = tmpl->history_flags_mask;
    dst->role_since      = (float)time_get();
    npc_name_generate(dst->seed, dst->name, sizeof(dst->name));
    return 1;
}

static void npc_template_seed_defaults(void) {
    if (g_npc_templates.count > 0) return;
    for (int i = 0; i < NPC_ROLE_COUNT; i++) {
        NpcTemplate* t = npc_template_alloc();
        if (!t) break;
        npc_template_fill(t, (NpcRole)i, 0);
    }
    LOG("npc_template_seed_defaults: %u templates", g_npc_templates.count);
}

static NpcTemplate* npc_template_for_role(NpcRole role) {
    NpcTemplate* best = NULL;
    uint32_t best_uses = UINT32_MAX;
    for (uint32_t i = 0; i < g_npc_templates.count; i++) {
        if (g_npc_templates.templates[i].base_role != role) continue;
        if (g_npc_templates.templates[i].used_count < best_uses) {
            best_uses = g_npc_templates.templates[i].used_count;
            best = &g_npc_templates.templates[i];
        }
    }
    if (!best) {
        best = npc_template_alloc();
        if (best) npc_template_fill(best, role, 0);
    }
    if (best) { best->used_count++; best->last_used = (float)time_get(); }
    return best;
}

static void npc_profile_init(NpcProfile* p, NpcRole role, uint32_t faction,
                              uint32_t home_launcher, uint32_t seed) {
    memset(p, 0, sizeof(*p));
    p->seed          = seed;
    p->faction       = faction;
    p->home_launcher = home_launcher;
    p->role          = role;
    p->prev_role     = role;
    p->role_since    = (float)time_get();
    p->rep_with_player = 0;
    p->last_conversion = NPC_CONV_NONE;
    npc_name_generate(seed, p->name, sizeof(p->name));
}

static void npc_role_change(NpcProfile* p, NpcRole new_role, NpcConversion reason) {
    if (!p || p->role == new_role) return;
    p->prev_role = p->role;
    p->role = new_role;
    p->role_since = (float)time_get();
    p->last_conversion = reason;
    switch (reason) {
        case NPC_CONV_TO_PIRATE:    p->history_flags |= NPC_HIST_FACTION_DEFECTED; break;
        case NPC_CONV_TO_MERCENARY: p->history_flags |= NPC_HIST_FACTION_DEFECTED; break;
        case NPC_CONV_TO_REFUGEE:   p->history_flags |= NPC_HIST_WITNESSED_ATROCITY; break;
        default: break;
    }
}

static void npc_profile_drift(uint32_t entity_slot, NpcProfile* p, float dt) {
    (void)dt;
    if (!p || p->role == NPC_ROLE_IDLE) return;
    int32_t zone_rep   = (p->faction < FACTION_COUNT) ? g_player_reputation[p->faction] : 0;
    int32_t player_rep = p->rep_with_player;
    if (p->role == NPC_ROLE_TRADER && player_rep < -50 && zone_rep < -30) {
        npc_role_change(p, NPC_ROLE_PIRATE, NPC_CONV_TO_PIRATE);
        notice_push("A trader turned pirate");
        return;
    }
    if (p->role == NPC_ROLE_PIRATE && player_rep > 50) {
        npc_role_change(p, NPC_ROLE_TRADER, NPC_CONV_TO_TRADER);
        notice_push("A pirate turned trader");
        return;
    }
    if (p->role == NPC_ROLE_PATROL && p->faction < FACTION_COUNT) {
        RegimeData* regime = faction_local_regime(p->faction);
        if (regime && regime->stability < 0.2f) {
            npc_role_change(p, NPC_ROLE_MERCENARY, NPC_CONV_TO_MERCENARY);
            notice_push("A patrol deserter turned mercenary");
            return;
        }
    }
    if (p->role == NPC_ROLE_PATROL &&
        p->home_launcher != UINT32_MAX &&
        !entity_alive(p->home_launcher)) {
        npc_role_change(p, NPC_ROLE_REFUGEE, NPC_CONV_TO_REFUGEE);
        p->home_launcher = UINT32_MAX;
        notice_push("A patrol became a refugee");
        return;
    }
    Thing* t = entity_get(entity_slot);
    if (t && t->maxhp > 0.f) {
        float hp_frac = t->hp / t->maxhp;
        if (hp_frac < 0.2f && zone_rep > 50 &&
            (float)time_get() - p->role_since > 120.f) {
            npc_role_change(p, NPC_ROLE_IDLE, NPC_CONV_RETIRED);
        }
    }
}

static void npc_psych_init(NpcPsychState* p, uint32_t seed) {
    memset(p, 0, sizeof(*p));
    uint32_t h = hash_u32(seed ^ 0x51C0u);
    p->fear      = (h        & 0xFF) / 255.f;
    p->anger     = ((h >>  8) & 0xFF) / 255.f;
    p->loyalty   = ((h >> 16) & 0xFF) / 255.f;
    p->curiosity = ((h >> 24) & 0xFF) / 255.f;
    p->greed     = xrng_f();
    p->current   = NPC_MOOD_CALM;
    p->mood_intensity = 0.2f;
    p->last_change = (float)time_get();
}

static NpcMood npc_psych_pick_mood(const NpcPsychState* p) {
    if ((p->event_bits & NPC_PSYCH_EV_SAW_ATROCITY) && p->fear > 0.8f) return NPC_MOOD_BROKEN;
    if (p->fear > 0.65f)  return NPC_MOOD_FLEEING;
    if (p->anger > 0.70f) return NPC_MOOD_HUNTING;
    if (p->anger > 0.50f) return NPC_MOOD_AGITATED;
    if (p->greed + p->loyalty > 1.2f) return NPC_MOOD_EUPHORIC;
    if (p->fear > 0.30f)  return NPC_MOOD_ALERT;
    return NPC_MOOD_CALM;
}

static void npc_psych_tick(NpcPsychState* p, float dt) {
    if (!p) return;
    float decay = dt * 0.02f;
    p->fear  -= decay * (p->fear  > 0.5f ? 0.5f : 1.f);
    p->anger -= decay * (p->anger > 0.5f ? 0.3f : 1.f);
    p->greed -= decay * 0.5f;
    if (p->fear  < 0.f) p->fear  = 0.f;
    if (p->anger < 0.f) p->anger = 0.f;
    if (p->greed < 0.f) p->greed = 0.f;
    NpcMood nm = npc_psych_pick_mood(p);
    if (nm != p->current) {
        p->current = nm;
        p->last_change = (float)time_get();
        p->mood_intensity = 0.2f + (float)nm / NPC_MOOD_COUNT * 0.8f;
    }
}

static void npc_psych_on_event(NpcPsychState* p, NpcPsychEvent ev, float severity) {
    if (!p) return;
    switch (ev) {
        case NPC_PSYCH_EV_HIT: p->fear += severity * 0.3f; p->anger += severity * 0.5f; break;
        case NPC_PSYCH_EV_KILLED_FRIEND:
            p->fear += 0.2f; p->anger += 0.6f;
            p->loyalty = clampf(p->loyalty + 0.1f, 0.f, 1.f);
            p->event_bits |= NPC_PSYCH_EV_KILLED_FRIEND;
            break;
        case NPC_PSYCH_EV_SAW_ATROCITY:
            p->fear += 0.5f; p->anger += 0.2f; p->loyalty -= 0.3f;
            p->event_bits |= NPC_PSYCH_EV_SAW_ATROCITY;
            break;
        case NPC_PSYCH_EV_TRADED: p->greed += severity * 0.2f; p->loyalty += severity * 0.1f; break;
        case NPC_PSYCH_EV_WON_FIGHT: p->anger -= 0.1f; p->fear -= 0.2f; p->curiosity += 0.1f; break;
        case NPC_PSYCH_EV_HELPED_PLAYER: p->loyalty += 0.3f; break;
        default: break;
    }
    p->fear      = clampf(p->fear, 0.f, 1.f);
    p->anger     = clampf(p->anger, 0.f, 1.f);
    p->loyalty   = clampf(p->loyalty, 0.f, 1.f);
    p->curiosity = clampf(p->curiosity, 0.f, 1.f);
    p->greed     = clampf(p->greed, 0.f, 1.f);
}

static NpcPsychPhase npc_psych_evaluate(const NpcNeeds* n) {
    if (!n) return NPC_PSYCH_STABLE;
    if (n->vitals.stress > 0.9f) return NPC_PSYCH_MADNESS;
    if (n->vitals.stress > 0.7f) return NPC_PSYCH_PANIC;
    if (n->vitals.stress > 0.4f) return NPC_PSYCH_STRESSED;
    return NPC_PSYCH_STABLE;
}

static void npc_psych_apply(uint32_t slot, NpcNeeds* needs) {
    if (!needs) return;
    NpcPsychPhase phase = npc_psych_evaluate(needs);
    Thing* t = entity_get(slot);
    if (!t) return;
    uint32_t prev = ENT_I(t, 26);
    ENT_SET_I(t, 26, (uint32_t)phase);
    if (prev == (uint32_t)phase) return;
    switch (phase) {
        case NPC_PSYCH_PANIC: behavior_force(slot, BEH_FLEE); notice_push("Crew in panic"); break;
        case NPC_PSYCH_MADNESS: {
            NpcProfile* prof = npc_profile_get(slot);
            if (prof) {
                if (xrng_f() < 0.5f) npc_role_change(prof, NPC_ROLE_PIRATE, NPC_CONV_TO_PIRATE);
                else prof->role = NPC_ROLE_IDLE;
            }
            behavior_force(slot, BEH_WANDER);
            notice_push("Crew snapped");
            break;
        }
        default: break;
    }
}

static void npc_psych_calm(uint32_t slot) {
    NpcNeeds* needs = npc_needs_get(slot);
    if (!needs) return;
    needs->vitals.stress = clampf(needs->vitals.stress - 0.4f, 0.f, 1.f);
    needs->vitals.morale = clampf(needs->vitals.morale + 0.2f, 0.f, 1.f);
}

static void npc_vitals_drift(NpcNeeds* n, NpcOccupation occ, float dt) {
    if (!n) return;
    float drain = 0.f;
    switch (occ) {
        case NPC_OCC_WORKING: drain = 0.02f; break;
        case NPC_OCC_TRAINING: drain = 0.03f; break;
        case NPC_OCC_PATROLLING: drain = 0.015f; break;
        case NPC_OCC_EMERGENCY: drain = 0.05f; break;
        case NPC_OCC_SLEEPING: drain = -0.10f; break;
        case NPC_OCC_EATING: drain = -0.02f; break;
        default: drain = 0.005f; break;
    }
    n->vitals.energy = clampf(n->vitals.energy - drain * dt, 0.f, 1.f);
    float hunger_rate = (occ == NPC_OCC_EATING) ? -0.20f : 0.005f;
    n->vitals.hunger = clampf(n->vitals.hunger + hunger_rate * dt, 0.f, 1.f);
    float stress_rate = 0.f;
    switch (occ) {
        case NPC_OCC_EMERGENCY: stress_rate = 0.05f; break;
        case NPC_OCC_SLEEPING:
        case NPC_OCC_LEISURE:   stress_rate = -0.05f; break;
        default: stress_rate = 0.005f; break;
    }
    n->vitals.stress = clampf(n->vitals.stress + stress_rate * dt, 0.f, 1.f);
    n->vitals.morale = lerpf(n->vitals.morale, 0.6f, dt * 0.1f);
    float boredom_rate = 0.f;
    switch (occ) {
        case NPC_OCC_WORKING: boredom_rate = 0.02f; break;
        case NPC_OCC_LEISURE:
        case NPC_OCC_SOCIAL:  boredom_rate = -0.15f; break;
        default: boredom_rate = 0.005f; break;
    }
    n->vitals.boredom = clampf(n->vitals.boredom + boredom_rate * dt, 0.f, 1.f);
    float social_rate = (occ == NPC_OCC_SOCIAL) ? -0.20f : 0.01f;
    n->vitals.social = clampf(n->vitals.social + social_rate * dt, 0.f, 1.f);
}

static void npc_aspirations_tick(NpcNeeds* n, NpcOccupation occ, float dt) {
    if (!n) return;
    for (int i = 0; i < NPC_ASPIRATION_MAX; i++) {
        NpcAspirationState* a = &n->aspirations[i];
        if (!a->active || a->completed) continue;
        switch (a->kind) {
            case NPC_ASPIRATION_BECOME_PILOT:
                if (occ == NPC_OCC_TRAINING) a->progress_current++;
                break;
            case NPC_ASPIRATION_MASTER_REPAIR:
                if (occ == NPC_OCC_WORKING) a->progress_current++;
                break;
            case NPC_ASPIRATION_WEALTH:
                a->progress_current += (uint32_t)(dt * 2.f);
                break;
            case NPC_ASPIRATION_SURVIVE:
                a->progress_current++;
                break;
            default: break;
        }
        a->time_invested += dt;
        if (a->progress_current >= a->progress_target) a->completed = 1;
    }
}

static NpcOccupation npc_occupation_from_task(NpcTaskKind k) {
    switch (k) {
        case NPC_TASK_REPAIR_NODE:     return NPC_OCC_WORKING;
        case NPC_TASK_EXTINGUISH_FIRE: return NPC_OCC_EMERGENCY;
        case NPC_TASK_SEAL_BREACH:     return NPC_OCC_EMERGENCY;
        case NPC_TASK_MIX_INGREDIENTS: return NPC_OCC_WORKING;
        case NPC_TASK_MINE_ASTEROID:   return NPC_OCC_WORKING;
        case NPC_TASK_PATROL:          return NPC_OCC_PATROLLING;
        case NPC_TASK_PILOT_SHIP:      return NPC_OCC_WORKING;
        case NPC_TASK_TRADE:           return NPC_OCC_WORKING;
        default: return NPC_OCC_IDLE;
    }
}

static NpcOccupation npc_occupation_from_aspiration(NpcAspiration k) {
    switch (k) {
        case NPC_ASPIRATION_BECOME_PILOT:  return NPC_OCC_TRAINING;
        case NPC_ASPIRATION_MASTER_REPAIR: return NPC_OCC_WORKING;
        case NPC_ASPIRATION_MASTER_MIXING: return NPC_OCC_WORKING;
        case NPC_ASPIRATION_EXPLORE:       return NPC_OCC_PATROLLING;
        default: return NPC_OCC_IDLE;
    }
}

static void npc_context_evaluate(uint32_t slot, NpcNeeds* n) {
    if (!n) return;
    float best_score = 0.f;
    NpcOccupation best = NPC_OCC_IDLE;
    uint32_t best_target = UINT32_MAX;
    float now = (float)time_get();
    Thing* t = entity_get(slot);
    if (t && t->maxhp > 0.f) {
        float hp_frac = t->hp / t->maxhp;
        if (hp_frac < 0.25f) { best = NPC_OCC_EMERGENCY; best_score = 200.f; }
    }
    if (n->vitals.energy < 0.15f) {
        float s = 100.f * (0.15f - n->vitals.energy) / 0.15f;
        if (s > best_score) { best = NPC_OCC_SLEEPING; best_score = s; }
    }
    if (n->vitals.hunger > 0.80f) {
        float s = 80.f * (n->vitals.hunger - 0.80f) / 0.20f;
        if (s > best_score) { best = NPC_OCC_EATING; best_score = s; }
    }
    if (n->vitals.boredom > 0.70f) {
        float s = 50.f * (n->vitals.boredom - 0.70f) / 0.30f;
        if (s > best_score) { best = NPC_OCC_LEISURE; best_score = s; }
    }
    if (n->vitals.social > 0.70f) {
        float s = 50.f * (n->vitals.social - 0.70f) / 0.30f;
        if (s > best_score) { best = NPC_OCC_SOCIAL; best_score = s; }
    }
    for (uint8_t i = 0; i < n->tasks.count; i++) {
        NpcTask* task = &n->tasks.tasks[i];
        if (!task->active) continue;
        float s = (float)task->priority;
        if (task->deadline > 0.f) {
            float urgency = 1.f - clampf((task->deadline - now) / 30.f, 0.f, 1.f);
            s *= 1.f + urgency * 2.f;
        }
        if (s > best_score) {
            best = npc_occupation_from_task(task->kind);
            best_score = s;
            best_target = task->target;
            n->tasks.current = i;
        }
    }
    for (int i = 0; i < NPC_ASPIRATION_MAX; i++) {
        NpcAspirationState* a = &n->aspirations[i];
        if (!a->active || a->completed) continue;
        NpcOccupation occ = npc_occupation_from_aspiration((NpcAspiration)a->kind);
        float s = a->motivation * 30.f;
        if (s > best_score) { best = occ; best_score = s; }
    }
    if (n->assignment.active && best_score < 10.f) {
        best = npc_occupation_from_task(n->assignment.default_task);
        best_score = 10.f;
        best_target = n->assignment.post_slot;
    }
    if (n->occupation == best) {
        n->cache.best = best;
        n->cache.best_score = best_score;
        n->cache.best_target = best_target;
        return;
    }
    if (n->occupation != NPC_OCC_IDLE && best_score < 15.f) return;
    n->cache.best = best;
    n->cache.best_score = best_score;
    n->cache.best_target = best_target;
    n->occupation = best;
    n->occupation_since = now;
}

static void npc_occupation_apply(uint32_t slot, NpcNeeds* n, float dt) {
    if (!n) return;
    AiData* ai = (AiData*)entity_side_ptr(slot);
    if (!ai) return;
    uint32_t target_behavior = BEH_IDLE;
    switch (n->occupation) {
        case NPC_OCC_EMERGENCY:
        case NPC_OCC_SLEEPING: target_behavior = BEH_IDLE; break;
        case NPC_OCC_WORKING:
            if (n->tasks.current < n->tasks.count) {
                NpcTask* t = &n->tasks.tasks[n->tasks.current];
                if (t->kind == NPC_TASK_REPAIR_NODE) target_behavior = BEH_REPAIR_ID;
                else                                 target_behavior = BEH_GUARD;
            } else target_behavior = BEH_GUARD;
            break;
        case NPC_OCC_SOCIAL:
        case NPC_OCC_LEISURE: target_behavior = BEH_WANDER; break;
        case NPC_OCC_TRAINING:
        case NPC_OCC_PATROLLING: target_behavior = BEH_PATROL; break;
        case NPC_OCC_EATING: target_behavior = BEH_IDLE; break;
        default: target_behavior = BEH_WANDER;
    }
    if (ai->behavior_id != target_behavior) behavior_force(slot, target_behavior);
    (void)dt;
}

static void npc_needs_tick(uint32_t slot, float dt) {
    NpcNeeds* n = npc_needs_get(slot);
    if (!n) return;
    npc_vitals_drift(n, n->occupation, dt);
    npc_aspirations_tick(n, n->occupation, dt);
    float now = (float)time_get();
    int force = n->cache.dirty || (now - n->cache.last_eval > 2.0f);
    if (force) {
        npc_context_evaluate(slot, n);
        n->cache.dirty = 0;
        n->cache.last_eval = now;
    }
    npc_occupation_apply(slot, n, dt);
    npc_psych_apply(slot, n);
}

static void npc_social_exchange(uint32_t a, uint32_t b) {
    NpcNeeds* na = npc_needs_get(a);
    NpcNeeds* nb = npc_needs_get(b);
    if (!na || !nb) return;
    na->vitals.social = clampf(na->vitals.social - 0.3f, 0.f, 1.f);
    nb->vitals.social = clampf(nb->vitals.social - 0.3f, 0.f, 1.f);
    na->vitals.morale = clampf(na->vitals.morale + 0.1f, 0.f, 1.f);
    nb->vitals.morale = clampf(nb->vitals.morale + 0.1f, 0.f, 1.f);
    na->vitals.stress = clampf(na->vitals.stress - 0.1f, 0.f, 1.f);
    nb->vitals.stress = clampf(nb->vitals.stress - 0.1f, 0.f, 1.f);
}

static uint32_t npc_task_id(NpcTaskKind kind, uint32_t target) {
    return hash_combine((uint32_t)kind, target);
}

static void npc_task_upsert(uint32_t slot, NpcTaskKind kind, uint32_t target,
                             V3 pos, int priority, float deadline) {
    NpcNeeds* n = npc_needs_get(slot);
    if (!n) return;
    uint32_t tid = npc_task_id(kind, target);
    for (int i = 0; i < n->tasks.count; i++) {
        NpcTask* t = &n->tasks.tasks[i];
        if (!t->active) continue;
        uint32_t etid = hash_combine((uint32_t)t->kind, t->target);
        if (etid != tid) continue;
        if (priority > t->priority) t->priority = priority;
        if (deadline > 0.f && (t->deadline == 0.f || deadline < t->deadline)) t->deadline = deadline;
        n->cache.dirty = 1;
        return;
    }
    if (n->tasks.count >= NPC_TASK_QUEUE_MAX) {
        int min_i = 0;
        for (int i = 1; i < n->tasks.count; i++)
            if (n->tasks.tasks[i].priority < n->tasks.tasks[min_i].priority) min_i = i;
        if (priority <= n->tasks.tasks[min_i].priority) return;
        n->tasks.tasks[min_i].active = 0;
        n->tasks.count--;
    }
    NpcTask* t = &n->tasks.tasks[n->tasks.count++];
    memset(t, 0, sizeof(*t));
    t->kind = kind;
    t->target = target;
    t->pos = pos;
    t->priority = priority;
    t->deadline = deadline;
    t->effort_left = 5.f;
    t->active = 1;
    n->cache.dirty = 1;
}

static void npc_task_post(uint32_t slot, NpcTaskKind kind, uint32_t target, V3 pos) {
    if ((int)kind < 0 || kind >= NPC_TASK_COUNT) return;
    const NpcTaskSpec* sp = &g_npc_task_specs[kind];
    float now = (float)time_get();
    float deadline = (sp->base_deadline > 0.f) ? (now + sp->base_deadline) : 0.f;
    npc_task_upsert(slot, kind, target, pos, sp->base_priority, deadline);
}

static void npc_task_repair(uint32_t slot, uint32_t node, V3 pos) { npc_task_post(slot, NPC_TASK_REPAIR_NODE, node, pos); }
static void npc_task_fire(uint32_t slot, uint32_t fire, V3 pos) { npc_task_post(slot, NPC_TASK_EXTINGUISH_FIRE, fire, pos); }
static void npc_task_breach(uint32_t slot, uint32_t node, V3 pos) { npc_task_post(slot, NPC_TASK_SEAL_BREACH, node, pos); }
static void npc_task_pilot(uint32_t slot, uint32_t ship, V3 pos) { npc_task_post(slot, NPC_TASK_PILOT_SHIP, ship, pos); }
static void npc_task_patrol(uint32_t slot, uint32_t post, V3 pos) { npc_task_post(slot, NPC_TASK_PATROL, post, pos); }
static void npc_task_mine(uint32_t slot, uint32_t ast, V3 pos) { npc_task_post(slot, NPC_TASK_MINE_ASTEROID, ast, pos); }
static void npc_task_trade(uint32_t slot, uint32_t lau, V3 pos) { npc_task_post(slot, NPC_TASK_TRADE, lau, pos); }

static void event_bus_init(void) {
    g_event_queue_cap = 64;
    g_event_queue = (GameEvent*)xcalloc(g_event_queue_cap, sizeof(GameEvent));
    g_event_queue_n = 0;
}

static void event_bus_shutdown(void) {
    xfree(g_event_queue);
    g_event_queue = NULL;
    g_event_queue_cap = g_event_queue_n = 0;
}

static void event_emit(GameEventKind kind, uint32_t actor, uint32_t target,
                        V3 pos, float magnitude, uint32_t extra) {
    if (g_event_queue_n >= g_event_queue_cap) {
        uint32_t nc = g_event_queue_cap * 2 + 2;
        if (nc > 256) nc = 256;
        if (nc <= g_event_queue_cap) return;
        GameEvent* ne = (GameEvent*)xrealloc(g_event_queue, nc * sizeof(GameEvent));
        if (!ne) return;
        g_event_queue = ne;
        g_event_queue_cap = nc;
    }
    GameEvent* e = &g_event_queue[g_event_queue_n++];
    e->kind = kind;
    e->actor = actor;
    e->target = target;
    e->pos = pos;
    e->magnitude = magnitude;
    e->extra = extra;
    e->time = (float)time_get();
    e->broadcast = 1;
}

static void faction_system_init(void) {
    memset(g_player_reputation, 0, sizeof(g_player_reputation));
    memset(g_faction_war, 0, sizeof(g_faction_war));
    memset(g_zone_faction, 0xFF, sizeof(g_zone_faction));
    for (uint32_t i = 0; i < FACTION_COUNT; i++) {
        snprintf(g_faction_names[i], sizeof(g_faction_names[i]), "Faction-%u", i);
        for (uint32_t j = 0; j < FACTION_COUNT; j++)
            g_faction_relations[i][j] = (i == j) ? 1.f : 0.f;
    }
    g_faction_count = 0;
}

static uint32_t faction_register(const char* name) {
    if (g_faction_count >= FACTION_COUNT) return UINT32_MAX;
    uint32_t id = g_faction_count++;
    if (name) {
        strncpy(g_faction_names[id], name, 31);
        g_faction_names[id][31] = '\0';
    }
    return id;
}

static int32_t player_rep_get(uint32_t fid) {
    return (fid < FACTION_COUNT) ? g_player_reputation[fid] : 0;
}

static void player_rep_add(uint32_t fid, int32_t delta) {
    if (fid >= FACTION_COUNT) return;
    int32_t r = g_player_reputation[fid] + delta;
    if (r > REP_MAX) r = REP_MAX;
    if (r < REP_MIN) r = REP_MIN;
    g_player_reputation[fid] = r;
}

static RegimeData* faction_local_regime(uint32_t fid) {
    for (uint32_t i = 0; i < g_type_count[ET_REGIME]; i++) {
        uint32_t slot = g_type_slots[ET_REGIME][i];
        if (!g_alive[slot]) continue;
        RegimeData* rd = (RegimeData*)entity_side_ptr(slot);
        if (rd && (rd->flags & 0xFF) == fid) return rd;
    }
    return NULL;
}

static int faction_local_regime_is_hostile(uint32_t fid) {
    return player_rep_get(fid) < -20;
}

static void faction_on_kill_real(const Thing* t) {
    if (!t) return;
    uint32_t victim = 0xFF;
    switch (t->type) {
        case ET_PIRATE: victim = ENT_I(t, 1) & 0xFF; break;
        case ET_ALIEN:  victim = ENT_I(t, 1) & 0xFF; break;
        default: return;
    }
    if (victim >= g_faction_count) return;
    player_rep_add(victim, -50);
    for (uint32_t f = 0; f < g_faction_count; f++)
        if (f != victim && g_faction_war[f][victim]) player_rep_add(f, 30);
}

static ConsensusView consensus_compute_faction(uint32_t faction) {
    ConsensusView v;
    memset(&v, 0, sizeof(v));
    int32_t raw = 0;
    uint32_t count = 0;
    float fear_acc = 0.f, awe_acc = 0.f;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        Thing* t = &g_things[i];
        if (t->type != ET_CREW && t->type != ET_SHIP) continue;
        NpcProfile* prof = npc_profile_get(i);
        if (!prof) continue;
        if (faction != 0xFFFFFFFFu && prof->faction != faction) continue;
        raw += prof->rep_with_player;
        count++;
        NpcNeeds* needs = npc_needs_get(i);
        if (needs) {
            fear_acc += needs->vitals.stress;
            awe_acc  += (prof->rep_with_player > 200) ? 1.f : 0.f;
        }
    }
    v.raw_rep   = raw;
    v.npc_count = count;
    v.effective = (count > 0) ? (raw / (int32_t)(1 + count / 4)) : 0;
    v.trust = (count > 0) ? clampf((float)v.effective / 500.f + 0.5f, 0.f, 1.f) : 0.5f;
    v.fear  = (count > 0) ? clampf(fear_acc / (float)count, 0.f, 1.f) : 0.f;
    v.awe   = (count > 0) ? clampf(awe_acc / (float)count, 0.f, 1.f) : 0.f;
    v.valid = 1;
    return v;
}

static const PlayerConsensus* player_consensus_get(void) {
    if (!g_player_consensus.valid || g_player_consensus_dirty) {
        g_player_consensus.global = consensus_compute_faction(0xFFFFFFFFu);
        for (uint32_t f = 0; f < FACTION_COUNT; f++)
            g_player_consensus.by_faction[f] = consensus_compute_faction(f);
        const ConsensusView* gv = &g_player_consensus.global;
        g_player_consensus.price_multiplier   = clampf(1.2f - gv->trust * 0.4f, 0.5f, 2.0f);
        g_player_consensus.repair_speed_mult  = clampf(0.5f + gv->trust * 1.5f, 0.5f, 2.0f);
        g_player_consensus.mission_difficulty = clampf(1.2f - gv->trust * 0.4f, 0.5f, 2.0f);
        g_player_consensus.betrayal_risk      = clampf((1.f - gv->trust) * 0.5f + gv->fear * 0.3f, 0.f, 1.f);
        g_player_consensus.valid = 1;
        g_player_consensus_dirty = 0;
    }
    return &g_player_consensus;
}

static void consensus_mark_dirty(void) { g_player_consensus_dirty = 1; }

static V3 walk_forward_dir(float yaw, float pitch) {
    float cy = cosf(yaw),   sy = sinf(yaw);
    float cp = cosf(pitch), sp = sinf(pitch);
    return v3(sy * cp, sp, -cy * cp);
}

static float walker_eye_bob(WalkerState* w) {
    if (!w->grounded) return 0.f;
    return sinf(w->bob_phase) * w->bob_amp;
}

static void move_integrate(Thing* t, V3 accel, float max_speed, float drag, float dt) {
    if (!t || dt <= 0.f) return;
    t->vel = v3add(t->vel, v3mul(accel, dt));
    if (drag > 0.f) t->vel = v3mul(t->vel, 1.f - drag * dt);
    if (max_speed > 0.f) {
        float sp = v3len(t->vel);
        if (sp > max_speed) t->vel = v3mul(t->vel, max_speed / sp);
    }
    t->pos = v3add(t->pos, v3mul(t->vel, dt));
}

static void move_tick_ship(Thing* t, const Intent* i, const ShipData* sd, float dt) {
    if (!t || !i || !sd || dt <= 0.f) return;
    t->rot += i->look_dx * 0.0025f;
    float pitch = ENT_F(t, 24) - i->look_dy * 0.0025f;
    pitch = clampf(pitch, -1.30f, 1.30f);
    ENT_SET_F(t, 24, pitch);
    if (!i->boost) {
        if (i->strafe < -0.5f) t->rot += sd->turn_rate * dt;
        if (i->strafe >  0.5f) t->rot -= sd->turn_rate * dt;
    }
    V3 fwd   = v3(sinf(t->rot) * cosf(pitch), sinf(pitch), -cosf(t->rot) * cosf(pitch));
    V3 right = v3(cosf(t->rot), 0.f, sinf(t->rot));
    V3 up    = v3norm(v3cross(right, fwd));
    float base = sd->accel;
    if (i->boost)   base *= 1.8f;
    if (i->evasive) base *= (1.f + g_xp_b7.perk_evasive * 0.25f);
    V3 accel = v3zero();
    accel = v3add(accel, v3mul(fwd, i->throttle * base));
    accel = v3add(accel, v3mul(up, i->move_dir.y * base * 0.5f));
    accel = v3add(accel, v3mul(right, i->strafe * base * 0.8f));
    if (i->boost && i->strafe != 0.f && sd->energy > 2.f) {
        float lateral = base * 1.2f;
        accel = v3add(accel, v3mul(right, lateral * i->strafe));
        ShipData* sd_mut = (ShipData*)sd;
        sd_mut->energy -= 15.f * dt;
        if (sd_mut->energy < 0.f) sd_mut->energy = 0.f;
    }
    float max_speed = sd->max_speed * (1.f + g_xp_b7.perk_speed * 0.04f);
    if (i->boost) max_speed *= 1.4f;
    move_integrate(t, accel, max_speed, i->brake ? 5.f : 0.f, dt);
    if (i->throttle > 0.f) {
        ShipData* sd_mut = (ShipData*)sd;
        sd_mut->fuel -= sd_mut->fuel_consumption * dt;
        if (sd_mut->fuel < 0.f) sd_mut->fuel = 0.f;
    }
}

static void move_tick_drone(Thing* t, const Intent* i, float dt) {
    if (!t || !i || dt <= 0.f) return;
    t->rot -= i->look_dx * 0.0025f;
    V3 fwd   = v3(sinf(t->rot), 0.f, -cosf(t->rot));
    V3 right = v3(cosf(t->rot), 0.f, sinf(t->rot));
    V3 accel = v3zero();
    accel = v3add(accel, v3mul(fwd,   i->throttle * 40.f));
    accel = v3add(accel, v3mul(right, i->strafe   * 40.f));
    accel.y += i->move_dir.y * 40.f;
    move_integrate(t, accel, 25.f, 2.f, dt);
}

static void walker_apply_inertia(WalkerState* w, uint32_t slot, float dt) {
    if (!w || dt <= 0.f || w->grounded) return;
    Thing* ship = entity_get(slot);
    if (!ship) return;
    V3 ship_accel_world = v3mul(v3sub(ship->vel, w->last_ship_vel_world), 1.f / dt);
    V3 ship_accel_local = world_dir_to_local(slot, ship_accel_world);
    w->vel_local = v3sub(w->vel_local, v3mul(ship_accel_local, INERTIA_COEF * dt));
}

static void walker_apply_centrifugal(WalkerState* w, uint32_t slot, float dt) {
    if (!w || w->grounded) return;
    Thing* ship = entity_get(slot);
    if (!ship) return;
    float d_rot = ship->rot - w->last_ship_rot;
    if (fabsf(d_rot) <= 0.001f) return;
    float omega = d_rot / dt;
    V3 radial = v3(w->pos_local.x, 0.f, w->pos_local.z);
    float rl = v3len(radial);
    if (rl <= 0.05f) return;
    V3 outward = v3mul(radial, 1.f / rl);
    float cf = omega * omega * rl * CENTRIFUGAL_COEF;
    if (cf > 8.f) cf = 8.f;
    w->vel_local = v3add(w->vel_local, v3mul(outward, cf * dt));
}

static void walker_apply_shake(WalkerState* w, float dt) {
    if (!w) return;
    if (g_game.shake <= 0.01f) return;
    float s = g_game.shake * SHAKE_COEF;
    if (w->grounded) {
        w->hurt_shake = fminf(w->hurt_shake + s * 0.4f * dt, 1.f);
        return;
    }
    float t = (float)time_get();
    float sx = (sinf(t * 45.f) * 0.7f + sinf(t * 67.f + 1.1f) * 0.3f) * s;
    float sy = (sinf(t * 30.f + 2.3f) * 0.6f + sinf(t * 51.f) * 0.4f) * s * 0.5f;
    float sz = (sinf(t * 38.f + 0.7f) * 0.65f + sinf(t * 55.f + 3.5f) * 0.35f) * s * 0.8f;
    w->vel_local = v3add(w->vel_local, v3(sx * dt, sy * dt, sz * dt));
    w->hurt_shake = fminf(w->hurt_shake + s * 0.3f * dt, 1.f);
}

static void walker_apply_gravity(WalkerState* w, float dt) {
    if (!w || w->grounded) return;
    if (g_player.inside_ship == UINT32_MAX) return;
    Thing* ship = entity_get(g_player.inside_ship);
    if (!ship) return;
    V3 wp = local_to_world_pos(g_player.inside_ship, w->pos_local);
    const float RANGE = 500.f;
    const float MASS_MIN = 1.f;
    const float G_MAX = g_tuning.walker_gravity * 4.f;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(wp, RANGE, g_things_cap, &nearby);
    for (uint32_t k = 0; k < n; k++) {
        if (nearby[k] == g_player.inside_ship) continue;
        Thing* t = &g_things[nearby[k]];
        if (t->type != ET_STAR || t->mass < MASS_MIN) continue;
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        V3 d = v3sub(t->pos, wp);
        float r2 = v3lensq(d);
        if (r2 < 4.f) continue;
        float r = sqrtf(r2);
        float g_acc = g_tuning.walker_gravity * (t->mass / 1000.f) / r2;
        if (g_acc > G_MAX) g_acc = G_MAX;
        V3 dir_local = world_dir_to_local(g_player.inside_ship, v3mul(d, 1.f / r));
        w->vel_local = v3add(w->vel_local, v3mul(dir_local, g_acc * dt));
    }
    sh_scratch_release();
    for (uint32_t k = 0; k < g_things_cap; k++) {
        if (!g_alive[k]) continue;
        if (g_things[k].type != ET_ANOMALY) continue;
        if (ENT_I(&g_things[k], 0) != ANOMALY_TYPE_ATTRACTOR) continue;
        if (g_things[k].flags & ENT_FLAG_MARKED_DEAD) continue;
        V3 d = v3sub(g_things[k].pos, wp);
        float r2 = v3lensq(d);
        if (r2 < 4.f || r2 > RANGE * RANGE) continue;
        float r = sqrtf(r2);
        float g_acc = g_tuning.walker_gravity * 1.5f * 100.f / r2;
        if (g_acc > G_MAX) g_acc = G_MAX;
        V3 dir_local = world_dir_to_local(g_player.inside_ship, v3mul(d, 1.f / r));
        w->vel_local = v3add(w->vel_local, v3mul(dir_local, g_acc * dt));
    }
}

static V3 walker_apply_floor(WalkerState* w, uint32_t slot, V3 next, float dt) {
    int has_floor = 0;
    float fy = floor_y_at(slot, next.x, next.z, &has_floor);
    if (!has_floor) { w->grounded = 0; return next; }
    float dist = next.y - fy;
    if (dist <= 0.02f) {
        next.y = fy;
        if (w->vel_local.y < 0.f) w->vel_local.y = 0.f;
        w->grounded = 1;
    } else if (w->vel_local.y < 0.f && dist < 0.3f) {
        next.y = fy;
        w->vel_local.y = 0.f;
        w->grounded = 1;
    } else {
        w->grounded = 0;
        w->vel_local.y -= g_tuning.walker_gravity * dt;
        if (w->vel_local.y < -30.f) w->vel_local.y = -30.f;
    }
    return next;
}

static void walker_decay_hurt_shake(WalkerState* w) {
    if (!w || w->hurt_shake <= 0.001f) return;
    w->hurt_shake *= 0.88f;
    if (w->hurt_shake < 0.005f) w->hurt_shake = 0.f;
}

static void player_apply_crouch(WalkerState* w, int crouching, float dt) {
    if (!w || dt <= 0.f) return;
    float target_eye   = crouching ? WALKER_EYE_CROUCH : WALKER_EYE_STAND;
    float target_blend = crouching ? 1.f : 0.f;
    float k_eye   = 1.f - expf(-12.f * dt);
    float k_blend = 1.f - expf(-18.f * dt);
    w->eye_height   += (target_eye   - w->eye_height)   * k_eye;
    w->crouch_blend += (target_blend - w->crouch_blend) * k_blend;
    if (w->crouch_blend < 0.005f) w->crouch_blend = 0.f;
    if (w->crouch_blend > 0.995f) w->crouch_blend = 1.f;
}

static void player_apply_bob(WalkerState* w, int crouching, float dt) {
    if (!w || dt <= 0.f) return;
    float speed_h2 = w->vel_local.x * w->vel_local.x + w->vel_local.z * w->vel_local.z;
    float speed_h  = sqrtf(speed_h2);
    float ref_speed = g_tuning.walker_speed;
    if (ref_speed < 0.1f) ref_speed = 0.1f;
    float speed_norm = clampf(speed_h / ref_speed, 0.f, 1.5f);
    if (speed_h > 0.01f && w->grounded) {
        float freq = 8.f + speed_norm * 4.f;
        w->bob_phase += dt * freq;
        float base_amp = 0.03f + speed_norm * 0.03f;
        if (crouching) base_amp *= 0.4f;
        if (w->aiming) base_amp *= 0.5f;
        w->bob_amp += (base_amp - w->bob_amp) * clampf(dt * 10.f, 0.f, 1.f);
    } else {
        w->bob_amp *= 0.88f;
        if (w->bob_amp < 0.001f) w->bob_amp = 0.f;
    }
}

static void gravity_sample_local(uint32_t slot, V3 p, GravSample* out);


/* ═══════════════════════════════════════════════════════════════════════
   HUMANOID MORPHOLOGY IMPLEMENTATION
   mannequin ⊕ stacked causes → bake → gait / needs / designation
   ═══════════════════════════════════════════════════════════════════════ */

static const int8_t g_hp_parent[HP_COUNT] = {
    /* PELVIS */ -1,
    /* TORSO  */ HP_PELVIS,
    /* CHEST  */ HP_TORSO,
    /* NECK   */ HP_CHEST,
    /* HEAD   */ HP_NECK,
    /* LEG_L  */ HP_PELVIS,
    /* LEG_R  */ HP_PELVIS,
    /* FOOT_L */ HP_LEG_L,
    /* FOOT_R */ HP_LEG_R,
    /* ARM_L  */ HP_CHEST,
    /* ARM_R  */ HP_CHEST,
    /* HAND_L */ HP_ARM_L,
    /* HAND_R */ HP_ARM_R
};

static void humanoid_part_reset(HumanoidPart* p, HumanoidPartId id) {
    memset(p, 0, sizeof(*p));
    p->id = (uint8_t)id;
    p->parent = g_hp_parent[id];
    p->present = 1;
    p->integrity = 1.f;
    p->mass_scale = 1.f;
    p->joint_limit = 1.f;
    p->cavity_n = 0;
    p->mutation_n = 0;
    p->ports = 0;
    if (id == HP_HEAD) { p->cavity_n = 4; p->ports = 1; }
    if (id == HP_CHEST) p->ports = 2;
    if (id == HP_HAND_L || id == HP_HAND_R) p->ports = 1;
}

static void humanoid_mannequin(HumanoidMorph* h, uint32_t seed, SpeciesKind sp) {
    if (!h) return;
    memset(h, 0, sizeof(*h));
    h->entity_slot = UINT32_MAX;
    h->seed = seed;
    h->species = (uint8_t)sp;
    h->designation = HDES_STOCK;
    h->part_n = (uint8_t)HP_COUNT;
    for (int i = 0; i < HP_COUNT; i++)
        humanoid_part_reset(&h->parts[i], (HumanoidPartId)i);
    h->attach_n = 0;
    h->power_budget = 0.f;
    h->gait_speed_mul = 1.f;
    h->gait_limp = 0.f;
    h->fat_scale = 1.f;
    h->soft_mass = 70.f;
    snprintf(h->label, sizeof(h->label), "stock");
    /* canonical vitals */
    h->vital_n = 4;
    h->vitals[0] = (HumanoidVital){ HVITAL_AIRWAY, 1, 0.15f, HP_HEAD };
    h->vitals[1] = (HumanoidVital){ HVITAL_NEURAL, 1, 0.20f, HP_HEAD };
    h->vitals[2] = (HumanoidVital){ HVITAL_CIRCULATORY, 1, 0.15f, HP_CHEST };
    h->vitals[3] = (HumanoidVital){ HVITAL_LOCOMOTOR, 1, 0.10f, HP_PELVIS };
    h->baked = 0;
}

static int humanoid_cause_push(HumanoidMorph* h, HumanoidCause c) {
    if (!h || h->causes.count >= HUMANOID_CAUSE_MAX) return 0;
    if (c.magnitude < 0.f) c.magnitude = 0.f;
    if (c.magnitude > 1.f) c.magnitude = 1.f;
    h->causes.items[h->causes.count++] = c;
    h->baked = 0;
    return 1;
}

static void humanoid_cause_push_kv(HumanoidMorph* h, HumanoidCauseKind kind,
                                    HumanoidTag tag, HumanoidPartId bias,
                                    float mag) {
    HumanoidCause c;
    c.kind = (uint8_t)kind;
    c.tag = (uint8_t)tag;
    c.part_bias = (uint8_t)bias;
    c._pad = 0;
    c.magnitude = mag;
    c.age = 0.f;
    humanoid_cause_push(h, c);
}

static float humanoid_stack_tag(const HumanoidMorph* h, HumanoidTag tag) {
    float s = 0.f;
    for (uint8_t i = 0; i < h->causes.count; i++)
        if (h->causes.items[i].tag == (uint8_t)tag)
            s += h->causes.items[i].magnitude;
    return s;
}

static HumanoidPart* humanoid_part(HumanoidMorph* h, HumanoidPartId id) {
    if (!h || (int)id < 0 || id >= h->part_n) return NULL;
    return &h->parts[id];
}


static int humanoid_attach_add(HumanoidMorph* h, const HumanoidAttachment* src) {
    if (!h || !src || h->attach_n >= HUMANOID_ATTACH_MAX) return -1;
    if (src->socket >= h->part_n && src->socket >= HP_COUNT) return -1;
    h->attach[h->attach_n] = *src;
    if (h->attach[h->attach_n].origin_n == 0) {
        h->attach[h->attach_n].origin_n = 1;
        h->attach[h->attach_n].origins[0] = HORIG_ROBOTIC;
        h->attach[h->attach_n].origin_w[0] = 8;
    }
    if (h->attach[h->attach_n].integrity <= 0.f)
        h->attach[h->attach_n].integrity = 1.f;
    h->attach_n++;
    h->baked = 0;
    return (int)h->attach_n - 1;
}

/* Outfit prosthesis: external, low invasion, removable conceptually. */
static int humanoid_attach_outfit_limb(HumanoidMorph* h, HumanoidPartId socket,
                                        HumanoidOrigin origin, const char* tag) {
    HumanoidAttachment a;
    memset(&a, 0, sizeof(a));
    a.tier = HATT_OUTFIT;
    a.control = HCTRL_MOTOR;
    a.socket = (uint8_t)socket;
    a.origin_n = 1;
    a.origins[0] = (uint8_t)origin;
    a.origin_w[0] = 10;
    a.replaces_limb = 1;
    a.invasive_depth = 0;
    a.integrity = 1.f;
    a.integration = 0.35f; /* strapped, not fused */
    a.mass_kg = 4.5f;
    a.power_draw = (origin == HORIG_ROBOTIC || origin == HORIG_COMPUTE_SIM) ? 0.4f : 0.f;
    a.ports_bonus = (origin == HORIG_ROBOTIC) ? 2 : 0;
    if (tag) snprintf(a.tag, sizeof(a.tag), "%.15s", tag);
    else snprintf(a.tag, sizeof(a.tag), "outfit_limb");
    return humanoid_attach_add(h, &a);
}

/* Invasive assimilation: graft / symbiont / frankenstein / hybrid. */
static int humanoid_attach_assimilate(HumanoidMorph* h, HumanoidPartId socket,
                                       HumanoidControlMode ctrl,
                                       const uint8_t* origins, const uint8_t* weights,
                                       int origin_n, int depth, uint32_t donor_seed,
                                       const char* tag, int tentacle) {
    HumanoidAttachment a;
    memset(&a, 0, sizeof(a));
    a.tier = HATT_ASSIMILATION;
    a.control = (uint8_t)ctrl;
    a.socket = (uint8_t)socket;
    a.origin_n = 0;
    for (int i = 0; i < origin_n && i < HUMANOID_ORIGIN_MAX; i++) {
        a.origins[a.origin_n] = origins[i];
        a.origin_w[a.origin_n] = weights ? weights[i] : 8;
        a.origin_n++;
    }
    if (a.origin_n == 0) {
        a.origin_n = 1; a.origins[0] = HORIG_BIOLOGIC; a.origin_w[0] = 8;
    }
    a.replaces_limb = 1;
    a.invasive_depth = (uint8_t)clampf((float)depth, 0.f, 3.f);
    a.integrity = 0.85f;
    a.integration = 0.55f + 0.12f * (float)a.invasive_depth;
    a.mass_kg = tentacle ? 3.2f : 5.0f;
    a.power_draw = 0.f;
    for (int i = 0; i < a.origin_n; i++) {
        if (a.origins[i] == HORIG_ROBOTIC || a.origins[i] == HORIG_COMPUTE_SIM)
            a.power_draw += 0.25f * (float)a.origin_w[i] / 10.f;
        if (a.origins[i] == HORIG_SYMBIONT)
            a.control = HCTRL_SYMBIOTIC;
    }
    a.ports_bonus = (ctrl == HCTRL_BEHAVIOR_SIM || ctrl == HCTRL_MOTOR) ? 1 : 0;
    a.flags = tentacle ? 1u : 0u;
    if (ctrl == HCTRL_BEHAVIOR_SIM) a.flags |= 4u; /* donor_trace */
    a.donor_seed = donor_seed;
    if (tag) snprintf(a.tag, sizeof(a.tag), "%.15s", tag);
    else snprintf(a.tag, sizeof(a.tag), "assimilate");
    return humanoid_attach_add(h, &a);
}

static int humanoid_attach_remove(HumanoidMorph* h, int idx) {
    if (!h || idx < 0 || idx >= h->attach_n) return 0;
    HumanoidAttachment* a = &h->attach[idx];
    /* Outfit can always come off; assimilation only if integration low */
    if (a->tier == HATT_ASSIMILATION && a->integration > 0.75f)
        return 0; /* too fused — needs surgical regress */
    h->attach[idx] = h->attach[h->attach_n - 1];
    h->attach_n--;
    h->baked = 0;
    return 1;
}

static void humanoid_apply_attachments(HumanoidMorph* h) {
    if (!h) return;
    h->power_budget = 0.f;
    for (uint8_t i = 0; i < h->part_n; i++)
        h->parts[i].prosthetic = 0;

    for (uint8_t i = 0; i < h->attach_n; i++) {
        HumanoidAttachment* a = &h->attach[i];
        if (a->socket >= h->part_n) continue;
        HumanoidPart* p = &h->parts[a->socket];
        h->power_budget += a->power_draw;

        if (a->replaces_limb) {
            p->present = 1;
            p->prosthetic = 1;
            p->integrity = clampf(fmaxf(p->integrity, a->integrity * a->integration), 0.05f, 1.f);
            /* control quality affects joint */
            float ctrl_q = 0.55f;
            switch (a->control) {
            case HCTRL_MOTOR:        ctrl_q = 0.9f; break;
            case HCTRL_SYMBIOTIC:    ctrl_q = 0.8f; break;
            case HCTRL_BEHAVIOR_SIM: ctrl_q = 0.7f; break;
            case HCTRL_AUTONOMOUS:   ctrl_q = 0.6f; break;
            default: ctrl_q = 0.4f; break;
            }
            if (a->tier == HATT_OUTFIT) ctrl_q *= 0.92f;
            p->joint_limit = clampf(fmaxf(p->joint_limit, ctrl_q * a->integrity), 0.05f, 1.f);
            p->mass_scale = clampf(a->mass_kg / 5.f, 0.5f, 2.5f);
            p->ports = (uint8_t)clampf((float)p->ports + (float)a->ports_bonus, 0.f, 6.f);
            /* restore children soft presence for feet/hands if parent replaced */
            for (int k = 0; k < h->part_n; k++) {
                if (h->parts[k].parent == (int8_t)p->id && !h->parts[k].present) {
                    h->parts[k].present = 1;
                    h->parts[k].integrity = 0.6f * a->integrity;
                    h->parts[k].joint_limit = 0.7f;
                    h->parts[k].prosthetic = 1;
                }
            }
        } else {
            /* additive (tentacle beside arm, sensor stalk, etc.) */
            p->mutation_n = (uint8_t)clampf((float)p->mutation_n + 1.f, 0.f, 8.f);
            p->ports = (uint8_t)clampf((float)p->ports + (float)a->ports_bonus, 0.f, 6.f);
            if (a->flags & 1u) /* tentacle */
                p->cavity_n = (uint8_t)(p->cavity_n + 1);
        }

        /* assimilation deep → dependency / filter needs */
        if (a->tier == HATT_ASSIMILATION && a->invasive_depth >= 2) {
            humanoid_cause_push_kv(h, HCAUSE_CYBER, HTAG_DEPENDENCY, (HumanoidPartId)a->socket,
                                   0.25f * (float)a->invasive_depth);
        }
        /* donor behavior sim leaves identity noise */
        if (a->control == HCTRL_BEHAVIOR_SIM && a->donor_seed)
            h->tag_stack[HTAG_AUGMENT] += 0.15f;
    }
}

static void humanoid_bake(HumanoidMorph* h) {
    if (!h) return;
    /* reset phenotype soft fields toward mannequin */
    for (int i = 0; i < h->part_n; i++) {
        HumanoidPart* p = &h->parts[i];
        if (!p->prosthetic) {
            p->present = 1;
            p->integrity = 1.f;
            p->mass_scale = 1.f;
            p->joint_limit = 1.f;
            p->mutation_n = 0;
        }
    }
    for (int t = 0; t < HTAG_COUNT; t++)
        h->tag_stack[t] = humanoid_stack_tag(h, (HumanoidTag)t);

    /* apply each cause */
    for (uint8_t i = 0; i < h->causes.count; i++) {
        HumanoidCause* c = &h->causes.items[i];
        float m = c->magnitude;
        int bias = (c->part_bias < h->part_n) ? (int)c->part_bias : -1;
        HumanoidPart* p = (bias >= 0) ? &h->parts[bias] : NULL;

        switch ((HumanoidTag)c->tag) {
        case HTAG_LIMP:
            if (!p) p = &h->parts[HP_LEG_L];
            p->joint_limit = clampf(p->joint_limit - 0.35f * m, 0.1f, 1.f);
            p->integrity   = clampf(p->integrity   - 0.20f * m, 0.05f, 1.f);
            break;
        case HTAG_FAT_PAD:
            h->fat_scale = clampf(h->fat_scale + 0.25f * m, 0.7f, 2.2f);
            h->soft_mass = 70.f * h->fat_scale;
            h->parts[HP_TORSO].mass_scale = h->fat_scale;
            h->parts[HP_PELVIS].mass_scale = 0.9f + 0.1f * h->fat_scale;
            break;
        case HTAG_MISSING_LIMB:
            if (!p) p = &h->parts[HP_LEG_R];
            p->present = 0;
            p->integrity = 0.f;
            p->joint_limit = 0.f;
            /* children feet/hands */
            for (int k = 0; k < h->part_n; k++)
                if (h->parts[k].parent == (int8_t)p->id) {
                    h->parts[k].present = 0;
                    h->parts[k].integrity = 0.f;
                }
            break;
        case HTAG_MISSING_DIGIT:
            if (!p) p = &h->parts[HP_HAND_R];
            p->integrity = clampf(p->integrity - 0.15f * m, 0.2f, 1.f);
            break;
        case HTAG_EXTRA_SENSOR:
            if (!p) p = &h->parts[HP_HEAD];
            p->mutation_n = (uint8_t)clampf((float)p->mutation_n + 1.f + m, 0.f, 6.f);
            p->cavity_n = (uint8_t)(p->cavity_n + 1);
            break;
        case HTAG_FUSED_JOINT:
            if (!p) p = &h->parts[HP_LEG_L];
            p->joint_limit = clampf(p->joint_limit - 0.5f * m, 0.05f, 1.f);
            break;
        case HTAG_CHRONIC_PAIN:
            if (p) p->integrity = clampf(p->integrity - 0.1f * m, 0.1f, 1.f);
            break;
        case HTAG_AUGMENT:
            /* causes only queue intent; real limb comes from Attachment (outfit or assimilation) */
            if (!p) p = &h->parts[HP_ARM_R];
            p->present = 1;
            break;
        case HTAG_DEPENDENCY:
            /* marks vitals / filter need — handled below */
            break;
        default: break;
        }
    }

    /* gait from legs */
    {
        HumanoidPart* ll = &h->parts[HP_LEG_L];
        HumanoidPart* lr = &h->parts[HP_LEG_R];
        float jl = (ll->present ? ll->joint_limit * ll->integrity : 0.f);
        float jr = (lr->present ? lr->joint_limit * lr->integrity : 0.f);
        float both = jl + jr;
        h->gait_speed_mul = clampf(0.35f + 0.65f * (both * 0.5f), 0.25f, 1.15f);
        h->gait_limp = clampf(fabsf(jl - jr), 0.f, 1.f);
        if (!ll->present || !lr->present)
            h->gait_speed_mul = clampf(h->gait_speed_mul * 0.55f, 0.2f, 1.f);
        if (h->fat_scale > 1.2f)
            h->gait_speed_mul *= clampf(1.4f - 0.25f * h->fat_scale, 0.7f, 1.f);
    }

    /* vitals check */
    for (uint8_t i = 0; i < h->vital_n; i++) {
        HumanoidVital* v = &h->vitals[i];
        if (v->anchor_part < 0 || v->anchor_part >= h->part_n) {
            v->ok = 1; continue;
        }
        HumanoidPart* ap = &h->parts[v->anchor_part];
        float score = ap->present ? ap->integrity : 0.f;
        if (ap->prosthetic && score > 0.3f) score = fmaxf(score, 0.7f);
        v->ok = (score >= v->min_integrity) ? 1 : 0;
    }
    if (h->tag_stack[HTAG_DEPENDENCY] > 0.4f) {
        /* add filter vital if missing */
        int has_f = 0;
        for (uint8_t i = 0; i < h->vital_n; i++)
            if (h->vitals[i].id == HVITAL_FILTER) has_f = 1;
        if (!has_f && h->vital_n < HUMANOID_VITAL_MAX) {
            h->vitals[h->vital_n++] = (HumanoidVital){ HVITAL_FILTER, 0, 0.5f, HP_CHEST };
        }
    }

    humanoid_apply_attachments(h);

    /* designation from stacks (priority: ballast > mutant > medical > aug > labor > stock) */
    h->designation = HDES_STOCK;
    if (h->tag_stack[HTAG_LIMP] < 0.35f && h->fat_scale < 1.35f &&
        h->parts[HP_LEG_L].present && h->parts[HP_LEG_R].present)
        h->designation = HDES_LABOR_FIT;
    if (h->tag_stack[HTAG_AUGMENT] > 0.5f || h->attach_n > 0)
        h->designation = HDES_AUGMENTED;
    if (h->tag_stack[HTAG_MISSING_LIMB] > 0.3f || h->tag_stack[HTAG_CHRONIC_PAIN] > 0.8f)
        h->designation = HDES_MEDICAL;
    if (h->tag_stack[HTAG_EXTRA_SENSOR] > 0.6f)
        h->designation = HDES_MUTANT;
    for (uint8_t i = 0; i < h->vital_n; i++)
        if (!h->vitals[i].ok) { h->designation = HDES_BALLAST; break; }

    h->baked = 1;
}

/* Fix the bogus line I almost left - rewrite designation section cleanly via second pass if needed */

static void humanoid_regress(HumanoidMorph* h, float amount) {
    if (!h || amount <= 0.f) return;
    for (uint8_t i = 0; i < h->causes.count; i++) {
        h->causes.items[i].magnitude = clampf(
            h->causes.items[i].magnitude * (1.f - amount), 0.f, 1.f);
    }
    /* drop near-zero causes */
    uint8_t w = 0;
    for (uint8_t i = 0; i < h->causes.count; i++) {
        if (h->causes.items[i].magnitude > 0.04f)
            h->causes.items[w++] = h->causes.items[i];
    }
    h->causes.count = w;
    h->baked = 0;
    humanoid_bake(h);
}

static void humanoid_apply_template(HumanoidMorph* h, const HumanoidTemplate* tpl, uint32_t seed) {
    if (!h || !tpl) return;
    humanoid_mannequin(h, seed, (SpeciesKind)tpl->species);
    for (uint8_t i = 0; i < tpl->cause_n; i++)
        humanoid_cause_push(h, tpl->causes[i]);
    if (tpl->policy == HTPL_POLYMORPHIC && tpl->noise > 0.f) {
        /* deterministic jitter from seed */
        uint32_t s = seed ? seed : 1u;
        for (int k = 0; k < 3; k++) {
            s = s * 1664525u + 1013904223u;
            float r = (float)(s & 0xffff) / 65535.f;
            HumanoidCauseKind ck = (HumanoidCauseKind)(s % HCAUSE_COUNT);
            HumanoidTag tg = (HumanoidTag)((s >> 3) % HTAG_COUNT);
            HumanoidPartId bias = (HumanoidPartId)((s >> 7) % HP_COUNT);
            float mag = tpl->noise * (0.15f + 0.85f * r);
            if (tg == HTAG_MISSING_LIMB && mag < 0.55f) continue; /* rare */
            humanoid_cause_push_kv(h, ck, tg, bias, mag);
        }
    }
    /* template-specific attachments (outfit vs assimilation) */
    if (tpl->name) {
        if (strcmp(tpl->name, "combat_amputee") == 0) {
            humanoid_cause_push_kv(h, HCAUSE_COMBAT, HTAG_MISSING_LIMB, HP_LEG_R, 1.f);
            humanoid_attach_outfit_limb(h, HP_LEG_R, HORIG_ROBOTIC, "servo_leg");
        } else if (strcmp(tpl->name, "aug_pilot") == 0) {
            humanoid_attach_outfit_limb(h, HP_ARM_R, HORIG_ROBOTIC, "pilot_arm");
            {
                uint8_t o[] = { HORIG_ROBOTIC, HORIG_COMPUTE_SIM };
                uint8_t w[] = { 6, 10 };
                humanoid_attach_assimilate(h, HP_HEAD, HCTRL_BEHAVIOR_SIM, o, w, 2, 2,
                                           seed ^ 0xA11Eu, "neuro_link", 0);
            }
        } else if (strcmp(tpl->name, "symbiont_tentacle") == 0) {
            humanoid_cause_push_kv(h, HCAUSE_FAUNA, HTAG_MISSING_LIMB, HP_ARM_L, 1.f);
            {
                uint8_t o[] = { HORIG_SYMBIONT, HORIG_BIOLOGIC };
                uint8_t w[] = { 12, 5 };
                humanoid_attach_assimilate(h, HP_ARM_L, HCTRL_SYMBIOTIC, o, w, 2, 2,
                                           seed, "tentacle", 1);
            }
        } else if (strcmp(tpl->name, "franken_graft") == 0) {
            humanoid_cause_push_kv(h, HCAUSE_ACCIDENT, HTAG_MISSING_LIMB, HP_ARM_R, 1.f);
            {
                uint8_t o[] = { HORIG_GRAFT_HUMAN, HORIG_ROBOTIC };
                uint8_t w[] = { 9, 4 };
                humanoid_attach_assimilate(h, HP_ARM_R, HCTRL_BEHAVIOR_SIM, o, w, 2, 3,
                                           seed ^ 0xDEADU, "graft_arm", 0);
            }
        } else if (strcmp(tpl->name, "hybrid_chimera") == 0) {
            humanoid_cause_push_kv(h, HCAUSE_RADIATION, HTAG_MISSING_LIMB, HP_LEG_L, 1.f);
            {
                uint8_t o[] = { HORIG_HYBRID, HORIG_GRAFT_ALIEN, HORIG_ROBOTIC };
                uint8_t w[] = { 8, 5, 3 };
                humanoid_attach_assimilate(h, HP_LEG_L, HCTRL_AUTONOMOUS, o, w, 3, 2,
                                           seed, "chimera_leg", 0);
            }
        }
    }
    humanoid_bake(h);
    if (tpl->policy == HTPL_REGRESS)
        humanoid_regress(h, 0.5f);
    snprintf(h->label, sizeof(h->label), "%.23s", tpl->name ? tpl->name : "tpl");
}

static float humanoid_zone_affinity(const HumanoidMorph* h, float zone_med, float zone_aug, float zone_mut, float zone_labor) {
    if (!h) return 0.f;
    float s = 0.3f;
    switch (h->designation) {
    case HDES_STOCK:     s += 0.4f * zone_labor; break;
    case HDES_LABOR_FIT: s += 0.6f * zone_labor; break;
    case HDES_MEDICAL:   s += 0.7f * zone_med; break;
    case HDES_AUGMENTED: s += 0.7f * zone_aug; break;
    case HDES_MUTANT:    s += 0.7f * zone_mut; break;
    case HDES_BALLAST:   s -= 0.5f; break;
    default: break;
    }
    return clampf(s, 0.f, 1.f);
}

static HumanoidMorph* humanoid_for_entity(uint32_t slot) {
    if (slot == UINT32_MAX) return &g_player_morph;
    if (!g_humanoid_pool || slot >= g_humanoid_cap) return NULL;
    if (g_humanoid_pool[slot].part_n == 0) return NULL;
    return &g_humanoid_pool[slot];
}

static HumanoidMorph* humanoid_ensure(uint32_t slot, uint32_t seed) {
    if (slot == UINT32_MAX) {
        if (!g_player_morph.part_n)
            humanoid_mannequin(&g_player_morph, seed, SPECIES_HUMANOID);
        return &g_player_morph;
    }
    if (!g_humanoid_pool || g_humanoid_cap < g_things_cap) {
        uint32_t nc = g_things_cap ? g_things_cap : 64;
        HumanoidMorph* n = (HumanoidMorph*)xrealloc(g_humanoid_pool, nc * sizeof(HumanoidMorph));
        if (!n) return NULL;
        if (nc > g_humanoid_cap)
            memset(n + g_humanoid_cap, 0, (nc - g_humanoid_cap) * sizeof(HumanoidMorph));
        g_humanoid_pool = n; g_humanoid_cap = nc;
    }
    HumanoidMorph* h = &g_humanoid_pool[slot];
    if (h->part_n == 0)
        humanoid_mannequin(h, seed, SPECIES_HUMANOID);
    h->entity_slot = slot;
    return h;
}

static void humanoid_templates_init(void) {
    g_humanoid_template_n = 0;
    #define TPL() &g_humanoid_templates[g_humanoid_template_n]
    HumanoidTemplate* t;
    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "civilian_stock"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.25f;
    t->cause_n = 1;
    t->causes[0] = (HumanoidCause){ HCAUSE_HABIT, HTAG_FAT_PAD, HP_TORSO, 0, 0.2f, 0.f };
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "labor_fit"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.2f;
    t->cause_n = 1;
    t->causes[0] = (HumanoidCause){ HCAUSE_WORK, HTAG_LIMP, HP_LEG_L, 0, 0.15f, 0.f };
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "combat_amputee"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.15f;
    t->cause_n = 1;
    t->causes[0] = (HumanoidCause){ HCAUSE_COMBAT, HTAG_MISSING_LIMB, HP_LEG_R, 0, 1.0f, 0.f };
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "aug_pilot"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.2f;
    t->cause_n = 0;
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "irradiated"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.35f;
    t->cause_n = 2;
    t->causes[0] = (HumanoidCause){ HCAUSE_RADIATION, HTAG_EXTRA_SENSOR, HP_HEAD, 0, 0.5f, 0.f };
    t->causes[1] = (HumanoidCause){ HCAUSE_RADIATION, HTAG_CHRONIC_PAIN, HP_TORSO, 0, 0.4f, 0.f };
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "symbiont_tentacle"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.2f;
    t->cause_n = 0;
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "franken_graft"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.25f;
    t->cause_n = 0;
    g_humanoid_template_n++;

    t = TPL(); memset(t, 0, sizeof(*t));
    t->name = "hybrid_chimera"; t->species = SPECIES_HUMANOID;
    t->policy = HTPL_POLYMORPHIC; t->noise = 0.3f;
    t->cause_n = 0;
    g_humanoid_template_n++;
    #undef TPL
}

static void humanoid_system_init(void) {
    if (g_humanoid_inited) return;
    memset(&g_player_morph, 0, sizeof(g_player_morph));
    humanoid_templates_init();
    humanoid_mannequin(&g_player_morph, 1u, SPECIES_HUMANOID);
    humanoid_bake(&g_player_morph);
    g_humanoid_inited = 1;
    LOG("humanoid_system_init: %d templates, mannequin ready", g_humanoid_template_n);
}

static void humanoid_system_shutdown(void) {
    xfree(g_humanoid_pool);
    g_humanoid_pool = NULL;
    g_humanoid_cap = 0;
    g_humanoid_inited = 0;
}

static const HumanoidTemplate* humanoid_template_find(const char* name) {
    for (int i = 0; i < g_humanoid_template_n; i++)
        if (g_humanoid_templates[i].name && name &&
            strcmp(g_humanoid_templates[i].name, name) == 0)
            return &g_humanoid_templates[i];
    return NULL;
}

static void humanoid_spawn_from_template(uint32_t slot, const char* tpl_name, uint32_t seed) {
    HumanoidMorph* h = humanoid_ensure(slot, seed);
    if (!h) return;
    const HumanoidTemplate* tpl = humanoid_template_find(tpl_name);
    if (tpl) humanoid_apply_template(h, tpl, seed);
    else {
        humanoid_mannequin(h, seed, SPECIES_HUMANOID);
        humanoid_bake(h);
    }
    h->entity_slot = slot;
}

/* Push environmental tendency (zone radiation, etc.) */
static void humanoid_apply_zone_tendencies(HumanoidMorph* h, float rad, float work, float diet) {
    if (!h) return;
    if (rad > 0.2f)
        humanoid_cause_push_kv(h, HCAUSE_RADIATION, HTAG_EXTRA_SENSOR, HP_HEAD, rad * 0.5f);
    if (work > 0.3f)
        humanoid_cause_push_kv(h, HCAUSE_WORK, HTAG_LIMP, HP_LEG_L, work * 0.3f);
    if (diet > 0.3f)
        humanoid_cause_push_kv(h, HCAUSE_HABIT, HTAG_FAT_PAD, HP_TORSO, diet * 0.4f);
    humanoid_bake(h);
}

static void walker_physics_intent(WalkerState* w, uint32_t slot,
                                   const Intent* i, float dt) {
    if (!w || !i || dt <= 0.f) return;
    Thing* ship = entity_get(slot);
    if (!ship) return;

    if (g_support_enabled && w == &g_player.walker) {
        walker_physics_support(w, slot, i, dt); return;
    }

    w->yaw   += i->look_dx * 0.0030f;
    w->pitch -= i->look_dy * 0.0030f;
    w->pitch  = clampf(w->pitch, -1.45f, 1.45f);
    while (w->yaw >  PI_F) w->yaw -= TAU_F;
    while (w->yaw < -PI_F) w->yaw += TAU_F;

    {
        GravSample gs;
        gravity_sample_local(slot, w->pos_local, &gs);
        if (slot == g_player.inside_ship) g_player_grav = gs;
    }

    player_apply_crouch(w, i->crouch, dt);
    w->aiming = i->fire_secondary ? 1 : 0;
    if (i->jump && w->grounded && !i->crouch) {
        w->vel_local.y = g_tuning.walker_jump_vel;
        w->grounded = 0;
        w->jumping = 1;
    }
    if (w->grounded && w->jumping) w->jumping = 0;

    float speed = g_tuning.walker_speed;
    if (i->sprint && !i->crouch) speed *= WALK_SPRINT_MUL;
    if (i->crouch)               speed *= 0.5f;
    if (w->aiming)               speed *= 0.65f;
    /* humanoid phenotype gait */
    if (w == &g_player.walker) {
        if (!g_player_morph.baked) humanoid_bake(&g_player_morph);
        speed *= g_player_morph.gait_speed_mul;
        if (g_player_morph.gait_limp > 0.05f) {
            /* slight yaw bias + speed already reduced */
            w->yaw += g_player_morph.gait_limp * 0.15f * sinf(w->bob_phase * 2.f) * dt;
        }
    }
    float cy = cosf(w->yaw), sy = sinf(w->yaw);
    float fx = sy, fz = -cy;
    float rx = cy, rz = sy;
    float vx = fx * (i->throttle * speed) + rx * (i->strafe * speed * 0.5f);
    float vz = fz * (i->throttle * speed) + rz * (i->strafe * speed * 0.5f);
    if (w->grounded) {
        if (fabsf(vx) > 0.001f || fabsf(vz) > 0.001f) {
            w->vel_local.x = vx; w->vel_local.z = vz;
        } else {
            float damp = 1.f - 8.f * dt;
            if (damp < 0.f) damp = 0.f;
            w->vel_local.x *= damp; w->vel_local.z *= damp;
            if (fabsf(w->vel_local.x) < 0.05f) w->vel_local.x = 0.f;
            if (fabsf(w->vel_local.z) < 0.05f) w->vel_local.z = 0.f;
        }
    } else {
        const float AIR_ACCEL = 8.f;
        float dx = vx - w->vel_local.x;
        float dz = vz - w->vel_local.z;
        float dl = sqrtf(dx * dx + dz * dz);
        float ac = AIR_ACCEL * dt;
        if (dl > ac && dl > 0.001f) { dx = dx * ac / dl; dz = dz * ac / dl; }
        w->vel_local.x += dx; w->vel_local.z += dz;
    }

    walker_apply_inertia(w, slot, dt);
    walker_apply_centrifugal(w, slot, dt);
    walker_apply_shake(w, dt);
    walker_apply_gravity(w, dt);

    V3 next = v3add(w->pos_local, v3mul(w->vel_local, dt));
    next = walker_apply_floor(w, slot, next, dt);
    V3 resolved;
    walker_collide(slot, w->pos_local, next, &resolved);
    w->pos_local = resolved;
    w->last_ship_vel_world = ship->vel;
    w->last_ship_rot       = ship->rot;
    walker_decay_hurt_shake(w);
    player_apply_bob(w, i->crouch, dt);
}

static void eva_physics_intent(const Intent* i, float dt) {
    if (!i || dt <= 0.f) return;
    float cy = cosf(g_player.walker.yaw);
    float sy = sinf(g_player.walker.yaw);
    float cp = cosf(g_player.walker.pitch);
    float sp = sinf(g_player.walker.pitch);
    V3 fwd   = v3(sy * cp, sp, -cy * cp);
    V3 right = v3(cy, 0.f, sy);
    V3 accel = v3zero();
    if (i->throttle > 0.f) accel = v3add(accel, v3mul(fwd,   i->throttle));
    if (i->throttle < 0.f) accel = v3add(accel, v3mul(fwd,   i->throttle));
    if (i->strafe > 0.f)   accel = v3add(accel, v3mul(right, i->strafe));
    if (i->strafe < 0.f)   accel = v3add(accel, v3mul(right, i->strafe));
    if (i->move_dir.y != 0.f) accel = v3add(accel, v3(0.f, i->move_dir.y, 0.f));
    float al = v3len(accel);
    if (al > 0.01f) {
        accel = v3mul(accel, EVA_JETPACK_FORCE / al);
        g_player.eva_vel = v3add(g_player.eva_vel, v3mul(accel, dt));
    }
    g_player.eva_vel = v3mul(g_player.eva_vel, 1.f - 0.3f * dt);
    float sp2 = v3len(g_player.eva_vel);
    if (sp2 > EVA_MAX_SPEED) g_player.eva_vel = v3mul(g_player.eva_vel, EVA_MAX_SPEED / sp2);
    g_player.eva_pos = v3add(g_player.eva_pos, v3mul(g_player.eva_vel, dt));
    g_player.walker.yaw   += i->look_dx * 0.0030f;
    g_player.walker.pitch -= i->look_dy * 0.0030f;
    g_player.walker.pitch  = clampf(g_player.walker.pitch, -1.45f, 1.45f);
    while (g_player.walker.yaw >  PI_F) g_player.walker.yaw -= TAU_F;
    while (g_player.walker.yaw < -PI_F) g_player.walker.yaw += TAU_F;
}



/* ═══════════════════════════════════════════════════════════════════════
   DIRECTED GRAPH — cycle detection + topological sort
   Generic utilities (adjacency lists). Used by the capability system and
   available for any other dependency graph in the game.
   ═══════════════════════════════════════════════════════════════════════ */

#define DIGRAPH_MAX_N        64
#define DIGRAPH_MAX_EDEG     8   /* max out-edges per node */

typedef struct {
    int16_t  adj[DIGRAPH_MAX_N][DIGRAPH_MAX_EDEG];
    uint8_t  adj_n[DIGRAPH_MAX_N];
    int      n;                  /* node count [0..n) */
} DiGraph;

typedef struct {
    int16_t path[DIGRAPH_MAX_N + 1];
    int     len;                 /* nodes in path; last equals first if closed */
    int     has_cycle;
} DiGraphCycle;

static void digraph_init(DiGraph* g, int n) {
    if (!g) return;
    if (n > DIGRAPH_MAX_N) n = DIGRAPH_MAX_N;
    if (n < 0) n = 0;
    memset(g, 0, sizeof(*g));
    g->n = n;
}

static int digraph_add_edge(DiGraph* g, int from, int to) {
    if (!g || from < 0 || to < 0 || from >= g->n || to >= g->n) return 0;
    if (g->adj_n[from] >= DIGRAPH_MAX_EDEG) return 0;
    /* avoid duplicate edges */
    for (uint8_t i = 0; i < g->adj_n[from]; i++)
        if (g->adj[from][i] == (int16_t)to) return 1;
    g->adj[from][g->adj_n[from]++] = (int16_t)to;
    return 1;
}

/* DFS 3-color cycle detection with path recovery.
   WHITE=0, GRAY=1, BLACK=2. Back-edge onto GRAY closes a cycle. */
static int digraph_cycle_dfs(const DiGraph* g, int u,
                              uint8_t* color, int16_t* parent,
                              DiGraphCycle* out) {
    color[u] = 1;
    for (uint8_t i = 0; i < g->adj_n[u]; i++) {
        int v = (int)g->adj[u][i];
        if (color[v] == 1) {
            /* cycle: v ... u -> v */
            out->len = 0;
            out->path[out->len++] = (int16_t)v;
            int x = u;
            int guard = g->n + 2;
            while (x != v && x >= 0 && guard-- > 0) {
                if (out->len < DIGRAPH_MAX_N)
                    out->path[out->len++] = (int16_t)x;
                x = parent[x];
            }
            if (out->len < DIGRAPH_MAX_N + 1)
                out->path[out->len++] = (int16_t)v;
            out->has_cycle = 1;
            return 1;
        }
        if (color[v] == 0) {
            parent[v] = (int16_t)u;
            if (digraph_cycle_dfs(g, v, color, parent, out))
                return 1;
        }
    }
    color[u] = 2;
    return 0;
}

/* Returns 1 if a directed cycle exists. Fills out with one cycle path. */
static int digraph_find_cycle(const DiGraph* g, DiGraphCycle* out) {
    if (out) { out->len = 0; out->has_cycle = 0; }
    if (!g || g->n <= 0) return 0;

    /* self-loops */
    for (int u = 0; u < g->n; u++) {
        for (uint8_t i = 0; i < g->adj_n[u]; i++) {
            if (g->adj[u][i] == (int16_t)u) {
                if (out) {
                    out->path[0] = (int16_t)u;
                    out->path[1] = (int16_t)u;
                    out->len = 2;
                    out->has_cycle = 1;
                }
                return 1;
            }
        }
    }

    uint8_t color[DIGRAPH_MAX_N];
    int16_t parent[DIGRAPH_MAX_N];
    memset(color, 0, sizeof(color));
    for (int i = 0; i < DIGRAPH_MAX_N; i++) parent[i] = -1;

    DiGraphCycle local;
    DiGraphCycle* c = out ? out : &local;
    c->len = 0; c->has_cycle = 0;

    for (int u = 0; u < g->n; u++) {
        if (color[u] != 0) continue;
        if (digraph_cycle_dfs(g, u, color, parent, c))
            return 1;
    }
    return 0;
}

/* True if edge from→to would create a cycle (to can already reach from). */
static int digraph_edge_creates_cycle(const DiGraph* g, int from, int to) {
    if (!g || from < 0 || to < 0 || from >= g->n || to >= g->n) return 0;
    if (from == to) return 1;
    /* BFS from `to` along existing edges; if we reach `from`, adding from→to cycles */
    uint8_t seen[DIGRAPH_MAX_N];
    int16_t q[DIGRAPH_MAX_N];
    int qh = 0, qt = 0;
    memset(seen, 0, sizeof(seen));
    q[qt++] = (int16_t)to; seen[to] = 1;
    while (qh < qt) {
        int u = q[qh++];
        if (u == from) return 1;
        for (uint8_t i = 0; i < g->adj_n[u]; i++) {
            int v = (int)g->adj[u][i];
            if (!seen[v]) { seen[v] = 1; q[qt++] = (int16_t)v; }
        }
    }
    return 0;
}

/* Kahn topological sort. Returns count written to out[], or -1 on cycle.
   If cycle_out non-NULL and cycle found, fills cycle path.
   active[] optional: if non-NULL, only nodes with active[u]!=0 participate
   (indeg and queue restricted to the induced subgraph).
   seed_order[] optional: preferred order to enqueue zero-indegree nodes
   (length seed_n) for stable sorts. */
static int digraph_topo_sort_ex(const DiGraph* g, int16_t* out, int out_cap,
                                 DiGraphCycle* cycle_out,
                                 const uint8_t* active,
                                 const int16_t* seed_order, int seed_n) {
    if (!g || !out || out_cap <= 0) return 0;

    /* Count active nodes; build induced check */
    int expected = 0;
    uint8_t use[DIGRAPH_MAX_N];
    memset(use, 0, sizeof(use));
    for (int u = 0; u < g->n; u++) {
        if (active && !active[u]) continue;
        use[u] = 1;
        expected++;
    }
    if (expected == 0) return 0;

    /* Cycle check on induced subgraph: temporarily mask edges */
    {
        DiGraph sub;
        digraph_init(&sub, g->n);
        for (int u = 0; u < g->n; u++) {
            if (!use[u]) continue;
            for (uint8_t i = 0; i < g->adj_n[u]; i++) {
                int v = (int)g->adj[u][i];
                if (use[v]) digraph_add_edge(&sub, u, v);
            }
        }
        if (digraph_find_cycle(&sub, cycle_out))
            return -1;
    }

    int indeg[DIGRAPH_MAX_N];
    memset(indeg, 0, sizeof(indeg));
    for (int u = 0; u < g->n; u++) {
        if (!use[u]) continue;
        for (uint8_t i = 0; i < g->adj_n[u]; i++) {
            int v = (int)g->adj[u][i];
            if (use[v]) indeg[v]++;
        }
    }

    int16_t queue[DIGRAPH_MAX_N];
    int qh = 0, qt = 0;
    uint8_t queued[DIGRAPH_MAX_N];
    memset(queued, 0, sizeof(queued));

    /* Seed queue in preferred order for stability */
    if (seed_order && seed_n > 0) {
        for (int i = 0; i < seed_n; i++) {
            int u = (int)seed_order[i];
            if (u < 0 || u >= g->n || !use[u] || queued[u]) continue;
            if (indeg[u] == 0) { queue[qt++] = (int16_t)u; queued[u] = 1; }
        }
    }
    for (int u = 0; u < g->n; u++) {
        if (!use[u] || queued[u]) continue;
        if (indeg[u] == 0) { queue[qt++] = (int16_t)u; queued[u] = 1; }
    }

    int written = 0;
    while (qh < qt) {
        int u = queue[qh++];
        if (written < out_cap) out[written++] = (int16_t)u;
        for (uint8_t i = 0; i < g->adj_n[u]; i++) {
            int v = (int)g->adj[u][i];
            if (!use[v]) continue;
            if (--indeg[v] == 0 && !queued[v]) {
                queue[qt++] = (int16_t)v;
                queued[v] = 1;
            }
        }
    }
    if (written != expected) {
        if (cycle_out) {
            DiGraph sub;
            digraph_init(&sub, g->n);
            for (int u = 0; u < g->n; u++) {
                if (!use[u]) continue;
                for (uint8_t i = 0; i < g->adj_n[u]; i++) {
                    int v = (int)g->adj[u][i];
                    if (use[v]) digraph_add_edge(&sub, u, v);
                }
            }
            digraph_find_cycle(&sub, cycle_out);
        }
        return -1;
    }
    return written;
}

static int digraph_topo_sort(const DiGraph* g, int16_t* out, int out_cap,
                              DiGraphCycle* cycle_out) {
    return digraph_topo_sort_ex(g, out, out_cap, cycle_out, NULL, NULL, 0);
}

/* Format cycle path into buf using optional name_fn(id) or "#id". */
typedef const char* (*DiGraphNameFn)(int id);
static int digraph_cycle_format(const DiGraphCycle* c, DiGraphNameFn name_fn,
                                 char* buf, int buf_sz) {
    if (!c || !buf || buf_sz <= 0) return 0;
    buf[0] = 0;
    if (!c->has_cycle || c->len <= 0) return 0;
    int pos = 0;
    for (int i = 0; i < c->len && pos < buf_sz - 32; i++) {
        const char* nm = name_fn ? name_fn((int)c->path[i]) : NULL;
        char tmp[32];
        if (!nm) { snprintf(tmp, sizeof(tmp), "#%d", (int)c->path[i]); nm = tmp; }
        int n = snprintf(buf + pos, (size_t)(buf_sz - pos), "%s%s",
                         (i ? " -> " : ""), nm);
        if (n > 0) pos += n;
    }
    return pos;
}

/* ═══════════════════════════════════════════════════════════════════════
   MODULAR CAPABILITY SYSTEM
   + dependency validation
   + topological sort of grant order (Kahn / DFS)
   ═══════════════════════════════════════════════════════════════════════ */

typedef enum {
    CAP_MOVE_VEHICLE = 0,
    CAP_MOVE_WALKER,
    CAP_MOVE_EVA,
    CAP_FIRE_VEHICLE,
    CAP_REPAIR,
    CAP_MINE,
    CAP_INTERACT,
    CAP_PICKUP,
    CAP_CAMERA_FOLLOW,
    CAP_CAMERA_FP,
    CAP_AIM,
    CAP_CROUCH,
    CAP_EVA_VERTICAL,
    CAP_COMBAT,
    CAP_RECON,
    CAP_CARGO,
    CAP_SENSOR,
    CAP_JAMMER,
    CAP_HAUL,
    CAP_DOCK,
    CAP_SCAN,
    CAP_COUNT
} CapId;

typedef void (*CapHookFn)(uint32_t owner, float dt, void* user);
typedef int  (*CapGateFn)(uint32_t owner, void* user);

typedef struct {
    CapId       id;
    const char* name;
    uint32_t    bit;
    CapId       deps[CAP_MAX_DEPS];
    uint8_t     require_n;
    CapId       conflicts[CAP_MAX_DEPS];
    uint8_t     conflict_n;
    CapHookFn   on_grant, on_revoke, on_tick;
    CapGateFn   can_use;
    void*       user;
    uint8_t     registered;
} CapDef;

typedef struct {
    CapId   id;
    uint8_t enabled, level, flags;
    float   cooldown;
} CapInst;

typedef struct {
    CapInst  inst[CAP_SLOTS_PER_SET];
    uint8_t  count;
    uint32_t mask;
} CapSet;

typedef enum {
    CAP_OK = 0,
    CAP_ERR_UNKNOWN,
    CAP_ERR_FULL,
    CAP_ERR_MISSING_DEP,
    CAP_ERR_CONFLICT,
    CAP_ERR_NOT_PRESENT,
    CAP_ERR_CYCLE
} CapResult;

static CapDef   g_cap_defs[CAP_MAX_DEFS];
static CapSet   g_cap_player;
static CapSet*  g_cap_entity = NULL;
static uint32_t g_cap_entity_cap = 0;
static int      g_cap_inited = 0;
static CapId    g_cap_last_missing = (CapId)0;
static CapId    g_cap_last_conflict = (CapId)0;

/* Precomputed global topo order of all registered caps (deps first). */
static CapId    g_cap_topo[CAP_COUNT];
static int      g_cap_topo_n = 0;
static int      g_cap_topo_valid = 0;
/* Last detected cycle path (ids[0] -> ids[1] -> ... -> ids[0]). */
static CapId    g_cap_cycle_path[CAP_COUNT + 1];
static int      g_cap_cycle_len = 0;

static int  cap_edge_would_cycle(CapId id, CapId need);
static const char* cap_name(CapId id);
static void cap_register_ex(CapId id, const char* name,
                             const CapId* reqs, int nreq,
                             const CapId* conf, int nconf,
                             CapHookFn g, CapHookFn r, CapHookFn t, CapGateFn gate, void* user) {
    if ((int)id < 0 || id >= CAP_COUNT || id >= CAP_MAX_DEFS) return;
    CapDef* d = &g_cap_defs[id];
    memset(d, 0, sizeof(*d));
    d->id = id; d->name = name ? name : "?";
    d->bit = (id < 32) ? (1u << (unsigned)id) : 0u;
    /* Stage requires, rejecting self-loops and edges that close a cycle. */
    if (reqs) {
        for (int i = 0; i < nreq && i < CAP_MAX_DEPS; i++) {
            CapId need = reqs[i];
            if (need == id) {
                LOG("cap_register: REJECT self-loop on %s", name ? name : "?");
                continue;
            }
            /* Temporarily mark registered so reachability sees this node. */
            d->registered = 1;
            if (cap_edge_would_cycle(id, need)) {
                LOG("cap_register: REJECT %s requires %s (would cycle)",
                    name ? name : "?", cap_name(need));
                d->registered = 0;
                continue;
            }
            d->registered = 0;
            d->deps[d->require_n++] = need;
        }
    }
    if (conf) for (int i = 0; i < nconf && i < CAP_MAX_DEPS; i++) d->conflicts[d->conflict_n++] = conf[i];
    d->on_grant = g; d->on_revoke = r; d->on_tick = t; d->can_use = gate; d->user = user;
    d->registered = 1;
    g_cap_topo_valid = 0; /* invalidate order */
}

static void cap_register(CapId id, const char* name) {
    cap_register_ex(id, name, NULL, 0, NULL, 0, NULL, NULL, NULL, NULL, NULL);
}

static const CapDef* cap_def(CapId id) {
    if ((int)id < 0 || id >= CAP_COUNT) return NULL;
    return g_cap_defs[id].registered ? &g_cap_defs[id] : NULL;
}

static CapSet* cap_set_for(uint32_t owner) {
    if (owner == CAP_OWNER_PLAYER) return &g_cap_player;
    if (owner >= g_things_cap) return NULL;
    if (!g_cap_entity || g_cap_entity_cap < g_things_cap) {
        uint32_t nc = g_things_cap ? g_things_cap : 64;
        CapSet* n = (CapSet*)xrealloc(g_cap_entity, nc * sizeof(CapSet));
        if (!n) return NULL;
        if (nc > g_cap_entity_cap)
            memset(n + g_cap_entity_cap, 0, (nc - g_cap_entity_cap) * sizeof(CapSet));
        g_cap_entity = n; g_cap_entity_cap = nc;
    }
    return &g_cap_entity[owner];
}

static void cap_set_recompute_mask(CapSet* s) {
    uint32_t m = 0;
    for (uint8_t i = 0; i < s->count; i++) {
        if (!s->inst[i].enabled) continue;
        const CapDef* d = cap_def(s->inst[i].id);
        if (d) m |= d->bit;
    }
    s->mask = m;
}

static int cap_set_find(const CapSet* s, CapId id) {
    for (uint8_t i = 0; i < s->count; i++)
        if (s->inst[i].id == id) return (int)i;
    return -1;
}

static int cap_has(uint32_t owner, CapId id) {
    CapSet* s = cap_set_for(owner);
    if (!s) return 0;
    int idx = cap_set_find(s, id);
    return (idx >= 0 && s->inst[idx].enabled) ? 1 : 0;
}

static int player_cap(int id) { return cap_has(CAP_OWNER_PLAYER, (CapId)id); }

static CapResult cap_check_deps(uint32_t owner, CapId id) {
    const CapDef* d = cap_def(id);
    if (!d) return CAP_ERR_UNKNOWN;
    g_cap_last_missing = (CapId)0;
    g_cap_last_conflict = (CapId)0;
    for (uint8_t i = 0; i < d->require_n; i++) {
        if (!cap_has(owner, d->deps[i])) {
            g_cap_last_missing = d->deps[i];
            return CAP_ERR_MISSING_DEP;
        }
    }
    for (uint8_t i = 0; i < d->conflict_n; i++) {
        if (cap_has(owner, d->conflicts[i])) {
            g_cap_last_conflict = d->conflicts[i];
            return CAP_ERR_CONFLICT;
        }
    }
    return CAP_OK;
}

static const char* cap_name(CapId id) {
    const CapDef* d = cap_def(id);
    return d ? d->name : "?";
}

/* Bridge: capability dependency graph → generic digraph cycle check */
static int cap_deps_to_digraph(DiGraph* g) {
    digraph_init(g, CAP_COUNT);
    for (int id = 0; id < CAP_COUNT; id++) {
        if (!g_cap_defs[id].registered) continue;
        CapDef* d = &g_cap_defs[id];
        for (uint8_t r = 0; r < d->require_n; r++) {
            CapId need = d->deps[r];
            if ((int)need < 0 || need >= CAP_COUNT || !g_cap_defs[need].registered)
                continue;
            /* edge: need → id (dependency before dependent) */
            digraph_add_edge(g, (int)need, id);
        }
    }
    return g->n;
}

static const char* cap_name_as_digraph(int id) {
    return cap_name((CapId)id);
}

static int cap_graph_find_cycle(DiGraphCycle* out) {
    DiGraph g;
    cap_deps_to_digraph(&g);
    int hit = digraph_find_cycle(&g, out);
    if (hit && out) {
        char buf[512];
        digraph_cycle_format(out, cap_name_as_digraph, buf, (int)sizeof(buf));
        LOG("cap_graph_find_cycle: %s", buf[0] ? buf : "(unnamed)");
    }
    return hit;
}



/* ── Cycle detection (DFS 3-color) + path recovery ──
   WHITE=0 unvisited, GRAY=1 in stack, BLACK=2 done.
   On back-edge gray→gray, reconstruct cycle via parent[]. */
static int cap_cycle_dfs(int u, uint8_t* color, int* parent,
                          CapId adj[][CAP_MAX_DEPS * 2], const uint8_t* adj_n) {
    color[u] = 1; /* GRAY */
    for (uint8_t i = 0; i < adj_n[u]; i++) {
        int v = (int)adj[u][i];
        if (color[v] == 1) {
            /* back edge u → v : cycle v .. u → v */
            g_cap_cycle_len = 0;
            g_cap_cycle_path[g_cap_cycle_len++] = (CapId)v;
            int x = u;
            /* walk parents from u back to v */
            int guard = CAP_COUNT + 2;
            while (x != v && x >= 0 && guard-- > 0) {
                if (g_cap_cycle_len < CAP_COUNT)
                    g_cap_cycle_path[g_cap_cycle_len++] = (CapId)x;
                x = parent[x];
            }
            if (g_cap_cycle_len < CAP_COUNT + 1)
                g_cap_cycle_path[g_cap_cycle_len++] = (CapId)v; /* close */
            return 1;
        }
        if (color[v] == 0) {
            parent[v] = u;
            if (cap_cycle_dfs(v, color, parent, adj, adj_n))
                return 1;
        }
    }
    color[u] = 2; /* BLACK */
    return 0;
}

static int cap_cycle_detect(CapId adj[][CAP_MAX_DEPS * 2], const uint8_t* adj_n,
                             const uint8_t* is_reg) {
    uint8_t color[CAP_COUNT];
    int parent[CAP_COUNT];
    memset(color, 0, sizeof(color));
    for (int i = 0; i < CAP_COUNT; i++) parent[i] = -1;
    g_cap_cycle_len = 0;
    for (int u = 0; u < CAP_COUNT; u++) {
        if (!is_reg[u] || color[u] != 0) continue;
        if (cap_cycle_dfs(u, color, parent, adj, adj_n))
            return 1;
    }
    return 0;
}

static void cap_cycle_log(const char* tag) {
    if (g_cap_cycle_len <= 0) {
        LOG("%s: cycle detected (path unknown)", tag);
        return;
    }
    /* Build readable path string */
    char buf[512];
    int pos = 0;
    buf[0] = 0;
    for (int i = 0; i < g_cap_cycle_len && pos < (int)sizeof(buf) - 48; i++) {
        const char* nm = cap_name(g_cap_cycle_path[i]);
        int n = snprintf(buf + pos, sizeof(buf) - (size_t)pos, "%s%s",
                         (i ? " -> " : ""), nm);
        if (n > 0) pos += n;
    }
    LOG("%s: CYCLE: %s", tag, buf);
}

/* Self-loop: id requires id */
static int cap_has_self_loop(void) {
    for (int id = 0; id < CAP_COUNT; id++) {
        if (!g_cap_defs[id].registered) continue;
        CapDef* d = &g_cap_defs[id];
        for (uint8_t r = 0; r < d->require_n; r++) {
            if (d->deps[r] == (CapId)id) {
                g_cap_cycle_path[0] = (CapId)id;
                g_cap_cycle_path[1] = (CapId)id;
                g_cap_cycle_len = 2;
                return 1;
            }
        }
    }
    return 0;
}

/* Build adjacency (need → dependent) for all registered caps. */
static int cap_build_adj(CapId adj[][CAP_MAX_DEPS * 2], uint8_t* adj_n,
                          int* indeg, uint8_t* is_reg) {
    memset(adj_n, 0, sizeof(uint8_t) * CAP_COUNT);
    memset(indeg, 0, sizeof(int) * CAP_COUNT);
    memset(is_reg, 0, sizeof(uint8_t) * CAP_COUNT);
    int present = 0;
    for (int id = 0; id < CAP_COUNT; id++) {
        if (!g_cap_defs[id].registered) continue;
        is_reg[id] = 1; present++;
        CapDef* d = &g_cap_defs[id];
        for (uint8_t r = 0; r < d->require_n; r++) {
            CapId need = d->deps[r];
            if ((int)need < 0 || need >= CAP_COUNT || !g_cap_defs[need].registered)
                continue;
            if (adj_n[need] < (uint8_t)(CAP_MAX_DEPS * 2))
                adj[need][adj_n[need]++] = (CapId)id;
            indeg[id]++;
        }
    }
    return present;
}

/* Would adding edge need→id create a cycle? (id currently reachable from need via deps?)
   Check if `need` is reachable from `id` in the require graph (id requires ... requires need). */
static int cap_edge_would_cycle(CapId id, CapId need) {
    if (id == need) return 1;
    if ((int)id < 0 || id >= CAP_COUNT || (int)need < 0 || need >= CAP_COUNT) return 0;
    /* BFS from id following requires — if we reach need, edge need→id closes cycle */
    uint8_t seen[CAP_COUNT];
    CapId q[CAP_COUNT];
    int qh = 0, qt = 0;
    memset(seen, 0, sizeof(seen));
    q[qt++] = id; seen[id] = 1;
    while (qh < qt) {
        CapId u = q[qh++];
        if (!g_cap_defs[u].registered) continue;
        CapDef* d = &g_cap_defs[u];
        for (uint8_t r = 0; r < d->require_n; r++) {
            CapId v = d->deps[r];
            if ((int)v < 0 || v >= CAP_COUNT) continue;
            if (v == need) return 1;
            if (!seen[v]) { seen[v] = 1; q[qt++] = v; }
        }
    }
    return 0;
}

/* ── Topological sort (Kahn) over the full registry ──
   Edge: req → id  (dependency must come before dependent).
   Returns CAP_OK and fills g_cap_topo[0..g_cap_topo_n), or CAP_ERR_CYCLE. */
static CapResult cap_topo_rebuild(void) {
    DiGraph g;
    DiGraphCycle cyc;
    cap_deps_to_digraph(&g);

    /* Only registered nodes participate */
    uint8_t active[DIGRAPH_MAX_N];
    memset(active, 0, sizeof(active));
    int present = 0;
    for (int id = 0; id < CAP_COUNT && id < DIGRAPH_MAX_N; id++) {
        if (g_cap_defs[id].registered) { active[id] = 1; present++; }
    }

    int16_t order[DIGRAPH_MAX_N];
    int n = digraph_topo_sort_ex(&g, order, DIGRAPH_MAX_N, &cyc, active, NULL, 0);
    g_cap_cycle_len = 0;
    if (n < 0) {
        g_cap_topo_valid = 0;
        g_cap_topo_n = 0;
        if (cyc.has_cycle) {
            g_cap_cycle_len = cyc.len < CAP_COUNT + 1 ? cyc.len : CAP_COUNT + 1;
            for (int i = 0; i < g_cap_cycle_len; i++)
                g_cap_cycle_path[i] = (CapId)cyc.path[i];
        }
        cap_cycle_log("cap_topo_rebuild");
        return CAP_ERR_CYCLE;
    }
    g_cap_topo_n = 0;
    for (int i = 0; i < n && i < CAP_COUNT; i++)
        g_cap_topo[g_cap_topo_n++] = (CapId)order[i];
    g_cap_topo_valid = 1;
    return CAP_OK;
}

/* Topo-sort an arbitrary subset (stable w.r.t. global order when available).
   out[] receives ids with dependencies first. Returns count, or -1 on cycle. */
static int cap_topo_sort_subset(const CapId* ids, int n, CapId* out, int out_cap) {
    if (n <= 0 || !out || out_cap <= 0) return 0;
    if (n > CAP_COUNT) n = CAP_COUNT;

    uint8_t want[DIGRAPH_MAX_N];
    memset(want, 0, sizeof(want));
    for (int i = 0; i < n; i++) {
        if ((int)ids[i] >= 0 && ids[i] < CAP_COUNT && ids[i] < DIGRAPH_MAX_N)
            want[ids[i]] = 1;
    }
    /* Close under transitive requires */
    int changed = 1;
    while (changed) {
        changed = 0;
        for (int id = 0; id < CAP_COUNT && id < DIGRAPH_MAX_N; id++) {
            if (!want[id] || !g_cap_defs[id].registered) continue;
            CapDef* d = &g_cap_defs[id];
            for (uint8_t r = 0; r < d->require_n; r++) {
                CapId need = d->deps[r];
                if ((int)need >= 0 && need < DIGRAPH_MAX_N && !want[need]) {
                    want[need] = 1; changed = 1;
                }
            }
        }
    }

    DiGraph g;
    DiGraphCycle cyc;
    cap_deps_to_digraph(&g);

    /* Stable seed from global topo if available */
    int16_t seed[DIGRAPH_MAX_N];
    int seed_n = 0;
    if (g_cap_topo_valid) {
        for (int i = 0; i < g_cap_topo_n && seed_n < DIGRAPH_MAX_N; i++)
            seed[seed_n++] = (int16_t)g_cap_topo[i];
    }

    int16_t order[DIGRAPH_MAX_N];
    int written = digraph_topo_sort_ex(&g, order, DIGRAPH_MAX_N, &cyc,
                                        want, seed_n ? seed : NULL, seed_n);
    if (written < 0) {
        g_cap_cycle_len = 0;
        if (cyc.has_cycle) {
            g_cap_cycle_len = cyc.len < CAP_COUNT + 1 ? cyc.len : CAP_COUNT + 1;
            for (int i = 0; i < g_cap_cycle_len; i++)
                g_cap_cycle_path[i] = (CapId)cyc.path[i];
        }
        LOG("cap_topo_sort_subset: cycle");
        if (g_cap_cycle_len > 0) cap_cycle_log("cap_topo_sort_subset");
        return -1;
    }
    int out_n = 0;
    for (int i = 0; i < written && out_n < out_cap; i++)
        out[out_n++] = (CapId)order[i];
    return out_n;
}

static int cap_validate_set(uint32_t owner, CapId* out_broken) {
    CapSet* s = cap_set_for(owner);
    if (!s) return 0;
    int bad = 0;
    for (uint8_t i = 0; i < s->count; i++) {
        if (!s->inst[i].enabled) continue;
        if (cap_check_deps(owner, s->inst[i].id) != CAP_OK) {
            if (out_broken && bad == 0) *out_broken = s->inst[i].id;
            bad++;
        }
    }
    return bad;
}

static int cap_revoke_dependents(uint32_t owner, CapId id, int depth) {
    if (depth > CAP_COUNT) return 0;
    CapSet* s = cap_set_for(owner);
    if (!s) return 0;
    CapId doomed[CAP_SLOTS_PER_SET];
    int nd = 0;
    for (uint8_t i = 0; i < s->count; i++) {
        if (!s->inst[i].enabled) continue;
        const CapDef* d = cap_def(s->inst[i].id);
        if (!d) continue;
        for (uint8_t r = 0; r < d->require_n; r++) {
            if (d->deps[r] == id) {
                if (nd < CAP_SLOTS_PER_SET) doomed[nd++] = s->inst[i].id;
                break;
            }
        }
    }
    int n = 0;
    for (int i = 0; i < nd; i++) {
        CapSet* s2 = cap_set_for(owner);
        int idx = s2 ? cap_set_find(s2, doomed[i]) : -1;
        if (idx < 0) continue;
        CapInst* ci = &s2->inst[idx];
        if (!ci->enabled) continue;
        const CapDef* d = cap_def(doomed[i]);
        ci->enabled = 0;
        if (d && d->on_revoke) d->on_revoke(owner, 0.f, d->user);
        s2->inst[idx] = s2->inst[s2->count - 1];
        s2->count--;
        cap_set_recompute_mask(s2);
        n++;
        n += cap_revoke_dependents(owner, doomed[i], depth + 1);
    }
    return n;
}

static CapResult cap_grant_flags(uint32_t owner, CapId id, uint8_t level, uint32_t flags) {
    const CapDef* d = cap_def(id);
    if (!d) return CAP_ERR_UNKNOWN;
    CapSet* s = cap_set_for(owner);
    if (!s) return CAP_ERR_UNKNOWN;
    if (!(flags & CAP_GRANT_FORCE)) {
        CapResult r = cap_check_deps(owner, id);
        if (r != CAP_OK) return r;
    }
    int idx = cap_set_find(s, id);
    if (idx >= 0) {
        CapInst* ci = &s->inst[idx];
        int was = ci->enabled;
        ci->enabled = 1;
        if (level > ci->level) ci->level = level;
        if (!was && d->on_grant) d->on_grant(owner, 0.f, d->user);
        cap_set_recompute_mask(s);
        return CAP_OK;
    }
    if (s->count >= CAP_SLOTS_PER_SET) return CAP_ERR_FULL;
    CapInst* ci = &s->inst[s->count++];
    ci->id = id; ci->enabled = 1; ci->level = level; ci->flags = 0; ci->cooldown = 0.f;
    if (d->on_grant) d->on_grant(owner, 0.f, d->user);
    cap_set_recompute_mask(s);
    return CAP_OK;
}

static int cap_grant(uint32_t owner, CapId id, uint8_t level) {
    return cap_grant_flags(owner, id, level, 0) == CAP_OK;
}

static CapResult cap_revoke_flags(uint32_t owner, CapId id, uint32_t flags) {
    CapSet* s = cap_set_for(owner);
    if (!s) return CAP_ERR_UNKNOWN;
    int idx = cap_set_find(s, id);
    if (idx < 0) return CAP_ERR_NOT_PRESENT;
    CapInst* ci = &s->inst[idx];
    const CapDef* d = cap_def(id);
    if (ci->enabled && d && d->on_revoke) d->on_revoke(owner, 0.f, d->user);
    s->inst[idx] = s->inst[s->count - 1];
    s->count--;
    cap_set_recompute_mask(s);
    if (!(flags & CAP_GRANT_NO_CASCADE))
        cap_revoke_dependents(owner, id, 0);
    return CAP_OK;
}

static int cap_revoke(uint32_t owner, CapId id) {
    return cap_revoke_flags(owner, id, 0) == CAP_OK;
}

static int cap_can_use(uint32_t owner, CapId id) {
    if (!cap_has(owner, id)) return 0;
    if (cap_check_deps(owner, id) != CAP_OK) return 0;
    const CapDef* d = cap_def(id);
    if (d && d->can_use) return d->can_use(owner, d->user);
    CapSet* s = cap_set_for(owner);
    int idx = cap_set_find(s, id);
    if (idx >= 0 && s->inst[idx].cooldown > 0.f) return 0;
    return 1;
}

static void cap_set_cooldown(uint32_t owner, CapId id, float sec) {
    CapSet* s = cap_set_for(owner);
    if (!s) return;
    int idx = cap_set_find(s, id);
    if (idx >= 0) s->inst[idx].cooldown = sec;
}

static void cap_clear(uint32_t owner) {
    CapSet* s = cap_set_for(owner);
    if (!s) return;
    for (uint8_t i = 0; i < s->count; i++) {
        if (!s->inst[i].enabled) continue;
        const CapDef* d = cap_def(s->inst[i].id);
        if (d && d->on_revoke) d->on_revoke(owner, 0.f, d->user);
    }
    s->count = 0; s->mask = 0;
}

static void cap_tick_owner(uint32_t owner, float dt) {
    CapSet* s = cap_set_for(owner);
    if (!s) return;
    for (uint8_t i = 0; i < s->count; i++) {
        CapInst* ci = &s->inst[i];
        if (ci->cooldown > 0.f) { ci->cooldown -= dt; if (ci->cooldown < 0.f) ci->cooldown = 0.f; }
        if (!ci->enabled) continue;
        const CapDef* d = cap_def(ci->id);
        if (d && d->on_tick) d->on_tick(owner, dt, d->user);
    }
}

static void cap_tick_all(float dt) {
    cap_tick_owner(CAP_OWNER_PLAYER, dt);
    if (!g_cap_entity) return;
    for (uint32_t s = 0; s < g_cap_entity_cap && s < g_things_cap; s++) {
        if (!g_alive || !g_alive[s] || !g_cap_entity[s].count) continue;
        cap_tick_owner(s, dt);
    }
}

/* Grant list using topological order — deps first, one pass when acyclic. */
static int cap_grant_list(uint32_t owner, const CapId* ids, int n, uint8_t level) {
    CapId ordered[CAP_COUNT];
    int on = cap_topo_sort_subset(ids, n, ordered, CAP_COUNT);
    if (on < 0) {
        /* cycle: fall back to multi-pass */
        on = 0;
        for (int i = 0; i < n; i++) ordered[on++] = ids[i];
    }
    int granted = 0;
    for (int i = 0; i < on; i++) {
        CapResult r = cap_grant_flags(owner, ordered[i], level, 0);
        if (r == CAP_ERR_MISSING_DEP || r == CAP_ERR_CONFLICT) {
            /* force only as last resort for preset composition */
            r = cap_grant_flags(owner, ordered[i], level, CAP_GRANT_FORCE);
        }
        if (r == CAP_OK) granted++;
    }
    return granted;
}

static void cap_apply_player_mode(PlayerMode mode) {
    cap_clear(CAP_OWNER_PLAYER);
    CapId list[12]; int n = 0;
    switch (mode) {
    case PLAYER_MODE_PILOT:
        list[n++] = CAP_MOVE_VEHICLE; list[n++] = CAP_AIM;
        list[n++] = CAP_FIRE_VEHICLE; list[n++] = CAP_REPAIR;
        list[n++] = CAP_CAMERA_FOLLOW; list[n++] = CAP_INTERACT;
        list[n++] = CAP_CROUCH; list[n++] = CAP_DOCK; list[n++] = CAP_SCAN;
        break;
    case PLAYER_MODE_ON_FOOT:
    case PLAYER_MODE_PLATFORM:
        list[n++] = CAP_MOVE_WALKER; list[n++] = CAP_AIM;
        list[n++] = CAP_REPAIR; list[n++] = CAP_MINE;
        list[n++] = CAP_INTERACT; list[n++] = CAP_PICKUP;
        list[n++] = CAP_CAMERA_FP; list[n++] = CAP_CROUCH;
        break;
    case PLAYER_MODE_EVA:
        list[n++] = CAP_MOVE_EVA; list[n++] = CAP_AIM;
        list[n++] = CAP_MINE; list[n++] = CAP_INTERACT;
        list[n++] = CAP_PICKUP; list[n++] = CAP_CAMERA_FP;
        list[n++] = CAP_EVA_VERTICAL;
        break;
    default: break;
    }
    cap_grant_list(CAP_OWNER_PLAYER, list, n, 0);
    CapId broken;
    int v = cap_validate_set(CAP_OWNER_PLAYER, &broken);
    if (v > 0) LOG("cap_apply_player_mode: %d violations first=%s", v, cap_name(broken));
}

static void cap_apply_drone_mask(uint32_t slot, uint32_t mask) {
    cap_clear(slot);
    CapId list[12]; int n = 0;
    list[n++] = CAP_MOVE_VEHICLE;
    if (mask & DRONE_CAP_COMBAT) { list[n++] = CAP_COMBAT; list[n++] = CAP_AIM; list[n++] = CAP_FIRE_VEHICLE; }
    if (mask & DRONE_CAP_REPAIR) list[n++] = CAP_REPAIR;
    if (mask & DRONE_CAP_RECON)  list[n++] = CAP_RECON;
    if (mask & DRONE_CAP_CARGO)  list[n++] = CAP_CARGO;
    if (mask & DRONE_CAP_MINING) list[n++] = CAP_MINE;
    if (mask & DRONE_CAP_HAUL)   list[n++] = CAP_HAUL;
    if (mask & DRONE_CAP_SENSOR) list[n++] = CAP_SENSOR;
    if (mask & DRONE_CAP_JAMMER) list[n++] = CAP_JAMMER;
    cap_grant_list(slot, list, n, 0);
}

static void cap_system_init(void) {
    if (g_cap_inited) return;
    memset(g_cap_defs, 0, sizeof(g_cap_defs));
    memset(&g_cap_player, 0, sizeof(g_cap_player));

    cap_register(CAP_MOVE_VEHICLE, "move.vehicle");
    cap_register(CAP_MOVE_WALKER,  "move.walker");
    cap_register(CAP_MOVE_EVA,     "move.eva");
    /* mutual exclusion among locomotion */
    g_cap_defs[CAP_MOVE_VEHICLE].conflicts[0] = CAP_MOVE_WALKER;
    g_cap_defs[CAP_MOVE_VEHICLE].conflicts[1] = CAP_MOVE_EVA;
    g_cap_defs[CAP_MOVE_VEHICLE].conflict_n = 2;
    g_cap_defs[CAP_MOVE_WALKER].conflicts[0] = CAP_MOVE_VEHICLE;
    g_cap_defs[CAP_MOVE_WALKER].conflicts[1] = CAP_MOVE_EVA;
    g_cap_defs[CAP_MOVE_WALKER].conflict_n = 2;
    g_cap_defs[CAP_MOVE_EVA].conflicts[0] = CAP_MOVE_VEHICLE;
    g_cap_defs[CAP_MOVE_EVA].conflicts[1] = CAP_MOVE_WALKER;
    g_cap_defs[CAP_MOVE_EVA].conflict_n = 2;

    cap_register(CAP_AIM, "aim");
    {
        CapId r[] = { CAP_AIM };
        cap_register_ex(CAP_FIRE_VEHICLE, "fire.vehicle", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_MINE, "action.mine", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_SCAN, "ship.scan", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
    }
    cap_register(CAP_REPAIR, "action.repair");
    cap_register(CAP_INTERACT, "action.interact");
    {
        CapId r[] = { CAP_INTERACT };
        cap_register_ex(CAP_PICKUP, "action.pickup", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
    }
    {
        CapId c[] = { CAP_CAMERA_FP };
        cap_register_ex(CAP_CAMERA_FOLLOW, "camera.follow", NULL, 0, c, 1, NULL,NULL,NULL,NULL,NULL);
        CapId c2[] = { CAP_CAMERA_FOLLOW };
        cap_register_ex(CAP_CAMERA_FP, "camera.fp", NULL, 0, c2, 1, NULL,NULL,NULL,NULL,NULL);
    }
    cap_register(CAP_CROUCH, "input.crouch");
    {
        CapId r[] = { CAP_MOVE_EVA };
        cap_register_ex(CAP_EVA_VERTICAL, "input.eva_vert", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
    }
    {
        CapId r[] = { CAP_MOVE_VEHICLE };
        cap_register_ex(CAP_DOCK, "ship.dock", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_COMBAT, "drone.combat", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_RECON, "drone.recon", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_CARGO, "drone.cargo", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_SENSOR, "drone.sensor", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_JAMMER, "drone.jammer", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
        cap_register_ex(CAP_HAUL, "drone.haul", r, 1, NULL, 0, NULL,NULL,NULL,NULL,NULL);
    }

    if (cap_topo_rebuild() != CAP_OK)
        LOG("cap_system_init: topo order incomplete (cycle?)");
    else {
        LOG("cap_system_init: topo order (%d):", g_cap_topo_n);
        for (int i = 0; i < g_cap_topo_n; i++)
            LOG("  [%d] %s", i, cap_name(g_cap_topo[i]));
    }

    g_cap_inited = 1;
    cap_apply_player_mode(PLAYER_MODE_PILOT);
}

static void cap_system_shutdown(void) {
    xfree(g_cap_entity); g_cap_entity = NULL; g_cap_entity_cap = 0;
    memset(&g_cap_player, 0, sizeof(g_cap_player));
    g_cap_topo_n = 0; g_cap_topo_valid = 0; g_cap_inited = 0;
}

static void cap_player_move(float dt) {
    if (player_cap(CAP_MOVE_VEHICLE)) {
        if (g_player.inside_ship == UINT32_MAX) return;
        Thing* t = entity_get(g_player.inside_ship);
        if (!t) return;
        if (t->type == ET_SHIP) {
            ShipData* sd = (ShipData*)entity_side_ptr(g_player.inside_ship);
            if (sd) move_tick_ship(t, &g_player_intent, sd, dt);
        } else if (t->type == ET_DRONE) {
            move_tick_drone(t, &g_player_intent, dt);
        }
    } else if (player_cap(CAP_MOVE_WALKER)) {
        walker_physics_intent(&g_player.walker, g_player.inside_ship, &g_player_intent, dt);
    } else if (player_cap(CAP_MOVE_EVA)) {
        eva_physics_intent(&g_player_intent, dt);
    }
}

static void cap_player_camera(float dt) {
    if (player_cap(CAP_CAMERA_FOLLOW)) {
        if (piloting_is_drone()) camera_tick_drone(g_player.inside_ship, dt);
        else camera_tick_ship_follow(g_player.inside_ship, dt);
    } else camera_tick_fp(dt);
}

static void cap_player_fire(float dt) {
    if (!cap_can_use(CAP_OWNER_PLAYER, CAP_FIRE_VEHICLE)) return;
    if (g_player.inside_ship != UINT32_MAX)
        fire_tick(g_player.inside_ship, &g_player_intent, dt);
}

static void cap_player_gameplay_tick(float dt) {
    if (cap_can_use(CAP_OWNER_PLAYER, CAP_REPAIR)) player_repair_tick(dt);
    if (cap_can_use(CAP_OWNER_PLAYER, CAP_MINE))   player_mining_tick(dt);
    if (cap_can_use(CAP_OWNER_PLAYER, CAP_FIRE_VEHICLE) && piloting_is_ship())
        player_fire_tick(dt);
    if (player_cap(CAP_INTERACT) || player_cap(CAP_PICKUP))
        player_interaction_tick(dt);
}

static void move_tick_all(float dt) {
    if (dt <= 0.f) return;
    cap_player_move(dt);
    for (uint32_t k = 0; k < g_things_cap; k++) {
        if (!g_alive[k]) continue;
        Thing* t = &g_things[k];
        if (!(t->flags & ENT_FLAG_AI_CONTROLLED)) continue;
        if (t->flags & (ENT_FLAG_MARKED_DEAD | ENT_FLAG_PLAYER_OWNED)) continue;
        if (t->type != ET_SHIP && t->type != ET_DRONE) continue;
        if (k == g_player.inside_ship) continue;
        AiData* ai = (AiData*)entity_side_ptr(k);
        if (!ai) continue;
        if (t->type == ET_SHIP) {
            ShipData* sd = (ShipData*)entity_side_ptr(k);
            if (sd) move_tick_ship(t, &ai->intent, sd, dt);
        } else move_tick_drone(t, &ai->intent, dt);
    }
}

static void crew_nav_clear(int idx) {
    if (idx < 0 || idx >= CREW_MAX) return;
    memset(&g_crew_nav[idx], 0, sizeof(g_crew_nav[idx]));
    g_crew_nav[idx].active_path = 0;
}

static void crew_nav_set(int idx, uint32_t ship_slot, int* path, int path_len) {
    if (idx < 0 || idx >= CREW_MAX) return;
    CrewNavState* ns = &g_crew_nav[idx];
    ns->ship_slot = ship_slot;
    ns->path_len = (path_len < CREW_PATH_MAX) ? path_len : CREW_PATH_MAX;
    ns->path_idx = 1;
    for (int i = 0; i < ns->path_len; i++) ns->path[i] = path[i];
    ns->active_path = (path_len >= 2);
}

static int crew_nav_step(CrewMember* c, int crew_idx, float dt) {
    if (!c || crew_idx < 0 || crew_idx >= CREW_MAX) return -1;
    CrewNavState* ns = &g_crew_nav[crew_idx];
    for (;;) {
        if (!ns->active_path) return -1;
        int target_node = -1;
        if (ns->path_idx >= 0 && ns->path_idx < ns->path_len) target_node = ns->path[ns->path_idx];
        if (target_node < 0) { crew_nav_clear(crew_idx); return -1; }
        ShipDataExt* ext = ship_ext(c->inside_ship);
        if (!ext || target_node >= ext->node_count) { crew_nav_clear(crew_idx); return -1; }
        ShipNode* tn = &ext->nodes[target_node];
        V3 target_local = v3(tn->pos_local.x, tn->pos_local.y - tn->half_ext.y, tn->pos_local.z);
        V3 to = v3sub(target_local, c->pos_local);
        to.y = 0.f;
        float dist = v3len(to);
        if (dist < 0.4f) {
            ns->path_idx++;
            if (ns->path_idx >= ns->path_len) {
                ns->active_path = 0;
                ns->path_idx = 0;
                ns->path_len = 0;
                return 1;
            }
            continue;
        }
        V3 dir = v3mul(to, 1.f / dist);
        c->pos_local = v3add(c->pos_local, v3mul(dir, CREW_WALK_SPEED * dt));
        c->yaw = atan2f(dir.x, -dir.z);
        c->leg_phase = (c->leg_phase + 1) & 15;
        int hf = 0;
        float fy = floor_y_at(c->inside_ship, c->pos_local.x, c->pos_local.z, &hf);
        if (hf) c->pos_local.y = fy;
        walker_collide(c->inside_ship, c->pos_local, c->pos_local, &c->pos_local);
        return 0;
    }
}

static float crew_ship_hp_frac(uint32_t ship_slot) {
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return 0.f;
    ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[COMP_HULL]);
    if (!cd || cd->maxhp <= 0.f) return 0.f;
    return cd->hp / cd->maxhp;
}

static void crew_state_sit(CrewMember* c, uint32_t ship_slot, float dt, float ship_hp) {
    (void)ship_slot;
    c->work_timer -= dt;
    if (c->work_timer <= 0.f || ship_hp < 0.40f) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
        c->target_node = UINT32_MAX;
    }
}

static void crew_state_work(CrewMember* c, uint32_t ship_slot, float dt, float ship_hp) {
    (void)ship_hp;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!c || !ext) return;
    if (c->target_node >= (uint32_t)ext->node_count) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
        c->target_node = UINT32_MAX;
        return;
    }
    ShipNode* n = &ext->nodes[c->target_node];
    if (n->structural_hp > 0.f && n->current_hp >= n->structural_hp - 0.01f) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
        c->target_node = UINT32_MAX;
        return;
    }
    if (n->current_hp <= 0.01f) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
        c->target_node = UINT32_MAX;
        return;
    }
    for (uint32_t i = 0; i < g_crew_alerts_n; i++) {
        CrewAlert* a = &g_crew_alerts[i];
        if (!a->active) continue;
        if (a->priority >= 9) { c->state = CREW_STATE_PANIC; c->anim_timer = 0.f; return; }
    }
    V3 target_pos = v3(n->pos_local.x, n->pos_local.y - n->half_ext.y, n->pos_local.z);
    V3 to = v3sub(target_pos, c->pos_local);
    to.y = 0.f;
    float dist = v3len(to);
    if (dist > 0.8f) {
        V3 dir = v3mul(to, 1.f / dist);
        c->pos_local = v3add(c->pos_local, v3mul(dir, CREW_WALK_SPEED * dt));
        c->yaw = atan2f(dir.x, -dir.z);
        c->leg_phase = (c->leg_phase + 1) & 15;
        int hf = 0;
        float fy = floor_y_at(c->inside_ship, c->pos_local.x, c->pos_local.z, &hf);
        if (hf) c->pos_local.y = fy;
        walker_collide(c->inside_ship, c->pos_local, c->pos_local, &c->pos_local);
        return;
    }
    c->yaw = atan2f(to.x, -to.z);
    if (to.x == 0.f && to.z == 0.f) c->leg_phase = (c->leg_phase + 2) & 15;
    n->current_hp += 2.f * dt;
    if (n->current_hp > n->structural_hp) n->current_hp = n->structural_hp;
    c->work_timer -= dt;
    if (c->work_timer <= 0.f) {
        c->work_timer = 8.f;
        c->state = CREW_STATE_IDLE;
        c->anim_timer = 2.f;
        c->target_node = UINT32_MAX;
    }
}

static void crew_state_walk(CrewMember* c, uint32_t ship_slot, int crew_idx, float dt) {
    (void)ship_slot;
    int r = crew_nav_step(c, crew_idx, dt);
    if (r == 1 || r == -1) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
        c->target_node = UINT32_MAX;
    }
}

static void crew_state_idle(CrewMember* c, uint32_t ship_slot, int crew_idx, float dt) {
    c->anim_timer -= dt;
    if (c->anim_timer > 0.f) return;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return;
    int from = pf_nearest_walkable(ship_slot, c->pos_local, 5.f);
    if (from < 0) { c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX); return; }
    int path[CREW_PATH_MAX];
    if (xrng_f() < 0.30f) {
        int best = -1;
        float best_frac = 0.85f;
        for (int i = 0; i < ext->node_count; i++) {
            ShipNode* n = &ext->nodes[i];
            if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
            if (n->structural_hp <= 0.f) continue;
            if (n->current_hp <= 0.01f) continue;
            float f = n->current_hp / n->structural_hp;
            if (f < best_frac) { best_frac = f; best = i; }
        }
        if (best >= 0) {
            int pn = pf_path(ship_slot, from, best, path, CREW_PATH_MAX);
            if (pn >= 2) {
                crew_nav_set(crew_idx, ship_slot, path, pn);
                c->target_node = (uint32_t)best;
                c->state = CREW_STATE_WALK;
                c->work_timer = 8.f;
                return;
            }
        }
    }
    if (xrng_f() < 0.30f) {
        int n = pf_find_reachable_prop(ship_slot, from, NODE_PROP_COCKPIT, path, CREW_PATH_MAX);
        if (n >= 2) {
            crew_nav_set(crew_idx, ship_slot, path, n);
            c->target_node = (uint32_t)path[n - 1];
            c->state = CREW_STATE_WALK;
            return;
        }
    }
    if (xrng_f() < 0.40f) {
        int n = pf_find_reachable_prop(ship_slot, from, NODE_PROP_COMPUTER_ROOM, path, CREW_PATH_MAX);
        if (n >= 2) {
            crew_nav_set(crew_idx, ship_slot, path, n);
            c->target_node = (uint32_t)path[n - 1];
            c->state = CREW_STATE_WALK;
            return;
        }
    }
    int target = -1;
    for (int tries = 0; tries < 8; tries++) {
        int cand = xrng_int(ext->node_count);
        if (ext->nodes[cand].props_mask & NODE_PROP_WALKABLE) { target = cand; break; }
    }
    if (target < 0) return;
    int n = pf_path(ship_slot, from, target, path, CREW_PATH_MAX);
    if (n >= 2) {
        crew_nav_set(crew_idx, ship_slot, path, n);
        c->target_node = (uint32_t)target;
        c->state = CREW_STATE_WALK;
    } else {
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
    }
}

static void crew_state_panic(CrewMember* c, uint32_t ship_slot, int crew_idx, float dt, float ship_hp) {
    (void)ship_hp;
    if (c->state != CREW_STATE_PANIC) {
        c->state = CREW_STATE_PANIC;
        c->work_timer = 0.f;
        crew_nav_clear(crew_idx);
        int from = pf_nearest_walkable(ship_slot, c->pos_local, 5.f);
        if (from >= 0) {
            int path[CREW_PATH_MAX];
            int n = pf_find_reachable_prop(ship_slot, from, NODE_PROP_EJECT, path, CREW_PATH_MAX);
            if (n >= 2) crew_nav_set(crew_idx, ship_slot, path, n);
        }
    }
    int r = crew_nav_step(c, crew_idx, dt * 1.5f);
    if (r == 1) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = 999.f;
    } else if (r == -1) {
        c->anim_timer -= dt;
        if (c->anim_timer <= 0.f) {
            c->anim_timer = 0.5f;
            float ang = xrng_range(0.f, TAU_F);
            V3 dir = v3(cosf(ang), 0.f, sinf(ang));
            c->pos_local = v3add(c->pos_local, v3mul(dir, CREW_WALK_SPEED * 1.2f * dt));
            V3 resolved;
            walker_collide(ship_slot, c->pos_local, c->pos_local, &resolved);
            c->pos_local = resolved;
        }
    }
}

static void crew_state_combat(CrewMember* c, uint32_t ship_slot, int crew_idx, float dt) {
    (void)ship_slot;
    uint32_t target = UINT32_MAX;
    float best_d2 = 100.f;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!entity_alive(i)) continue;
        if (i == c->entity_slot) continue;
        Thing* t = (Thing*)entity_get(i);
        if (!t) continue;
        if (t->type != ET_ALIEN && t->type != ET_CREW) continue;
        if (!(t->flags & ENT_FLAG_HOSTILE)) continue;
        float d2 = v3distsq(t->pos, c->pos_local);
        if (d2 < best_d2) { best_d2 = d2; target = i; }
    }
    if (target == UINT32_MAX) {
        c->anim_timer -= dt;
        if (c->anim_timer <= 0.f) {
            c->state = CREW_STATE_IDLE;
            c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
            crew_nav_clear(crew_idx);
        }
        return;
    }
    Thing* tgt = (Thing*)entity_get(target);
    if (!tgt) return;
    V3 to = v3sub(tgt->pos, c->pos_local);
    c->yaw = atan2f(to.x, -to.z);
}

static void crew_tick_state_update_v2(CrewMember* c, uint32_t ship_slot, int crew_idx, float dt) {
    if (!c) return;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return;
    float ship_hp = crew_ship_hp_frac(ship_slot);
    if (ship_hp < 0.30f) { crew_state_panic(c, ship_slot, crew_idx, dt, ship_hp); return; }
    if (c->state == CREW_STATE_PANIC) {
        c->state = CREW_STATE_IDLE;
        c->anim_timer = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
        crew_nav_clear(crew_idx);
        return;
    }
    switch (c->state) {
        case CREW_STATE_SIT:    crew_state_sit(c, ship_slot, dt, ship_hp); break;
        case CREW_STATE_WORK:   crew_state_work(c, ship_slot, dt, ship_hp); break;
        case CREW_STATE_WALK:   crew_state_walk(c, ship_slot, crew_idx, dt); break;
        case CREW_STATE_IDLE:   crew_state_idle(c, ship_slot, crew_idx, dt); break;
        case CREW_STATE_COMBAT: crew_state_combat(c, ship_slot, crew_idx, dt); break;
        default: break;
    }
}

static void crew_alerts_init(void) {
    if (g_crew_alerts) return;
    g_crew_alerts_cap = 8;
    g_crew_alerts = (CrewAlert*)xcalloc(g_crew_alerts_cap, sizeof(CrewAlert));
    g_crew_alerts_n = 0;
}

static CrewAlert* crew_alert_alloc(void) {
    for (uint32_t i = 0; i < g_crew_alerts_n; i++)
        if (!g_crew_alerts[i].active) return &g_crew_alerts[i];
    if (g_crew_alerts_n >= g_crew_alerts_cap) {
        uint32_t nc = g_crew_alerts_cap * 2 + 2;
        if (nc > CREW_ALERT_SOFT_CAP) nc = CREW_ALERT_SOFT_CAP;
        if (nc <= g_crew_alerts_cap) return NULL;
        CrewAlert* na = (CrewAlert*)xrealloc(g_crew_alerts, nc * sizeof(CrewAlert));
        if (!na) return NULL;
        memset(&na[g_crew_alerts_cap], 0, (nc - g_crew_alerts_cap) * sizeof(CrewAlert));
        g_crew_alerts = na;
        g_crew_alerts_cap = nc;
    }
    return &g_crew_alerts[g_crew_alerts_n++];
}

static int crew_alert_priority_for(CrewAlertKind k) {
    switch (k) {
        case CREW_ALERT_BREACH:        return 10;
        case CREW_ALERT_FIRE:          return 9;
        case CREW_ALERT_INTRUDER:      return 9;
        case CREW_ALERT_DEATH:         return 8;
        case CREW_ALERT_HULL_LOW:      return 8;
        case CREW_ALERT_REPAIR_NEEDED: return 6;
        case CREW_ALERT_MIXING_NEEDED: return 4;
        case CREW_ALERT_DOCKING:       return 3;
        default: return 1;
    }
}

static void crew_alert_push(CrewAlertKind kind, uint32_t target, V3 pos, float escalate_after) {
    if (kind == CREW_ALERT_NONE) return;
    for (uint32_t i = 0; i < g_crew_alerts_n; i++) {
        CrewAlert* a = &g_crew_alerts[i];
        if (!a->active) continue;
        if (a->kind == kind && a->target_slot == target) {
            a->created_at = (float)time_get();
            a->deadline = a->created_at + escalate_after;
            return;
        }
    }
    CrewAlert* a = crew_alert_alloc();
    if (!a) return;
    a->kind = kind;
    a->target_slot = target;
    a->pos = pos;
    a->priority = crew_alert_priority_for(kind);
    a->created_at = (float)time_get();
    a->deadline = a->created_at + escalate_after;
    a->assigned_crew = UINT32_MAX;
    a->active = 1;
    a->escalated = 0;
}

static int crew_is_free_v2(uint32_t crew_slot) {
    if (!entity_alive(crew_slot)) return 0;
    Thing* c = entity_get(crew_slot);
    if (!c || c->type != ET_CREW) return 0;
    NpcNeeds* n = npc_needs_get(crew_slot);
    if (!n) return 1;
    return (n->occupation == NPC_OCC_IDLE || n->occupation == NPC_OCC_LEISURE);
}

static uint32_t crew_pick_best_for_alert_v2(CrewAlert* a) {
    uint32_t best = UINT32_MAX;
    float best_score = 0.f;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        Thing* t = &g_things[i];
        if (t->type != ET_CREW) continue;
        if (!crew_is_free_v2(i)) continue;
        if (a->escalated) return i;
        NpcProfile* prof = npc_profile_get(i);
        NpcNeeds* n = npc_needs_get(i);
        float skill = prof ? clampf(prof->trades_done / 20.f, 0.1f, 1.f) : 0.3f;
        if (n) {
            for (int k = 0; k < NPC_ASPIRATION_MAX; k++) {
                if (!n->aspirations[k].active) continue;
                if (a->kind == CREW_ALERT_REPAIR_NEEDED &&
                    n->aspirations[k].kind == NPC_ASPIRATION_MASTER_REPAIR)
                    skill += 0.3f;
            }
        }
        float dist = v3dist(t->pos, a->pos);
        float score = skill / (1.f + dist / 10.f);
        if (score > best_score) { best_score = score; best = i; }
    }
    return best;
}

static void crew_assign_repair_alert(uint32_t crew_slot, uint32_t node, V3 pos) {
    npc_task_repair(crew_slot, node, pos);
    NpcNeeds* n = npc_needs_get(crew_slot);
    if (n) n->occupation = NPC_OCC_EMERGENCY;
}

static void crew_alerts_tick_v2(float dt) {
    (void)dt;
    float now = (float)time_get();
    for (uint32_t i = 0; i < g_crew_alerts_n; i++) {
        CrewAlert* a = &g_crew_alerts[i];
        if (!a->active) continue;
        if (a->target_slot != UINT32_MAX && !entity_alive(a->target_slot)) { a->active = 0; continue; }
        if (a->assigned_crew == UINT32_MAX) {
            uint32_t c = crew_pick_best_for_alert_v2(a);
            if (c != UINT32_MAX) {
                a->assigned_crew = c;
                crew_assign_repair_alert(c, a->target_slot, a->pos);
            }
        }
        if (!a->escalated && now > a->deadline) {
            a->escalated = 1;
            a->priority = 10;
            a->assigned_crew = crew_pick_best_for_alert_v2(a);
        }
        if (a->assigned_crew != UINT32_MAX && !crew_is_free_v2(a->assigned_crew))
            a->assigned_crew = UINT32_MAX;
    }
}

static void crew_alert_breach(V3 pos) {
    crew_alert_push(CREW_ALERT_BREACH, UINT32_MAX, pos, g_crew_alert_specs[CREW_ALERT_BREACH].escalate_after);
}
static void crew_alert_fire(V3 pos) {
    crew_alert_push(CREW_ALERT_FIRE, UINT32_MAX, pos, g_crew_alert_specs[CREW_ALERT_FIRE].escalate_after);
}
static void crew_alert_intruder(uint32_t e) {
    crew_alert_push(CREW_ALERT_INTRUDER, e, v3zero(), g_crew_alert_specs[CREW_ALERT_INTRUDER].escalate_after);
}
static void crew_alert_repair_needed(uint32_t node, V3 pos) {
    crew_alert_push(CREW_ALERT_REPAIR_NEEDED, node, pos, g_crew_alert_specs[CREW_ALERT_REPAIR_NEEDED].escalate_after);
}
static void crew_alert_death(V3 pos) {
    crew_alert_push(CREW_ALERT_DEATH, UINT32_MAX, pos, g_crew_alert_specs[CREW_ALERT_DEATH].escalate_after);
}

static void fire_compute_aim_assist(uint32_t slot, V3 origin, V3 aim,
                                     float assist_max, float cone_dot, V3* out) {
    if (!out) return;
    *out = aim;
    if (assist_max <= 0.f) return;
    if (cone_dot <= -1.f) cone_dot = 0.90f;
    PerceptionResult pr;
    perceive(slot, &pr);
    if (!pr.valid || pr.hostile_count == 0) return;
    V3 best_dir = aim;
    float best_dot = cone_dot;
    uint32_t best_slot = UINT32_MAX;
    for (uint32_t k = 0; k < pr.hostile_count; k++) {
        uint32_t h = pr.hostiles[k];
        Thing* ht = entity_get(h);
        if (!ht) continue;
        V3 to = v3norm(v3sub(ht->pos, origin));
        float dot = v3dot(to, aim);
        if (dot < cone_dot) continue;
        if (dot > best_dot) { best_dot = dot; best_dir = to; best_slot = h; }
    }
    if (best_slot == UINT32_MAX) return;
    float t = (best_dot - cone_dot) / (1.f - cone_dot);
    t = clampf(t, 0.f, 1.f);
    float blend = (1.f - t) * assist_max;
    V3 result = v3norm(v3add(v3mul(aim, 1.f - blend), v3mul(best_dir, blend)));
    if (v3lensq(result) < 1e-4f) return;
    *out = result;
}

static V3 fire_apply_spread(V3 aim, float spread, float precision_perk) {
    if (spread <= 0.f) return aim;
    float p = clampf(precision_perk * 0.05f, 0.f, 0.2f);
    float s = spread * (1.f - p);
    V3 right;
    if (fabsf(aim.y) < 0.9f) right = v3norm(v3cross(aim, v3(0.f, 1.f, 0.f)));
    else                     right = v3(1.f, 0.f, 0.f);
    V3 up = v3norm(v3cross(right, aim));
    float jx = xrng_range(-s, s);
    float jy = xrng_range(-s, s);
    V3 jitter = v3add(v3mul(right, jx), v3mul(up, jy));
    V3 result = v3norm(v3add(aim, jitter));
    if (v3lensq(result) < 1e-4f) return aim;
    return result;
}

static int fire_spawn_projectiles(uint32_t slot, uint32_t weapon_kind,
                                   V3 aim, V3 ship_vel, V3 ship_pos,
                                   float damage, float proj_speed, float spread,
                                   uint32_t dmg_type,
                                   float assist_max, float cone_dot) {
    Thing* t = entity_get(slot);
    if (!t) return 0;
    aim = v3norm(aim);
    if (v3lensq(aim) < 1e-4f) {
        float pitch = ENT_F(t, 24);
        aim = v3norm(v3(sinf(t->rot) * cosf(pitch), sinf(pitch), -cosf(t->rot) * cosf(pitch)));
        if (v3lensq(aim) < 1e-4f) aim = v3(0, 0, 1);
    }
    V3 assisted = aim;
    fire_compute_aim_assist(slot, ship_pos, aim, assist_max, cone_dot, &assisted);
    aim = fire_apply_spread(assisted, spread, (float)g_xp_b7.perk_precision);
    ShipDataExt* ext = ship_ext(slot);
    int fired = 0;
    int mount_count = 0;
    if (ext && ext->node_count > 0) {
        for (int k = 0; k < ext->node_count && fired < 2; k++) {
            if (!(ext->nodes[k].props_mask & NODE_PROP_WEAPON_MOUNT)) continue;
            mount_count++;
            if (fired >= 2) break;
            V3 mpos = ship_node_world_pos(slot, k);
            V3 vel  = v3add(ship_vel, v3mul(aim, proj_speed));
            projectile_spawn_ext(slot, mpos, vel, damage, dmg_type, weapon_kind);
            fired++;
        }
    }
    if (fired == 0 || mount_count == 0) {
        V3 mpos = v3add(ship_pos, v3mul(aim, t->radius + 0.5f));
        V3 vel  = v3add(ship_vel, v3mul(aim, proj_speed));
        projectile_spawn_ext(slot, mpos, vel, damage, dmg_type, weapon_kind);
        fired = 1;
    }
    return fired;
}

static void fire_tick_ship(uint32_t slot, const Intent* i, float dt) {
    Thing* t = entity_get(slot);
    if (!t || !i) return;
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (!sd || sd->weapon_slot == UINT32_MAX) return;
    WeaponData* wd = (WeaponData*)entity_side_ptr(sd->weapon_slot);
    if (!wd) return;
   if (wd->cooldown > 0.f) return;
    if (wd->heat_max > 0.f && wd->heat + wd->heat_per_shot > wd->heat_max) return;
    if (wd->heat < 0.f) wd->heat = 0.f;
    const WeaponDef* def = &g_weapon_defs[wd->kind];
    if (def->ammo_regen > 0.f && wd->ammo < wd->ammo_max) {
        float na = (float)wd->ammo + def->ammo_regen * dt;
        if (na > (float)wd->ammo_max) na = (float)wd->ammo_max;
        wd->ammo = (uint32_t)na;
    }
    int primary_down   = i->fire_primary;
    int secondary_down = i->fire_secondary && piloting_is_ship();
    if (!primary_down && !secondary_down) return;
    if (wd->cooldown > 0.f) return;
    if (wd->ammo < wd->ammo_per_shot) return;
    if (wd->heat_max > 0.f && wd->heat >= wd->heat_max) return;
    if (sd->energy < 1.f) return;

    V3 aim;
    if (primary_down) {
        // PRIMARY: screen-centre crosshair (ship forward / intent aim_dir)
        if (v3lensq(i->aim_dir) > 0.01f) {
            aim = i->aim_dir;
        } else {
            float pitch = ENT_F(t, 24);
            aim = v3norm(v3(sinf(t->rot) * cosf(pitch),
                             sinf(pitch),
                            -cosf(t->rot) * cosf(pitch)));
        }
    } else {
        // SECONDARY: floating cockpit-display crosshair — any direction,
        // all weapon mounts fire toward it ("more cannon shot another side")
        aim = cockpit_display_aim_direction();
    }
    float assist = def->aim_assist_max;
    if (assist > 0.f) assist *= (1.f + g_xp_b7.perk_precision * 0.05f);
    if (assist > 0.95f) assist = 0.95f;
    float spread = wd->spread * i->accuracy_mod;
    int fired = fire_spawn_projectiles(slot, wd->kind, aim, t->vel, t->pos,
                                        wd->damage, wd->projectile_speed,
                                        spread, def->dmg_type,
                                        assist, def->aim_cone_dot);
    if (fired == 0) return;
    wd->cooldown = wd->cooldown_max;
    wd->ammo -= wd->ammo_per_shot;
    wd->heat += wd->heat_per_shot;
    if (wd->heat > wd->heat_max) wd->heat = wd->heat_max;
    sd->energy -= 0.5f;
    if (sd->energy < 0.f) sd->energy = 0.f;
    audio_sfx_shoot(t->pos, wd->kind);
}

static void fire_tick_drone(uint32_t slot, const Intent* i, float dt) {
    Thing* t = entity_get(slot);
    if (!t || !i) return;
    float cd = ENT_F(t, 30);
    if (cd > 0.f) { cd -= dt; if (cd < 0.f) cd = 0.f; ENT_SET_F(t, 30, cd); }
    if (!i->fire_primary) return;
    if (cd > 0.f) return;
    V3 aim = v3(sinf(t->rot), 0.f, -cosf(t->rot));
    if (v3lensq(i->aim_dir) > 0.01f) aim = v3norm(i->aim_dir);
    int fired = fire_spawn_projectiles(slot, WEAPON_LASER, aim, t->vel, t->pos,
                                        PROJECTILE_DAMAGE * 0.5f,
                                        PROJECTILE_SPEED * 0.6f,
                                        0.f, DMG_ENERGY, 0.f, 0.f);
    if (fired > 0) {
        ENT_SET_F(t, 30, 0.15f);
        audio_sfx_shoot(t->pos, WEAPON_LASER);
    }
}

static void fire_tick_alien(uint32_t slot, const Intent* i, float dt) {
    Thing* t = entity_get(slot);
    if (!t || !i) return;
    float cd = ENT_F(t, 3);
    if (cd > 0.f) { cd -= dt; if (cd < 0.f) cd = 0.f; ENT_SET_F(t, 3, cd); }
    if (!i->fire_primary) return;
    if (cd > 0.f) return;
    uint32_t wk = ENT_I(t, 5);
    if (wk >= WEAPON_COUNT) wk = WEAPON_PULSE;
    const WeaponDef* def = &g_weapon_defs[wk];
    V3 aim = v3(sinf(t->rot), 0.f, -cosf(t->rot));
    if (v3lensq(i->aim_dir) > 0.01f) aim = v3norm(i->aim_dir);
    float spread = def->spread * i->accuracy_mod;
    int fired = fire_spawn_projectiles(slot, wk, aim, t->vel, t->pos,
                                        def->damage, def->projectile_speed,
                                        spread, def->dmg_type,
                                        def->aim_assist_max, def->aim_cone_dot);
    if (fired > 0) {
        ENT_SET_F(t, 3, def->cooldown_max * (0.9f + xrng_f() * 0.3f));
        audio_sfx_shoot(t->pos, wk);
    }
}

static void fire_tick_crew(uint32_t slot, const Intent* i, float dt) {
    Thing* t = entity_get(slot);
    if (!t || !i) return;
    float cd = ENT_F(t, 30);
    if (cd > 0.f) { cd -= dt; if (cd < 0.f) cd = 0.f; ENT_SET_F(t, 30, cd); }
    if (!i->fire_primary) return;
    if (cd > 0.f) return;
    V3 aim = v3norm(i->aim_dir);
    if (v3lensq(aim) < 0.01f) {
        float yaw = ENT_F(t, 20);
        aim = v3(sinf(yaw), 0.f, -cosf(yaw));
    }
    int fired = fire_spawn_projectiles(slot, WEAPON_PULSE, aim, t->vel, t->pos,
                                        PROJECTILE_DAMAGE * 0.5f,
                                        PROJECTILE_SPEED * 0.6f,
                                        0.08f, DMG_ENERGY, 0.f, 0.f);
    if (fired > 0) {
        ENT_SET_F(t, 30, 0.8f);
        audio_sfx_shoot(t->pos, WEAPON_PULSE);
    }
}

static void fire_tick(uint32_t slot, const Intent* i, float dt) {
    Thing* t = entity_get(slot);
    if (!t || !i) return;
    if (t->flags & ENT_FLAG_MARKED_DEAD) return;
    switch (t->type) {
        case ET_SHIP:  fire_tick_ship(slot, i, dt);  break;
        case ET_DRONE: fire_tick_drone(slot, i, dt); break;
        case ET_ALIEN: fire_tick_alien(slot, i, dt); break;
        case ET_PIRATE: fire_tick_alien(slot, i, dt); break;
        case ET_CREW:  fire_tick_crew(slot, i, dt);  break;
        default: break;
    }
}

static void fire_tick_all(float dt) {
    if (dt <= 0.f) return;
    cap_player_fire(dt);
    for (uint32_t k = 0; k < g_things_cap; k++) {
        if (!g_alive[k]) continue;
        Thing* t = &g_things[k];
        if (!(t->flags & ENT_FLAG_AI_CONTROLLED)) continue;
        if (t->flags & (ENT_FLAG_MARKED_DEAD | ENT_FLAG_PLAYER_OWNED)) continue;
        if (t->type != ET_SHIP && t->type != ET_DRONE &&
            t->type != ET_ALIEN && t->type != ET_PIRATE && t->type != ET_CREW) continue;
        if (k == g_player.inside_ship) continue;
        AiData* ai = (AiData*)entity_side_ptr(k);
        if (!ai) continue;
        fire_tick(k, &ai->intent, dt);
    }
}

static int crew_spawn(uint32_t slot, V3 local, uint32_t seed) {
    if (g_crew_count >= CREW_MAX) return -1;
    if (!entity_alive(slot)) return -1;
    int idx = g_crew_count++;
    CrewMember* c = &g_crew[idx];
    memset(c, 0, sizeof(*c));
    c->inside_ship  = slot;
    c->pos_local    = local;
    c->target_local = local;
    c->yaw          = xrng_range(-PI_F, PI_F);
    c->seed         = seed;
    c->state        = CREW_STATE_IDLE;
    c->anim_timer   = xrng_range(CREW_IDLE_MIN, CREW_IDLE_MAX);
    c->alive        = 1;
    c->entity_slot  = UINT32_MAX;
    uint64_t ox = g_xrng_x, oy = g_xrng_y;
    int og = g_xrng_gauss_valid;
    float os = g_xrng_gauss_spare;
    body_gen(seed, 0, 0, 0, &c->morphology);
    c->height        = c->morphology.height;
    c->uniform_color = c->morphology.detail_color;
    g_xrng_x = ox; g_xrng_y = oy;
    g_xrng_gauss_valid = og; g_xrng_gauss_spare = os;
    int hf = 0;
    float fy = floor_y_at(slot, c->pos_local.x, c->pos_local.z, &hf);
    if (hf) c->pos_local.y = fy;
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_CREW;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_NO_COLLIDE | ENT_FLAG_NO_INTEGRATE;
    t.pos    = local_to_world_pos(slot, c->pos_local);
    t.radius = 0.5f;
    t.hp = t.maxhp = 50.f;
    t.mass   = 70.f;
    ENT_SET_F(&t, 20, c->yaw);
    ENT_SET_I(&t, 30, 0xFFFFFFFFu);
    uint32_t eslot = entity_spawn(&t);
    if (eslot != UINT32_MAX) {
        c->entity_slot = eslot;
        AiData* ai = (AiData*)entity_attach_side(eslot, SD_AI);
        if (ai) {
            memset(ai, 0, sizeof(*ai));
            ai->target_slot = UINT32_MAX;
            ai->leader_slot = UINT32_MAX;
            ai->behavior_id = BEH_IDLE;
            intent_full_clear(&ai->intent);
        }
        {
            const char* tpl = "civilian_stock";
            uint32_t s = seed ? seed : (slot * 2654435761u);
            switch (s & 7) {
            case 0: tpl = "combat_amputee"; break;
            case 1: tpl = "aug_pilot"; break;
            case 2: tpl = "irradiated"; break;
            case 3: tpl = "labor_fit"; break;
            case 4: tpl = "symbiont_tentacle"; break;
            case 5: tpl = "franken_graft"; break;
            case 6: tpl = "hybrid_chimera"; break;
            default: break;
            }
            humanoid_spawn_from_template(eslot, tpl, s);
        }
    }
    return idx;
}

static void crew_remove(int idx) {
    if (idx < 0 || idx >= g_crew_count) return;
    body_free(&g_crew[idx].morphology);
    if (g_crew[idx].entity_slot != UINT32_MAX && entity_alive(g_crew[idx].entity_slot))
        entity_mark_dead(g_crew[idx].entity_slot);
    for (int i = idx; i < g_crew_count - 1; i++) g_crew[i] = g_crew[i + 1];
    g_crew_count--;
    crew_nav_clear(idx);
    crew_nav_clear(g_crew_count);
}

static void crew_release_all(void) {
    for (int i = 0; i < g_crew_count; i++) body_free(&g_crew[i].morphology);
    memset(g_crew, 0, sizeof(g_crew));
    g_crew_count = 0;
    for (int i = 0; i < CREW_MAX; i++) crew_nav_clear(i);
}

static void crew_init(void) {
    crew_release_all();
}

static void crew_generate_intent_fire(uint32_t crew_entity_slot, Intent* out) {
    if (!out) return;
    intent_clear_fire(out);
    Thing* t = entity_get(crew_entity_slot);
    if (!t || t->type != ET_CREW) return;
    PerceptionResult pr;
    perceive(crew_entity_slot, &pr);
    if (pr.hostile_count == 0) return;
    uint32_t best = pr.hostiles[0];
    float best_d2 = v3distsq(g_things[best].pos, t->pos);
    for (uint32_t k = 1; k < pr.hostile_count; k++) {
        float d2 = v3distsq(g_things[pr.hostiles[k]].pos, t->pos);
        if (d2 < best_d2) { best_d2 = d2; best = pr.hostiles[k]; }
    }
    if (best_d2 > 100.f) return;
    Thing* tgt = entity_get(best);
    if (!tgt) return;
    ai_intent_aim_at(out, t->pos, tgt->pos);
    out->fire_primary = 1;
    out->fire_target_slot = best;
    out->accuracy_mod *= combat_accuracy_mod(crew_entity_slot, best, WEAPON_PULSE);
}

static void crew_tick(float dt) {
    if (dt <= 0.f) return;
    for (int i = 0; i < g_crew_count; i++) {
        CrewMember* c = &g_crew[i];
        if (!c->alive) continue;
        if (c->inside_ship == UINT32_MAX) continue;
        if (!entity_alive(c->inside_ship)) { c->alive = 0; continue; }
        crew_tick_state_update_v2(c, c->inside_ship, i, dt);
        if (c->entity_slot != UINT32_MAX && entity_alive(c->entity_slot)) {
            Thing* ce = (Thing*)entity_get(c->entity_slot);
            if (ce) {
                ce->pos = local_to_world_pos(c->inside_ship, c->pos_local);
                ENT_SET_F(ce, 20, c->yaw);
            }
            Intent fire_intent;
            intent_full_clear(&fire_intent);
            crew_generate_intent_fire(c->entity_slot, &fire_intent);
            if (fire_intent.fire_primary) fire_tick_crew(c->entity_slot, &fire_intent, dt);
            npc_needs_tick(c->entity_slot, dt);
        }
    }
}

static void crew_publish(uint32_t crew_idx) {
    if (crew_idx >= (uint32_t)g_crew_count) return;
    CrewMember* c = &g_crew[crew_idx];
    if (!c->alive || c->entity_slot == UINT32_MAX) return;
    if (!entity_alive(c->entity_slot)) return;
    if (c->morphology.block_count <= 0) return;
    Thing* ship = (Thing*)entity_get(c->inside_ship);
    if (!ship) return;
    V3 world = local_to_world_pos(c->inside_ship, c->pos_local);
    V3 local_fwd = v3(sinf(c->yaw), 0.f, -cosf(c->yaw));
    V3 world_fwd = local_to_world_dir(c->inside_ship, local_fwd);
    float world_yaw = atan2f(world_fwd.x, -world_fwd.z);
    body_publish(&c->morphology, world, world_yaw, 0.f, c->entity_slot);
}

static void crew_publish_by_entity(uint32_t entity_slot) {
    for (int i = 0; i < g_crew_count; i++) {
        if (g_crew[i].entity_slot == entity_slot) { crew_publish((uint32_t)i); return; }
    }
}

static uint32_t ship_matinv_get(uint32_t ship_slot, uint16_t mid) {
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd || mid >= MATERIAL_COUNT) return 0;
    return sd->matinv[mid];
}

static void ship_matinv_set(uint32_t ship_slot, uint16_t mid, uint32_t q) {
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd || mid >= MATERIAL_COUNT) return;
    sd->matinv[mid] = q;
}

static void ship_node_hp_ptrs(ShipDataExt* ext, int node_idx,
                               float** hp_out, float** max_out,
                               uint16_t* mat_out, int* is_armor_out) {
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    ShipNode* n = &ext->nodes[node_idx];
    if (n->armor_count > 0 && n->armor_refs[0] >= 0 && n->armor_refs[0] < ext->armor_count) {
        ArmorLayer* a = &ext->armor[n->armor_refs[0]];
        *hp_out      = &a->hp;
        *max_out     = &a->maxhp;
        *mat_out     = a->material_id;
        *is_armor_out = 1;
    } else {
        *hp_out      = &n->current_hp;
        *max_out     = &n->structural_hp;
        *mat_out     = n->material_id;
        *is_armor_out = 0;
    }
}

static void ship_repair_cost(uint32_t ship_slot, int node_idx, RepairCost* out) {
    if (!out) return;
    memset(out, 0, sizeof(*out));
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return;
    float* hp = NULL; float* max_hp = NULL; uint16_t mat = 0; int is_armor = 0;
    ship_node_hp_ptrs(ext, node_idx, &hp, &max_hp, &mat, &is_armor);
    if (!hp || !max_hp || *max_hp <= 0.f) return;
    float missing = *max_hp - *hp;
    if (missing < 0.5f) return;
    float missing_frac = missing / *max_hp;
    ShipNode* n = &ext->nodes[node_idx];
    V3 d = v3mul(n->half_ext, 2.f);
    float volume = d.x * d.y * d.z * (is_armor ? 0.15f : 1.f);
    if (volume < 0.001f) volume = 0.001f;
    const Material* m = (mat < g_matpool.count) ? &g_matpool.cache[mat] : NULL;
    float weight = m ? m->weight : 1.f;
    if (weight < 0.1f) weight = 0.1f;
    float qtyf = missing_frac * volume * weight * 8.f;
    uint32_t qty = (uint32_t)ceilf(qtyf);
    if (qty < 1) qty = 1;
    if (ext->is_platform) qty *= 2;
    out->lines[0].material_id = mat;
    out->lines[0].qty = (uint16_t)(qty > 0xFFFF ? 0xFFFF : qty);
    out->count = 1;
    out->time_required = missing_frac * 30.f;
    if (ext->is_platform) out->time_required *= 2.f;
    out->compute_required = 1;
}

static int repair_try_consume(uint32_t ship_slot, const RepairCost* cost, int dry_run) {
    if (!cost || cost->count <= 0) return 0;
    for (int i = 0; i < cost->count; i++) {
        RepairLine line = cost->lines[i];
        uint32_t have = ship_matinv_get(ship_slot, line.material_id);
        if (have >= line.qty) continue;
        int found = 0;
        for (uint32_t mid = 0; mid < g_matpool.count; mid++) {
            if (mid == (uint32_t)line.material_id) continue;
            if (mat_similarity(line.material_id, (uint16_t)mid) <= 0.60f) continue;
            uint32_t h2 = ship_matinv_get(ship_slot, (uint16_t)mid);
            if (h2 >= (uint32_t)(line.qty * 1.5f)) { found = 1; break; }
        }
        if (!found) return 0;
    }
    if (dry_run) return 1;
    for (int i = 0; i < cost->count; i++) {
        RepairLine line = cost->lines[i];
        uint32_t have = ship_matinv_get(ship_slot, line.material_id);
        if (have >= line.qty) {
            ship_matinv_set(ship_slot, line.material_id, have - line.qty);
            continue;
        }
        for (uint32_t mid = 0; mid < g_matpool.count; mid++) {
            if (mid == (uint32_t)line.material_id) continue;
            if (mat_similarity(line.material_id, (uint16_t)mid) <= 0.60f) continue;
            uint32_t h2 = ship_matinv_get(ship_slot, (uint16_t)mid);
            uint16_t penalty = (uint16_t)(line.qty * 1.5f);
            if (h2 >= penalty) {
                ship_matinv_set(ship_slot, (uint16_t)mid, h2 - penalty);
                break;
            }
        }
    }
    return 1;
}

static int repair_afford(uint32_t ship_slot, const RepairCost* cost) {
    return repair_try_consume(ship_slot, cost, 1);
}

static int repair_consume(uint32_t ship_slot, const RepairCost* cost) {
    return repair_try_consume(ship_slot, cost, 0);
}

static void repair_sources_init(void) {
    for (int i = 0; i < REPAIR_SRC_COUNT; i++) {
        g_repair_sources[i].rate = 0.f;
        g_repair_sources[i].range = 0.f;
    }
    g_repair_sources[REPAIR_SRC_WALKER_REACH].rate   = WALKER_REPAIR_RATE;
    g_repair_sources[REPAIR_SRC_WALKER_REACH].range  = WALKER_REPAIR_REACH;
    g_repair_sources[REPAIR_SRC_FOOT_DRONE].rate     = FOOT_REPAIR_RATE;
    g_repair_sources[REPAIR_SRC_FOOT_DRONE].range    = 3.f;
    g_repair_sources[REPAIR_SRC_SHIP_DRONE].rate     = SHIP_REPAIR_RATE;
    g_repair_sources[REPAIR_SRC_SHIP_DRONE].range    = 10.f;
    g_repair_sources[REPAIR_SRC_DOCK_ROBOT].rate     = DOCK_REPAIR_RATE;
    g_repair_sources[REPAIR_SRC_DOCK_ROBOT].range    = 1e9f;
    g_repair_sources[REPAIR_SRC_PLATFORM_ROBOT].rate = PLATFORM_REPAIR_RATE;
    g_repair_sources[REPAIR_SRC_PLATFORM_ROBOT].range = 1e9f;
}

static int repair_source_valid(RepairSource src, uint32_t ship_slot, int node_idx, uint32_t src_entity) {
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return 0;
    ShipNode* n = &ext->nodes[node_idx];
    Thing* ship = entity_get(ship_slot);
    if (!ship) return 0;
    switch (src) {
        case REPAIR_SRC_WALKER_REACH: {
            if (g_player.mode != PLAYER_MODE_ON_FOOT && g_player.mode != PLAYER_MODE_PLATFORM) return 0;
            if (g_player.inside_ship != ship_slot) return 0;
            if (!(n->props_mask & NODE_PROP_WALKABLE)) return 0;
            V3 nw = ship_node_world_pos(ship_slot, node_idx);
            V3 local_eye = v3(g_player.walker.pos_local.x,
                               g_player.walker.pos_local.y + g_player.walker.eye_height,
                               g_player.walker.pos_local.z);
            V3 pw = v3add(ship->pos, local_to_world_dir(ship_slot, local_eye));
            float reach = g_repair_sources[src].range + n->half_ext.x;
            return (v3dist(nw, pw) <= reach) ? 1 : 0;
        }
        case REPAIR_SRC_SHIP_DRONE:
        case REPAIR_SRC_FOOT_DRONE: {
            Thing* d = entity_get(src_entity);
            if (!d || d->type != ET_DRONE) return 0;
            uint32_t caps = ENT_I(d, 21);
            if (!(caps & DRONE_CAP_REPAIR)) return 0;
            int dsrc = (int)ENT_I(d, 22);
            if (src == REPAIR_SRC_FOOT_DRONE && dsrc != DRONE_SOURCE_FOOT) return 0;
            if (src == REPAIR_SRC_SHIP_DRONE && dsrc != DRONE_SOURCE_SHIP) return 0;
            V3 nw = ship_node_world_pos(ship_slot, node_idx);
            float reach = g_tuning.drone_repair_range + n->half_ext.x;
            return (v3dist(d->pos, nw) <= reach) ? 1 : 0;
        }
        case REPAIR_SRC_DOCK_ROBOT:     return g_game.docked ? 1 : 0;
        case REPAIR_SRC_PLATFORM_ROBOT: return ext->is_platform ? 1 : 0;
        default: return 0;
    }
}

static float repair_rate_effective(RepairSource src) {
    if ((int)src < 0 || (int)src >= REPAIR_SRC_COUNT) return 1.f;
    float base = g_repair_sources[src].rate;
    float mult = g_player_consensus.repair_speed_mult;
    if (mult < 0.5f) mult = 0.5f;
    if (mult > 2.0f) mult = 2.0f;
    return base * mult;
}

static int ship_repair_node(uint32_t ship_slot, int node_idx, RepairSource src,
                             uint32_t src_entity, float amount) {
    if (amount == 0.f) return 0;
    if (!repair_source_valid(src, ship_slot, node_idx, src_entity)) return 0;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return 0;
    float* hp = NULL; float* max_hp = NULL; uint16_t mat = 0; int is_armor = 0;
    ship_node_hp_ptrs(ext, node_idx, &hp, &max_hp, &mat, &is_armor);
    (void)mat;
    if (!hp || !max_hp || *max_hp <= 0.f) return 0;
    if (amount < 0.f) {
        *hp -= (-amount);
        if (*hp < 0.f) *hp = 0.f;
        if (!is_armor && *hp <= 0.f) {
            ext->nodes[node_idx].props_mask |= NODE_PROP_BREACHED;
            ext->nodes[node_idx].damage_visual = 3;
            dirty_invalidate(ship_slot, SHIP_DIRTY_TOPO);
        }
        return 1;
    }
    float missing = *max_hp - *hp;
    if (missing < 0.5f) return 0;
    float apply = (amount < missing) ? amount : missing;
    float frac = apply / *max_hp;
    RepairCost full;
    ship_repair_cost(ship_slot, node_idx, &full);
    if (full.count == 0) return 0;
    RepairCost scaled = full;
    for (int i = 0; i < scaled.count; i++) {
        uint32_t q = (uint32_t)ceilf((float)full.lines[i].qty * frac);
        if (q < 1) q = 1;
        scaled.lines[i].qty = (uint16_t)(q > 0xFFFF ? 0xFFFF : q);
    }
    if (!repair_afford(ship_slot, &scaled)) { notice_push("NEED MATERIALS"); return 0; }
    if (!repair_consume(ship_slot, &scaled)) return 0;
    *hp += apply;
    if (*hp > *max_hp) *hp = *max_hp;
    if (!is_armor && *hp >= *max_hp * 0.99f) {
        ext->nodes[node_idx].props_mask &= ~NODE_PROP_BREACHED;
        dirty_invalidate(ship_slot, SHIP_DIRTY_TOPO);
    }
    if (!is_armor) {
        ShipNode* n = &ext->nodes[node_idx];
        if (n->structural_hp > 0.f) {
            float nf = n->current_hp / n->structural_hp;
            n->damage_visual = (nf < 0.50f) ? 2 : (nf < 0.80f) ? 1 : 0;
        }
    }
    return 1;
}

static int repair_find_worst_node(uint32_t ship_slot, int from_node) {
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return -1;
    int best = -1;
    float best_frac = 1.f;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (n->structural_hp <= 0.f) continue;
        float f = n->current_hp / n->structural_hp;
        if (f < best_frac) { best_frac = f; best = i; }
    }
    (void)from_node;
    return best;
}

static int repair_find_nearest_damaged(uint32_t ship_slot, V3 pos, float range) {
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return -1;
    int best = -1;
    float best_d2 = range * range;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (n->structural_hp <= 0.f) continue;
        if (n->current_hp >= n->structural_hp) continue;
        float d2 = v3lensq(v3sub(n->pos_local, pos));
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    return best;
}

static int repair_tick(uint32_t src_slot, RepairSource src, uint32_t target_ship, float range_override, float dt) {
    if (dt <= 0.f) return 0;
    if (!entity_alive(target_ship)) return 0;
    ShipDataExt* ext = ship_ext(target_ship);
    if (!ext) return 0;
    V3 src_pos;
    if (src == REPAIR_SRC_WALKER_REACH) {
        src_pos = g_player.walker.pos_local;
    } else {
        Thing* d = entity_get(src_slot);
        if (!d) return 0;
        src_pos = d->pos;
    }
    float range = range_override > 0.f ? range_override : g_repair_sources[src].range;
    int node = -1;
    if (src == REPAIR_SRC_WALKER_REACH) {
        int best = -1;
        float best_d2 = range * range;
        for (int i = 0; i < ext->node_count; i++) {
            if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
            if (ext->nodes[i].current_hp >= ext->nodes[i].structural_hp) continue;
            float d2 = v3lensq(v3sub(ext->nodes[i].pos_local, src_pos));
            if (d2 < best_d2) { best_d2 = d2; best = i; }
        }
        node = best;
    } else if (src == REPAIR_SRC_SHIP_DRONE || src == REPAIR_SRC_FOOT_DRONE) {
        Thing* d = entity_get(src_slot);
        if (!d) return 0;
        int best = -1;
        float best_d2 = range * range;
        for (int i = 0; i < ext->node_count; i++) {
            if (ext->nodes[i].current_hp >= ext->nodes[i].structural_hp) continue;
            V3 nw = ship_node_world_pos(target_ship, i);
            float d2 = v3distsq(nw, d->pos);
            if (d2 < best_d2) { best_d2 = d2; best = i; }
        }
        node = best;
    } else {
        node = repair_find_worst_node(target_ship, 0);
    }
    if (node < 0) return 0;
    float rate = repair_rate_effective(src);
    return ship_repair_node(target_ship, node, src, src_slot, rate * dt);
}

static void repair_tick_all(float dt) {
    if (dt <= 0.f) return;
    if ((g_player.mode == PLAYER_MODE_ON_FOOT || g_player.mode == PLAYER_MODE_PLATFORM) &&
        g_player.inside_ship != UINT32_MAX && g_player_intent.repair) {
        repair_tick(0, REPAIR_SRC_WALKER_REACH, g_player.inside_ship, 0.f, dt);
    }
    for (uint32_t k = 0; k < g_things_cap; k++) {
        if (!g_alive[k]) continue;
        Thing* t = &g_things[k];
        if (t->type != ET_DRONE) continue;
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        uint32_t caps = ENT_I(t, 21);
        if (!(caps & DRONE_CAP_REPAIR)) continue;
        uint32_t target_ship = ENT_I(t, 24);
        if (target_ship == UINT32_MAX || !entity_alive(target_ship)) continue;
        int dsrc = (int)ENT_I(t, 22);
        RepairSource src = (dsrc == DRONE_SOURCE_FOOT) ? REPAIR_SRC_FOOT_DRONE : REPAIR_SRC_SHIP_DRONE;
        repair_tick(k, src, target_ship, 0.f, dt);
    }
}

static uint32_t mining_find_target(V3 eye, V3 look_dir, float range, float cone_dot) {
    uint32_t best = UINT32_MAX;
    float best_d2 = range * range;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        Thing* t = &g_things[i];
        if (t->type != ET_ASTEROID) continue;
        V3 delta = v3sub(t->pos, eye);
        float d2 = v3lensq(delta);
        if (d2 > best_d2) continue;
        if (d2 < 0.0001f) continue;
        V3 ndir = v3mul(delta, 1.f / sqrtf(d2));
        if (v3dot(ndir, look_dir) < cone_dot) continue;
        best_d2 = d2;
        best = i;
    }
    return best;
}

static int mining_break_asteroid(uint32_t ast_slot) {
    Thing* a = entity_get(ast_slot);
    if (!a) return 0;
    uint32_t mat_seed = hash3_u32(a->seed, 0xCCu, 0xDDu);
    uint16_t mid = mat_pool_get(mat_seed);
    uint32_t amount = 1 + (uint32_t)(a->radius * 2.f);
    if (amount > 8) amount = 8;
    V3 pos = a->pos;
    float radius = a->radius;
    int n_pickups = 1 + (int)(xrng_u32() % 3u);
    uint32_t per = amount / (uint32_t)n_pickups;
    if (per < 1) per = 1;
    for (int i = 0; i < n_pickups; i++) {
        V3 off = v3(xrng_range(-1.5f, 1.5f), xrng_range(-0.5f, 0.5f), xrng_range(-1.5f, 1.5f));
        pickup_spawn(v3add(pos, off), PICKUP_TYPE_MAT, mid, (float)per);
    }
    particle_burst_procedural(pos, 8, 4.f, PART_TYPE_MINED_ORE,
                                hash_u32((uint32_t)(time_get() * 1000.f)));
    lanzadera_share_mined(pos, mid, amount);
    notice_push("ORE MINED");
    audio_sfx_pickup(pos);
    explosion_generic(pos, radius * 1.5f, 15.f, a->seed);
    entity_mark_dead(ast_slot);
    g_hints.collected_first_mat = 1;
    return 1;
}

static int mining_tick(uint32_t src_slot, const Intent* i, float dt) {
    if (!i->mine || dt <= 0.f) return 0;
    V3 eye;
    V3 look_dir;
    if (g_player.mode == PLAYER_MODE_EVA) {
        eye = g_player.eva_pos;
        look_dir = support_forward(&g_player.walker);
    } else if (g_player.mode == PLAYER_MODE_ON_FOOT || g_player.mode == PLAYER_MODE_PLATFORM) {
        if (g_player.inside_ship == UINT32_MAX) return 0;
        eye = local_to_world_pos(g_player.inside_ship, g_player.walker.pos_local);
        V3 local_fwd = support_forward(&g_player.walker);
        look_dir = local_to_world_dir(g_player.inside_ship, local_fwd);
    } else if (g_player.mode == PLAYER_MODE_PILOT) {
        Thing* t = entity_get(src_slot);
        if (!t) return 0;
        eye = t->pos;
        look_dir = v3norm(v3sub(t->vel, v3zero()));
        if (v3lensq(look_dir) < 0.01f) {
            float pitch = ENT_F(t, 24);
            look_dir = v3(sinf(t->rot) * cosf(pitch), sinf(pitch), -cosf(t->rot) * cosf(pitch));
        }
    } else return 0;
    look_dir = v3norm(look_dir);
    if (v3lensq(look_dir) < 0.01f) return 0;
    uint32_t target = mining_find_target(eye, look_dir, MINING_RANGE, 0.75f);
    if (target == UINT32_MAX) return 0;
    Thing* a = entity_get(target);
    if (!a) return 0;
    float rate = MINING_RATE * g_tuning.mining_rate_mult;
    rate *= 1.f + 0.3f * (float)g_player.mixing_level;
    a->hp -= rate * dt;
    if (a->hp <= 0.f) mining_break_asteroid(target);
    return 1;
}

static void mining_tick_all(float dt) {
    if (g_player.mode == PLAYER_MODE_PILOT) return;
    mining_tick(actor_ship_slot(), &g_player_intent, dt);
}

static void beh_idle_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)s; (void)a; (void)dt;
    ai_intent_brake(o);
}

static void beh_wander_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    Thing* t = entity_get(s);
    if (!t || !a) return;
    a->timer -= dt;
    if (a->timer <= 0.f) {
        a->timer = 3.f;
        a->waypoint = v3add(a->home_pos,
            v3(xrng_range(-15,15), xrng_range(-5,5), xrng_range(-15,15)));
    }
    ai_intent_steer_toward(o, t, a->waypoint);
}

static void beh_patrol_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    Thing* t = entity_get(s);
    if (!t || !a) return;
    a->timer -= dt;
    if (a->timer <= 0.f) {
        a->timer = 5.f;
        a->waypoint = v3add(a->home_pos,
            v3(xrng_range(-30,30), xrng_range(-10,10), xrng_range(-30,30)));
    }
    ai_intent_steer_toward(o, t, a->waypoint);
}

static void beh_follow_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)dt;
    Thing* t = entity_get(s);
    if (!t || !a || a->leader_slot == UINT32_MAX) return;
    Thing* l = entity_get(a->leader_slot);
    if (!l) { ai_intent_brake(o); return; }
    V3 behind = v3sub(l->pos, v3mul(l->vel, 0.2f));
    if (v3distsq(t->pos, behind) > 64.f) ai_intent_steer_toward(o, t, behind);
    else ai_intent_brake(o);
}

static void beh_orbit_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)dt;
    Thing* t = entity_get(s);
    if (!t || !a) return;
    Thing* tgt = entity_get(a->target_slot);
    if (!tgt) { ai_intent_brake(o); return; }
    ai_intent_steer_orbit(o, t, tgt->pos, 25.f);
}

static void beh_guard_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)dt;
    Thing* t = entity_get(s);
    if (!t || !a) return;
    uint32_t e = UINT32_MAX;
    float best_d2 = 225.f * 225.f;
    PerceptionResult pr;
    perceive(s, &pr);
    for (uint32_t k = 0; k < pr.hostile_count; k++) {
        uint32_t h = pr.hostiles[k];
        Thing* ht = entity_get(h);
        if (!ht) continue;
        if (v3distsq(ht->pos, a->home_pos) > 900.f) continue;
        float d2 = v3distsq(ht->pos, t->pos);
        if (d2 < best_d2) { best_d2 = d2; e = h; }
    }
    if (e != UINT32_MAX) {
        Thing* et = entity_get(e);
        if (et) ai_intent_steer_toward(o, t, et->pos);
        ai_intent_aim_at(o, t->pos, et ? et->pos : a->home_pos);
        o->fire_primary = (best_d2 < 400.f * 400.f);
        o->fire_target_slot = e;
    } else {
        if (v3distsq(t->pos, a->home_pos) > 16.f) ai_intent_steer_toward(o, t, a->home_pos);
        else ai_intent_brake(o);
    }
}

static void beh_chase_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)dt;
    Thing* t = entity_get(s);
    if (!t || !a) return;
    if (a->target_slot == UINT32_MAX || !entity_alive(a->target_slot)) {
        PerceptionResult pr;
        perceive(s, &pr);
        uint32_t nearest = UINT32_MAX;
        float best_d2 = 800.f * 800.f;
        for (uint32_t k = 0; k < pr.hostile_count; k++) {
            float d2 = v3distsq(g_things[pr.hostiles[k]].pos, t->pos);
            if (d2 < best_d2) { best_d2 = d2; nearest = pr.hostiles[k]; }
        }
        if (nearest == UINT32_MAX) { ai_intent_brake(o); return; }
        a->target_slot = nearest;
    }
    Thing* tgt = entity_get(a->target_slot);
    if (!tgt) { ai_intent_brake(o); return; }
    ai_intent_steer_toward(o, t, tgt->pos);
    ai_intent_aim_at(o, t->pos, tgt->pos);
    o->fire_primary = (v3dist(t->pos, tgt->pos) < 500.f) ? 1 : 0;
    o->fire_target_slot = a->target_slot;
}

static void beh_flee_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)dt;
    Thing* t = entity_get(s);
    if (!t || !a) return;
    uint32_t e = a->target_slot;
    if (e == UINT32_MAX || !entity_alive(e)) {
        PerceptionResult pr;
        perceive(s, &pr);
        if (pr.hostile_count == 0) { ai_intent_brake(o); return; }
        e = pr.hostiles[0];
    }
    Thing* et = entity_get(e);
    if (!et) { ai_intent_brake(o); return; }
    ai_intent_steer_away(o, t, et->pos);
    o->boost = 1;
}

static void beh_repair_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)a; (void)dt;
    Thing* t = entity_get(s);
    if (!t) return;
    uint32_t ship = ENT_I(t, 24);
    uint32_t node = ENT_I(t, 25);
    if (ship == UINT32_MAX || !entity_alive(ship) || node == UINT32_MAX) {
        ENT_SET_I(t, 24, UINT32_MAX);
        ai_intent_brake(o);
        return;
    }
    ShipDataExt* ext = ship_ext(ship);
    if (!ext || (int)node >= ext->node_count) { ai_intent_brake(o); return; }
    V3 nw = ship_node_world_pos(ship, (int)node);
    float d = v3dist(t->pos, nw);
    if (d > g_tuning.drone_repair_range * 0.7f) ai_intent_steer_toward(o, t, nw);
    else ai_intent_brake(o);
}

static void beh_crew_pilot_intent(uint32_t s, AiData* a, Intent* o, float dt) {
    (void)dt;
    if (!a) return;
    Thing* ship = entity_get(a->leader_slot);
    if (!ship) { ai_intent_brake(o); return; }
    uint32_t target = a->target_slot;
    if (target == UINT32_MAX) {
        PerceptionResult pr;
        perceive(s, &pr);
        uint32_t nearest = UINT32_MAX;
        float best_d2 = 800.f * 800.f;
        for (uint32_t k = 0; k < pr.hostile_count; k++) {
            float d2 = v3distsq(g_things[pr.hostiles[k]].pos, ship->pos);
            if (d2 < best_d2) { best_d2 = d2; nearest = pr.hostiles[k]; }
        }
        if (nearest != UINT32_MAX) { a->target_slot = nearest; target = nearest; }
    }
    if (target != UINT32_MAX && entity_alive(target)) {
        Thing* tgt = entity_get(target);
        if (tgt) {
            V3 dir = v3norm(v3sub(tgt->pos, ship->pos));
            ai_intent_steer_world_dir(o, ship, dir);
            ai_intent_aim_at(o, ship->pos, tgt->pos);
            o->fire_primary = 1;
            o->fire_target_slot = target;
        }
    } else {
        if (v3lensq(ship->vel) < 1.f) {
            V3 f = v3(sinf(ship->rot), 0, -cosf(ship->rot));
            ai_intent_steer_world_dir(o, ship, f);
        } else {
            ai_intent_brake(o);
        }
    }
}

static void behavior_register(uint32_t id, const char* name, BehIntentFn intent_fn) {
    if (id == BEH_NONE || id >= BEH_CUSTOM) return;
    BehaviorDef* b = &g_behaviors[id];
    b->id = id;
    b->name = name;
    b->intent = intent_fn;
    b->registered = 1;
    if (id >= g_behavior_count) g_behavior_count = id + 1;
}

static BehaviorDef* behavior_find(uint32_t id) {
    if (id == BEH_NONE || id >= BEH_CUSTOM) return NULL;
    return g_behaviors[id].registered ? &g_behaviors[id] : NULL;
}

static void behavior_force(uint32_t slot, uint32_t id) {
    AiData* ai = (AiData*)entity_side_ptr(slot);
    if (!ai) return;
    ai->behavior_id = id;
}

static void behavior_register_builtins(void) {
    behavior_register(BEH_IDLE,       "idle",       beh_idle_intent);
    behavior_register(BEH_WANDER,     "wander",     beh_wander_intent);
    behavior_register(BEH_PATROL,     "patrol",     beh_patrol_intent);
    behavior_register(BEH_FOLLOW,     "follow",     beh_follow_intent);
    behavior_register(BEH_ORBIT,      "orbit",      beh_orbit_intent);
    behavior_register(BEH_GUARD,      "guard",      beh_guard_intent);
    behavior_register(BEH_CHASE,      "chase",      beh_chase_intent);
    behavior_register(BEH_FLEE,       "flee",       beh_flee_intent);
    behavior_register(BEH_REPAIR_ID,  "repair",     beh_repair_intent);
    behavior_register(BEH_CREW_PILOT, "crew_pilot", beh_crew_pilot_intent);
    LOG("behavior_register_builtins: %u behaviors", g_behavior_count);
}

static void behavior_init(void) {
    memset(g_behaviors, 0, sizeof(g_behaviors));
    g_behavior_count = 0;
    behavior_register_builtins();
}

static void behavior_tick_all(float dt) { (void)dt; }

static void needs_tick_intent(uint32_t slot, AiData* ai, Intent* out) {
    (void)ai;
    Thing* t = entity_get(slot);
    if (!t) return;
    NpcNeeds* needs = npc_needs_get(slot);
    if (needs) {
        NpcPsychPhase phase = npc_psych_evaluate(needs);
        if (phase == NPC_PSYCH_PANIC || phase == NPC_PSYCH_MADNESS) {
            if (needs->vitals.stress > 0.9f) {
                V3 away_dir = xrng_dir3();
                ai_intent_steer_world_dir(out, t, away_dir);
                out->boost = 1;
                out->fire_primary = 0;
                return;
            }
        }
    }
    if (t->maxhp > 0.f && t->hp / t->maxhp < 0.15f) {
        CombatStateData* cs = combat_state_get(slot);
        if (cs && cs->opponent != UINT32_MAX && entity_alive(cs->opponent)) {
            Thing* op = entity_get(cs->opponent);
            if (op) {
                ai_intent_steer_away(out, t, op->pos);
                out->boost = 1;
                out->fire_primary = 0;
            }
        }
    }
}

static void ai_generate_intent_for(uint32_t slot, AiData* ai, float dt) {
    if (!ai) return;
    Thing* t = entity_get(slot);
    if (!t) return;
    if (t->flags & ENT_FLAG_MARKED_DEAD) return;
    Intent result;
    intent_full_clear(&result);
    result.accuracy_mod = 1.0f;
    BehaviorDef* beh = behavior_find(ai->behavior_id);
    if (beh && beh->intent) beh->intent(slot, ai, &result, dt);
    CombatStateData* cs = combat_state_get(slot);
    if (cs && cs->state != CS_IDLE) combat_tick_intent(slot, ai, dt, &result);
    needs_tick_intent(slot, ai, &result);
    ai->intent = result;
}

static void ai_generate_all_intents(float dt) {
    if (dt <= 0.f) return;
    perceive_all(dt);
    for (uint32_t k = 0; k < g_things_cap; k++) {
        if (!g_alive[k]) continue;
        Thing* t = &g_things[k];
        if (!(t->flags & ENT_FLAG_AI_CONTROLLED)) continue;
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->flags & ENT_FLAG_PLAYER_OWNED) continue;
        if (k == g_player.inside_ship) continue;
        if (t->type != ET_SHIP && t->type != ET_DRONE && t->type != ET_ALIEN && t->type != ET_PIRATE) continue;
        AiData* ai = (AiData*)entity_side_ptr(k);
        if (!ai) continue;
        ai_generate_intent_for(k, ai, dt);
        if (t->type == ET_SHIP) npc_needs_tick(k, dt);
    }
}

static uint8_t current_zone_faction(void) {
    int32_t idx = g_game.current_zone & 0xFF;
    if (idx < 0) return 0xFF;
    return g_zone_faction[idx];
}

static NpcPatrolRoster* npc_roster_for(uint32_t launcher_slot) {
    for (uint32_t i = 0; i < g_patrol_rosters_n; i++)
        if (g_patrol_rosters[i].launcher_slot == launcher_slot) return &g_patrol_rosters[i];
    if (g_patrol_rosters_n >= g_patrol_rosters_cap) {
        uint32_t nc = g_patrol_rosters_cap + 2;
        NpcPatrolRoster* nr = (NpcPatrolRoster*)xrealloc(g_patrol_rosters, nc * sizeof(NpcPatrolRoster));
        if (!nr) return NULL;
        memset(&nr[g_patrol_rosters_cap], 0, (nc - g_patrol_rosters_cap) * sizeof(NpcPatrolRoster));
        g_patrol_rosters = nr;
        g_patrol_rosters_cap = nc;
    }
    NpcPatrolRoster* r = &g_patrol_rosters[g_patrol_rosters_n++];
    memset(r, 0, sizeof(*r));
    r->launcher_slot = launcher_slot;
    r->target_count = 4;
    r->next_spawn_check = (float)time_get() + xrng_range(2.f, 8.f);
    return r;
}

static void npc_roster_push(NpcPatrolRoster* r, uint32_t slot, NpcRole role, float lifetime) {
    if (!r) return;
    if (r->count >= r->cap) {
        uint32_t nc = r->cap + 2;
        NpcPatrolEntry* np = (NpcPatrolEntry*)xrealloc(r->patrols, nc * sizeof(NpcPatrolEntry));
        if (!np) return;
        r->patrols = np;
        r->cap = nc;
    }
    NpcPatrolEntry* e = &r->patrols[r->count++];
    e->slot = slot;
    e->role = role;
    e->spawn_time = (float)time_get();
    e->lifetime = lifetime;
    e->seed = g_npc_next_seed++;
}

static void npc_roster_compact(NpcPatrolRoster* r) {
    if (!r) return;
    uint32_t w = 0;
    for (uint32_t i = 0; i < r->count; i++) {
        NpcPatrolEntry* e = &r->patrols[i];
        if (!entity_alive(e->slot)) continue;
        Thing* t = entity_get(e->slot);
        if (!t) continue;
        if ((float)time_get() - e->spawn_time > e->lifetime) { entity_mark_dead(e->slot); continue; }
        r->patrols[w++] = *e;
    }
    r->count = w;
}

static NpcRole npc_pick_role_for_zone(uint32_t launcher_slot) {
    ShipDataExt* ext = ship_ext(launcher_slot);
    if (!ext) return NPC_ROLE_PATROL;
    int hostile = 0, peaceful = 0;
    if (ext->is_platform) peaceful++;
    uint8_t zone_fid = current_zone_faction();
    int zone_hostile = 0;
    if (zone_fid < g_faction_count) zone_hostile = faction_local_regime_is_hostile(zone_fid);
    if (zone_hostile) { hostile += 7; peaceful += 3; }
    else if (zone_fid < g_faction_count) { hostile += 1; peaceful += 9; }
    else { hostile += 4; peaceful += 6; }
    int total = hostile + peaceful;
    if (total <= 0) return NPC_ROLE_PATROL;
    uint32_t r = xrng_u32() % (uint32_t)(total * 10);
    if (r < (uint32_t)(hostile * 10)) {
        static const NpcRole pool[4] = { NPC_ROLE_PATROL, NPC_ROLE_BOUNTY_HUNTER, NPC_ROLE_PIRATE, NPC_ROLE_MERCENARY };
        return pool[xrng_u32() % 4];
    }
    static const NpcRole pool2[6] = { NPC_ROLE_TRADER, NPC_ROLE_TRANSPORT, NPC_ROLE_EXPLORER, NPC_ROLE_SCIENTIST, NPC_ROLE_PATROL, NPC_ROLE_ENVOY };
    return pool2[xrng_u32() % 6];
}

static uint32_t npc_spawn_by_role(NpcRole role, uint32_t faction, uint32_t home_launcher, V3 pos) {
    uint32_t seed = g_npc_next_seed++;
    NpcTemplate* tmpl = npc_template_for_role(role);
    float hp_mul    = 1.f;
    float speed_mul = 1.f;
    uint32_t weapon_kind = WEAPON_PULSE;
    int32_t starting_rep = 0;
    float aggression = 0.3f, fear_base = 0.3f;
    if (tmpl) {
        hp_mul      = tmpl->hp_mul;
        speed_mul   = tmpl->speed_mul;
        weapon_kind = tmpl->weapon_kind;
        starting_rep = tmpl->starting_rep;
        aggression  = tmpl->aggression;
        fear_base   = tmpl->fear_base;
    }
    uint32_t slot = ship_create_with_weapon(pos, SHIP_PRESET_ENEMY, weapon_kind);
    if (slot == UINT32_MAX) return UINT32_MAX;
    Thing* t = entity_get(slot);
    if (!t) { entity_destroy(slot); return UINT32_MAX; }
    t->maxhp = t->hp = t->maxhp * hp_mul;
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (sd) { sd->max_speed *= speed_mul; sd->accel *= speed_mul; }
    NpcProfile* prof = npc_profile_alloc();
    if (!prof) { entity_destroy(slot); return UINT32_MAX; }
    npc_profile_init(prof, role, faction, home_launcher, seed);
    prof->rep_with_player = starting_rep;
    npc_profile_bind(slot, prof);
    NpcNeeds* needs = npc_needs_attach(slot);
    if (needs) { needs->vitals.stress = fear_base * 0.5f; needs->cache.dirty = 1; }
    NpcPsychState* psych = npc_psych_attach(slot);
    if (psych) { npc_psych_init(psych, seed); psych->fear = fear_base; psych->anger = aggression; }
    t->flags |= ENT_FLAG_AI_CONTROLLED;
    if (role == NPC_ROLE_PATROL || role == NPC_ROLE_BOUNTY_HUNTER ||
        role == NPC_ROLE_TRADER || role == NPC_ROLE_TRANSPORT ||
        role == NPC_ROLE_EXPLORER || role == NPC_ROLE_ENVOY ||
        role == NPC_ROLE_SCIENTIST)
        t->flags |= ENT_FLAG_PLAYER_OWNED;
    if (role == NPC_ROLE_PIRATE || role == NPC_ROLE_MERCENARY) t->flags |= ENT_FLAG_HOSTILE;
    AiData* ai = (AiData*)entity_side_ptr(slot);
    if (!ai) {
        AiData* new_ai = (AiData*)entity_attach_side(slot, SD_AI);
        if (new_ai) {
            memset(new_ai, 0, sizeof(*new_ai));
            new_ai->target_slot = UINT32_MAX;
            new_ai->leader_slot = UINT32_MAX;
            intent_full_clear(&new_ai->intent);
            ai = new_ai;
        }
    }
    if (ai) {
        ai->leader_slot = home_launcher;
        ai->home_pos = pos;
        switch (role) {
            case NPC_ROLE_PATROL:        ai->behavior_id = BEH_PATROL; break;
            case NPC_ROLE_TRADER:        ai->behavior_id = BEH_WANDER; break;
            case NPC_ROLE_PIRATE:        ai->behavior_id = BEH_CHASE;  break;
            case NPC_ROLE_BOUNTY_HUNTER: ai->behavior_id = BEH_PATROL; break;
            case NPC_ROLE_TRANSPORT:     ai->behavior_id = BEH_WANDER; break;
            case NPC_ROLE_EXPLORER:      ai->behavior_id = BEH_WANDER; break;
            case NPC_ROLE_ENVOY:         ai->behavior_id = BEH_ORBIT;  break;
            case NPC_ROLE_MERCENARY:     ai->behavior_id = BEH_CHASE;  break;
            case NPC_ROLE_REFUGEE:       ai->behavior_id = BEH_FLEE;   break;
            case NPC_ROLE_SCIENTIST:     ai->behavior_id = BEH_ORBIT;  break;
            default:                     ai->behavior_id = BEH_IDLE;   break;
        }
    }
    return slot;
}

static void patrol_roster_tick_all(float dt) {
    (void)dt;
    float now = (float)time_get();
    for (uint32_t i = 0; i < g_patrol_rosters_n; i++) {
        NpcPatrolRoster* r = &g_patrol_rosters[i];
        if (!entity_alive(r->launcher_slot)) continue;
        npc_roster_compact(r);
        if (now < r->next_spawn_check) continue;
        if (r->count >= r->target_count) continue;
        r->next_spawn_check = now + xrng_range(2.f, 8.f);
        NpcRole role = npc_pick_role_for_zone(r->launcher_slot);
        Thing* launcher = entity_get(r->launcher_slot);
        if (!launcher) continue;
        V3 spawn_pos = v3add(launcher->pos,
                              v3(xrng_range(-30.f, 30.f),
                                  xrng_range(-10.f, 10.f),
                                  xrng_range(-30.f, 30.f)));
        uint32_t slot = npc_spawn_by_role(role, current_zone_faction(), r->launcher_slot, spawn_pos);
        if (slot != UINT32_MAX) npc_roster_push(r, slot, role, 120.f + xrng_f() * 120.f);
    }
}

static void block7_init(void) {
    npc_template_init();
    npc_template_seed_defaults();
    drone_cam_init();
    repair_sources_init();
    LOG("block7_init: npc_templates=%u behaviors=%u", g_npc_templates.count, g_behavior_count);
}

static void block7_shutdown(void) {
    xfree(g_npc_templates.templates);
    g_npc_templates.templates = NULL;
    g_npc_templates.count = g_npc_templates.cap = 0;
    for (uint32_t i = 0; i < g_patrol_rosters_n; i++) xfree(g_patrol_rosters[i].patrols);
    xfree(g_patrol_rosters);
    g_patrol_rosters = NULL;
    g_patrol_rosters_n = g_patrol_rosters_cap = 0;
    LOG("block7_shutdown");
}

static int drone_deploy_from_ship(uint32_t ship_slot, uint32_t bp_seed) {
    if (!entity_alive(ship_slot)) return 0;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return 0;
    int free_idx = -1;
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        if (ext->drone_slots_ship[i] == UINT32_MAX ||
            !entity_alive(ext->drone_slots_ship[i])) {
            free_idx = i;
            break;
        }
    }
    if (free_idx < 0) {
        notice_push("NO FREE DRONE SLOT");
        return 0;
    }
    uint32_t slot = drone_spawn(bp_seed, DRONE_SOURCE_SHIP, ship_slot);
    if (slot == UINT32_MAX) return 0;
    ext->drone_slots_ship[free_idx] = slot;
    audio_sfx_drone_deploy();
    notice_push("DRONE DEPLOYED");
    return 1;
}

static int drone_deploy_from_foot(uint32_t bp_seed) {
    if (g_player.foot_drone_count >= MAX_DRONES_PER_SOURCE) {
        notice_push("NO FREE FOOT DRONE SLOT");
        return 0;
    }
    uint32_t slot = drone_spawn(bp_seed, DRONE_SOURCE_FOOT, UINT32_MAX);
    if (slot == UINT32_MAX) return 0;
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        if (g_player.foot_drone_slots[i] == UINT32_MAX ||
            !entity_alive(g_player.foot_drone_slots[i])) {
            g_player.foot_drone_slots[i] = slot;
            g_player.foot_drone_count++;
            break;
        }
    }
    audio_sfx_drone_deploy();
    notice_push("FOOT DRONE DEPLOYED");
    return 1;
}

static int drone_recall(uint32_t drone_slot) {
    if (!entity_alive(drone_slot)) return 0;
    Thing* d = entity_get(drone_slot);
    if (!d || d->type != ET_DRONE) return 0;
    uint32_t src = ENT_I(d, 22);
    if (src == DRONE_SOURCE_SHIP) {
        for (uint32_t s = 0; s < g_things_cap; s++) {
            if (!g_alive[s]) continue;
            if (g_things[s].type != ET_SHIP) continue;
            ShipDataExt* ext = ship_ext(s);
            if (!ext) continue;
            for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
                if (ext->drone_slots_ship[i] == drone_slot) {
                    ext->drone_slots_ship[i] = UINT32_MAX;
                    entity_mark_dead(drone_slot);
                    audio_sfx_drone_recall();
                    return 1;
                }
            }
        }
    } else if (src == DRONE_SOURCE_FOOT) {
        for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
            if (g_player.foot_drone_slots[i] == drone_slot) {
                g_player.foot_drone_slots[i] = UINT32_MAX;
                if (g_player.foot_drone_count > 0)
                    g_player.foot_drone_count--;
                entity_mark_dead(drone_slot);
                audio_sfx_drone_recall();
                return 1;
            }
        }
    }
    return 0;
}

static void drone_decision_tick(uint32_t slot, DroneDecision* dec, float dt) {
    if (!dec || !dec->used) return;
    (void)slot;
    if (dec->pending_timer > 0.f) {
        dec->pending_timer -= dt;
        if (dec->pending_timer <= 0.f) dec->pending_cap = 0;
    }
    if (dec->decision_delay > 0.f) dec->decision_delay -= dt;
}

static void drone_tick_all(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap && i < 512; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_DRONE) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        drone_decision_tick(i, &g_drone_decisions[i], dt);
    }
}

static void pirate_spawn_wave(uint32_t count, V3 center, uint32_t wave_seed) {
    if (count == 0 || count > 8) return;
    for (uint32_t i = 0; i < count; i++) {
        uint32_t h = hash3_u32(wave_seed, i, 0xFADEu);
        V3 offset = v3(((h)        & 0xFF) / 255.f * 200.f - 100.f,
                        ((h >> 8)  & 0xFF) / 255.f * 30.f,
                        ((h >> 16) & 0xFF) / 255.f * 200.f - 100.f);
        npc_spawn_by_role(NPC_ROLE_PIRATE, 0xFF, UINT32_MAX,
                            v3add(center, offset));
    }
    notice_push("PIRATES INBOUND");
    LOG("pirate_spawn_wave: %u at (%.0f,%.0f,%.0f)",
        count, center.x, center.y, center.z);
}

static void pirate_wave_tick(float dt) {
    static float    s_wave_timer = 0.f;
    static uint32_t s_wave_count = 0;
    s_wave_timer -= dt;
    if (s_wave_timer > 0.f) return;
    s_wave_timer = 40.f + xrng_f() * 40.f;
    s_wave_count++;
    if (s_wave_count > 3) return;
    uint32_t target = UINT32_MAX;
    if (g_player_platform_slot != UINT32_MAX && entity_alive(g_player_platform_slot))
        target = g_player_platform_slot;
    if (target == UINT32_MAX) target = g_game.player_ship_slot;
    if (target == UINT32_MAX) return;
    Thing* ship = entity_get(target);
    if (!ship) return;
    uint32_t n = 1 + (xrng_u32() % 3) + s_wave_count / 2;
    pirate_spawn_wave(n, ship->pos, xrng_u32());
    if (target == g_player_platform_slot)
        notice_push("RAID ON THE PLATFORM");
}

static ZonePersist* zone_current_persist(void) {
    return zone_persist_find(g_game.zone_coords[0], g_game.zone_coords[1], g_game.zone_coords[2]);
}

static void ambient_spawn_asteroid(V3 center, uint32_t seed) {
    ZonePersist* zp = zone_current_persist();
    float fd = zp && zp->pattern_gen ? zp->form[0] : 0.5f;
    float fv = zp && zp->pattern_gen ? zp->form[1] : 0.4f;
    float fr = zp && zp->pattern_gen ? zp->form[2] : 0.4f;
    float ysp = 12.f + fv * 40.f;
    /* low density zones rarely top-up asteroids */
    if (fd < 0.25f && (seed & 3u) != 0u) return;
    V3 off = v3(xrng_range(-ZONE_HALF * 0.8f, ZONE_HALF * 0.8f),
                 xrng_range(-ysp, ysp),
                 xrng_range(-ZONE_HALF * 0.8f, ZONE_HALF * 0.8f));
    float r = 2.5f + xrng_f() * (6.f + fr * 10.f);
    asteroid_spawn(v3add(center, off), r, seed);
}

static void ambient_spawn_alien(V3 center, uint32_t seed) {
    ZonePersist* zp = zone_current_persist();
    float fh = zp && zp->pattern_gen ? zp->form[3] : 0.35f;
    float fv = zp && zp->pattern_gen ? zp->form[1] : 0.4f;
    /* hazard gates ambient hostiles */
    if (fh < 0.30f) return;
    if (fh < 0.55f && (seed & 1u) == 0u) return;
    float ysp = 10.f + fv * 35.f;
    V3 off = v3(xrng_range(-ZONE_HALF * 0.7f, ZONE_HALF * 0.7f),
                 xrng_range(-ysp, ysp),
                 xrng_range(-ZONE_HALF * 0.7f, ZONE_HALF * 0.7f));
    alien_spawn(v3add(center, off), seed);
}

static void zone_population_tick(float dt) {
    static float s_ambient_timer = 0.f;
    if (g_zone_jump_notice_cd > 0.f) g_zone_jump_notice_cd -= dt;
    s_ambient_timer -= dt;
    if (s_ambient_timer > 0.f) return;
    ZonePersist* zp = zone_current_persist();
    float fd = zp && zp->pattern_gen ? zp->form[0] : 0.5f;
    float fh = zp && zp->pattern_gen ? zp->form[3] : 0.35f;
    /* denser / more hazardous zones refresh faster */
    float interval = 38.f - fd * 14.f - fh * 8.f;
    if (interval < 12.f) interval = 12.f;
    s_ambient_timer = interval + xrng_f() * 12.f;
    if (g_game.player_ship_slot == UINT32_MAX) return;
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (!ship) return;
    /* weight spawn kind by form */
    float w_ast = 0.35f + fd * 0.55f;
    float w_ali = fh * 0.85f;
    float sum = w_ast + w_ali;
    if (sum < 0.05f) return;
    uint32_t kind = (xrng_f() * sum < w_ast) ? 0u : 1u;
    if (kind >= g_ambient_count) kind = 0;
    g_ambient_spawners[kind](ship->pos, xrng_u32());
}

static int32_t zone_hash_index(int32_t x, int32_t y, int32_t z) {
    uint32_t h = hash3_u32((uint32_t)x, (uint32_t)y, (uint32_t)z);
    return (int32_t)(h & 0xFF);
}

static void zone_set_current(int32_t x, int32_t y, int32_t z) {
    g_game.zone_coords[0] = x;
    g_game.zone_coords[1] = y;
    g_game.zone_coords[2] = z;
    g_game.current_zone  = zone_hash_index(x, y, z);
    g_game.zone_seed     = zone_seed_calc(x, y, z);
    uint8_t fid = current_zone_faction();
    if (fid == 0xFF) {
        g_zone_faction[g_game.current_zone & 0xFF] =
            (uint8_t)(g_game.zone_seed % FACTION_COUNT);
    }
}

static void zone_generate(int32_t zx, int32_t zy, int32_t zz) {
    uint32_t seed = zone_seed_calc(zx, zy, zz);
    ZonePersist* zp = zone_persist_find(zx, zy, zz);
    if (!zp) {
        zp = zone_persist_create(zx, zy, zz, seed);
        if (!zp) return;
    } else {
        zp->last_visited = (uint32_t)time_get();
        zp->visits++;
        zone_persist_drop_entities(zx, zy, zz);
        zone_persist_restore_entities(zp);
        return;
    }
    if (!zp->pattern_gen) zone_form_bake(zp);
    mat_gen_for_zone(seed, zx, zy, zz);
    V3 center = v3((float)(zx * (int)ZONE_HALF * 2), 0.f,
                    (float)(zz * (int)ZONE_HALF * 2));
    uint64_t sx = g_xrng_x, sy = g_xrng_y;
    int sg = g_xrng_gauss_valid;
    float ss = g_xrng_gauss_spare;
    xrng_seed(seed ^ 0xCAFEu);
    /* form[0] density, [1] vertical, [2] rare, [3] hazard */
    float fd = zp->form[0], fv = zp->form[1], fr = zp->form[2], fh = zp->form[3];
    int n_ast = (int)(8.f + fd * 42.f + (float)(seed % 8));
    float y_spread = 12.f + fv * 50.f;
    for (int i = 0; i < n_ast; i++) {
        V3 offset = v3(xrng_range(-ZONE_HALF * 0.9f, ZONE_HALF * 0.9f),
                        xrng_range(-y_spread, y_spread),
                        xrng_range(-ZONE_HALF * 0.9f, ZONE_HALF * 0.9f));
        float r = 2.f + xrng_f() * (8.f + fr * 12.f);
        uint32_t mseed = hash3_u32(seed, (uint32_t)i, 0xAAu);
        asteroid_spawn(v3add(center, offset), r, mseed);
    }
    int n_lau = (fd > 0.35f) ? (1 + (int)((seed >> 8) % 3)) : ((seed >> 8) & 1);
    for (int i = 0; i < n_lau; i++) {
        V3 offset = v3(xrng_range(-ZONE_HALF * 0.7f, ZONE_HALF * 0.7f),
                        0.f,
                        xrng_range(-ZONE_HALF * 0.7f, ZONE_HALF * 0.7f));
        launcher_spawn(v3add(center, offset),
                        hash3_u32(seed, (uint32_t)i, 0xBBu));
    }
    int n_lan = (fr > 0.55f) ? (1 + (int)((seed >> 16) % 2)) : (int)((seed >> 16) % 2);
    for (int i = 0; i < n_lan; i++) {
        V3 offset = v3(xrng_range(-ZONE_HALF * 0.6f, ZONE_HALF * 0.6f),
                        xrng_range(-10.f, 10.f),
                        xrng_range(-ZONE_HALF * 0.6f, ZONE_HALF * 0.6f));
        lanzadera_spawn(v3add(center, offset),
                         hash3_u32(seed, (uint32_t)i, 0xCCu));
    }
    int n_ali = (int)(fh * 6.f + (float)((seed >> 24) % 3));
    if (n_ali > 8) n_ali = 8;
    for (int i = 0; i < n_ali; i++) {
        V3 offset = v3(xrng_range(-ZONE_HALF * 0.8f, ZONE_HALF * 0.8f),
                        xrng_range(-y_spread * 0.5f, y_spread * 0.5f),
                        xrng_range(-ZONE_HALF * 0.8f, ZONE_HALF * 0.8f));
        alien_spawn(v3add(center, offset),
                     hash3_u32(seed, (uint32_t)i, 0xDDu));
    }
    int n_ano = (fr > 0.6f || fh > 0.7f) ? (1 + (int)((seed >> 28) % 2)) : (int)((seed >> 28) % 2);
    for (int i = 0; i < n_ano; i++) {
        V3 offset = v3(xrng_range(-ZONE_HALF * 0.7f, ZONE_HALF * 0.7f),
                        0.f,
                        xrng_range(-ZONE_HALF * 0.7f, ZONE_HALF * 0.7f));
        anomaly_spawn(v3add(center, offset),
                       (uint32_t)(xrng_u32() % ANOMALY_TYPE_COUNT),
                       50.f, 8.f);
    }
    g_xrng_x = sx; g_xrng_y = sy;
    g_xrng_gauss_valid = sg; g_xrng_gauss_spare = ss;
    zone_spawn_content_extras(zx, zy, zz, seed);     /* contenido de B: regímenes, torres, naufragios, cápsulas, etc. */
    zone_persist_snapshot_entities(zp);
    zp->flags |= 1u;
    zone_set_current(zx, zy, zz);
    LOG("zone_generate: (%d,%d,%d) seed=%08X ast=%d lau=%d lan=%d ali=%d ano=%d form=%.2f/%.2f/%.2f/%.2f%s",
        zx, zy, zz, seed, n_ast, n_lau, n_lan, n_ali, n_ano,
        zp->form[0], zp->form[1], zp->form[2], zp->form[3],
        zp->radar_silent ? " silent" : "");
}

static uint32_t mission_spawn(uint32_t type, uint32_t target_type,
                                uint32_t target_count, float time_limit,
                                uint32_t reward_credits) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_MISSION;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC;
    t.pos    = v3zero();
    t.radius = 0.f;
    t.hp = t.maxhp = 1.f;
    t.mass   = 0.f;
    t.seed   = xrng_u32();
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    MissionData* md = (MissionData*)entity_attach_side(slot, SD_MISSION);
    if (!md) { entity_destroy(slot); return UINT32_MAX; }
    memset(md, 0, sizeof(*md));
    md->mission_type   = type;
    md->target_type    = target_type;
    md->target_count   = target_count;
    md->current_count  = 0;
    md->time_limit     = time_limit;
    md->time_remaining = time_limit;
    md->state          = MISSION_STATE_PENDING;
    md->reward_credits = reward_credits;
    md->flags          = 0;
    return slot;
}

static void mission_progress(uint32_t mission_slot, uint32_t amount) {
    if (!entity_alive(mission_slot)) return;
    MissionData* md = (MissionData*)entity_side_ptr(mission_slot);
    if (!md || md->state != MISSION_STATE_ACTIVE) return;
    md->current_count += amount;
    if (md->current_count >= md->target_count) {
        md->state = MISSION_STATE_COMPLETE;
        g_game.score += md->reward_credits;
        notice_push("MISSION COMPLETE");
        xp_gain_b7(50);
        achievement_notify("MISSION_5");
    }
}

static void mission_on_kill(uint32_t dead_type) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_MISSION) continue;
        MissionData* md = (MissionData*)entity_side_ptr(i);
        if (!md || md->state != MISSION_STATE_ACTIVE) continue;
        if (md->mission_type != MISSION_TYPE_KILL) continue;
        if (md->target_type != dead_type) continue;
        mission_progress(i, 1);
    }
}

static void mission_state_pending(uint32_t slot, MissionData* md, float dt) {
    (void)slot; (void)dt;
    md->state = MISSION_STATE_ACTIVE;
}

static void mission_state_active(uint32_t slot, MissionData* md, float dt) {
    (void)slot;
    md->time_remaining -= dt;
    if (md->time_remaining <= 0.f) {
        md->state = MISSION_STATE_FAILED;
        notice_push("MISSION FAILED");
    }
}

static void mission_state_complete(uint32_t slot, MissionData* md, float dt) {
    (void)md; (void)dt;
    if (entity_alive(slot)) entity_mark_dead(slot);
}

static void mission_state_failed(uint32_t slot, MissionData* md, float dt) {
    (void)md; (void)dt;
    if (entity_alive(slot)) entity_mark_dead(slot);
}

static const MissionStateFn g_mission_state_fns[] = {
    mission_state_pending,
    mission_state_active,
    mission_state_complete,
    mission_state_failed
};

static void mission_tick(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_MISSION) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        MissionData* md = (MissionData*)entity_side_ptr(i);
        if (!md || md->state > MISSION_STATE_FAILED) continue;
        MissionStateFn fn = g_mission_state_fns[md->state];
        if (fn) fn(i, md, dt);
    }
}

static uint32_t contract_reward_calc(uint16_t mat_id, uint16_t qty,
                                       uint32_t faction) {
    const Material* m = mat_get(mat_id);
    float base = m ? m->price_base * (float)qty : 10.f * (float)qty;
    float mult = g_player_consensus.mission_difficulty;
    if (mult < 0.5f) mult = 0.5f;
    if (mult > 2.0f) mult = 2.0f;
    base *= mult;
    if (faction < FACTION_COUNT) {
        int32_t rep = player_rep_get(faction);
        if (rep > 100)       base *= 1.15f;
        else if (rep < -100) base *= 0.7f;
    }
    uint32_t r = (uint32_t)base;
    if (r < 10) r = 10;
    return r;
}

static int contract_generate(uint32_t slot_idx, uint32_t seed,
                               uint32_t faction) {
    if (slot_idx >= MAX_CONTRACTS) return 0;
    uint64_t sx = g_xrng_x, sy = g_xrng_y;
    int sg = g_xrng_gauss_valid;
    float ss = g_xrng_gauss_spare;
    xrng_seed(seed);
    ContractData* c = &g_contracts[slot_idx];
    memset(c, 0, sizeof(*c));
    c->req_mat  = mat_pool_get(hash3_u32(seed, 0x11u, 0x22u));
    c->req_qty  = (uint16_t)(3 + xrng_u32() % 15);
    c->reward   = contract_reward_calc((uint16_t)c->req_mat,
                                         c->req_qty, faction);
    c->deadline = (float)time_get() + 300.f + xrng_f() * 600.f;
    c->flags    = 0;
    g_xrng_x = sx; g_xrng_y = sy;
    g_xrng_gauss_valid = sg; g_xrng_gauss_spare = ss;
    return 1;
}

static int contract_accept(uint32_t idx) {
    if (idx >= MAX_CONTRACTS) return 0;
    ContractData* c = &g_contracts[idx];
    if (c->flags & 1u) return 0;
    c->flags |= 1u;
    notice_push("CONTRACT ACCEPTED");
    return 1;
}

static int contract_deliver(uint32_t idx) {
    if (idx >= MAX_CONTRACTS) return 0;
    ContractData* c = &g_contracts[idx];
    if (!(c->flags & 1u)) return 0;
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return 0;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return 0;
    if (c->req_mat >= MATERIAL_COUNT) return 0;
    if (sd->matinv[c->req_mat] < c->req_qty) {
        notice_push("NOT ENOUGH MATERIALS");
        return 0;
    }
    sd->matinv[c->req_mat] -= c->req_qty;
    g_game.score += c->reward;
    c->flags = 0;
    notice_push("CONTRACT FULFILLED");
    achievement_progress_add("TRADER_10", 1);
    return 1;
}

static void contract_tick(float dt) {
    if (dt <= 0.f) return;
    float now = (float)time_get();
    for (uint32_t i = 0; i < MAX_CONTRACTS; i++) {
        ContractData* c = &g_contracts[i];
        if (!(c->flags & 1u)) continue;
        if (now > c->deadline) {
            c->flags = 0;
            notice_push("CONTRACT EXPIRED");
        }
    }
    static float s_refresh_timer = 0.f;
    s_refresh_timer += dt;
    if (s_refresh_timer > 60.f) {
        s_refresh_timer = 0.f;
        for (uint32_t i = 0; i < MAX_CONTRACTS; i++) {
            if (!(g_contracts[i].flags & 1u))
                contract_generate(i, hash3_u32((uint32_t)now, i, 0xAAu), 0xFF);
        }
    }
}

static void tournament_phase_idle(float dt) { (void)dt; }

static void tournament_phase_round(float dt) {
    g_tournament_timer -= dt;
    if (g_tournament_timer <= 0.f) {
        g_tournament_phase = TOURNAMENT_PHASE_INTERMISSION;
        g_tournament_timer = 5.f;
        g_tournament_wave++;
        notice_push("ROUND COMPLETE");
    }
    uint32_t enemy_count = 0;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_PIRATE && g_things[i].type != ET_ALIEN)
            continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        enemy_count++;
    }
    if (enemy_count == 0 && g_game.player_ship_slot != UINT32_MAX) {
        Thing* ship = entity_get(g_game.player_ship_slot);
        if (ship) {
            uint32_t n = 2 + (uint32_t)g_tournament_wave;
            if (n > 6) n = 6;
            pirate_spawn_wave(n, ship->pos,
                              hash3_u32((uint32_t)g_tournament_wave,
                                         0xBBu, 0xCCu));
        }
    }
}

static void tournament_phase_intermission(float dt) {
    g_tournament_timer -= dt;
    if (g_tournament_timer <= 0.f) {
        g_tournament_phase = TOURNAMENT_PHASE_ROUND;
        g_tournament_timer = 30.f;
    }
}

static void tournament_phase_ended(float dt) {
    (void)dt;
    g_tournament_mode = 0;
    notice_push("TOURNAMENT ENDED");
}

static const TournamentPhaseFn g_tournament_phase_fns[] = {
    tournament_phase_idle,
    tournament_phase_round,
    tournament_phase_intermission,
    tournament_phase_ended
};

static void tournament_start(void) {
    g_tournament_mode  = 1;
    g_tournament_wave  = 0;
    g_tournament_timer = 30.f;
    g_tournament_kills = 0;
    g_tournament_phase = TOURNAMENT_PHASE_ROUND;
    notice_push("TOURNAMENT STARTED");
}

static void tournament_tick(float dt) {
    if (!g_tournament_mode) return;
    if (g_tournament_phase > TOURNAMENT_PHASE_ENDED) return;
    TournamentPhaseFn fn = g_tournament_phase_fns[g_tournament_phase];
    if (fn) fn(dt);
    if (g_tournament_wave >= 10)
        g_tournament_phase = TOURNAMENT_PHASE_ENDED;
}

static int forge_step_process_queue(ForgeData* fd, float dt) {
    if (!fd || fd->queue_count == 0) return 0;
    fd->craft_timer += dt;
    if (fd->craft_timer >= 2.f) {
        uint16_t out_mat = fd->queue[0].out_mat;
        uint16_t out_qty = fd->queue[0].out_qty;
        fd->craft_timer = 0.f;
        for (uint32_t i = 1; i < fd->queue_count; i++)
            fd->queue[i - 1] = fd->queue[i];
        fd->queue_count--;
        fd->active_recipe = fd->queue_count > 0 ? 1 : 0;
        if (out_mat < COMP_COUNT && fd->owner_slot != UINT32_MAX) {
            Thing* f = entity_get(fd->owner_slot);
            if (f) {
                part_crate_spawn(v3add(f->pos, v3(1.2f, 0.6f, 0.f)),
                                 out_mat, out_qty);
                notice_push("PART BUILT");
            }
        }
        return 1;
    }
    return 0;
}

static const ForgeStepFn g_forge_steps[] = {
    forge_step_process_queue
};

static uint32_t forge_spawn(V3 pos) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_FORGE;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC;
    t.pos    = pos;
    t.radius = 2.f;
    t.mass   = 200.f;
    t.hp = t.maxhp = 100.f;
    t.seed   = xrng_u32();
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    ForgeData* fd = (ForgeData*)entity_attach_side(slot, SD_FORGE);
    if (!fd) { entity_destroy(slot); return UINT32_MAX; }
    memset(fd, 0, sizeof(*fd));
    return slot;
}

static int forge_add(uint32_t slot, uint16_t in_mat, uint16_t in_qty,
                      uint16_t out_mat, uint16_t out_qty) {
    if (!entity_alive(slot)) return 0;
    ForgeData* fd = (ForgeData*)entity_side_ptr(slot);
    if (!fd) return 0;
    if (fd->queue_count >= 8) return 0;
    fd->queue[fd->queue_count].in_mat  = in_mat;
    fd->queue[fd->queue_count].in_qty  = in_qty;
    fd->queue[fd->queue_count].out_mat = out_mat;
    fd->queue[fd->queue_count].out_qty = out_qty;
    fd->queue_count++;
    return 1;
}

static void forge_tick(float dt) {
    if (dt <= 0.f) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_FORGE) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        ForgeData* fd = (ForgeData*)entity_side_ptr(i);
        if (!fd) continue;
        for (size_t k = 0;
             k < sizeof(g_forge_steps) / sizeof(g_forge_steps[0]); k++)
            g_forge_steps[k](fd, dt);
    }
}

static uint32_t knowledge_piece_generate(KnowledgeKind kind, uint32_t seed) {
    if (g_know_pieces_n >= g_know_pieces_cap) {
        uint32_t nc = g_know_pieces_cap ? g_know_pieces_cap * 2 : 16;
        KnowledgePiece* np = (KnowledgePiece*)xrealloc(g_know_pieces,
                                                       nc * sizeof(KnowledgePiece));
        if (!np) return UINT32_MAX;
        memset(&np[g_know_pieces_cap], 0,
               (nc - g_know_pieces_cap) * sizeof(KnowledgePiece));
        g_know_pieces = np;
        g_know_pieces_cap = nc;
    }
    uint32_t idx = g_know_pieces_n++;
    KnowledgePiece* kp = &g_know_pieces[idx];
    memset(kp, 0, sizeof(*kp));
    kp->id   = idx + 1;
    kp->kind = (int)kind < KNOW_COUNT ? kind : KNOW_NONE;
    if ((int)kind < KNOW_COUNT && g_knowledge_kind_specs[kind].name) {
        snprintf(kp->name, sizeof(kp->name), "%s-%05X",
                 g_knowledge_kind_specs[kind].name, seed & 0xFFFFF);
        kp->difficulty = g_knowledge_kind_specs[kind].default_difficulty;
    } else {
        snprintf(kp->name, sizeof(kp->name), "Piece-%05X", seed & 0xFFFFF);
        kp->difficulty = 0.5f;
    }
    snprintf(kp->description, sizeof(kp->description),
             "Generated knowledge piece (seed=%08X)", seed);
    kp->prereq_count = 0;
    kp->domain = seed % 8;
    kp->effect_mult = 0.5f + (seed & 0xFF) / 255.f * 0.5f;
    kp->context_id = 0;
    kp->affecter_id = 0;
    kp->runtime_seed = seed;
    kp->consistent_with_science = 1;
    return idx;
}

static uint32_t knowledge_bundle_generate(uint32_t seed, const char* owner) {
    if (g_know_bundles_n >= g_know_bundles_cap) {
        uint32_t nc = g_know_bundles_cap ? g_know_bundles_cap * 2 : 8;
        KnowledgeBundle* nb = (KnowledgeBundle*)xrealloc(g_know_bundles,
                                                         nc * sizeof(KnowledgeBundle));
        if (!nb) return UINT32_MAX;
        memset(&nb[g_know_bundles_cap], 0,
               (nc - g_know_bundles_cap) * sizeof(KnowledgeBundle));
        g_know_bundles = nb;
        g_know_bundles_cap = nc;
    }
    uint32_t idx = g_know_bundles_n++;
    KnowledgeBundle* kb = &g_know_bundles[idx];
    memset(kb, 0, sizeof(*kb));
    kb->id = idx + 1;
    if (owner) {
        strncpy(kb->owner_name, owner, 31);
        kb->owner_name[31] = '\0';
    } else {
        snprintf(kb->owner_name, sizeof(kb->owner_name),
                 "Owner-%05X", seed & 0xFFFFF);
    }
    uint32_t n = 1 + (seed % 6);
    if (n > 16) n = 16;
    for (uint32_t i = 0; i < n; i++) {
        uint32_t pseed = hash3_u32(seed, i, 0xAAu);
        KnowledgeKind k = (KnowledgeKind)(pseed % (uint32_t)KNOW_COUNT);
        uint32_t pidx = knowledge_piece_generate(k, pseed);
        if (pidx != UINT32_MAX)
            kb->piece_ids[kb->piece_count++] = pidx + 1;
    }
    kb->secrecy = (uint8_t)(seed % 4);
    kb->runtime_seed = seed;
    return idx;
}

static void knowledge_rebuild(void) {
    g_know_pieces_n = 0;
    g_know_bundles_n = 0;
    for (int i = 0; i < MAX_ENTITIES * 4; i++)
        g_computer_knowledge[i].count = 0;
    memset(&g_player_knowledge, 0, sizeof(g_player_knowledge));
    memset(g_crew_knowledge, 0, sizeof(g_crew_knowledge));
    uint32_t bidx = knowledge_bundle_generate(0xC0DE1234u, "Player");
    if (bidx != UINT32_MAX) {
        KnowledgeBundle* kb = &g_know_bundles[bidx];
        for (uint32_t i = 0; i < kb->piece_count && i < 32; i++)
            g_player_knowledge.known_piece_ids[g_player_knowledge.count++] =
                kb->piece_ids[i];
    }
    LOG("knowledge_rebuild: %u pieces, %u bundles",
        g_know_pieces_n, g_know_bundles_n);
}

static int knowledge_learn(uint32_t player_idx, uint32_t piece_id) {
    if (player_idx >= 32) return 0;
    for (uint32_t i = 0; i < g_player_knowledge.count; i++)
        if (g_player_knowledge.known_piece_ids[i] == piece_id) return 0;
    if (g_player_knowledge.count >= 32) return 0;
    g_player_knowledge.known_piece_ids[g_player_knowledge.count++] = piece_id;
    notice_push("KNOWLEDGE GAINED");
    xp_gain_b7(25);
    return 1;
}

static int knowledge_player_has(uint32_t piece_id) {
    for (uint32_t i = 0; i < g_player_knowledge.count; i++)
        if (g_player_knowledge.known_piece_ids[i] == piece_id) return 1;
    return 0;
}

static int computer_knowledge_learn(uint32_t computer_idx, uint32_t bundle_id) {
    if (computer_idx >= MAX_ENTITIES * 4) return 0;
    ComputerKnowledge* ck = &g_computer_knowledge[computer_idx];
    if (ck->count >= 3) return 0;
    for (uint32_t i = 0; i < ck->count; i++)
        if (ck->bundle_ids[i] == bundle_id) return 0;
    ck->bundle_ids[ck->count++] = bundle_id;
    return 1;
}

static int crew_knowledge_learn(uint32_t crew_idx, uint32_t piece_id) {
    if (crew_idx >= CREW_MAX) return 0;
    CrewKnowledge* ck = &g_crew_knowledge[crew_idx];
    if (ck->count >= 8) return 0;
    for (uint32_t i = 0; i < ck->count; i++)
        if (ck->known_piece_ids[i] == piece_id) return 0;
    ck->known_piece_ids[ck->count++] = piece_id;
    return 1;
}

static uint32_t social_group_spawn(uint32_t kind, uint32_t seed) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_SOCIAL;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC;
    t.pos    = v3zero();
    t.radius = 0.f;
    t.hp = t.maxhp = 1.f;
    t.mass   = 0.f;
    t.seed   = seed;
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    SocialGroupData* sg = (SocialGroupData*)entity_attach_side(slot, SD_SOCIAL);
    if (!sg) { entity_destroy(slot); return UINT32_MAX; }
    memset(sg, 0, sizeof(*sg));
    sg->group_kind   = kind;
    sg->member_count = 1 + (seed % 100);
    sg->influence    = (seed & 0xFF) / 255.f;
    sg->leader_slot  = UINT32_MAX;
    sg->reputation   = 0;
    sg->flags        = 0;
    return slot;
}

static void social_reputation_adjust(uint32_t slot, int32_t delta) {
    if (!entity_alive(slot)) return;
    SocialGroupData* sg = (SocialGroupData*)entity_side_ptr(slot);
    if (!sg) return;
    sg->reputation += delta;
    if (sg->reputation > 1000)   sg->reputation = 1000;
    if (sg->reputation < -1000)  sg->reputation = -1000;
}

static void social_group_tick(float dt) { (void)dt; }

static void world_event_on_kill(const GameEvent* ev) { (void)ev; }

static void world_event_on_ship_under_attack(const GameEvent* ev) {
    (void)ev;
    for (uint32_t i = 0; i < g_patrol_rosters_n; i++) {
        NpcPatrolRoster* r = &g_patrol_rosters[i];
        if (!entity_alive(r->launcher_slot)) continue;
        Thing* l = entity_get(r->launcher_slot);
        if (!l) continue;
        float d = v3dist(l->pos, ev->pos);
        if (d < 800.f) {
            for (uint32_t k = 0; k < r->count; k++) {
                if (!entity_alive(r->patrols[k].slot)) continue;
                CombatStateData* cs = combat_state_attach(r->patrols[k].slot);
                if (cs && cs->state == CS_IDLE) {
                    combat_state_set(cs, CS_ALERT);
                    cs->opponent = ev->actor;
                }
            }
        }
    }
}

static void world_event_on_new_territory(const GameEvent* ev) { (void)ev; }

static void world_event_propagate(void) {
    for (uint32_t i = 0; i < g_event_queue_n; i++) {
        GameEvent* ev = &g_event_queue[i];
        if (!ev->broadcast) continue;
        if ((uint32_t)ev->kind >= EVT_COUNT) continue;
        WorldEventHandler h = g_world_event_handlers[ev->kind];
        if (h) h(ev);
    }
    g_event_queue_n = 0;
}

static void world_population_init(void) {
    zone_db_init();
    zone_set_current(0, 0, 0);
    zone_generate(0, 0, 0);
    LOG("world_population_init: zone (0,0,0) seeded");
}

static void world_population_shutdown(void) {
    for (uint32_t i = 0; i < g_patrol_rosters_n; i++)
        xfree(g_patrol_rosters[i].patrols);
    xfree(g_patrol_rosters);
    g_patrol_rosters = NULL;
    g_patrol_rosters_n = g_patrol_rosters_cap = 0;
    zone_db_shutdown();
    LOG("world_population_shutdown");
}

static void missions_contracts_init(void) {
    for (uint32_t i = 0; i < MAX_CONTRACTS; i++) {
        memset(&g_missions[i], 0, sizeof(MissionData));
        memset(&g_contracts[i], 0, sizeof(ContractData));
        contract_generate(i,
                          hash3_u32((uint32_t)time_get(), i, 0xAAu),
                          0xFF);
    }
    g_tournament_mode  = 0;
    g_tournament_phase = TOURNAMENT_PHASE_IDLE;
    g_tournament_wave  = 0;
    g_tournament_timer = 0.f;
    g_tournament_kills = 0;
    knowledge_rebuild();
    LOG("missions_contracts_init: contracts=%u knowledge_pieces=%u knowledge_bundles=%u",
        MAX_CONTRACTS, g_know_pieces_n, g_know_bundles_n);
}

static void missions_contracts_shutdown(void) {
    xfree(g_know_pieces);
    g_know_pieces = NULL;
    g_know_pieces_n = g_know_pieces_cap = 0;
    xfree(g_know_bundles);
    g_know_bundles = NULL;
    g_know_bundles_n = g_know_bundles_cap = 0;
    LOG("missions_contracts_shutdown");
}

static void block9_init(void) {
    world_population_init();
    missions_contracts_init();
    LOG("block9_init: zones+missions+contracts+tournament+forge+knowledge ready");
}

static void block9_shutdown(void) {
    missions_contracts_shutdown();
    world_population_shutdown();
    LOG("block9_shutdown");
}
static const char* tv_enter_ship(uint32_t slot) {
    if (!entity_alive(slot)) return "SHIP NOT FOUND";
    Thing* t = entity_get(slot);
    if (!t || t->type != ET_SHIP) return "NOT A SHIP";
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || ext->is_platform) return "IS A PLATFORM";
    int cockpit = ship_find_node_with_prop(slot, NODE_PROP_COCKPIT);
    if (cockpit < 0) return "NO COCKPIT";
    V3 cw = ship_node_world_pos(slot, cockpit);
    if (g_player.mode == PLAYER_MODE_EVA) {
        if (v3dist(cw, g_player.eva_pos) > 3.0f) return "TOO FAR FROM COCKPIT";
    } else if (g_player.mode == PLAYER_MODE_ON_FOOT) {
        if (g_player.inside_ship != slot) return "NOT IN THIS SHIP";
        V3 pw = local_to_world_pos(slot, g_player.walker.pos_local);
        if (v3dist(cw, pw) > 3.0f) return "TOO FAR FROM COCKPIT";
    }
    return NULL;
}

static const char* tv_board_platform(uint32_t slot) {
    if (!entity_alive(slot)) return "PLATFORM NOT FOUND";
    ShipDataExt* ext = ship_ext(slot);
    if (!ext || !ext->is_platform) return "NOT A PLATFORM";
    if (g_player.mode != PLAYER_MODE_EVA) return "MUST BE EVA";
    int best = -1;
    float best_d2 = 36.0f;
    for (int i = 0; i < ext->node_count; i++) {
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        V3 nw = ship_node_world_pos(slot, i);
        float d2 = v3distsq(nw, g_player.eva_pos);
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    if (best < 0) return "TOO FAR FROM PLATFORM";
    return NULL;
}

static const char* tv_enter_drone(uint32_t slot) {
    if (!entity_alive(slot)) return "DRONE NOT FOUND";
    Thing* d = entity_get(slot);
    if (!d || d->type != ET_DRONE) return "NOT A DRONE";
    if (!(d->flags & ENT_FLAG_PLAYER_OWNED)) return "NOT YOUR DRONE";
    if (d->flags & ENT_FLAG_MARKED_DEAD) return "DRONE DESTROYED";
    if ((float)time_get() - g_last_drone_switch < 0.5f) return "PLEASE WAIT";
    if (d->maxhp > 0.f && d->hp < d->maxhp * 0.1f) return "DRONE TOO DAMAGED";
    CombatStateData* cs = combat_state_get(slot);
    if (cs && cs->state == CS_ENGAGED) return "IN COMBAT";
    if (g_player.mode == PLAYER_MODE_ON_FOOT) {
        if (g_player.inside_ship == UINT32_MAX) return "NOT IN SHIP";
        V3 mw = local_to_world_pos(g_player.inside_ship, g_player.walker.pos_local);
        if (v3dist(mw, d->pos) > 4.f) return "TOO FAR FROM DRONE";
    }
    return NULL;
}

static const char* tv_exit_drone(uint32_t slot) {
    (void)slot;
    if (g_player.mode != PLAYER_MODE_PILOT) return "NOT PILOTING";
    if (!piloting_is_drone()) return "NOT IN DRONE";
    if ((float)time_get() - g_last_drone_switch < 0.5f) return "PLEASE WAIT";
    CombatStateData* cs = combat_state_get(g_player.inside_ship);
    if (cs && cs->state == CS_ENGAGED) return "IN COMBAT";
    return NULL;
}

static const char* tv_disembark(uint32_t slot) {
    (void)slot;
    if (g_player.mode != PLAYER_MODE_ON_FOOT &&
        g_player.mode != PLAYER_MODE_PLATFORM) return "NOT ON FOOT";
    if (g_player.inside_ship == UINT32_MAX) return "NOT IN SHIP";
    static float s_last = -10.f;
    if ((float)time_get() - s_last < 0.5f) return "PLEASE WAIT";
    ShipDataExt* ext = ship_ext(g_player.inside_ship);
    if (ext) {
        int eject = ship_find_node_with_prop(g_player.inside_ship, NODE_PROP_EJECT);
        if (eject >= 0) {
            V3 ew = ship_node_world_pos(g_player.inside_ship, eject);
            V3 pw = local_to_world_pos(g_player.inside_ship, g_player.walker.pos_local);
            if (v3dist(ew, pw) > 2.5f) return "MOVE TO EJECT NODE";
        }
    }
    return NULL;
}

static const char* tv_exit_ship(uint32_t slot) {
    (void)slot;
    if (g_player.mode != PLAYER_MODE_PILOT) return "NOT PILOTING";
    if (g_player.inside_ship == UINT32_MAX) return "NOT IN SHIP";
    Thing* t = entity_get(g_player.inside_ship);
    if (!t) return "SHIP LOST";
    if (t->type == ET_DRONE) return NULL;
    if (t->type != ET_SHIP) return "NOT A SHIP";
    ShipDataExt* ext = ship_ext(g_player.inside_ship);
    if (!ext) return "NO SHIP DATA";
    for (int i = 0; i < ext->node_count; i++)
        if (ext->nodes[i].props_mask & NODE_PROP_WALKABLE) return NULL;
    return "NO WALKABLE NODES";
}

static void ta_enter_ship(uint32_t slot) {
    int cockpit = ship_find_node_with_prop(slot, NODE_PROP_COCKPIT);
    g_player.prev_inside_ship = g_player.inside_ship;
    g_player.prev_mode        = (int)g_player.mode;
    g_player.inside_ship      = slot;
    g_player.mode             = PLAYER_MODE_PILOT;
    walker_reset_to_node(&g_player.walker, slot, cockpit);
    notice_push("PILOT MODE");
    g_hints.entered_cockpit = 1;
}

static void ta_board_platform(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    int best = -1;
    float best_d2 = 36.0f;
    for (int i = 0; i < ext->node_count; i++) {
        if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
        V3 nw = ship_node_world_pos(slot, i);
        float d2 = v3distsq(nw, g_player.eva_pos);
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    if (best < 0) return;
    g_player.prev_inside_ship = g_player.inside_ship;
    g_player.prev_mode        = (int)g_player.mode;
    g_player.inside_ship      = slot;
    g_player.mode             = PLAYER_MODE_PLATFORM;
    walker_reset_to_node(&g_player.walker, slot, best);
    notice_push("BOARDED PLATFORM");
}

static void ta_enter_drone(uint32_t slot) {
    uint32_t prev = g_player.inside_ship;
    g_player.prev_inside_ship = prev;
    g_player.prev_mode        = (int)g_player.mode;
    g_player.mode             = PLAYER_MODE_PILOT;
    g_player.inside_ship      = slot;
    AiData* ai = (AiData*)entity_side_ptr(slot);
    if (ai) {
        behavior_force(slot, BEH_IDLE);
        ai->leader_slot = UINT32_MAX;
        ai->target_slot = UINT32_MAX;
    }
    if (prev != UINT32_MAX) {
        ShipDataExt* ext = ship_ext(prev);
        if (ext && ext->node_count > 0)
            walker_reset_to_node(&g_player.walker, prev, 0);
    }
    notice_push("DRONE PILOT");
    g_last_drone_switch = (float)time_get();
    g_hints.deployed_drone = 1;
}

static void ta_exit_drone(uint32_t slot) {
    (void)slot;
    uint32_t drone_slot = g_player.inside_ship;
    Thing* d = entity_get(drone_slot);
    uint32_t prev = g_player.prev_inside_ship;
    if (!d || d->type != ET_DRONE) {
        g_player.mode = PLAYER_MODE_EVA;
        g_player.inside_ship = UINT32_MAX;
        if (v3lensq(g_player.eva_pos) < 0.01f)
            g_player.eva_pos = g_game.cam.pos;
        notice_push("EVA (drone lost)");
    } else if (prev == UINT32_MAX || !entity_alive(prev)) {
        g_player.mode = PLAYER_MODE_EVA;
        g_player.eva_pos = d->pos;
        g_player.eva_vel = d->vel;
        g_player.inside_ship = UINT32_MAX;
        notice_push("EVA (drone bailout)");
    } else {
        g_player.inside_ship = prev;
        g_player.mode        = (PlayerMode)g_player.prev_mode;
        notice_push("LEFT DRONE");
    }
    g_last_drone_switch = (float)time_get();
}

static void ta_disembark(uint32_t slot) {
    (void)slot;
    uint32_t ship_slot = g_player.inside_ship;
    Thing* ship = entity_get(ship_slot);
    if (!ship) return;
    int has_eject = (ship_find_node_with_prop(ship_slot, NODE_PROP_EJECT) >= 0);
    g_player.eva_pos = player_eye_base();
    g_player.eva_vel = ship->vel;
    g_player.prev_inside_ship = g_player.inside_ship;
    g_player.prev_mode        = (int)g_player.mode;
    g_player.mode             = PLAYER_MODE_EVA;
    g_player.inside_ship      = UINT32_MAX;
    notice_push(has_eject ? "EVA" : "EVA (no eject node)");
}

static void ta_exit_ship(uint32_t slot) {
    (void)slot;
    uint32_t s = g_player.inside_ship;
    Thing* t = entity_get(s);
    if (t && t->type == ET_DRONE) { ta_exit_drone(s); return; }
    g_player.mode = PLAYER_MODE_ON_FOOT;
    notice_push("ON FOOT");
}

static void player_transitions_init(void) {
    for (int i = 0; i < PLAYER_MODE_COUNT; i++)
        for (int j = 0; j < PLAYER_MODE_COUNT; j++)
            g_transitions[i][j] = (TransitionEntry){NULL, NULL};
    g_transitions[PLAYER_MODE_PILOT][PLAYER_MODE_ON_FOOT] =
        (TransitionEntry){ tv_exit_ship,   ta_exit_ship   };
    g_transitions[PLAYER_MODE_PILOT][PLAYER_MODE_EVA] =
        (TransitionEntry){ tv_disembark,   ta_disembark   };
    g_transitions[PLAYER_MODE_PILOT][PLAYER_MODE_PILOT] =
        (TransitionEntry){ tv_enter_drone, ta_enter_drone };
    g_transitions[PLAYER_MODE_ON_FOOT][PLAYER_MODE_PILOT] =
        (TransitionEntry){ tv_enter_ship,  ta_enter_ship  };
    g_transitions[PLAYER_MODE_ON_FOOT][PLAYER_MODE_EVA] =
        (TransitionEntry){ tv_disembark,   ta_disembark   };
    g_transitions[PLAYER_MODE_EVA][PLAYER_MODE_PILOT] =
        (TransitionEntry){ tv_enter_ship,  ta_enter_ship  };
    g_transitions[PLAYER_MODE_EVA][PLAYER_MODE_PLATFORM] =
        (TransitionEntry){ tv_board_platform, ta_board_platform };
    g_transitions[PLAYER_MODE_PLATFORM][PLAYER_MODE_EVA] =
        (TransitionEntry){ tv_disembark,   ta_disembark   };
}

static int player_transition_to(PlayerMode target, uint32_t target_slot) {
    if ((int)target < 0 || target >= PLAYER_MODE_COUNT) return 0;
    TransitionEntry* e = &g_transitions[g_player.mode][target];
    if (!e->apply) { notice_push("INVALID TRANSITION"); return 0; }
    if (e->validate) {
        const char* err = e->validate(target_slot);
        if (err) { notice_push(err); return 0; }
    }
    e->apply(target_slot);
    cap_apply_player_mode(g_player.mode);
    return 1;
}

static void player_force_eva(V3 pos, V3 vel, const char* reason) {
    g_player.prev_inside_ship = g_player.inside_ship;
    g_player.prev_mode        = (int)g_player.mode;
    g_player.mode             = PLAYER_MODE_EVA;
    g_player.eva_pos          = pos;
    g_player.eva_vel          = vel;
    g_player.inside_ship      = UINT32_MAX;
    if (reason) notice_push(reason);
}

static int player_try_fallback_eva_from_ship_death(void) {
    if (g_player.inside_ship == UINT32_MAX) return 0;
    if (entity_alive(g_player.inside_ship)) return 0;
    V3 spawn = g_game.cam.pos;
    V3 dir = v3sub(g_game.cam.target, g_game.cam.pos);
    float dl = v3len(dir);
    if (dl > 0.01f) spawn = v3add(spawn, v3mul(dir, 5.f / dl));
    player_force_eva(spawn, v3zero(), "SHIP LOST — EVA");
    return 1;
}

static void player_init(void) {
    inv_clear(&g_player.inventory);
    memset(&g_player, 0, sizeof(g_player));
    humanoid_mannequin(&g_player_morph, 1u, SPECIES_HUMANOID);
    humanoid_bake(&g_player_morph);
    g_player.mode             = PLAYER_MODE_PILOT;
    g_player.inside_ship      = UINT32_MAX;
    g_player.prev_inside_ship = UINT32_MAX;
    g_player.prev_mode        = (int)PLAYER_MODE_PILOT;
    g_player.suit_compute_total = 3;
    g_player.suit_compute_tier  = 1;
    g_player.suit_compute_used  = 0;
    g_player.foot_drone_count   = 0;
    g_player.walker.eye_height  = WALKER_EYE_STAND;
    g_player.walker.grounded    = 1;
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        g_player.foot_drone_slots[i] = UINT32_MAX;
        g_player.drone_slots[i]      = UINT32_MAX;
    }
    intent_full_clear(&g_player_intent);
    g_last_drone_switch = -1.f;
    player_transitions_init();
}

static uint32_t player_find_ship(float dist, uint32_t filter) {
    if (g_player.mode != PLAYER_MODE_EVA) return UINT32_MAX;
    V3 check = g_player.eva_pos;
    uint32_t best = UINT32_MAX;
    float best_d2 = dist * dist;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!entity_alive(i)) continue;
        Thing* t = entity_get(i);
        if (!t || t->type != ET_SHIP) continue;
        ShipDataExt* ext = ship_ext(i);
        if (!ext) continue;
        if ((filter & 1) && !ext->is_platform) continue;
        if ((filter & 2) &&  ext->is_platform) continue;
        float d2 = v3distsq(t->pos, check);
        if (d2 < best_d2) { best_d2 = d2; best = i; }
    }
    return best;
}

static uint32_t player_find_cockpit(void) {
    if (g_player.mode != PLAYER_MODE_ON_FOOT &&
        g_player.mode != PLAYER_MODE_EVA) return UINT32_MAX;
    V3 check = (g_player.mode == PLAYER_MODE_EVA)
             ? g_player.eva_pos
             : local_to_world_pos(g_player.inside_ship, g_player.walker.pos_local);
    uint32_t best = UINT32_MAX;
    float best_d2 = 16.0f;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!entity_alive(i)) continue;
        Thing* t = entity_get(i);
        if (!t || t->type != ET_SHIP) continue;
        ShipDataExt* ext = ship_ext(i);
        if (!ext || ext->is_platform) continue;
        for (int j = 0; j < ext->node_count; j++) {
            if (!(ext->nodes[j].props_mask & NODE_PROP_COCKPIT)) continue;
            V3 nw = ship_node_world_pos(i, j);
            float d2 = v3distsq(nw, check);
            if (d2 < best_d2) { best_d2 = d2; best = i; }
        }
    }
    return best;
}

static void camera_set(Camera* cam, V3 pos, V3 target, V3 up,
                        float fov, float znear, float zfar) {
    if (!cam) return;
    cam->pos    = pos;
    cam->target = target;
    cam->up     = up;
    cam->fov    = fov;
    cam->znear  = znear;
    cam->zfar   = zfar;
    cam->dirty  = 1;
}

static void camera_compute_view(Camera* cam) {
    if (!cam || !cam->dirty) return;
    mat4_lookat(cam->view, cam->pos, cam->target, cam->up);
    float asp = (float)(g_win_w > 0 ? g_win_w : 1280)
              / (float)(g_win_h > 0 ? g_win_h : 720);
    mat4_perspective(cam->proj, cam->fov, asp, cam->znear, cam->zfar);
    mat4_mul(cam->vp, cam->proj, cam->view);
    frustum_from_vp(&cam->frustum, cam->vp);
    cam->dirty = 0;
}

static V3 camera_shake_vec(void) {
    return v3(g_game.shake * 0.05f, 0.f, g_game.shake * 0.05f);
}

static V3 camera_up_vector(WalkerState* w) {
    V3 up = v3(0.f, 1.f, 0.f);
    if (w && w == &g_player.walker && g_player.inside_ship != UINT32_MAX && w->support.init &&
        (g_player.mode == PLAYER_MODE_ON_FOOT || g_player.mode == PLAYER_MODE_PLATFORM))
        up = local_to_world_dir(g_player.inside_ship, w->support.up);
    if (w && w->hurt_shake > 0.001f) {
        float s = w->hurt_shake;
        float t = (float)time_get();
        float roll = s * 0.15f
                   * (sinf(t * 75.f) * 0.7f + sinf(t * 51.f + 1.3f) * 0.3f);
        up.x += roll;
        up = v3norm(up);
    }
    return up;
}

static void frustum_from_vp(Frustum* fr, const Mat4 vp) {
    float p[6][4] = {
        { vp[3]+vp[0], vp[7]+vp[4],  vp[11]+vp[8],  vp[15]+vp[12] },
        { vp[3]-vp[0], vp[7]-vp[4],  vp[11]-vp[8],  vp[15]-vp[12] },
        { vp[3]+vp[1], vp[7]+vp[5],  vp[11]+vp[9],  vp[15]+vp[13] },
        { vp[3]-vp[1], vp[7]-vp[5],  vp[11]-vp[9],  vp[15]-vp[13] },
        { vp[3]+vp[2], vp[7]+vp[6],  vp[11]+vp[10], vp[15]+vp[14] },
        { vp[3]-vp[2], vp[7]-vp[6],  vp[11]-vp[10], vp[15]-vp[14] }
    };
    for (int i = 0; i < 6; i++) {
        float l = sqrtf(p[i][0]*p[i][0] + p[i][1]*p[i][1] + p[i][2]*p[i][2]);
        if (l > EPS) {
            p[i][0] /= l; p[i][1] /= l; p[i][2] /= l; p[i][3] /= l;
        }
        memcpy(fr->p[i], p[i], sizeof(p[i]));
    }
}

static int frustum_test_sphere(const Frustum* fr, V3 c, float r) {
    for (int i = 0; i < 6; i++) {
        float d = fr->p[i][0] * c.x + fr->p[i][1] * c.y
                + fr->p[i][2] * c.z + fr->p[i][3];
        if (d < -r) return 0;
    }
    return 1;
}

static V3 player_eye_base(void) {
    if (g_player.mode == PLAYER_MODE_EVA)
        return v3add(g_player.eva_pos, v3(0.f, EVA_EYE_OFFSET, 0.f));
    if (g_player.mode == PLAYER_MODE_ON_FOOT ||
        g_player.mode == PLAYER_MODE_PLATFORM) {
        if (g_player.inside_ship == UINT32_MAX) return v3zero();
        WalkerState* w = &g_player.walker;
        V3 local_eye = v3add(w->pos_local, v3mul(support_up(w), w->eye_height));
        V3 base = local_to_world_pos(g_player.inside_ship, local_eye);
        base = v3add(base, v3mul(local_to_world_dir(g_player.inside_ship, support_up(w)), walker_eye_bob(w)));
        return base;
    }
    return g_game.cam.pos;
}

static V3 player_eye(V3 shake) {
    return v3add(player_eye_base(), shake);
}

static V3 player_look(void) {
    WalkerState* w = &g_player.walker;
    V3 dir = support_forward(w);
    V3 eye = player_eye(v3zero());
    if (g_player.mode == PLAYER_MODE_EVA)
        return v3add(eye, v3mul(dir, 10.f));
    if (g_player.mode == PLAYER_MODE_ON_FOOT ||
        g_player.mode == PLAYER_MODE_PLATFORM) {
        if (g_player.inside_ship == UINT32_MAX) return v3add(eye, dir);
        V3 wd = local_to_world_dir(g_player.inside_ship, dir);
        return v3add(eye, v3mul(wd, 10.f));
    }
    return v3add(eye, dir);
}

static void camera_tick_ship_follow(uint32_t slot, float dt) {
    Thing* t = entity_get(slot);
    if (!t) {
        camera_set(&g_game.cam, v3(0, 4, 12), v3(0, 0, 20), v3(0, 1, 0),
                    1.2f, 0.5f, 8000.f);
        return;
    }
    float pitch = ENT_F(t, 24);
    V3 fwd = v3(sinf(t->rot) * cosf(pitch), sinf(pitch), -cosf(t->rot) * cosf(pitch));
    if (v3lensq(fwd) < 1e-4f) fwd = v3(0, 0, 1);
    float speed = v3len(t->vel);
    float speed_norm = clampf(speed / 200.f, 0.f, 1.f);
    float dist   = t->radius * 8.f + speed_norm * t->radius * 3.f;
    float height = t->radius * 1.6f + speed_norm * t->radius * 0.5f;

    V3 eye_target  = v3add(v3sub(t->pos, v3mul(fwd, dist)), v3(0.f, height, 0.f));
    V3 look_target = v3add(v3add(t->pos, v3mul(fwd, dist * 2.f)), v3mul(t->vel, 0.4f));

    static V3 s_eye  = {0, 0, 0};
    static V3 s_look = {0, 0, 0};
    static uint32_t s_slot = UINT32_MAX;
    if (s_slot != slot) {
        s_eye = eye_target; s_look = look_target; s_slot = slot;
    } else {
        float k = 1.f - expf(-8.f * dt);
        s_eye  = v3add(v3mul(s_eye,  1.f - k), v3mul(eye_target,  k));
        s_look = v3add(v3mul(s_look, 1.f - k), v3mul(look_target, k));
    }

    V3 up = v3(0.f, 1.f, 0.f);
    float zmin, zmax; cockpit_zoom_limits(&zmin, &zmax);
    float fov = (1.2f + speed_norm * 0.3f) / clampf(g_game.zoom, zmin, zmax);
    camera_set(&g_game.cam, v3add(s_eye, camera_shake_vec()), s_look,
                up, fov, 0.1f, 8000.f);
}

static void camera_tick_fp(float dt) {
    (void)dt;
    V3 eye  = player_eye(camera_shake_vec());
    V3 look = player_look();
    float zmin, zmax; cockpit_zoom_limits(&zmin, &zmax);
    float fov = 1.2f / clampf(g_game.zoom, zmin, zmax);
    if (g_player.walker.aiming) fov *= 0.75f;
    V3 up = camera_up_vector(&g_player.walker);
    camera_set(&g_game.cam, eye, look, up, fov, 0.05f, 8000.f);
}

static void drone_cam_init(void) {
    memset(&g_drone_cam, 0, sizeof(g_drone_cam));
    g_drone_cam.current_pose = CAM_DRONE_BEHIND;
    g_drone_cam.manual_override = (CamDronePoseKind)-1;
    memset(&g_drone_cam_poi, 0, sizeof(g_drone_cam_poi));
    g_drone_cam_poi.current_poi = UINT32_MAX;
    for (int i = 0; i < 4; i++) g_drone_cam_poi.recent_pois[i] = UINT32_MAX;
}

static CamDronePoseKind drone_cam_pick_pose(const Thing* d) {
    if (!d) return CAM_DRONE_BEHIND;
    if (g_drone_cam.manual_override != (CamDronePoseKind)-1)
        return g_drone_cam.manual_override;
    float hp_frac = (d->maxhp > 0.f) ? d->hp / d->maxhp : 1.f;
    if (hp_frac < 0.25f) return CAM_DRONE_UP;
    V3 v = d->vel;
    float vlen = v3len(v);
    if (vlen < 0.1f) return CAM_DRONE_BEHIND;
    float cf = cosf(d->rot), sf = sinf(d->rot);
    V3 fwd = v3(sf, 0.f, -cf);
    V3 right = v3(cf, 0.f, sf);
    float fwd_dot   = v3dot(v, fwd)   / vlen;
    float right_dot = v3dot(v, right) / vlen;
    float up_dot    = v.y             / vlen;
    if (up_dot > 0.5f)  return CAM_DRONE_DOWN;
    if (up_dot < -0.5f) return CAM_DRONE_UP;
    if (fabsf(right_dot) > 0.6f)
        return (right_dot > 0.f) ? CAM_DRONE_LEFT : CAM_DRONE_RIGHT;
    if (fwd_dot < -0.5f) return CAM_DRONE_FRONT;
    return CAM_DRONE_BEHIND;
}

static V3 drone_cam_pose_offset_local(CamDronePoseKind pose,
                                       float dist, float height) {
    switch (pose) {
        case CAM_DRONE_BEHIND:      return v3(0.f,          height, -dist);
        case CAM_DRONE_FRONT:       return v3(0.f,          height,  dist);
        case CAM_DRONE_LEFT:        return v3(-dist,        height,  0.f);
        case CAM_DRONE_RIGHT:       return v3( dist,        height,  0.f);
        case CAM_DRONE_UP:          return v3(0.f,          dist,    0.f);
        case CAM_DRONE_DOWN:        return v3(0.f,         -dist,    0.f);
        case CAM_DRONE_OBLIQUE_BL:  return v3(-dist * 0.7f, height, -dist * 0.7f);
        case CAM_DRONE_OBLIQUE_FR:  return v3( dist * 0.7f, height,  dist * 0.7f);
        default:                    return v3(0.f,          height, -dist);
    }
}

static void camera_apply_drone_extension(uint32_t slot, V3* out_eye,
                                           V3* out_look, float dt) {
    Thing* d = entity_get(slot);
    if (!d || d->type != ET_DRONE || !out_eye || !out_look) return;
    CamDronePoseKind target = drone_cam_pick_pose(d);
    if (target != g_drone_cam.current_pose) {
        g_drone_cam.current_pose = target;
        g_drone_cam.pose_blend = 0.f;
    }
    g_drone_cam.pose_blend = clampf(g_drone_cam.pose_blend + dt * 3.f, 0.f, 1.f);
    float cf = cosf(d->rot), sf = sinf(d->rot);
    V3 fwd   = v3(sf, 0.f, -cf);
    V3 right = v3(cf, 0.f, sf);
    V3 up    = v3(0.f, 1.f, 0.f);
    float dist = d->radius * 10.f + 2.5f;
    float height = d->radius * 2.5f + 0.5f;
    V3 off_local = drone_cam_pose_offset_local(target, dist, height);
    V3 off_world = v3add(
        v3add(v3mul(right, off_local.x), v3mul(up, off_local.y)),
        v3mul(fwd, off_local.z));
    V3 target_eye  = v3add(d->pos, v3add(off_world, v3mul(d->vel, -0.10f)));
    V3 target_look = v3add(d->pos, v3mul(d->vel, 0.20f));
    float k = 1.f - expf(-8.f * dt);
    g_drone_cam.offset_smooth = v3add(
        v3mul(g_drone_cam.offset_smooth, 1.f - k),
        v3mul(target_eye, k));
    g_drone_cam.look_smooth = v3add(
        v3mul(g_drone_cam.look_smooth, 1.f - k),
        v3mul(target_look, k));
    *out_eye  = g_drone_cam.offset_smooth;
    *out_look = g_drone_cam.look_smooth;
    g_drone_cam.last_update = (float)time_get();
}

static void drone_cam_cycle_manual(int dir) {
    int cur = (int)g_drone_cam.manual_override;
    cur += dir;
    if (cur < -1) cur = CAM_DRONE_COUNT - 1;
    if (cur >= CAM_DRONE_COUNT) cur = -1;
    g_drone_cam.manual_override = (CamDronePoseKind)cur;
    g_drone_cam.override_until  = (uint32_t)time_get() + 8;
}

static void drone_cam_tick(float dt) {
    (void)dt;
    if (g_drone_cam.manual_override != (CamDronePoseKind)-1) {
        if ((uint32_t)time_get() > g_drone_cam.override_until)
            g_drone_cam.manual_override = (CamDronePoseKind)-1;
    }
}

static int poi_is_recent(uint32_t slot) {
    for (int i = 0; i < 4; i++)
        if (g_drone_cam_poi.recent_pois[i] == slot) return 1;
    return 0;
}

static void poi_mark_recent(uint32_t slot) {
    for (int i = 3; i > 0; i--)
        g_drone_cam_poi.recent_pois[i] = g_drone_cam_poi.recent_pois[i - 1];
    g_drone_cam_poi.recent_pois[0] = slot;
}

static float poi_score(uint32_t slot, V3 drone_pos) {
    Thing* t = entity_get(slot);
    if (!t) return 0.f;
    float dist = v3dist(t->pos, drone_pos);
    float base = 0.f;
    if ((t->flags & ENT_FLAG_HOSTILE) && !(t->flags & ENT_FLAG_PLAYER_OWNED))
        base = 100.f;
    else if (t->type == ET_PICKUP || t->type == ET_WRECK)        base = 50.f;
    else if (t->type == ET_LAUNCHER || t->type == ET_LANZADERA)  base = 30.f;
    else if (t->type == ET_SHIP)                                 base = 40.f;
    else if (t->type == ET_STAR)                                 base = 10.f;
    if (base <= 0.f) return 0.f;
    return base * (1.f / (1.f + dist / 100.f));
}

static uint32_t drone_cam_poi_select(uint32_t drone_slot,
                                       const PerceptionResult* p) {
    (void)drone_slot;
    if (!p) return UINT32_MAX;
    uint32_t best = UINT32_MAX;
    float best_score = 0.f;
    for (int i = 0; i < p->visible_count; i++) {
        uint32_t s = p->visible[i];
        if (poi_is_recent(s)) continue;
        float score = poi_score(s, p->origin);
        if (score > best_score) { best_score = score; best = s; }
    }
    return best;
}

static void drone_cam_poi_tick(uint32_t drone_slot, float dt) {
    Thing* d = entity_get(drone_slot);
    if (!d) return;
    float sp = v3len(d->vel);
    if (sp > 1.5f) {
        g_drone_cam_poi.current_poi = UINT32_MAX;
        g_drone_cam_poi.poi_look_timer = 0.f;
        return;
    }
    float now = (float)time_get();
    if (now < g_drone_cam_poi.next_scan_time &&
        g_drone_cam_poi.current_poi != UINT32_MAX) {
        Thing* poi = entity_get(g_drone_cam_poi.current_poi);
        if (poi) {
            V3 to = v3sub(poi->pos, d->pos);
            float target_rot = atan2f(to.x, -to.z);
            float diff = target_rot - d->rot;
            while (diff >  PI_F) diff -= TAU_F;
            while (diff < -PI_F) diff += TAU_F;
            d->rot += diff * clampf(dt * 2.f, 0.f, 1.f);
            g_drone_cam_poi.poi_look_timer += dt;
            if (g_drone_cam_poi.poi_look_timer > 4.f) {
                poi_mark_recent(g_drone_cam_poi.current_poi);
                g_drone_cam_poi.current_poi = UINT32_MAX;
            }
            return;
        }
        g_drone_cam_poi.current_poi = UINT32_MAX;
    }
    g_drone_cam_poi.next_scan_time = now + 1.0f;
    PerceptionResult pr;
    perceive(drone_slot, &pr);
    uint32_t best = drone_cam_poi_select(drone_slot, &pr);
    if (best != UINT32_MAX) {
        g_drone_cam_poi.current_poi = best;
        g_drone_cam_poi.poi_look_timer = 0.f;
    }
}

static void camera_tick_drone(uint32_t drone_slot, float dt) {
    camera_tick_ship_follow(drone_slot, dt);
    V3 eye = g_game.cam.pos;
    V3 look = g_game.cam.target;
    camera_apply_drone_extension(drone_slot, &eye, &look, dt);
    camera_set(&g_game.cam, eye, look, v3(0, 1, 0),
               g_game.cam.fov, g_game.cam.znear, g_game.cam.zfar);
    drone_cam_poi_tick(drone_slot, dt);
    drone_cam_tick(dt);
}

static void player_repair_tick(float dt) {
    if (!g_player_intent.repair) return;
    if (g_player.mode != PLAYER_MODE_ON_FOOT &&
        g_player.mode != PLAYER_MODE_PLATFORM) return;
    if (g_player.inside_ship == UINT32_MAX) return;
    repair_tick(0, REPAIR_SRC_WALKER_REACH, g_player.inside_ship, 0.f, dt);
}

static void player_mining_tick(float dt) {
    if (g_player.mode == PLAYER_MODE_PILOT) return;
    mining_tick(actor_ship_slot(), &g_player_intent, dt);
}

static void player_fire_tick(float dt) {
    if (g_player.mode == PLAYER_MODE_PILOT && g_player.inside_ship != UINT32_MAX)
        fire_tick(g_player.inside_ship, &g_player_intent, dt);
    (void)dt;
}

static void player_interaction_tick(float dt) {
    (void)dt;
    if (g_player.mode == PLAYER_MODE_PILOT) { if (g_player_intent.interact) player_interact_context(); return; }
    uint32_t src = (g_player.mode == PLAYER_MODE_EVA) ? g_game.player_ship_slot : g_player.inside_ship;
    if (src == UINT32_MAX || !entity_alive(src)) return;
    pickup_try_collect_nearby(src, 2.5f);
    if (g_player_intent.interact) player_interact_context();
}

static void player_tick(float dt) {
    if (dt <= 0.f) return;
    if (player_try_fallback_eva_from_ship_death()) return;
    cap_player_gameplay_tick(dt);
    cap_tick_owner(CAP_OWNER_PLAYER, dt);
}

static void camera_tick_for_mode(float dt) {
    cap_player_camera(dt);
}

static void tick_camera(float dt) {
    camera_tick_for_mode(dt);
    camera_compute_view(&g_game.cam);
}

static void cockpit_display_init(void) {
    memset(&g_cockpit_display, 0, sizeof(g_cockpit_display));
    g_cockpit_display.visible     = 1;
    g_cockpit_display.y_offset    = 0.08f;
    g_cockpit_display.target_y    = 0.08f;
    g_cockpit_display.width_px    = 560.f;
    g_cockpit_display.height_px   = 220.f;
    g_cockpit_display.alpha       = 0.90f;
    g_cockpit_display.scan_phase  = 0.f;
    g_cockpit_display.crosshair_x = 0.f;
    g_cockpit_display.crosshair_y = 0.f;
    g_cockpit_display.page        = CPD_PAGE_MAP;
    g_cockpit_display.pos_preset  = CPD_POS_BOTTOM;
    g_cockpit_display.sole_control = 1;
}

static void block10a_init(void) {
    player_init();
    drone_cam_init();
    cockpit_display_init();
    LOG("block10a_init: player + camera + drone camera ready");
}

static void block10a_shutdown(void) {
    LOG("block10a_shutdown");
}

static float ruido2(int x, int y, uint32_t seed) {
    uint32_t h = (uint32_t)x * 73856093u ^ (uint32_t)y * 19349663u ^ seed;
    h ^= h >> 13; h *= 0x5bd1e995u; h ^= h >> 15;
    return (h & 0xFFFFFFu) / 16777216.0f;
}

static FirmaMaterial firma_crear(uint32_t mat_id, ProcesoMaterial proc,
                                   EstadoFisico est, float dens, float emis,
                                   uint32_t variacion) {
    FirmaMaterial f;
    f.identidad = 0xC0FFEE0000000000ULL | (uint64_t)(mat_id & 0xFFFF);
    f.proceso   = splitmix64(f.identidad ^ ((uint64_t)proc * 0x100000001ULL));
    uint64_t bits = ((uint64_t)est << 32) | (variacion & 0xFFFFFFFFu);
    uint32_t db, eb;
    memcpy(&db, &dens, 4);
    memcpy(&eb, &emis, 4);
    bits ^= ((uint64_t)db) << 16;
    bits ^=  (uint64_t)eb;
    f.estado = splitmix64(f.proceso ^ bits);
    return f;
}

static EstadoFisico material_default_state(uint32_t mat_id) {
    if (mat_id >= g_matpool.count) return EST_SOLIDO;
    const Material* m = &g_matpool.cache[mat_id];
    if (!m->name) return EST_SOLIDO;
    if (strstr(m->name, "Plasma") || strstr(m->name, "Solar") ||
        strstr(m->name, "Antimatt")) return EST_PLASMA;
    if (strstr(m->name, "Ice") || strstr(m->name, "Crystal")) return EST_CRISTAL;
    if (m->tag_mask & MAT_TAG_VOLATILE) return EST_GAS;
    if (m->tag_mask & MAT_TAG_ORGANIC)  return EST_LIQUIDO;
    if (mat_id == 0) return EST_POLVO;
    return EST_SOLIDO;
}

static void generar_patron(uint8_t* salida, const FirmaMaterial* f,
                            V4 color_base, EstadoFisico est,
                            const PropiedadesMaterial* props) {
    uint32_t s1 = (uint32_t)(f->identidad ^ f->proceso);
    uint32_t s2 = (uint32_t)(f->proceso   ^ f->estado);
    uint32_t s3 = (uint32_t)(f->estado);
    int mat_id  = (int)(f->identidad & 0xFFFF);
    int proc_id = (int)(f->proceso & 0xFF);
    int est_id  = (int)(f->estado  & 0xFF);
    ParametrosPatron* pp = NULL;
    if (mat_id >= 0 && mat_id < MATERIAL_COUNT && proc_id >= 0 &&
        proc_id < PROC_TOTAL && est_id >= 0 && est_id < EST_TOTAL) {
        ParametrosPatron* cand = &g_params[mat_id][proc_id][est_id];
        if (cand->frecuencia1 > 0) pp = cand;
    }
    int   f1   = pp ? pp->frecuencia1 : (2 + (int)(s1 % 6u));
    int   f2   = pp ? pp->frecuencia2 : (5 + (int)(s2 % 12u));
    float amp  = pp ? pp->amplitud    : (0.30f + (s3 % 100u) / 200.f);
    int   warp = pp ? pp->distorsion  : (int)((s1 >> 8) % 4u);
    float emi  = pp ? pp->emision     : (props ? props->emision : 0.f);
    for (int y = 0; y < TILE_TAM; y++)
    for (int x = 0; x < TILE_TAM; x++) {
        float nx = (x + 0.5f) / TILE_TAM, ny = (y + 0.5f) / TILE_TAM;
        float n = 0.f;
        n += (ruido2((int)(nx * f1 * 2), (int)(ny * f1 * 2), s1) - 0.5f) * amp;
        n += (ruido2((int)(nx * f2 * 2), (int)(ny * f2 * 2), s2) - 0.5f) * amp * 0.5f;
        n += (ruido2((int)(nx * 6),      (int)(ny * 6),      s3) - 0.5f) * amp * 0.25f;
        switch (warp) {
            case 1: n += sinf(nx * TAU_F + ny * PI_F) * 0.10f; break;
            case 2: n *= 1.f + 0.3f * cosf(nx * 4.f * PI_F); break;
            case 3: n = floorf(n * 6.f + 0.5f) / 6.f; break;
            default: break;
        }
        switch (est) {
            case EST_POLVO:   n *= 1.6f; break;
            case EST_LIQUIDO: n += sinf(ny * TAU_F + nx * 4.f * PI_F) * 0.15f; break;
            case EST_GAS:     n *= 0.4f; break;
            case EST_PLASMA:  n  = sinf(n * 4.f * PI_F) * 0.8f; break;
            case EST_CRISTAL: n  = floorf(n * 4.f + 0.5f) / 4.f; break;
            default: break;
        }
        float cx = nx - 0.5f, cy = ny - 0.5f;
        float rad = sqrtf(cx * cx + cy * cy) * 2.f;
        float lobe1 = ruido2((int)(nx * 6.f),  (int)(ny * 6.f),  s1) * 0.35f;
        float lobe2 = ruido2((int)(nx * 14.f), (int)(ny * 14.f), s2) * 0.15f;
        float lobe3 = ruido2((int)(nx * 28.f), (int)(ny * 28.f), s3) * 0.08f;
        float edge  = 0.62f + lobe1 + lobe2 + lobe3;
        float mask  = 1.f - smoothstepf(edge - 0.10f, edge + 0.02f, rad);
        float shade = 0.55f + 0.45f * mask;
        float r = color_base.x * (1.f + n) * shade;
        float g = color_base.y * (1.f + n) * shade;
        float b = color_base.z * (1.f + n) * shade;
        if (emi > 0.f && n > 0.3f) {
            float e = (n - 0.3f) * emi * 2.f;
            r += e; g += e * 0.7f; b += e * 0.5f;
        }
        float a = mask;
        if (est == EST_GAS)     a *= 0.35f;
        if (est == EST_LIQUIDO) a *= 0.85f;
        r = clampf(r, 0, 1); g = clampf(g, 0, 1);
        b = clampf(b, 0, 1); a = clampf(a, 0, 1);
        int idx = (y * TILE_TAM + x) * 4;
        salida[idx + 0] = (uint8_t)(r * 255);
        salida[idx + 1] = (uint8_t)(g * 255);
        salida[idx + 2] = (uint8_t)(b * 255);
        salida[idx + 3] = (uint8_t)(a * 255);
    }
}

static void atlas_create_texture(void) {
    if (g_atlas) return;
    memset(g_atlas_px, 255, sizeof(g_atlas_px));
    gl_GenTextures(1, &g_atlas);
    gl_BindTexture(GL_TEXTURE_2D, g_atlas);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    gl_TexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, ATLAS_TAM, ATLAS_TAM,
                  0, GL_RGBA, GL_UNSIGNED_BYTE, g_atlas_px);
    LOG("atlas_create_texture: %dx%d", ATLAS_TAM, ATLAS_TAM);
}

static void atlas_upload_full(void) {
    if (!g_atlas) return;
    gl_BindTexture(GL_TEXTURE_2D, g_atlas);
    gl_TexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, ATLAS_TAM, ATLAS_TAM,
                     GL_RGBA, GL_UNSIGNED_BYTE, g_atlas_px);
    LOG("atlas_upload_full");
}

static void atlas_subir_mosaico(int slot, const uint8_t* px) {
    if (!g_atlas || slot < 0 || slot >= ATLAS_SLOTS) return;
    int tx = slot % TILES_POR_FILA;
    int ty = slot / TILES_POR_FILA;
    gl_BindTexture(GL_TEXTURE_2D, g_atlas);
    gl_TexSubImage2D(GL_TEXTURE_2D, 0, tx * TILE_TAM, ty * TILE_TAM,
                     TILE_TAM, TILE_TAM, GL_RGBA, GL_UNSIGNED_BYTE, px);
}

static void atlas_blit_tile_cpu(int slot, const uint8_t* px) {
    if (slot < 0 || slot >= ATLAS_SLOTS) return;
    int tx = slot % TILES_POR_FILA;
    int ty = slot / TILES_POR_FILA;
    for (int y = 0; y < TILE_TAM; y++) {
        memcpy(&g_atlas_px[((ty * TILE_TAM + y) * ATLAS_TAM + tx * TILE_TAM) * 4],
               &px[y * TILE_TAM * 4], TILE_TAM * 4);
    }
}

static int atlas_cache_lookup(const FirmaMaterial* f) {
    for (int i = 0; i < g_cache_n; i++) {
        EntradaCache* e = &g_cache[i];
        if (e->usado && e->a == f->identidad &&
            e->b == f->proceso && e->c == f->estado) {
            e->ultimo_uso = g_frame_atlas;
            return e->slot;
        }
    }
    return -1;
}

static int atlas_cache_insert(const FirmaMaterial* f, const uint8_t* px) {
    int slot = -1;
    if (g_slot_next < ATLAS_SLOTS) {
        slot = g_slot_next++;
    } else {
        int victima = 0;
        uint32_t t_viejo = UINT32_MAX;
        for (int i = 0; i < g_cache_n; i++)
            if (g_cache[i].ultimo_uso < t_viejo) {
                t_viejo = g_cache[i].ultimo_uso;
                victima = i;
            }
        slot = g_cache[victima].slot;
        g_cache[victima].a = f->identidad;
        g_cache[victima].b = f->proceso;
        g_cache[victima].c = f->estado;
        g_cache[victima].ultimo_uso = g_frame_atlas;
        atlas_subir_mosaico(slot, px);
        return slot;
    }
    if (g_cache_n >= ATLAS_SLOTS) return -1;
    EntradaCache* e = &g_cache[g_cache_n++];
    e->a = f->identidad;
    e->b = f->proceso;
    e->c = f->estado;
    e->slot = slot;
    e->usado = 1;
    e->ultimo_uso = g_frame_atlas;
    atlas_subir_mosaico(slot, px);
    return slot;
}

static void atlas_pregenerar_base(void) {
    for (uint32_t m = 0; m < MATERIAL_COUNT; m++) {
        EstadoFisico est = material_default_state(m);
        for (uint32_t p = 0; p < 2; p++) {
            ProcesoMaterial proc = (p == 0) ? PROC_BRUTO : PROC_REFINADO;
            FirmaMaterial f = firma_crear(m, proc, est,
                                           g_matpool.props[m].densidad,
                                           g_matpool.props[m].emision, 0);
            generar_patron(g_tile_buf, &f, g_matpool.cache[m].color, est,
                            &g_matpool.props[m]);
            if (g_slot_next >= ATLAS_SLOTS) return;
            int slot = g_slot_next++;
            atlas_blit_tile_cpu(slot, g_tile_buf);
            if (g_cache_n >= ATLAS_SLOTS) return;
            EntradaCache* e = &g_cache[g_cache_n++];
            e->a = f.identidad;
            e->b = f.proceso;
            e->c = f.estado;
            e->slot = slot;
            e->usado = 1;
            e->ultimo_uso = 0;
        }
    }
}

/* Unico cuerpo de rect UV por slot (todos los publicadores reutilizan) */
static void atlas_tile_uv_rect(int slot, float* u0, float* v0,
                                float* u1, float* v1) {
    if (!u0 || !v0 || !u1 || !v1) return;
    float inset = 0.5f / ATLAS_TAM;
    int tx = slot % TILES_POR_FILA, ty = slot / TILES_POR_FILA;
    *u0 = (float)(tx * TILE_TAM) / ATLAS_TAM + inset;
    *v0 = (float)(ty * TILE_TAM) / ATLAS_TAM + inset;
    *u1 = (float)((tx + 1) * TILE_TAM) / ATLAS_TAM - inset;
    *v1 = (float)((ty + 1) * TILE_TAM) / ATLAS_TAM - inset;
}

/* Slot 0 reservado: disco blanco con alfa suave. El tint viene de
   rcmd_color, asi cualquier cuerpo circular sin material pinta un disco
   del color de su tipo y nunca el atlas entero (cuadrados flotantes). */
static void atlas_disc_uv(float* u0, float* v0, float* u1, float* v1) {
    atlas_tile_uv_rect(0, u0, v0, u1, v1);
}

static void atlas_disc_pregenerar(void) {
    uint8_t* px = g_tile_buf;
    float r_out = 0.485f;
    for (int y = 0; y < TILE_TAM; y++)
    for (int x = 0; x < TILE_TAM; x++) {
        float nx = ((float)x + 0.5f) / TILE_TAM - 0.5f;
        float ny = ((float)y + 0.5f) / TILE_TAM - 0.5f;
        float r = sqrtf(nx * nx + ny * ny);
        float edge = clampf((r_out - r) / 0.06f, 0.f, 1.f);
        uint8_t a = (uint8_t)(edge * 255.f);
        int idx = (y * TILE_TAM + x) * 4;
        px[idx + 0] = 255;
        px[idx + 1] = 255;
        px[idx + 2] = 255;
        px[idx + 3] = a;
    }
    atlas_blit_tile_cpu(0, px);
}

static void material_tile_uv(uint32_t mat_id, ProcesoMaterial proc,
                              EstadoFisico est,
                              const PropiedadesMaterial* props,
                              uint32_t variacion,
                              float* u0, float* v0, float* u1, float* v1) {
    if (!u0 || !v0 || !u1 || !v1) return;
    FirmaMaterial f = firma_crear(mat_id, proc, est,
                                    props ? props->densidad : 1.f,
                                    props ? props->emision  : 0.f,
                                    variacion);
    int slot = atlas_cache_lookup(&f);
    if (slot < 0) {
        V4 base = (mat_id < g_matpool.count)
                  ? g_matpool.cache[mat_id].color
                  : v4(0.5f, 0.5f, 0.5f, 1.f);
        generar_patron(g_tile_buf, &f, base, est, props);
        slot = atlas_cache_insert(&f, g_tile_buf);
    }
    if (slot < 0) {
        *u0 = UV_BLANCO_U; *v0 = UV_BLANCO_V;
        *u1 = UV_BLANCO_U; *v1 = UV_BLANCO_V;
        return;
    }
    atlas_tile_uv_rect(slot, u0, v0, u1, v1);
}

static void atlas_init(void) {
    if (g_atlas) return;
    materials_init();
    atlas_create_texture();
    g_cache_n = 0;
    g_slot_next = 1;
    g_frame_atlas = 0;
    atlas_disc_pregenerar();
    atlas_pregenerar_base();
    atlas_upload_full();
    LOG("atlas_init: %d tiles pre-generated, next_slot=%d",
        g_cache_n, g_slot_next);
}

static void atlas_shutdown(void) {
    if (g_atlas && gl_DeleteTextures) gl_DeleteTextures(1, &g_atlas);
    g_atlas = 0;
    g_cache_n = 0;
    g_slot_next = 1;
    LOG("atlas_shutdown");
}

static int patrones_save(const char* path) {
    FILE* f = fopen(path, "wb");
    if (!f) return 0;
    uint32_t magic = 0x50415452u, ver = 1;
    fwrite(&magic, 4, 1, f);
    fwrite(&ver, 4, 1, f);
    fwrite(g_params, sizeof(ParametrosPatron),
           (size_t)MATERIAL_COUNT * PROC_TOTAL * EST_TOTAL, f);
    fclose(f);
    return 1;
}

static int patrones_load(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) return 0;
    uint32_t magic = 0, ver = 0;
    if (fread(&magic, 4, 1, f) != 1 || magic != 0x50415452u) {
        fclose(f); return 0;
    }
    if (fread(&ver, 4, 1, f) != 1 || ver != 1) {
        fclose(f); return 0;
    }
    size_t n = fread(g_params, sizeof(ParametrosPatron),
                     (size_t)MATERIAL_COUNT * PROC_TOTAL * EST_TOTAL, f);
    fclose(f);
    return n == (size_t)(MATERIAL_COUNT * PROC_TOTAL * EST_TOTAL);
}

static void matlearn_init(void) {
    if (g_matlearn) return;
    g_matlearn_cap = 16;
    g_matlearn = (MaterialLearnEntry*)xcalloc(g_matlearn_cap,
                                              sizeof(MaterialLearnEntry));
    g_matlearn_n = 0;
}

static MaterialLearnEntry* matlearn_find(uint32_t a, uint32_t b,
                                          uint32_t proc) {
    if (a > b) { uint32_t t = a; a = b; b = t; }
    for (uint32_t i = 0; i < g_matlearn_n; i++) {
        MaterialLearnEntry* e = &g_matlearn[i];
        if (e->mat_a == a && e->mat_b == b && e->process_id == proc) return e;
    }
    return NULL;
}

static MaterialLearnEntry* matlearn_get_or_create(uint32_t a, uint32_t b,
                                                    uint32_t proc) {
    if (a > b) { uint32_t t = a; a = b; b = t; }
    MaterialLearnEntry* e = matlearn_find(a, b, proc);
    if (e) return e;
    if (g_matlearn_n >= g_matlearn_cap) {
        uint32_t nc = g_matlearn_cap * 2 + 2;
        if (nc > MAT_LEARN_SOFT_CAP) nc = MAT_LEARN_SOFT_CAP;
        if (nc <= g_matlearn_cap) return NULL;
        MaterialLearnEntry* np = (MaterialLearnEntry*)xrealloc(
            g_matlearn, nc * sizeof(MaterialLearnEntry));
        if (!np) return NULL;
        memset(&np[g_matlearn_cap], 0,
               (nc - g_matlearn_cap) * sizeof(MaterialLearnEntry));
        g_matlearn = np;
        g_matlearn_cap = nc;
    }
    e = &g_matlearn[g_matlearn_n++];
    memset(e, 0, sizeof(*e));
    e->mat_a = a;
    e->mat_b = b;
    e->process_id = proc;
    return e;
}

static float matlearn_bonus(uint32_t a, uint32_t b, uint32_t proc) {
    MaterialLearnEntry* e = matlearn_find(a, b, proc);
    if (!e) return 0.f;
    float total = (float)(e->successes + e->failures) + 1.f;
    return clampf(0.4f * (float)e->successes / total, 0.f, 0.4f);
}

static void matlearn_on_success(uint32_t a, uint32_t b, uint32_t proc) {
    MaterialLearnEntry* e = matlearn_get_or_create(a, b, proc);
    if (!e) return;
    e->successes++;
    e->last_used = (float)time_get();
}

static void matlearn_on_failure(uint32_t a, uint32_t b, uint32_t proc) {
    MaterialLearnEntry* e = matlearn_get_or_create(a, b, proc);
    if (!e) return;
    e->failures++;
    e->last_used = (float)time_get();
}

static void recipe_pool_init(void) {
    g_recipes_cap = 16;
    g_recipes = (Recipe*)xcalloc(g_recipes_cap, sizeof(Recipe));
    g_recipes_n = 0;
}

static void recipe_pool_add(const Recipe* r) {
    if (!r) return;
    if (g_recipes_n >= g_recipes_cap) {
        uint32_t nc = g_recipes_cap * 2 + 2;
        Recipe* nr = (Recipe*)xrealloc(g_recipes, nc * sizeof(Recipe));
        if (!nr) return;
        g_recipes = nr;
        g_recipes_cap = nc;
    }
    g_recipes[g_recipes_n++] = *r;
}

static Recipe* recipe_find(uint32_t mat_a, uint32_t mat_b,
                             uint32_t process_id) {
    for (uint32_t i = 0; i < g_recipes_n; i++) {
        Recipe* r = &g_recipes[i];
        if (r->process_id != process_id) continue;
        uint32_t a = r->input_mat[0], b = r->input_mat[1];
        if ((a == mat_a && b == mat_b) || (a == mat_b && b == mat_a)) return r;
    }
    return NULL;
}

static void refine_pool_init(void) {
    g_refines_cap = 8;
    g_refines = (RefineProcess*)xcalloc(g_refines_cap, sizeof(RefineProcess));
    g_refines_n = 0;
}

static void refine_pool_add(const RefineProcess* r) {
    if (!r) return;
    if (g_refines_n >= g_refines_cap) {
        uint32_t nc = g_refines_cap * 2 + 2;
        RefineProcess* nr = (RefineProcess*)xrealloc(g_refines, nc * sizeof(RefineProcess));
        if (!nr) return;
        g_refines = nr;
        g_refines_cap = nc;
    }
    g_refines[g_refines_n++] = *r;
}

static RefineProcess* refine_find(uint32_t in_mat) {
    for (uint32_t i = 0; i < g_refines_n; i++)
        if (g_refines[i].input_mat == in_mat) return &g_refines[i];
    return NULL;
}

static void recipes_seed_procedural(void) {
    recipe_pool_init();
    refine_pool_init();
    for (int i = 0; i < 24; i++) {
        Recipe r;
        memset(&r, 0, sizeof(r));
        r.runtime_seed = xrng_u32();
        uint32_t in_count = 1 + xrng_u32() % 4;
        for (uint32_t k = 0; k < in_count && k < 4; k++) {
            r.input_mat[k] = xrng_u32() % MATERIAL_COUNT;
            r.input_qty[k] = 1 + xrng_u32() % 3;
        }
        r.output_mat     = xrng_u32() % MATERIAL_COUNT;
        r.output_qty     = 1 + xrng_u32() % 5;
        r.process_id     = xrng_u32() % PROC_TOTAL;
        r.time_sec       = 1.f + xrng_f() * 5.f;
        r.success_chance = 0.5f + xrng_f() * 0.4f;
        recipe_pool_add(&r);
    }
    for (int i = 0; i < 12; i++) {
        RefineProcess r;
        r.input_mat     = xrng_u32() % MATERIAL_COUNT;
        r.output_mat    = xrng_u32() % MATERIAL_COUNT;
        r.ratio         = 2.f + xrng_f() * 3.f;
        r.efficiency    = 0.3f + xrng_f() * 0.5f;
        r.heat_required = 20.f + xrng_f() * 80.f;
        refine_pool_add(&r);
    }
    LOG("recipes_seed_procedural: %u recipes, %u refines",
        g_recipes_n, g_refines_n);
}

static void mixing_rules_init(void) {
    for (int i = 0; i < MIX_MODE_COUNT; i++) {
        g_mixing_rules[i].mode = (MixingMode)i;
        g_mixing_rules[i].allowed_input_kinds = 0xFFFFFFFFu;
        g_mixing_rules[i].compute_cost = 4;
        g_mixing_rules[i].tier_max = 5;
        g_mixing_rules[i].success_base = 0.6f;
        g_mixing_rules[i].loss_prob = 0.2f;
        g_mixing_rules[i].catastrophic = 0.03f;
    }
    g_mixing_rules[MIX_MODE_STRUCTURAL].compute_cost = 2;
    g_mixing_rules[MIX_MODE_STRUCTURAL].success_base = 0.70f;
    g_mixing_rules[MIX_MODE_STRUCTURAL].loss_prob    = 0.15f;
    g_mixing_rules[MIX_MODE_STRUCTURAL].catastrophic = 0.02f;

    g_mixing_rules[MIX_MODE_COMPUTATIONAL].compute_cost = 8;
    g_mixing_rules[MIX_MODE_COMPUTATIONAL].success_base = 0.55f;
    g_mixing_rules[MIX_MODE_COMPUTATIONAL].loss_prob    = 0.20f;
    g_mixing_rules[MIX_MODE_COMPUTATIONAL].catastrophic = 0.05f;

    g_mixing_rules[MIX_MODE_ORGANIC].compute_cost = 3;
    g_mixing_rules[MIX_MODE_ORGANIC].success_base = 0.50f;
    g_mixing_rules[MIX_MODE_ORGANIC].loss_prob    = 0.30f;
    g_mixing_rules[MIX_MODE_ORGANIC].catastrophic = 0.02f;

    g_mixing_rules[MIX_MODE_ENERGETIC].compute_cost = 10;
    g_mixing_rules[MIX_MODE_ENERGETIC].success_base = 0.45f;
    g_mixing_rules[MIX_MODE_ENERGETIC].loss_prob    = 0.20f;
    g_mixing_rules[MIX_MODE_ENERGETIC].catastrophic = 0.10f;

    g_mixing_rules[MIX_MODE_MEDICAL].compute_cost = 4;
    g_mixing_rules[MIX_MODE_MEDICAL].success_base = 0.65f;
    g_mixing_rules[MIX_MODE_MEDICAL].loss_prob    = 0.25f;
    g_mixing_rules[MIX_MODE_MEDICAL].catastrophic = 0.05f;

    g_mixing_rules[MIX_MODE_TOOL].compute_cost = 3;
    g_mixing_rules[MIX_MODE_TOOL].success_base = 0.68f;
    g_mixing_rules[MIX_MODE_TOOL].loss_prob    = 0.18f;
    g_mixing_rules[MIX_MODE_TOOL].catastrophic = 0.03f;

    g_mixing_rules[MIX_MODE_DRONE].compute_cost = 12;
    g_mixing_rules[MIX_MODE_DRONE].success_base = 0.40f;
    g_mixing_rules[MIX_MODE_DRONE].loss_prob    = 0.20f;
    g_mixing_rules[MIX_MODE_DRONE].catastrophic = 0.08f;

    LOG("mixing_rules_init: %d modes", MIX_MODE_COUNT);
}

static const MixingRule* mixing_rule_for(MixingMode mode) {
    if ((int)mode < 0 || mode >= MIX_MODE_COUNT) return NULL;
    return &g_mixing_rules[mode];
}

static int mixing_can_combine(ThingKind a, ThingKind b, MixingMode mode) {
    if (a == THING_KIND_ANY || b == THING_KIND_ANY) return 1;
    switch (mode) {
        case MIX_MODE_STRUCTURAL:
            return (a == THING_KIND_SHIP_PIECE || a == THING_KIND_ARMOR ||
                    a == THING_KIND_TOOL) &&
                   (b == THING_KIND_SHIP_PIECE || b == THING_KIND_ARMOR ||
                    b == THING_KIND_TOOL);
        case MIX_MODE_COMPUTATIONAL:
            return (a == THING_KIND_COMPUTER || a == THING_KIND_TOOL) &&
                   (b == THING_KIND_COMPUTER || b == THING_KIND_TOOL);
        case MIX_MODE_ORGANIC:
            return (a == THING_KIND_FOOD || a == THING_KIND_CREATURE ||
                    a == THING_KIND_MEDICINE) &&
                   (b == THING_KIND_FOOD || b == THING_KIND_CREATURE ||
                    b == THING_KIND_MEDICINE);
        case MIX_MODE_ENERGETIC:
            return (a == THING_KIND_WEAPON) || (b == THING_KIND_WEAPON);
        case MIX_MODE_MEDICAL:
            return (a == THING_KIND_MEDICINE || a == THING_KIND_FOOD) &&
                   (b == THING_KIND_MEDICINE || b == THING_KIND_FOOD);
        case MIX_MODE_TOOL:
            return (a == THING_KIND_TOOL || a == THING_KIND_SHIP_PIECE) &&
                   (b == THING_KIND_TOOL || b == THING_KIND_SHIP_PIECE);
        case MIX_MODE_DRONE:
            return (a == THING_KIND_DRONE_KIT || a == THING_KIND_COMPUTER) &&
                   (b == THING_KIND_DRONE_KIT || b == THING_KIND_COMPUTER);
        default: return 1;
    }
}

static int mixing_execute(uint32_t ship_slot, int node_idx,
                            const uint32_t* input_seeds, int input_count,
                            MixingMode mode, MixingResult* out) {
    if (!out || !input_seeds) return 0;
    memset(out, 0, sizeof(*out));
    out->damaged_ship_slot = UINT32_MAX;
    if (input_count < 2 || input_count > 4) {
        snprintf(out->message, sizeof(out->message), "NEED 2-4 INPUTS");
        return 0;
    }
    const MixingRule* rule = mixing_rule_for(mode);
    if (!rule) {
        snprintf(out->message, sizeof(out->message), "INVALID MODE");
        return 0;
    }
    ThingBlueprint bps[4];
    memset(bps, 0, sizeof(bps));
    for (int i = 0; i < input_count; i++) {
        ThingBlueprint* bp = bp_cache_get(input_seeds[i]);
        if (!bp) {
            snprintf(out->message, sizeof(out->message), "UNKNOWN INPUT %d", i);
            return 0;
        }
        bps[i] = *bp;
    }
    for (int i = 0; i < input_count; i++)
        for (int j = i + 1; j < input_count; j++)
            if (!mixing_can_combine(bps[i].kind, bps[j].kind, mode)) {
                snprintf(out->message, sizeof(out->message), "INCOMPATIBLE");
                return 0;
            }
    bp_compose(bps, input_count, rule->tier_max, &out->result);
    float bonus = 0.f;
    for (int i = 0; i < input_count; i++)
        for (int j = i + 1; j < input_count; j++) {
            uint32_t a = input_seeds[i] & 0xFF;
            uint32_t b = input_seeds[j] & 0xFF;
            bonus += matlearn_bonus(a, b, (uint32_t)mode);
        }
    bonus += (float)g_player.mixing_level *
             (g_balance.mixing_success_bonus_per_level > 0.f
              ? g_balance.mixing_success_bonus_per_level : 0.02f);
    float success = rule->success_base + bonus;
    if (success > 0.95f) success = 0.95f;
    if (success < 0.05f) success = 0.05f;
    float roll = xrng_f();
    if (roll < success) {
        out->ok = 1;
        out->consumed_count = input_count;
        snprintf(out->message, sizeof(out->message), "MIXING OK");
        matlearn_on_success(input_seeds[0] & 0xFF,
                             input_seeds[1] & 0xFF, (uint32_t)mode);
        audio_sfx_mixing_success();
    } else {
        out->consumed_count = input_count;
        if (xrng_f() < rule->catastrophic) {
            out->ok = 0;
            out->damaged_ship_slot = ship_slot;
            out->damage_amount = 30.f + xrng_f() * 30.f;
            snprintf(out->message, sizeof(out->message), "CATASTROPHIC MIX");
            audio_sfx_mixing_catastro();
            bp_free(&out->result);
            memset(&out->result, 0, sizeof(out->result));
        } else {
            out->ok = 0;
            int lost = (int)(rule->loss_prob * (float)input_count);
            if (lost < 1) lost = 1;
            if (lost > 16) lost = 16;
            out->lost_count = lost;
            for (int i = 0; i < lost; i++)
                out->lost_material_ids[i] = (uint16_t)(input_seeds[i] & 0xFFFF);
            snprintf(out->message, sizeof(out->message), "MIXING FAILED");
            audio_sfx_mixing_fail();
            bp_free(&out->result);
            memset(&out->result, 0, sizeof(out->result));
        }
        matlearn_on_failure(input_seeds[0] & 0xFF,
                              input_seeds[1] & 0xFF, (uint32_t)mode);
    }
    (void)node_idx;
    return out->ok;
}

static void mixing_result_apply(const MixingResult* res, uint32_t ship_slot) {
    if (!res) return;
    if (res->ok && res->result.kind != THING_KIND_ANY) {
        inv_add(&g_player.inventory, &res->result, 1);
        g_player.mixing_xp += 10;
        while (g_player.mixing_xp >= (g_player.mixing_level + 1) * 100) {
            g_player.mixing_xp -= (g_player.mixing_level + 1) * 100;
            g_player.mixing_level++;
            notice_push("MIXING LEVEL UP");
        }
        notice_push("MIXING SUCCESS");
        audio_sfx_craft();
        g_hints.mixed_once = 1;
    }
    if (res->damaged_ship_slot != UINT32_MAX && res->damage_amount > 0.f) {
        ShipDataExt* ext = ship_ext(res->damaged_ship_slot);
        if (ext && ext->node_count > 0) {
            int node = (int)(xrng_u32() % (uint32_t)ext->node_count);
            ShipNode* n = &ext->nodes[node];
            if (n->current_hp > 0.f) {
                n->current_hp -= res->damage_amount;
                if (n->current_hp < 0.f) n->current_hp = 0.f;
                if (n->current_hp <= 0.f)
                    node_breach(res->damaged_ship_slot, node);
            }
        }
        notice_push("SHIP DAMAGED");
        g_game.shake = fminf(g_game.shake + 2.f, 8.f);
    }
    if (res->lost_count > 0) notice_push("MATERIALS LOST");
    bp_free((ThingBlueprint*)&res->result);
    (void)ship_slot;
}

static void mixing_set_slot(int slot, int32_t arg) {
    if (slot < 0 || slot >= 4) return;
    if (arg < 0 || arg >= g_player.inventory.count) return;
    g_mixing_ui.input_seeds[slot] = g_player.inventory.items[arg].bp.seed;
    if (slot >= g_mixing_ui.input_count)
        g_mixing_ui.input_count = slot + 1;
    g_mixing_ui.active = 1;
}

static void mixing_promote(void) {
    if (!g_mixing_ui.active) return;
    if (g_mixing_ui.input_count < 2) {
        notice_push("NEED 2+ INPUTS");
        return;
    }
    MixingResult res;
    mixing_execute(g_mixing_ui.ship_slot, g_mixing_ui.node_idx,
                    g_mixing_ui.input_seeds, g_mixing_ui.input_count,
                    (MixingMode)g_mixing_ui.mode, &res);
    mixing_result_apply(&res, g_mixing_ui.ship_slot);
    snprintf(g_mixing_ui.preview, sizeof(g_mixing_ui.preview), "%s",
             res.message);
    g_mixing_ui.input_count = 0;
}

static void mixing_hierarchy(void) {
    notice_push("HIERARCHY VIEW");
}

static void mixing_inspect(void) {
    if (g_mixing_ui.input_count == 0) return;
    uint32_t seed = g_mixing_ui.input_seeds[0];
    ThingBlueprint* bp = bp_cache_get(seed);
    if (!bp) return;
    snprintf(g_mixing_ui.preview, sizeof(g_mixing_ui.preview),
             "K=%d T=%u M=%.1f HP=%.1f Mat=%d",
             (int)bp->kind, bp->tier, bp->mass, bp->hp,
             (int)bp->material_id);
}

static void mixing_set_mode(MixingMode mode) {
    if ((int)mode < 0 || mode >= MIX_MODE_COUNT) return;
    g_mixing_ui.mode = (int)mode;
    notice_push("MIXING MODE CHANGED");
}

static void mixing_ui_tick(float dt) {
    if (!g_mixing_ui.active) return;
    if (g_mixing_ui.fade_alpha < 1.f) {
        g_mixing_ui.fade_alpha += dt * 3.f;
        if (g_mixing_ui.fade_alpha > 1.f) g_mixing_ui.fade_alpha = 1.f;
    }
}

static void mixing_ui_open(uint32_t ship_slot, int node_idx) {
    memset(&g_mixing_ui, 0, sizeof(g_mixing_ui));
    g_mixing_ui.active = 1;
    g_mixing_ui.ship_slot = ship_slot;
    g_mixing_ui.node_idx = node_idx;
    g_mixing_ui.mode = MIX_MODE_STRUCTURAL;
    snprintf(g_mixing_ui.preview, sizeof(g_mixing_ui.preview),
             "SELECT 2-4 INPUTS");
    input_set_context(CTX_MIX);
}

static void mixing_ui_close(void) {
    g_mixing_ui.active = 0;
    input_set_context(CTX_GAME);
}

