typedef void (*TutorialStepFn)(float dt);

static void xp_init(void) {
    g_xp_b7.level          = 1;
    g_xp_b7.xp             = 0;
    g_xp_b7.xp_to_next     = 50;
    g_xp_b7.perk_pts       = 0;
    g_xp_b7.perk_toughness = 0;
    g_xp_b7.perk_precision = 0;
    g_xp_b7.perk_greed     = 0;
    g_xp_b7.perk_speed     = 0;
    g_xp_b7.perk_evasive   = 0;
}

static void xp_gain_b7(int amount) {
    if (amount <= 0) return;
    g_xp_b7.xp += amount;
    while (g_xp_b7.xp >= g_xp_b7.xp_to_next) {
        g_xp_b7.xp -= g_xp_b7.xp_to_next;
        g_xp_b7.level++;
        g_xp_b7.perk_pts++;
        g_xp_b7.xp_to_next = 50 + g_xp_b7.level * 25;
        notice_push("LEVEL UP");
        audio_sfx_upgrade();
    }
}

static int xp_greed_dice(void) {
    float p = 0.10f + g_xp_b7.perk_greed * 0.05f;
    return (xrng_f() < p) ? 1 : 0;
}

static int perk_select(int which) {
    if (g_xp_b7.perk_pts <= 0) return 0;
    switch (which) {
        case 0: g_xp_b7.perk_toughness++; break;
        case 1: g_xp_b7.perk_precision++; break;
        case 2: g_xp_b7.perk_greed++;     break;
        case 3: g_xp_b7.perk_speed++;     break;
        case 4: g_xp_b7.perk_evasive++;   break;
        default: return 0;
    }
    g_xp_b7.perk_pts--;
    notice_push("PERK UNLOCKED");
    audio_sfx_upgrade();
    return 1;
}

static void achievements_init(void) {
    for (int i = 0; i < MAX_ACHIEVEMENTS; i++) {
        Achievement* a = &g_achievements[i];
        memset(a, 0, sizeof(*a));
        a->name = g_achievement_defs[i].name;
        a->desc = g_achievement_defs[i].desc;
        a->goal = g_achievement_defs[i].goal;
        a->unlocked = 0;
        a->progress = 0;
    }
    memset(&g_achievement_toast, 0, sizeof(g_achievement_toast));
    memset(&g_reputation_toast,  0, sizeof(g_reputation_toast));
}

static int achievement_find(const char* name) {
    if (!name) return -1;
    for (int i = 0; i < MAX_ACHIEVEMENTS; i++) {
        if (!g_achievements[i].name) continue;
        if (strcmp(g_achievements[i].name, name) == 0) return i;
    }
    return -1;
}

static void achievement_unlock(int idx) {
    if (idx < 0 || idx >= MAX_ACHIEVEMENTS) return;
    Achievement* a = &g_achievements[idx];
    if (a->unlocked) return;
    a->unlocked = 1;
    a->progress = a->goal;
    g_achievement_toast.active = 1;
    g_achievement_toast.index  = idx;
    g_achievement_toast.timer  = 3.f;
    notice_push("ACHIEVEMENT UNLOCKED");
    audio_sfx_upgrade();
    xp_gain_b7(30);
}

static void achievement_progress_add(const char* name, int delta) {
    int idx = achievement_find(name);
    if (idx < 0) return;
    Achievement* a = &g_achievements[idx];
    if (a->unlocked) return;
    a->progress += delta;
    if (a->progress >= a->goal) achievement_unlock(idx);
}

static void achievement_notify(const char* name) {
    int idx = achievement_find(name);
    if (idx < 0) return;
    achievement_unlock(idx);
}

static void achievement_tick(float dt) {
    if (g_achievement_toast.active) {
        g_achievement_toast.timer -= dt;
        if (g_achievement_toast.timer <= 0.f) g_achievement_toast.active = 0;
    }
    if (g_game.time_alive   > 300.f) achievement_notify("SURVIVOR_5M");
    if (g_game.zones_visited >= 5)   achievement_notify("EXPLORER_5");
    if (g_game.kills_aliens >= 1)    achievement_notify("FIRST_BLOOD");
    if (g_game.kills_asteroids >= 10) achievement_notify("ASTEROID_10");
}

static void reputation_toast_init(int32_t delta, uint32_t faction) {
    g_reputation_toast.active  = 1;
    g_reputation_toast.timer   = 3.f;
    g_reputation_toast.delta   = delta;
    g_reputation_toast.faction = faction;
}

static void reputation_toast_tick(float dt) {
    if (!g_reputation_toast.active) return;
    g_reputation_toast.timer -= dt;
    if (g_reputation_toast.timer <= 0.f) g_reputation_toast.active = 0;
}

static void hint_show(const char* text) {
    g_active_hint.text      = text;
    g_active_hint.remaining = HINT_DURATION;
    g_active_hint.shown     = 0;
}

static void hint_clear(void) {
    g_active_hint.text      = NULL;
    g_active_hint.remaining = 0.f;
    g_active_hint.shown     = 0;
}

static void hint_tick(float dt) {
    if (!g_active_hint.text) return;
    g_active_hint.remaining -= dt;
    if (g_active_hint.remaining <= 0.f) hint_clear();
}

static void hint_suggest(void) {
    if (g_active_hint.text) return;
    if (!g_hints.entered_cockpit)         hint_show("Press INTERACT near the cockpit");
    else if (!g_hints.walked_on_foot)     hint_show("Press EXIT SHIP to walk");
    else if (!g_hints.repaired_node)      hint_show("Walk near a damaged node, press REPAIR");
    else if (!g_hints.collected_first_mat) hint_show("Mine asteroids with secondary fire");
    else if (!g_hints.mixed_once)         hint_show("Open mixing UI to combine items");
    else if (!g_hints.deployed_drone)     hint_show("Deploy a drone with DEPLOY DRONE");
}

static void tut_step_intro(float dt) {
    g_tutorial.step_timer += dt;
    if (g_tutorial.step_timer > 4.f) {
        g_tutorial.step = TUT_WALK;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_walk(float dt) {
    g_tutorial.step_timer += dt;
    if (g_player.mode == PLAYER_MODE_ON_FOOT ||
        g_player.mode == PLAYER_MODE_PLATFORM) {
        if (v3len(g_player.walker.vel_local) > 0.5f) g_tutorial.walk_accum++;
        if (g_tutorial.walk_accum >= TUT_WALK_TARGET_M * 60) {
            g_tutorial.step = TUT_ENTER_COCKPIT;
            g_tutorial.step_timer = 0.f;
            g_hints.walked_on_foot = 1;
        }
    }
    if (g_tutorial.step_timer > TUT_STEP_TIMEOUT) {
        g_tutorial.step = TUT_ENTER_COCKPIT;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_enter_cockpit(float dt) {
    g_tutorial.step_timer += dt;
    if (g_player.mode == PLAYER_MODE_PILOT) {
        g_tutorial.step = TUT_PILOT;
        g_tutorial.step_timer = 0.f;
    }
    if (g_tutorial.step_timer > TUT_STEP_TIMEOUT) {
        g_tutorial.step = TUT_PILOT;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_pilot(float dt) {
    g_tutorial.step_timer += dt;
    if (g_tutorial.step_timer > 5.f) {
        g_tutorial.step = TUT_REPAIR;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_repair(float dt) {
    g_tutorial.step_timer += dt;
    if (g_hints.repaired_node) {
        g_tutorial.step = TUT_MIXING;
        g_tutorial.step_timer = 0.f;
    }
    if (g_tutorial.step_timer > TUT_STEP_TIMEOUT) {
        g_tutorial.step = TUT_MIXING;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_mixing(float dt) {
    g_tutorial.step_timer += dt;
    if (g_hints.mixed_once) {
        g_tutorial.step = TUT_DRONE;
        g_tutorial.step_timer = 0.f;
    }
    if (g_tutorial.step_timer > TUT_STEP_TIMEOUT) {
        g_tutorial.step = TUT_DRONE;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_drone(float dt) {
    g_tutorial.step_timer += dt;
    if (g_hints.deployed_drone) {
        g_tutorial.step = TUT_COMPLETE;
        g_tutorial.step_timer = 0.f;
    }
    if (g_tutorial.step_timer > TUT_STEP_TIMEOUT) {
        g_tutorial.step = TUT_COMPLETE;
        g_tutorial.step_timer = 0.f;
    }
}

static void tut_step_complete(float dt) {
    (void)dt;
    g_tutorial.step = TUT_NONE;
    g_tutorial.enabled = 0;
    notice_push("TUTORIAL COMPLETE");
}

static const TutorialStepFn g_tutorial_step_fns[TUT_COUNT] = {
    NULL,
    tut_step_intro,
    tut_step_walk,
    tut_step_enter_cockpit,
    tut_step_pilot,
    tut_step_repair,
    tut_step_mixing,
    tut_step_drone,
    tut_step_complete
};

static void tutorial_init(void) {
    g_tutorial.step       = TUT_INTRO;
    g_tutorial.step_timer = 0.f;
    g_tutorial.walk_accum = 0;
    g_tutorial.enabled    = g_balance.tutorial_enabled;
}

static void tutorial_tick(float dt) {
    if (!g_tutorial.enabled) return;
    if ((int)g_tutorial.step < 0 || g_tutorial.step >= TUT_COUNT) return;
    TutorialStepFn fn = g_tutorial_step_fns[g_tutorial.step];
    if (fn) fn(dt);
}

static void scan_targets_init(void) {
    g_scan_targets_cap = SCAN_TARGETS_SOFT_CAP;
    g_scan_targets = (ScanTarget*)xcalloc(g_scan_targets_cap, sizeof(ScanTarget));
    g_scan_targets_n = 0;
    g_b7_scan_active = 0;
}

static void scan_target_clear(void) {
    g_scan_targets_n = 0;
}

static int scan_target_add(uint32_t slot) {
    if (g_scan_targets_n >= g_scan_targets_cap) return 0;
    for (uint32_t i = 0; i < g_scan_targets_n; i++)
        if (g_scan_targets[i].slot == slot) return 0;
    ScanTarget* st = &g_scan_targets[g_scan_targets_n++];
    st->slot      = slot;
    st->scan_time = 0.f;
    st->locked    = 0;
    return 1;
}

static void scan_target_tick(float dt) {
    if (!g_b7_scan_active) return;
    for (uint32_t i = 0; i < g_scan_targets_n; ) {
        ScanTarget* st = &g_scan_targets[i];
        if (!entity_alive(st->slot)) {
            g_scan_targets[i] = g_scan_targets[g_scan_targets_n - 1];
            g_scan_targets_n--;
            continue;
        }
        st->scan_time += dt;
        if (st->scan_time >= SCAN_TIME) st->locked = 1;
        i++;
    }
}

static void scan_toggle_b7(void) {
    g_b7_scan_active = !g_b7_scan_active;
    if (g_b7_scan_active) {
        scan_target_clear();
        uint32_t ship_slot = actor_ship_slot();
        if (ship_slot == UINT32_MAX) return;
        Thing* ship = entity_get(ship_slot);
        if (!ship) return;
        PerceptionResult pr;
        perceive(ship_slot, &pr);
        for (int i = 0;
             i < pr.visible_count && g_scan_targets_n < g_scan_targets_cap;
             i++)
            scan_target_add(pr.visible[i]);
        notice_push("SCAN ON");
    } else {
        scan_target_clear();
        notice_push("SCAN OFF");
    }
}

static void scan_publish(void) {
    if (!g_b7_scan_active) return;
    for (uint32_t i = 0; i < g_scan_targets_n; i++) {
        ScanTarget* st = &g_scan_targets[i];
        Thing* t = entity_get(st->slot);
        if (!t) continue;
        V4 color = st->locked ? v4(0.2f, 1.f, 0.2f, 1.f)
                              : v4(1.f, 1.f, 0.2f, 1.f);
        uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 106);
        if (rc != UINT32_MAX) {
            rcmd_billboard(rc, t->pos, 1.2f);
            rcmd_color(rc, color);
            rcmd_visible(rc);
        }
    }
}

static void hud_text_push(float x, float y, float size, V4 color, const char* s) {
    if (!s) return;
    while (*s) {
        if (g_hud_chars_n >= g_hud_chars_cap) {
            uint32_t nc = g_hud_chars_cap * 2 + 128;
            HUDChar* np = (HUDChar*)xrealloc(g_hud_chars, nc * sizeof(HUDChar));
            if (!np) return;
            g_hud_chars = np;
            g_hud_chars_cap = nc;
        }
        HUDChar* hc = &g_hud_chars[g_hud_chars_n++];
        hc->x = x; hc->y = y; hc->size = size; hc->color = color;
        int c = (unsigned char)*s++;
        if (c < 32 || c > 127) c = '?';
        hc->glyph = c - 32;
        x += size * 0.55f;
    }
}

static void hud_draw_bar(float x, float y, float w, float h,
                          float frac, V4 fg, V4 bg) {
    if (frac < 0.f) frac = 0.f;
    if (frac > 1.f) frac = 1.f;
    stream_quad(x, y, w, h, bg);
    if (frac > 0.001f) stream_quad(x, y, w * frac, h, fg);
}

static void hud_draw_stats(void) {
    float x = 20.f, y = 20.f;
    float bar_w = 200.f, bar_h = 14.f;
    float hp_frac = 1.f;
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot != UINT32_MAX) {
        ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
        if (sd && sd->comp_maxhp[COMP_HULL] > 0.f)
            hp_frac = sd->comp_hp[COMP_HULL] / sd->comp_maxhp[COMP_HULL];
    }
    hud_draw_bar(x, y, bar_w, bar_h, hp_frac,
                  v4(0.9f, 0.2f, 0.2f, 0.9f), v4(0.15f, 0.05f, 0.05f, 0.8f));
    char buf[64];
    snprintf(buf, sizeof(buf), "HULL %d%%", (int)(hp_frac * 100.f));
    hud_text_push(x + bar_w + 10.f, y - 2.f, 16.f, v4(1,1,1,1), buf);
    y += bar_h + 6.f;
    float en_frac = 1.f;
    if (ship_slot != UINT32_MAX) {
        ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
        if (sd && sd->energy_max > 0.f) en_frac = sd->energy / sd->energy_max;
    }
    hud_draw_bar(x, y, bar_w, bar_h, en_frac,
                  v4(0.2f, 0.6f, 1.f, 0.9f), v4(0.05f, 0.10f, 0.20f, 0.8f));
    snprintf(buf, sizeof(buf), "ENERGY %d%%", (int)(en_frac * 100.f));
    hud_text_push(x + bar_w + 10.f, y - 2.f, 16.f, v4(1,1,1,1), buf);
    y += bar_h + 6.f;
    float fu_frac = 1.f;
    if (ship_slot != UINT32_MAX) {
        ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
        if (sd && sd->fuel_max > 0.f) fu_frac = sd->fuel / sd->fuel_max;
    }
    hud_draw_bar(x, y, bar_w, bar_h, fu_frac,
                  v4(0.9f, 0.7f, 0.2f, 0.9f), v4(0.15f, 0.10f, 0.05f, 0.8f));
    snprintf(buf, sizeof(buf), "FUEL %d%%", (int)(fu_frac * 100.f));
    hud_text_push(x + bar_w + 10.f, y - 2.f, 16.f, v4(1,1,1,1), buf);
    y += bar_h + 12.f;
    float xp_frac = (g_xp_b7.xp_to_next > 0)
                    ? (float)g_xp_b7.xp / (float)g_xp_b7.xp_to_next : 0.f;
    hud_draw_bar(x, y, bar_w, bar_h, xp_frac,
                  v4(0.7f, 0.3f, 0.9f, 0.9f), v4(0.10f, 0.05f, 0.15f, 0.8f));
    snprintf(buf, sizeof(buf), "LV %d  %d/%d", g_xp_b7.level, g_xp_b7.xp, g_xp_b7.xp_to_next);
    hud_text_push(x + bar_w + 10.f, y - 2.f, 16.f, v4(1,1,1,1), buf);
}

