/* Sala de radar de la lanzadera: radar grande cuando el andador esta
   dentro de la sala de ordenadores de la base/plataforma. */
typedef struct {
    uint32_t slot;
    float    closing;
    float    dist;
} RadarBlip;

static RadarBlip* g_radar_blips    = NULL;
static uint32_t   g_radar_blip_cap = 0;

static void radar_blips_reserve(uint32_t need) {
    if (need <= g_radar_blip_cap) return;
    uint32_t nc = g_radar_blip_cap ? g_radar_blip_cap : 16u;
    while (nc < need) nc *= 2u;
    RadarBlip* p = (RadarBlip*)xrealloc(g_radar_blips,
                                        (size_t)nc * sizeof(RadarBlip));
    if (p) { g_radar_blips = p; g_radar_blip_cap = nc; }
}

static void radar_blips_shutdown(void) {
    xfree(g_radar_blips);
    g_radar_blips    = NULL;
    g_radar_blip_cap = 0;
}

static int radar_blip_cmp_closing(const void* a, const void* b) {
    float ca = ((const RadarBlip*)a)->closing;
    float cb = ((const RadarBlip*)b)->closing;
    if (ca < cb) return  1;
    if (ca > cb) return -1;
    return 0;
}

static int walker_in_computer_room(void) {
    if (g_player.mode != PLAYER_MODE_ON_FOOT &&
        g_player.mode != PLAYER_MODE_PLATFORM) return 0;
    uint32_t s = g_player.inside_ship;
    if (s == UINT32_MAX || !entity_alive(s)) return 0;
    ShipDataExt* ext = ship_ext(s);
    if (!ext) return 0;
    V3 p = g_player.walker.pos_local;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_COMPUTER_ROOM)) continue;
        V3 d = v3sub(p, n->pos_local);
        if (fabsf(d.x) <= n->half_ext.x + 0.4f &&
            fabsf(d.z) <= n->half_ext.z + 0.4f &&
            fabsf(d.y) <= n->half_ext.y + 1.6f) return 1;
    }
    return 0;
}

static uint32_t radar_room_collect(V3 origin, V3 origin_vel, float range) {
    radar_blips_reserve(g_things_cap > 1 ? g_things_cap : 2);
    if (!g_radar_blips) return 0;
    uint32_t n = 0;
    V3 rel_vel;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        Thing* t = &g_things[i];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->type != ET_ASTEROID && t->type != ET_ALIEN &&
            t->type != ET_PIRATE && t->type != ET_LANZADERA &&
            t->type != ET_SHIP) continue;
        if (i == g_player.inside_ship) continue;
        V3 d = v3sub(t->pos, origin);
        float dist = v3len(d);
        if (dist > range) continue;
        rel_vel = v3sub(t->vel, origin_vel);
        float closing = 0.f;
        if (dist > 0.01f)
            closing = -v3dot(rel_vel, v3mul(d, 1.f / dist));
        g_radar_blips[n].slot    = i;
        g_radar_blips[n].closing = closing;
        g_radar_blips[n].dist    = dist;
        n++;
    }
    if (n > 1)
        qsort(g_radar_blips, n, sizeof(RadarBlip), radar_blip_cmp_closing);
    return n;
}

static void hud_draw_radar_room(void) {
    if (!walker_in_computer_room()) return;
    uint32_t home = g_player.inside_ship;
    Thing* ship = entity_get(home);
    if (!ship) return;
    V3 origin    = local_to_world_pos(home, g_player.walker.pos_local);
    V3 origin_vel = ship->vel;
    uint32_t n = radar_room_collect(origin, origin_vel, LANZADERA_RADAR_RANGE);
    float r  = (float)(g_win_w < g_win_h ? g_win_w : g_win_h) * 0.28f;
    float cx = (float)g_win_w * 0.5f;
    float cy = (float)g_win_h * 0.25f + r;
    stream_quad(cx - r, cy - r, r * 2.f, r * 2.f, v4(0.02f, 0.06f, 0.03f, 0.8f));
    stream_thick_line2d(cx - r, cy, cx + r, cy, 1.f, v4(0.2f, 0.7f, 0.2f, 0.7f));
    stream_thick_line2d(cx, cy - r, cx, cy + r, 1.f, v4(0.2f, 0.7f, 0.2f, 0.7f));
    hud_text_push(cx - r + 8.f, cy - r + 6.f, 16.f,
                  v4(0.3f, 1.f, 0.4f, 1.f), "RADAR SALA");
    float inv = r / (float)LANZADERA_RADAR_RANGE;
    for (uint32_t k = 0; k < n; k++) {
        Thing* t = &g_things[g_radar_blips[k].slot];
        V3 d = v3sub(t->pos, origin);
        float sx = cx + d.x * inv;
        float sy = cy + d.z * inv;
        V4 c;
        if (t->type == ET_ALIEN || t->type == ET_PIRATE) c = v4(1.f, 0.2f, 0.2f, 0.95f);
        else if (t->type == ET_LANZADERA)                c = v4(0.3f, 1.f, 1.f, 0.95f);
        else if (t->type == ET_SHIP)                     c = v4(0.4f, 0.6f, 1.f, 0.9f);
        else                                             c = v4(0.7f, 0.7f, 0.7f, 0.85f);
        float s = (t->type == ET_ASTEROID) ? 2.f + t->radius * 0.2f : 4.f;
        if (s > 8.f) s = 8.f;
        stream_quad(sx - s, sy - s, s * 2.f, s * 2.f, c);
    }
    int rows = (int)((r * 2.f - 60.f) / 16.f);
    if (rows < 1) rows = 1;
    for (uint32_t k = 0; k < n && (int)k < rows; k++) {
        RadarBlip* b = &g_radar_blips[k];
        Thing* t = &g_things[b->slot];
        const char* kind = (t->type == ET_ASTEROID) ? "AST" :
                           (t->type == ET_PIRATE || t->type == ET_ALIEN) ? "HOSTILE" :
                           (t->type == ET_LANZADERA) ? "BASE" : "SHIP";
        char buf[96];
        snprintf(buf, sizeof(buf), "%-7s d=%6.0fm closing=%+.1f m/s",
                 kind, b->dist, b->closing);
        V4 c = (b->closing > 0.f) ? v4(1.f, 0.6f, 0.3f, 1.f)
                                  : v4(0.5f, 0.9f, 0.5f, 1.f);
        hud_text_push(cx + r + 12.f, cy - r + 28.f + (float)k * 16.f, 14.f, c, buf);
    }
    hud_text_push(cx - r + 8.f, cy + r - 22.f, 13.f,
                  v4(0.5f, 0.9f, 0.5f, 0.8f),
                  "V: entregar carga a la lanzadera | N: construir piso");
}

static void hud_draw_radar(void) {
    if (g_player.mode == PLAYER_MODE_PILOT && piloting_is_ship()
        && g_cockpit_display.visible && g_cockpit_display.sole_control)
        return; /* map lives on cockpit tactile panel */
    float r = 90.f;
    float cx = (float)g_win_w - r - 20.f;
    float cy = (float)g_win_h - r - 20.f;
    V4 bg = v4(0.05f, 0.10f, 0.05f, 0.6f);
    stream_quad(cx - r, cy - r, r * 2.f, r * 2.f, bg);
    stream_thick_line2d(cx - r, cy, cx + r, cy, 1.f, v4(0.2f,0.6f,0.2f,0.6f));
    stream_thick_line2d(cx, cy - r, cx, cy + r, 1.f, v4(0.2f,0.6f,0.2f,0.6f));
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    Thing* ship = entity_get(ship_slot);
    if (!ship) return;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (i == ship_slot) continue;
        Thing* t = &g_things[i];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        if (t->type != ET_SHIP && t->type != ET_ALIEN &&
            t->type != ET_PIRATE && t->type != ET_ASTEROID &&
            t->type != ET_PICKUP) continue;
        V3 d = v3sub(t->pos, ship->pos);
        if (v3len(d) > 2000.f) continue;
        float sx = cx + d.x * (r / 2000.f);
        float sy = cy + d.z * (r / 2000.f);
        V4 c;
        if (t->type == ET_ALIEN || t->type == ET_PIRATE) c = v4(1.f, 0.2f, 0.2f, 0.9f);
        else if (t->type == ET_ASTEROID)                  c = v4(0.6f, 0.6f, 0.6f, 0.9f);
        else if (t->type == ET_PICKUP)                    c = v4(0.2f, 1.f, 0.9f, 0.9f);
        else                                              c = v4(0.5f, 0.5f, 1.f, 0.9f);
        stream_quad(sx - 2.f, sy - 2.f, 4.f, 4.f, c);
    }
}

static void hud_draw_crosshair(void) {
    float cx = (float)g_win_w * 0.5f;
    float cy = (float)g_win_h * 0.5f;
    V4 col = v4(1.f, 1.f, 1.f, 0.8f);
    float s = 8.f;
    stream_thick_line2d(cx - s, cy, cx - 3.f, cy, 1.5f, col);
    stream_thick_line2d(cx + 3.f, cy, cx + s, cy, 1.5f, col);
    stream_thick_line2d(cx, cy - s, cx, cy - 3.f, 1.5f, col);
    stream_thick_line2d(cx, cy + 3.f, cx, cy + s, 1.5f, col);
}

static void hud_draw_achievement_toast(void) {
    if (!g_achievement_toast.active) return;
    int idx = g_achievement_toast.index;
    if (idx < 0 || idx >= MAX_ACHIEVEMENTS) return;
    Achievement* a = &g_achievements[idx];
    float x = (float)g_win_w - 320.f;
    float y = 20.f;
    float alpha = clampf(g_achievement_toast.timer, 0.f, 1.f);
    stream_quad(x - 10.f, y - 5.f, 300.f, 45.f, v4(0.1f, 0.1f, 0.1f, alpha * 0.7f));
    hud_text_push(x, y, 14.f, v4(1.f, 0.9f, 0.3f, alpha), "ACHIEVEMENT UNLOCKED");
    hud_text_push(x, y + 18.f, 16.f, v4(1, 1, 1, alpha), a->name ? a->name : "?");
}

static void hud_draw_reputation_toast(void) {
    if (!g_reputation_toast.active) return;
    float x = (float)g_win_w - 320.f;
    float y = 80.f;
    float alpha = clampf(g_reputation_toast.timer, 0.f, 1.f);
    char buf[64];
    snprintf(buf, sizeof(buf), "REP %+d (F%u)",
             g_reputation_toast.delta, g_reputation_toast.faction);
    V4 col = (g_reputation_toast.delta >= 0)
             ? v4(0.4f, 1.f, 0.4f, alpha)
             : v4(1.f, 0.4f, 0.4f, alpha);
    hud_text_push(x, y, 14.f, col, buf);
}

static void hud_draw_messages(void) {
    int vw = g_win_w, vh = g_win_h;
    for (uint32_t id = 0; id < g_things_cap; id++) {
        if (!g_alive[id] || g_things[id].type != ET_MESSAGE) continue;
        uint32_t pidx = ENT_I(&g_things[id], 0);
        if (pidx >= GAME_MAX_NOTICES) continue;
        const char* txt = g_game.notices[pidx].text;
        if (!txt[0]) continue;
        float sx, sy;
        if (!project_screen(g_things[id].pos, g_game.cam.vp, &sx, &sy, vw, vh))
            continue;
        if (sx < 0 || sx > vw || sy < 0 || sy > vh) continue;
        float life = ENT_F(&g_things[id], 1);
        float maxl = ENT_F(&g_things[id], 2);
        float a = (maxl > 0.f) ? clampf(life / maxl, 0.f, 1.f) : 1.f;
        text_push_centered(sx, sy, 14, v4(0.9f, 0.9f, 0.9f, a), txt);
    }
}

static void hud_draw_debug_paths(void) {
    if (!g_debug_paths) return;
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return;
    for (int i = 0; i < ext->node_count; i++) {
        V3 nw = ship_node_world_pos(ship_slot, i);
        V4 col = (ext->nodes[i].current_hp < ext->nodes[i].structural_hp)
                 ? v4(1.f, 0.4f, 0.4f, 0.9f)
                 : v4(0.4f, 1.f, 0.4f, 0.9f);
        uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 200);
        if (rc != UINT32_MAX) {
            rcmd_billboard(rc, nw, 0.5f);
            rcmd_color(rc, col);
            rcmd_visible(rc);
        }
    }    // ---- Bloque 25 verification counter ----
    {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "CELLS  int=%u  ext=%u  world=%u",
                 g_dbg_cells_interior, g_dbg_cells_exterior, g_dbg_cells_world);
        hud_text_push(20.f, 300.f, 14.f, v4(0.55f, 1.f, 0.55f, 1.f), buf);
        snprintf(buf, sizeof(buf), "MESH  box=%d sph=%d cyl=%d total=%d",
                 g_mesh_unit_box_id, g_mesh_unit_sphere_id,
                 g_mesh_unit_cyl_id, g_mesh_count);
        hud_text_push(20.f, 318.f, 14.f, v4(0.55f, 1.f, 0.55f, 1.f), buf);
    }
    if (g_player.mode == PLAYER_MODE_PILOT && piloting_is_ship()) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "COCKPIT DISP  y=%.0f%%  cross=(%.2f,%.2f)",
                 g_cockpit_display.y_offset * 100.f,
                 g_cockpit_display.crosshair_x,
                 g_cockpit_display.crosshair_y);
        hud_text_push(20.f, 340.f, 13.f,
                       v4(1.f, 0.85f, 0.30f, 0.9f), buf);

        V3 sd = cockpit_display_aim_direction();
        V3 ship_fwd;
        Thing* sh = entity_get(g_player.inside_ship);
        if (sh) {
            float p = ENT_F(sh, 24);
            ship_fwd = v3norm(v3(sinf(sh->rot) * cosf(p),
                                  sinf(p),
                                 -cosf(sh->rot) * cosf(p)));
        } else {
            ship_fwd = v3(0, 0, 1);
        }
        float ang = acosf(clampf(v3dot(sd, ship_fwd), -1.f, 1.f))
                    * 180.f / PI_F;
        snprintf(buf, sizeof(buf),
                 "SEC AIM offset from forward: %.1f deg", ang);
        hud_text_push(20.f, 358.f, 13.f,
                       v4(1.f, 0.85f, 0.30f, 0.9f), buf);
    }
    
}

static void cockpit_display_render(void) {
    if (g_ctx != CTX_GAME) return;
    if (g_player.mode != PLAYER_MODE_PILOT) return;
    if (!piloting_is_ship()) return;
    if (!g_cockpit_display.visible) return;

    CockpitDisplay* d = &g_cockpit_display;
    float w, h, x, y, a = d->alpha;
    cockpit_display_rect(&x, &y, &w, &h);
    float cy = y + h * 0.5f;
    char buf[96];
    static const char* page_names[CPD_PAGE_COUNT] = { "MAP", "SYS", "TGT", "NAV" };

    /* Panel body */
    stream_quad(x, y, w, h, v4(0.02f, 0.06f, 0.10f, 0.62f * a));
    V4 frame = d->touch_focus ? v4(0.45f, 0.95f, 1.f, 0.9f * a)
                              : v4(0.30f, 0.75f, 0.95f, 0.75f * a);
    stream_quad(x, y, w, 2.f, frame);
    stream_quad(x, y + h - 2.f, w, 2.f, frame);
    stream_quad(x, y, 2.f, h, frame);
    stream_quad(x + w - 2.f, y, 2.f, h, frame);

    /* Tab bar — tactile page switch */
    {
        float tab_h = 22.f;
        float tab_w = w / (float)CPD_PAGE_COUNT;
        for (int i = 0; i < CPD_PAGE_COUNT; i++) {
            float tx = x + tab_w * (float)i;
            int sel = (d->page == i);
            V4 bg = sel ? v4(0.10f, 0.28f, 0.38f, 0.85f * a)
                        : v4(0.04f, 0.10f, 0.16f, 0.7f * a);
            if (sel && d->tab_flash > 0.f)
                bg.w = clampf(bg.w + d->tab_flash, 0.f, 1.f);
            stream_quad(tx + 1.f, y + 1.f, tab_w - 2.f, tab_h - 1.f, bg);
            hud_text_push(tx + 10.f, y + 5.f, 11.f,
                          sel ? v4(0.7f, 1.f, 1.f, a) : v4(0.5f, 0.7f, 0.8f, 0.75f * a),
                          page_names[i]);
        }
        stream_quad(x, y + 22.f, w, 1.f, v4(0.25f, 0.55f, 0.7f, 0.5f * a));
    }

    float content_y = y + 26.f;
    float content_h = h - 44.f;

    if (d->page == CPD_PAGE_MAP) {
        float radar_r  = content_h * 0.48f;
        float radar_cx = x + content_h * 0.5f + 8.f;
        float radar_cy = content_y + content_h * 0.5f;
        cockpit_radar_draw(radar_cx, radar_cy, radar_r);
        cockpit_vitality_draw(x + content_h + 18.f, content_y + 4.f,
                               w - content_h - 28.f, content_h - 8.f);
        /* secondary aim on map only (not a world mirilla) */
        float ch_x = x + w * 0.5f + d->crosshair_x * w * 0.42f;
        float ch_y = cy - d->crosshair_y * content_h * 0.42f;
        V4 gold = v4(1.f, 0.85f, 0.30f, 0.9f * a);
        stream_thick_line2d(ch_x - 8.f, ch_y, ch_x - 3.f, ch_y, 2.f, gold);
        stream_thick_line2d(ch_x + 3.f, ch_y, ch_x + 8.f, ch_y, 2.f, gold);
        stream_thick_line2d(ch_x, ch_y - 8.f, ch_x, ch_y - 3.f, 2.f, gold);
        stream_thick_line2d(ch_x, ch_y + 3.f, ch_x, ch_y + 8.f, 2.f, gold);
    } else if (d->page == CPD_PAGE_SYS) {
        cockpit_vitality_draw(x + 12.f, content_y + 4.f, w - 24.f, content_h - 8.f);
        uint32_t slot = g_player.inside_ship;
        ShipData* sd = (ShipData*)entity_side_ptr(slot);
        Thing* sh = entity_get(slot);
        if (sd && sh) {
            snprintf(buf, sizeof(buf), "HP %.0f/%.0f  mass %.0f",
                     sh->hp, sh->maxhp, sh->mass);
            hud_text_push(x + 16.f, content_y + content_h - 36.f, 11.f,
                          v4(0.7f, 0.9f, 1.f, a), buf);
            snprintf(buf, sizeof(buf), "fuel %.1f/%.1f  energy %.0f%%",
                     sd->fuel, sd->fuel_max,
                     (sd->energy_max > 0.f) ? (sd->energy / sd->energy_max * 100.f) : 0.f);
            hud_text_push(x + 16.f, content_y + content_h - 22.f, 11.f,
                          v4(0.7f, 0.9f, 1.f, a), buf);
        }
    } else if (d->page == CPD_PAGE_TGT) {
        hud_text_push(x + 12.f, content_y + 4.f, 12.f,
                      v4(0.6f, 0.95f, 1.f, a), "SCAN LOCKS");
        float ry = content_y + 22.f;
        int drawn = 0;
        for (uint32_t i = 0; i < g_scan_targets_n && drawn < 8; i++) {
            ScanTarget* st = &g_scan_targets[i];
            if (!st) continue;
            snprintf(buf, sizeof(buf), "target %u", (unsigned)i);
            hud_text_push(x + 16.f, ry, 11.f, v4(0.85f, 0.9f, 0.7f, a), buf);
            ry += 14.f; drawn++;
        }
        if (drawn == 0)
            hud_text_push(x + 16.f, ry, 11.f, v4(0.5f, 0.55f, 0.6f, a), "no contacts");
    } else if (d->page == CPD_PAGE_NAV) {
        Thing* sh = entity_get(g_player.inside_ship);
        if (sh) {
            float ry = content_y + 8.f;
            snprintf(buf, sizeof(buf), "ZONE  %d  %d  %d",
                     g_game.zone_coords[0], g_game.zone_coords[1], g_game.zone_coords[2]);
            hud_text_push(x + 14.f, ry, 12.f, v4(0.7f, 1.f, 0.9f, a), buf);
            ry += 16.f;
            ZonePersist* zp = zone_persist_find(
                g_game.zone_coords[0], g_game.zone_coords[1], g_game.zone_coords[2]);
            if (zp && zp->pattern_gen) {
                snprintf(buf, sizeof(buf), "FORM dens %.0f%%  vert %.0f%%  rare %.0f%%  haz %.0f%%%s",
                         zp->form[0]*100.f, zp->form[1]*100.f,
                         zp->form[2]*100.f, zp->form[3]*100.f,
                         zp->radar_silent ? "  SILENT" : "");
                hud_text_push(x + 14.f, ry, 10.f, v4(0.65f, 0.9f, 1.f, a), buf);
                ry += 14.f;
            }
            snprintf(buf, sizeof(buf), "POS  %.0f  %.0f  %.0f",
                     sh->pos.x, sh->pos.y, sh->pos.z);
            hud_text_push(x + 14.f, ry, 12.f, v4(0.7f, 1.f, 0.9f, a), buf);
            ry += 16.f;
            float pitch = ENT_F(sh, 24);
            snprintf(buf, sizeof(buf), "HDG  %.0f deg   pitch %.0f   SPD %.1f",
                     sh->rot * 180.f / PI_F, pitch * 180.f / PI_F, v3len(sh->vel));
            hud_text_push(x + 14.f, ry, 11.f, v4(0.7f, 1.f, 0.9f, a), buf);
            ry += 16.f;

            float jump_min = zone_jump_min_range();
            float step = ZONE_HALF * 2.f;
            V3 zc = v3((float)(g_game.zone_coords[0] * (int)step),
                        (float)(g_game.zone_coords[1] * (int)step),
                        (float)(g_game.zone_coords[2] * (int)step));
            V3 rel = v3sub(sh->pos, zc);
            float radial = sqrtf(rel.x*rel.x + rel.z*rel.z);
            snprintf(buf, sizeof(buf), "JUMP MIN  %.0f   radial %.0f   ring %s",
                     jump_min, radial,
                     radial >= jump_min * 0.85f ? "ACTIVE" : "inside");
            hud_text_push(x + 14.f, ry, 11.f,
                          radial >= jump_min * 0.85f
                            ? v4(1.f, 0.85f, 0.3f, a)
                            : v4(0.6f, 0.85f, 0.95f, a), buf);
            ry += 15.f;

            if (g_zone_jump_pending_dx || g_zone_jump_pending_dy || g_zone_jump_pending_dz) {
                int32_t tx = g_game.zone_coords[0] + g_zone_jump_pending_dx;
                int32_t ty = g_game.zone_coords[1] + g_zone_jump_pending_dy;
                int32_t tz = g_game.zone_coords[2] + g_zone_jump_pending_dz;
                snprintf(buf, sizeof(buf), "CORRIDOR -> %d %d %d   HYPERJUMP to transit",
                         tx, ty, tz);
                hud_text_push(x + 14.f, ry, 12.f, v4(1.f, 0.75f, 0.25f, a), buf);
                ry += 14.f;
                ZonePersist* dest = zone_persist_find(tx, ty, tz);
                if (dest && dest->pattern_gen) {
                    snprintf(buf, sizeof(buf), "dest form dens %.0f%% haz %.0f%%%s",
                             dest->form[0]*100.f, dest->form[3]*100.f,
                             dest->radar_silent ? " silent" : "");
                    hud_text_push(x + 14.f, ry, 10.f, v4(0.7f, 0.8f, 0.9f, a), buf);
                } else {
                    hud_text_push(x + 14.f, ry, 10.f, v4(0.55f, 0.65f, 0.75f, a),
                                  "dest not scanned yet");
                }
            } else {
                hud_text_push(x + 14.f, ry, 10.f, v4(0.5f, 0.65f, 0.75f, a),
                              "No jump corridor — fly outward");
            }
            ry += 16.f;
            snprintf(buf, sizeof(buf), "PANEL %s  |  PgUp/Dn snap",
                     d->pos_preset == CPD_POS_TOP ? "TOP" : "BOTTOM");
            hud_text_push(x + 14.f, ry, 10.f, v4(0.5f, 0.7f, 0.85f, 0.85f * a), buf);
        }
    }

    /* Footer */
    snprintf(buf, sizeof(buf), "%s  |  %s  |  aim %.2f,%.2f  |  F7/F8 pages",
             page_names[d->page],
             d->pos_preset == CPD_POS_TOP ? "TOP" : "BOT",
             d->crosshair_x, d->crosshair_y);
    hud_text_push(x + 8.f, y + h - 14.f, 9.f,
                  v4(0.5f, 0.8f, 0.95f, 0.7f * a), buf);
}

static void hud_render(void) {
    g_pick_n = 0;
    cockpit_display_render();               // NEW — cockpit computer display
    size_t n = sizeof(g_hud_sections) / sizeof(g_hud_sections[0]);
    for (size_t i = 0; i < n; i++)
        if (g_hud_sections[i]) g_hud_sections[i]();
    scan_publish();
}

