/* BLOQUE 17e — cola de forja cerca ('K') e instalación manual ('J') */

static void act_forge_queue(int32_t arg);
static void act_assemble(int32_t arg);

static uint32_t player_cargo_ship_slot(void) {
    uint32_t s = actor_ship_slot();
    if (s != UINT32_MAX && entity_alive(s)) return s;
    return g_player_platform_slot;
}

static int forge_consume_raw(ShipData* sd, uint32_t qty, uint16_t* out_first) {
    if (!sd) return 0;
    uint32_t left = qty;
    for (uint32_t m = 0; m < MATERIAL_COUNT && left > 0; m++) {
        if (!sd->matinv[m]) continue;
        uint32_t take = sd->matinv[m] < left ? sd->matinv[m] : left;
        if (*out_first == 0xFFFFu) *out_first = (uint16_t)m;
        sd->matinv[m] -= (uint32_t)take;
        left -= take;
    }
    return (left == 0);
}

static int forge_near_player(float range) {
    if (g_platform_forge_slot == UINT32_MAX || !entity_alive(g_platform_forge_slot))
        return 0;
    Thing* f = entity_get(g_platform_forge_slot);
    if (!f) return 0;
    V3 pp;
    if (g_player.mode == PLAYER_MODE_EVA) pp = g_player.eva_pos;
    else if (g_player.inside_ship != UINT32_MAX &&
             entity_alive(g_player.inside_ship)) {
        if (g_player.mode == PLAYER_MODE_PILOT) {
            Thing* in = entity_get(g_player.inside_ship);
            if (!in) return 0;
            pp = in->pos;
        } else
            pp = local_to_world_pos(g_player.inside_ship, g_player.walker.pos_local);
    }
    else return 0;
    return v3dist(pp, f->pos) < range;
}

static void act_forge_queue(int32_t arg) {
    (void)arg;
    if (g_ctx != CTX_GAME) return;
    if (!forge_near_player(4.5f)) { notice_push("NO FORGE HERE"); return; }
    uint32_t s = player_cargo_ship_slot();
    if (s == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(s);
    if (!sd) return;
    uint32_t mats = 0;
    for (uint32_t m = 0; m < MATERIAL_COUNT; m++) mats += sd->matinv[m];
    if (mats < FORGE_PART_COST) { notice_push("NEED RAW MATS"); return; }
    uint16_t first_mat = 0xFFFFu;
    if (!forge_consume_raw(sd, FORGE_PART_COST, &first_mat))
        { notice_push("NEED RAW MATS"); return; }
    uint32_t kind = g_forge_out_kind;
    g_forge_out_kind = (g_forge_out_kind + 1) % COMP_COUNT;
    uint32_t d = xrng_u32() % 100u;
    uint32_t quality = (d < 12u) ? 3u : (d < 45u) ? 2u : 1u;
    if (g_platform_forge_slot == UINT32_MAX ||
        !forge_add(g_platform_forge_slot,
                   first_mat == 0xFFFFu ? (uint16_t)0 : first_mat,
                   (uint16_t)FORGE_PART_COST,
                   (uint16_t)kind, (uint16_t)quality))
        { notice_push("FORGE QUEUE FULL"); return; }
    char b[96];
    const char* kn[] = { "HULL", "ENGINE", "SHIELD", "LIFE" };
    snprintf(b, sizeof(b), "FORGING %s (Q%u) -%u MATS",
             kn[kind % COMP_COUNT], quality, FORGE_PART_COST);
    notice_push(b);
}

static void act_assemble(int32_t arg) {
    (void)arg;
    if (g_ctx != CTX_GAME) return;
    if (!part_cargo_count()) { notice_push("NO PARTS IN HAND"); return; }
    if (!assembly_near_own_ship()) { notice_push("SHIP NOT NEARBY"); return; }
    if (!assembly_install_one(v3zero())) notice_push("ASSEMBLY FAILED");
}


static float cockpit_zoom_limits(float* out_min, float* out_max) {
    float zmin = 0.55f, zmax = 1.85f; /* poor default visor */
    uint32_t slot = g_player.inside_ship;
    if (slot != UINT32_MAX) {
        ShipData* sd = (ShipData*)entity_side_ptr(slot);
        if (sd) {
            float q = 0.35f;
            if (sd->computer_slot != UINT32_MAX && sd->computer_slot != 0)
                q += 0.35f;
            if (sd->comp_intact[COMP_COMPUTER])
                q += 0.25f;
            if (sd->energy_max > 0.f)
                q += 0.15f * clampf(sd->energy / sd->energy_max, 0.f, 1.f);
            zmin = lerpf(0.70f, 0.35f, q); /* better computer → closer zoom in */
            zmax = lerpf(1.60f, 3.20f, q); /* better → farther zoom out */
        }
    }
    if (out_min) *out_min = zmin;
    if (out_max) *out_max = zmax;
    return zmax - zmin;
}
static void act_zoom_in(int32_t arg) {
    (void)arg;
    float zmin, zmax; cockpit_zoom_limits(&zmin, &zmax);
    g_game.zoom *= 1.1f;
    if (g_game.zoom > zmax) g_game.zoom = zmax;
}
static void act_zoom_out(int32_t arg) {
    (void)arg;
    float zmin, zmax; cockpit_zoom_limits(&zmin, &zmax);
    g_game.zoom *= 0.9f;
    if (g_game.zoom < zmin) g_game.zoom = zmin;
}

