static void action_dispatch(Action a, int32_t arg) {
    if ((int)a < 0 || a >= ACT_COUNT) return;
    if (a >= ACT_MIX_MODE_0 && a <= ACT_MIX_MODE_6)
        arg = (int32_t)(a - ACT_MIX_MODE_0);
    else if (a >= ACT_SLOT_0 && a <= ACT_SLOT_9)
        arg = (int32_t)(a - ACT_SLOT_0);
    else if (a >= ACT_PERK_1 && a <= ACT_PERK_5)
        arg = (int32_t)(a - ACT_PERK_1);
    else if (a == ACT_MIX_A) arg = 0;
    else if (a == ACT_MIX_B) arg = 1;
    if (g_actions[a]) g_actions[a](arg);
}

/* ---------------- Player action helpers ---------------- */

static void player_try_enter_drone(void) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_DRONE) continue;
        if (!(g_things[i].flags & ENT_FLAG_PLAYER_OWNED)) continue;
        if (g_things[i].flags & ENT_FLAG_MARKED_DEAD) continue;
        if (player_transition_to(PLAYER_MODE_PILOT, i)) return;
    }
    notice_push("NO DRONE IN RANGE");
}
static void player_try_exit_drone(void) {
    if (!piloting_is_drone()) return;
    player_transition_to(PLAYER_MODE_EVA, UINT32_MAX);
}
static void player_deploy_drone(void) {
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    drone_deploy_from_ship(ship_slot, xrng_u32());
}
static void player_recall_drone(void) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type != ET_DRONE) continue;
        if (drone_recall(i)) return;
    }
}
static void player_command_drone(void) {
    ShipDataExt* ext = ship_ext(g_game.player_ship_slot);
    if (!ext) return;
    int worst = ship_find_worst_damaged_node(g_game.player_ship_slot);
    if (worst < 0) { notice_push("ALL NODES OK"); return; }
    int cmd = 0;
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        uint32_t d = ext->drone_slots_ship[i];
        if (d == UINT32_MAX || !entity_alive(d)) continue;
        Thing* dt = entity_get(d);
        if (!dt) continue;
        if (!(ENT_I(dt, 21) & DRONE_CAP_REPAIR)) continue;
        ENT_SET_I(dt, 24, g_game.player_ship_slot);
        ENT_SET_I(dt, 25, (uint32_t)worst);
        behavior_force(d, BEH_REPAIR_ID);
        cmd++;
    }
    if (cmd == 0) notice_push("NO REPAIR DRONES");
}
static void player_convert_platform(void) {
    uint32_t slot = actor_ship_slot();
    if (slot == UINT32_MAX) return;
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    if (ext->is_platform) ship_convert_to_ship(slot);
    else                  ship_convert_to_platform(slot);
}
static void player_attach_fuselage(void) {
    if (g_game.player_ship_slot == UINT32_MAX) return;
    ship_grow_random_fuselage(g_game.player_ship_slot, 1);
    notice_push("FUSELAGE ATTACHED");
}
static void player_try_hyperjump(void) {
    int dx = 0, dy = 0, dz = 0;
    if (g_zone_jump_pending_dx || g_zone_jump_pending_dy || g_zone_jump_pending_dz) {
        dx = g_zone_jump_pending_dx;
        dy = g_zone_jump_pending_dy;
        dz = g_zone_jump_pending_dz;
    } else {
        Thing* ship = entity_get(g_game.player_ship_slot);
        if (ship) {
            float cp = cosf(ENT_F(ship, 24)), sp = sinf(ENT_F(ship, 24));
            V3 f = v3(sinf(ship->rot) * cp, sp, -cosf(ship->rot) * cp);
            float ax = fabsf(f.x), ay = fabsf(f.y), az = fabsf(f.z);
            if (ax >= ay && ax >= az) dx = f.x >= 0.f ? 1 : -1;
            else if (az >= ay)        dz = f.z >= 0.f ? 1 : -1;
            else                      dy = f.y >= 0.f ? 1 : -1;
        } else dx = 1;
    }
    int32_t nx = g_game.zone_coords[0] + dx;
    int32_t ny = g_game.zone_coords[1] + dy;
    int32_t nz = g_game.zone_coords[2] + dz;
    zone_generate(nx, ny, nz);
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (ship) {
        float step = ZONE_HALF * 2.f;
        ship->pos.x -= (float)dx * step;
        ship->pos.y -= (float)dy * step;
        ship->pos.z -= (float)dz * step;
    }
    g_zone_jump_pending_dx = g_zone_jump_pending_dy = g_zone_jump_pending_dz = 0;
    notice_push("HYPERJUMP");
}

// =====================================================================
// BLOQUE 11b — Context tick + Intent + helpers de jugador
// =====================================================================

static void menu_cycle(int dir);          // forward
static void menu_cycle_dir(int dir);      // forward

static void menu_repeat_tick(void) {
    if (g_ctx != CTX_MENU && g_ctx != CTX_PAUSED) return;
    if (input_repeat(ACT_MENU_UP,    0.35f, 0.10f)) menu_cycle(-1);
    if (input_repeat(ACT_MENU_DOWN,  0.35f, 0.10f)) menu_cycle(+1);
    if (input_repeat(ACT_MENU_LEFT,  0.35f, 0.10f)) menu_cycle_dir(-1);
    if (input_repeat(ACT_MENU_RIGHT, 0.35f, 0.10f)) menu_cycle_dir(+1);
    /* Raton: hover selecciona, click confirma (pick zones de menu_draw_item) */
    const MenuSpec* spec = menu_spec_for(g_menu_kind);
    if (!spec || spec->count <= 0) return;
    int32_t arg = 0;
    int32_t id = render_pick_test((float)input_mouse_x(),
                                  (float)input_mouse_y(), &arg);
    if (id >= 100 && id < 100 + spec->count) {
        g_menu_sel = id - 100;
        if (input_lmb_down()) menu_confirm(g_menu_sel);
    }
}

static void context_tick_impl(InputContext ctx, float dt) {
    switch (ctx) {
        case CTX_GAME:    break;
        case CTX_PAUSED:  break;
        case CTX_DOCKED:  docked_ui_tick(dt);  break;
        case CTX_GARAGE:  garage_ui_tick(dt);  break;
        case CTX_MIX:     mixing_ui_tick(dt);  break;
        case CTX_CONFORM: conform_ui_tick(dt); break;
        case CTX_TABLET:  tablet_ui_tick(dt);  break;
        case CTX_MODAL:   modal_ui_tick(dt);   break;
        case CTX_MENU:    menu_repeat_tick();  break;
        default: break;
    }
}

static void intent_from_input(Intent* out) {
    if (!out) return;
    intent_full_clear(out);
    if (input_held(ACT_FWD))   out->throttle += 1.f;
    if (input_held(ACT_BACK))  out->throttle -= 1.f;
    if (input_held(ACT_LEFT))  out->strafe   -= 1.f;
    if (input_held(ACT_RIGHT)) out->strafe   += 1.f;
    if (player_cap(CAP_EVA_VERTICAL)) {
        if (input_held(ACT_JUMP)) out->move_dir.y += 1.f;
        if (input_held(ACT_DOWN)) out->move_dir.y -= 1.f;
        out->crouch = 0;
    } else if (player_cap(CAP_CROUCH)) {
        out->crouch = input_held(ACT_DOWN);
    }
    out->boost = input_held(ACT_BOOST);
    out->brake = input_held(ACT_BRAKE);
    out->evasive = input_held(ACT_EVASIVE);
    out->sprint = input_held(ACT_BOOST);
    if (cap_can_use(CAP_OWNER_PLAYER, CAP_REPAIR)) out->repair = toggle_get(ACT_REPAIR);
    if (cap_can_use(CAP_OWNER_PLAYER, CAP_FIRE_VEHICLE)) {
        out->fire_primary = input_held(ACT_FIRE_PRIMARY);
        out->fire_secondary = input_held(ACT_FIRE_SECONDARY);
    }
    if (cap_can_use(CAP_OWNER_PLAYER, CAP_MINE)) out->mine = input_held(ACT_FIRE_SECONDARY);
    out->jump = input_pressed(ACT_JUMP);
    if (player_cap(CAP_INTERACT)) out->interact = input_pressed(ACT_INTERACT);
    int dx, dy; input_take_mouse_delta(&dx, &dy);
    out->look_dx = (float)dx; out->look_dy = (float)dy;
    out->accuracy_mod = 1.f;
    if (player_cap(CAP_AIM)) {
        if (player_cap(CAP_CAMERA_FOLLOW)) {
            V3 cam_fwd = v3sub(g_game.cam.target, g_game.cam.pos);
            if (v3lensq(cam_fwd) > 1e-6f) out->aim_dir = v3norm(cam_fwd);
        } else {
            V3 eye = player_eye_base();
            V3 look = player_look();
            V3 d = v3sub(look, eye);
            if (v3lensq(d) > 1e-6f) out->aim_dir = v3norm(d);
        }
    }
}

// ---------- helpers sueltos de jugador ----------

static void rect_travel_toggle(void) {
    if (g_game.player_ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (!sd || !ship) return;
    if (g_rect_travel) { g_rect_travel = 0; notice_push("TRAVEL OFF"); return; }
    if (sd->fuel < 5.f) { notice_push("NEED FUEL"); return; }
    float cy = cosf(ship->rot), sy = sinf(ship->rot);
    float cp = cosf(ENT_F(ship, 24)), sp = sinf(ENT_F(ship, 24));
    g_rect_dir = v3(sy * cp, sp, -cy * cp);
    g_rect_factor = xrng_range(0.9f, 1.2f);
    g_rect_target_speed = sd->max_speed * 2.f * g_rect_factor;
    g_rect_travel = 1;
    notice_push("RECT TRAVEL ON");
}

