// =====================================================================
// BLOQUE 12a — Stream system (VBO batching para flat/billboard/lines)
// =====================================================================

static void stream_grow(void) {
    size_t new_cap = g_flat_cap ? g_flat_cap * 2 : 65536;
    FlatVtx* nc = (FlatVtx*)xrealloc(g_flat_cpu, new_cap * sizeof(FlatVtx));
    if (!nc) return;
    g_flat_cpu = nc;
    g_flat_cap = new_cap;
    gl_BindBuffer(GL_ARRAY_BUFFER, g_flat_vbo);
    gl_BufferData(GL_ARRAY_BUFFER,
                   (GLsizeiptr_)(new_cap * sizeof(FlatVtx)),
                   NULL, GL_DYNAMIC_DRAW);
}

static void stream_init(void) {
    if (g_flat_vao) return;
    gl_GenVertexArrays(1, &g_flat_vao);
    gl_GenBuffers(1, &g_flat_vbo);
    g_flat_cap = 65536;
    g_flat_cpu = (FlatVtx*)xmalloc(g_flat_cap * sizeof(FlatVtx));
    if (!g_flat_cpu) { g_flat_cap = 0; return; }
    gl_BindVertexArray(g_flat_vao);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_flat_vbo);
    gl_BufferData(GL_ARRAY_BUFFER,
                   (GLsizeiptr_)(g_flat_cap * sizeof(FlatVtx)),
                   NULL, GL_DYNAMIC_DRAW);
    gl_VertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, sizeof(FlatVtx), (void*)0);
    gl_EnableVertexAttribArray(0);
    gl_VertexAttribPointer(1, 4, GL_FLOAT, GL_FALSE, sizeof(FlatVtx),
                            (void*)(3 * sizeof(float)));
    gl_EnableVertexAttribArray(1);
    gl_VertexAttribPointer(2, 2, GL_FLOAT, GL_FALSE, sizeof(FlatVtx),
                            (void*)(7 * sizeof(float)));
    gl_EnableVertexAttribArray(2);
    gl_VertexAttribPointer(3, 4, GL_FLOAT, GL_FALSE, sizeof(FlatVtx),
                            (void*)(9 * sizeof(float)));
    gl_EnableVertexAttribArray(3);
    gl_BindVertexArray(0);
}

static void stream_destroy(void) {
    if (g_flat_vbo && gl_DeleteBuffers)      gl_DeleteBuffers(1, &g_flat_vbo);
    if (g_flat_vao && gl_DeleteVertexArrays) gl_DeleteVertexArrays(1, &g_flat_vao);
    if (g_flat_cpu) { xfree(g_flat_cpu); g_flat_cpu = NULL; }
    g_flat_vao = 0; g_flat_vbo = 0; g_flat_cap = 0; g_flat_n = 0;
}

static void stream_push_tex(V3 p, V4 c, float u, float v,
                              float ex, float ey, float ez, float ew) {
    if (g_flat_n >= g_flat_cap) stream_grow();
    if (g_flat_n >= g_flat_cap) return;
    FlatVtx* d = &g_flat_cpu[g_flat_n++];
    d->pos = p; d->color = c;
    d->u = u; d->v = v;
    d->ex = ex; d->ey = ey; d->ez = ez; d->ew = ew;
}

static void stream_push(V3 p, V4 c) {
    stream_push_tex(p, c, UV_BLANCO_U, UV_BLANCO_V, 1.f, 0.f, 0.f, 0.f);
}

static void stream_quad(float x, float y, float w, float h, V4 col) {
    V3 a = v3(x, y, 0), b = v3(x + w, y, 0);
    V3 c = v3(x + w, y + h, 0), d = v3(x, y + h, 0);
    stream_push(a, col); stream_push(b, col); stream_push(c, col);
    stream_push(a, col); stream_push(c, col); stream_push(d, col);
}

static void stream_billboard_tex(V3 center, float size, V4 col, V3 cam_pos,
                                   float u0, float v0, float u1, float v1,
                                   float ex, float ey, float ez, float ew) {
    V3 toCam = v3sub(cam_pos, center);
    float d = v3len(toCam);
    if (d < EPS) return;
    toCam = v3mul(toCam, 1.f / d);
    V3 up = v3(0, 1, 0);
    V3 right = v3cross(up, toCam);
    float rl = v3len(right);
    if (rl < 0.01f) right = v3(1, 0, 0);
    else right = v3mul(right, 1.f / rl);
    V3 realUp = v3cross(toCam, right);
    float hs = size * 0.5f;
    V3 hr = v3mul(right, hs), hu = v3mul(realUp, hs);
    V3 a = v3sub(v3sub(center, hr), hu);
    V3 b = v3sub(v3add(center, hr), hu);
    V3 c = v3add(v3add(center, hr), hu);
    V3 e = v3add(v3sub(center, hr), hu);
    stream_push_tex(a, col, u0, v0, ex, ey, ez, ew);
    stream_push_tex(b, col, u1, v0, ex, ey, ez, ew);
    stream_push_tex(c, col, u1, v1, ex, ey, ez, ew);
    stream_push_tex(a, col, u0, v0, ex, ey, ez, ew);
    stream_push_tex(c, col, u1, v1, ex, ey, ez, ew);
    stream_push_tex(e, col, u0, v1, ex, ey, ez, ew);
}

static void stream_thick_line2d(float x0, float y0, float x1, float y1,
                                  float thick, V4 col) {
    float dx = x1 - x0, dy = y1 - y0;
    float len = sqrtf(dx * dx + dy * dy);
    if (len < EPS) return;
    float nx = -dy / len * (thick * 0.5f);
    float ny =  dx / len * (thick * 0.5f);
    V3 a = v3(x0 + nx, y0 + ny, 0), b = v3(x1 + nx, y1 + ny, 0);
    V3 c = v3(x1 - nx, y1 - ny, 0), d = v3(x0 - nx, y0 - ny, 0);
    stream_push(a, col); stream_push(b, col); stream_push(c, col);
    stream_push(a, col); stream_push(c, col); stream_push(d, col);
}

static void stream_flush(const Mat4 vp, uint32_t n_total, uint32_t n_tri) {
    if (n_total == 0 || !g_flat_cpu || !g_shader_flat) return;
    gl_UseProgram(g_shader_flat);
    gl_UniformMatrix4fv(g_flat_u_vp, 1, GL_FALSE, vp);
    gl_Uniform1f(g_flat_u_time, (float)time_get());
    gl_Uniform1i(g_flat_u_tex, 0);
    gl_ActiveTexture(GL_TEXTURE0);
    gl_BindTexture(GL_TEXTURE_2D, g_atlas ? g_atlas : g_atlas_dummy);
    gl_BindVertexArray(g_flat_vao);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_flat_vbo);
    gl_BufferSubData(GL_ARRAY_BUFFER, 0,
                     (GLsizeiptr_)(n_total * sizeof(FlatVtx)), g_flat_cpu);
    if (n_tri > 0) gl_DrawArrays(GL_TRIANGLES, 0, (GLsizei)n_tri);
    if (n_total > n_tri)
        gl_DrawArrays(GL_LINES, (GLint)n_tri, (GLsizei)(n_total - n_tri));
    gl_BindVertexArray(0);
    gl_UseProgram(0);
}

// =====================================================================
// BLOQUE 12b — Shader compilation + 4 shaders (flat/mesh/stars/text)
// =====================================================================

static GLuint shader_compile(GLenum type, const char* src) {
    GLuint s = gl_CreateShader(type);
    gl_ShaderSource(s, 1, &src, NULL);
    gl_CompileShader(s);
    GLint ok = 0;
    gl_GetShaderiv(s, GL_COMPILE_STATUS, &ok);
    if (!ok) {
        char log[1024]; GLsizei n = 0;
        gl_GetShaderInfoLog(s, sizeof(log), &n, log);
        LOG("shader_compile FAIL (type=%u): %.500s", (uint32_t)type, log);
        gl_DeleteShader(s);
        return 0;
    }
    return s;
}

static GLuint shader_program(const char* vs, const char* fs) {
    GLuint v = shader_compile(GL_VERTEX_SHADER, vs);
    if (!v) return 0;
    GLuint f = shader_compile(GL_FRAGMENT_SHADER, fs);
    if (!f) { gl_DeleteShader(v); return 0; }
    GLuint p = gl_CreateProgram();
    gl_AttachShader(p, v);
    gl_AttachShader(p, f);
    gl_LinkProgram(p);
    GLint ok = 0;
    gl_GetProgramiv(p, GL_LINK_STATUS, &ok);
    gl_DeleteShader(v);
    gl_DeleteShader(f);
    if (!ok) {
        char log[1024]; GLsizei n = 0;
        gl_GetProgramInfoLog(p, sizeof(log), &n, log);
        LOG("shader_program link FAIL: %.500s", log);
        gl_DeleteProgram(p);
        return 0;
    }
    return p;
}

static void render_init_shaders(void) {
    const char* vs_flat =
        "#version 330 core\n"
        "layout(location=0) in vec3 a_pos;\n"
        "layout(location=1) in vec4 a_color;\n"
        "layout(location=2) in vec2 a_uv;\n"
        "layout(location=3) in vec4 a_extra;\n"
        "uniform mat4 u_vp;\n"
        "out vec4 v_color; out vec2 v_uv; out vec4 v_extra;\n"
        "void main() {\n"
        "  gl_Position = u_vp * vec4(a_pos, 1.0);\n"
        "  v_color = a_color; v_uv = a_uv; v_extra = a_extra;\n"
        "}\n";
    const char* fs_flat =
        "#version 330 core\n"
        "in vec4 v_color; in vec2 v_uv; in vec4 v_extra;\n"
        "uniform sampler2D u_tex; uniform float u_tiempo;\n"
        "out vec4 f_color;\n"
        "void main() {\n"
        "  vec4 t = texture(u_tex, v_uv);\n"
        "  vec3 col = v_color.rgb * t.rgb;\n"
        "  col += v_extra.y * vec3(1.0, 0.7, 0.4) * 0.4;\n"
        "  float a = t.a * v_color.a;\n"
        "  if (a < 0.02) discard;\n"
        "  f_color = vec4(col, a);\n"
        "}\n";
    const char* vs_mesh =
        "#version 330 core\n"
        "layout(location=0) in vec3 a_pos;\n"
        "layout(location=1) in vec3 a_nrm;\n"
        "layout(location=2) in vec2 a_uv;\n"
        "uniform mat4 u_vp; uniform mat4 u_model;\n"
        "out vec3 v_nrm; out vec3 v_world;\n"
        "void main() {\n"
        "  vec4 w = u_model * vec4(a_pos, 1.0);\n"
        "  gl_Position = u_vp * w;\n"
        "  v_nrm = mat3(u_model) * a_nrm;\n"
        "  v_world = w.xyz;\n"
        "}\n";
    const char* fs_mesh =
        "#version 330 core\n"
        "in vec3 v_nrm; in vec3 v_world;\n"
        "uniform vec3 u_color;\n"
        "out vec4 f_color;\n"
        "void main() {\n"
        "  vec3 n = normalize(v_nrm);\n"
        "  vec3 L = normalize(vec3(0.30, 1.00, 0.50));\n"
        "  float d = max(dot(n, L), 0.0);\n"
        "  f_color = vec4(u_color * (0.35 + d * 0.65), 1.0);\n"
        "}\n";
    const char* vs_stars =
        "#version 330 core\n"
        "layout(location=0) in vec2 a_corner;\n"
        "layout(location=1) in vec4 a_pos_size;\n"
        "layout(location=2) in float a_bright;\n"
        "uniform mat4 u_vp; uniform float u_screen_h;\n"
        "out float v_bright; out vec3 v_world;\n"
        "void main() {\n"
        "  vec4 clip = u_vp * vec4(a_pos_size.xyz, 1.0);\n"
        "  float px = 2.0 / u_screen_h;\n"
        "  clip.xy += a_corner * a_pos_size.w * px * clip.w;\n"
        "  gl_Position = clip;\n"
        "  v_bright = a_bright; v_world = a_pos_size.xyz;\n"
        "}\n";
    const char* fs_stars =
        "#version 330 core\n"
        "in float v_bright; in vec3 v_world;\n"
        "uniform vec3 u_cam_pos;\n"
        "uniform float u_fade_start; uniform float u_fade_end;\n"
        "out vec4 f_color;\n"
        "void main() {\n"
        "  float dist = distance(v_world, u_cam_pos);\n"
        "  float fade = 1.0 - smoothstep(u_fade_start, u_fade_end, dist);\n"
        "  float a = v_bright * fade;\n"
        "  if (a < 0.02) discard;\n"
        "  f_color = vec4(1.0, 0.95, 0.85, a);\n"
        "}\n";
    const char* vs_text =
        "#version 330 core\n"
        "layout(location=0) in vec2 a_pos;\n"
        "layout(location=1) in vec2 a_uv;\n"
        "layout(location=2) in vec4 a_color;\n"
        "uniform mat4 u_vp;\n"
        "out vec2 v_uv; out vec4 v_color;\n"
        "void main(){ gl_Position=u_vp*vec4(a_pos,0,1); v_uv=a_uv; v_color=a_color; }\n";
    const char* fs_text =
        "#version 330 core\n"
        "in vec2 v_uv; in vec4 v_color;\n"
        "uniform sampler2D u_tex;\n"
        "out vec4 f_color;\n"
        "void main(){ float a = texture(u_tex,v_uv).a; f_color=vec4(v_color.rgb, v_color.a*a); }\n";

    g_shader_flat  = shader_program(vs_flat,  fs_flat);
    g_shader_mesh  = shader_program(vs_mesh,  fs_mesh);
    g_shader_stars = shader_program(vs_stars, fs_stars);
    g_shader_text  = shader_program(vs_text,  fs_text);

    if (g_shader_flat) {
        g_flat_u_vp   = gl_GetUniformLocation(g_shader_flat, "u_vp");
        g_flat_u_tex  = gl_GetUniformLocation(g_shader_flat, "u_tex");
        g_flat_u_time = gl_GetUniformLocation(g_shader_flat, "u_tiempo");
    }
    if (g_shader_mesh) {
        g_mesh_u_vp    = gl_GetUniformLocation(g_shader_mesh, "u_vp");
        g_mesh_u_model = gl_GetUniformLocation(g_shader_mesh, "u_model");
        g_mesh_u_color = gl_GetUniformLocation(g_shader_mesh, "u_color");
    }
    if (g_shader_stars) {
        g_star_u_vp         = gl_GetUniformLocation(g_shader_stars, "u_vp");
        g_star_u_screen_h   = gl_GetUniformLocation(g_shader_stars, "u_screen_h");
        g_star_u_cam_pos    = gl_GetUniformLocation(g_shader_stars, "u_cam_pos");
        g_star_u_fade_start = gl_GetUniformLocation(g_shader_stars, "u_fade_start");
        g_star_u_fade_end   = gl_GetUniformLocation(g_shader_stars, "u_fade_end");
    }
    if (g_shader_text) {
        g_text_u_vp  = gl_GetUniformLocation(g_shader_text, "u_vp");
        g_text_u_tex = gl_GetUniformLocation(g_shader_text, "u_tex");
    }

    uint8_t blanco[4] = {255, 255, 255, 255};
    gl_GenTextures(1, &g_atlas_dummy);
    gl_BindTexture(GL_TEXTURE_2D, g_atlas_dummy);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    gl_TexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, 1, 1, 0, GL_RGBA,
                  GL_UNSIGNED_BYTE, blanco);
    LOG("render_init_shaders: flat=%u mesh=%u stars=%u text=%u",
        g_shader_flat, g_shader_mesh, g_shader_stars, g_shader_text);
}

static void render_destroy_shaders(void) {
    if (g_shader_flat  && gl_DeleteProgram)  gl_DeleteProgram(g_shader_flat);
    if (g_shader_mesh  && gl_DeleteProgram)  gl_DeleteProgram(g_shader_mesh);
    if (g_shader_stars && gl_DeleteProgram)  gl_DeleteProgram(g_shader_stars);
    if (g_shader_text  && gl_DeleteProgram)  gl_DeleteProgram(g_shader_text);
    if (g_atlas_dummy  && gl_DeleteTextures) gl_DeleteTextures(1, &g_atlas_dummy);
    g_shader_flat = g_shader_mesh = g_shader_stars = g_shader_text = 0;
    g_atlas_dummy = 0;
}

// =====================================================================
// BLOQUE 12c — Font atlas (GDI -> GL texture) + text shader + text_flush
// =====================================================================

static int font_build(const char* face, int size) {
    if (g_font.inited) return 1;
    HDC dc = CreateCompatibleDC(NULL);
    if (!dc) return 0;
    HFONT font = CreateFontA(size, 0, 0, 0, FW_NORMAL, 0, 0, 0,
        ANSI_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS,
        ANTIALIASED_QUALITY, DEFAULT_PITCH | FF_DONTCARE, face);
    if (!font) { DeleteDC(dc); return 0; }
    SelectObject(dc, font);
    float total = 4.f;
    for (int i = 0; i < 96; i++) {
        char c[2] = { (char)(i + 32), 0 };
        SIZE sz = { 0 };
        GetTextExtentPoint32A(dc, c, 1, &sz);
        g_font.char_w[i] = (float)(sz.cx + 2);
        total += g_font.char_w[i];
    }
    g_font.cell_h = size + 4;
    g_font.width  = (int)total;
    g_font.height = g_font.cell_h;
    float off = 2.f;
    for (int i = 0; i < 96; i++) {
        g_font.char_u0[i] = off / (float)g_font.width;
        g_font.char_u1[i] = (off + g_font.char_w[i]) / (float)g_font.width;
        off += g_font.char_w[i];
    }
    BITMAPINFO bmi = {0};
    bmi.bmiHeader.biSize        = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth       = g_font.width;
    bmi.bmiHeader.biHeight      = -g_font.height;
    bmi.bmiHeader.biPlanes      = 1;
    bmi.bmiHeader.biBitCount    = 32;
    bmi.bmiHeader.biCompression = BI_RGB;
    void* bits = NULL;
    HBITMAP bmp = CreateDIBSection(dc, &bmi, DIB_RGB_COLORS, &bits, NULL, 0);
    if (!bmp || !bits) { DeleteObject(font); DeleteDC(dc); return 0; }
    SelectObject(dc, bmp);
    RECT rc = { 0, 0, g_font.width, g_font.height };
    HBRUSH bg = CreateSolidBrush(RGB(0, 0, 0));
    FillRect(dc, &rc, bg);
    DeleteObject(bg);
    SetBkMode(dc, TRANSPARENT);
    SetTextColor(dc, RGB(255, 255, 255));
    float off2 = 2.f;
    for (int i = 0; i < 96; i++) {
        char c[2] = { (char)(i + 32), 0 };
        RECT r = { (int)off2, 0, (int)(off2 + g_font.char_w[i]),
                    g_font.height };
        DrawTextA(dc, c, 1, &r, DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_NOCLIP);
        off2 += g_font.char_w[i];
    }
    unsigned char* src  = (unsigned char*)bits;
    size_t total_px = (size_t)g_font.width * g_font.height;
    unsigned char* rgba = (unsigned char*)xmalloc(total_px * 4);
    for (size_t i = 0; i < total_px; i++) {
        unsigned char g = src[i * 4];
        rgba[i*4+0] = 255; rgba[i*4+1] = 255; rgba[i*4+2] = 255;
        rgba[i*4+3] = g;
    }
    gl_GenTextures(1, &g_font.tex);
    gl_BindTexture(GL_TEXTURE_2D, g_font.tex);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    gl_TexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    gl_TexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, g_font.width, g_font.height,
                   0, GL_RGBA, GL_UNSIGNED_BYTE, rgba);
    xfree(rgba);
    DeleteObject(bmp);
    DeleteObject(font);
    DeleteDC(dc);
    g_font.inited = 1;
    LOG("font_build: %dx%d", g_font.width, g_font.height);
    return 1;
}

static void font_destroy(void) {
    if (g_font.tex && gl_DeleteTextures) gl_DeleteTextures(1, &g_font.tex);
    memset(&g_font, 0, sizeof(g_font));
}

static int text_shader_init(void) {
    gl_GenVertexArrays(1, &g_text_vao);
    gl_GenBuffers(1, &g_text_vbo);
    gl_BindVertexArray(g_text_vao);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_text_vbo);
    gl_VertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 8 * sizeof(float), (void*)0);
    gl_EnableVertexAttribArray(0);
    gl_VertexAttribPointer(1, 2, GL_FLOAT, GL_FALSE, 8 * sizeof(float),
                            (void*)(2 * sizeof(float)));
    gl_EnableVertexAttribArray(1);
    gl_VertexAttribPointer(2, 4, GL_FLOAT, GL_FALSE, 8 * sizeof(float),
                            (void*)(4 * sizeof(float)));
    gl_EnableVertexAttribArray(2);
    gl_BindVertexArray(0);
    return 1;
}

static void text_flush(int vw, int vh) {
    if (g_hud_chars_n == 0 || !g_font.inited || !g_shader_text) {
        g_hud_chars_n = 0;
        return;
    }
    size_t n_verts  = (size_t)g_hud_chars_n * 6;
    size_t buf_size = n_verts * 8 * sizeof(float);
    static float* buf = NULL;
    static size_t buf_cap = 0;
    if (buf_size > buf_cap) {
        float* nb = (float*)xrealloc(buf, buf_size);
        if (!nb) { g_hud_chars_n = 0; return; }
        buf = nb;
        buf_cap = buf_size;
    }
    Mat4 ortho;
    mat4_ortho(ortho, 0.f, (float)vw, (float)vh, 0.f, -1.f, 1.f);
    size_t idx = 0;
    for (uint32_t i = 0; i < g_hud_chars_n; i++) {
        HUDChar* hc = &g_hud_chars[i];
        int g = hc->glyph;
        if (g < 0 || g >= 96) g = '?' - 32;
        float sc = hc->size / (float)g_font.cell_h;
        float w  = g_font.char_w[g] * sc;
        float h  = hc->size;
        float x  = hc->x, y = hc->y;
        float u0 = g_font.char_u0[g];
        float u1 = g_font.char_u1[g];
        V4 c = hc->color;
        #define V(px,py,uu,vv) do { \
            buf[idx++]=(px); buf[idx++]=(py); buf[idx++]=(uu); buf[idx++]=(vv); \
            buf[idx++]=c.x; buf[idx++]=c.y; buf[idx++]=c.z; buf[idx++]=c.w; \
        } while(0)
        V(x, y, u0, 0.f);
        V(x + w, y, u1, 0.f);
        V(x + w, y + h, u1, 1.f);
        V(x, y, u0, 0.f);
        V(x + w, y + h, u1, 1.f);
        V(x, y + h, u0, 1.f);
        #undef V
    }
    if (buf_size > g_text_vbo_cap) {
        gl_BindBuffer(GL_ARRAY_BUFFER, g_text_vbo);
        gl_BufferData(GL_ARRAY_BUFFER, (GLsizeiptr_)buf_size, NULL,
                       GL_DYNAMIC_DRAW);
        g_text_vbo_cap = buf_size;
    }
    gl_Disable(GL_CULL_FACE);
    gl_Disable(GL_DEPTH_TEST);
    gl_Enable(GL_BLEND);
    gl_BlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    gl_UseProgram(g_shader_text);
    gl_UniformMatrix4fv(g_text_u_vp, 1, GL_FALSE, ortho);
    gl_Uniform1i(g_text_u_tex, 0);
    gl_ActiveTexture(GL_TEXTURE0);
    gl_BindTexture(GL_TEXTURE_2D, g_font.tex);
    gl_BindVertexArray(g_text_vao);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_text_vbo);
    gl_BufferSubData(GL_ARRAY_BUFFER, 0, (GLsizeiptr_)buf_size, buf);
    gl_DrawArrays(GL_TRIANGLES, 0, (GLsizei)n_verts);
    gl_BindVertexArray(0);
    gl_UseProgram(0);
    gl_Enable(GL_DEPTH_TEST);
    g_hud_chars_n = 0;
}
// =====================================================================
// BLOQUE 13a — Mesh system (upload, box, sphere, cylinder)
// =====================================================================

static int mesh_upload(const float* verts, int n_verts) {
    if (g_mesh_count >= MAX_MESHES) return -1;
    if (n_verts <= 0 || !verts) return -1;
    int slot = g_mesh_count++;
    Mesh* m = &g_meshes[slot];
    gl_GenVertexArrays(1, &m->vao);
    gl_GenBuffers(1, &m->vbo);
    gl_BindVertexArray(m->vao);
    gl_BindBuffer(GL_ARRAY_BUFFER, m->vbo);
    gl_BufferData(GL_ARRAY_BUFFER,
                   (GLsizeiptr_)(sizeof(float) * 8 * n_verts),
                   verts, GL_STATIC_DRAW);
    gl_VertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE,
                            (GLsizei)(8 * sizeof(float)), (void*)0);
    gl_EnableVertexAttribArray(0);
    gl_VertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE,
                            (GLsizei)(8 * sizeof(float)),
                            (void*)(3 * sizeof(float)));
    gl_EnableVertexAttribArray(1);
    gl_VertexAttribPointer(2, 2, GL_FLOAT, GL_FALSE,
                            (GLsizei)(8 * sizeof(float)),
                            (void*)(6 * sizeof(float)));
    gl_EnableVertexAttribArray(2);
    gl_BindVertexArray(0);
    m->vertex_count = n_verts;
    m->used = 1;
    return slot;
}

static void mesh_destroy_all(void) {
    for (int i = 0; i < g_mesh_count; i++) {
        Mesh* m = &g_meshes[i];
        if (m->vbo && gl_DeleteBuffers)      gl_DeleteBuffers(1, &m->vbo);
        if (m->vao && gl_DeleteVertexArrays) gl_DeleteVertexArrays(1, &m->vao);
    }
    memset(g_meshes, 0, sizeof(g_meshes));
    g_mesh_count = 0;
}

static V3 sphere_point_cb(float th, float ph, float seed) {
    float n = sinf(th * 3 + ph * 2 + seed * 0.7f) * 0.5f
            + sinf(th * 5 - ph * 3 + seed * 1.3f) * 0.3f
            + sinf(th * 2 + ph * 4 + seed * 2.1f) * 0.4f;
    float r = 1.f + n * 0.32f;
    r = powf(r, 1.35f);
    return v3(sinf(th) * cosf(ph) * r, cosf(th) * r * 0.9f + 0.1f,
              sinf(th) * sinf(ph) * r);
}

static V3 alien_point_cb(float th, float ph, float seed) {
    float n = sinf(th * 2.1f + ph * 1.7f + seed * 3.f) * 0.6f
            + sinf(th * 4.3f - ph * 2.9f + seed * 5.f) * 0.45f
            + sinf(th * 1.3f + ph * 5.1f + seed * 7.f) * 0.35f;
    n += sinf(th * 5 + seed) * cosf(ph * 4 + seed * 1.3f) * 0.35f;
    float r = 1.f + n * 0.55f;
    return v3(sinf(th) * cosf(ph) * r, cosf(th) * r * 0.85f,
              sinf(th) * sinf(ph) * r);
}

static V3 sphere_unit_cb(float th, float ph, float seed) {
    (void)seed;
    return v3(sinf(th) * cosf(ph), cosf(th), sinf(th) * sinf(ph));
}

static int mesh_from_sphere(PointFn fn, int rings, int segs, float seed) {
    if (g_mesh_count >= MAX_MESHES) return -1;
    int quads = rings * segs, n_verts = quads * 6;
    float* buf = (float*)xmalloc((size_t)n_verts * 8 * sizeof(float));
    if (!buf) return -1;
    int n = 0;
    #define EMIT(px,py,pz,nx,ny,nz,uu,vv) do { \
        buf[n++]=(px);buf[n++]=(py);buf[n++]=(pz); \
        buf[n++]=(nx);buf[n++]=(ny);buf[n++]=(nz); \
        buf[n++]=(uu);buf[n++]=(vv); \
    } while(0)
    for (int i = 0; i < rings; i++) {
        float th0 = PI_F * (float)i / rings;
        float th1 = PI_F * (float)(i + 1) / rings;
        for (int j = 0; j < segs; j++) {
            float ph0 = TAU_F * (float)j / segs;
            float ph1 = TAU_F * (float)(j + 1) / segs;
            V3 p00 = fn(th0, ph0, seed), p01 = fn(th0, ph1, seed);
            V3 p10 = fn(th1, ph0, seed), p11 = fn(th1, ph1, seed);
            V3 n00 = v3norm(p00), n01 = v3norm(p01);
            V3 n10 = v3norm(p10), n11 = v3norm(p11);
            float u0 = (float)j / segs, u1 = (float)(j + 1) / segs;
            float v0 = (float)i / rings, v1 = (float)(i + 1) / rings;
            EMIT(p00.x,p00.y,p00.z, n00.x,n00.y,n00.z, u0,v0);
            EMIT(p10.x,p10.y,p10.z, n10.x,n10.y,n10.z, u0,v1);
            EMIT(p11.x,p11.y,p11.z, n11.x,n11.y,n11.z, u1,v1);
            EMIT(p00.x,p00.y,p00.z, n00.x,n00.y,n00.z, u0,v0);
            EMIT(p11.x,p11.y,p11.z, n11.x,n11.y,n11.z, u1,v1);
            EMIT(p01.x,p01.y,p01.z, n01.x,n01.y,n01.z, u1,v0);
        }
    }
    #undef EMIT
    int slot = mesh_upload(buf, n_verts);
    xfree(buf);
    return slot;
}

static int mesh_unit_box(void) {
    if (g_mesh_count >= MAX_MESHES) return -1;
    float v[36 * 8];
    int n = 0;
    #define V(px,py,pz,nx,ny,nz,uu,vv) do { \
        v[n++]=(px);v[n++]=(py);v[n++]=(pz); \
        v[n++]=(nx);v[n++]=(ny);v[n++]=(nz); \
        v[n++]=(uu);v[n++]=(vv); \
    } while(0)
    V( 0.5f,-0.5f,-0.5f, 1,0,0, 0,0); V( 0.5f,-0.5f, 0.5f, 1,0,0, 1,0); V( 0.5f, 0.5f, 0.5f, 1,0,0, 1,1);
    V( 0.5f,-0.5f,-0.5f, 1,0,0, 0,0); V( 0.5f, 0.5f, 0.5f, 1,0,0, 1,1); V( 0.5f, 0.5f,-0.5f, 1,0,0, 0,1);
    V(-0.5f,-0.5f, 0.5f,-1,0,0, 0,0); V(-0.5f,-0.5f,-0.5f,-1,0,0, 1,0); V(-0.5f, 0.5f,-0.5f,-1,0,0, 1,1);
    V(-0.5f,-0.5f, 0.5f,-1,0,0, 0,0); V(-0.5f, 0.5f,-0.5f,-1,0,0, 1,1); V(-0.5f, 0.5f, 0.5f,-1,0,0, 0,1);
    V(-0.5f, 0.5f,-0.5f,0,1,0, 0,0); V( 0.5f, 0.5f,-0.5f,0,1,0, 1,0); V( 0.5f, 0.5f, 0.5f,0,1,0, 1,1);
    V(-0.5f, 0.5f,-0.5f,0,1,0, 0,0); V( 0.5f, 0.5f, 0.5f,0,1,0, 1,1); V(-0.5f, 0.5f, 0.5f,0,1,0, 0,1);
    V(-0.5f,-0.5f, 0.5f,0,-1,0,0,0); V( 0.5f,-0.5f, 0.5f,0,-1,0,1,0); V( 0.5f,-0.5f,-0.5f,0,-1,0,1,1);
    V(-0.5f,-0.5f, 0.5f,0,-1,0,0,0); V( 0.5f,-0.5f,-0.5f,0,-1,0,1,1); V(-0.5f,-0.5f,-0.5f,0,-1,0,0,1);
    V(-0.5f,-0.5f, 0.5f,0,0,1, 0,0); V( 0.5f,-0.5f, 0.5f,0,0,1, 1,0); V( 0.5f, 0.5f, 0.5f,0,0,1, 1,1);
    V(-0.5f,-0.5f, 0.5f,0,0,1, 0,0); V( 0.5f, 0.5f, 0.5f,0,0,1, 1,1); V(-0.5f, 0.5f, 0.5f,0,0,1, 0,1);
    V( 0.5f,-0.5f,-0.5f,0,0,-1,0,0); V(-0.5f,-0.5f,-0.5f,0,0,-1,1,0); V(-0.5f, 0.5f,-0.5f,0,0,-1,1,1);
    V( 0.5f,-0.5f,-0.5f,0,0,-1,0,0); V(-0.5f, 0.5f,-0.5f,0,0,-1,1,1); V( 0.5f, 0.5f,-0.5f,0,0,-1,0,1);
    #undef V
    return mesh_upload(v, 36);
}

static int mesh_unit_cylinder(int segs) {
    if (g_mesh_count >= MAX_MESHES) return -1;
    int n_verts = segs * 12;
    float* buf = (float*)xcalloc((size_t)n_verts * 8, sizeof(float));
    if (!buf) return -1;
    int n = 0;
    #define EMIT(px,py,pz,nx,ny,nz,uu,vv) do { \
        buf[n++]=(px);buf[n++]=(py);buf[n++]=(pz); \
        buf[n++]=(nx);buf[n++]=(ny);buf[n++]=(nz); \
        buf[n++]=(uu);buf[n++]=(vv); \
    } while(0)
    for (int j = 0; j < segs; j++) {
        float a0 = TAU_F * (float)j / segs, a1 = TAU_F * (float)(j + 1) / segs;
        V3 n0 = v3(cosf(a0), 0, sinf(a0)), n1 = v3(cosf(a1), 0, sinf(a1));
        V3 p00 = v3(n0.x, -0.5f, n0.z), p01 = v3(n1.x, -0.5f, n1.z);
        V3 p10 = v3(n0.x,  0.5f, n0.z), p11 = v3(n1.x,  0.5f, n1.z);
        float u0 = (float)j / segs, u1 = (float)(j + 1) / segs;
        EMIT(p00.x,p00.y,p00.z, n0.x,0,n0.z, u0,0);
        EMIT(p10.x,p10.y,p10.z, n0.x,0,n0.z, u0,1);
        EMIT(p11.x,p11.y,p11.z, n1.x,0,n1.z, u1,1);
        EMIT(p00.x,p00.y,p00.z, n0.x,0,n0.z, u0,0);
        EMIT(p11.x,p11.y,p11.z, n1.x,0,n1.z, u1,1);
        EMIT(p01.x,p01.y,p01.z, n1.x,0,n1.z, u1,0);
    }
    for (int j = 0; j < segs; j++) {
        float a0 = TAU_F * (float)j / segs, a1 = TAU_F * (float)(j + 1) / segs;
        EMIT(0,0.5f,0, 0,1,0, 0.5f,0.5f);
        EMIT(cosf(a1),0.5f,sinf(a1), 0,1,0, 1,0);
        EMIT(cosf(a0),0.5f,sinf(a0), 0,1,0, 0,0);
    }
    for (int j = 0; j < segs; j++) {
        float a0 = TAU_F * (float)j / segs, a1 = TAU_F * (float)(j + 1) / segs;
        EMIT(0,-0.5f,0, 0,-1,0, 0.5f,0.5f);
        EMIT(cosf(a0),-0.5f,sinf(a0), 0,-1,0, 0,0);
        EMIT(cosf(a1),-0.5f,sinf(a1), 0,-1,0, 1,0);
    }
    #undef EMIT
    int slot = mesh_upload(buf, n_verts);
    xfree(buf);
    return slot;
}

static void meshes_init(void) {
    if (g_mesh_unit_box_id >= 0) return;
    g_mesh_unit_box_id    = mesh_unit_box();
    g_mesh_unit_sphere_id = mesh_from_sphere(sphere_unit_cb, 8, 12, 0.f);
    g_mesh_unit_cyl_id    = mesh_unit_cylinder(12);
    for (int i = 0; i < NUM_AST_SHAPES; i++)
        g_mesh_ast[i] = mesh_from_sphere(sphere_point_cb, 7, 11, (float)(i + 3));
    for (int i = 0; i < NUM_ALI_SHAPES; i++)
        g_mesh_ali[i] = mesh_from_sphere(alien_point_cb, 6, 10, (float)(i * 7 + 1));
    for (int i = 0; i < NUM_PICK_SHAPES; i++)
        g_mesh_pick[i] = mesh_from_sphere(sphere_unit_cb, 4, 8, (float)i);
    LOG("meshes_init: ast=%d ali=%d pick=%d box=%d sph=%d cyl=%d total=%d",
        NUM_AST_SHAPES, NUM_ALI_SHAPES, NUM_PICK_SHAPES,
        g_mesh_unit_box_id, g_mesh_unit_sphere_id, g_mesh_unit_cyl_id,
        g_mesh_count);
}

static void meshes_shutdown(void) {
    mesh_destroy_all();
    for (int i = 0; i < NUM_AST_SHAPES;  i++) g_mesh_ast[i]  = -1;
    for (int i = 0; i < NUM_ALI_SHAPES;  i++) g_mesh_ali[i]  = -1;
    for (int i = 0; i < NUM_PICK_SHAPES; i++) g_mesh_pick[i] = -1;
    g_mesh_unit_box_id    = -1;
    g_mesh_unit_sphere_id = -1;
    g_mesh_unit_cyl_id    = -1;
}

// =====================================================================
// BLOQUE 13b — Starfield instanced (1500 estrellas, fade por distancia)
// =====================================================================

static void starfield_generate(void) {
    float L = STARFIELD_RANGE;
    g_star_count = STARFIELD_MAX;
    for (int i = 0; i < g_star_count; i++) {
        StarInstance* s = &g_stars[i];
        s->pos = v3(xrng_range(-L * 0.5f, L * 0.5f),
                    xrng_range(-L * 0.5f, L * 0.5f),
                    xrng_range(-L * 0.5f, L * 0.5f));
        s->size = xrng_range(1.0f, 2.8f);
        float b = xrng_f();
        s->brightness = 0.2f + b * b * 0.8f;
        s->_pad[0] = s->_pad[1] = s->_pad[2] = 0.f;
    }
}

static int starfield_init(void) {
    if (g_star_vao) return 1;
    if (!gl_DrawArraysInstanced || !gl_VertexAttribDivisor) {
        LOG("starfield: no instancing support");
        return 0;
    }
    gl_GenVertexArrays(1, &g_star_vao);
    gl_BindVertexArray(g_star_vao);
    static const float corners[] = { -1.f, -1.f,  1.f, -1.f,
                                       -1.f,  1.f,  1.f,  1.f };
    gl_GenBuffers(1, &g_star_vbo_quad);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_star_vbo_quad);
    gl_BufferData(GL_ARRAY_BUFFER, sizeof(corners), corners, GL_STATIC_DRAW);
    gl_VertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 2 * sizeof(float), (void*)0);
    gl_EnableVertexAttribArray(0);
    gl_VertexAttribDivisor(0, 0);
    gl_GenBuffers(1, &g_star_vbo_inst);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_star_vbo_inst);
    gl_BufferData(GL_ARRAY_BUFFER, STARFIELD_MAX * sizeof(StarInstance),
                  NULL, GL_DYNAMIC_DRAW);
    gl_VertexAttribPointer(1, 4, GL_FLOAT, GL_FALSE, sizeof(StarInstance),
                            (void*)0);
    gl_EnableVertexAttribArray(1);
    gl_VertexAttribDivisor(1, 1);
    gl_VertexAttribPointer(2, 1, GL_FLOAT, GL_FALSE, sizeof(StarInstance),
                            (void*)(4 * sizeof(float)));
    gl_EnableVertexAttribArray(2);
    gl_VertexAttribDivisor(2, 1);
    gl_BindVertexArray(0);
    starfield_generate();
    LOG("starfield_init: %d stars", g_star_count);
    return 1;
}

static void starfield_render(Camera* cam, int vh) {
    if (g_star_count == 0 || !g_shader_stars) return;
    float L = STARFIELD_RANGE;
    for (int i = 0; i < g_star_count; i++) {
        StarInstance* s = &g_stars[i];
        V3 rel = v3sub(s->pos, cam->pos);
        rel.x = rel.x - L * roundf(rel.x / L);
        rel.y = rel.y - L * roundf(rel.y / L);
        rel.z = rel.z - L * roundf(rel.z / L);
        g_star_gpu[i].pos        = v3add(cam->pos, rel);
        g_star_gpu[i].size       = s->size;
        g_star_gpu[i].brightness = s->brightness;
        g_star_gpu[i]._pad[0] = g_star_gpu[i]._pad[1] = g_star_gpu[i]._pad[2] = 0.f;
    }
    gl_UseProgram(g_shader_stars);
    gl_UniformMatrix4fv(g_star_u_vp, 1, GL_FALSE, cam->vp);
    gl_Uniform1f(g_star_u_screen_h, (float)vh);
    gl_Uniform3f(g_star_u_cam_pos, cam->pos.x, cam->pos.y, cam->pos.z);
    gl_Uniform1f(g_star_u_fade_start, STARFIELD_FADE_START);
    gl_Uniform1f(g_star_u_fade_end,   STARFIELD_FADE_END);
    gl_BindVertexArray(g_star_vao);
    gl_BindBuffer(GL_ARRAY_BUFFER, g_star_vbo_inst);
    gl_BufferSubData(GL_ARRAY_BUFFER, 0, g_star_count * sizeof(StarInstance),
                     g_star_gpu);
    gl_Enable(GL_BLEND);
    gl_BlendFunc(GL_SRC_ALPHA, GL_ONE);
    gl_Disable(GL_DEPTH_TEST);
    gl_DrawArraysInstanced(GL_TRIANGLE_STRIP, 0, 4, g_star_count);
    gl_Enable(GL_DEPTH_TEST);
    gl_BlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    gl_BindVertexArray(0);
    gl_UseProgram(0);
}

static void starfield_shutdown(void) {
    if (g_star_vbo_inst && gl_DeleteBuffers)      gl_DeleteBuffers(1, &g_star_vbo_inst);
    if (g_star_vbo_quad && gl_DeleteBuffers)      gl_DeleteBuffers(1, &g_star_vbo_quad);
    if (g_star_vao      && gl_DeleteVertexArrays) gl_DeleteVertexArrays(1, &g_star_vao);
    g_star_vao = 0; g_star_vbo_quad = 0; g_star_vbo_inst = 0;
    g_star_count = 0;
}

// =====================================================================
// BLOQUE 13c — Rcmd frame reset + publish + collide hooks
// =====================================================================

static void rcmd_pool_frame_reset(void) {
    for (uint32_t i = 0; i < g_rp.cmd_cap; i++) {
        g_rp.cmds[i].kind  = RCK_NONE;
        g_rp.cmds[i].flags = 0;
        g_rp.free_cmds[i]  = g_rp.cmd_cap - 1 - i;
    }
    g_rp.free_count    = g_rp.cmd_cap;
    g_rp.cmd_count     = 0;
    g_rp.visible_count = 0;
    memset(g_entity_rcmds, 0xFF, sizeof(g_entity_rcmds));
    memset(g_entity_rcmd_count, 0, sizeof(g_entity_rcmd_count));
}

/* ── Visual proxies: circular = billboard con tile/disco;
   non-circular = pure vertex meshes (box/cyl). No recursive extrusion. ── */

static int thing_visual_is_circular(uint32_t type) {
    switch (type) {
        case ET_ASTEROID: case ET_PICKUP: case ET_MATERIAL:
        case ET_STAR: case ET_FIELD: case ET_ANOMALY:
        case ET_ALIEN: case ET_DRONE: case ET_CAPSULE:
            return 1;
        default: return 0;
    }
}

static V4 thing_visual_color(uint32_t slot, const Thing* t) {
    V4 col = v4(0.7f, 0.7f, 0.9f, 0.9f);
    switch (t->type) {
        case ET_ASTEROID:  col = v4(0.6f, 0.5f, 0.4f, 1.f); break;
        case ET_ALIEN:     col = v4(0.9f, 0.3f, 0.3f, 1.f); break;
        case ET_PIRATE:    col = v4(1.0f, 0.5f, 0.2f, 1.f); break;
        case ET_SHIP: {
            ShipDataExt* ext = ship_ext(slot);
            if (ext && ext->node_count > 0) {
                const ShipNode* n0 = &ext->nodes[0];
                V4 mc = mat_get(n0->material_id)->color;
                float dmg = (n0->structural_hp > 0.f) ? 1.f - n0->current_hp / n0->structural_hp : 0.f;
                col = v4(mc.x * (1.f - dmg * 0.5f), mc.y * (1.f - dmg * 0.7f), mc.z * (1.f - dmg * 0.9f), 1.f);
            } else col = v4(0.4f, 0.7f, 1.0f, 1.f);
            break;
        }
        case ET_DRONE:     col = v4(0.4f, 1.0f, 0.6f, 1.f); break;
        case ET_PICKUP:    col = v4(1.0f, 0.9f, 0.3f, 1.f); break;
        case ET_CREW:      col = v4(0.9f, 0.9f, 0.9f, 1.f); break;
        case ET_LAUNCHER:  col = v4(0.3f, 1.0f, 0.3f, 1.f); break;
        case ET_LANZADERA: col = v4(0.3f, 0.8f, 0.8f, 1.f); break;
        case ET_STAR:      col = v4(1.0f, 0.9f, 0.4f, 1.f); break;
        case ET_FIELD:     col = v4(0.4f, 0.4f, 1.0f, 0.45f); break;
        case ET_ANOMALY:   col = v4(0.8f, 0.3f, 1.0f, 0.7f); break;
        case ET_CAPSULE:   col = v4(0.85f, 0.85f, 0.95f, 1.f); break;
        default: break;
    }
    return col;
}

/* Cuerpo circular: billboard con tile de material (asteroide/pickup/material)
   o disco procedural del slot 0 (anomalias, campos, estrellas...). Nunca UV
   0..1 del atlas entero (era el origen de los cuadrados flotantes). */
static void thing_publish_circular(uint32_t slot, const Thing* t,
                                    uint16_t mid, V4 col) {
    float R = t->radius;
    (void)slot;
    if (R < 0.05f) R = 0.05f;
    float u0, v0, u1, v1;
    u0 = 0.f; v0 = 0.f; u1 = 1.f; v1 = 1.f;
    if (mid > 0 || t->type == ET_ASTEROID || t->type == ET_PICKUP) {
        material_tile_uv(mid, PROC_BRUTO, material_default_state(mid),
                         &g_matpool.props[mid < MATERIAL_COUNT ? mid : 0],
                         t->seed & 0xFF, &u0, &v0, &u1, &v1);
    } else {
        atlas_disc_uv(&u0, &v0, &u1, &v1);
    }
    uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 100);
    if (rc != UINT32_MAX) {
        rcmd_billboard_tex(rc, t->pos, R * 2.f, u0, v0, u1, v1, 0, 0, 0, 0);
        rcmd_color(rc, col);
        rcmd_visible(rc);
    }
}

/* Pure vertex proxies: unit box / cylinder scaled to radius. */
static void thing_publish_vertex_proxy(uint32_t slot, const Thing* t, V4 col) {
    float R = t->radius;
    if (R < 0.05f) R = 0.05f;
    int use_cyl = (t->type == ET_DRONE || t->type == ET_LAUNCHER);
    int mesh_id = use_cyl ? g_mesh_unit_cyl_id : g_mesh_unit_box_id;
    if (mesh_id < 0) mesh_id = g_mesh_unit_box_id;
    if (mesh_id < 0) {
        /* fallback billboard 1:1 radius */
        uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 100);
        if (rc != UINT32_MAX) {
            rcmd_billboard(rc, t->pos, R * 2.f);
            rcmd_color(rc, col);
            rcmd_visible(rc);
        }
        return;
    }
    Mat4 m;
    float sx, sy, sz;
    if (t->type == ET_CREW) {
        sx = R * 0.7f; sy = R * 1.6f; sz = R * 0.7f; /* capsule-ish box */
    } else if (use_cyl) {
        sx = R; sy = R * 1.2f; sz = R;
    } else if (t->type == ET_PIRATE) {
        sx = R * 1.2f; sy = R * 0.7f; sz = R * 1.4f;
    } else {
        sx = sy = sz = R;
    }
    mesh_xform_yaw(m, t->pos, t->rot, sx, sy, sz);
    uint32_t rc = rcmd_alloc(RCK_MESH, 100);
    if (rc == UINT32_MAX) return;
    rcmd_mesh(rc, (GLuint)mesh_id, m, col);
    rcmd_visible(rc);
    (void)slot;
}

static void thing_publish_impl(uint32_t slot, const Thing* t) {
    if (!t) return;
    if (t->flags & ENT_FLAG_NO_PUBLISH) return;

    /* Ships keep specialized exterior publisher when available */
    if (t->type == ET_SHIP) {
        ShipDataExt* ext = ship_ext(slot);
        if (ext && ext->node_count > 0) {
            /* exterior path is invoked elsewhere; still emit a soft core marker */
            V4 col = thing_visual_color(slot, t);
            uint32_t rc = rcmd_alloc(RCK_BILLBOARD3D, 90);
            if (rc != UINT32_MAX) {
                rcmd_billboard(rc, t->pos, t->radius * 0.35f);
                rcmd_color(rc, v4(col.x, col.y, col.z, 0.35f));
                rcmd_visible(rc);
            }
            return;
        }
    }

    uint16_t mid = 0;
    if (t->type == ET_ASTEROID)      mid = (uint16_t)ENT_I(t, 0);
    else if (t->type == ET_PICKUP)   mid = (uint16_t)ENT_I(t, 1);
    else if (t->type == ET_MATERIAL) mid = (uint16_t)ENT_I(t, 0);

    V4 col = thing_visual_color(slot, t);

    if (thing_visual_is_circular(t->type))
        thing_publish_circular(slot, t, mid, col);
    else
        thing_publish_vertex_proxy(slot, t, col);
}

static void thing_collide_impl(uint32_t a, uint32_t b, V3 n, float depth,
                                 float rel_vel) {
    (void)rel_vel;
    Thing* ta = entity_get(a);
    Thing* tb = entity_get(b);
    if (!ta || !tb) return;
    if ((ta->flags & ENT_FLAG_STATIC) && (tb->flags & ENT_FLAG_STATIC)) return;
    float total_mass = ta->mass + tb->mass;
    if (total_mass <= 0.001f) return;
    float push_a = tb->mass / total_mass;
    float push_b = ta->mass / total_mass;
    ta->pos = v3add(ta->pos, v3mul(n, -depth * push_a));
    tb->pos = v3add(tb->pos, v3mul(n,  depth * push_b));
    V3 rel = v3sub(ta->vel, tb->vel);
    float vn = v3dot(rel, n);
    if (vn < 0.f) {
        float j = -(1.5f * vn) / (1.f / ta->mass + 1.f / tb->mass);
        ta->vel = v3add(ta->vel, v3mul(n,  j / ta->mass));
        tb->vel = v3sub(tb->vel, v3mul(n,  j / tb->mass));
    }
}

// =====================================================================
// BLOQUE 13d — Render 3D (flat + mesh) y orquestador por frame
// =====================================================================

// =====================================================================
// BLOQUE 25 — UNIFIED CELL PUBLISH
//
// Every visible volume in the game world (ship hull node, greeble,
// interior floor/wall/ceiling, launcher arm, lanzadera tower) is emitted
// through cell_publish_box() / cell_publish_box_oriented(). All of them
// share g_mesh_unit_box_id / g_mesh_unit_cyl_id / g_mesh_unit_sphere_id
// and the same Rcmd RCK_MESH pipeline as body_publish (crew bodies) and
// thing_publish_impl (world billboards for far LOD).
// =====================================================================

static uint32_t cell_publish_mesh(uint32_t slot_hint, int32_t layer,
                                    GLuint mesh_id, const Mat4 xform,
                                    V4 color) {
    if (!mesh_id) return UINT32_MAX;
if ((int)mesh_id < 0 || (int)mesh_id >= g_mesh_count) return UINT32_MAX;
    uint32_t rc = rcmd_alloc(RCK_MESH, layer);
    if (rc == UINT32_MAX) return UINT32_MAX;
    Rcmd* c = &g_rp.cmds[rc];
    c->mesh = mesh_id;
    
    memcpy(c->xform, xform, sizeof(Mat4));
    c->color  = color;
    c->pick_id  = -1;
    c->pick_arg = -1;
    c->extra[0] = (float)(slot_hint & 0xFFFF);
    rcmd_visible(rc);
    return rc;
}

static uint32_t cell_publish_box(uint32_t slot_hint, int32_t layer,
                                  V3 center_world, V3 half_ext,
                                  V4 color, GLuint mesh_override) {
    GLuint mesh = mesh_override ? mesh_override
                                 : (GLuint)g_mesh_unit_box_id;
    if ((int)mesh < 0) return UINT32_MAX;
    Mat4 m;
    mat4_identity(m);
    m[0]  = half_ext.x * 2.f;
    m[5]  = half_ext.y * 2.f;
    m[10] = half_ext.z * 2.f;
    m[12] = center_world.x;
    m[13] = center_world.y;
    m[14] = center_world.z;
    return cell_publish_mesh(slot_hint, layer, mesh, m, color);
}

// Oriented variant — used so hull/greebles rotate with the ship.
// ship_rot is the column-major rotation matrix cached in ShipDataExt.
static uint32_t cell_publish_box_oriented(uint32_t slot_hint, int32_t layer,
                                            V3 center_world, V3 half_ext,
                                            V4 color, const Mat4 ship_rot) {
    GLuint mesh = (GLuint)g_mesh_unit_box_id;
    if ((int)mesh < 0) return UINT32_MAX;
    Mat4 m;
    const float sx = half_ext.x * 2.f;
    const float sy = half_ext.y * 2.f;
    const float sz = half_ext.z * 2.f;
    m[0]  = ship_rot[0] * sx; m[1]  = ship_rot[1] * sx; m[2]  = ship_rot[2] * sx; m[3]  = 0.f;
    m[4]  = ship_rot[4] * sy; m[5]  = ship_rot[5] * sy; m[6]  = ship_rot[6] * sy; m[7]  = 0.f;
    m[8]  = ship_rot[8] * sz; m[9]  = ship_rot[9] * sz; m[10] = ship_rot[10]* sz; m[11] = 0.f;
    m[12] = center_world.x;
    m[13] = center_world.y;
    m[14] = center_world.z;
    m[15] = 1.f;
    return cell_publish_mesh(slot_hint, layer, mesh, m, color);
}

// Deterministic greebles from n->seed — no global xrng, no shared cache,
// stable frame-to-frame. Replaces the visual function of the (dead-code)
// ship_build_external_morphology cache path without touching it.
static void ship_greeble_publish(uint32_t ship_slot, const ShipNode* n,
                                   V3 node_world, const Mat4 ship_rot) {
    if (!n) return;
    const int n_blocks = 2 + (int)(hash_u32(n->seed ^ 0xAAu) & 3u); // 2..5
    const V4 base = mat_get(n->material_id)->color;
    uint32_t h = n->seed;
    for (int k = 0; k < n_blocks; k++) {
        h = hash_u32(h + (uint32_t)k * 0x9E3779B1u);
        int face = (int)(h % 6u);
        if (face == PORT_PY || face == PORT_NY) continue; // skip up/down
        V3 nrm = port_normal_local(face);
        float fx = ((h >>  4) & 0xFF) / 255.f;
        float fy = ((h >> 12) & 0xFF) / 255.f;
        float fz = ((h >> 20) & 0xFF) / 255.f;
        V3 lo = v3(
            nrm.x * (n->half_ext.x + 0.05f + fx * 0.15f),
            nrm.y * (n->half_ext.y + 0.05f + fy * 0.15f),
            nrm.z * (n->half_ext.z + 0.05f + fz * 0.15f));
        // rotate local offset by ship_rot then translate
        V3 wo = v3(
            ship_rot[0]*lo.x + ship_rot[4]*lo.y + ship_rot[8] *lo.z,
            ship_rot[1]*lo.x + ship_rot[5]*lo.y + ship_rot[9] *lo.z,
            ship_rot[2]*lo.x + ship_rot[6]*lo.y + ship_rot[10]*lo.z);
        V3 world = v3add(node_world, wo);
        V3 scale = v3(
            n->half_ext.x * (0.22f + fx * 0.30f),
            n->half_ext.y * (0.22f + fy * 0.30f),
            n->half_ext.z * (0.22f + fz * 0.30f));
        float tint = 0.70f + 0.40f * fx;
        V4 col = v4(base.x * tint, base.y * tint, base.z * tint, 1.f);
        cell_publish_box_oriented(ship_slot, LAYER_NEAR, world, scale, col,
                                    ship_rot);
        g_dbg_cells_exterior++;
    }
}

// =====================================================================
// EXTERIOR — one hull box per node + deterministic greebles.
// skip_walkable_hull=1 when the player is inside: don't draw a solid hull
// box over the room they are standing in (the interior publisher draws that
// volume).
// =====================================================================
static void ship_publish_exterior(uint32_t ship_slot, int skip_walkable_hull) {
    ShipDataExt* ext = ship_ext(ship_slot);
    Thing* ship = entity_get(ship_slot);
    if (!ext || !ship) return;
    ship_cache_transform_if_dirty(ship_slot, ship);
    const Mat4* R = &ext->ship_rot_cache;

    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (skip_walkable_hull && (n->props_mask & NODE_PROP_WALKABLE))
            continue;

        V4 base = mat_get(n->material_id)->color;
        float dmg = 0.f;
        if (n->structural_hp > 0.f)
            dmg = 1.f - n->current_hp / n->structural_hp;
        V4 hull_c = v4(base.x * (1.f - dmg * 0.40f),
                        base.y * (1.f - dmg * 0.65f),
                        base.z * (1.f - dmg * 0.85f), 1.f);
        if (n->props_mask & NODE_PROP_BREACHED)
            hull_c = v4(0.40f, 0.06f, 0.04f, 1.f);

        V3 cw = v3add(ship->pos, ext->node_cached_offset[i]);
        cell_publish_box_oriented(ship_slot, LAYER_NEAR, cw, n->half_ext,
                                    hull_c, *R);
        g_dbg_cells_exterior++;

        // Only greeble non-walkable nodes (interior nodes get their own
        // trim from ship_publish_interior and we don't want double
        // geometry when the player is inside).
        if (!skip_walkable_hull)
            ship_greeble_publish(ship_slot, n, cw, *R);
    }
}

// =====================================================================
// INTERIOR — floor / ceiling / 4 walls per walkable node.
// Doorways are cut automatically by checking port_peer_node for a
// walkable neighbour. Damage and breached state tint the surfaces.
// =====================================================================
static void ship_publish_interior(uint32_t ship_slot) {
    ShipDataExt* ext = ship_ext(ship_slot);
    Thing* ship = entity_get(ship_slot);
    if (!ext || !ship) return;
    ship_cache_transform_if_dirty(ship_slot, ship);

    const float T     = 0.04f;   // surface thickness
    const float INSET = 0.02f;   // inset to avoid z-fighting with node AABB

    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;

        V4 base = mat_get(n->material_id)->color;
        float dmg = (float)n->damage_visual * 0.20f;
        V4 floor_c = v4(base.x * (1.f - dmg * 0.30f),
                         base.y * (1.f - dmg * 0.55f),
                         base.z * (1.f - dmg * 0.80f), 1.f);
        V4 wall_c  = v4(base.x * 0.70f, base.y * 0.70f, base.z * 0.70f, 1.f);
        V4 ceil_c  = v4(base.x * 0.42f, base.y * 0.42f, base.z * 0.42f, 1.f);
        V4 trim_c  = v4(base.x * 0.95f, base.y * 0.85f, base.z * 0.55f, 1.f);
        if (n->props_mask & NODE_PROP_BREACHED) {
            floor_c = v4(0.55f, 0.10f, 0.05f, 1.f);
            wall_c  = v4(0.32f, 0.06f, 0.03f, 1.f);
            ceil_c  = v4(0.18f, 0.04f, 0.02f, 1.f);
            trim_c  = v4(0.80f, 0.20f, 0.10f, 1.f);
        }

        V3 cw = v3add(ship->pos, ext->node_cached_offset[i]);
        V3 he = n->half_ext;

        // ---- FLOOR ----
        {
            V3 fc = v3(cw.x, cw.y - he.y + T * 0.5f + INSET, cw.z);
            V3 fh = v3(he.x - INSET, T * 0.5f, he.z - INSET);
            cell_publish_box(ship_slot, LAYER_NEAR, fc, fh, floor_c, 0);
            g_dbg_cells_interior++;
        }
        // ---- CEILING ----
        {
            V3 cc = v3(cw.x, cw.y + he.y - T * 0.5f - INSET, cw.z);
            V3 ch = v3(he.x - INSET, T * 0.5f, he.z - INSET);
            cell_publish_box(ship_slot, LAYER_NEAR, cc, ch, ceil_c, 0);
            g_dbg_cells_interior++;
        }
        // ---- 4 WALLS (skip where a walkable peer exists) ----
        for (int port = 0; port < 6; port++) {
            if (port == PORT_PY || port == PORT_NY) continue;
            int peer = n->port_peer_node[port];
            int connected = 0;
            if (peer >= 0 && peer < ext->node_count) {
                if (ext->nodes[peer].props_mask & NODE_PROP_WALKABLE)
                    connected = 1;
            }
            if (connected) {
                // thin doorway frame (does not occlude the doorway)
                V3 dn = port_normal_local(port);
                V3 dc, dh;
                if (port == PORT_PX || port == PORT_NX) {
                    float sx = (port == PORT_PX) ? 1.f : -1.f;
                    dc = v3(cw.x + sx * (he.x - 0.005f), cw.y, cw.z);
                    dh = v3(0.02f, he.y * 0.95f, he.z * 0.05f);
                } else {
                    float sz = (port == PORT_PZ) ? 1.f : -1.f;
                    dc = v3(cw.x, cw.y, cw.z + sz * (he.z - 0.005f));
                    dh = v3(he.x * 0.05f, he.y * 0.95f, 0.02f);
                }
                (void)dn;
                cell_publish_box(ship_slot, LAYER_NEAR, dc, dh, trim_c, 0);
                g_dbg_cells_interior++;
                continue;
            }
            V3 wc, wh;
            if (port == PORT_PX || port == PORT_NX) {
                float sx = (port == PORT_PX) ? 1.f : -1.f;
                wc = v3(cw.x + sx * (he.x - T * 0.5f - INSET), cw.y, cw.z);
                wh = v3(T * 0.5f, he.y - INSET, he.z - INSET);
            } else {
                float sz = (port == PORT_PZ) ? 1.f : -1.f;
                wc = v3(cw.x, cw.y, cw.z + sz * (he.z - T * 0.5f - INSET));
                wh = v3(he.x - INSET, he.y - INSET, T * 0.5f);
            }
            cell_publish_box(ship_slot, LAYER_NEAR, wc, wh, wall_c, 0);
            g_dbg_cells_interior++;
        }
        // ---- Corner trim (visual polish, low cost) ----
        for (int corner = 0; corner < 4; corner++) {
            float sx = (corner & 1) ? -1.f : 1.f;
            float sz = (corner & 2) ? -1.f : 1.f;
            V3 cc = v3(cw.x + sx * (he.x - 0.08f), cw.y, cw.z + sz * (he.z - 0.08f));
            V3 ch = v3(0.06f, he.y - INSET, 0.06f);
            cell_publish_box(ship_slot, LAYER_NEAR, cc, ch, trim_c, 0);
            g_dbg_cells_interior++;
        }
    }
}

// =====================================================================
// WORLD — same box primitive for launchers and lanzaderas. Uses the
// cylinder mesh for the lanzadera tower to prove the shared mesh set
// works for the world generator too.
// =====================================================================
static void world_structure_publish(uint32_t slot, const Thing* t) {
    if (!t) return;
    if (t->flags & ENT_FLAG_MARKED_DEAD) return;

    switch (t->type) {
        case ET_LAUNCHER: {
            V4 hub_c = v4(0.35f, 0.90f, 0.50f, 1.f);
            V4 arm_c = v4(0.28f, 0.70f, 0.40f, 1.f);
            cell_publish_box(slot, LAYER_NEAR, t->pos,
                              v3(t->radius, t->radius * 0.55f, t->radius),
                              hub_c, 0);
            g_dbg_cells_world++;
            for (int a = 0; a < 4; a++) {
                float ang = TAU_F * (float)a / 4.f + t->rot;
                V3 off = v3(cosf(ang) * t->radius * 1.45f, 0.f,
                             sinf(ang) * t->radius * 1.45f);
                V3 ap = v3add(t->pos, off);
                V3 ah = v3(t->radius * 1.10f, t->radius * 0.18f,
                            t->radius * 0.18f);
                cell_publish_box(slot, LAYER_NEAR, ap, ah, arm_c, 0);
                g_dbg_cells_world++;
            }
            break;
        }
        case ET_LANZADERA: {
            V4 base_c = v4(0.30f, 0.80f, 0.80f, 1.f);
            V4 tower_c = v4(0.45f, 0.90f, 0.90f, 1.f);
            cell_publish_box(slot, LAYER_NEAR, t->pos,
                              v3(t->radius, t->radius * 0.7f, t->radius),
                              base_c, 0);
            g_dbg_cells_world++;
            V3 tower_pos = v3add(t->pos, v3(0.f, t->radius * 1.8f, 0.f));
            V3 tower_h   = v3(t->radius * 0.35f, t->radius * 1.4f,
                               t->radius * 0.35f);
            cell_publish_box(slot, LAYER_NEAR, tower_pos, tower_h, tower_c,
                              (GLuint)g_mesh_unit_cyl_id);
            g_dbg_cells_world++;
            break;
        }
        default: break;
    }
}

static void render_frame_3d(void) {
    if (!g_shader_flat) return;
    V3 cam_pos = g_game.cam.pos;

    g_flat_n = 0;
    for (uint32_t i = 0; i < g_rp.visible_count; i++) {
        uint32_t idx = g_rp.visible[i];
        if (idx >= g_rp.cmd_cap) continue;
        Rcmd* c = &g_rp.cmds[idx];
        if (c->kind != RCK_BILLBOARD3D) continue;
        stream_billboard_tex(c->p0, c->w, c->color, cam_pos,
                             c->uv[0], c->uv[1], c->uv[2], c->uv[3],
                             c->extra[0], c->extra[1], c->extra[2], c->extra[3]);
    }
    if (g_flat_n > 0) {
        stream_flush(g_game.cam.vp, g_flat_n, g_flat_n);
        g_flat_n = 0;
    }

    if (g_shader_mesh) {
        gl_UseProgram(g_shader_mesh);
        gl_UniformMatrix4fv(g_mesh_u_vp, 1, GL_FALSE, g_game.cam.vp);
        for (uint32_t i = 0; i < g_rp.visible_count; i++) {
            uint32_t idx = g_rp.visible[i];
            if (idx >= g_rp.cmd_cap) continue;
            Rcmd* c = &g_rp.cmds[idx];
            if (c->kind != RCK_MESH) continue;
            if ((uint32_t)c->mesh >= (uint32_t)g_mesh_count) continue;
            Mesh* m = &g_meshes[c->mesh];
            if (!m->used) continue;
            gl_UniformMatrix4fv(g_mesh_u_model, 1, GL_FALSE, c->xform);
            gl_Uniform3f(g_mesh_u_color, c->color.x, c->color.y, c->color.z);
            gl_BindVertexArray(m->vao);
            gl_DrawArrays(GL_TRIANGLES, 0, m->vertex_count);
        }
        gl_BindVertexArray(0);
        gl_UseProgram(0);
    }
}

static void render_orchestrate(float dt) {
    tick_camera(dt);
    audio_set_listener(g_game.cam.pos, g_game.cam.target, g_game.cam.up);
    g_frame_atlas++;

    g_dbg_cells_interior = 0;
    g_dbg_cells_exterior = 0;
    g_dbg_cells_world    = 0;

    gl_ClearColor(0.02f, 0.02f, 0.05f, 1.f);
    gl_Clear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    gl_Viewport(0, 0, g_win_w, g_win_h);
    starfield_render(&g_game.cam, g_win_h);

    rcmd_pool_frame_reset();

    emit_world_3d();
    if (g_debug_paths)    debug_emit_3d();
    if (g_b7_scan_active) scan_emit_3d();

    render_frame_3d();

    hud_render();

    if (g_flat_n > 0) {
        gl_Disable(GL_DEPTH_TEST);
        Mat4 ortho;
        mat4_ortho(ortho, 0.f, (float)g_win_w, (float)g_win_h, 0.f, -1.f, 1.f);
        stream_flush(ortho, g_flat_n, g_flat_n);
        gl_Enable(GL_DEPTH_TEST);
        g_flat_n = 0;
    }

    text_flush(g_win_w, g_win_h);
    win_swap();

    if (g_dbg_cells_verbose && (g_game.frame % 300) == 0) {
        LOG("cells: interior=%u exterior=%u world=%u",
            g_dbg_cells_interior, g_dbg_cells_exterior, g_dbg_cells_world);
    }
}

