// =====================================================================
// BLOQUE 14b — Menús: draw item / generic / market / render
// =====================================================================

static void menu_draw_item(float x, float y, float w, float h,
                            const char* label, int selected, int enabled,
                            int pick_id, int pick_arg) {
    V4 bg = selected ? v4(0.25f, 0.35f, 0.55f, 0.85f)
                     : v4(0.10f, 0.12f, 0.18f, 0.75f);
    V4 fg = enabled  ? v4(1.f, 1.f, 1.f, 1.f)
                     : v4(0.5f, 0.5f, 0.5f, 1.f);
    V4 accent = selected ? v4(1.f, 0.9f, 0.4f, 1.f)
                         : v4(0.3f, 0.3f, 0.3f, 1.f);
    stream_quad(x, y, w, h, bg);
    stream_quad(x, y, 3.f, h, accent);
    hud_text_push(x + 12.f, y + (h - 16.f) * 0.5f, 16.f, fg, label);
    if (pick_id >= 0)
        pick_push(pick_id, pick_arg, 100, x, y, w, h);
}

static void menu_draw_generic(const MenuSpec* spec) {
    if (!spec || spec->count == 0) return;
    float cx = (float)g_win_w * 0.5f;
    float top = (float)g_win_h * 0.20f;
    float w = 400.f;
    float item_h = 40.f;
    float pad = 6.f;
    float total_h = (float)spec->count * (item_h + pad) + 60.f;
    float x = cx - w * 0.5f;
    float y = top;
    stream_quad(x - 10.f, y - 60.f, w + 20.f, total_h + 20.f,
                 v4(0.05f, 0.05f, 0.08f, 0.85f));
    hud_text_push(cx - 60.f, y - 40.f, 22.f,
                   v4(1.f, 0.9f, 0.4f, 1.f), spec->title);
    y += 10.f;
    for (int i = 0; i < spec->count; i++) {
        const MenuItemSpec* it = &spec->items[i];
        int selected = (i == g_menu_sel);
        menu_draw_item(x, y, w, item_h, it->label, selected, it->enabled,
                       100 + i, i);
        y += item_h + pad;
    }
    hud_text_push(cx - 100.f, y + 10.f, 12.f,
                   v4(0.7f, 0.7f, 0.7f, 1.f),
                   "Up/Down: select   Enter: confirm   Esc: cancel");
}

static void menu_draw_market(void) {
    uint32_t launcher_slot = g_game.current_market_slot;
    int kind = (int)g_game.current_market_kind;
    float cx = (float)g_win_w * 0.5f;
    float w = 720.f;
    float x = cx - w * 0.5f;
    float y = (float)g_win_h * 0.18f;
    stream_quad(x - 20.f, y - 60.f, w + 40.f, 520.f,
                 v4(0.05f, 0.05f, 0.08f, 0.9f));
    hud_text_push(cx - 60.f, y - 40.f, 22.f,
                   v4(1.f, 0.9f, 0.4f, 1.f),
                   kind == 0 ? "LAUNCHER" : "LANZADERA");
    hud_text_push(x + 10.f,  y + 10.f, 14.f, v4(0.7f,0.7f,0.7f,1.f), "ITEM");
    hud_text_push(x + 220.f, y + 10.f, 14.f, v4(0.7f,0.7f,0.7f,1.f), "QTY");
    hud_text_push(x + 290.f, y + 10.f, 14.f, v4(0.7f,0.7f,0.7f,1.f), "PRICE");
    hud_text_push(x + 410.f, y + 10.f, 14.f, v4(0.7f,0.7f,0.7f,1.f), "TTL");
    y += 34.f;
    int drawn = 0;
    if (!entity_alive(launcher_slot)) {
        hud_text_push(x + 10.f, y, 16.f, v4(1,0.5f,0.5f,1.f), "NO LAUNCHER");
        return;
    }
    // FIX: validar tipo antes del cast (evita leer la ShipData con layout distinto)
    Thing* lt = entity_get(launcher_slot);
    if (!lt) return;
    if (kind == 0 && lt->type != ET_LAUNCHER) {
        hud_text_push(x + 10.f, y, 16.f, v4(1,0.5f,0.5f,1.f), "NOT A LAUNCHER");
        return;
    }
    if (kind == 1 && lt->type != ET_LANZADERA) {
        hud_text_push(x + 10.f, y, 16.f, v4(1,0.5f,0.5f,1.f), "NOT A LANZADERA");
        return;
    }
    if (kind == 0) {
        LauncherData* ld = (LauncherData*)entity_side_ptr(launcher_slot);
        if (!ld) return;
        int rows_max = (int)((float)g_win_h * 0.25f / 42.f);
        if (rows_max < 2) rows_max = 2;
        for (uint32_t i = 0; i < ld->offer_count && drawn < rows_max; i++) {
            LauncherOffer* off = &ld->offers[i];
            int selected = (drawn == g_menu_sel);
            float row_y = y + drawn * 42.f;
            V4 bg = selected ? v4(0.25f,0.35f,0.55f,0.8f)
                             : v4(0.10f,0.12f,0.18f,0.6f);
            stream_quad(x, row_y, w, 38.f, bg);
            const Material* m = mat_get(off->mat_id);
            char buf[64];
            snprintf(buf, sizeof(buf), "%-12s", m ? m->name : "?");
            hud_text_push(x + 10.f, row_y + 10.f, 15.f,
                           m ? m->color : v4(1,1,1,1), buf);
            snprintf(buf, sizeof(buf), "%u", off->qty);
            hud_text_push(x + 220.f, row_y + 10.f, 15.f, v4(1,1,1,1), buf);
            snprintf(buf, sizeof(buf), "%u cr", off->price);
            hud_text_push(x + 290.f, row_y + 10.f, 15.f,
                           v4(1.f,0.9f,0.4f,1.f), buf);
            snprintf(buf, sizeof(buf), "%.0fs", off->ttl);
            hud_text_push(x + 410.f, row_y + 10.f, 15.f,
                           v4(0.7f,0.7f,0.7f,1.f), buf);
            pick_push(200 + i, (int)i, 100, x, row_y, w, 38.f);
            drawn++;
        }
    } else {
        LanzaderaData* lzd = (LanzaderaData*)entity_side_ptr(launcher_slot);
        if (!lzd) return;
        int rows_max = (int)((float)g_win_h * 0.25f / 42.f);
        if (rows_max < 2) rows_max = 2;
        for (uint32_t i = 0; i < lzd->offer_count && drawn < rows_max; i++) {
            LanzaderaOffer* off = &lzd->offers[i];
            int selected = (drawn == g_menu_sel);
            float row_y = y + drawn * 42.f;
            V4 bg = selected ? v4(0.25f,0.35f,0.55f,0.8f)
                             : v4(0.10f,0.12f,0.18f,0.6f);
            stream_quad(x, row_y, w, 38.f, bg);
            const Material* m = mat_get(off->mat_id);
            char buf[64];
            snprintf(buf, sizeof(buf), "%-12s", m ? m->name : "?");
            hud_text_push(x + 10.f, row_y + 10.f, 15.f,
                           m ? m->color : v4(1,1,1,1), buf);
            snprintf(buf, sizeof(buf), "%u", off->qty);
            hud_text_push(x + 220.f, row_y + 10.f, 15.f, v4(1,1,1,1), buf);
            snprintf(buf, sizeof(buf), "%u cr", off->price);
            hud_text_push(x + 290.f, row_y + 10.f, 15.f,
                           v4(1.f,0.9f,0.4f,1.f), buf);
            snprintf(buf, sizeof(buf), "%.0fs", off->ttl);
            hud_text_push(x + 410.f, row_y + 10.f, 15.f,
                           v4(0.7f,0.7f,0.7f,1.f), buf);
            pick_push(200 + i, (int)i, 100, x, row_y, w, 38.f);
            drawn++;
        }
    }
    hud_text_push(cx - 140.f, y + 8 * 42.f + 20.f, 13.f,
                   v4(0.7f,0.7f,0.7f,1.f),
                   "Left/Right: Buy/Sell toggle   Enter: trade   Esc: back");
}

static void menu_render(void) {
    if (g_menu_kind == MENU_NONE) return;
    if (g_ctx != CTX_MENU && g_ctx != CTX_PAUSED && g_ctx != CTX_DOCKED) return;
    if (g_menu_kind == MENU_DOCK_MARKET) { menu_draw_market(); return; }
    const MenuSpec* spec = menu_spec_for(g_menu_kind);
    if (spec) menu_draw_generic(spec);
}

// =====================================================================
// BLOQUE 14c — Mixing UI render (overlay 800x560)
// =====================================================================

static void mixing_ui_render(void) {
    if (!g_mixing_ui.active) return;
    if (g_ctx != CTX_MIX) return;
    float cx = (float)g_win_w * 0.5f;
    float cy = (float)g_win_h * 0.5f;
    float w = 800.f, h = 560.f;
    float x = cx - w * 0.5f, y = cy - h * 0.5f;
    float alpha = g_mixing_ui.fade_alpha;
    stream_quad(x, y, w, h, v4(0.05f, 0.05f, 0.10f, 0.92f * alpha));
    stream_quad(x, y, w, 3.f, v4(0.4f, 0.8f, 0.5f, alpha));
    hud_text_push(x + 20.f, y + 16.f, 22.f,
                   v4(1.f, 0.9f, 0.4f, alpha), "MIXING");
    static const char* mode_names[] = {
        "STRUCTURAL", "COMPUTATIONAL", "ORGANIC", "ENERGETIC",
        "MEDICAL", "TOOL", "DRONE"
    };
    int mode = g_mixing_ui.mode;
    if (mode < 0 || mode >= MIX_MODE_COUNT) mode = 0;
    float mode_x = x + 20.f, mode_y = y + 60.f;
    for (int i = 0; i < MIX_MODE_COUNT; i++) {
        V4 col = (i == mode) ? v4(0.4f, 0.8f, 0.5f, alpha)
                              : v4(0.2f, 0.2f, 0.2f, alpha * 0.7f);
        stream_quad(mode_x, mode_y, 100.f, 28.f, col);
        hud_text_push(mode_x + 8.f, mode_y + 6.f, 12.f,
                       v4(1,1,1,alpha), mode_names[i]);
        pick_push(300 + i, i, 100, mode_x, mode_y, 100.f, 28.f);
        mode_x += 108.f;
    }
    float slots_y = y + 120.f;
    hud_text_push(x + 20.f, slots_y - 20.f, 14.f,
                   v4(0.7f,0.7f,0.7f,alpha),
                   "INPUTS (click inventory to select)");
    for (int i = 0; i < 4; i++) {
        float sx = x + 20.f + (float)i * 190.f;
        stream_quad(sx, slots_y, 180.f, 100.f,
                     v4(0.10f,0.12f,0.18f,alpha * 0.7f));
        char buf[64];
        if (i < g_mixing_ui.input_count && g_mixing_ui.input_seeds[i] != 0) {
            ThingBlueprint* bp = bp_cache_get(g_mixing_ui.input_seeds[i]);
            if (bp) {
                snprintf(buf, sizeof(buf), "K=%d T=%u",
                          (int)bp->kind, bp->tier);
                hud_text_push(sx + 10.f, slots_y + 10.f, 12.f,
                               v4(1,1,1,alpha), buf);
                snprintf(buf, sizeof(buf), "M=%.1f HP=%.0f",
                          bp->mass, bp->hp);
                hud_text_push(sx + 10.f, slots_y + 40.f, 12.f,
                               v4(0.8f,0.8f,0.8f,alpha), buf);
            }
        } else {
            hud_text_push(sx + 10.f, slots_y + 40.f, 12.f,
                           v4(0.5f,0.5f,0.5f,alpha), "empty");
        }
        pick_push(310 + i, i, 100, sx, slots_y, 180.f, 100.f);
    }
    float inv_x = x + 20.f;
    float inv_y = y + 260.f;
    hud_text_push(inv_x, inv_y - 20.f, 14.f,
                   v4(0.7f,0.7f,0.7f,alpha), "INVENTORY");
    for (int i = 0; i < g_player.inventory.count && i < 12; i++) {
        InventoryItem* it = &g_player.inventory.items[i];
        float row_y = inv_y + (float)i * 20.f;
        V4 col = v4(0.7f,0.7f,0.7f,alpha);
        char buf[64];
        snprintf(buf, sizeof(buf), "K=%d T=%u q%u",
                  (int)it->bp.kind, it->bp.tier, it->qty);
        hud_text_push(inv_x, row_y, 12.f, col, buf);
        pick_push(400 + i, i, 100, inv_x, row_y, 400.f, 18.f);
    }
    float prev_y = y + h - 100.f;
    hud_text_push(x + 20.f, prev_y, 16.f,
                   v4(0.9f, 1.f, 0.7f, alpha),
                   g_mixing_ui.preview[0]
                     ? g_mixing_ui.preview
                     : "Select inputs, then PROMOTE");
    hud_text_push(cx - 200.f, y + h - 40.f, 12.f,
                   v4(0.6f,0.6f,0.6f,alpha),
                   "1-7: mode   Esc: close   Enter: promote   I: inspect");
}

