// =====================================================================
// BLOQUE 14f — Editor de patrones (modal)
// =====================================================================

static void editor_open(void) {
    g_edit_mat   = 0;
    g_edit_proc  = 0;
    g_edit_est   = 0;
    g_edit_param = 0;
    input_set_context(CTX_MODAL);
    notice_push("EDITOR OPEN");
}

static void editor_apply(void) {
    if (g_edit_mat < 0 || g_edit_mat >= MATERIAL_COUNT) return;
    if (g_edit_proc < 0 || g_edit_proc >= PROC_TOTAL) return;
    if (g_edit_est < 0 || g_edit_est >= EST_TOTAL) return;
    ParametrosPatron* pp = &g_params[g_edit_mat][g_edit_proc][g_edit_est];
    pp->amplitud = clampf(pp->amplitud + 0.05f, 0.f, 1.f);
    notice_push("PARAM APPLIED");
    g_matpool_initialized = 0;
    materials_init();
    atlas_shutdown();
    atlas_init();
}

static void editor_remove(void) {
    if (g_edit_mat < 0 || g_edit_mat >= MATERIAL_COUNT) return;
    if (g_edit_proc < 0 || g_edit_proc >= PROC_TOTAL) return;
    if (g_edit_est < 0 || g_edit_est >= EST_TOTAL) return;
    ParametrosPatron* pp = &g_params[g_edit_mat][g_edit_proc][g_edit_est];
    pp->amplitud = 0.3f;
    notice_push("PARAM RESET");
    g_matpool_initialized = 0;
    materials_init();
    atlas_shutdown();
    atlas_init();
}

static void editor_render(void) {
    if (g_ctx != CTX_MODAL) return;
    float cx = (float)g_win_w * 0.5f;
    float w = 600.f;
    float x = cx - w * 0.5f;
    float y = (float)g_win_h * 0.5f - 200.f;
    stream_quad(x, y, w, 400.f, v4(0.05f, 0.05f, 0.08f, 0.94f));
    hud_text_push(x + 20.f, y + 16.f, 22.f,
                   v4(1.f, 0.9f, 0.4f, 1.f), "PATTERN EDITOR");
    char buf[128];
    const Material* m = mat_get((uint16_t)g_edit_mat);
    snprintf(buf, sizeof(buf), "Material: %d  %s",
              g_edit_mat, m ? m->name : "?");
    hud_text_push(x + 20.f, y + 60.f, 14.f, v4(1,1,1,1), buf);
    snprintf(buf, sizeof(buf), "Process: %d   State: %d",
              g_edit_proc, g_edit_est);
    hud_text_push(x + 20.f, y + 80.f, 14.f, v4(1,1,1,1), buf);
    if (g_edit_mat < MATERIAL_COUNT &&
        g_edit_proc < PROC_TOTAL &&
        g_edit_est < EST_TOTAL) {
        ParametrosPatron* pp = &g_params[g_edit_mat][g_edit_proc][g_edit_est];
        snprintf(buf, sizeof(buf), "F1=%d F2=%d Amp=%.2f Warp=%d Emi=%.2f",
                  pp->frecuencia1, pp->frecuencia2, pp->amplitud,
                  pp->distorsion, pp->emision);
        hud_text_push(x + 20.f, y + 120.f, 13.f,
                       v4(0.9f,0.9f,0.9f,1.f), buf);
    }
    hud_text_push(x + 20.f, y + 360.f, 12.f,
                   v4(0.7f,0.7f,0.7f,1.f),
                   "Enter: apply   Backspace: reset   Esc: close");
}

