// =====================================================================
// BLOQUE 16b — Audio system (miniaudio) — completo
// =====================================================================
static void audio_gen_sound(uint32_t id, int16_t* buf, uint32_t n_frames) {
    uint32_t s = id * 0x9E3779B1u;
    float dur = (float)n_frames / AUDIO_SAMPLE_RATE;
    for (uint32_t i = 0; i < n_frames; i++) {
        float t = (float)i / AUDIO_SAMPLE_RATE;
        float env = 1.f - t / dur;
        if (env < 0.f) env = 0.f;
        float sample = 0.f;
        switch (id) {
            case AUDIO_SFX_SHOOT_PULSE:
                sample = sinf(t * 880.f * TAU_F) * env * 0.4f;
                break;
            case AUDIO_SFX_SHOOT_LASER:
                sample = sinf(t * 1800.f * TAU_F) * env * 0.35f;
                break;
            case AUDIO_SFX_SHOOT_MISSILE:
            case AUDIO_SFX_SHOOT_PLASMA:
                s = s * 1103515245u + 12345u;
                sample = ((float)(s >> 16) / 32768.f - 1.f) * env * 0.5f;
                break;
            case AUDIO_SFX_EXPLOSION_SM:
                s = s * 1103515245u + 12345u;
                sample = ((float)(s >> 16) / 32768.f - 1.f) * env * 0.7f;
                break;
            case AUDIO_SFX_EXPLOSION_LG:
                s = s * 1103515245u + 12345u;
                sample = ((float)(s >> 16) / 32768.f - 1.f) * env * 0.9f;
                break;
            case AUDIO_SFX_PICKUP:
                sample = sinf(t * 1320.f * TAU_F) * env * 0.35f;
                break;
            case AUDIO_SFX_DOCK:
            case AUDIO_SFX_UNDOCK:
                sample = (sinf(t * 261.6f * TAU_F) +
                          sinf(t * 329.6f * TAU_F)) * env * 0.2f;
                break;
            case AUDIO_SFX_CRAFT:
                sample = (sinf(t * 523.3f * TAU_F) +
                          sinf(t * 659.3f * TAU_F)) * env * 0.25f;
                break;
            case AUDIO_SFX_UI_CLICK:
                sample = sinf(t * 1200.f * TAU_F) * env * 0.3f;
                break;
            case AUDIO_SFX_MIXING_SUCCESS:
                sample = (sinf(t * 440.f * TAU_F) +
                          sinf(t * 554.f * TAU_F) +
                          sinf(t * 659.f * TAU_F)) * env * 0.2f;
                break;
            case AUDIO_SFX_MIXING_FAIL:
            case AUDIO_SFX_MIXING_CATASTRO:
                s = s * 1103515245u + 12345u;
                sample = ((float)(s >> 16) / 32768.f - 1.f) * env * 0.6f;
                break;
            case AUDIO_SFX_DRONE_DEPLOY:
                sample = sinf(t * (400.f + 800.f * t / dur) * TAU_F) * env * 0.35f;
                break;
            case AUDIO_SFX_DRONE_RECALL:
                sample = sinf(t * (1200.f - 800.f * t / dur) * TAU_F) * env * 0.35f;
                break;
            case AUDIO_SFX_UPGRADE:
                sample = sinf(t * 880.f * TAU_F) * env * 0.4f;
                break;
            case AUDIO_SFX_FOOTSTEP:
            case AUDIO_SFX_JETPACK:
            case AUDIO_SFX_REPAIR_LOOP:
                s = s * 1103515245u + 12345u;
                sample = ((float)(s >> 16) / 32768.f - 1.f) * env * 0.3f;
                break;
            default:
                sample = sinf(t * 440.f * TAU_F) * env * 0.3f;
                break;
        }
        if (sample >  1.f) sample =  1.f;
        if (sample < -1.f) sample = -1.f;
        buf[i] = (int16_t)(sample * 32767.f);
    }
}

static void audio_gen_music(uint32_t id, int16_t* buf, uint32_t n_frames) {
    float dur = (float)n_frames / AUDIO_SAMPLE_RATE;
    float base_f = (id == AUDIO_MUSIC_AMBIENT) ? 60.f : 80.f;
    for (uint32_t i = 0; i < n_frames; i++) {
        float t = (float)i / AUDIO_SAMPLE_RATE;
        float fade = 1.f;
        if (t < 0.5f) fade = t / 0.5f;
        if (t > dur - 0.5f) fade = (dur - t) / 0.5f;
        if (fade < 0.f) fade = 0.f;
        float sample = sinf(t * base_f * TAU_F) * 0.15f
                     + sinf(t * base_f * 2.f * TAU_F) * 0.10f
                     + sinf(t * base_f * 3.f * TAU_F) * 0.05f;
        sample *= fade;
        if (sample >  1.f) sample =  1.f;
        if (sample < -1.f) sample = -1.f;
        buf[i] = (int16_t)(sample * 32767.f);
    }
}

static int audio_load_sound(uint32_t id) {
    if (id >= AUDIO_MAX_SOUNDS) return 0;
    AudioSound* snd = &g_audio.sounds[id];
    if (snd->used) return 1;
    uint32_t n_frames;
    if (id == AUDIO_MUSIC_AMBIENT || id == AUDIO_MUSIC_DOCKED)
        n_frames = AUDIO_SAMPLE_RATE * 6;
    else
        n_frames = AUDIO_SAMPLE_RATE / 5;
    uint32_t n_bytes = n_frames * (uint32_t)sizeof(int16_t);
    int16_t* buf = (int16_t*)xmalloc(n_bytes);
    if (!buf) return 0;
    if (id == AUDIO_MUSIC_AMBIENT || id == AUDIO_MUSIC_DOCKED)
        audio_gen_music(id, buf, n_frames);
    else
        audio_gen_sound(id, buf, n_frames);
    snd->data        = (uint8_t*)buf;
    snd->size        = n_bytes;
    snd->frame_count = n_frames;
    snd->sample_rate = AUDIO_SAMPLE_RATE;
    snd->channels    = 1;
    snd->format      = ma_format_s16;
    snd->used        = 1;
    return 1;
}

static void audio_load_all(void) {
    static const uint32_t ids[] = {
        AUDIO_SFX_SHOOT_PULSE, AUDIO_SFX_SHOOT_LASER, AUDIO_SFX_SHOOT_MISSILE,
        AUDIO_SFX_SHOOT_PLASMA, AUDIO_SFX_EXPLOSION_SM, AUDIO_SFX_EXPLOSION_LG,
        AUDIO_SFX_PICKUP, AUDIO_SFX_DOCK, AUDIO_SFX_UNDOCK, AUDIO_SFX_CRAFT,
        AUDIO_SFX_UI_CLICK, AUDIO_MUSIC_AMBIENT, AUDIO_MUSIC_DOCKED,
        AUDIO_SFX_MIXING_SUCCESS, AUDIO_SFX_MIXING_FAIL,
        AUDIO_SFX_MIXING_CATASTRO, AUDIO_SFX_DRONE_DEPLOY,
        AUDIO_SFX_DRONE_RECALL, AUDIO_SFX_UPGRADE, AUDIO_SFX_FOOTSTEP,
        AUDIO_SFX_JETPACK, AUDIO_SFX_REPAIR_LOOP
    };
    int loaded = 0;
    for (size_t i = 0; i < sizeof(ids)/sizeof(ids[0]); i++)
        if (audio_load_sound(ids[i])) loaded++;
    LOG("audio_load_all: %d sounds generated", loaded);
}

static void audio_init(AudioSystem* sys) {
    if (!sys) return;
    memset(sys, 0, sizeof(*sys));
    ma_result r = ma_engine_init(NULL, &sys->engine);
    if (r != MA_SUCCESS) {
        LOG("audio_init: engine init failed (%d)", (int)r);
        sys->failed = 1;
        return;
    }
    sys->engine_sample_rate = ma_engine_get_sample_rate(&sys->engine);
    audio_load_all();
    sys->music_volume = 0.5f;
    sys->music_current = 0;
    sys->music_pending = 0;
    sys->music_crossfade = 0.f;
    sys->music_a_active = 1;
    sys->music_started = 0;
    sys->inited = 1;
    LOG("audio_init: engine SR=%u", sys->engine_sample_rate);
}

static void voice_stop(AudioVoiceSlot* v) {
    if (!v || !v->initialized) return;
    ma_sound_stop(&v->sound);
    ma_sound_uninit(&v->sound);
    v->initialized = 0;
    v->busy = 0;
}

static void voice_play(uint32_t sound_id, float vol, int prio,
                        int is_3d, V3 pos) {
    if (!g_audio.inited || g_audio.failed) return;
    if (sound_id >= AUDIO_MAX_SOUNDS) return;
    AudioSound* snd = &g_audio.sounds[sound_id];
    if (!snd->used) return;
    AudioVoiceSlot* v = NULL;
    for (int i = 0; i < AUDIO_MAX_VOICES; i++)
        if (!g_audio.voices[i].busy) { v = &g_audio.voices[i]; break; }
    if (!v) {
        int lowest = 0x7FFFFFFF;
        for (int i = 0; i < AUDIO_MAX_VOICES; i++)
            if (g_audio.voices[i].priority < lowest) {
                lowest = g_audio.voices[i].priority;
                v = &g_audio.voices[i];
            }
        if (!v || v->priority >= prio) return;
        voice_stop(v);
    }
    if (v->initialized) voice_stop(v);
    ma_audio_buffer_ref_init(snd->format, snd->channels,
                              snd->data, snd->size, &v->ref);
    if (ma_sound_init_from_data_source(&g_audio.engine, &v->ref, 0,
                                        NULL, &v->sound) != MA_SUCCESS)
        return;
    v->initialized = 1;
    ma_sound_set_volume(&v->sound, clampf(vol, 0.f, 1.f));
    if (is_3d) {
        ma_sound_set_position(&v->sound, pos.x, pos.y, pos.z);
        ma_sound_set_spatialization_enabled(&v->sound, MA_TRUE);
    } else {
        ma_sound_set_spatialization_enabled(&v->sound, MA_FALSE);
    }
    ma_sound_start(&v->sound);
    v->busy = 1;
    v->priority = prio;
    v->sound_id = sound_id;
}

static void audio_shutdown(AudioSystem* sys) {
    if (!sys || !sys->inited) return;
    for (uint32_t i = 0; i < AUDIO_MAX_VOICES; i++)
        if (sys->voices[i].initialized) {
            ma_sound_uninit(&sys->voices[i].sound);
            sys->voices[i].initialized = 0;
        }
    if (sys->music_a_initialized) {
        ma_sound_uninit(&sys->music_a); sys->music_a_initialized = 0;
    }
    if (sys->music_b_initialized) {
        ma_sound_uninit(&sys->music_b); sys->music_b_initialized = 0;
    }
    for (int i = 0; i < AUDIO_MAX_SOUNDS; i++)
        if (sys->sounds[i].data) {
            xfree(sys->sounds[i].data);
            memset(&sys->sounds[i], 0, sizeof(AudioSound));
        }
    ma_engine_uninit(&sys->engine);
    sys->inited = 0;
    LOG("audio_shutdown");
}

static void audio_play_music(uint32_t id) {
    if (!g_audio.inited || g_audio.failed) return;
    if (id == g_audio.music_current && g_audio.music_pending == 0) return;
    if (id >= AUDIO_MAX_SOUNDS) return;
    AudioSound* snd = &g_audio.sounds[id];
    if (!snd->used) return;
    if (!g_audio.music_started) {
        ma_audio_buffer_ref_init(snd->format, snd->channels,
                                  snd->data, snd->size, &g_audio.music_ref_a);
        if (ma_sound_init_from_data_source(&g_audio.engine,
                                            &g_audio.music_ref_a,
                                            0, NULL,
                                            &g_audio.music_a) != MA_SUCCESS)
            return;
        ma_sound_set_looping(&g_audio.music_a, MA_TRUE);
        ma_sound_set_volume(&g_audio.music_a, g_audio.music_volume);
        ma_sound_set_spatialization_enabled(&g_audio.music_a, MA_FALSE);
        ma_sound_start(&g_audio.music_a);
        g_audio.music_a_initialized = 1;
        g_audio.music_a_active      = 1;
        g_audio.music_current       = id;
        g_audio.music_started       = 1;
        return;
    }
    if (g_audio.music_pending != 0) return;
    int use_b = g_audio.music_a_active;
    ma_sound* sound = use_b ? &g_audio.music_b : &g_audio.music_a;
    ma_audio_buffer_ref* ref = use_b ? &g_audio.music_ref_b : &g_audio.music_ref_a;
    uint8_t* inited = use_b ? &g_audio.music_b_initialized
                             : &g_audio.music_a_initialized;
    if (*inited) { ma_sound_stop(sound); ma_sound_uninit(sound); *inited = 0; }
    ma_audio_buffer_ref_init(snd->format, snd->channels,
                              snd->data, snd->size, ref);
    if (ma_sound_init_from_data_source(&g_audio.engine, ref, 0, NULL,
                                        sound) != MA_SUCCESS) return;
    ma_sound_set_looping(sound, MA_TRUE);
    ma_sound_set_volume(sound, 0.f);
    ma_sound_set_spatialization_enabled(sound, MA_FALSE);
    ma_sound_start(sound);
    *inited = 1;
    g_audio.music_pending = id;
    g_audio.music_crossfade = 0.f;
}

static void audio_tick(float dt) {
    if (!g_audio.inited) return;
    for (uint32_t i = 0; i < AUDIO_MAX_VOICES; i++) {
        AudioVoiceSlot* v = &g_audio.voices[i];
        if (!v->busy || !v->initialized) continue;
        if (!ma_sound_is_playing(&v->sound)) voice_stop(v);
    }
    if (g_audio.music_pending != 0) {
        g_audio.music_crossfade += dt / 1.5f;
        if (g_audio.music_crossfade >= 1.f) {
            g_audio.music_current = g_audio.music_pending;
            g_audio.music_pending = 0;
            int old_b = g_audio.music_a_active;
            if (old_b) {
                if (g_audio.music_a_initialized)
                    ma_sound_stop(&g_audio.music_a);
            } else {
                if (g_audio.music_b_initialized)
                    ma_sound_stop(&g_audio.music_b);
            }
            g_audio.music_a_active = !old_b;
            ma_sound_set_volume(
                g_audio.music_a_active ? &g_audio.music_a : &g_audio.music_b,
                g_audio.music_volume);
            g_audio.music_crossfade = 0.f;
        } else {
            float cf = g_audio.music_crossfade;
            float old_vol = g_audio.music_volume * (1.f - cf);
            float new_vol = g_audio.music_volume * cf;
            if (g_audio.music_a_active) {
                ma_sound_set_volume(&g_audio.music_a, old_vol);
                if (g_audio.music_b_initialized)
                    ma_sound_set_volume(&g_audio.music_b, new_vol);
            } else {
                if (g_audio.music_a_initialized)
                    ma_sound_set_volume(&g_audio.music_a, new_vol);
                ma_sound_set_volume(&g_audio.music_b, old_vol);
            }
        }
    }
}

static void audio_set_listener(V3 pos, V3 fwd, V3 up) {
    if (!g_audio.inited) return;
    ma_engine_listener_set_position(&g_audio.engine, 0, pos.x, pos.y, pos.z);
    ma_engine_listener_set_direction(&g_audio.engine, 0, fwd.x, fwd.y, fwd.z);
    ma_engine_listener_set_world_up(&g_audio.engine, 0, up.x, up.y, up.z);
}

// =====================================================================
