// =====================================================================
// BLOQUE 18d — HW profile detect
// =====================================================================
static void hw_profile_detect(HWProfile* out) {
    if (!out) return;
    memset(out, 0, sizeof(*out));
    MEMORYSTATUSEX mse; memset(&mse, 0, sizeof(mse)); mse.dwLength = sizeof(mse);
    int ramMB = 1024;
    if (GlobalMemoryStatusEx(&mse))
        ramMB = (int)(mse.ullTotalPhys / (1024ull * 1024ull));
    out->ramMB = ramMB;
    int tier = 1;
    if (ramMB < 2048) tier = 0;
    else if (ramMB < 6144) tier = 1;
    else if (ramMB < 12288) tier = 2;
    else tier = 3;
    out->tier = tier;
    const HwTierSpec* s = &g_hw_tiers[tier];
    out->maxAst=s->maxAst; out->maxAli=s->maxAli; out->maxBul=s->maxBul;
    out->maxPick=s->maxPick; out->maxEnergy=s->maxEnergy;
    out->maxField=s->maxField; out->maxParticles=s->maxParticles;
    out->maxRings=s->maxRings; out->maxGhosts=s->maxGhosts;
    out->texSize=s->texSize; out->atlasGrid=s->atlasGrid;
    out->lodPixelThreshold=s->lodPixelThreshold;
    out->slowMoEnabled=1; out->screenshakeEnabled=1;
    LOG("hw_profile_detect: ram=%dMB tier=%d", ramMB, tier);
}

// =====================================================================
// BLOQUE 18e — slot_remap + save_write/read helpers
// =====================================================================
static void slot_remap_init(SlotRemap* r, uint32_t cap) {
    if (!r) return;
    r->entries = (RemapEntry*)xcalloc(cap, sizeof(RemapEntry));
    r->cap = cap; r->count = 0;
}
static void slot_remap_free(SlotRemap* r) {
    if (!r) return;
    xfree(r->entries); r->entries = NULL; r->count = r->cap = 0;
}
static void slot_remap_add(SlotRemap* r, uint32_t old_slot, uint32_t new_slot) {
    if (!r || !r->entries || r->count >= r->cap) return;
    RemapEntry* e = &r->entries[r->count++];
    e->old_slot=old_slot; e->new_slot=new_slot; e->used=1;
}
static uint32_t slot_remap_find(const SlotRemap* r, uint32_t old_slot) {
    if (!r || !r->entries) return UINT32_MAX;
    for (uint32_t i = 0; i < r->count; i++)
        if (r->entries[i].used && r->entries[i].old_slot == old_slot)
            return r->entries[i].new_slot;
    return UINT32_MAX;
}
static int save_write_u32(SaveWriter* w, uint32_t v) {
    if (!w || !w->f) return 0;
    fwrite(&v,4,1,w->f); w->cursor += 4; return 1;
}
static int save_write_u64(SaveWriter* w, uint64_t v) {
    if (!w || !w->f) return 0;
    fwrite(&v,8,1,w->f); w->cursor += 8; return 1;
}
static int save_write_f32(SaveWriter* w, float v) {
    if (!w || !w->f) return 0;
    fwrite(&v,4,1,w->f); w->cursor += 4; return 1;
}
static int save_write_v3(SaveWriter* w, V3 v) {
    return save_write_f32(w,v.x) && save_write_f32(w,v.y) && save_write_f32(w,v.z);
}
static int save_read_u32(SaveReader* r, uint32_t* out) {
    if (!r || !r->f || !out) return 0;
    if (fread(out,4,1,r->f) != 1) return 0;
    r->cursor += 4; return 1;
}
static int save_read_u64(SaveReader* r, uint64_t* out) {
    if (!r || !r->f || !out) return 0;
    if (fread(out,8,1,r->f) != 1) return 0;
    r->cursor += 8; return 1;
}
static int save_read_f32(SaveReader* r, float* out) {
    if (!r || !r->f || !out) return 0;
    if (fread(out,4,1,r->f) != 1) return 0;
    r->cursor += 4; return 1;
}
static int save_read_v3(SaveReader* r, V3* out) {
    return out && save_read_f32(r,&out->x)
               && save_read_f32(r,&out->y)
               && save_read_f32(r,&out->z);
}

// =====================================================================
// BLOQUE 18f — save_full_game_v3
// =====================================================================
static int save_full_game_v3(const char* path) {
    if (!path) return 0;
    FILE* f = fopen(path, "wb");
    if (!f) { LOG("save_full_game_v3: cannot open %s", path); return 0; }
    SaveWriter w = { f, 0 };
    SaveHeader h; memset(&h, 0, sizeof(h));
    h.magic = SAVE_MAGIC_V3;
    h.version = SAVE_VERSION_V3;
    h.things_cap = g_things_cap;
    h.things_live = g_live_count;
    h.player_ship_slot_old = g_game.player_ship_slot;
    h.timestamp = (uint64_t)(time_get() * 1000.0);
    if (fwrite(&h, sizeof(h), 1, f) != 1) { fclose(f); return 0; }
    w.cursor = sizeof(h);
    save_write_u32(&w, (uint32_t)g_game.zone_coords[0]);
    save_write_u32(&w, (uint32_t)g_game.zone_coords[1]);
    save_write_u32(&w, (uint32_t)g_game.zone_coords[2]);
    save_write_u32(&w, g_game.zone_seed);
    save_write_u32(&w, g_game.zones_visited);
    save_write_u64(&w, g_game.score);
    save_write_u32(&w, g_game.wave);
    save_write_u32(&w, g_game.kills_aliens);
    save_write_u32(&w, g_game.kills_asteroids);
    save_write_f32(&w, g_game.distance_traveled);
    save_write_f32(&w, g_game.time_alive);
    save_write_u32(&w, (uint32_t)g_game.current_zone);
    save_write_u32(&w, (uint32_t)g_player.mode);
    save_write_u32(&w, g_player.inside_ship);
    save_write_u32(&w, g_player.prev_inside_ship);
    save_write_u32(&w, (uint32_t)g_player.prev_mode);
    save_write_v3(&w, g_player.eva_pos);
    save_write_v3(&w, g_player.eva_vel);
    save_write_v3(&w, g_player.walker.pos_local);
    save_write_f32(&w, g_player.walker.yaw);
    save_write_f32(&w, g_player.walker.pitch);
    save_write_u32(&w, g_player.suit_compute_total);
    save_write_u32(&w, g_player.suit_compute_tier);
    save_write_u32(&w, g_player.mixing_level);
    save_write_u32(&w, g_player.mixing_xp);
    save_write_u32(&w, (uint32_t)g_player.inventory.count);
    for (int i = 0; i < g_player.inventory.count; i++) {
        InventoryItem* it = &g_player.inventory.items[i];
        save_write_u32(&w, it->bp.seed);
        save_write_u32(&w, (uint32_t)it->bp.kind);
        save_write_u32(&w, it->bp.tier);
        save_write_u32(&w, it->bp.material_id);
        save_write_f32(&w, it->bp.mass);
        save_write_f32(&w, it->bp.hp);
        save_write_u32(&w, it->qty);
    }
    save_write_u32(&w, (uint32_t)g_xp_b7.level);
    save_write_u32(&w, (uint32_t)g_xp_b7.xp);
    save_write_u32(&w, (uint32_t)g_xp_b7.xp_to_next);
    save_write_u32(&w, (uint32_t)g_xp_b7.perk_pts);
    save_write_u32(&w, (uint32_t)g_xp_b7.perk_toughness);
    save_write_u32(&w, (uint32_t)g_xp_b7.perk_precision);
    save_write_u32(&w, (uint32_t)g_xp_b7.perk_greed);
    save_write_u32(&w, (uint32_t)g_xp_b7.perk_speed);
    save_write_u32(&w, (uint32_t)g_xp_b7.perk_evasive);
    uint32_t count = 0;
    for (uint32_t i = 0; i < g_things_cap; i++)
        if (g_alive[i] && g_things[i].type != ET_NONE) count++;
    save_write_u32(&w, count);
    SlotRemap remap; slot_remap_init(&remap, count + 4);
    uint32_t written = 0;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i] || g_things[i].type == ET_NONE) continue;
        Thing* t = &g_things[i];
        save_write_u32(&w, i);
        save_write_u32(&w, t->type);
        save_write_u32(&w, t->flags);
        save_write_u32(&w, t->seed);
        save_write_u32(&w, t->id);
        save_write_u32(&w, t->parent);
        save_write_v3(&w, t->pos);
        save_write_v3(&w, t->vel);
        save_write_f32(&w, t->radius);
        save_write_f32(&w, t->hp);
        save_write_f32(&w, t->maxhp);
        save_write_f32(&w, t->mass);
        save_write_f32(&w, t->life);
        save_write_f32(&w, t->rot);
        save_write_f32(&w, t->spin);
        save_write_f32(&w, ENT_F(t,24));
        save_write_f32(&w, ENT_F(t,20));
        save_write_u32(&w, ENT_I(t,0));
        save_write_u32(&w, ENT_I(t,5));
        save_write_u32(&w, ENT_I(t,21));
        save_write_u32(&w, ENT_I(t,22));
        save_write_u32(&w, t->num_children);
        save_write_u32(&w, t->num_mat_refs);
        for (uint32_t k = 0; k < t->num_children && k < 8; k++)
            save_write_u32(&w, t->u.hub.children[k]);
        for (uint32_t k = 0; k < t->num_mat_refs && k < 8; k++)
            save_write_u32(&w, t->u.hub.mat_refs[k]);
        if ((int)i == (int)g_game.player_ship_slot)
            slot_remap_add(&remap, i, written);
        written++;
    }
    save_write_u32(&w, remap.count);
    for (uint32_t i = 0; i < remap.count; i++) {
        save_write_u32(&w, remap.entries[i].old_slot);
        save_write_u32(&w, remap.entries[i].new_slot);
    }
    slot_remap_free(&remap);
    fclose(f);
    LOG("save_full_game_v3: wrote %u entities to %s", written, path);
    return 1;
}

// =====================================================================
// BLOQUE 18g — load_full_game_v3
// =====================================================================
static int load_full_game_v3(const char* path) {
    if (!path) return 0;
    FILE* f = fopen(path, "rb");
    if (!f) { LOG("load_full_game_v3: cannot open %s", path); return 0; }
    SaveHeader h;
    if (fread(&h, sizeof(h), 1, f) != 1) { fclose(f); return 0; }
    if (h.magic != SAVE_MAGIC_V3 || h.version != SAVE_VERSION_V3) {
        fclose(f); notice_push("SAVE INCOMPATIBLE"); return 0;
    }
    SaveReader r = { f, sizeof(h) };
    for (uint32_t i = 0; i < g_things_cap; i++)
        if (g_alive[i]) entity_destroy(i);
    crew_init();
    uint32_t zx,zy,zz,zseed,zones_v,wave,ka,kas,curz;
    uint64_t score; float dist,ta;
    save_read_u32(&r,&zx); save_read_u32(&r,&zy); save_read_u32(&r,&zz);
    save_read_u32(&r,&zseed); save_read_u32(&r,&zones_v);
    save_read_u64(&r,&score);
    save_read_u32(&r,&wave);
    save_read_u32(&r,&ka); save_read_u32(&r,&kas);
    save_read_f32(&r,&dist); save_read_f32(&r,&ta);
    save_read_u32(&r,&curz);
    g_game.zone_coords[0]=(int32_t)zx; g_game.zone_coords[1]=(int32_t)zy;
    g_game.zone_coords[2]=(int32_t)zz;
    g_game.zone_seed=zseed; g_game.zones_visited=zones_v;
    g_game.score=score; g_game.wave=wave;
    g_game.kills_aliens=ka; g_game.kills_asteroids=kas;
    g_game.distance_traveled=dist; g_game.time_alive=ta;
    g_game.current_zone=(int32_t)curz;
    uint32_t pmode,inside,prev_inside,prev_mode;
    V3 eva_pos,eva_vel,walker_pos;
    float wyaw,wpitch;
    uint32_t sct,scti,mixlvl,mixxp;
    save_read_u32(&r,&pmode); save_read_u32(&r,&inside);
    save_read_u32(&r,&prev_inside); save_read_u32(&r,&prev_mode);
    save_read_v3(&r,&eva_pos); save_read_v3(&r,&eva_vel);
    save_read_v3(&r,&walker_pos);
    save_read_f32(&r,&wyaw); save_read_f32(&r,&wpitch);
    save_read_u32(&r,&sct); save_read_u32(&r,&scti);
    save_read_u32(&r,&mixlvl); save_read_u32(&r,&mixxp);
    g_player.mode=(PlayerMode)pmode;
    g_player.inside_ship=inside;
    g_player.prev_inside_ship=prev_inside;
    g_player.prev_mode=(int)prev_mode;
    g_player.eva_pos=eva_pos; g_player.eva_vel=eva_vel;
    g_player.walker.pos_local=walker_pos;
    g_player.walker.yaw=wyaw; g_player.walker.pitch=wpitch;
    g_player.suit_compute_total=sct; g_player.suit_compute_tier=scti;
    g_player.mixing_level=mixlvl; g_player.mixing_xp=mixxp;
    uint32_t inv_count=0;
    save_read_u32(&r,&inv_count);
    if (inv_count > INVENTORY_MAX) inv_count = INVENTORY_MAX;
    inv_clear(&g_player.inventory);
    for (uint32_t i = 0; i < inv_count; i++) {
        uint32_t seed,kind,tier,mat,qty; float mass,hp;
        save_read_u32(&r,&seed); save_read_u32(&r,&kind);
        save_read_u32(&r,&tier); save_read_u32(&r,&mat);
        save_read_f32(&r,&mass); save_read_f32(&r,&hp);
        save_read_u32(&r,&qty);
        InventoryItem* it = &g_player.inventory.items[g_player.inventory.count++];
        memset(it, 0, sizeof(*it));
        it->bp.seed=seed; it->bp.kind=(ThingKind)kind; it->bp.tier=tier;
        it->bp.material_id=(uint16_t)mat; it->bp.mass=mass; it->bp.hp=hp;
        it->qty=(uint16_t)qty;
    }
    uint32_t xl,xx,xn,pp,pt,pp2,pg,ps,pe;
    save_read_u32(&r,&xl); save_read_u32(&r,&xx); save_read_u32(&r,&xn);
    save_read_u32(&r,&pp); save_read_u32(&r,&pt); save_read_u32(&r,&pp2);
    save_read_u32(&r,&pg); save_read_u32(&r,&ps); save_read_u32(&r,&pe);
    g_xp_b7.level=(int)xl; g_xp_b7.xp=(int)xx;
    g_xp_b7.xp_to_next=(int)xn; g_xp_b7.perk_pts=(int)pp;
    g_xp_b7.perk_toughness=(int)pt; g_xp_b7.perk_precision=(int)pp2;
    g_xp_b7.perk_greed=(int)pg; g_xp_b7.perk_speed=(int)ps;
    g_xp_b7.perk_evasive=(int)pe;
    uint32_t ec=0;
    save_read_u32(&r,&ec);
    if (ec > MAX_ENTITIES) { notice_push("SAVE CORRUPT"); fclose(f); return 0; }
    SlotRemap remap; slot_remap_init(&remap, ec + 4);
    uint32_t player_ship_new = UINT32_MAX;
    for (uint32_t i = 0; i < ec; i++) {
        uint32_t old_slot,type,flags,seed,id,parent;
        V3 pos,vel;
        float radius,hp,maxhp,mass,life,rot,spin,pitch,yaw;
        uint32_t ei0,ei5,ei21,ei22,nchild,nmat;
        uint32_t children[8],mat_refs[8];
        save_read_u32(&r,&old_slot); save_read_u32(&r,&type);
        save_read_u32(&r,&flags); save_read_u32(&r,&seed);
        save_read_u32(&r,&id); save_read_u32(&r,&parent);
        save_read_v3(&r,&pos); save_read_v3(&r,&vel);
        save_read_f32(&r,&radius); save_read_f32(&r,&hp);
        save_read_f32(&r,&maxhp); save_read_f32(&r,&mass);
        save_read_f32(&r,&life); save_read_f32(&r,&rot);
        save_read_f32(&r,&spin); save_read_f32(&r,&pitch);
        save_read_f32(&r,&yaw);
        save_read_u32(&r,&ei0); save_read_u32(&r,&ei5);
        save_read_u32(&r,&ei21); save_read_u32(&r,&ei22);
        save_read_u32(&r,&nchild); save_read_u32(&r,&nmat);
        if (nchild > 8) nchild = 8;
        if (nmat > 8)   nmat = 8;
        for (uint32_t k = 0; k < nchild; k++) save_read_u32(&r,&children[k]);
        for (uint32_t k = 0; k < nmat;   k++) save_read_u32(&r,&mat_refs[k]);
        Thing t; entity_clear_template(&t);
        t.type = type < ET_COUNT ? type : ET_NONE;
        t.flags=flags; t.seed=seed; t.parent=parent;
        t.pos=pos; t.vel=vel;
        t.radius=radius; t.hp=hp; t.maxhp=maxhp; t.mass=mass;
        t.life=life; t.rot=rot; t.spin=spin;
        ENT_SET_F(&t,24,pitch); ENT_SET_F(&t,20,yaw);
        ENT_SET_I(&t,0,ei0); ENT_SET_I(&t,5,ei5);
        ENT_SET_I(&t,21,ei21); ENT_SET_I(&t,22,ei22);
        t.num_children=(uint16_t)nchild; t.num_mat_refs=(uint16_t)nmat;
        for (uint32_t k = 0; k < nchild; k++) t.u.hub.children[k]=children[k];
        for (uint32_t k = 0; k < nmat;   k++) t.u.hub.mat_refs[k]=mat_refs[k];
        uint32_t new_slot = entity_spawn(&t);
        if (new_slot == UINT32_MAX) continue;
        SideKind sk = thing_side_kind_for_type(t.type);
        if (sk == SD_AI) {
            AiData* ai = (AiData*)entity_attach_side(new_slot, SD_AI);
            if (ai) {
                memset(ai, 0, sizeof(*ai));
                ai->target_slot=UINT32_MAX; ai->leader_slot=UINT32_MAX;
                intent_full_clear(&ai->intent);
            }
        } else if (sk != SD_NONE && sk != SD_HUB_OVERFLOW) {
            entity_attach_side(new_slot, sk);
        }
        if (old_slot == h.player_ship_slot_old) player_ship_new = new_slot;
        slot_remap_add(&remap, old_slot, new_slot);
    }
    g_game.player_ship_slot = player_ship_new;
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        Thing* t = &g_things[i];
        uint32_t np = slot_remap_find(&remap, t->parent);
        if (np != UINT32_MAX) t->parent = np;
        for (uint32_t k = 0; k < t->num_children && k < 8; k++) {
            uint32_t nc = slot_remap_find(&remap, t->u.hub.children[k]);
            if (nc != UINT32_MAX) t->u.hub.children[k] = nc;
        }
    }
    slot_remap_free(&remap);
    fclose(f);
    notice_push("GAME LOADED");
    LOG("load_full_game_v3: restored %u entities", ec);
    return 1;
}

