static void sim_stage_autosave(float dt) {
    (void)dt;
    float now = (float)time_get();
    if (now - g_last_autosave_time > 60.f && !g_game.docked) {
        g_last_autosave_time = now;
        save_autosave();
    }
}

static void sim_pipeline(float dt) {
    int n = (int)(sizeof(g_sim_pipeline) / sizeof(g_sim_pipeline[0]));
    for (int i = 0; i < n; i++)
        if (g_sim_pipeline[i]) g_sim_pipeline[i](dt);
    g_game.frame++;
    g_game.lastTickDt = dt;
}

static void sim_tick(float real_dt) {
    static float accumulator = 0.f;
    accumulator += real_dt;
    int steps = 0;
    while (accumulator >= SIM_DT && steps < MAX_CATCHUP) {
        sh_rebuild();
        sim_pipeline(SIM_DT);
        accumulator -= SIM_DT;
        steps++;
    }
    if (steps >= MAX_CATCHUP) accumulator = 0.f;
}

// =====================================================================
// BLOQUE 20 — SAVE / QUICK-SAVE / PAUSE / QUIT
// =====================================================================

static void save_autosave(void) {
    if (!save_full_game_v3("saves/autosave.sav"))
        LOG("save_autosave: failed");
}

static void game_save_quick(void) {
    if (!save_full_game_v3("saves/quicksave.sav"))
        notice_push("SAVE FAILED");
    else
        notice_push("SAVED");
}

static void game_load_quick(void) {
    if (!load_full_game_v3("saves/quicksave.sav"))
        notice_push("LOAD FAILED");
}

static void game_request_quit(void) {
    save_autosave();
    g_game.request_quit = 1;
}

static void game_toggle_pause(int paused) {
    g_game.paused = paused;
}

// =====================================================================
// BLOQUE 21 — DOCK ACTIONS
// =====================================================================

static void player_refuel_at_dock(void) {
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return;
    uint32_t cost = 5;
    if (sd->matinv[0] < cost) {
        notice_push("NOT ENOUGH CREDITS");
        return;
    }
    sd->matinv[0] -= cost;
    sd->fuel = sd->fuel_max;
    notice_push("FUEL FULL");
}

static void player_repair_at_dock(void) {
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return;
    uint32_t cost = 10;
    if (sd->matinv[0] < cost) {
        notice_push("NOT ENOUGH CREDITS");
        return;
    }
    sd->matinv[0] -= cost;
    for (uint32_t i = 0; i < COMP_COUNT; i++) {
        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
        if (!cd) continue;
        cd->hp = cd->maxhp;
        cd->status = 0;
    }
    notice_push("REPAIRED");
}

static void player_upgrade_open(void) {
    input_set_context(CTX_GARAGE);
}

static void player_dock(void) {
    if (g_game.docked) return;
    if (g_player.mode != PLAYER_MODE_PILOT) return;
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    g_game.docked = 1;
    input_set_context(CTX_DOCKED);
    menu_open(MENU_DOCK_BASE);
    notice_push("DOCKED");
    audio_sfx_dock();
}

static void player_undock(void) {
    if (!g_game.docked) return;
    g_game.docked = 0;
    menu_close();
    input_set_context(CTX_GAME);
    notice_push("UNDOCKED");
    audio_sfx_undock();
}


// =====================================================================
// BLOQUE 22 — MARKET BUY / SELL
// =====================================================================

static void market_buy_selected(int sel) {
    uint32_t slot = g_game.current_market_slot;
    if (!entity_alive(slot)) return;
    if ((int)g_game.current_market_kind == 0)
        launcher_consume_offer(slot, (uint32_t)sel);
    else
        lanzadera_consume_offer(slot, (uint32_t)sel);
}

static void market_sell_selected(int sel) {
    uint32_t ship_slot = actor_ship_slot();
    if (ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(ship_slot);
    if (!sd) return;
    if (sel < 0 || sel >= (int)g_matpool.count) return;
    uint32_t have = sd->matinv[sel];
    if (have == 0) {
        notice_push("NOTHING TO SELL");
        return;
    }
    const Material* m = mat_get((uint16_t)sel);
    float mult = g_player_consensus.price_multiplier;
    if (mult < 0.5f) mult = 0.5f;
    if (mult > 2.0f) mult = 2.0f;
    uint32_t price = (uint32_t)(m->price_base * (float)have * mult * 0.8f);
    if (price < 1) price = 1;
    sd->matinv[sel] = 0;
    g_game.score += price;
    notice_push("SOLD");
}

