// BLOQUE 24 — APP LIFECYCLE + MAIN
// =====================================================================

static void app_init(void) {
    log_open("game.log");
    juegos_nucleo_init();
    juegos_nucleo_selftest();
    humanoid_system_init();
    cap_system_init();
    LOG("app_init: start");

    win_init();
    timer_init();
    block14_init();
    block15_init();
    b_features_init();
    render_init_shaders();
    stream_init();
    meshes_init();
    starfield_init();
    font_build("Consolas", 16);
    text_shader_init();
    atlas_init();
    ecs_core_init(MAX_ENTITIES, MAX_ENTITIES * MAX_RCMDS_PER_ENTITY);
    entity_set_publish(thing_publish_impl);
    entity_set_collide(thing_collide_impl);
    entity_set_death(death_dispatch);
    world_sim_init();
    block6_init();
    block7_init();
    block9_init();
    block10a_init();
    block10b_init();
    block10c_init();
    block11a_init();
    action_table_init();
    toggle_init();
    input_set_context(CTX_MENU);
    menu_open(MENU_MAIN);
    game_toggle_pause(1);
    crew_init();
    crew_alerts_init();
    faction_system_init();
    behavior_init();
    event_bus_init();
    parallel_pool_init(&g_parallel_pool);
    soft_task_init();

    g_game.player_ship_slot = ship_create_with_weapon(v3(4.f, 0.f, 4.f),
                                                      SHIP_PRESET_PLAYER, WEAPON_PULSE);
    if (g_game.player_ship_slot != UINT32_MAX)
        ship_gen_player(g_game.player_ship_slot);

    g_player_platform_slot = ship_create_with_weapon(v3(0, 0, 0),
                                                     SHIP_PRESET_PLAYER, WEAPON_PULSE);
    if (g_player_platform_slot != UINT32_MAX) {
        ship_gen_lanzadera_platform(g_player_platform_slot);
        g_player.inside_ship = g_player_platform_slot;
        g_player.mode        = PLAYER_MODE_PLATFORM;
        int start = ship_find_node_with_prop(g_player_platform_slot,
                                             NODE_PROP_COMPUTER_ROOM);
        if (start < 0) start = 0;
        walker_reset_to_node(&g_player.walker, g_player_platform_slot, start);
        lanzadera_spawn(v3(0.f, 3.5f, -30.f), xrng_u32());
        platform_forge_ensure(g_player_platform_slot);
        V3 room_local =
            v3(0.f, 2.0f, 0.f);
        crew_spawn(g_player_platform_slot, room_local, xrng_u32());
        crew_spawn(g_player_platform_slot,
                   v3(-4.2f, 0.f, 0.f), xrng_u32());
    }

    g_game.zoom          = 1.f;
    g_game.frame         = 0;
    g_game.lastTickDt    = SIM_DT;
    g_last_autosave_time = (float)time_get();
    audio_play_music(AUDIO_MUSIC_AMBIENT);
    LOG("app_init: done");
}

static void app_shutdown(void) {
    LOG("app_shutdown: start");
    cap_system_shutdown();
    humanoid_system_shutdown();
    save_autosave();
    parallel_pool_shutdown(&g_parallel_pool);
    event_bus_shutdown();
    block11a_shutdown();
    block10c_shutdown();
    block10b_shutdown();
    block10a_shutdown();
    block9_shutdown();
    block7_shutdown();
    block6_shutdown();
    world_sim_shutdown();
    ecs_core_shutdown();
    xfree(g_combat_states); g_combat_states = NULL; g_combat_states_n = g_combat_states_cap = 0; g_combat_free_n = 0;
    xfree(g_crew_alerts);   g_crew_alerts   = NULL; g_crew_alerts_n   = g_crew_alerts_cap   = 0;
    xfree(g_hud_chars);     g_hud_chars     = NULL; g_hud_chars_n     = g_hud_chars_cap     = 0;
    xfree(g_ship_ext);      g_ship_ext      = NULL; g_ship_ext_cap    = 0;
    lanzadera_shutdown_all();
    crew_release_all();
    sh_scratch_shutdown();
    radar_blips_shutdown();
    part_cargo_shutdown();
    atlas_shutdown();
    block15_shutdown();
    block14_shutdown();
    starfield_shutdown();
    meshes_shutdown();
    stream_destroy();
    font_destroy();
    render_destroy_shaders();
    win_shutdown();
    juegos_nucleo_shutdown();
    xmem_report("app_shutdown");
    LOG("app_shutdown: done");
    log_close();
}

static int app_step(void) {
    if (!win_pump()) return 0;
    float real_dt = (float)timer_step();
    if (real_dt > 0.1f) real_dt = 0.1f;

    input_begin_frame();
    input_process_queue();
    juegos_nucleo_drain(64);
    input_post_process(real_dt);
    context_tick_impl(g_ctx, real_dt);

    if (g_ctx == CTX_GAME && !g_game.paused)
        sim_tick(real_dt);

    soft_task_tick_all(real_dt);
    render_orchestrate(real_dt);

    if (g_game.flash > 0.f) g_game.flash -= real_dt * 2.f;
    if (g_game.flash < 0.f) g_game.flash = 0.f;
    if (g_game.shake > 0.f) g_game.shake *= (1.f - 3.f * real_dt);
    if (g_game.shake < 0.01f) g_game.shake = 0.f;

    if (g_game.request_quit) return 0;
    return 1;
}


/* ═══════════════════════════════════════════════════════════════════════
   BRIDGE — manejadores de acciones (tabla g_actions) + interacción contextual
   Reúne la lógica rica de B (game_dispatch/combined_dispatch) con la tabla
   data-driven de A: una sola ruta de ejecución por acción.
   ═══════════════════════════════════════════════════════════════════════ */

/* Interacción contextual (tecla INTERACT): abordar, cabina, laboratorio, eyectar */
static void player_interact_context(void) {
    if (g_player.mode == PLAYER_MODE_PILOT) {
        player_transition_to(PLAYER_MODE_ON_FOOT, g_player.inside_ship);
        return;
    }
    if (g_player.mode == PLAYER_MODE_EVA) {
        uint32_t ship = player_find_ship(8.f, 1 | 2);
        if (ship == UINT32_MAX) ship = player_find_ship(6.f, 0);
        if (ship == UINT32_MAX) return;
        ShipDataExt* ext = ship_ext(ship);
        if (ext && ext->is_platform) { player_transition_to(PLAYER_MODE_PLATFORM, ship); return; }
        int eject = ship_find_node_with_prop(ship, NODE_PROP_EJECT);
        if (eject >= 0) {
            g_player.prev_inside_ship = g_player.inside_ship;
            g_player.prev_mode        = (int)g_player.mode;
            g_player.inside_ship      = ship;
            g_player.mode             = PLAYER_MODE_ON_FOOT;
            walker_reset_to_node(&g_player.walker, ship, eject);
            notice_push("BOARDED SHIP");
        } else {
            player_transition_to(PLAYER_MODE_PILOT, ship);
        }
        return;
    }
    if (g_player.mode == PLAYER_MODE_ON_FOOT && g_player.inside_ship != UINT32_MAX) {
        uint32_t ship = g_player.inside_ship;
        V3 pw = local_to_world_pos(ship, g_player.walker.pos_local);
        int cockpit = ship_find_node_with_prop(ship, NODE_PROP_COCKPIT);
        if (cockpit >= 0 && v3dist(ship_node_world_pos(ship, cockpit), pw) < 2.5f) {
            if (player_transition_to(PLAYER_MODE_PILOT, ship)) return;
        }
        int room = ship_find_node_with_prop(ship, NODE_PROP_LAB | NODE_PROP_COMPUTER_ROOM);
        if (room >= 0 && v3dist(ship_node_world_pos(ship, room), pw) < 2.5f) {
            mixing_ui_open(ship, room);
            input_set_context(CTX_MIX);
            return;
        }
        int eject = ship_find_node_with_prop(ship, NODE_PROP_EJECT);
        if (eject >= 0 && v3dist(ship_node_world_pos(ship, eject), pw) < 2.f)
            player_transition_to(PLAYER_MODE_EVA, ship);
    }
}

static int player_mix_pick_index(void) {
    /* primer ítem del inventario que aún no esté en un slot de mezcla */
    for (int i = 0; i < g_player.inventory.count; i++) {
        uint32_t s = g_player.inventory.items[i].bp.seed;
        int used = 0;
        for (int k = 0; k < g_mixing_ui.input_count; k++)
            if (g_mixing_ui.input_seeds[k] == s) used = 1;
        if (!used) return i;
    }
    return -1;
}

