static void apply_gravity(V3* p, V3* vel, float dt) {
    for (uint32_t i = 0; i < g_type_count[ET_STAR]; i++) {
        uint32_t slot = g_type_slots[ET_STAR][i];
        if (!g_alive[slot]) continue;
        Thing* s = &g_things[slot];
        V3 d = v3sub(s->pos, *p);
        float r2 = v3dot(d, d);
        if (r2 < 2500000.f && r2 > 100.f) {
            float r = sqrtf(r2);
            float g = 200.f * (s->radius * s->radius) / r2;
            *vel = v3add(*vel, v3mul(v3mul(d, 1.f / r), g * dt));
        }
    }
}

static void camo_init(void) {
    if (g_game.player_ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
    if (!sd) return;
    sd->camo_active = 0;
    sd->camo_type   = 0;
}

static void camo_tick(float dt) {
    if (g_game.player_ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
    if (!sd || !sd->camo_active) return;
    float cost = (sd->camo_type == 3) ? 12.f
               : (sd->camo_type == 2) ? 8.f
               : (sd->camo_type == 1) ? 5.f : 0.f;
    sd->energy -= cost * dt;
    if (sd->energy < 0.f) { sd->energy = 0.f; sd->camo_active = 0; }
}

static uint32_t cannon_spawn(V3 pos, uint32_t wk) { return turret_spawn(pos, ET_CANNON, wk); }

static uint32_t turret_spawn(V3 pos, uint32_t type, uint32_t weapon_kind) {
    Thing t;
    entity_clear_template(&t);
    t.type   = type;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC | ENT_FLAG_NO_INTEGRATE;
    t.pos    = pos;
    t.radius = (type == ET_TOWER) ? 1.5f : 1.0f;
    t.hp = t.maxhp = (type == ET_TOWER) ? 120.f : 40.f;
    t.mass   = (type == ET_TOWER) ? 200.f : 80.f;
    t.rot    = xrng_range(0.f, TAU_F);
    t.seed   = xrng_u32();
    ENT_SET_I(&t, 0, weapon_kind);
    ENT_SET_F(&t, 1, 0.f);
    ENT_SET_F(&t, 2, (type == ET_TOWER) ? 1.5f : 0.6f);
    ENT_SET_F(&t, 3, (type == ET_TOWER) ? 600.f : 400.f);
    ENT_SET_F(&t, 4, (type == ET_TOWER) ? 10.f : 6.f);
    return entity_spawn(&t);
}

