static void computer_assign_drones(uint32_t computer_slot, uint32_t ship_slot) {
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext || computer_slot >= g_things_cap) return;
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        if (ext->drone_slots_ship[i] == UINT32_MAX) continue;
        uint32_t drone = ext->drone_slots_ship[i];
        if (!entity_alive(drone)) continue;
        DroneDecision* dec = drone_decision_get(drone);
        if (!dec) continue;
        dec->computer_slot = computer_slot;
        ComponentData* cd = (ComponentData*)entity_side_ptr(computer_slot);
        if (cd && cd->status == 2) dec->mode = DA_FERAL;
        else dec->mode = DA_SLAVE;
        computer_decide_priority(dec, drone, computer_slot);
    }
}

static DroneDecision* drone_decision_get(uint32_t drone_slot) {
    Thing* d = entity_get(drone_slot);
    if (!d || d->type != ET_DRONE) return NULL;
    uint32_t idx = ENT_I(d, 29);
    if (idx < 512 && g_drone_decisions[idx].used) return &g_drone_decisions[idx];
    for (uint32_t i = 0; i < 512; i++) {
        if (g_drone_decisions[i].used) continue;
        memset(&g_drone_decisions[i], 0, sizeof(g_drone_decisions[i]));
        g_drone_decisions[i].used = 1;
        g_drone_decisions[i].computer_slot = UINT32_MAX;
        g_drone_decisions[i].mode = DA_AUTONOMOUS;
        g_drone_decisions[i].autonomy_trust = 0.5f;
        ENT_SET_I(d, 29, i);
        return &g_drone_decisions[i];
    }
    return NULL;
}

static void computer_decide_priority(DroneDecision* dec, uint32_t drone_slot,
                                       uint32_t computer_slot) {
    Thing* d = entity_get(drone_slot);
    if (!d || !dec) return;
    uint32_t caps = ENT_I(d, 21);
    static const uint32_t base[] = {
        DRONE_CAP_COMBAT, DRONE_CAP_REPAIR, DRONE_CAP_CARGO,
        DRONE_CAP_RECON, DRONE_CAP_MINING, DRONE_CAP_HAUL,
        DRONE_CAP_SENSOR, DRONE_CAP_JAMMER
    };
    ComponentData* cd = (ComponentData*)entity_side_ptr(computer_slot);
    float hp_frac = 1.f;
    if (cd && cd->maxhp > 0.f) hp_frac = cd->hp / cd->maxhp;
    int pidx = 0;
    if (hp_frac < 0.5f && (caps & DRONE_CAP_REPAIR))
        dec->cap_priority[pidx++] = DRONE_CAP_REPAIR;
    for (int i = 0; i < 8 && pidx < 8; i++) {
        if (!(caps & base[i])) continue;
        if (pidx > 0 && dec->cap_priority[pidx-1] == base[i]) continue;
        dec->cap_priority[pidx++] = (uint8_t)base[i];
    }
    while (pidx < 8) dec->cap_priority[pidx++] = 0;
}

static int computer_store_bundle(uint32_t ship_slot, int node_idx,
                                   uint32_t bundle_id) {
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext || node_idx < 0 || node_idx >= ext->node_count) return 0;
    ShipNode* n = &ext->nodes[node_idx];
    if (!(n->props_mask & NODE_PROP_COMPUTER_ROOM)) return 0;
    uint32_t idx = ship_slot * 4 + (uint32_t)(node_idx & 3);
    if (idx >= MAX_ENTITIES * 4) return 0;
    ComputerKnowledge* ck = &g_computer_knowledge[idx];
    if (ck->count >= 3) return 0;
    ck->bundle_ids[ck->count++] = bundle_id;
    return 1;
}

static uint32_t density_spawn(V3 pos, float radius, float mult) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_DENSITY;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC | ENT_FLAG_NO_COLLIDE | ENT_FLAG_NO_INTEGRATE;
    t.pos    = pos;
    t.radius = radius;
    t.hp = t.maxhp = 1.f;
    t.mass   = 1.f;
    ENT_SET_F(&t, 0, clampf(mult, 0.1f, 10.f));
    return entity_spawn(&t);
}

static void density_tick(float dt) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i] || g_things[i].type != ET_DENSITY) continue;
        Thing* d = &g_things[i];
        float mult = ENT_F(d, 0);
        uint32_t* nearby;
        uint32_t n = sh_query_dyn(d->pos, d->radius, g_things_cap, &nearby);
        for (uint32_t k = 0; k < n; k++) {
            uint32_t o = nearby[k];
            if (o == i) continue;
            Thing* ot = &g_things[o];
            if (!ot || (ot->flags & ENT_FLAG_STATIC)) continue;
            V3 diff = v3sub(d->pos, ot->pos);
            float d2 = v3lensq(diff);
            if (d2 < 0.01f) continue;
            float dist = sqrtf(d2);
            float falloff = clampf(1.f - dist / d->radius, 0.f, 1.f);
            if (falloff <= 0.f) continue;
            V3 dir = v3mul(diff, 1.f / dist);
            ot->vel = v3add(ot->vel, v3mul(dir, mult * falloff * 25.f * dt));
        }
        sh_scratch_release();
    }
}

static void drawCockpitLighting(int vw, int vh) {
    if (!g_settings.beaconLights) return;
    float t = (float)time_get();

    int stateColor = 0;
    float pulseRate = 1.f;
    float hpFrac = (g_player.inside_ship != UINT32_MAX)
                   ? ship_health_fraction(g_player.inside_ship) : 1.f;
    if (hpFrac < 0.25f)       { stateColor = 2; pulseRate = 6.f; }
    else if (hpFrac < 0.50f)  { stateColor = 1; pulseRate = 3.f; }
    else if (g_rect_travel)   { stateColor = 3; pulseRate = 2.f; }
    else if (g_game.docked)   { stateColor = 4; pulseRate = 1.5f; }
    else if (g_b7_scan_active){ stateColor = 3; pulseRate = 1.0f; }

    float hueShift = 0.f, alphaMul = 1.f, flicker = 0.f;
    float biasX = 0.f, biasY = 0.f;
    Thing* ship = entity_get(g_game.player_ship_slot);
    V3 ship_pos = ship ? ship->pos : v3zero();
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i] || g_things[i].type != ET_FIELD) continue;
        float d = v3dist(ship_pos, g_things[i].pos);
        if (d > 350.f) continue;
        float strength = 1.f - d / 350.f;
        uint32_t ftype = ENT_I(&g_things[i], 0);
        if (ftype == FIELD_TYPE_GRAVITY) {
            hueShift += strength * 0.25f;
            flicker  += strength * 0.8f;
        } else if (ftype == FIELD_TYPE_DAMAGE) {
            V3 dir = v3norm(v3sub(g_things[i].pos, ship_pos));
            biasX += dir.x * strength * 0.15f;
            biasY += -dir.z * strength * 0.15f;
            alphaMul *= (1.f - strength * 0.2f);
        } else if (ftype == FIELD_TYPE_SLOW) {
            alphaMul *= (1.f - strength * 0.6f);
            stateColor = 2;
        }
    }
    alphaMul = clampf(alphaMul, 0.15f, 1.5f);

    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        if (g_things[i].type == ET_ALIEN &&
            v3dist(ship_pos, g_things[i].pos) < 400.f) {
            stateColor = 5;
            pulseRate = 2.5f;
            break;
        }
    }
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i] || g_things[i].type != ET_ANOMALY) continue;
        if (v3dist(ship_pos, g_things[i].pos) < 500.f) {
            hueShift += 0.15f;
            break;
        }
    }

    float tr, tg, tb;
    switch (stateColor) {
        case 0: tr=0.30f; tg=1.00f; tb=0.30f; break;
        case 1: tr=1.00f; tg=0.85f; tb=0.20f; break;
        case 2: tr=1.00f; tg=0.20f; tb=0.15f; break;
        case 3: tr=0.30f; tg=0.90f; tb=1.00f; break;
        case 4: tr=1.00f; tg=0.55f; tb=0.15f; break;
        case 5: tr=0.85f; tg=0.35f; tb=0.95f; break;
        default: tr=tg=tb=1.f;
    }
    if (hueShift > 0.f) {
        float s = clampf(hueShift, 0.f, 0.6f);
        float r2 = tr*(1.f-s) + tb*s;
        float g2 = tg*(1.f-s) + tr*s*0.6f;
        float b2 = tb*(1.f-s) + tg*s*0.6f;
        tr = r2; tg = g2; tb = b2;
    }

    float pulse = 0.5f + 0.5f * sinf(t * pulseRate);
    float baseAlpha = (0.35f + 0.55f * pulse) * alphaMul;
    if (flicker > 0.01f && xrng_f() < flicker * 0.3f) baseAlpha *= 0.15f;

    float cornerSize = 300.f;
    float edgeThick  = 32.f;
    float bxp = biasX * cornerSize;
    float byp = biasY * cornerSize;

    hud_quad(bxp, (float)vh + byp, cornerSize, -cornerSize,
             v4(tr, tg, tb, baseAlpha * 0.95f), 253);
    hud_quad((float)vw + bxp, (float)vh + byp, -cornerSize, -cornerSize,
             v4(tr, tg, tb, baseAlpha * 0.95f), 253);
    hud_quad(bxp, byp, cornerSize, cornerSize,
             v4(tr, tg, tb, baseAlpha * 0.95f), 253);
    hud_quad((float)vw + bxp, byp, -cornerSize, cornerSize,
             v4(tr, tg, tb, baseAlpha * 0.95f), 253);
    hud_line(edgeThick, edgeThick, (float)vw - edgeThick, edgeThick, 3.f,
             v4(tr, tg, tb, baseAlpha * 0.55f), 254);
    hud_line(edgeThick, (float)vh - edgeThick, (float)vw - edgeThick,
             (float)vh - edgeThick, 3.f,
             v4(tr, tg, tb, baseAlpha * 0.55f), 254);
    hud_line(edgeThick, edgeThick, edgeThick, (float)vh - edgeThick, 3.f,
             v4(tr, tg, tb, baseAlpha * 0.55f), 254);
    hud_line((float)vw - edgeThick, edgeThick, (float)vw - edgeThick,
             (float)vh - edgeThick, 3.f,
             v4(tr, tg, tb, baseAlpha * 0.55f), 254);
}



static float ship_health_fraction(uint32_t ship_slot) {
    ShipDataExt* ext = ship_ext(ship_slot);
    if (!ext) return 1.f;
    float worst = 1.f;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (n->structural_hp <= 0.f) continue;
        float f = n->current_hp / n->structural_hp;
        if (f < worst) worst = f;
    }
    return worst;
}

static void drawNavigationComputer(int vw, int vh) {
    const int MAX_H = 16;
    const char* keys[MAX_H];
    const char* labels[MAX_H];
    int n = collectActiveHints(keys, labels, MAX_H);
    if (n == 0 && g_game.zones_visited < 2) return;

    float panelW = 260.f;
    float panelH = 200.f;
    float px = 20.f;
    float py = 20.f;

    hud_quad(px, py, panelW, panelH, v4(0.02f, 0.04f, 0.07f, 0.82f), 300);
    hud_line(px, py, px + panelW, py, 1.5f,
             v4(0.2f, 0.35f, 0.5f, 0.9f), 301);
    hud_line(px, py + panelH, px + panelW, py + panelH, 1.5f,
             v4(0.2f, 0.35f, 0.5f, 0.9f), 301);
    hud_line(px, py, px, py + panelH, 1.5f,
             v4(0.2f, 0.35f, 0.5f, 0.9f), 301);
    hud_line(px + panelW, py, px + panelW, py + panelH, 1.5f,
             v4(0.2f, 0.35f, 0.5f, 0.9f), 301);

    text_push(px + 10.f, py + panelH - 16.f, 12.f,
              v4(0.5f, 0.9f, 1.f, 1.f), "NAV COMPUTER");

    float lineH = 14.f;
    int maxVisible = (int)((panelH - 40.f) / lineH);
    int showN = (n < maxVisible) ? n : maxVisible;
    for (int i = 0; i < showN; i++) {
        float y = py + panelH - 34.f - i * lineH;
        text_push(px + 10.f, y, 11.f, v4(1.f, 0.9f, 0.3f, 1.f), keys[i]);
        text_push(px + 80.f, y, 11.f, v4(0.85f, 0.85f, 0.85f, 1.f), labels[i]);
    }
    (void)vw; (void)vh;
}

static void text_push(float x, float y, float size, V4 c, const char* s) {
    hud_text_push(x, y, size, c, s);
}

static int collectActiveHints(const char** keys, const char** labels, int maxH) {
    int n = 0;
    #define HINT(K, L) do { if (n < maxH) { keys[n]=(K); labels[n]=(L); n++; } } while (0)
    if (g_game.paused) {
        HINT("ESC", "resume"); HINT("UP/DN", "navigate"); HINT("ENTER", "select");
    } else if (g_game.docked) {
        HINT("ENTER", "buy"); HINT("N", "missions"); HINT("P", "repair");
        HINT("F/ESC", "undock");
    } else if (g_player.mode == PLAYER_MODE_ON_FOOT) {
        HINT("WASD", "move"); HINT("E", "interact"); HINT("R", "repair");
        HINT("Ctrl", "crouch"); HINT("Space", "jump"); HINT("Shift", "sprint");
    } else if (g_player.mode == PLAYER_MODE_EVA) {
        HINT("WASD", "thrust"); HINT("Space/Ctrl", "up/down");
        HINT("E", "board"); HINT("Shift", "sprint");
    } else if (g_player.mode == PLAYER_MODE_PILOT) {
        HINT("WASD", "fly"); HINT("LMB", "fire"); HINT("RMB", "mine");
        HINT("X", "free-aim"); HINT("Z", "travel"); HINT("N", "scan");
        HINT("C", "camo"); HINT("H", "hyperjump"); HINT("F", "dock");
        HINT("SHIFT+F", "jump"); HINT("ESC", "pause");
    }
    #undef HINT
    return n;
}

static void drawSphericalMap(float cx, float cy, float radius) {
    if (g_game.zones_visited == 0) return;
    float t = (float)time_get() * 0.0004f;
    hud_line(cx - radius, cy, cx + radius, cy, 1.f,
             v4(0.25f, 0.4f, 0.6f, 1.f), 350);
    hud_line(cx, cy - radius, cx, cy + radius, 1.f,
             v4(0.25f, 0.4f, 0.6f, 1.f), 350);
    float ring_r = radius * 0.92f;
    for (int seg = 0; seg < 32; seg++) {
        float a0 = TAU_F * seg / 32.f;
        float a1 = TAU_F * (seg + 1) / 32.f;
        hud_line(cx + cosf(a0) * ring_r, cy + sinf(a0) * ring_r,
                 cx + cosf(a1) * ring_r, cy + sinf(a1) * ring_r,
                 1.f, v4(0.25f, 0.4f, 0.6f, 1.f), 350);
    }
    for (int zi = 0; zi < 16; zi++) {
        int32_t gx = g_game.zone_coords[0];
        if (zi == 8) {
            /* current zone center */
            hud_quad(cx - 3.f, cy - 3.f, 6.f, 6.f,
                     v4(1.f, 1.f, 0.3f, 1.f), 351);
            continue;
        }
        if ((zi % 2) != 0) continue;
        float theta = TAU_F * (float)(zi - 8) / 16.f + t;
        float dist  = 0.5f + 0.4f * ((float)(zi % 3) / 3.f);
        float px = cx + cosf(theta) * dist * radius;
        float py = cy + sinf(theta) * dist * radius;
        V4 col = (zi == 8) ? v4(1.f, 1.f, 0.3f, 1.f)
                          : v4(0.7f, 0.9f, 1.f, 0.85f);
        hud_quad(px - 2.f, py - 2.f, 4.f, 4.f, col, 351);
        (void)gx;
    }
}

static void drawTablet(void) {
    int vw = win_w(), vh = win_h();
    hud_quad(0, 0, (float)vw, (float)vh, v4(0.02f, 0.03f, 0.06f, 0.92f), 290);
    char buf[200];
    text_push(40, (float)vh - 30, 14.f, v4(0.5f, 1.f, 0.7f, 1.f),
                "TABLET  —  T to close");
    snprintf(buf, sizeof(buf),
             "MAT POOL %u  ZONE [%d,%d,%d]  SEED %08X",
             g_matpool.count,
             g_game.zone_coords[0], g_game.zone_coords[1], g_game.zone_coords[2],
             g_game.zone_seed);
    text_push(40, (float)vh - 60, 12.f, v4(0.7f, 0.9f, 1.f, 1.f), buf);

    /* Base materials */
    text_push(40, (float)vh - 100, 14.f, v4(0.5f, 1.f, 0.7f, 1.f),
                "MATERIALS (top 12)");
    for (int i = 0; i < 12 && i < (int)g_matpool.count; i++) {
        Material* m = &g_matpool.cache[i];
        hud_quad(40, (float)vh - 130 - i * 18.f, 12.f, 12.f, m->color, 300);
        snprintf(buf, sizeof(buf), "%s  w=%.1f  r=%.2f  tags=0x%02X",
                 m->name ? m->name : "?", m->weight, m->rarity, m->tag_mask);
        text_push(60, (float)vh - 130 - i * 18.f, 11.f,
                    v4(0.9f, 0.9f, 0.9f, 1.f), buf);
    }

    /* Ship components */
    ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
    if (sd) {
        text_push(500, (float)vh - 100, 14.f, v4(0.5f, 1.f, 0.7f, 1.f),
                    "SHIP COMPONENTS");
        const char* cn[] = { "HULL", "ENG", "WPN", "SHD" };
        for (int i = 0; i < COMP_COUNT; i++) {
            ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[i]);
            if (!cd) continue;
            snprintf(buf, sizeof(buf), "%s  %.0f/%.0f  status=%u",
                     cn[i], cd->hp, cd->maxhp, cd->status);
            text_push(500, (float)vh - 130 - i * 18.f, 11.f,
                        v4(0.9f, 0.9f, 0.9f, 1.f), buf);
        }
    }

    /* Inventory (ship) */
    ShipDataExt* ext = ship_ext(g_game.player_ship_slot);
    if (ext) {
        text_push(500, (float)vh - 230, 14.f, v4(0.5f, 1.f, 0.7f, 1.f),
                    "INVENTORY");
        for (int i = 0; i < ext->inventory.count && i < 10; i++) {
            InventoryItem* it = &ext->inventory.items[i];
            snprintf(buf, sizeof(buf), "%08X x%u tier=%u",
                     it->bp.seed, it->qty, it->bp.tier);
            text_push(500, (float)vh - 260 - i * 16.f, 11.f,
                        v4(0.85f, 0.85f, 0.85f, 1.f), buf);
        }
    }
}

static float env_factor_at(V3 pos) {
    float factor = 0.f;
    uint32_t* nearby;
    uint32_t n = sh_query_dyn(pos, 100.f, g_things_cap, &nearby);
    for (uint32_t i = 0; i < n; i++) {
        Thing* t = &g_things[nearby[i]];
        if (t->type == ET_STAR) factor += 0.05f;
        if (t->type == ET_ANOMALY) {
            uint32_t at = ENT_I(t, 0);
            if (at == ANOMALY_TYPE_JITTER)    factor -= 0.15f;
            if (at == ANOMALY_TYPE_KILLER)    factor -= 0.20f;
            if (at == ANOMALY_TYPE_ATTRACTOR) factor -= 0.10f;
        }
        if (t->type == ET_FIELD && ENT_I(t, 0) == FIELD_TYPE_HEAL) factor += 0.10f;
    }
    sh_scratch_release();
    return clampf(factor, -0.3f, 0.3f);
}

static void hints_tick(float dt) {
    (void)dt;
    if (g_game.paused || g_game.docked) return;
    if (!g_hints.entered_cockpit && g_player.mode == PLAYER_MODE_PILOT) {
        hint_trigger("Press E to leave the seat");
        g_hints.entered_cockpit = 1;
    }
    if (!g_hints.walked_on_foot && g_player.mode == PLAYER_MODE_ON_FOOT) {
        hint_trigger("E interact | R repair | Ctrl crouch | Space jump");
        g_hints.walked_on_foot = 1;
    }
    if (!g_hints.saw_first_crew && g_crew_count > 0
        && g_player.mode == PLAYER_MODE_ON_FOOT) {
        hint_trigger("Crew aboard — allies");
        g_hints.saw_first_crew = 1;
    }
    if (!g_hints_seen_computer && g_player.mode == PLAYER_MODE_ON_FOOT
        && g_player.inside_ship != UINT32_MAX) {
        ShipDataExt* ext = ship_ext(g_player.inside_ship);
        if (ext) {
            for (int i = 0; i < ext->node_count; i++) {
                if (!(ext->nodes[i].props_mask & NODE_PROP_COMPUTER_ROOM)) continue;
                float d2 = v3lensq(v3sub(ext->nodes[i].pos_local,
                                          g_player.walker.pos_local));
                if (d2 < 4.f) {
                    hint_trigger("Press E at a LAB to mix");
                    g_hints_seen_computer = 1;
                    break;
                }
            }
        }
    }
    if (!g_hints.deployed_drone) {
        ShipDataExt* ext = ship_ext(g_game.player_ship_slot);
        if (ext && ext->drone_count_ship > 0) {
            hint_trigger("Drone active — T command repair, Shift+R recall");
            g_hints.deployed_drone = 1;
        }
    }
    if (!g_hints.collected_first_mat) {
        ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
        if (sd) {
            for (int i = 0; i < MATERIAL_COUNT; i++) {
                if (sd->matinv[i] > 0) {
                    hint_trigger("Resources in inventory — R repairs nodes");
                    g_hints.collected_first_mat = 1;
                    break;
                }
            }
        }
    }
}

static void hint_trigger(const char* text) {
    if (!text) return;
    g_active_hint.text = text;
    g_active_hint.remaining = HINT_DURATION;
    g_active_hint.shown = 1;
}

static void hud_cockpit_frame(int vw, int vh) {
    if (!g_settings.cockpitFrame) return;
    if (vw < 100 || vh < 100) return;
    float sx = (float)vw / 1920.f;
    float sy = (float)vh / 1080.f;
    float edge = 32.f;
    V4 ec = v4(0.03f, 0.04f, 0.06f, 0.75f);
    V4 cc = v4(0.05f, 0.07f, 0.10f, 0.82f);
    hud_quad(0, 0, (float)vw, edge * sy, ec, 250);
    hud_quad(0, (float)vh - edge * sy, (float)vw, edge * sy, ec, 250);
    hud_quad(0, edge * sy, edge * sx, (float)vh - edge * sy * 2.f, ec, 250);
    hud_quad((float)vw - edge * sx, edge * sy, edge * sx,
             (float)vh - edge * sy * 2.f, ec, 250);
    float corner = 220.f * sx;
    hud_quad(edge * sx, edge * sy, corner * 0.55f, 20.f * sy, cc, 251);
    hud_quad((float)vw - edge * sx - corner * 0.55f, edge * sy,
             corner * 0.55f, 20.f * sy, cc, 251);
    hud_quad(edge * sx, (float)vh - edge * sy - 20.f * sy,
             corner * 0.55f, 20.f * sy, cc, 251);
    hud_quad((float)vw - edge * sx - corner * 0.55f,
             (float)vh - edge * sy - 20.f * sy, corner * 0.55f, 20.f * sy, cc, 251);
    V4 lc = v4(0.20f, 0.30f, 0.45f, 0.55f);
    hud_line(corner, edge * sy, (float)vw - corner, edge * sy, 1.f, lc, 252);
    hud_line(corner, (float)vh - edge * sy, (float)vw - corner,
             (float)vh - edge * sy, 1.f, lc, 252);
}

