static void hud_draw_drone_list(int vw, int vh) {
    float base_y = 100.f;
    float x = (float)vw - 200.f;
    int idx = 0;
    ShipDataExt* ext = ship_ext(g_game.player_ship_slot);
    if (ext) {
        for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
            uint32_t d = ext->drone_slots_ship[i];
            if (d == UINT32_MAX || !entity_alive(d)) continue;
            hud_draw_drone_row(d, idx, x, base_y, 0);
            idx++;
        }
    }
    for (int i = 0; i < MAX_DRONES_PER_SOURCE; i++) {
        uint32_t d = g_player.foot_drone_slots[i];
        if (d == UINT32_MAX || !entity_alive(d)) continue;
        hud_draw_drone_row(d, idx, x, base_y, 1);
        idx++;
    }
    (void)vh;
}

static void hud_draw_drone_row(uint32_t drone_slot, int display_idx,
                                 float x, float base_y, int is_foot) {
    Thing* d = entity_get(drone_slot);
    if (!d) return;
    uint32_t caps = ENT_I(d, 21);
    char caps_buf[16];
    int cs = 0;
    if (caps & DRONE_CAP_COMBAT) caps_buf[cs++] = 'C';
    if (caps & DRONE_CAP_REPAIR) caps_buf[cs++] = 'R';
    if (caps & DRONE_CAP_RECON)  caps_buf[cs++] = 'S';
    if (caps & DRONE_CAP_MINING) caps_buf[cs++] = 'M';
    if (caps & DRONE_CAP_CARGO)  caps_buf[cs++] = 'G';
    if (caps & DRONE_CAP_JAMMER) caps_buf[cs++] = 'J';
    caps_buf[cs] = '\0';
    char line[40];
    snprintf(line, sizeof(line), "%s%d [%s]",
             is_foot ? "f" : "F", display_idx + 1, caps_buf);
    V4 col = is_foot ? v4(0.7f, 0.9f, 1.f, 1.f) : v4(0.7f, 1.f, 0.7f, 1.f);
    text_push(x, base_y + display_idx * 16.f, 12.f, col, line);
}

