static void regime_tick(float dt) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i] || g_things[i].type != ET_REGIME) continue;
        RegimeData* rd = (RegimeData*)entity_side_ptr(i);
        if (!rd) continue;
        uint32_t fid = rd->flags & 0xFF;
        int32_t rep = player_rep_get(fid);
        if (rep >= 0) {
            rd->stability = fminf(1.f, rd->stability + 0.02f * dt);
        } else {
            rd->stability = fmaxf(0.f, rd->stability - 0.005f * dt * (float)(-rep / 100));
        }
    }
}

static void ship_evasive_maneuver_v2(uint32_t slot, float dt) {
    if (!input_held(ACT_EVASIVE)) return;
    Thing* s = entity_get(slot);
    if (!s) return;
    ShipData* sd = (ShipData*)entity_side_ptr(slot);
    if (!sd) return;
    EvasiveProfile ep = evasive_profile_compute(slot);
    if (ep.effectiveness < 0.1f) return;
    if (sd->energy <= 0.f) return;

    uint32_t* threats;
    uint32_t n = sh_query_dyn(s->pos, ep.range, g_things_cap, &threats);
    V3 away = v3zero();
    int count = 0;
    for (uint32_t i = 0; i < n; i++) {
        if (threats[i] == slot) continue;
        Thing* t = &g_things[threats[i]];
        int is_threat = 0;
        float weight = 1.f;
        if (t->type == ET_BULLET)  { is_threat = 1; weight = ep.hard_dodge ? 2.f : 1.f; }
        if (t->type == ET_ASTEROID && t->radius > 10.f) { is_threat = 1; weight = 1.2f; }
        if (t->type == ET_ALIEN || t->type == ET_PIRATE) { is_threat = 1; weight = 0.6f; }
        if (!is_threat) continue;
        V3 d = v3sub(s->pos, t->pos);
        float dl = v3len(d);
        if (dl < 0.01f) continue;
        weight *= clampf(1.f - dl / ep.range, 0.1f, 1.f);
        away = v3add(away, v3mul(v3mul(d, 1.f / dl), weight));
        count++;
    }
    sh_scratch_release();
    if (count == 0) return;
    away = v3norm(away);
    float thrust = (30.f + ep.effectiveness * 60.f) * dt;
    s->vel = v3add(s->vel, v3mul(away, thrust));
    sd->energy -= ep.energy_cost * dt;
    if (sd->energy < 0.f) sd->energy = 0.f;
}

static int ship_find_worst_damaged_node(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return -1;
    int best = -1;
    float best_frac = 1.f;
    for (int i = 0; i < ext->node_count; i++) {
        ShipNode* n = &ext->nodes[i];
        if (n->structural_hp <= 0.f) continue;
        float f = n->current_hp / n->structural_hp;
        if (f < best_frac) { best_frac = f; best = i; }
    }
    return best;
}

static void ship_grow_random_fuselage(uint32_t ship, int generations) {
    ShipDataExt* ext = ship_ext(ship);
    if (!ext) return;
    for (int g = 0; g < generations; g++) {
        if (ext->node_count == 0) break;
        if (ext->node_count >= SHIP_MAX_NODES - 2) break;
        int base = (int)(xrng_u32() % (uint32_t)ext->node_count);
        int port = morphology_pick_biased_port();
        if (ext->nodes[base].port_edge[port] != -1) {
            for (int p = 0; p < 6; p++) {
                if (ext->nodes[base].port_edge[p] == -1) { port = p; break; }
            }
            if (ext->nodes[base].port_edge[port] != -1) continue;
        }
        ship_attach_fuselage_at(ship, base, port);
    }
}

