static void throw_bomb_player(void) {
    if (g_b7_bomb_cd > 0.f) return;
    if (g_game.player_ship_slot == UINT32_MAX) return;
    ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (!sd || !ship) return;
    if (sd->matinv[0] < 2u) { notice_push("NEED 2 IRON"); return; }
    for (int i = 0; i < 8; i++) {
        int k = (g_b7_bomb_idx + i) % 8;
        if (g_b7_bombs[k].alive) continue;
        g_b7_bombs[k].alive = 1;
        g_b7_bombs[k].pos   = ship->pos;
        g_b7_bombs[k].life  = 2.5f;
        sd->matinv[0] -= 2u;
        g_b7_bomb_cd = 25.f;
        g_b7_bomb_idx = (k + 1) % 8;
        audio_sfx_shoot(ship->pos, WEAPON_MISSILE);
        return;
    }
}

