static uint32_t tower_spawn(V3 pos, uint32_t wk)  { return turret_spawn(pos, ET_TOWER, wk); }

static void turret_tick(float dt) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i]) continue;
        uint32_t type = g_things[i].type;
        if (type != ET_TOWER && type != ET_CANNON) continue;
        Thing* t = &g_things[i];
        if (t->flags & ENT_FLAG_MARKED_DEAD) continue;
        float cd = ENT_F(t, 2) - dt;
        if (cd > 0.f) { ENT_SET_F(t, 2, cd); continue; }
        uint32_t target = beh_find_nearest_enemy(i, ENT_F(t, 3));
        if (target == UINT32_MAX) { ENT_SET_F(t, 2, cd); continue; }
        Thing* tt = entity_get(target);
        V3 dir = v3norm(v3sub(tt->pos, t->pos));
        if (v3lensq(dir) < 0.01f) dir = v3(0, 0, 1);
        t->rot = atan2f(dir.x, dir.z);
        float bspeed = (type == ET_TOWER) ? 250.f : 220.f;
        projectile_spawn_ext(i, t->pos, v3mul(dir, bspeed),
                              ENT_F(t, 4), DMG_ENERGY, ENT_I(t, 0));
        ENT_SET_F(t, 2, (type == ET_TOWER) ? 1.5f : 0.6f);
    }
}

static uint32_t beh_find_nearest_enemy(uint32_t self, float range) {
    if (!entity_alive(self)) return UINT32_MAX;
    Thing* t = &g_things[self];
    uint32_t* buf;
    uint32_t n = sh_query_dyn(t->pos, range, g_things_cap, &buf);
    uint32_t best = UINT32_MAX;
    float best_d2 = range * range;
    for (uint32_t i = 0; i < n; i++) {
        uint32_t o = buf[i];
        if (!beh_is_enemy(self, o)) continue;
        float d2 = v3distsq(g_things[o].pos, t->pos);
        if (d2 < best_d2) { best_d2 = d2; best = o; }
    }
    sh_scratch_release();
    return best;
}

static void update_player_bombs(float dt) {
    if (g_b7_bomb_cd > 0.f) g_b7_bomb_cd -= dt;
    const float RADIUS = 40.f;
    for (int i = 0; i < 8; i++) {
        B7Bomb* b = &g_b7_bombs[i];
        if (!b->alive) continue;
        b->life -= dt;
        if (b->life > 0.f) continue;
        if (g_game.player_ship_slot != UINT32_MAX) {
            Thing* ship = entity_get(g_game.player_ship_slot);
            ShipData* sd = (ShipData*)entity_side_ptr(g_game.player_ship_slot);
            if (ship && sd) {
                float d = v3dist(ship->pos, b->pos);
                if (d < RADIUS) {
                    float heal = 30.f * (1.f - d / RADIUS);
                    for (uint32_t c = 0; c < COMP_COUNT; c++) {
                        ComponentData* cd = (ComponentData*)entity_side_ptr(sd->components_slot[c]);
                        if (!cd || cd->status == 2) continue;
                        cd->hp += heal;
                        if (cd->hp > cd->maxhp) cd->hp = cd->maxhp;
                    }
                }
            }
        }
        for (uint32_t j = 0; j < g_things_cap; j++) {
            if (!g_alive[j] || j == g_game.player_ship_slot) continue;
            Thing* o = &g_things[j];
            if (o->type == ET_SHIP) continue;
            float d = v3dist(o->pos, b->pos);
            if (d >= RADIUS) continue;
            float dmg = 30.f * (1.f - d / RADIUS);
            thing_hit_simple(0, j, dmg, DMG_PHYS, o->pos, v3(0, 1, 0));
        }
        audio_sfx_explosion(b->pos, 0);
        b->alive = 0;
    }
}

static uint32_t viscosity_spawn(V3 pos, float radius, float factor) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_VISCOSITY;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC | ENT_FLAG_NO_COLLIDE | ENT_FLAG_NO_INTEGRATE;
    t.pos    = pos;
    t.radius = radius;
    t.hp = t.maxhp = 1.f;
    t.mass   = 1.f;
    ENT_SET_F(&t, 0, clampf(factor, 0.1f, 1.0f));
    return entity_spawn(&t);
}

static void viscosity_tick(float dt) {
    for (uint32_t i = 0; i < g_things_cap; i++) {
        if (!g_alive[i] || g_things[i].type != ET_VISCOSITY) continue;
        Thing* v = &g_things[i];
        float factor = ENT_F(v, 0);
        uint32_t* nearby;
        uint32_t n = sh_query_dyn(v->pos, v->radius, g_things_cap, &nearby);
        for (uint32_t k = 0; k < n; k++) {
            uint32_t o = nearby[k];
            if (o == i) continue;
            Thing* ot = &g_things[o];
            if (!ot || (ot->flags & ENT_FLAG_STATIC)) continue;
            ot->vel = v3mul(ot->vel, 1.f - (1.f - factor) * dt);
        }
        sh_scratch_release();
    }
}

