static void zone_check_boundary(void) {
    Thing* ship = entity_get(g_game.player_ship_slot);
    if (!ship) return;

    /* Local zone frame: center at zone coords * step */
    float step = ZONE_HALF * 2.f;
    V3 center = v3((float)(g_game.zone_coords[0] * (int)step),
                    (float)(g_game.zone_coords[1] * (int)step),
                    (float)(g_game.zone_coords[2] * (int)step));
    V3 rel = v3sub(ship->pos, center);
    float jump_min = zone_jump_min_range();

    int dx = 0, dy = 0, dz = 0;
    /* hard boundary still ZONE_HALF in local axes */
    if (rel.x >  ZONE_HALF) dx =  1;
    if (rel.x < -ZONE_HALF) dx = -1;
    if (rel.y >  ZONE_HALF) dy =  1;
    if (rel.y < -ZONE_HALF) dy = -1;
    if (rel.z >  ZONE_HALF) dz =  1;
    if (rel.z < -ZONE_HALF) dz = -1;

    /* Soft ring: past jump_min along primary axis → pending jump (HYPERJUMP confirms) */
    float ax = fabsf(rel.x), ay = fabsf(rel.y), az = fabsf(rel.z);
    int soft = 0;
    int32_t sdx = 0, sdy = 0, sdz = 0;
    if (ax >= ay && ax >= az && ax > jump_min * 0.85f) {
        soft = 1; sdx = rel.x >= 0.f ? 1 : -1;
    } else if (az >= ay && az > jump_min * 0.85f) {
        soft = 1; sdz = rel.z >= 0.f ? 1 : -1;
    } else if (ay > jump_min * 0.85f) {
        soft = 1; sdy = rel.y >= 0.f ? 1 : -1;
    }
    if (soft) {
        g_zone_jump_pending_dx = sdx;
        g_zone_jump_pending_dy = sdy;
        g_zone_jump_pending_dz = sdz;
        if (g_zone_jump_notice_cd <= 0.f) {
            notice_push("JUMP CORRIDOR — HYPERJUMP to transit");
            g_zone_jump_notice_cd = 8.f;
        }
    } else {
        g_zone_jump_pending_dx = g_zone_jump_pending_dy = g_zone_jump_pending_dz = 0;
    }

    if (dx || dy || dz) {
        int32_t nx = g_game.zone_coords[0] + dx;
        int32_t ny = g_game.zone_coords[1] + dy;
        int32_t nz = g_game.zone_coords[2] + dz;
        zone_generate(nx, ny, nz);
        /* wrap ship into new local frame */
        ship->pos.x -= (float)dx * step;
        ship->pos.y -= (float)dy * step;
        ship->pos.z -= (float)dz * step;
        notice_push("ZONE TRANSIT");
        g_zone_jump_pending_dx = g_zone_jump_pending_dy = g_zone_jump_pending_dz = 0;
    }
}


/* ── adaptadores A↔B: spawns con la semántica de B sobre las firmas de A ── */
static uint32_t launcher_spawn_n(V3 pos, uint32_t count) {
    uint32_t M = LAUNCHER_SOURCE_COUNT_MAX;
    if (count < 1) count = 1;
    if (count > M) count = M;
    uint32_t seed = xrng_u32();
    seed = seed - (seed % M) + (count - 1);      /* A deriva source_count = 1 + seed %% MAX */
    return launcher_spawn(pos, seed);
}
static uint32_t anomaly_spawn_life(V3 pos, float radius, uint32_t atype, float strength, float life) {
    uint32_t s = anomaly_spawn(pos, atype, radius, strength);
    if (s != UINT32_MAX) { Thing* a = entity_get(s); if (a) a->life = life; }
    return s;
}
static uint32_t mission_spawn_at(V3 pos, uint32_t mtype, uint32_t ttype, uint32_t tmat, uint32_t tcount, float tl, uint32_t reward) {
    (void)tmat;
    uint32_t s = mission_spawn(mtype, ttype, tcount, tl, reward);
    if (s != UINT32_MAX) { Thing* m = entity_get(s); if (m) m->pos = pos; }
    return s;
}
static void zone_spawn_content_extras(int32_t zx, int32_t zy, int32_t zz, uint32_t seed) {
    uint64_t ox = g_xrng_x, oy = g_xrng_y;
    int og = g_xrng_gauss_valid;
    float os = g_xrng_gauss_spare;
    xrng_seed(seed ? seed : 1);

    int depth = abs((int)zx);
    int first = (zx == 0 && zy == 0 && zz == 0);
    uint8_t zone_owner = 0xFF;
    if (g_faction_count > 0) {
        zone_owner = (uint8_t)(xrng_u32() % g_faction_count);
        ZonePersist* zp = zone_db_find(zx, zy, zz);
        if (zp) zone_faction_set((uint32_t)(zp - g_zonedb.zones), zone_owner);
    }
    if (first || xrng_f() < 0.40f)
        launcher_spawn_n(zone_rand_pos_flat(60, 200), 3 + (uint32_t)xrng_int(4));
    if (first || xrng_f() < 0.30f)
        lanzadera_spawn(zone_rand_pos_flat(80, 250), xrng_u32());
    if (first || xrng_f() < 0.15f)
        forge_spawn(zone_rand_pos_flat(50, 150));
    if (zone_owner < g_faction_count && (first || xrng_f() < 0.25f))
        regime_spawn(zone_rand_pos_flat(100, 300), zone_owner,
                      (uint32_t)xrng_int(5), 0.05f + xrng_f() * 0.15f,
                      0.5f + xrng_f() * 0.4f);
    if (zone_owner < g_faction_count && (first || xrng_f() < 0.35f))
        ideology_spawn(zone_rand_pos_flat(100, 300), zone_owner,
                        (uint32_t)xrng_int(5), 0.4f + xrng_f() * 0.3f);
    {
        int n = first ? 2 : ((xrng_f() < 0.50f) ? 1 + xrng_int(2) : 0);
        for (int i = 0; i < n && g_faction_count > 0; i++) {
            uint32_t f = (zone_owner < g_faction_count)
                         ? zone_owner : (uint32_t)xrng_int((int)g_faction_count);
            social_spawn(zone_rand_pos_flat(80, 250), f,
                          (uint32_t)xrng_int(5), 20 + (uint32_t)xrng_int(200));
        }
    }
    if (first || xrng_f() < 0.20f)
        star_spawn(zone_rand_pos_flat(500, 900), 15.f + xrng_f() * 15.f,
                    0.8f + xrng_f() * 0.6f);
    {
        int n = first ? 2 : ((xrng_f() < 0.30f) ? 1 + xrng_int(3) : 0);
        for (int i = 0; i < n; i++)
            anomaly_spawn_life(zone_rand_pos_wide(200, 500), 8.f + xrng_f() * 12.f,
                           (uint32_t)xrng_int(ANOMALY_TYPE_COUNT),
                           0.8f + xrng_f() * 1.5f, 30.f + xrng_f() * 60.f);
    }
    if (depth >= 2 && xrng_f() < 0.15f) {
        int n = 1 + xrng_int(3);
        for (int i = 0; i < n; i++) {
            V3 p = zone_rand_pos_flat(150, 400);
            if (xrng_f() < 0.5f) tower_spawn(p, WEAPON_PULSE);
            else                 cannon_spawn(p, WEAPON_PULSE);
        }
    }
    if (xrng_f() < 0.40f) {
        int n = 1 + xrng_int(3);
        for (int i = 0; i < n; i++)
            wreck_spawn(zone_rand_pos_flat(100, 400), v3zero(), xrng_u32());
    }
    if (xrng_f() < 0.20f) capsule_spawn(zone_rand_pos_flat(100, 400), v3zero());
    if (xrng_f() < 0.15f)
        field_spawn(zone_rand_pos_wide(150, 400), 20.f + xrng_f() * 10.f,
                     (uint32_t)xrng_int(FIELD_TYPE_COUNT), 1.f,
                     40.f + xrng_f() * 20.f);
    if (xrng_f() < 0.10f)
        viscosity_spawn(zone_rand_pos_flat(200, 500), 15.f + xrng_f() * 10.f,
                         0.4f + xrng_f() * 0.3f);
    if (xrng_f() < 0.10f)
        density_spawn(zone_rand_pos_flat(200, 500), 20.f + xrng_f() * 15.f,
                       1.5f + xrng_f() * 2.f);
    {
        int n = first ? 2 : ((xrng_f() < 0.50f) ? 1 + xrng_int(2) : 0);
        for (int i = 0; i < n; i++) {
            V3 p = zone_rand_pos_flat(50, 200);
            uint32_t mt = (uint32_t)xrng_int(MISSION_TYPE_COUNT);
            uint32_t ttype = ET_ALIEN, tmat = 0, tcount = 3;
            float tl = 120.f;
            switch (mt) {
                case MISSION_TYPE_KILL:
                    ttype = (xrng_f() < 0.7f) ? ET_ALIEN : ET_PIRATE;
                    tcount = 2 + (uint32_t)xrng_int(5);
                    tl = 60.f + xrng_f() * 60.f;
                    break;
                case MISSION_TYPE_COLLECT:
                    tmat = (uint32_t)xrng_int(MATERIAL_COUNT);
                    tcount = 3 + (uint32_t)xrng_int(10);
                    tl = 120.f + xrng_f() * 60.f;
                    break;
                case MISSION_TYPE_DELIVER:
                    tmat = (uint32_t)xrng_int(MATERIAL_COUNT);
                    tcount = 2 + (uint32_t)xrng_int(3);
                    tl = 180.f;
                    break;
                default:
                    tcount = 1;
                    tl = 60.f + xrng_f() * 30.f;
                    break;
            }
            mission_spawn_at(p, mt, ttype, tmat, tcount, tl, 50 + (uint32_t)xrng_int(200));
        }
    }
    if (xrng_f() < 0.30f)
        contract_spawn(zone_rand_pos_flat(80, 250), (uint32_t)xrng_int(MATERIAL_COUNT),
                        3 + (uint32_t)xrng_int(5), 100 + (uint32_t)xrng_int(300));
    if (first || xrng_f() < 0.10f)
        tournament_spawn(zone_rand_pos_flat(200, 400), 3 + (uint32_t)xrng_int(3));

    g_xrng_x = ox; g_xrng_y = oy;
    g_xrng_gauss_valid = og; g_xrng_gauss_spare = os;
}

static V3 zone_rand_pos_flat(float min_r, float max_r) {
    float a = xrng_range(0.f, TAU_F);
    float d = xrng_range(min_r, max_r);
    return v3(cosf(a) * d, xrng_range(-10.f, 10.f), sinf(a) * d);
}

static void zone_faction_set(uint32_t zi, uint8_t fid) {
    if (zi < 256) g_zone_faction[zi] = fid;
}

static ZonePersist* zone_db_find(int32_t x, int32_t y, int32_t z) {
    for (uint32_t i = 0; i < g_zonedb.zone_count; i++) {
        ZonePersist* zp = &g_zonedb.zones[i];
        if (zp->x == x && zp->y == y && zp->z == z) return zp;
    }
    return NULL;
}

static uint32_t contract_spawn(V3 pos, uint32_t req_mat, uint32_t req_qty,
                                 uint32_t reward) {
    Thing t;
    entity_clear_template(&t);
    t.type   = ET_CONTRACT;
    t.flags  = ENT_FLAG_ALIVE | ENT_FLAG_STATIC | ENT_FLAG_NO_COLLIDE | ENT_FLAG_NO_INTEGRATE;
    t.pos    = pos;
    t.radius = 2.0f;
    t.hp = t.maxhp = 1.f;
    t.mass   = 1.f;
    uint32_t slot = entity_spawn(&t);
    if (slot == UINT32_MAX) return UINT32_MAX;
    ContractData* cd = (ContractData*)entity_attach_side(slot, SD_MISSION);
    if (!cd) { entity_destroy(slot); return UINT32_MAX; }
    cd->req_mat = req_mat;
    cd->req_qty = req_qty;
    cd->reward  = reward;
    return slot;
}

static V3 zone_rand_pos_wide(float min_r, float max_r) {
    float a = xrng_range(0.f, TAU_F);
    float d = xrng_range(min_r, max_r);
    return v3(cosf(a) * d, xrng_range(-100.f, 100.f), sinf(a) * d);
}

