/* ═══════════════════════════════════════════════════════════════════════
   GRAVEDAD POR GENERADORES · FLOTABILIDAD · APOYO EN PISOS IRREGULARES
   El marco de apoyo (up/xref/zref) generaliza el "arriba = +Y" original: con
   gravedad normal es la identidad, por lo que la física previa se conserva.
   ═══════════════════════════════════════════════════════════════════════ */

static V3 sup_map(const SupportState* s, V3 v) {
    return v3add(v3add(v3mul(s->xref, v.x), v3mul(s->up, v.y)), v3mul(s->zref, v.z));
}
static V3 sup_unmap(const SupportState* s, V3 v) {
    return v3(v3dot(v, s->xref), v3dot(v, s->up), v3dot(v, s->zref));
}
static V3 support_up(const WalkerState* w) { return (w && w->support.init) ? w->support.up : v3(0.f, 1.f, 0.f); }
static V3 support_forward(const WalkerState* w) {
    V3 d = walk_forward_dir(w->yaw, w->pitch);
    return w->support.init ? sup_map(&w->support, d) : d;
}
static void support_init(SupportState* s) {
    memset(s, 0, sizeof(*s));
    s->up = v3(0.f, 1.f, 0.f); s->xref = v3(1.f, 0.f, 0.f); s->zref = v3(0.f, 0.f, 1.f);
    s->init = 1; s->mode = SUP_GROUNDED; s->regime = GR_NORMAL; s->boots_energy = 1.f;
}

static void support_orient(SupportState* s, V3 up_t, float rate, float dt) {
    float c = clampf(v3dot(s->up, up_t), -1.f, 1.f);
    if (c > 0.99995f) return;
    float t = clampf(rate * dt, 0.f, 1.f);

    V3 nu;
    if (c < -0.9999f) {
        V3 cand = (fabsf(s->up.y) < 0.9f) ? v3(0.f, 1.f, 0.f) : v3(1.f, 0.f, 0.f);
        V3 perp = v3norm(v3cross(s->up, cand));
        if (v3lensq(perp) < 1e-6f) perp = v3(1.f, 0.f, 0.f);
        nu = v3norm(v3add(v3mul(s->up, 1.f - t), v3mul(perp, t)));
    } else {
        nu = v3norm(v3add(v3mul(s->up, 1.f - t), v3mul(up_t, t)));
    }

    V3 ax = v3cross(s->up, nu);
    float sn = v3len(ax), cs = v3dot(s->up, nu);
    if (sn > 1e-6f) {
        ax = v3mul(ax, 1.f / sn);
        V3* vs[2] = { &s->xref, &s->zref };
        for (int k = 0; k < 2; k++) {
            V3 v = *vs[k];
            *vs[k] = v3add(v3add(v3mul(v, cs), v3mul(v3cross(ax, v), sn)),
                           v3mul(ax, v3dot(ax, v) * (1.f - cs)));
        }
    }
    s->up = nu;

    V3 xr = v3sub(s->xref, v3mul(s->up, v3dot(s->xref, s->up)));
    if (v3lensq(xr) < 1e-4f)
        xr = v3sub(s->zref, v3mul(s->up, v3dot(s->zref, s->up)));
    if (v3lensq(xr) < 1e-4f) {
        V3 cand = (fabsf(s->up.x) < 0.9f) ? v3(1.f, 0.f, 0.f) : v3(0.f, 1.f, 0.f);
        xr = v3sub(cand, v3mul(s->up, v3dot(cand, s->up)));
    }
    s->xref = v3norm(xr);
    s->zref = v3norm(v3cross(s->up, s->xref));
}

/* ── generadores ── */
static uint32_t grav_ship_signature(const ShipDataExt* ext) {
    uint32_t h = 2166136261u ^ (uint32_t)ext->node_count;
    for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) {
        h = (h ^ ext->nodes[i].props_mask) * 16777619u;
        h = (h ^ (uint32_t)(int32_t)(ext->nodes[i].pos_local.y * 64.f)) * 16777619u;
    }
    return h;
}
static void gravgen_autogen(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot); Thing* t = entity_get(slot);
    if (!ext || !t) return;
    const float R = 26.f;
    int n = (int)ext->node_count; if (n > SHIP_MAX_NODES) n = SHIP_MAX_NODES;
    uint8_t covered[SHIP_MAX_NODES]; memset(covered, 0, sizeof(covered));
    int made = 0;
    while (made < 6 && g_gravgen_n < GRAVGEN_MAX) {
        int pick = -1;
        for (int i = 0; i < n && pick < 0; i++)
            if (!covered[i] && (ext->nodes[i].props_mask & NODE_PROP_GRAVGEN)) pick = i;
        for (int i = 0; i < n && pick < 0; i++)
            if (!covered[i] && (ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) pick = i;
        if (pick < 0) break;
        GravGen* g = &g_gravgens[g_gravgen_n++];
        memset(g, 0, sizeof(*g));
        g->ship = slot; g->node_idx = pick; g->alive = 1; g->enabled = 1; g->power = 1.f; g->target = 1.f;
        g->kind = GGK_PLANE; g->dir = v3(0.f, -1.f, 0.f); g->strength = 1.f;
        g->falloff = 1.5f; g->spin_up = 1.2f; g->spin_down = 2.5f; g->radius = R;
        g->damp = 0.6f;
        uint32_t h = t->seed * 2654435761u ^ ((uint32_t)pick * 40503u);
        if (slot != g_game.player_ship_slot) {
            if ((h >> 5) % 9 == 0)       g->strength = 0.4f;                         /* baja gravedad */
            else if ((h >> 11) % 31 == 0) { g->enabled = 0; g->power = 0.f; g->target = 0.f; }   /* generador apagado: nave en cero-g */
        }
        V3 c = ext->nodes[pick].pos_local;
        V3 lo = v3sub(c, ext->nodes[pick].half_ext), hi = v3add(c, ext->nodes[pick].half_ext);
        for (int i = 0; i < n; i++) {
            if (!(ext->nodes[i].props_mask & NODE_PROP_WALKABLE)) continue;
            if (v3dist(ext->nodes[i].pos_local, c) > R) continue;
            covered[i] = 1;
            V3 a = v3sub(ext->nodes[i].pos_local, ext->nodes[i].half_ext), b = v3add(ext->nodes[i].pos_local, ext->nodes[i].half_ext);
            lo = v3(fminf(lo.x, a.x), fminf(lo.y, a.y), fminf(lo.z, a.z));
            hi = v3(fmaxf(hi.x, b.x), fmaxf(hi.y, b.y), fmaxf(hi.z, b.z));
        }
        covered[pick] = 1;
        g->center = c;
        g->vmin = v3sub(lo, v3(0.5f, 0.5f, 0.5f)); g->vmax = v3add(hi, v3(0.5f, 0.5f, 0.5f));
        made++;
    }
}
static void gravgen_ensure(uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    uint32_t sig = grav_ship_signature(ext);
    int si = -1;
    for (int i = 0; i < g_grav_sig_n; i++) if (g_grav_sigs[i].slot == slot) { si = i; break; }
    if (si >= 0 && g_grav_sigs[si].sig == sig) return;
    struct { int node; uint8_t en; float tgt, pw; } keep[16]; int nk = 0;
    int w = 0;
    for (int i = 0; i < g_gravgen_n; i++) {
        if (g_gravgens[i].ship == slot) {
            if (nk < 16) { keep[nk].node = g_gravgens[i].node_idx; keep[nk].en = g_gravgens[i].enabled; keep[nk].tgt = g_gravgens[i].target; keep[nk].pw = g_gravgens[i].power; nk++; }
        } else g_gravgens[w++] = g_gravgens[i];
    }
    g_gravgen_n = w;
    gravgen_autogen(slot);
    for (int i = 0; i < g_gravgen_n; i++) {
        if (g_gravgens[i].ship != slot) continue;
        for (int k = 0; k < nk; k++)
            if (keep[k].node == g_gravgens[i].node_idx) { g_gravgens[i].enabled = keep[k].en; g_gravgens[i].target = keep[k].tgt; g_gravgens[i].power = keep[k].pw; }
    }
    if (si < 0 && g_grav_sig_n < 96) si = g_grav_sig_n++;
    if (si >= 0) { g_grav_sigs[si].slot = slot; g_grav_sigs[si].sig = sig; }
}
static void gravgen_set_ship(uint32_t slot, int enabled) {
    gravgen_ensure(slot);
    int cnt = 0;
    for (int i = 0; i < g_gravgen_n; i++)
        if (g_gravgens[i].ship == slot) { g_gravgens[i].enabled = (uint8_t)enabled; g_gravgens[i].target = enabled ? 1.f : 0.f; cnt++; }
    if (cnt) notice_push(enabled ? "GRAVITY ON" : "GRAVITY OFF");
}
static void gravgen_toggle_ship(uint32_t slot) {
    gravgen_ensure(slot);
    int any_on = 0;
    for (int i = 0; i < g_gravgen_n; i++) if (g_gravgens[i].ship == slot && g_gravgens[i].enabled) any_on = 1;
    gravgen_set_ship(slot, !any_on);
}
static void gravgen_tick_all(float dt) {
    for (uint32_t s = 0; s < g_things_cap; s++)
        if (g_alive[s] && g_things[s].type == ET_SHIP) gravgen_ensure(s);
    int w = 0;
    static float tacc = 0.f; tacc += dt;
    for (int i = 0; i < g_gravgen_n; i++) {
        GravGen* g = &g_gravgens[i];
        if (!entity_alive(g->ship)) continue;
        ShipDataExt* ext = ship_ext(g->ship);
        if (ext && g->node_idx < (int)ext->node_count) {
            const ShipNode* n = &ext->nodes[g->node_idx];
            float hp = n->structural_hp > 0.f ? clampf(n->current_hp / n->structural_hp, 0.f, 1.f) : 1.f;
            float tgt = g->enabled ? fminf(g->target, smoothstepf(0.f, 0.7f, hp)) : 0.f;
            float d = tgt - g->power;
            float step = d > 0.f ? dt / g->spin_up : dt / g->spin_down;
            g->power += clampf(d, -step, step);
            g->flicker = hp < 0.35f ? (0.35f - hp) * (0.5f + 0.5f * sinf(tacc * 37.f + (float)i)) : 0.f;
        }
        g->phase += g->omega * g->power * dt;
        g_gravgens[w++] = *g;
    }
    g_gravgen_n = w;
}
static void gravity_gen_contrib(const GravGen* g, V3 p, V3* out, float* damp, float* cover) {
    *out = v3(0.f, 0.f, 0.f); *damp = 1.f; *cover = 0.f;
    V3 d = v3(fmaxf(fmaxf(g->vmin.x - p.x, 0.f), p.x - g->vmax.x),
              fmaxf(fmaxf(g->vmin.y - p.y, 0.f), p.y - g->vmax.y),
              fmaxf(fmaxf(g->vmin.z - p.z, 0.f), p.z - g->vmax.z));
    float w = 1.f - smoothstepf(0.f, g->falloff, v3len(d));
    if (w <= 0.f) return;
    float pot = g->power * w * (1.f - g->flicker);
    float G0 = g_tuning.walker_gravity;
    switch (g->kind) {
        case GGK_PLANE:    *out = v3mul(g->dir, G0 * g->strength * pot); break;
        case GGK_RADIAL: { V3 r = v3sub(p, g->center); float l = v3len(r); if (l > 1e-3f) *out = v3mul(r, -G0 * g->strength * pot / l); break; }
        case GGK_SPIN: {   V3 r = v3sub(p, g->center); V3 rad = v3sub(r, v3mul(g->axis, v3dot(r, g->axis))); float l = v3len(rad);
                           if (l > 1e-3f) *out = v3mul(rad, g->omega * g->omega * pot);   /* centrífuga habitable */ break; }
        case GGK_DAMPENER: *damp = 1.f - pot * g->damp; break;
        case GGK_ZERO_VOL: *damp = 1.f - pot; break;
        case GGK_VORTEX: { V3 r = v3sub(p, g->center); V3 t = v3cross(g->axis, r); float l = v3len(t);
                           if (l > 1e-3f) *out = v3mul(t, G0 * g->strength * pot / l); break; }
    }
    *cover = w * g->power;
}
/* atracción exterior (estrellas/atractores) reutilizando la lógica original como aceleración */
static V3 gravity_world_pull_player(V3 p_local) {
    WalkerState tmp; memset(&tmp, 0, sizeof(tmp));
    tmp.pos_local = p_local;
    walker_apply_gravity(&tmp, 1.f);
    return tmp.vel_local;
}

static void gravity_sample_local(uint32_t slot, V3 p, GravSample* out) {
    gravgen_ensure(slot);
    V3 sum = v3(0.f, 0.f, 0.f); float damp = 1.f, cover = 0.f; int have = 0;
    for (int i = 0; i < g_gravgen_n; i++) {
        if (g_gravgens[i].ship != slot) continue;
        have = 1;
        V3 o; float dm, cv;
        gravity_gen_contrib(&g_gravgens[i], p, &o, &dm, &cv);
        sum = v3add(sum, o); damp *= dm; if (cv > cover) cover = cv;
    }
    V3 g = v3mul(sum, damp);
    if (!have) g = v3(0.f, -g_tuning.walker_gravity, 0.f);          /* nave sin generadores: gravedad original */
    if (slot == g_player.inside_ship) g = v3add(g, v3mul(gravity_world_pull_player(p), 1.f - cover * 0.85f));
    out->g = g; out->mag = v3len(g); out->cover = cover;
    out->up = out->mag > 1e-3f ? v3mul(g, -1.f / out->mag) : v3(0.f, 1.f, 0.f);
}

/* ── geometría de apoyo ── */
static int support_in_walkable(const ShipDataExt* ext, V3 p) {
    for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) {
        const ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        if (fabsf(p.x - n->pos_local.x) <= n->half_ext.x && fabsf(p.y - n->pos_local.y) <= n->half_ext.y && fabsf(p.z - n->pos_local.z) <= n->half_ext.z) return 1;
    }
    return 0;
}
/* distancia por la que un rayo sale de la unión de salas caminables que contienen o */
static int support_box_exit(const ShipDataExt* ext, V3 o, V3 dir, float* t_out) {
    float best = -1.f;
    for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) {
        const ShipNode* n = &ext->nodes[i];
        if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
        V3 lo = v3sub(n->pos_local, n->half_ext), hi = v3add(n->pos_local, n->half_ext);
        if (o.x < lo.x || o.x > hi.x || o.y < lo.y || o.y > hi.y || o.z < lo.z || o.z > hi.z) continue;
        float t = 1e9f;
        if (dir.x >  1e-6f) t = fminf(t, (hi.x - o.x) / dir.x); else if (dir.x < -1e-6f) t = fminf(t, (lo.x - o.x) / dir.x);
        if (dir.y >  1e-6f) t = fminf(t, (hi.y - o.y) / dir.y); else if (dir.y < -1e-6f) t = fminf(t, (lo.y - o.y) / dir.y);
        if (dir.z >  1e-6f) t = fminf(t, (hi.z - o.z) / dir.z); else if (dir.z < -1e-6f) t = fminf(t, (lo.z - o.z) / dir.z);
        if (t > best) best = t;
    }
    if (best < 0.f) return 0;
    *t_out = best; return 1;
}

static int support_sample(const ShipDataExt* ext, const SupportState* s,
                          V3 feet, float step_up, float reach,
                          float* h_out, V3* nrm_out) {
    const float R = 0.28f;
    V3 offs[5] = { v3(0.f, 0.f, 0.f),
                   v3mul(s->xref, R), v3mul(s->xref, -R),
                   v3mul(s->zref, R), v3mul(s->zref, -R) };
    float hh[5]; int ok[5]; int cnt = 0; float sum = 0.f;
    V3 down = v3mul(s->up, -1.f);
    for (int k = 0; k < 5; k++) {
        V3 o = v3add(v3add(feet, offs[k]), v3mul(s->up, step_up));
        float t;
        if (support_box_exit(ext, o, down, &t) && t <= step_up + reach) {
            hh[k] = step_up - t; ok[k] = 1; cnt++; sum += hh[k];
        } else { hh[k] = 0.f; ok[k] = 0; }
    }
    if (!cnt) return 0;
    float hc = ok[0] ? hh[0] : sum / (float)cnt;
    float dx = (ok[1] && ok[2]) ? (hh[1] - hh[2]) / (2.f * R) : 0.f;
    float dz = (ok[3] && ok[4]) ? (hh[3] - hh[4]) / (2.f * R) : 0.f;
    *nrm_out = v3norm(v3sub(v3sub(s->up, v3mul(s->xref, dx)), v3mul(s->zref, dz)));
    *h_out = hc;
    return cnt;
}

static int support_nearest_face(const ShipDataExt* ext, V3 p,
                                 float* d_out, V3* n_in) {
    static const V3 inw[6] = {
        { 1.f, 0.f, 0.f }, { -1.f, 0.f, 0.f },
        { 0.f, 1.f, 0.f }, { 0.f, -1.f, 0.f },
        { 0.f, 0.f, 1.f }, { 0.f, 0.f, -1.f }
    };
    for (int pass = 0; pass < 2; pass++) {
        float best = 1e9f; V3 bn = v3(0.f, 1.f, 0.f); int found = 0;
        for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) {
            const ShipNode* n = &ext->nodes[i];
            if (!(n->props_mask & NODE_PROP_WALKABLE)) continue;
            V3 lo = v3sub(n->pos_local, n->half_ext);
            V3 hi = v3add(n->pos_local, n->half_ext);
            if (p.x < lo.x || p.x > hi.x) continue;
            if (p.y < lo.y || p.y > hi.y) continue;
            if (p.z < lo.z || p.z > hi.z) continue;
            float dist[6] = { p.x - lo.x, hi.x - p.x,
                              p.y - lo.y, hi.y - p.y,
                              p.z - lo.z, hi.z - p.z };
            for (int f = 0; f < 6; f++) {
                if (dist[f] >= best) continue;
                if (pass == 0) {
                    V3 q = v3add(v3sub(p, v3mul(inw[f], dist[f])),
                                 v3mul(inw[f], -0.3f));
                    if (support_in_walkable(ext, q)) continue;
                }
                best = dist[f]; bn = inw[f]; found = 1;
            }
        }
        if (found) { *d_out = best; *n_in = bn; return 1; }
    }
    return 0;
}

static void walker_physics_support(WalkerState* w, uint32_t slot,
                                    const Intent* i, float dt) {
    Thing* ship = entity_get(slot); ShipDataExt* ext = ship_ext(slot);
    if (!ship || !ext) return;
    SupportState* s = &w->support;
    if (!s->init) support_init(s);

    w->yaw   += i->look_dx * 0.0030f;
    w->pitch -= i->look_dy * 0.0030f;
    w->pitch  = clampf(w->pitch, -1.45f, 1.45f);
    while (w->yaw >  PI_F) w->yaw -= TAU_F;
    while (w->yaw < -PI_F) w->yaw += TAU_F;
    player_apply_crouch(w, i->crouch, dt);
    w->aiming = i->fire_secondary ? 1 : 0;

    GravSample gs; gravity_sample_local(slot, w->pos_local, &gs);
    if (slot == g_player.inside_ship) g_player_grav = gs;

    const float G0 = g_tuning.walker_gravity;
    float ratio = G0 > 1e-4f ? gs.mag / G0 : 1.f;
    int reg;
    if (ratio < 0.12f)      reg = GR_ZERO;
    else if (ratio < 0.7f)  reg = GR_LOW;
    else if (ratio > 1.5f)  reg = GR_HIGH;
    else                    reg = GR_NORMAL;
    if (reg != s->regime) {
        if (reg == GR_ZERO) { notice_push("ZERO-G (CTRL: BOOTS)"); w->grounded = 0; }
        else if (s->regime == GR_ZERO) notice_push("GRAVITY RESTORED");
        s->regime = (uint8_t)reg;
    }

    /* Cooldown ANTES de decidir magnetic */
    s->boots_cd = fmaxf(0.f, s->boots_cd - dt);

    int magnetic = 0; V3 face_n = v3(0.f, 1.f, 0.f);
    if (reg == GR_ZERO && i->crouch && !i->jump
        && s->boots_cd <= 0.f && s->boots_energy > 0.f) {
        float fd; V3 fn;
        if (support_nearest_face(ext, w->pos_local, &fd, &fn) && fd < 1.4f) {
            magnetic = 1; face_n = fn;
        }
    }
    if (i->jump && magnetic) {
        s->boots_cd = 0.45f;
        magnetic = 0;
    }

    s->boots = (uint8_t)magnetic;
    s->boots_energy = clampf(s->boots_energy
                              + (magnetic ? -0.04f : 0.08f) * dt, 0.f, 1.f);

    float speed = g_tuning.walker_speed;
    if (i->sprint && !i->crouch) speed *= WALK_SPRINT_MUL;
    if (i->crouch)               speed *= 0.5f;
    if (w->aiming)               speed *= 0.65f;
    float cy = cosf(w->yaw), sy = sinf(w->yaw);
    float vx = sy * (i->throttle * speed) + cy * (i->strafe * speed * 0.5f);
    float vz = -cy * (i->throttle * speed) + sy * (i->strafe * speed * 0.5f);

    if (reg == GR_ZERO && !magnetic) {
        s->mode = SUP_FLOATING; w->grounded = 0; w->jumping = 0;
        V3 fwd = support_forward(w);
        V3 right = sup_map(s, v3(cy, 0.f, sy));
        float th = 7.f * ((i->sprint) ? 1.8f : 1.f);
        V3 acc = v3add(v3add(v3mul(fwd, i->throttle),
                             v3mul(right, i->strafe * 0.6f)),
                       v3mul(s->up, i->jump ? 1.f : 0.f));
        w->vel_local = v3add(w->vel_local, v3mul(acc, th * dt));
        w->vel_local = v3mul(w->vel_local, fmaxf(0.f, 1.f - 0.35f * dt));
    } else {
        V3 up_t = magnetic ? face_n : (gs.mag > 1e-3f ? gs.up : s->up);
        float gm = magnetic ? G0 : gs.mag;
        float rr = magnetic ? 1.f : ratio;
        support_orient(s, up_t, 6.f * (magnetic ? 1.2f : 1.f), dt);
        V3 vl = sup_unmap(s, w->vel_local);
        if (i->jump && w->grounded && !i->crouch) {
            vl.y = g_tuning.walker_jump_vel
                   * clampf(1.f / sqrtf(fmaxf(rr, 0.25f)), 0.7f, 2.f);
            if (magnetic) vl.y = 3.5f;
            w->grounded = 0; w->jumping = 1;
        }
        if (w->grounded && w->jumping) w->jumping = 0;
        if (w->grounded) {
            if (fabsf(vx) > 0.001f || fabsf(vz) > 0.001f) { vl.x = vx; vl.z = vz; }
            else {
                float damp = fmaxf(0.f, 1.f - 8.f * dt);
                vl.x *= damp; vl.z *= damp;
                if (fabsf(vl.x) < 0.05f) vl.x = 0.f;
                if (fabsf(vl.z) < 0.05f) vl.z = 0.f;
            }
        } else {
            float dx = vx - vl.x, dz = vz - vl.z;
            float dl = sqrtf(dx * dx + dz * dz), ac = 8.f * dt;
            if (dl > ac && dl > 0.001f) { dx = dx * ac / dl; dz = dz * ac / dl; }
            vl.x += dx; vl.z += dz;
            vl.y -= gm * dt;
            if (vl.y < -60.f) vl.y = -60.f;
        }
        w->vel_local = sup_map(s, vl);
    }

    walker_apply_inertia(w, slot, dt);
    walker_apply_centrifugal(w, slot, dt);
    walker_apply_shake(w, dt);

    V3 next = v3add(w->pos_local, v3mul(w->vel_local, dt));

    if (s->mode != SUP_FLOATING || magnetic) {
        float vy = v3dot(w->vel_local, s->up);
        float reach = 0.14f + fmaxf(0.f, -vy) * dt + 0.05f;
        const float STEP_UP = 0.45f;
        float step = magnetic ? 0.f : STEP_UP;
        float h; V3 nrm;
        int hit = support_sample(ext, s, next, step, reach, &h, &nrm);
        if (hit && vy <= 0.05f
            && h >= -(0.12f + fmaxf(0.f, -vy) * dt)
            && h <= STEP_UP) {
            float k = fabsf(h) > 0.02f ? fminf(1.f, 18.f * dt) : 1.f;
            next = v3add(next, v3mul(s->up, h * k));
            w->vel_local = v3sub(w->vel_local, v3mul(s->up, v3dot(w->vel_local, s->up)));
            w->grounded = 1;
            s->slope_deg = magnetic ? 0.f
                : acosf(clampf(v3dot(nrm, s->up), -1.f, 1.f)) * 57.29578f;
            s->mode = magnetic ? SUP_MAGNETIC : SUP_GROUNDED;
            if (s->slope_deg > 50.f) {
                V3 tang = v3norm(v3sub(s->up, v3mul(nrm, v3dot(s->up, nrm))));
                w->vel_local = v3add(w->vel_local,
                    v3mul(tang, G0 * sinf(s->slope_deg * 0.017453f) * dt));
                s->mode = SUP_SLIDING;
            }
        } else { w->grounded = 0; s->mode = SUP_AIRBORNE; }
    }

    V3 resolved;
    walker_collide(slot, w->pos_local, next, &resolved);
    if (s->mode == SUP_FLOATING && v3dist(resolved, next) > 1e-4f)
        w->vel_local = v3mul(w->vel_local, 0.4f);
    w->pos_local = resolved;
    w->vel_y = v3dot(w->vel_local, s->up);
    w->last_ship_vel_world = ship->vel;
    w->last_ship_rot       = ship->rot;
    walker_decay_hurt_shake(w);
    player_apply_bob(w, i->crouch, dt);
}

/* ═══════════════════════════════════════════════════════════════════════
   GUI: REFERENCIAS DE CASCO (transparencias flotantes) Y DE ÁMBITO (pantallas)
   Sin shaders nuevos: se proyecta con project_screen y se dibuja con las
   primitivas 2D existentes (hud_quad/hud_line/hud_text_push).
   ═══════════════════════════════════════════════════════════════════════ */
#define C4(r, g, b, a) V4{ (r), (g), (b), (a) }
static int g_screen_active = -1;

static void gui_line3(V3 a, V3 b, V4 c) {
    float x0, y0, x1, y1;
    if (!project_screen(a, g_game.cam.vp, &x0, &y0, g_win_w, g_win_h)) return;
    if (!project_screen(b, g_game.cam.vp, &x1, &y1, g_win_w, g_win_h)) return;
    hud_line(x0, y0, x1, y1, 1.2f, c, 3);
}
static V4 gui_hp_color(float hp, float a) {
    return C4(1.f - 0.7f * hp, 0.35f + 0.6f * hp, 0.35f, a);
}
static void hullref_draw_ship(uint32_t slot, float alpha) {
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    gravgen_ensure(slot);
    float placed[24][2]; int np = 0;
    for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) {
        const ShipNode* n = &ext->nodes[i];
        float hp = n->structural_hp > 0.f ? clampf(n->current_hp / n->structural_hp, 0.f, 1.f) : 1.f;
        V4 col = gui_hp_color(hp, alpha * (hp < 0.5f ? 1.f : 0.55f));
        V3 c = n->pos_local, h = n->half_ext;
        V3 p[8];
        for (int k = 0; k < 8; k++)
            p[k] = local_to_world_pos(slot, v3(c.x + ((k & 1) ? h.x : -h.x), c.y + ((k & 2) ? h.y : -h.y), c.z + ((k & 4) ? h.z : -h.z)));
        static const int E[12][2] = { {0,1},{2,3},{4,5},{6,7},{0,2},{1,3},{4,6},{5,7},{0,4},{1,5},{2,6},{3,7} };
        for (int e = 0; e < 12; e++) gui_line3(p[E[e][0]], p[E[e][1]], col);
        /* etiquetas: generador de gravedad y daño */
        char tag[40] = ""; int is_gen = 0; float pw = 0.f;
        for (int g = 0; g < g_gravgen_n; g++)
            if (g_gravgens[g].ship == slot && g_gravgens[g].node_idx == (int)i) { is_gen = 1; pw = g_gravgens[g].power; }
        if (is_gen) snprintf(tag, sizeof(tag), "GRAV %d%%", (int)(pw * 100.f));
        else if (hp < 0.5f) snprintf(tag, sizeof(tag), "HP %d%%", (int)(hp * 100.f));
        if (tag[0]) {
            float sx, sy;
            if (project_screen(local_to_world_pos(slot, c), g_game.cam.vp, &sx, &sy, g_win_w, g_win_h)) {
                int clash = 0;
                for (int q = 0; q < np; q++) if (fabsf(placed[q][0] - sx) < 60.f && fabsf(placed[q][1] - sy) < 14.f) clash = 1;
                if (!clash && np < 24) {
                    placed[np][0] = sx; placed[np][1] = sy; np++;
                    hud_quad(sx - 34.f, sy - 8.f, 68.f, 14.f, C4(0.f, 0.05f, 0.1f, 0.55f * alpha), 3);
                    text_push_centered(sx, sy - 7.f, 10.f, is_gen ? C4(0.5f, 0.9f, 1.f, alpha) : gui_hp_color(hp, alpha), tag);
                }
            }
        }
    }
}
static void hullref_draw(void) {
    if (g_hullref_mode <= 0) return;
    uint32_t own = (g_player.mode == PLAYER_MODE_ON_FOOT || g_player.mode == PLAYER_MODE_PLATFORM) ? g_player.inside_ship : g_game.player_ship_slot;
    if (own != UINT32_MAX && entity_alive(own)) hullref_draw_ship(own, 0.85f);
    if (g_hullref_mode >= 2) {
        uint32_t best = UINT32_MAX; float bd = 400.f;
        for (uint32_t s = 0; s < g_things_cap; s++) {
            if (!g_alive[s] || g_things[s].type != ET_SHIP || s == own) continue;
            float d = v3dist(g_things[s].pos, g_game.cam.pos);
            if (d < bd) { bd = d; best = s; }
        }
        if (best != UINT32_MAX) hullref_draw_ship(best, 0.5f);
    }
}

/* pantallas ancladas a nodos (cabina, sala de cómputo, genérico): panel translúcido con contenido por página */
static void screen_page_ship(float x0, float y0, float sc, uint32_t slot) {
    ShipDataExt* ext = ship_ext(slot);
    float tot = 0.f, mx = 0.f;
    if (ext) for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) { tot += ext->nodes[i].current_hp; mx += ext->nodes[i].structural_hp; }
    hud_text_push(x0 + 8.f * sc, y0 + 6.f * sc, 11.f * sc, C4(0.5f, 0.9f, 1.f, 1.f), "SHIP STATUS");
    hud_bar(x0 + 8.f * sc, y0 + 24.f * sc, 150.f * sc, 8.f * sc, mx > 0.f ? tot / mx : 0.f, C4(0.3f, 1.f, 0.5f, 0.9f), C4(0.1f, 0.15f, 0.15f, 0.6f));
    static const char* RG[4] = { "NORMAL", "LOW-G", "ZERO-G", "HIGH-G" };
    char b[64]; snprintf(b, sizeof(b), "GRAV %s  %.1f m/s2", RG[g_player.walker.support.regime & 3], g_player_grav.mag);
    hud_text_push(x0 + 8.f * sc, y0 + 38.f * sc, 9.f * sc, C4(0.9f, 0.9f, 0.6f, 1.f), b);
    int row = 0;
    for (int g = 0; g < g_gravgen_n && row < 4; g++) {
        if (g_gravgens[g].ship != slot) continue;
        snprintf(b, sizeof(b), "GEN %d %s", row + 1, g_gravgens[g].enabled ? "ON" : "OFF");
        hud_text_push(x0 + 8.f * sc, y0 + (54.f + row * 14.f) * sc, 9.f * sc, C4(0.7f, 0.9f, 1.f, 1.f), b);
        hud_bar(x0 + 70.f * sc, y0 + (55.f + row * 14.f) * sc, 80.f * sc, 6.f * sc, g_gravgens[g].power, C4(0.4f, 0.8f, 1.f, 0.9f), C4(0.1f, 0.1f, 0.2f, 0.6f));
        row++;
    }
    hud_text_push(x0 + 8.f * sc, y0 + 118.f * sc, 8.f * sc, C4(0.6f, 0.7f, 0.7f, 0.9f), "F5 GRAVITY  F4 HULL REF");
}
static void screen_page_nav(float x0, float y0, float sc) {
    hud_text_push(x0 + 8.f * sc, y0 + 6.f * sc, 11.f * sc, C4(0.5f, 0.9f, 1.f, 1.f), "NAVIGATION");
    char b[64]; snprintf(b, sizeof(b), "ZONE %d %d %d", g_game.zone_coords[0], g_game.zone_coords[1], g_game.zone_coords[2]);
    hud_text_push(x0 + 8.f * sc, y0 + 24.f * sc, 10.f * sc, C4(0.9f, 0.9f, 0.6f, 1.f), b);
    hud_text_push(x0 + 8.f * sc, y0 + 40.f * sc, 8.f * sc, C4(0.6f, 0.7f, 0.7f, 0.9f), "Z TRAVEL   SHIFT+H HYPERJUMP");
}
static void screen_page_computer(float x0, float y0, float sc) {
    hud_text_push(x0 + 8.f * sc, y0 + 6.f * sc, 11.f * sc, C4(0.5f, 0.9f, 1.f, 1.f), "COMPUTER");
    hud_text_push(x0 + 8.f * sc, y0 + 26.f * sc, 9.f * sc, C4(0.8f, 0.9f, 0.8f, 1.f), "F7 EXTRACT");
    hud_text_push(x0 + 8.f * sc, y0 + 40.f * sc, 9.f * sc, C4(0.8f, 0.9f, 0.8f, 1.f), "F8 ASSIGN DRONES");
    hud_text_push(x0 + 8.f * sc, y0 + 54.f * sc, 9.f * sc, C4(0.8f, 0.9f, 0.8f, 1.f), "F9 STORE BUNDLE");
}
static void screens_draw(void) {
    uint32_t slot = (g_player.mode == PLAYER_MODE_ON_FOOT || g_player.mode == PLAYER_MODE_PLATFORM) ? g_player.inside_ship : g_game.player_ship_slot;
    if (slot == UINT32_MAX || !entity_alive(slot)) return;
    ShipDataExt* ext = ship_ext(slot);
    if (!ext) return;
    g_screen_active = -1; float best = 3.f;
    for (uint32_t i = 0; i < (uint32_t)ext->node_count; i++) {
        const ShipNode* n = &ext->nodes[i];
        int kind = (n->props_mask & NODE_PROP_COMPUTER_ROOM) ? 2 : (n->props_mask & NODE_PROP_COCKPIT) ? 0 : (n->props_mask & NODE_PROP_SCREEN) ? 1 : -1;
        if (kind < 0) continue;
        V3 c = local_to_world_pos(slot, v3add(n->pos_local, v3(0.f, 0.3f, 0.f)));
        V3 to = v3sub(c, g_game.cam.pos);
        float d = v3len(to);
        if (d > 14.f || d < 0.2f) continue;
        V3 r = v3norm(v3cross(v3(0.f, 1.f, 0.f), to));
        V3 u = v3(0.f, 1.f, 0.f);
        V3 q[4] = { v3add(v3add(c, v3mul(r, -0.7f)), v3mul(u,  0.4f)), v3add(v3add(c, v3mul(r,  0.7f)), v3mul(u,  0.4f)),
                    v3add(v3add(c, v3mul(r,  0.7f)), v3mul(u, -0.4f)), v3add(v3add(c, v3mul(r, -0.7f)), v3mul(u, -0.4f)) };
        float sx[4], sy[4]; int ok = 1;
        for (int k = 0; k < 4; k++) if (!project_screen(q[k], g_game.cam.vp, &sx[k], &sy[k], g_win_w, g_win_h)) ok = 0;
        if (!ok) continue;
        float x0 = fminf(fminf(sx[0], sx[1]), fminf(sx[2], sx[3])), x1 = fmaxf(fmaxf(sx[0], sx[1]), fmaxf(sx[2], sx[3]));
        float y0 = fminf(fminf(sy[0], sy[1]), fminf(sy[2], sy[3])), y1 = fmaxf(fmaxf(sy[0], sy[1]), fmaxf(sy[2], sy[3]));
        float bw = x1 - x0; if (bw < 40.f) continue;
        float hp = n->structural_hp > 0.f ? clampf(n->current_hp / n->structural_hp, 0.f, 1.f) : 1.f;
        float fade = clampf(1.f - (d - 8.f) / 6.f, 0.25f, 1.f) * (0.35f + 0.65f * hp);
        hud_quad(x0, y0, bw, y1 - y0, C4(0.f, 0.08f, 0.12f, 0.45f * fade), 3);
        for (int k = 0; k < 4; k++) hud_line(sx[k], sy[k], sx[(k + 1) & 3], sy[(k + 1) & 3], 1.5f, C4(0.3f, 0.9f, 1.f, 0.8f * fade), 3);
        if (hp < 0.5f && (((int)(time_get() * 14.0)) & 1)) hud_quad(x0, y0 + (y1 - y0) * 0.5f, bw, 2.f, C4(1.f, 0.4f, 0.3f, 0.5f), 3);   /* ruido por daño */
        float sc = bw / 170.f;
        if (kind == 2) screen_page_computer(x0, y0, sc);
        else if (kind == 0) screen_page_ship(x0, y0, sc, slot);
        else screen_page_nav(x0, y0, sc);
        if (d < best && kind == 2) { best = d; g_screen_active = (int)i; }
    }
}
/* teclas de pantalla de cómputo (F7/F8/F9) cuando hay una cerca */
static void screens_tick(float dt) {
    (void)dt;
    static uint8_t prev[3] = {0, 0, 0};
    int cur[3] = { g_input.keys[VK_F7] != 0, g_input.keys[VK_F8] != 0, g_input.keys[VK_F9] != 0 };
    uint32_t slot = g_player.inside_ship;
    if (g_screen_active >= 0 && slot != UINT32_MAX) {
        if (cur[0] && !prev[0]) player_extract_from_computer(slot, g_screen_active);
        if (cur[1] && !prev[1]) computer_assign_drones(slot, g_screen_active);
        if (cur[2] && !prev[2]) {
            if (g_player.inventory.count > 0) {
                if (computer_store_bundle(slot, g_screen_active, g_player.inventory.items[0].bp.seed)) notice_push("BUNDLE STORED");
                else notice_push("COMPUTER FULL");
            } else notice_push("NO ITEM TO STORE");
        }
    }
    for (int k = 0; k < 3; k++) prev[k] = (uint8_t)cur[k];
}
/* indicador de gravedad / apoyo (HUD de visor) */
static void hud_draw_gravity_indicator(void) {
    if (g_player.mode != PLAYER_MODE_ON_FOOT) return;
    WalkerState* w = &g_player.walker; if (!w->support.init) return;
    static const char* RG[4] = { "NORMAL", "LOW-G", "ZERO-G", "HIGH-G" };
    static const char* MD[5] = { "GROUNDED", "SLIDING", "AIRBORNE", "FLOATING", "MAGNETIC" };
    float x = 16.f, y = (float)g_win_h - 90.f;
    hud_quad(x - 6.f, y - 6.f, 170.f, 56.f, C4(0.f, 0.05f, 0.1f, 0.4f), 3);
    char b[64]; snprintf(b, sizeof(b), "G %.1f  %s", g_player_grav.mag, RG[w->support.regime & 3]);
    hud_text_push(x, y, 11.f, w->support.regime == GR_ZERO ? C4(1.f, 0.8f, 0.3f, 1.f) : C4(0.6f, 0.95f, 1.f, 1.f), b);
    hud_text_push(x, y + 14.f, 9.f, C4(0.8f, 0.8f, 0.8f, 0.9f), MD[w->support.mode % 5]);
    hud_bar(x, y + 30.f, 120.f, 5.f, w->support.boots_energy, C4(0.5f, 0.8f, 1.f, 0.9f), C4(0.1f, 0.1f, 0.2f, 0.6f));
    float ax = x + 140.f, ay = y + 20.f;       /* flecha del "arriba" local respecto de la vista */
    V3 ur = sup_unmap(&w->support, v3(0.f, 1.f, 0.f));
    hud_line(ax, ay, ax + ur.x * 14.f, ay - ur.z * 14.f, 2.f, C4(0.5f, 1.f, 0.7f, 0.9f), 3);
}
static void hud_draw_gui_refs(void) {
    hullref_draw();
    screens_draw();
    hud_draw_gravity_indicator();
}
static void sim_stage_gravity(float dt) {
    gravgen_tick_all(dt);
    screens_tick(dt);
}

/* tripulación que ve algo imposible (anomalías cercanas) reacciona una vez por ciclo */
static void npc_saw_impossible_tick(float dt) {
    static float cd = 0.f;
    cd -= dt; if (cd > 0.f) return; cd = 1.5f;
    for (uint32_t c = 0; c < g_things_cap; c++) {
        if (!g_alive[c] || g_things[c].type != ET_CREW) continue;
        uint32_t* near_buf; uint32_t n = sh_query_dyn(g_things[c].pos, 80.f, g_things_cap, &near_buf);
        for (uint32_t k = 0; k < n; k++)
            if (g_alive[near_buf[k]] && g_things[near_buf[k]].type == ET_ANOMALY) { npc_on_saw_impossible(c); break; }
        sh_scratch_release();
    }
}
static void sim_stage_b_content(float dt) {
    npc_saw_impossible_tick(dt);
    turret_tick(dt);
    regime_tick(dt);
    ideology_tick(dt);
    viscosity_tick(dt);
    density_tick(dt);
    wreck_tick(dt);
    capsule_tick(dt);
    chain_tick(dt);
    message_tick(dt);
    pointer_tick(dt);
    station_traffic_tick(dt);
    camo_tick(dt);
    update_player_bombs(dt);
    rect_travel_tick(dt);
    launcher_patrol_tick(dt);
    hints_tick(dt);
    pirate_tick(dt);
    zone_check_boundary();
}

